window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["ISA"]={"book":"ISA","editions":{"hbo-source":[[1,1,"חֲזוֹן֙ יְשַֽׁעְיָ֣הוּ בֶן־אָמ֔וֹץ אֲשֶׁ֣ר חָזָ֔ה עַל־יְהוּדָ֖ה וִ⁠ירוּשָׁלִָ֑ם בִּ⁠ימֵ֨י עֻזִּיָּ֧הוּ יוֹתָ֛ם אָחָ֥ז יְחִזְקִיָּ֖הוּ מַלְכֵ֥י יְהוּדָֽה׃","ẖàzwòn֙ yĕşǎֽʻĕyá֣hẇ ben-ʼám֔wòẕ ʼàşě֣r ẖázá֔h ʻal-yĕhẇdá֖h wi⁠yrẇşá̌liá֑m bi̇⁠ymé֨y ʻuzi̇yá֧̇hẇ ywòţá֛m ʼáẖá֥z yĕẖizĕqiyá֖̇hẇ malĕké֥y yĕhẇdáֽh׃"],[1,2,"שִׁמְע֤וּ שָׁמַ֨יִם֙ וְ⁠הַאֲזִ֣ינִי אֶ֔רֶץ כִּ֥י יְהוָ֖ה דִּבֵּ֑ר בָּנִים֙ גִּדַּ֣לְתִּי וְ⁠רוֹמַ֔מְתִּי וְ⁠הֵ֖ם פָּ֥שְׁעוּ בִֽ⁠י׃","şǐmĕʻ֤ẇ şá̌ma֨yim֙ wĕ⁠haʼàzi֣yniy ʼe֔reẕ ki֥̇y yĕhwá֖h di̇bé֑̇r bá̇niym֙ gi̇dȧ֣lĕţi̇y wĕ⁠rwòma֔mĕţi̇y wĕ⁠hé֖m pá֥̇şĕ̌ʻẇ biֽ⁠y׃"],[1,3,"יָדַ֥ע שׁוֹר֙ קֹנֵ֔⁠הוּ וַ⁠חֲמ֖וֹר אֵב֣וּס בְּעָלָ֑י⁠ו יִשְׂרָאֵל֙ לֹ֣א יָדַ֔ע עַמִּ֖⁠י לֹ֥א הִתְבּוֹנָֽן׃","yáda֥ʻ ş̌wòr֙ qòné֔⁠hẇ wa⁠ẖàm֖wòr ʼéb֣ẇs bĕ̇ʻálá֑y⁠w yişĕ̂ráʼél֙ lò֣ʼ yáda֔ʻ ʻami֖̇⁠y lò֥ʼ hiţĕḃwònáֽn׃"],[1,4,"ה֣וֹי ׀ גּ֣וֹי חֹטֵ֗א עַ֚ם כֶּ֣בֶד עָוֺ֔ן זֶ֣רַע מְרֵעִ֔ים בָּנִ֖ים מַשְׁחִיתִ֑ים עָזְב֣וּ אֶת־יְהוָ֗ה נִֽאֲצ֛וּ אֶת־קְד֥וֹשׁ יִשְׂרָאֵ֖ל נָזֹ֥רוּ אָחֽוֹר׃","h֣wòy ׀ ġ֣wòy ẖòté֗ʼ ʻa֚m kė֣bed ʻáwֺ֔n ze֣raʻ mĕréʻi֔ym bá̇ni֖ym maşĕ̌ẖiyţi֑ym ʻázĕb֣ẇ ʼeţ-yĕhwá֗h niֽʼàẕ֛ẇ ʼeţ-qĕd֥wòş̌ yişĕ̂ráʼé֖l názò֥rẇ ʼáẖֽwòr׃"],[1,5,"עַ֣ל מֶ֥ה תֻכּ֛וּ ע֖וֹד תּוֹסִ֣יפוּ סָרָ֑ה כָּל־רֹ֣אשׁ לָ⁠חֳלִ֔י וְ⁠כָל־לֵבָ֖ב דַּוָּֽי׃","ʻa֣l me֥h ţuk֛̇ẇ ʻ֖wòd ţ̇wòsi֣ypẇ sárá֑h ká̇l-rò֣ʼş̌ lá⁠ẖoli֔y wĕ⁠kál-lébá֖b dȧwáֽ̇y׃"],[1,6,"מִ⁠כַּף־רֶ֤גֶל וְ⁠עַד־רֹאשׁ֙ אֵֽין־בּ֣⁠וֹ מְתֹ֔ם פֶּ֥צַע וְ⁠חַבּוּרָ֖ה וּ⁠מַכָּ֣ה טְרִיָּ֑ה לֹא־זֹ֨רוּ֙ וְ⁠לֹ֣א חֻבָּ֔שׁוּ וְ⁠לֹ֥א רֻכְּכָ֖ה בַּ⁠שָּֽׁמֶן׃","mi⁠kȧp-re֤gel wĕ⁠ʻad-ròʼş̌֙ ʼéֽyn-ḃ֣⁠wò mĕţò֔m pė֥ẕaʻ wĕ⁠ẖaḃẇrá֖h ẇ⁠maká֣̇h tĕriyá֑̇h lòʼ-zò֨rẇ֙ wĕ⁠lò֣ʼ ẖubá̇֔ş̌ẇ wĕ⁠lò֥ʼ rukĕ̇ká֖h bȧ⁠şáֽ̇̌men׃"],[1,7,"אַרְצְ⁠כֶ֣ם שְׁמָמָ֔ה עָרֵי⁠כֶ֖ם שְׂרֻפ֣וֹת אֵ֑שׁ אַדְמַתְ⁠כֶ֗ם לְ⁠נֶגְדְּ⁠כֶם֙ זָרִים֙ אֹכְלִ֣ים אֹתָ֔⁠הּ וּ⁠שְׁמָמָ֖ה כְּ⁠מַהְפֵּכַ֥ת זָרִֽים׃","ʼarĕẕĕ⁠ke֣m şĕ̌mámá֔h ʻáréy⁠ke֖m şĕ̂rup֣wòţ ʼé֑ş̌ ʼadĕmaţĕ⁠ke֗m lĕ⁠negĕdĕ̇⁠kem֙ záriym֙ ʼòkĕli֣ym ʼòţá֔⁠ḣ ẇ⁠şĕ̌mámá֖h kĕ̇⁠mahĕpé̇ka֥ţ záriֽym׃"],[1,8,"וְ⁠נוֹתְרָ֥ה בַת־צִיּ֖וֹן כְּ⁠סֻכָּ֣ה בְ⁠כָ֑רֶם כִּ⁠מְלוּנָ֥ה בְ⁠מִקְשָׁ֖ה כְּ⁠עִ֥יר נְצוּרָֽה׃","wĕ⁠nwòţĕrá֥h baţ-ẕiẏ֖wòn kĕ̇⁠suká֣̇h bĕ⁠ká֑rem ki̇⁠mĕlẇná֥h bĕ⁠miqĕşá֖̌h kĕ̇⁠ʻi֥yr nĕẕẇráֽh׃"],[1,9,"לוּלֵי֙ יְהוָ֣ה צְבָא֔וֹת הוֹתִ֥יר לָ֛⁠נוּ שָׂרִ֖יד כִּ⁠מְעָ֑ט כִּ⁠סְדֹ֣ם הָיִ֔ינוּ לַ⁠עֲמֹרָ֖ה דָּמִֽינוּ׃ס","lẇléy֙ yĕhwá֣h ẕĕbáʼ֔wòţ hwòţi֥yr lá֛⁠nẇ şá̂ri֖yd ki̇⁠mĕʻá֑t ki̇⁠sĕdò֣m háyi֔ynẇ la⁠ʻàmòrá֖h dá̇miֽynẇ׃s"],[1,10,"שִׁמְע֥וּ דְבַר־יְהוָ֖ה קְצִינֵ֣י סְדֹ֑ם הַאֲזִ֛ינוּ תּוֹרַ֥ת אֱלֹהֵ֖י⁠נוּ עַ֥ם עֲמֹרָֽה׃","şǐmĕʻ֥ẇ dĕbar-yĕhwá֖h qĕẕiyné֣y sĕdò֑m haʼàzi֛ynẇ ţ̇wòra֥ţ ʼèlòhé֖y⁠nẇ ʻa֥m ʻàmòráֽh׃"],[1,11,"לָ⁠מָּה־לִּ֤⁠י רֹב־זִבְחֵי⁠כֶם֙ יֹאמַ֣ר יְהוָ֔ה שָׂבַ֛עְתִּי עֹל֥וֹת אֵילִ֖ים וְ⁠חֵ֣לֶב מְרִיאִ֑ים וְ⁠דַ֨ם פָּרִ֧ים וּ⁠כְבָשִׂ֛ים וְ⁠עַתּוּדִ֖ים לֹ֥א חָפָֽצְתִּי׃","lá⁠má̇h-li֤̇⁠y ròb-zibĕẖéy⁠kem֙ yòʼma֣r yĕhwá֔h şá̂ba֛ʻĕţi̇y ʻòl֥wòţ ʼéyli֖ym wĕ⁠ẖé֣leb mĕriyʼi֑ym wĕ⁠da֨m pá̇ri֧ym ẇ⁠kĕbáşî֛ym wĕ⁠ʻaţ̇ẇdi֖ym lò֥ʼ ẖápáֽẕĕţi̇y׃"],[1,12,"כִּ֣י תָבֹ֔אוּ לֵ⁠רָא֖וֹת פָּנָ֑⁠י מִי־בִקֵּ֥שׁ זֹ֛את מִ⁠יֶּדְ⁠כֶ֖ם רְמֹ֥ס חֲצֵרָֽ⁠י׃","ki֣̇y ţábò֔ʼẇ lé⁠ráʼ֖wòţ pá̇ná֑⁠y miy-biqé֥̇ş̌ zò֛ʼţ mi⁠yėdĕ⁠ke֖m rĕmò֥s ẖàẕéráֽ⁠y׃"],[1,13,"לֹ֣א תוֹסִ֗יפוּ הָבִיא֙ מִנְחַת־שָׁ֔וְא קְטֹ֧רֶת תּוֹעֵבָ֛ה הִ֖יא לִ֑⁠י חֹ֤דֶשׁ וְ⁠שַׁבָּת֙ קְרֹ֣א מִקְרָ֔א לֹא־אוּכַ֥ל אָ֖וֶן וַ⁠עֲצָרָֽה׃","lò֣ʼ ţwòsi֗ypẇ hábiyʼ֙ minĕẖaţ-şá̌֔wĕʼ qĕtò֧reţ ţ̇wòʻébá֛h hi֖yʼ li֑⁠y ẖò֤deş̌ wĕ⁠şǎbá̇ţ֙ qĕrò֣ʼ miqĕrá֔ʼ lòʼ-ʼẇka֥l ʼá֖wen wa⁠ʻàẕáráֽh׃"],[1,14,"חָדְשֵׁי⁠כֶ֤ם וּ⁠מוֹעֲדֵי⁠כֶם֙ שָׂנְאָ֣ה נַפְשִׁ֔⁠י הָי֥וּ עָלַ֖⁠י לָ⁠טֹ֑רַח נִלְאֵ֖יתִי נְשֹֽׂא׃","ẖádĕşé̌y⁠ke֤m ẇ⁠mwòʻàdéy⁠kem֙ şá̂nĕʼá֣h napĕşǐ֔⁠y háy֥ẇ ʻála֖⁠y lá⁠tò֑raẖ nilĕʼé֖yţiy nĕşòֽ̂ʼ׃"],[1,15,"וּ⁠בְ⁠פָרִשְׂ⁠כֶ֣ם כַּפֵּי⁠כֶ֗ם אַעְלִ֤ים עֵינַ⁠י֙ מִ⁠כֶּ֔ם גַּ֛ם כִּֽי־תַרְבּ֥וּ תְפִלָּ֖ה אֵינֶ֣⁠נִּי שֹׁמֵ֑עַ יְדֵי⁠כֶ֖ם דָּמִ֥ים מָלֵֽאוּ׃","ẇ⁠bĕ⁠párişĕ̂⁠ke֣m kȧpé̇y⁠ke֗m ʼaʻĕli֤ym ʻéyna⁠y֙ mi⁠kė֔m gȧ֛m kiֽ̇y-ţarĕḃ֥ẇ ţĕpilá֖̇h ʼéyne֣⁠ni̇y şò̌mé֑ʻa yĕdéy⁠ke֖m dá̇mi֥ym máléֽʼẇ׃"],[1,16,"רַחֲצוּ֙ הִזַּכּ֔וּ הָסִ֛ירוּ רֹ֥עַ מַעַלְלֵי⁠כֶ֖ם מִ⁠נֶּ֣גֶד עֵינָ֑⁠י חִדְל֖וּ הָרֵֽעַ׃","raẖàẕẇ֙ hizȧk̇֔ẇ hási֛yrẇ rò֥ʻa maʻalĕléy⁠ke֖m mi⁠nė֣ged ʻéyná֑⁠y ẖidĕl֖ẇ háréֽʻa׃"],[1,17,"לִמְד֥וּ הֵיטֵ֛ב דִּרְשׁ֥וּ מִשְׁפָּ֖ט אַשְּׁר֣וּ חָמ֑וֹץ שִׁפְט֣וּ יָת֔וֹם רִ֖יבוּ אַלְמָנָֽה׃ס","limĕd֥ẇ héyté֛b di̇rĕş֥̌ẇ mişĕ̌pá֖̇t ʼaşĕ̇̌r֣ẇ ẖám֑wòẕ şǐpĕt֣ẇ yáţ֔wòm ri֖ybẇ ʼalĕmánáֽh׃s"],[1,18,"לְכוּ־נָ֛א וְ⁠נִוָּֽכְחָ֖ה יֹאמַ֣ר יְהוָ֑ה אִם־יִֽהְי֨וּ חֲטָאֵי⁠כֶ֤ם כַּ⁠שָּׁנִים֙ כַּ⁠שֶּׁ֣לֶג יַלְבִּ֔ינוּ אִם־יַאְדִּ֥ימוּ כַ⁠תּוֹלָ֖ע כַּ⁠צֶּ֥מֶר יִהְיֽוּ׃","lĕkẇ-ná֛ʼ wĕ⁠niwáֽ̇kĕẖá֖h yòʼma֣r yĕhwá֑h ʼim-yiֽhĕy֨ẇ ẖàtáʼéy⁠ke֤m kȧ⁠şá̇̌niym֙ kȧ⁠şė֣̌leg yalĕbi̇֔ynẇ ʼim-yaʼĕdi֥̇ymẇ ka⁠ţ̇wòlá֖ʻ kȧ⁠ẕė֥mer yihĕyֽẇ׃"],[1,19,"אִם־תֹּאב֖וּ וּ⁠שְׁמַעְתֶּ֑ם ט֥וּב הָ⁠אָ֖רֶץ תֹּאכֵֽלוּ׃","ʼim-ţò̇ʼb֖ẇ ẇ⁠şĕ̌maʻĕţė֑m t֥ẇb há⁠ʼá֖reẕ ţò̇ʼkéֽlẇ׃"],[1,20,"וְ⁠אִם־תְּמָאֲנ֖וּ וּ⁠מְרִיתֶ֑ם חֶ֣רֶב תְּאֻכְּל֔וּ כִּ֛י פִּ֥י יְהוָ֖ה דִּבֵּֽר׃ס","wĕ⁠ʼim-ţĕ̇máʼàn֖ẇ ẇ⁠mĕriyţe֑m ẖe֣reb ţĕ̇ʼukĕ̇l֔ẇ ki֛̇y pi֥̇y yĕhwá֖h di̇béֽ̇r׃s"],[1,21,"אֵיכָה֙ הָיְתָ֣ה לְ⁠זוֹנָ֔ה קִרְיָ֖ה נֶאֱמָנָ֑ה מְלֵאֲתִ֣י מִשְׁפָּ֗ט צֶ֛דֶק יָלִ֥ין בָּ֖⁠הּ וְ⁠עַתָּ֥ה מְרַצְּחִֽים׃","ʼéykáh֙ háyĕţá֣h lĕ⁠zwòná֔h qirĕyá֖h neʼèmáná֑h mĕléʼàţi֣y mişĕ̌pá̇֗t ẕe֛deq yáli֥yn bá֖̇⁠ḣ wĕ⁠ʻaţá֥̇h mĕraẕĕ̇ẖiֽym׃"],[1,22,"כַּסְפֵּ֖⁠ךְ הָיָ֣ה לְ⁠סִיגִ֑ים סָבְאֵ֖⁠ךְ מָה֥וּל בַּ⁠מָּֽיִם׃","kȧsĕpé֖̇⁠kĕ háyá֣h lĕ⁠siygi֑ym sábĕʼé֖⁠kĕ máh֥ẇl bȧ⁠máֽ̇yim׃"],[1,23,"שָׂרַ֣יִ⁠ךְ סוֹרְרִ֗ים וְ⁠חַבְרֵי֙ גַּנָּבִ֔ים כֻּלּ⁠וֹ֙ אֹהֵ֣ב שֹׁ֔חַד וְ⁠רֹדֵ֖ף שַׁלְמֹנִ֑ים יָתוֹם֙ לֹ֣א יִשְׁפֹּ֔טוּ וְ⁠רִ֥יב אַלְמָנָ֖ה לֹֽא־יָב֥וֹא אֲלֵי⁠הֶֽם׃פ","şá̂ra֣yi⁠kĕ swòrĕri֗ym wĕ⁠ẖabĕréy֙ gȧná̇bi֔ym ku̇l̇⁠wò֙ ʼòhé֣b şò̌֔ẖad wĕ⁠ròdé֖p şǎlĕmòni֑ym yáţwòm֙ lò֣ʼ yişĕ̌pò̇֔tẇ wĕ⁠ri֥yb ʼalĕmáná֖h lòֽʼ-yáb֥wòʼ ʼàléy⁠heֽm׃p"],[1,24,"לָ⁠כֵ֗ן נְאֻ֤ם הָֽ⁠אָדוֹן֙ יְהוָ֣ה צְבָא֔וֹת אֲבִ֖יר יִשְׂרָאֵ֑ל ה֚וֹי אֶנָּחֵ֣ם מִ⁠צָּרַ֔⁠י וְ⁠אִנָּקְמָ֖ה מֵ⁠אוֹיְבָֽ⁠י׃","lá⁠ké֗n nĕʼu֤m háֽ⁠ʼádwòn֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʼàbi֖yr yişĕ̂ráʼé֑l h֚wòy ʼená̇ẖé֣m mi⁠ẕá̇ra֔⁠y wĕ⁠ʼiná̇qĕmá֖h mé⁠ʼwòyĕbáֽ⁠y׃"],[1,25,"וְ⁠אָשִׁ֤יבָה יָדִ⁠י֙ עָלַ֔יִ⁠ךְ וְ⁠אֶצְרֹ֥ף כַּ⁠בֹּ֖ר סִיגָ֑יִ⁠ךְ וְ⁠אָסִ֖ירָה כָּל־בְּדִילָֽיִ⁠ךְ׃","wĕ⁠ʼáşǐ֤ybáh yádi⁠y֙ ʻála֔yi⁠kĕ wĕ⁠ʼeẕĕrò֥p kȧ⁠bò֖̇r siygá֑yi⁠kĕ wĕ⁠ʼási֖yráh ká̇l-bĕ̇diyláֽyi⁠kĕ׃"],[1,26,"וְ⁠אָשִׁ֤יבָה שֹׁפְטַ֨יִ⁠ךְ֙ כְּ⁠בָ⁠רִ֣אשֹׁנָ֔ה וְ⁠יֹעֲצַ֖יִ⁠ךְ כְּ⁠בַ⁠תְּחִלָּ֑ה אַחֲרֵי־כֵ֗ן יִקָּ֤רֵא לָ⁠ךְ֙ עִ֣יר הַ⁠צֶּ֔דֶק קִרְיָ֖ה נֶאֱמָנָֽה׃","wĕ⁠ʼáşǐ֤ybáh şò̌pĕta֨yi⁠kĕ֙ kĕ̇⁠bá⁠ri֣ʼşò̌ná֔h wĕ⁠yòʻàẕa֖yi⁠kĕ kĕ̇⁠ba⁠ţĕ̇ẖilá֑̇h ʼaẖàréy-ké֗n yiqá֤̇réʼ lá⁠kĕ֙ ʻi֣yr ha⁠ẕė֔deq qirĕyá֖h neʼèmánáֽh׃"],[1,27,"צִיּ֖וֹן בְּ⁠מִשְׁפָּ֣ט תִּפָּדֶ֑ה וְ⁠שָׁבֶ֖י⁠הָ בִּ⁠צְדָקָֽה׃","ẕiẏ֖wòn bĕ̇⁠mişĕ̌pá֣̇t ţi̇pá̇de֑h wĕ⁠şá̌be֖y⁠há bi̇⁠ẕĕdáqáֽh׃"],[1,28,"וְ⁠שֶׁ֧בֶר פֹּשְׁעִ֛ים וְ⁠חַטָּאִ֖ים יַחְדָּ֑ו וְ⁠עֹזְבֵ֥י יְהוָ֖ה יִכְלֽוּ׃","wĕ⁠şě֧ber pò̇şĕ̌ʻi֛ym wĕ⁠ẖatá̇ʼi֖ym yaẖĕdá֑̇w wĕ⁠ʻòzĕbé֥y yĕhwá֖h yikĕlֽẇ׃"],[1,29,"כִּ֣י יֵבֹ֔שׁוּ מֵ⁠אֵילִ֖ים אֲשֶׁ֣ר חֲמַדְתֶּ֑ם וְ⁠תַ֨חְפְּר֔וּ מֵ⁠הַ⁠גַּנּ֖וֹת אֲשֶׁ֥ר בְּחַרְתֶּֽם׃","ki֣̇y yébò֔ş̌ẇ mé⁠ʼéyli֖ym ʼàşě֣r ẖàmadĕţė֑m wĕ⁠ţa֨ẖĕpĕ̇r֔ẇ mé⁠ha⁠gȧṅ֖wòţ ʼàşě֥r bĕ̇ẖarĕţėֽm׃"],[1,30,"כִּ֣י תִֽהְי֔וּ כְּ⁠אֵלָ֖ה נֹבֶ֣לֶת עָלֶ֑⁠הָ וּֽ⁠כְ⁠גַנָּ֔ה אֲשֶׁר־מַ֖יִם אֵ֥ין לָֽ⁠הּ׃","ki֣̇y ţiֽhĕy֔ẇ kĕ̇⁠ʼélá֖h nòbe֣leţ ʻále֑⁠há ẇֽ⁠kĕ⁠ganá̇֔h ʼàşěr-ma֖yim ʼé֥yn láֽ⁠ḣ׃"],[1,31,"וְ⁠הָיָ֤ה הֶ⁠חָסֹן֙ לִ⁠נְעֹ֔רֶת וּ⁠פֹעֲל֖⁠וֹ לְ⁠נִיצ֑וֹץ וּ⁠בָעֲר֧וּ שְׁנֵי⁠הֶ֛ם יַחְדָּ֖ו וְ⁠אֵ֥ין מְכַבֶּֽה׃ס","wĕ⁠háyá֤h he⁠ẖásòn֙ li⁠nĕʻò֔reţ ẇ⁠pòʻàl֖⁠wò lĕ⁠niyẕ֑wòẕ ẇ⁠báʻàr֧ẇ şĕ̌néy⁠he֛m yaẖĕdá֖̇w wĕ⁠ʼé֥yn mĕkabėֽh׃s"],[2,1,"הַ⁠דָּבָר֙ אֲשֶׁ֣ר חָזָ֔ה יְשַֽׁעְיָ֖הוּ בֶּן־אָמ֑וֹץ עַל־יְהוּדָ֖ה וִ⁠ירוּשָׁלִָֽם׃","ha⁠dá̇bár֙ ʼàşě֣r ẖázá֔h yĕşǎֽʻĕyá֖hẇ bėn-ʼám֑wòẕ ʻal-yĕhẇdá֖h wi⁠yrẇşá̌liáֽm׃"],[2,2,"וְ⁠הָיָ֣ה ׀ בְּ⁠אַחֲרִ֣ית הַ⁠יָּמִ֗ים נָכ֨וֹן יִֽהְיֶ֜ה הַ֤ר בֵּית־יְהוָה֙ בְּ⁠רֹ֣אשׁ הֶ⁠הָרִ֔ים וְ⁠נִשָּׂ֖א מִ⁠גְּבָע֑וֹת וְ⁠נָהֲר֥וּ אֵלָ֖י⁠ו כָּל־הַ⁠גּוֹיִֽם׃","wĕ⁠háyá֣h ׀ bĕ̇⁠ʼaẖàri֣yţ ha⁠yá̇mi֗ym nák֨wòn yiֽhĕye֜h ha֤r bé̇yţ-yĕhwáh֙ bĕ̇⁠rò֣ʼş̌ he⁠hári֔ym wĕ⁠nişá֖̇̂ʼ mi⁠gĕ̇báʻ֑wòţ wĕ⁠náhàr֥ẇ ʼélá֖y⁠w ká̇l-ha⁠ġwòyiֽm׃"],[2,3,"וְֽ⁠הָלְכ֞וּ עַמִּ֣ים רַבִּ֗ים וְ⁠אָמְרוּ֙ לְכ֣וּ ׀ וְ⁠נַעֲלֶ֣ה אֶל־הַר־יְהוָ֗ה אֶל־בֵּית֙ אֱלֹהֵ֣י יַעֲקֹ֔ב וְ⁠יֹרֵ֨⁠נוּ֙ מִ⁠דְּרָכָ֔י⁠ו וְ⁠נֵלְכָ֖ה בְּ⁠אֹרְחֹתָ֑י⁠ו כִּ֤י מִ⁠צִּיּוֹן֙ תֵּצֵ֣א תוֹרָ֔ה וּ⁠דְבַר־יְהוָ֖ה מִ⁠ירוּשָׁלִָֽם׃","wĕֽ⁠hálĕk֞ẇ ʻami֣̇ym rabi̇֗ym wĕ⁠ʼámĕrẇ֙ lĕk֣ẇ ׀ wĕ⁠naʻàle֣h ʼel-har-yĕhwá֗h ʼel-bé̇yţ֙ ʼèlòhé֣y yaʻàqò֔b wĕ⁠yòré֨⁠nẇ֙ mi⁠dĕ̇ráká֔y⁠w wĕ⁠nélĕká֖h bĕ̇⁠ʼòrĕẖòţá֑y⁠w ki֤̇y mi⁠ẕi̇ẏwòn֙ ţé̇ẕé֣ʼ ţwòrá֔h ẇ⁠dĕbar-yĕhwá֖h mi⁠yrẇşá̌liáֽm׃"],[2,4,"וְ⁠שָׁפַט֙ בֵּ֣ין הַ⁠גּוֹיִ֔ם וְ⁠הוֹכִ֖יחַ לְ⁠עַמִּ֣ים רַבִּ֑ים וְ⁠כִתְּת֨וּ חַרְבוֹתָ֜⁠ם לְ⁠אִתִּ֗ים וַ⁠חֲנִיתֽוֹתֵי⁠הֶם֙ לְ⁠מַזְמֵר֔וֹת לֹא־יִשָּׂ֨א ג֤וֹי אֶל־גּוֹי֙ חֶ֔רֶב וְ⁠לֹא־יִלְמְד֥וּ ע֖וֹד מִלְחָמָֽה׃פ","wĕ⁠şá̌pat֙ bé֣̇yn ha⁠ġwòyi֔m wĕ⁠hwòki֖yẖa lĕ⁠ʻami֣̇ym rabi֑̇ym wĕ⁠kiţĕ̇ţ֨ẇ ẖarĕbwòţá֜⁠m lĕ⁠ʼiţi̇֗ym wa⁠ẖàniyţֽwòţéy⁠hem֙ lĕ⁠mazĕmér֔wòţ lòʼ-yişá̇̂֨ʼ g֤wòy ʼel-ġwòy֙ ẖe֔reb wĕ⁠lòʼ-yilĕmĕd֥ẇ ʻ֖wòd milĕẖámáֽh׃p"],[2,5,"בֵּ֖ית יַעֲקֹ֑ב לְכ֥וּ וְ⁠נֵלְכָ֖ה בְּ⁠א֥וֹר יְהוָֽה׃","bé֖̇yţ yaʻàqò֑b lĕk֥ẇ wĕ⁠nélĕká֖h bĕ̇⁠ʼ֥wòr yĕhwáֽh׃"],[2,6,"כִּ֣י נָטַ֗שְׁתָּה עַמְּ⁠ךָ֙ בֵּ֣ית יַעֲקֹ֔ב כִּ֤י מָלְאוּ֙ מִ⁠קֶּ֔דֶם וְ⁠עֹֽנְנִ֖ים כַּ⁠פְּלִשְׁתִּ֑ים וּ⁠בְ⁠יַלְדֵ֥י נָכְרִ֖ים יַשְׂפִּֽיקוּ׃","ki֣̇y náta֗şĕ̌ţá̇h ʻamĕ̇⁠ká֙ bé֣̇yţ yaʻàqò֔b ki֤̇y málĕʼẇ֙ mi⁠qė֔dem wĕ⁠ʻòֽnĕni֖ym kȧ⁠pĕ̇lişĕ̌ţi֑̇ym ẇ⁠bĕ⁠yalĕdé֥y nákĕri֖ym yaşĕ̂piֽ̇yqẇ׃"],[2,7,"וַ⁠תִּמָּלֵ֤א אַרְצ⁠וֹ֙ כֶּ֣סֶף וְ⁠זָהָ֔ב וְ⁠אֵ֥ין קֵ֖צֶה לְ⁠אֹצְרֹתָ֑י⁠ו וַ⁠תִּמָּלֵ֤א אַרְצ⁠וֹ֙ סוּסִ֔ים וְ⁠אֵ֥ין קֵ֖צֶה לְ⁠מַרְכְּבֹתָֽי⁠ו׃","wa⁠ţi̇má̇lé֤ʼ ʼarĕẕ⁠wò֙ kė֣sep wĕ⁠záhá֔b wĕ⁠ʼé֥yn qé֖ẕeh lĕ⁠ʼòẕĕròţá֑y⁠w wa⁠ţi̇má̇lé֤ʼ ʼarĕẕ⁠wò֙ sẇsi֔ym wĕ⁠ʼé֥yn qé֖ẕeh lĕ⁠marĕkĕ̇bòţáֽy⁠w׃"],[2,8,"וַ⁠תִּמָּלֵ֥א אַרְצ֖⁠וֹ אֱלִילִ֑ים לְ⁠מַעֲשֵׂ֤ה יָדָי⁠ו֙ יִֽשְׁתַּחֲו֔וּ לַ⁠אֲשֶׁ֥ר עָשׂ֖וּ אֶצְבְּעֹתָֽי⁠ו׃","wa⁠ţi̇má̇lé֥ʼ ʼarĕẕ֖⁠wò ʼèliyli֑ym lĕ⁠maʻàşé֤̂h yádáy⁠w֙ yiֽşĕ̌ţȧẖàw֔ẇ la⁠ʼàşě֥r ʻáş֖̂ẇ ʼeẕĕbĕ̇ʻòţáֽy⁠w׃"],[2,9,"וַ⁠יִּשַּׁ֥ח אָדָ֖ם וַ⁠יִּשְׁפַּל־אִ֑ישׁ וְ⁠אַל־תִּשָּׂ֖א לָ⁠הֶֽם׃","wa⁠yi̇şȧ֥̌ẖ ʼádá֖m wa⁠yi̇şĕ̌pȧl-ʼi֑yş̌ wĕ⁠ʼal-ţi̇şá֖̇̂ʼ lá⁠heֽm׃"],[2,10,"בּ֣וֹא בַ⁠צּ֔וּר וְ⁠הִטָּמֵ֖ן בֶּֽ⁠עָפָ֑ר מִ⁠פְּנֵי֙ פַּ֣חַד יְהוָ֔ה וּ⁠מֵ⁠הֲדַ֖ר גְּאֹנֽ⁠וֹ׃","ḃ֣wòʼ ba⁠ẕ̇֔ẇr wĕ⁠hitá̇mé֖n bėֽ⁠ʻápá֑r mi⁠pĕ̇néy֙ pȧ֣ẖad yĕhwá֔h ẇ⁠mé⁠hàda֖r gĕ̇ʼònֽ⁠wò׃"],[2,11,"עֵינֵ֞י גַּבְה֤וּת אָדָם֙ שָׁפֵ֔ל וְ⁠שַׁ֖ח ר֣וּם אֲנָשִׁ֑ים וְ⁠נִשְׂגַּ֧ב יְהוָ֛ה לְ⁠בַדּ֖⁠וֹ בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃ס","ʻéyné֞y gȧbĕh֤ẇţ ʼádám֙ şá̌pé֔l wĕ⁠şǎ֖ẖ r֣ẇm ʼànáşǐ֑ym wĕ⁠nişĕ̂gȧ֧b yĕhwá֛h lĕ⁠baḋ֖⁠wò bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃s"],[2,12,"כִּ֣י י֞וֹם לַ⁠יהוָ֧ה צְבָא֛וֹת עַ֥ל כָּל־גֵּאֶ֖ה וָ⁠רָ֑ם וְ⁠עַ֖ל כָּל־נִשָּׂ֥א וְ⁠שָׁפֵֽל׃","ki֣̇y y֞wòm la⁠yhwá֧h ẕĕbáʼ֛wòţ ʻa֥l ká̇l-gé̇ʼe֖h wá⁠rá֑m wĕ⁠ʻa֖l ká̇l-nişá֥̇̂ʼ wĕ⁠şá̌péֽl׃"],[2,13,"וְ⁠עַל֙ כָּל־אַרְזֵ֣י הַ⁠לְּבָנ֔וֹן הָ⁠רָמִ֖ים וְ⁠הַ⁠נִּשָּׂאִ֑ים וְ⁠עַ֖ל כָּל־אַלּוֹנֵ֥י הַ⁠בָּשָֽׁן׃","wĕ⁠ʻal֙ ká̇l-ʼarĕzé֣y ha⁠lĕ̇bán֔wòn há⁠rámi֖ym wĕ⁠ha⁠ni̇şá̇̂ʼi֑ym wĕ⁠ʻa֖l ká̇l-ʼal̇wòné֥y ha⁠bá̇şáֽ̌n׃"],[2,14,"וְ⁠עַ֖ל כָּל־הֶ⁠הָרִ֣ים הָ⁠רָמִ֑ים וְ⁠עַ֖ל כָּל־הַ⁠גְּבָע֥וֹת הַ⁠נִּשָּׂאֽוֹת׃","wĕ⁠ʻa֖l ká̇l-he⁠hári֣ym há⁠rámi֑ym wĕ⁠ʻa֖l ká̇l-ha⁠gĕ̇báʻ֥wòţ ha⁠ni̇şá̇̂ʼֽwòţ׃"],[2,15,"וְ⁠עַ֖ל כָּל־מִגְדָּ֣ל גָּבֹ֑הַ וְ⁠עַ֖ל כָּל־חוֹמָ֥ה בְצוּרָֽה׃","wĕ⁠ʻa֖l ká̇l-migĕdá֣̇l gá̇bò֑ha wĕ⁠ʻa֖l ká̇l-ẖwòmá֥h bĕẕẇráֽh׃"],[2,16,"וְ⁠עַ֖ל כָּל־אֳנִיּ֣וֹת תַּרְשִׁ֑ישׁ וְ⁠עַ֖ל כָּל־שְׂכִיּ֥וֹת הַ⁠חֶמְדָּֽה׃","wĕ⁠ʻa֖l ká̇l-ʼoniẏ֣wòţ ţȧrĕşǐ֑yş̌ wĕ⁠ʻa֖l ká̇l-şĕ̂kiẏ֥wòţ ha⁠ẖemĕdáֽ̇h׃"],[2,17,"וְ⁠שַׁח֙ גַּבְה֣וּת הָ⁠אָדָ֔ם וְ⁠שָׁפֵ֖ל ר֣וּם אֲנָשִׁ֑ים וְ⁠נִשְׂגַּ֧ב יְהוָ֛ה לְ⁠בַדּ֖⁠וֹ בַּ⁠יּ֥וֹם הַ⁠הֽוּא׃","wĕ⁠şǎẖ֙ gȧbĕh֣ẇţ há⁠ʼádá֔m wĕ⁠şá̌pé֖l r֣ẇm ʼànáşǐ֑ym wĕ⁠nişĕ̂gȧ֧b yĕhwá֛h lĕ⁠baḋ֖⁠wò bȧ⁠ẏ֥wòm ha⁠hֽẇʼ׃"],[2,18,"וְ⁠הָ⁠אֱלִילִ֖ים כָּלִ֥יל יַחֲלֹֽף׃","wĕ⁠há⁠ʼèliyli֖ym ká̇li֥yl yaẖàlòֽp׃"],[2,19,"וּ⁠בָ֨אוּ֙ בִּ⁠מְעָר֣וֹת צֻרִ֔ים וּ⁠בִ⁠מְחִלּ֖וֹת עָפָ֑ר מִ⁠פְּנֵ֞י פַּ֤חַד יְהוָה֙ וּ⁠מֵ⁠הֲדַ֣ר גְּאוֹנ֔⁠וֹ בְּ⁠קוּמ֖⁠וֹ לַ⁠עֲרֹ֥ץ הָ⁠אָֽרֶץ׃","ẇ⁠bá֨ʼẇ֙ bi̇⁠mĕʻár֣wòţ ẕuri֔ym ẇ⁠bi⁠mĕẖil֖̇wòţ ʻápá֑r mi⁠pĕ̇né֞y pȧ֤ẖad yĕhwáh֙ ẇ⁠mé⁠hàda֣r gĕ̇ʼwòn֔⁠wò bĕ̇⁠qẇm֖⁠wò la⁠ʻàrò֥ẕ há⁠ʼáֽreẕ׃"],[2,20,"בַּ⁠יּ֤וֹם הַ⁠הוּא֙ יַשְׁלִ֣יךְ הָ⁠אָדָ֔ם אֵ֚ת אֱלִילֵ֣י כַסְפּ֔⁠וֹ וְ⁠אֵ֖ת אֱלִילֵ֣י זְהָב֑⁠וֹ אֲשֶׁ֤ר עָֽשׂוּ־ל⁠וֹ֙ לְ⁠הִֽשְׁתַּחֲוֺ֔ת לַ⁠חְפֹּ֥ר פֵּר֖וֹת וְ⁠לָ⁠עֲטַלֵּפִֽים׃","bȧ⁠ẏ֤wòm ha⁠hẇʼ֙ yaşĕ̌li֣ykĕ há⁠ʼádá֔m ʼé֚ţ ʼèliylé֣y kasĕṗ֔⁠wò wĕ⁠ʼé֖ţ ʼèliylé֣y zĕháb֑⁠wò ʼàşě֤r ʻáֽş̂ẇ-l⁠wò֙ lĕ⁠hiֽşĕ̌ţȧẖàwֺ֔ţ la⁠ẖĕpò֥̇r pé̇r֖wòţ wĕ⁠lá⁠ʻàtalé̇piֽym׃"],[2,21,"לָ⁠בוֹא֙ בְּ⁠נִקְר֣וֹת הַ⁠צֻּרִ֔ים וּ⁠בִ⁠סְעִפֵ֖י הַ⁠סְּלָעִ֑ים מִ⁠פְּנֵ֞י פַּ֤חַד יְהוָה֙ וּ⁠מֵ⁠הֲדַ֣ר גְּאוֹנ֔⁠וֹ בְּ⁠קוּמ֖⁠וֹ לַ⁠עֲרֹ֥ץ הָ⁠אָֽרֶץ׃","lá⁠bwòʼ֙ bĕ̇⁠niqĕr֣wòţ ha⁠ẕu̇ri֔ym ẇ⁠bi⁠sĕʻipé֖y ha⁠sĕ̇láʻi֑ym mi⁠pĕ̇né֞y pȧ֤ẖad yĕhwáh֙ ẇ⁠mé⁠hàda֣r gĕ̇ʼwòn֔⁠wò bĕ̇⁠qẇm֖⁠wò la⁠ʻàrò֥ẕ há⁠ʼáֽreẕ׃"],[2,22,"חִדְל֤וּ לָ⁠כֶם֙ מִן־הָ֣⁠אָדָ֔ם אֲשֶׁ֥ר נְשָׁמָ֖ה בְּ⁠אַפּ֑⁠וֹ כִּֽי־בַ⁠מֶּ֥ה נֶחְשָׁ֖ב הֽוּא׃פ","ẖidĕl֤ẇ lá⁠kem֙ min-há֣⁠ʼádá֔m ʼàşě֥r nĕşá̌má֖h bĕ̇⁠ʼaṗ֑⁠wò kiֽ̇y-ba⁠mė֥h neẖĕşá֖̌b hֽẇʼ׃p"],[3,1,"כִּי֩ הִנֵּ֨ה הָ⁠אָד֜וֹן יְהוָ֣ה צְבָא֗וֹת מֵסִ֤יר מִ⁠ירוּשָׁלִַ֨ם֙ וּ⁠מִ֣⁠יהוּדָ֔ה מַשְׁעֵ֖ן וּ⁠מַשְׁעֵנָ֑ה כֹּ֚ל מִשְׁעַן־לֶ֔חֶם וְ⁠כֹ֖ל מִשְׁעַן־מָֽיִם׃","ki̇y֩ hiné̇֨h há⁠ʼád֜wòn yĕhwá֣h ẕĕbáʼ֗wòţ mési֤yr mi⁠yrẇşá̌lia֨m֙ ẇ⁠mi֣⁠yhẇdá֔h maşĕ̌ʻé֖n ẇ⁠maşĕ̌ʻéná֑h kò֚̇l mişĕ̌ʻan-le֔ẖem wĕ⁠kò֖l mişĕ̌ʻan-máֽyim׃"],[3,2,"גִּבּ֖וֹר וְ⁠אִ֣ישׁ מִלְחָמָ֑ה שׁוֹפֵ֥ט וְ⁠נָבִ֖יא וְ⁠קֹסֵ֥ם וְ⁠זָקֵֽן׃","gi̇ḃ֖wòr wĕ⁠ʼi֣yş̌ milĕẖámá֑h ş̌wòpé֥t wĕ⁠nábi֖yʼ wĕ⁠qòsé֥m wĕ⁠záqéֽn׃"],[3,3,"שַׂר־חֲמִשִּׁ֖ים וּ⁠נְשׂ֣וּא פָנִ֑ים וְ⁠יוֹעֵ֛ץ וַ⁠חֲכַ֥ם חֲרָשִׁ֖ים וּ⁠נְב֥וֹן לָֽחַשׁ׃","şâr-ẖàmişi֖̇̌ym ẇ⁠nĕş֣̂ẇʼ páni֑ym wĕ⁠ywòʻé֛ẕ wa⁠ẖàka֥m ẖàráşǐ֖ym ẇ⁠nĕb֥wòn láֽẖaş̌׃"],[3,4,"וְ⁠נָתַתִּ֥י נְעָרִ֖ים שָׂרֵי⁠הֶ֑ם וְ⁠תַעֲלוּלִ֖ים יִמְשְׁלוּ־בָֽ⁠ם׃","wĕ⁠náţaţi֥̇y nĕʻári֖ym şá̂réy⁠he֑m wĕ⁠ţaʻàlẇli֖ym yimĕşĕ̌lẇ-báֽ⁠m׃"],[3,5,"וְ⁠נִגַּ֣שׂ הָ⁠עָ֔ם אִ֥ישׁ בְּ⁠אִ֖ישׁ וְ⁠אִ֣ישׁ בְּ⁠רֵעֵ֑⁠הוּ יִרְהֲב֗וּ הַ⁠נַּ֨עַר֙ בַּ⁠זָּקֵ֔ן וְ⁠הַ⁠נִּקְלֶ֖ה בַּ⁠נִּכְבָּֽד׃","wĕ⁠nigȧ֣ş̂ há⁠ʻá֔m ʼi֥yş̌ bĕ̇⁠ʼi֖yş̌ wĕ⁠ʼi֣yş̌ bĕ̇⁠réʻé֑⁠hẇ yirĕhàb֗ẇ ha⁠nȧ֨ʻar֙ bȧ⁠zá̇qé֔n wĕ⁠ha⁠ni̇qĕle֖h bȧ⁠ni̇kĕbáֽ̇d׃"],[3,6,"כִּֽי־יִתְפֹּ֨שׂ אִ֤ישׁ בְּ⁠אָחִי⁠ו֙ בֵּ֣ית אָבִ֔י⁠ו שִׂמְלָ֣ה לְ⁠כָ֔ה קָצִ֖ין תִּֽהְיֶה־לָּ֑⁠נוּ וְ⁠הַ⁠מַּכְשֵׁלָ֥ה הַ⁠זֹּ֖את תַּ֥חַת יָדֶֽ⁠ךָ׃","kiֽ̇y-yiţĕpò̇֨ş̂ ʼi֤yş̌ bĕ̇⁠ʼáẖiy⁠w֙ bé֣̇yţ ʼábi֔y⁠w şîmĕlá֣h lĕ⁠ká֔h qáẕi֖yn ţiֽ̇hĕyeh-lá֑̇⁠nẇ wĕ⁠ha⁠mȧkĕşé̌lá֥h ha⁠zò֖̇ʼţ ţȧ֥ẖaţ yádeֽ⁠ká׃"],[3,7,"יִשָּׂא֩ בַ⁠יּ֨וֹם הַ⁠ה֤וּא ׀ לֵ⁠אמֹר֙ לֹא־אֶהְיֶ֣ה חֹבֵ֔שׁ וּ⁠בְ⁠בֵיתִ֕⁠י אֵ֥ין לֶ֖חֶם וְ⁠אֵ֣ין שִׂמְלָ֑ה לֹ֥א תְשִׂימֻ֖⁠נִי קְצִ֥ין עָֽם׃","yişá̇̂ʼ֩ ba⁠ẏ֨wòm ha⁠h֤ẇʼ ׀ lé⁠ʼmòr֙ lòʼ-ʼehĕye֣h ẖòbé֔ş̌ ẇ⁠bĕ⁠béyţi֕⁠y ʼé֥yn le֖ẖem wĕ⁠ʼé֣yn şîmĕlá֑h lò֥ʼ ţĕşîymu֖⁠niy qĕẕi֥yn ʻáֽm׃"],[3,8,"כִּ֤י כָשְׁלָה֙ יְר֣וּשָׁלִַ֔ם וִ⁠יהוּדָ֖ה נָפָ֑ל כִּֽי־לְשׁוֹנָ֤⁠ם וּ⁠מַֽעַלְלֵי⁠הֶם֙ אֶל־יְהוָ֔ה לַ⁠מְר֖וֹת עֵנֵ֥י כְבוֹדֽ⁠וֹ׃","ki֤̇y káşĕ̌láh֙ yĕr֣ẇşá̌lia֔m wi⁠yhẇdá֖h nápá֑l kiֽ̇y-lĕş̌wòná֤⁠m ẇ⁠maֽʻalĕléy⁠hem֙ ʼel-yĕhwá֔h la⁠mĕr֖wòţ ʻéné֥y kĕbwòdֽ⁠wò׃"],[3,9,"הַכָּרַ֤ת פְּנֵי⁠הֶם֙ עָ֣נְתָה בָּ֔⁠ם וְ⁠חַטָּאתָ֛⁠ם כִּ⁠סְדֹ֥ם הִגִּ֖ידוּ לֹ֣א כִחֵ֑דוּ א֣וֹי לְ⁠נַפְשָׁ֔⁠ם כִּֽי־גָמְל֥וּ לָ⁠הֶ֖ם רָעָֽה׃","haká̇ra֤ţ pĕ̇néy⁠hem֙ ʻá֣nĕţáh bá̇֔⁠m wĕ⁠ẖatá̇ʼţá֛⁠m ki̇⁠sĕdò֥m higi֖̇ydẇ lò֣ʼ kiẖé֑dẇ ʼ֣wòy lĕ⁠napĕşá̌֔⁠m kiֽ̇y-gámĕl֥ẇ lá⁠he֖m ráʻáֽh׃"],[3,10,"אִמְר֥וּ צַדִּ֖יק כִּי־ט֑וֹב כִּֽי־פְרִ֥י מַעַלְלֵי⁠הֶ֖ם יֹאכֵֽלוּ׃","ʼimĕr֥ẇ ẕadi֖̇yq ki̇y-t֑wòb kiֽ̇y-pĕri֥y maʻalĕléy⁠he֖m yòʼkéֽlẇ׃"],[3,11,"א֖וֹי לְ⁠רָשָׁ֣ע רָ֑ע כִּֽי־גְמ֥וּל יָדָ֖י⁠ו יֵעָ֥שֶׂה לּֽ⁠וֹ׃","ʼ֖wòy lĕ⁠ráşá֣̌ʻ rá֑ʻ kiֽ̇y-gĕm֥ẇl yádá֖y⁠w yéʻá֥şêh lֽ̇⁠wò׃"],[3,12,"עַמִּ⁠י֙ נֹגְשָׂ֣י⁠ו מְעוֹלֵ֔ל וְ⁠נָשִׁ֖ים מָ֣שְׁלוּ ב֑⁠וֹ עַמִּ⁠י֙ מְאַשְּׁרֶ֣י⁠ךָ מַתְעִ֔ים וְ⁠דֶ֥רֶךְ אֹֽרְחֹתֶ֖י⁠ךָ בִּלֵּֽעוּ׃ס","ʻami̇⁠y֙ nògĕşá֣̂y⁠w mĕʻwòlé֔l wĕ⁠náşǐ֖ym má֣şĕ̌lẇ b֑⁠wò ʻami̇⁠y֙ mĕʼaşĕ̇̌re֣y⁠ká maţĕʻi֔ym wĕ⁠de֥rekĕ ʼòֽrĕẖòţe֖y⁠ká bi̇léֽ̇ʻẇ׃s"],[3,13,"נִצָּ֥ב לָ⁠רִ֖יב יְהוָ֑ה וְ⁠עֹמֵ֖ד לָ⁠דִ֥ין עַמִּֽים׃","niẕá֥̇b lá⁠ri֖yb yĕhwá֑h wĕ⁠ʻòmé֖d lá⁠di֥yn ʻamiֽ̇ym׃"],[3,14,"יְהוָה֙ בְּ⁠מִשְׁפָּ֣ט יָב֔וֹא עִם־זִקְנֵ֥י עַמּ֖⁠וֹ וְ⁠שָׂרָ֑י⁠ו וְ⁠אַתֶּם֙ בִּֽעַרְתֶּ֣ם הַ⁠כֶּ֔רֶם גְּזֵלַ֥ת הֶֽ⁠עָנִ֖י בְּ⁠בָתֵּי⁠כֶֽם׃","yĕhwáh֙ bĕ̇⁠mişĕ̌pá֣̇t yáb֔wòʼ ʻim-ziqĕné֥y ʻaṁ֖⁠wò wĕ⁠şá̂rá֑y⁠w wĕ⁠ʼaţėm֙ biֽ̇ʻarĕţė֣m ha⁠kė֔rem gĕ̇zéla֥ţ heֽ⁠ʻáni֖y bĕ̇⁠báţé̇y⁠keֽm׃"],[3,15,"מ⁠ל⁠כם תְּדַכְּא֣וּ עַמִּ֔⁠י וּ⁠פְנֵ֥י עֲנִיִּ֖ים תִּטְחָ֑נוּ נְאֻם־אֲדֹנָ֥⁠י יְהוִ֖ה צְבָאֽוֹת׃ס","m⁠l⁠km ţĕ̇dakĕ̇ʼ֣ẇ ʻami̇֔⁠y ẇ⁠pĕné֥y ʻàniyi֖̇ym ţi̇tĕẖá֑nẇ nĕʼum-ʼàdòná֥⁠y yĕhwi֖h ẕĕbáʼֽwòţ׃s"],[3,16,"וַ⁠יֹּ֣אמֶר יְהוָ֗ה יַ֚עַן כִּ֤י גָֽבְהוּ֙ בְּנ֣וֹת צִיּ֔וֹן וַ⁠תֵּלַ֨כְנָה֙ נטוות גָּר֔וֹן וּֽ⁠מְשַׂקְּר֖וֹת עֵינָ֑יִם הָל֤וֹךְ וְ⁠טָפֹף֙ תֵּלַ֔כְנָה וּ⁠בְ⁠רַגְלֵי⁠הֶ֖ם תְּעַכַּֽסְנָה׃","wa⁠yò֣̇ʼmer yĕhwá֗h ya֚ʻan ki֤̇y gáֽbĕhẇ֙ bĕ̇n֣wòţ ẕiẏ֔wòn wa⁠ţé̇la֨kĕnáh֙ ntwwţ gá̇r֔wòn ẇֽ⁠mĕşâqĕ̇r֖wòţ ʻéyná֑yim hál֤wòkĕ wĕ⁠tápòp֙ ţé̇la֔kĕnáh ẇ⁠bĕ⁠ragĕléy⁠he֖m ţĕ̇ʻakȧֽsĕnáh׃"],[3,17,"וְ⁠שִׂפַּ֣ח אֲדֹנָ֔⁠י קָדְקֹ֖ד בְּנ֣וֹת צִיּ֑וֹן וַ⁠יהוָ֖ה פָּתְ⁠הֵ֥ן יְעָרֶֽה׃ס","wĕ⁠şîpȧ֣ẖ ʼàdòná֔⁠y qádĕqò֖d bĕ̇n֣wòţ ẕiẏ֑wòn wa⁠yhwá֖h pá̇ţĕ⁠hé֥n yĕʻáreֽh׃s"],[3,18,"בַּ⁠יּ֨וֹם הַ⁠ה֜וּא יָסִ֣יר אֲדֹנָ֗⁠י אֵ֣ת תִּפְאֶ֧רֶת הָ⁠עֲכָסִ֛ים וְ⁠הַ⁠שְּׁבִיסִ֖ים וְ⁠הַ⁠שַּׂהֲרֹנִֽים׃","bȧ⁠ẏ֨wòm ha⁠h֜ẇʼ yási֣yr ʼàdòná֗⁠y ʼé֣ţ ţi̇pĕʼe֧reţ há⁠ʻàkási֛ym wĕ⁠ha⁠şĕ̇̌biysi֖ym wĕ⁠ha⁠şȧ̂hàròniֽym׃"],[3,19,"הַ⁠נְּטִיפ֥וֹת וְ⁠הַ⁠שֵּׁיר֖וֹת וְ⁠הָֽ⁠רְעָלֽוֹת׃","ha⁠nĕ̇tiyp֥wòţ wĕ⁠ha⁠şé̇̌yr֖wòţ wĕ⁠háֽ⁠rĕʻálֽwòţ׃"],[3,20,"הַ⁠פְּאֵרִ֤ים וְ⁠הַ⁠צְּעָדוֹת֙ וְ⁠הַ⁠קִּשֻּׁרִ֔ים וּ⁠בָתֵּ֥י הַ⁠נֶּ֖פֶשׁ וְ⁠הַ⁠לְּחָשִֽׁים׃","ha⁠pĕ̇ʼéri֤ym wĕ⁠ha⁠ẕĕ̇ʻádwòţ֙ wĕ⁠ha⁠qi̇şu̇̌ri֔ym ẇ⁠báţé֥̇y ha⁠nė֖peş̌ wĕ⁠ha⁠lĕ̇ẖáşǐֽym׃"],[3,21,"הַ⁠טַּבָּע֖וֹת וְ⁠נִזְמֵ֥י הָ⁠אָֽף׃","ha⁠tȧbá̇ʻ֖wòţ wĕ⁠nizĕmé֥y há⁠ʼáֽp׃"],[3,22,"הַ⁠מַּֽחֲלָצוֹת֙ וְ⁠הַ⁠מַּ֣עֲטָפ֔וֹת וְ⁠הַ⁠מִּטְפָּח֖וֹת וְ⁠הָ⁠חֲרִיטִֽים׃","ha⁠mȧֽẖàláẕwòţ֙ wĕ⁠ha⁠mȧ֣ʻàtáp֔wòţ wĕ⁠ha⁠mi̇tĕpá̇ẖ֖wòţ wĕ⁠há⁠ẖàriytiֽym׃"],[3,23,"וְ⁠הַ⁠גִּלְיֹנִים֙ וְ⁠הַ⁠סְּדִינִ֔ים וְ⁠הַ⁠צְּנִיפ֖וֹת וְ⁠הָ⁠רְדִידִֽים׃","wĕ⁠ha⁠gi̇lĕyòniym֙ wĕ⁠ha⁠sĕ̇diyni֔ym wĕ⁠ha⁠ẕĕ̇niyp֖wòţ wĕ⁠há⁠rĕdiydiֽym׃"],[3,24,"וְ⁠הָיָה֩ תַ֨חַת בֹּ֜שֶׂם מַ֣ק יִֽהְיֶ֗ה וְ⁠תַ֨חַת חֲגוֹרָ֤ה נִקְפָּה֙ וְ⁠תַ֨חַת מַעֲשֶׂ֤ה מִקְשֶׁה֙ קָרְחָ֔ה וְ⁠תַ֥חַת פְּתִיגִ֖יל מַחֲגֹ֣רֶת שָׂ֑ק כִּי־תַ֖חַת יֹֽפִי׃","wĕ⁠háyáh֩ ţa֨ẖaţ bò̇֜şêm ma֣q yiֽhĕye֗h wĕ⁠ţa֨ẖaţ ẖàgwòrá֤h niqĕpá̇h֙ wĕ⁠ţa֨ẖaţ maʻàşê֤h miqĕşěh֙ qárĕẖá֔h wĕ⁠ţa֥ẖaţ pĕ̇ţiygi֖yl maẖàgò֣reţ şá֑̂q ki̇y-ţa֖ẖaţ yòֽpiy׃"],[3,25,"מְתַ֖יִ⁠ךְ בַּ⁠חֶ֣רֶב יִפֹּ֑לוּ וּ⁠גְבוּרָתֵ֖⁠ךְ בַּ⁠מִּלְחָמָֽה׃","mĕţa֖yi⁠kĕ bȧ⁠ẖe֣reb yipò֑̇lẇ ẇ⁠gĕbẇráţé֖⁠kĕ bȧ⁠mi̇lĕẖámáֽh׃"],[3,26,"וְ⁠אָנ֥וּ וְ⁠אָבְל֖וּ פְּתָחֶ֑י⁠הָ וְ⁠נִקָּ֖תָה לָ⁠אָ֥רֶץ תֵּשֵֽׁב׃","wĕ⁠ʼán֥ẇ wĕ⁠ʼábĕl֖ẇ pĕ̇ţáẖe֑y⁠há wĕ⁠niqá֖̇ţáh lá⁠ʼá֥reẕ ţé̇şéֽ̌b׃"],[4,1,"וְ⁠הֶחֱזִיקוּ֩ שֶׁ֨בַע נָשִׁ֜ים בְּ⁠אִ֣ישׁ אֶחָ֗ד בַּ⁠יּ֤וֹם הַ⁠הוּא֙ לֵ⁠אמֹ֔ר לַחְמֵ֣⁠נוּ נֹאכֵ֔ל וְ⁠שִׂמְלָתֵ֖⁠נוּ נִלְבָּ֑שׁ רַ֗ק יִקָּרֵ֤א שִׁמְ⁠ךָ֙ עָלֵ֔י⁠נוּ אֱסֹ֖ף חֶרְפָּתֵֽ⁠נוּ׃ס","wĕ⁠heẖèziyqẇ֩ şě֨baʻ náşǐ֜ym bĕ̇⁠ʼi֣yş̌ ʼeẖá֗d bȧ⁠ẏ֤wòm ha⁠hẇʼ֙ lé⁠ʼmò֔r laẖĕmé֣⁠nẇ nòʼké֔l wĕ⁠şîmĕláţé֖⁠nẇ nilĕbá֑̇ş̌ ra֗q yiqá̇ré֤ʼ şǐmĕ⁠ká֙ ʻálé֔y⁠nẇ ʼèsò֖p ẖerĕpá̇ţéֽ⁠nẇ׃s"],[4,2,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִֽהְיֶה֙ צֶ֣מַח יְהוָ֔ה לִ⁠צְבִ֖י וּ⁠לְ⁠כָב֑וֹד וּ⁠פְרִ֤י הָ⁠אָ֨רֶץ֙ לְ⁠גָא֣וֹן וּ⁠לְ⁠תִפְאֶ֔רֶת לִ⁠פְלֵיטַ֖ת יִשְׂרָאֵֽל׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yiֽhĕyeh֙ ẕe֣maẖ yĕhwá֔h li⁠ẕĕbi֖y ẇ⁠lĕ⁠káb֑wòd ẇ⁠pĕri֤y há⁠ʼá֨reẕ֙ lĕ⁠gáʼ֣wòn ẇ⁠lĕ⁠ţipĕʼe֔reţ li⁠pĕléyta֖ţ yişĕ̂ráʼéֽl׃"],[4,3,"וְ⁠הָיָ֣ה ׀ הַ⁠נִּשְׁאָ֣ר בְּ⁠צִיּ֗וֹן וְ⁠הַ⁠נּוֹתָר֙ בִּ⁠יר֣וּשָׁלִַ֔ם קָד֖וֹשׁ יֵאָ֣מֶר ל֑⁠וֹ כָּל־הַ⁠כָּת֥וּב לַ⁠חַיִּ֖ים בִּ⁠ירוּשָׁלִָֽם׃","wĕ⁠háyá֣h ׀ ha⁠ni̇şĕ̌ʼá֣r bĕ̇⁠ẕiẏ֗wòn wĕ⁠ha⁠ṅwòţár֙ bi̇⁠yr֣ẇşá̌lia֔m qád֖wòş̌ yéʼá֣mer l֑⁠wò ká̇l-ha⁠ká̇ţ֥ẇb la⁠ẖayi֖̇ym bi̇⁠yrẇşá̌liáֽm׃"],[4,4,"אִ֣ם ׀ רָחַ֣ץ אֲדֹנָ֗⁠י אֵ֚ת צֹאַ֣ת בְּנוֹת־צִיּ֔וֹן וְ⁠אֶת־דְּמֵ֥י יְרוּשָׁלִַ֖ם יָדִ֣יחַ מִ⁠קִּרְבָּ֑⁠הּ בְּ⁠ר֥וּחַ מִשְׁפָּ֖ט וּ⁠בְ⁠ר֥וּחַ בָּעֵֽר׃","ʼi֣m ׀ ráẖa֣ẕ ʼàdòná֗⁠y ʼé֚ţ ẕòʼa֣ţ bĕ̇nwòţ-ẕiẏ֔wòn wĕ⁠ʼeţ-dĕ̇mé֥y yĕrẇşá̌lia֖m yádi֣yẖa mi⁠qi̇rĕbá֑̇⁠ḣ bĕ̇⁠r֥ẇẖa mişĕ̌pá֖̇t ẇ⁠bĕ⁠r֥ẇẖa bá̇ʻéֽr׃"],[4,5,"וּ⁠בָרָ֣א יְהוָ֡ה עַל֩ כָּל־מְכ֨וֹן הַר־צִיּ֜וֹן וְ⁠עַל־מִקְרָאֶ֗⁠הָ עָנָ֤ן ׀ יוֹמָם֙ וְ⁠עָשָׁ֔ן וְ⁠נֹ֛גַהּ אֵ֥שׁ לֶהָבָ֖ה לָ֑יְלָה כִּ֥י עַל־כָּל־כָּב֖וֹד חֻפָּֽה׃","ẇ⁠bárá֣ʼ yĕhwá֡h ʻal֩ ká̇l-mĕk֨wòn har-ẕiẏ֜wòn wĕ⁠ʻal-miqĕráʼe֗⁠há ʻáná֤n ׀ ywòmám֙ wĕ⁠ʻáşá̌֔n wĕ⁠nò֛gaḣ ʼé֥ş̌ lehábá֖h lá֑yĕláh ki֥̇y ʻal-ká̇l-ká̇b֖wòd ẖupáֽ̇h׃"],[4,6,"וְ⁠סֻכָּ֛ה תִּהְיֶ֥ה לְ⁠צֵל־יוֹמָ֖ם מֵ⁠חֹ֑רֶב וּ⁠לְ⁠מַחְסֶה֙ וּ⁠לְ⁠מִסְתּ֔וֹר מִ⁠זֶּ֖רֶם וּ⁠מִ⁠מָּטָֽר׃פ","wĕ⁠suká֛̇h ţi̇hĕye֥h lĕ⁠ẕél-ywòmá֖m mé⁠ẖò֑reb ẇ⁠lĕ⁠maẖĕseh֙ ẇ⁠lĕ⁠misĕţ̇֔wòr mi⁠zė֖rem ẇ⁠mi⁠má̇táֽr׃p"],[5,1,"אָשִׁ֤ירָה נָּא֙ לִֽ⁠ידִידִ֔⁠י שִׁירַ֥ת דּוֹדִ֖⁠י לְ⁠כַרְמ֑⁠וֹ כֶּ֛רֶם הָיָ֥ה לִֽ⁠ידִידִ֖⁠י בְּ⁠קֶ֥רֶן בֶּן־שָֽׁמֶן׃","ʼáşǐ֤yráh ná̇ʼ֙ liֽ⁠ydiydi֔⁠y şǐyra֥ţ ḋwòdi֖⁠y lĕ⁠karĕm֑⁠wò kė֛rem háyá֥h liֽ⁠ydiydi֖⁠y bĕ̇⁠qe֥ren bėn-şáֽ̌men׃"],[5,2,"וַֽ⁠יְעַזְּקֵ֣⁠הוּ וַֽ⁠יְסַקְּלֵ֗⁠הוּ וַ⁠יִּטָּעֵ֨⁠הוּ֙ שֹׂרֵ֔ק וַ⁠יִּ֤בֶן מִגְדָּל֙ בְּ⁠תוֹכ֔⁠וֹ וְ⁠גַם־יֶ֖קֶב חָצֵ֣ב בּ֑⁠וֹ וַ⁠יְקַ֛ו לַ⁠עֲשׂ֥וֹת עֲנָבִ֖ים וַ⁠יַּ֥עַשׂ בְּאֻשִֽׁים׃","waֽ⁠yĕʻazĕ̇qé֣⁠hẇ waֽ⁠yĕsaqĕ̇lé֗⁠hẇ wa⁠yi̇tá̇ʻé֨⁠hẇ֙ şò̂ré֔q wa⁠yi֤̇ben migĕdá̇l֙ bĕ̇⁠ţwòk֔⁠wò wĕ⁠gam-ye֖qeb ẖáẕé֣b ḃ֑⁠wò wa⁠yĕqa֛w la⁠ʻàş֥̂wòţ ʻànábi֖ym wa⁠yȧ֥ʻaş̂ bĕ̇ʼuşǐֽym׃"],[5,3,"וְ⁠עַתָּ֛ה יוֹשֵׁ֥ב יְרוּשָׁלִַ֖ם וְ⁠אִ֣ישׁ יְהוּדָ֑ה שִׁפְטוּ־נָ֕א בֵּינִ֖⁠י וּ⁠בֵ֥ין כַּרְמִֽ⁠י׃","wĕ⁠ʻaţá֛̇h ywòşé֥̌b yĕrẇşá̌lia֖m wĕ⁠ʼi֣yş̌ yĕhẇdá֑h şǐpĕtẇ-ná֕ʼ bé̇yni֖⁠y ẇ⁠bé֥yn kȧrĕmiֽ⁠y׃"],[5,4,"מַה־לַּ⁠עֲשׂ֥וֹת עוֹד֙ לְ⁠כַרְמִ֔⁠י וְ⁠לֹ֥א עָשִׂ֖יתִי בּ֑⁠וֹ מַדּ֧וּעַ קִוֵּ֛יתִי לַ⁠עֲשׂ֥וֹת עֲנָבִ֖ים וַ⁠יַּ֥עַשׂ בְּאֻשִֽׁים׃","mah-lȧ⁠ʻàş֥̂wòţ ʻwòd֙ lĕ⁠karĕmi֔⁠y wĕ⁠lò֥ʼ ʻáşî֖yţiy ḃ֑⁠wò maḋ֧ẇʻa qiwé֛̇yţiy la⁠ʻàş֥̂wòţ ʻànábi֖ym wa⁠yȧ֥ʻaş̂ bĕ̇ʼuşǐֽym׃"],[5,5,"וְ⁠עַתָּה֙ אוֹדִֽיעָה־נָּ֣א אֶתְ⁠כֶ֔ם אֵ֛ת אֲשֶׁר־אֲנִ֥י עֹשֶׂ֖ה לְ⁠כַרְמִ֑⁠י הָסֵ֤ר מְשׂוּכָּת⁠וֹ֙ וְ⁠הָיָ֣ה לְ⁠בָעֵ֔ר פָּרֹ֥ץ גְּדֵר֖⁠וֹ וְ⁠הָיָ֥ה לְ⁠מִרְמָֽס׃","wĕ⁠ʻaţá̇h֙ ʼwòdiֽyʻáh-ná֣̇ʼ ʼeţĕ⁠ke֔m ʼé֛ţ ʼàşěr-ʼàni֥y ʻòşê֖h lĕ⁠karĕmi֑⁠y hásé֤r mĕş̂ẇká̇ţ⁠wò֙ wĕ⁠háyá֣h lĕ⁠báʻé֔r pá̇rò֥ẕ gĕ̇dér֖⁠wò wĕ⁠háyá֥h lĕ⁠mirĕmáֽs׃"],[5,6,"וַ⁠אֲשִׁיתֵ֣⁠הוּ בָתָ֗ה לֹ֤א יִזָּמֵר֙ וְ⁠לֹ֣א יֵעָדֵ֔ר וְ⁠עָלָ֥ה שָׁמִ֖יר וָ⁠שָׁ֑יִת וְ⁠עַ֤ל הֶ⁠עָבִים֙ אֲצַוֶּ֔ה מֵ⁠הַמְטִ֥יר עָלָ֖י⁠ו מָטָֽר׃","wa⁠ʼàşǐyţé֣⁠hẇ báţá֗h lò֤ʼ yizá̇mér֙ wĕ⁠lò֣ʼ yéʻádé֔r wĕ⁠ʻálá֥h şá̌mi֖yr wá⁠şá֑̌yiţ wĕ⁠ʻa֤l he⁠ʻábiym֙ ʼàẕawė֔h mé⁠hamĕti֥yr ʻálá֖y⁠w mátáֽr׃"],[5,7,"כִּ֣י כֶ֜רֶם יְהוָ֤ה צְבָאוֹת֙ בֵּ֣ית יִשְׂרָאֵ֔ל וְ⁠אִ֣ישׁ יְהוּדָ֔ה נְטַ֖ע שַׁעֲשׁוּעָ֑י⁠ו וַ⁠יְקַ֤ו לְ⁠מִשְׁפָּט֙ וְ⁠הִנֵּ֣ה מִשְׂפָּ֔ח לִ⁠צְדָקָ֖ה וְ⁠הִנֵּ֥ה צְעָקָֽה׃ס","ki֣̇y ke֜rem yĕhwá֤h ẕĕbáʼwòţ֙ bé֣̇yţ yişĕ̂ráʼé֔l wĕ⁠ʼi֣yş̌ yĕhẇdá֔h nĕta֖ʻ şǎʻàş̌ẇʻá֑y⁠w wa⁠yĕqa֤w lĕ⁠mişĕ̌pá̇t֙ wĕ⁠hiné֣̇h mişĕ̂pá̇֔ẖ li⁠ẕĕdáqá֖h wĕ⁠hiné֥̇h ẕĕʻáqáֽh׃s"],[5,8,"ה֗וֹי מַגִּיעֵ֥י בַ֨יִת֙ בְּ⁠בַ֔יִת שָׂדֶ֥ה בְ⁠שָׂדֶ֖ה יַקְרִ֑יבוּ עַ֚ד אֶ֣פֶס מָק֔וֹם וְ⁠הֽוּשַׁבְתֶּ֥ם לְ⁠בַדְּ⁠כֶ֖ם בְּ⁠קֶ֥רֶב הָ⁠אָֽרֶץ׃","h֗wòy magi̇yʻé֥y ba֨yiţ֙ bĕ̇⁠ba֔yiţ şá̂de֥h bĕ⁠şá̂de֖h yaqĕri֑ybẇ ʻa֚d ʼe֣pes máq֔wòm wĕ⁠hֽẇşǎbĕţė֥m lĕ⁠badĕ̇⁠ke֖m bĕ̇⁠qe֥reb há⁠ʼáֽreẕ׃"],[5,9,"בְּ⁠אָזְנָ֖⁠י יְהוָ֣ה צְבָא֑וֹת אִם־לֹ֞א בָּתִּ֤ים רַבִּים֙ לְ⁠שַׁמָּ֣ה יִֽהְי֔וּ גְּדֹלִ֥ים וְ⁠טוֹבִ֖ים מֵ⁠אֵ֥ין יוֹשֵֽׁב׃","bĕ̇⁠ʼázĕná֖⁠y yĕhwá֣h ẕĕbáʼ֑wòţ ʼim-lò֞ʼ bá̇ţi֤̇ym rabi̇ym֙ lĕ⁠şǎmá֣̇h yiֽhĕy֔ẇ gĕ̇dòli֥ym wĕ⁠twòbi֖ym mé⁠ʼé֥yn ywòşéֽ̌b׃"],[5,10,"כִּ֗י עֲשֶׂ֨רֶת֙ צִמְדֵּי־כֶ֔רֶם יַעֲשׂ֖וּ בַּ֣ת אֶחָ֑ת וְ⁠זֶ֥רַע חֹ֖מֶר יַעֲשֶׂ֥ה אֵיפָֽה׃פ","ki̇֗y ʻàşê֨reţ֙ ẕimĕdé̇y-ke֔rem yaʻàş֖̂ẇ bȧ֣ţ ʼeẖá֑ţ wĕ⁠ze֥raʻ ẖò֖mer yaʻàşê֥h ʼéypáֽh׃p"],[5,11,"ה֛וֹי מַשְׁכִּימֵ֥י בַ⁠בֹּ֖קֶר שֵׁכָ֣ר יִרְדֹּ֑פוּ מְאַחֲרֵ֣י בַ⁠נֶּ֔שֶׁף יַ֖יִן יַדְלִיקֵֽ⁠ם׃","h֛wòy maşĕ̌ki̇ymé֥y ba⁠bò֖̇qer şé̌ká֣r yirĕdò֑̇pẇ mĕʼaẖàré֣y ba⁠nė֔şěp ya֖yin yadĕliyqéֽ⁠m׃"],[5,12,"וְ⁠הָיָ֨ה כִנּ֜וֹר וָ⁠נֶ֗בֶל תֹּ֧ף וְ⁠חָלִ֛יל וָ⁠יַ֖יִן מִשְׁתֵּי⁠הֶ֑ם וְ⁠אֵ֨ת פֹּ֤עַל יְהוָה֙ לֹ֣א יַבִּ֔יטוּ וּ⁠מַעֲשֵׂ֥ה יָדָ֖י⁠ו לֹ֥א רָאֽוּ׃","wĕ⁠háyá֨h kiṅ֜wòr wá⁠ne֗bel ţò֧̇p wĕ⁠ẖáli֛yl wá⁠ya֖yin mişĕ̌ţé̇y⁠he֑m wĕ⁠ʼé֨ţ pò֤̇ʻal yĕhwáh֙ lò֣ʼ yabi̇֔ytẇ ẇ⁠maʻàşé֥̂h yádá֖y⁠w lò֥ʼ ráʼֽẇ׃"],[5,13,"לָ⁠כֵ֛ן גָּלָ֥ה עַמִּ֖⁠י מִ⁠בְּלִי־דָ֑עַת וּ⁠כְבוֹד⁠וֹ֙ מְתֵ֣י רָעָ֔ב וַ⁠הֲמוֹנ֖⁠וֹ צִחֵ֥ה צָמָֽא׃","lá⁠ké֛n gá̇lá֥h ʻami֖̇⁠y mi⁠bĕ̇liy-dá֑ʻaţ ẇ⁠kĕbwòd⁠wò֙ mĕţé֣y ráʻá֔b wa⁠hàmwòn֖⁠wò ẕiẖé֥h ẕámáֽʼ׃"],[5,14,"לָ⁠כֵ֗ן הִרְחִ֤יבָה שְּׁאוֹל֙ נַפְשָׁ֔⁠הּ וּ⁠פָעֲרָ֥ה פִ֖י⁠הָ לִ⁠בְלִי־חֹ֑ק וְ⁠יָרַ֨ד הֲדָרָ֧⁠הּ וַ⁠הֲמוֹנָ֛⁠הּ וּ⁠שְׁאוֹנָ֖⁠הּ וְ⁠עָלֵ֥ז בָּֽ⁠הּ׃","lá⁠ké֗n hirĕẖi֤ybáh şĕ̇̌ʼwòl֙ napĕşá̌֔⁠ḣ ẇ⁠páʻàrá֥h pi֖y⁠há li⁠bĕliy-ẖò֑q wĕ⁠yára֨d hàdárá֧⁠ḣ wa⁠hàmwòná֛⁠ḣ ẇ⁠şĕ̌ʼwòná֖⁠ḣ wĕ⁠ʻálé֥z báֽ̇⁠ḣ׃"],[5,15,"וַ⁠יִּשַּׁ֥ח אָדָ֖ם וַ⁠יִּשְׁפַּל־אִ֑ישׁ וְ⁠עֵינֵ֥י גְבֹהִ֖ים תִּשְׁפַּֽלְנָה׃","wa⁠yi̇şȧ֥̌ẖ ʼádá֖m wa⁠yi̇şĕ̌pȧl-ʼi֑yş̌ wĕ⁠ʻéyné֥y gĕbòhi֖ym ţi̇şĕ̌pȧֽlĕnáh׃"],[5,16,"וַ⁠יִּגְבַּ֛ה יְהוָ֥ה צְבָא֖וֹת בַּ⁠מִּשְׁפָּ֑ט וְ⁠הָ⁠אֵל֙ הַ⁠קָּד֔וֹשׁ נִקְדָּ֖שׁ בִּ⁠צְדָקָֽה׃","wa⁠yi̇gĕbȧ֛h yĕhwá֥h ẕĕbáʼ֖wòţ bȧ⁠mi̇şĕ̌pá֑̇t wĕ⁠há⁠ʼél֙ ha⁠qá̇d֔wòş̌ niqĕdá֖̇ş̌ bi̇⁠ẕĕdáqáֽh׃"],[5,17,"וְ⁠רָע֥וּ כְבָשִׂ֖ים כְּ⁠דָבְרָ֑⁠ם וְ⁠חָרְב֥וֹת מֵחִ֖ים גָּרִ֥ים יֹאכֵֽלוּ׃","wĕ⁠ráʻ֥ẇ kĕbáşî֖ym kĕ̇⁠dábĕrá֑⁠m wĕ⁠ẖárĕb֥wòţ méẖi֖ym gá̇ri֥ym yòʼkéֽlẇ׃"],[5,18,"ה֛וֹי מֹשְׁכֵ֥י הֶֽ⁠עָוֺ֖ן בְּ⁠חַבְלֵ֣י הַ⁠שָּׁ֑וְא וְ⁠כַ⁠עֲב֥וֹת הָ⁠עֲגָלָ֖ה חַטָּאָֽה׃","h֛wòy mòşĕ̌ké֥y heֽ⁠ʻáwֺ֖n bĕ̇⁠ẖabĕlé֣y ha⁠şá֑̇̌wĕʼ wĕ⁠ka⁠ʻàb֥wòţ há⁠ʻàgálá֖h ẖatá̇ʼáֽh׃"],[5,19,"הָ⁠אֹמְרִ֗ים יְמַהֵ֧ר ׀ יָחִ֛ישָׁ⁠ה מַעֲשֵׂ֖⁠הוּ לְמַ֣עַן נִרְאֶ֑ה וְ⁠תִקְרַ֣ב וְ⁠תָב֗וֹאָ⁠ה עֲצַ֛ת קְד֥וֹשׁ יִשְׂרָאֵ֖ל וְ⁠נֵדָֽעָה׃ס","há⁠ʼòmĕri֗ym yĕmahé֧r ׀ yáẖi֛yşá̌⁠h maʻàşé֖̂⁠hẇ lĕma֣ʻan nirĕʼe֑h wĕ⁠ţiqĕra֣b wĕ⁠ţáb֗wòʼá⁠h ʻàẕa֛ţ qĕd֥wòş̌ yişĕ̂ráʼé֖l wĕ⁠nédáֽʻáh׃s"],[5,20,"ה֣וֹי הָ⁠אֹמְרִ֥ים לָ⁠רַ֛ע ט֖וֹב וְ⁠לַ⁠טּ֣וֹב רָ֑ע שָׂמִ֨ים חֹ֤שֶׁךְ לְ⁠אוֹר֙ וְ⁠א֣וֹר לְ⁠חֹ֔שֶׁךְ שָׂמִ֥ים מַ֛ר לְ⁠מָת֖וֹק וּ⁠מָת֥וֹק לְ⁠מָֽר׃ס","h֣wòy há⁠ʼòmĕri֥ym lá⁠ra֛ʻ t֖wòb wĕ⁠la⁠ṫ֣wòb rá֑ʻ şá̂mi֨ym ẖò֤şěkĕ lĕ⁠ʼwòr֙ wĕ⁠ʼ֣wòr lĕ⁠ẖò֔şěkĕ şá̂mi֥ym ma֛r lĕ⁠máţ֖wòq ẇ⁠máţ֥wòq lĕ⁠máֽr׃s"],[5,21,"ה֖וֹי חֲכָמִ֣ים בְּ⁠עֵֽינֵי⁠הֶ֑ם וְ⁠נֶ֥גֶד פְּנֵי⁠הֶ֖ם נְבֹנִֽים׃","h֖wòy ẖàkámi֣ym bĕ̇⁠ʻéֽynéy⁠he֑m wĕ⁠ne֥ged pĕ̇néy⁠he֖m nĕbòniֽym׃"],[5,22,"ה֕וֹי גִּבּוֹרִ֖ים לִ⁠שְׁתּ֣וֹת יָ֑יִן וְ⁠אַנְשֵׁי־חַ֖יִל לִ⁠מְסֹ֥ךְ שֵׁכָֽר׃","h֕wòy gi̇ḃwòri֖ym li⁠şĕ̌ţ֣̇wòţ yá֑yin wĕ⁠ʼanĕşé̌y-ẖa֖yil li⁠mĕsò֥kĕ şé̌káֽr׃"],[5,23,"מַצְדִּיקֵ֥י רָשָׁ֖ע עֵ֣קֶב שֹׁ֑חַד וְ⁠צִדְקַ֥ת צַדִּיקִ֖ים יָסִ֥ירוּ מִמֶּֽ⁠נּוּ׃ס","maẕĕdi̇yqé֥y ráşá֖̌ʻ ʻé֣qeb şò֑̌ẖad wĕ⁠ẕidĕqa֥ţ ẕadi̇yqi֖ym yási֥yrẇ mimėֽ⁠ṅẇ׃s"],[5,24,"לָ⁠כֵן֩ כֶּ⁠אֱכֹ֨ל קַ֜שׁ לְשׁ֣וֹן אֵ֗שׁ וַ⁠חֲשַׁ֤שׁ לֶֽהָבָה֙ יִרְפֶּ֔ה שָׁרְשָׁ⁠ם֙ כַּ⁠מָּ֣ק יִֽהְיֶ֔ה וּ⁠פִרְחָ֖⁠ם כָּ⁠אָבָ֣ק יַעֲלֶ֑ה כִּ֣י מָאֲס֗וּ אֵ֚ת תּוֹרַת֙ יְהוָ֣ה צְבָא֔וֹת וְ⁠אֵ֛ת אִמְרַ֥ת קְדֽוֹשׁ־יִשְׂרָאֵ֖ל נִאֵֽצוּ׃","lá⁠kén֩ kė⁠ʼèkò֨l qa֜ş̌ lĕş֣̌wòn ʼé֗ş̌ wa⁠ẖàşǎ֤ş̌ leֽhábáh֙ yirĕpė֔h şá̌rĕşá̌⁠m֙ kȧ⁠má֣̇q yiֽhĕye֔h ẇ⁠pirĕẖá֖⁠m ká̇⁠ʼábá֣q yaʻàle֑h ki֣̇y máʼàs֗ẇ ʼé֚ţ ţ̇wòraţ֙ yĕhwá֣h ẕĕbáʼ֔wòţ wĕ⁠ʼé֛ţ ʼimĕra֥ţ qĕdֽwòş̌-yişĕ̂ráʼé֖l niʼéֽẕẇ׃"],[5,25,"עַל־כֵּ֡ן חָרָה֩ אַף־יְהוָ֨ה בְּ⁠עַמּ֜⁠וֹ וַ⁠יֵּ֣ט יָד֧⁠וֹ עָלָ֣י⁠ו וַ⁠יַּכֵּ֗⁠הוּ וַֽ⁠יִּרְגְּזוּ֙ הֶֽ⁠הָרִ֔ים וַ⁠תְּהִ֧י נִבְלָתָ֛⁠ם כַּ⁠סּוּחָ֖ה בְּ⁠קֶ֣רֶב חוּצ֑וֹת בְּ⁠כָל־זֹאת֙ לֹא־שָׁ֣ב אַפּ֔⁠וֹ וְ⁠ע֖וֹד יָד֥⁠וֹ נְטוּיָֽה׃","ʻal-ké̇֡n ẖáráh֩ ʼap-yĕhwá֨h bĕ̇⁠ʻaṁ֜⁠wò wa⁠yé֣̇t yád֧⁠wò ʻálá֣y⁠w wa⁠yȧké̇֗⁠hẇ waֽ⁠yi̇rĕgĕ̇zẇ֙ heֽ⁠hári֔ym wa⁠ţĕ̇hi֧y nibĕláţá֛⁠m kȧ⁠ṡẇẖá֖h bĕ̇⁠qe֣reb ẖẇẕ֑wòţ bĕ̇⁠kál-zòʼţ֙ lòʼ-şá֣̌b ʼaṗ֔⁠wò wĕ⁠ʻ֖wòd yád֥⁠wò nĕtẇyáֽh׃"],[5,26,"וְ⁠נָֽשָׂא־נֵ֤ס לַ⁠גּוֹיִם֙ מֵ⁠רָח֔וֹק וְ⁠שָׁ֥רַק ל֖⁠וֹ מִ⁠קְצֵ֣ה הָ⁠אָ֑רֶץ וְ⁠הִנֵּ֥ה מְהֵרָ֖ה קַ֥ל יָבֽוֹא׃","wĕ⁠náֽşá̂ʼ-né֤s la⁠ġwòyim֙ mé⁠ráẖ֔wòq wĕ⁠şá֥̌raq l֖⁠wò mi⁠qĕẕé֣h há⁠ʼá֑reẕ wĕ⁠hiné֥̇h mĕhérá֖h qa֥l yábֽwòʼ׃"],[5,27,"אֵין־עָיֵ֤ף וְ⁠אֵין־כּוֹשֵׁל֙ בּ֔⁠וֹ לֹ֥א יָנ֖וּם וְ⁠לֹ֣א יִישָׁ֑ן וְ⁠לֹ֤א נִפְתַּח֙ אֵז֣וֹר חֲלָצָ֔י⁠ו וְ⁠לֹ֥א נִתַּ֖ק שְׂר֥וֹךְ נְעָלָֽי⁠ו׃","ʼéyn-ʻáyé֤p wĕ⁠ʼéyn-k̇wòşé̌l֙ ḃ֔⁠wò lò֥ʼ yán֖ẇm wĕ⁠lò֣ʼ yiyşá֑̌n wĕ⁠lò֤ʼ nipĕţȧẖ֙ ʼéz֣wòr ẖàláẕá֔y⁠w wĕ⁠lò֥ʼ niţȧ֖q şĕ̂r֥wòkĕ nĕʻáláֽy⁠w׃"],[5,28,"אֲשֶׁ֤ר חִצָּי⁠ו֙ שְׁנוּנִ֔ים וְ⁠כָל־קַשְּׁתֹתָ֖י⁠ו דְּרֻכ֑וֹת פַּרְס֤וֹת סוּסָי⁠ו֙ כַּ⁠צַּ֣ר נֶחְשָׁ֔בוּ וְ⁠גַלְגִּלָּ֖י⁠ו כַּ⁠סּוּפָֽה׃","ʼàşě֤r ẖiẕá̇y⁠w֙ şĕ̌nẇni֔ym wĕ⁠kál-qaşĕ̇̌ţòţá֖y⁠w dĕ̇ruk֑wòţ pȧrĕs֤wòţ sẇsáy⁠w֙ kȧ⁠ẕȧ֣r neẖĕşá̌֔bẇ wĕ⁠galĕgi̇lá֖̇y⁠w kȧ⁠ṡẇpáֽh׃"],[5,29,"שְׁאָגָ֥ה ל֖⁠וֹ כַּ⁠לָּבִ֑יא ו⁠שאג כַּ⁠כְּפִירִ֤ים וְ⁠יִנְהֹם֙ וְ⁠יֹאחֵ֣ז טֶ֔רֶף וְ⁠יַפְלִ֖יט וְ⁠אֵ֥ין מַצִּֽיל׃","şĕ̌ʼágá֥h l֖⁠wò kȧ⁠lá̇bi֑yʼ w⁠şʼg kȧ⁠kĕ̇piyri֤ym wĕ⁠yinĕhòm֙ wĕ⁠yòʼẖé֣z te֔rep wĕ⁠yapĕli֖yt wĕ⁠ʼé֥yn maẕiֽ̇yl׃"],[5,30,"וְ⁠יִנְהֹ֥ם עָלָ֛י⁠ו בַּ⁠יּ֥וֹם הַ⁠ה֖וּא כְּ⁠נַהֲמַת־יָ֑ם וְ⁠נִבַּ֤ט לָ⁠אָ֨רֶץ֙ וְ⁠הִנֵּה־חֹ֔שֶׁךְ צַ֣ר וָ⁠א֔וֹר חָשַׁ֖ךְ בַּ⁠עֲרִיפֶֽי⁠הָ׃פ","wĕ⁠yinĕhò֥m ʻálá֛y⁠w bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ kĕ̇⁠nahàmaţ-yá֑m wĕ⁠nibȧ֤t lá⁠ʼá֨reẕ֙ wĕ⁠hiné̇h-ẖò֔şěkĕ ẕa֣r wá⁠ʼ֔wòr ẖáşǎ֖kĕ bȧ⁠ʻàriypeֽy⁠há׃p"],[6,1,"בִּ⁠שְׁנַת־מוֹת֙ הַ⁠מֶּ֣לֶךְ עֻזִּיָּ֔הוּ וָ⁠אֶרְאֶ֧ה אֶת־אֲדֹנָ֛⁠י יֹשֵׁ֥ב עַל־כִּסֵּ֖א רָ֣ם וְ⁠נִשָּׂ֑א וְ⁠שׁוּלָ֖י⁠ו מְלֵאִ֥ים אֶת־הַ⁠הֵיכָֽל׃","bi̇⁠şĕ̌naţ-mwòţ֙ ha⁠mė֣lekĕ ʻuzi̇yá̇֔hẇ wá⁠ʼerĕʼe֧h ʼeţ-ʼàdòná֛⁠y yòşé֥̌b ʻal-ki̇sé֖̇ʼ rá֣m wĕ⁠nişá֑̇̂ʼ wĕ⁠ş̌ẇlá֖y⁠w mĕléʼi֥ym ʼeţ-ha⁠héykáֽl׃"],[6,2,"שְׂרָפִ֨ים עֹמְדִ֤ים ׀ מִ⁠מַּ֨עַל֙ ל֔⁠וֹ שֵׁ֧שׁ כְּנָפַ֛יִם שֵׁ֥שׁ כְּנָפַ֖יִם לְ⁠אֶחָ֑ד בִּ⁠שְׁתַּ֣יִם ׀ יְכַסֶּ֣ה פָנָ֗י⁠ו וּ⁠בִ⁠שְׁתַּ֛יִם יְכַסֶּ֥ה רַגְלָ֖י⁠ו וּ⁠בִ⁠שְׁתַּ֥יִם יְעוֹפֵֽף׃","şĕ̂rápi֨ym ʻòmĕdi֤ym ׀ mi⁠mȧ֨ʻal֙ l֔⁠wò şé֧̌ş̌ kĕ̇nápa֛yim şé֥̌ş̌ kĕ̇nápa֖yim lĕ⁠ʼeẖá֑d bi̇⁠şĕ̌ţȧ֣yim ׀ yĕkasė֣h páná֗y⁠w ẇ⁠bi⁠şĕ̌ţȧ֛yim yĕkasė֥h ragĕlá֖y⁠w ẇ⁠bi⁠şĕ̌ţȧ֥yim yĕʻwòpéֽp׃"],[6,3,"וְ⁠קָרָ֨א זֶ֤ה אֶל־זֶה֙ וְ⁠אָמַ֔ר קָד֧וֹשׁ ׀ קָד֛וֹשׁ קָד֖וֹשׁ יְהוָ֣ה צְבָא֑וֹת מְלֹ֥א כָל־הָ⁠אָ֖רֶץ כְּבוֹדֽ⁠וֹ׃","wĕ⁠qárá֨ʼ ze֤h ʼel-zeh֙ wĕ⁠ʼáma֔r qád֧wòş̌ ׀ qád֛wòş̌ qád֖wòş̌ yĕhwá֣h ẕĕbáʼ֑wòţ mĕlò֥ʼ kál-há⁠ʼá֖reẕ kĕ̇bwòdֽ⁠wò׃"],[6,4,"וַ⁠יָּנֻ֨עוּ֙ אַמּ֣וֹת הַ⁠סִּפִּ֔ים מִ⁠קּ֖וֹל הַ⁠קּוֹרֵ֑א וְ⁠הַ⁠בַּ֖יִת יִמָּלֵ֥א עָשָֽׁן׃","wa⁠yá̇nu֨ʻẇ֙ ʼaṁ֣wòţ ha⁠si̇pi̇֔ym mi⁠q֖̇wòl ha⁠q̇wòré֑ʼ wĕ⁠ha⁠bȧ֖yiţ yimá̇lé֥ʼ ʻáşáֽ̌n׃"],[6,5,"וָ⁠אֹמַ֞ר אֽוֹי־לִ֣⁠י כִֽי־נִדְמֵ֗יתִי כִּ֣י אִ֤ישׁ טְמֵֽא־שְׂפָתַ֨יִם֙ אָנֹ֔כִי וּ⁠בְ⁠תוֹךְ֙ עַם־טְמֵ֣א שְׂפָתַ֔יִם אָנֹכִ֖י יוֹשֵׁ֑ב כִּ֗י אֶת־הַ⁠מֶּ֛לֶךְ יְהוָ֥ה צְבָא֖וֹת רָא֥וּ עֵינָֽ⁠י׃","wá⁠ʼòma֞r ʼֽwòy-li֣⁠y kiֽy-nidĕmé֗yţiy ki֣̇y ʼi֤yş̌ tĕméֽʼ-şĕ̂páţa֨yim֙ ʼánò֔kiy ẇ⁠bĕ⁠ţwòkĕ֙ ʻam-tĕmé֣ʼ şĕ̂páţa֔yim ʼánòki֖y ywòşé֑̌b ki̇֗y ʼeţ-ha⁠mė֛lekĕ yĕhwá֥h ẕĕbáʼ֖wòţ ráʼ֥ẇ ʻéynáֽ⁠y׃"],[6,6,"וַ⁠יָּ֣עָף אֵלַ֗⁠י אֶחָד֙ מִן־הַ⁠שְּׂרָפִ֔ים וּ⁠בְ⁠יָד֖⁠וֹ רִצְפָּ֑ה בְּ⁠מֶ֨לְקַחַ֔יִם לָקַ֖ח מֵ⁠עַ֥ל הַ⁠מִּזְבֵּֽחַ׃","wa⁠yá֣̇ʻáp ʼéla֗⁠y ʼeẖád֙ min-ha⁠şĕ̇̂rápi֔ym ẇ⁠bĕ⁠yád֖⁠wò riẕĕpá֑̇h bĕ̇⁠me֨lĕqaẖa֔yim láqa֖ẖ mé⁠ʻa֥l ha⁠mi̇zĕbéֽ̇ẖa׃"],[6,7,"וַ⁠יַּגַּ֣ע עַל־פִּ֔⁠י וַ⁠יֹּ֕אמֶר הִנֵּ֛ה נָגַ֥ע זֶ֖ה עַל־שְׂפָתֶ֑י⁠ךָ וְ⁠סָ֣ר עֲוֺנֶ֔⁠ךָ וְ⁠חַטָּאתְ⁠ךָ֖ תְּכֻפָּֽר׃","wa⁠yȧgȧ֣ʻ ʻal-pi̇֔⁠y wa⁠yò̇֕ʼmer hiné֛̇h nága֥ʻ ze֖h ʻal-şĕ̂páţe֑y⁠ká wĕ⁠sá֣r ʻàwֺne֔⁠ká wĕ⁠ẖatá̇ʼţĕ⁠ká֖ ţĕ̇kupáֽ̇r׃"],[6,8,"וָ⁠אֶשְׁמַ֞ע אֶת־ק֤וֹל אֲדֹנָ⁠י֙ אֹמֵ֔ר אֶת־מִ֥י אֶשְׁלַ֖ח וּ⁠מִ֣י יֵֽלֶךְ־לָ֑⁠נוּ וָ⁠אֹמַ֖ר הִנְ⁠נִ֥י שְׁלָחֵֽ⁠נִי׃","wá⁠ʼeşĕ̌ma֞ʻ ʼeţ-q֤wòl ʼàdòná⁠y֙ ʼòmé֔r ʼeţ-mi֥y ʼeşĕ̌la֖ẖ ẇ⁠mi֣y yéֽlekĕ-lá֑⁠nẇ wá⁠ʼòma֖r hinĕ⁠ni֥y şĕ̌láẖéֽ⁠niy׃"],[6,9,"וַ⁠יֹּ֕אמֶר לֵ֥ךְ וְ⁠אָמַרְתָּ֖ לָ⁠עָ֣ם הַ⁠זֶּ֑ה שִׁמְע֤וּ שָׁמ֨וֹעַ֙ וְ⁠אַל־תָּבִ֔ינוּ וּ⁠רְא֥וּ רָא֖וֹ וְ⁠אַל־תֵּדָֽעוּ׃","wa⁠yò̇֕ʼmer lé֥kĕ wĕ⁠ʼámarĕţá֖̇ lá⁠ʻá֣m ha⁠zė֑h şǐmĕʻ֤ẇ şá̌m֨wòʻa֙ wĕ⁠ʼal-ţá̇bi֔ynẇ ẇ⁠rĕʼ֥ẇ ráʼ֖wò wĕ⁠ʼal-ţé̇dáֽʻẇ׃"],[6,10,"הַשְׁמֵן֙ לֵב־הָ⁠עָ֣ם הַ⁠זֶּ֔ה וְ⁠אָזְנָ֥י⁠ו הַכְבֵּ֖ד וְ⁠עֵינָ֣י⁠ו הָשַׁ֑ע פֶּן־יִרְאֶ֨ה בְ⁠עֵינָ֜י⁠ו וּ⁠בְ⁠אָזְנָ֣י⁠ו יִשְׁמָ֗ע וּ⁠לְבָב֥⁠וֹ יָבִ֛ין וָ⁠שָׁ֖ב וְ⁠רָ֥פָא לֽ⁠וֹ׃","haşĕ̌mén֙ léb-há⁠ʻá֣m ha⁠zė֔h wĕ⁠ʼázĕná֥y⁠w hakĕbé֖̇d wĕ⁠ʻéyná֣y⁠w háşǎ֑ʻ pėn-yirĕʼe֨h bĕ⁠ʻéyná֜y⁠w ẇ⁠bĕ⁠ʼázĕná֣y⁠w yişĕ̌má֗ʻ ẇ⁠lĕbáb֥⁠wò yábi֛yn wá⁠şá֖̌b wĕ⁠rá֥páʼ lֽ⁠wò׃"],[6,11,"וָ⁠אֹמַ֕ר עַד־מָתַ֖י אֲדֹנָ֑⁠י וַ⁠יֹּ֡אמֶר עַ֣ד אֲשֶׁר֩ אִם־שָׁא֨וּ עָרִ֜ים מֵ⁠אֵ֣ין יוֹשֵׁ֗ב וּ⁠בָתִּים֙ מֵ⁠אֵ֣ין אָדָ֔ם וְ⁠הָ⁠אֲדָמָ֖ה תִּשָּׁאֶ֥ה שְׁמָמָֽה׃","wá⁠ʼòma֕r ʻad-máţa֖y ʼàdòná֑⁠y wa⁠yò̇֡ʼmer ʻa֣d ʼàşěr֩ ʼim-şá̌ʼ֨ẇ ʻári֜ym mé⁠ʼé֣yn ywòşé̌֗b ẇ⁠báţi̇ym֙ mé⁠ʼé֣yn ʼádá֔m wĕ⁠há⁠ʼàdámá֖h ţi̇şá̇̌ʼe֥h şĕ̌mámáֽh׃"],[6,12,"וְ⁠רִחַ֥ק יְהוָ֖ה אֶת־הָ⁠אָדָ֑ם וְ⁠רַבָּ֥ה הָ⁠עֲזוּבָ֖ה בְּ⁠קֶ֥רֶב הָ⁠אָֽרֶץ׃","wĕ⁠riẖa֥q yĕhwá֖h ʼeţ-há⁠ʼádá֑m wĕ⁠rabá֥̇h há⁠ʻàzẇbá֖h bĕ̇⁠qe֥reb há⁠ʼáֽreẕ׃"],[6,13,"וְ⁠ע֥וֹד בָּ⁠הּ֙ עֲשִׂ֣רִיָּ֔ה וְ⁠שָׁ֖בָה וְ⁠הָיְתָ֣ה לְ⁠בָעֵ֑ר כָּ⁠אֵלָ֣ה וְ⁠כָ⁠אַלּ֗וֹן אֲשֶׁ֤ר בְּ⁠שַׁלֶּ֨כֶת֙ מַצֶּ֣בֶת בָּ֔⁠ם זֶ֥רַע קֹ֖דֶשׁ מַצַּבְתָּֽ⁠הּ׃פ","wĕ⁠ʻ֥wòd bá̇⁠ḣ֙ ʻàşî֣riyá̇֔h wĕ⁠şá֖̌báh wĕ⁠háyĕţá֣h lĕ⁠báʻé֑r ká̇⁠ʼélá֣h wĕ⁠ká⁠ʼal̇֗wòn ʼàşě֤r bĕ̇⁠şǎlė֨keţ֙ maẕė֣beţ bá̇֔⁠m ze֥raʻ qò֖deş̌ maẕȧbĕţáֽ̇⁠ḣ׃p"],[7,1,"וַ⁠יְהִ֡י בִּ⁠ימֵ֣י אָ֠חָז בֶּן־יוֹתָ֨ם בֶּן־עֻזִּיָּ֜הוּ מֶ֣לֶךְ יְהוּדָ֗ה עָלָ֣ה רְצִ֣ין מֶֽלֶךְ־אֲ֠רָם וּ⁠פֶ֨קַח בֶּן־רְמַלְיָ֤הוּ מֶֽלֶךְ־יִשְׂרָאֵל֙ יְר֣וּשָׁלִַ֔ם לַ⁠מִּלְחָמָ֖ה עָלֶ֑י⁠הָ וְ⁠לֹ֥א יָכֹ֖ל לְ⁠הִלָּחֵ֥ם עָלֶֽי⁠הָ׃","wa⁠yĕhi֡y bi̇⁠ymé֣y ʼá֠ẖáz bėn-ywòţá֨m bėn-ʻuzi̇yá̇֜hẇ me֣lekĕ yĕhẇdá֗h ʻálá֣h rĕẕi֣yn meֽlekĕ-ʼà֠rám ẇ⁠pe֨qaẖ bėn-rĕmalĕyá֤hẇ meֽlekĕ-yişĕ̂ráʼél֙ yĕr֣ẇşá̌lia֔m la⁠mi̇lĕẖámá֖h ʻále֑y⁠há wĕ⁠lò֥ʼ yákò֖l lĕ⁠hilá̇ẖé֥m ʻáleֽy⁠há׃"],[7,2,"וַ⁠יֻּגַּ֗ד לְ⁠בֵ֤ית דָּוִד֙ לֵ⁠אמֹ֔ר נָ֥חָֽה אֲרָ֖ם עַל־אֶפְרָ֑יִם וַ⁠יָּ֤נַע לְבָב⁠וֹ֙ וּ⁠לְבַ֣ב עַמּ֔⁠וֹ כְּ⁠נ֥וֹעַ עֲצֵי־יַ֖עַר מִ⁠פְּנֵי־רֽוּחַ׃","wa⁠yu̇gȧ֗d lĕ⁠bé֤yţ dá̇wid֙ lé⁠ʼmò֔r ná֥ẖáֽh ʼàrá֖m ʻal-ʼepĕrá֑yim wa⁠yá֤̇naʻ lĕbáb⁠wò֙ ẇ⁠lĕba֣b ʻaṁ֔⁠wò kĕ̇⁠n֥wòʻa ʻàẕéy-ya֖ʻar mi⁠pĕ̇néy-rֽẇẖa׃"],[7,3,"וַ⁠יֹּ֣אמֶר יְהוָה֮ אֶֽל־יְשַׁעְיָהוּ֒ צֵא־נָא֙ לִ⁠קְרַ֣את אָחָ֔ז אַתָּ֕ה וּ⁠שְׁאָ֖ר יָשׁ֣וּב בְּנֶ֑⁠ךָ אֶל־קְצֵ֗ה תְּעָלַת֙ הַ⁠בְּרֵכָ֣ה הָ⁠עֶלְיוֹנָ֔ה אֶל־מְסִלַּ֖ת שְׂדֵ֥ה כוֹבֵֽס׃","wa⁠yò֣̇ʼmer yĕhwáh֮ ʼeֽl-yĕşǎʻĕyáhẇ֒ ẕéʼ-náʼ֙ li⁠qĕra֣ʼţ ʼáẖá֔z ʼaţá̇֕h ẇ⁠şĕ̌ʼá֖r yáş֣̌ẇb bĕ̇ne֑⁠ká ʼel-qĕẕé֗h ţĕ̇ʻálaţ֙ ha⁠bĕ̇réká֣h há⁠ʻelĕywòná֔h ʼel-mĕsilȧ֖ţ şĕ̂dé֥h kwòbéֽs׃"],[7,4,"וְ⁠אָמַרְתָּ֣ אֵ֠לָי⁠ו הִשָּׁמֵ֨ר וְ⁠הַשְׁקֵ֜ט אַל־תִּירָ֗א וּ⁠לְבָבְ⁠ךָ֙ אַל־יֵרַ֔ךְ מִ⁠שְּׁנֵ֨י זַנְב֧וֹת הָ⁠אוּדִ֛ים הָ⁠עֲשֵׁנִ֖ים הָ⁠אֵ֑לֶּה בָּ⁠חֳרִי־אַ֛ף רְצִ֥ין וַ⁠אֲרָ֖ם וּ⁠בֶן־רְמַלְיָֽהוּ׃","wĕ⁠ʼámarĕţá֣̇ ʼé֠láy⁠w hişá̇̌mé֨r wĕ⁠haşĕ̌qé֜t ʼal-ţi̇yrá֗ʼ ẇ⁠lĕbábĕ⁠ká֙ ʼal-yéra֔kĕ mi⁠şĕ̇̌né֨y zanĕb֧wòţ há⁠ʼẇdi֛ym há⁠ʻàşé̌ni֖ym há⁠ʼé֑lėh bá̇⁠ẖoriy-ʼa֛p rĕẕi֥yn wa⁠ʼàrá֖m ẇ⁠ben-rĕmalĕyáֽhẇ׃"],[7,5,"יַ֗עַן כִּֽי־יָעַ֥ץ עָלֶ֛י⁠ךָ אֲרָ֖ם רָעָ֑ה אֶפְרַ֥יִם וּ⁠בֶן־רְמַלְיָ֖הוּ לֵ⁠אמֹֽר׃","ya֗ʻan kiֽ̇y-yáʻa֥ẕ ʻále֛y⁠ká ʼàrá֖m ráʻá֑h ʼepĕra֥yim ẇ⁠ben-rĕmalĕyá֖hẇ lé⁠ʼmòֽr׃"],[7,6,"נַעֲלֶ֤ה בִֽ⁠יהוּדָה֙ וּ⁠נְקִיצֶ֔⁠נָּה וְ⁠נַבְקִעֶ֖⁠נָּה אֵלֵ֑י⁠נוּ וְ⁠נַמְלִ֥יךְ מֶ֨לֶךְ֙ בְּ⁠תוֹכָ֔⁠הּ אֵ֖ת בֶּן־טָֽבְאַֽל׃ס","naʻàle֤h biֽ⁠yhẇdáh֙ ẇ⁠nĕqiyẕe֔⁠ná̇h wĕ⁠nabĕqiʻe֖⁠ná̇h ʼélé֑y⁠nẇ wĕ⁠namĕli֥ykĕ me֨lekĕ֙ bĕ̇⁠ţwòká֔⁠ḣ ʼé֖ţ bėn-táֽbĕʼaֽl׃s"],[7,7,"כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה לֹ֥א תָק֖וּם וְ⁠לֹ֥א תִֽהְיֶֽה׃","kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h lò֥ʼ ţáq֖ẇm wĕ⁠lò֥ʼ ţiֽhĕyeֽh׃"],[7,8,"כִּ֣י רֹ֤אשׁ אֲרָם֙ דַּמֶּ֔שֶׂק וְ⁠רֹ֥אשׁ דַּמֶּ֖שֶׂק רְצִ֑ין וּ⁠בְ⁠ע֗וֹד שִׁשִּׁ֤ים וְ⁠חָמֵשׁ֙ שָׁנָ֔ה יֵחַ֥ת אֶפְרַ֖יִם מֵ⁠עָֽם׃","ki֣̇y rò֤ʼş̌ ʼàrám֙ dȧmė֔şêq wĕ⁠rò֥ʼş̌ dȧmė֖şêq rĕẕi֑yn ẇ⁠bĕ⁠ʻ֗wòd şǐşi֤̇̌ym wĕ⁠ẖáméş̌֙ şá̌ná֔h yéẖa֥ţ ʼepĕra֖yim mé⁠ʻáֽm׃"],[7,9,"וְ⁠רֹ֤אשׁ אֶפְרַ֨יִם֙ שֹׁמְר֔וֹן וְ⁠רֹ֥אשׁ שֹׁמְר֖וֹן בֶּן־רְמַלְיָ֑הוּ אִ֚ם לֹ֣א תַאֲמִ֔ינוּ כִּ֖י לֹ֥א תֵאָמֵֽנוּ׃ס","wĕ⁠rò֤ʼş̌ ʼepĕra֨yim֙ şò̌mĕr֔wòn wĕ⁠rò֥ʼş̌ şò̌mĕr֖wòn bėn-rĕmalĕyá֑hẇ ʼi֚m lò֣ʼ ţaʼàmi֔ynẇ ki֖̇y lò֥ʼ ţéʼáméֽnẇ׃s"],[7,10,"וַ⁠יּ֣וֹסֶף יְהוָ֔ה דַּבֵּ֥ר אֶל־אָחָ֖ז לֵ⁠אמֹֽר׃","wa⁠ẏ֣wòsep yĕhwá֔h dȧbé֥̇r ʼel-ʼáẖá֖z lé⁠ʼmòֽr׃"],[7,11,"שְׁאַל־לְ⁠ךָ֣ א֔וֹת מֵ⁠עִ֖ם יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ הַעְמֵ֣ק שְׁאָ֔לָה א֖וֹ הַגְבֵּ֥הַּ לְ⁠מָֽעְלָ⁠ה׃","şĕ̌ʼal-lĕ⁠ká֣ ʼ֔wòţ mé⁠ʻi֖m yĕhwá֣h ʼèlòhe֑y⁠ká haʻĕmé֣q şĕ̌ʼá֔láh ʼ֖wò hagĕbé֥̇hȧ lĕ⁠máֽʻĕlá⁠h׃"],[7,12,"וַ⁠יֹּ֖אמֶר אָחָ֑ז לֹא־אֶשְׁאַ֥ל וְ⁠לֹֽא־אֲנַסֶּ֖ה אֶת־יְהוָֽה׃","wa⁠yò֖̇ʼmer ʼáẖá֑z lòʼ-ʼeşĕ̌ʼa֥l wĕ⁠lòֽʼ-ʼànasė֖h ʼeţ-yĕhwáֽh׃"],[7,13,"וַ⁠יֹּ֕אמֶר שִׁמְעוּ־נָ֖א בֵּ֣ית דָּוִ֑ד הַ⁠מְעַ֤ט מִ⁠כֶּם֙ הַלְא֣וֹת אֲנָשִׁ֔ים כִּ֥י תַלְא֖וּ גַּ֥ם אֶת־אֱלֹהָֽ⁠י׃","wa⁠yò̇֕ʼmer şǐmĕʻẇ-ná֖ʼ bé֣̇yţ dá̇wi֑d ha⁠mĕʻa֤t mi⁠kėm֙ halĕʼ֣wòţ ʼànáşǐ֔ym ki֥̇y ţalĕʼ֖ẇ gȧ֥m ʼeţ-ʼèlòháֽ⁠y׃"],[7,14,"לָ֠⁠כֵן יִתֵּ֨ן אֲדֹנָ֥⁠י ה֛וּא לָ⁠כֶ֖ם א֑וֹת הִנֵּ֣ה הָ⁠עַלְמָ֗ה הָרָה֙ וְ⁠יֹלֶ֣דֶת בֵּ֔ן וְ⁠קָרָ֥את שְׁמ֖⁠וֹ עִמָּ֥נוּ אֵֽל׃","lá֠⁠kén yiţé̇֨n ʼàdòná֥⁠y h֛ẇʼ lá⁠ke֖m ʼ֑wòţ hiné֣̇h há⁠ʻalĕmá֗h háráh֙ wĕ⁠yòle֣deţ bé̇֔n wĕ⁠qárá֥ʼţ şĕ̌m֖⁠wò ʻimá֥̇nẇ ʼéֽl׃"],[7,15,"חֶמְאָ֥ה וּ⁠דְבַ֖שׁ יֹאכֵ֑ל לְ⁠דַעְתּ֛⁠וֹ מָא֥וֹס בָּ⁠רָ֖ע וּ⁠בָח֥וֹר בַּ⁠טּֽוֹב׃","ẖemĕʼá֥h ẇ⁠dĕba֖ş̌ yòʼké֑l lĕ⁠daʻĕţ֛̇⁠wò máʼ֥wòs bá̇⁠rá֖ʻ ẇ⁠báẖ֥wòr bȧ⁠ṫֽwòb׃"],[7,16,"כִּ֠י בְּ⁠טֶ֨רֶם יֵדַ֥ע הַ⁠נַּ֛עַר מָאֹ֥ס בָּ⁠רָ֖ע וּ⁠בָחֹ֣ר בַּ⁠טּ֑וֹב תֵּעָזֵ֤ב הָ⁠אֲדָמָה֙ אֲשֶׁ֣ר אַתָּ֣ה קָ֔ץ מִ⁠פְּנֵ֖י שְׁנֵ֥י מְלָכֶֽי⁠הָ׃","ki̇֠y bĕ̇⁠te֨rem yéda֥ʻ ha⁠nȧ֛ʻar máʼò֥s bá̇⁠rá֖ʻ ẇ⁠báẖò֣r bȧ⁠ṫ֑wòb ţé̇ʻázé֤b há⁠ʼàdámáh֙ ʼàşě֣r ʼaţá֣̇h qá֔ẕ mi⁠pĕ̇né֖y şĕ̌né֥y mĕlákeֽy⁠há׃"],[7,17,"יָבִ֨יא יְהוָ֜ה עָלֶ֗י⁠ךָ וְ⁠עַֽל־עַמְּ⁠ךָ֮ וְ⁠עַל־בֵּ֣ית אָבִי⁠ךָ֒ יָמִים֙ אֲשֶׁ֣ר לֹא־בָ֔אוּ לְ⁠מִ⁠יּ֥וֹם סוּר־אֶפְרַ֖יִם מֵ⁠עַ֣ל יְהוּדָ֑ה אֵ֖ת מֶ֥לֶךְ אַשּֽׁוּר׃פ","yábi֨yʼ yĕhwá֜h ʻále֗y⁠ká wĕ⁠ʻaֽl-ʻamĕ̇⁠ká֮ wĕ⁠ʻal-bé֣̇yţ ʼábiy⁠ká֒ yámiym֙ ʼàşě֣r lòʼ-bá֔ʼẇ lĕ⁠mi⁠ẏ֥wòm sẇr-ʼepĕra֖yim mé⁠ʻa֣l yĕhẇdá֑h ʼé֖ţ me֥lekĕ ʼaşֽ̇̌ẇr׃p"],[7,18,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִשְׁרֹ֤ק יְהוָה֙ לַ⁠זְּב֔וּב אֲשֶׁ֥ר בִּ⁠קְצֵ֖ה יְאֹרֵ֣י מִצְרָ֑יִם וְ⁠לַ֨⁠דְּבוֹרָ֔ה אֲשֶׁ֖ר בְּ⁠אֶ֥רֶץ אַשּֽׁוּר׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yişĕ̌rò֤q yĕhwáh֙ la⁠zĕ̇b֔ẇb ʼàşě֥r bi̇⁠qĕẕé֖h yĕʼòré֣y miẕĕrá֑yim wĕ⁠la֨⁠dĕ̇bwòrá֔h ʼàşě֖r bĕ̇⁠ʼe֥reẕ ʼaşֽ̇̌ẇr׃"],[7,19,"וּ⁠בָ֨אוּ וְ⁠נָח֤וּ כֻלָּ⁠ם֙ בְּ⁠נַחֲלֵ֣י הַ⁠בַּתּ֔וֹת וּ⁠בִ⁠נְקִיקֵ֖י הַ⁠סְּלָעִ֑ים וּ⁠בְ⁠כֹל֙ הַ⁠נַּ֣עֲצוּצִ֔ים וּ⁠בְ⁠כֹ֖ל הַ⁠נַּהֲלֹלִֽים׃","ẇ⁠bá֨ʼẇ wĕ⁠náẖ֤ẇ kulá̇⁠m֙ bĕ̇⁠naẖàlé֣y ha⁠bȧţ̇֔wòţ ẇ⁠bi⁠nĕqiyqé֖y ha⁠sĕ̇láʻi֑ym ẇ⁠bĕ⁠kòl֙ ha⁠nȧ֣ʻàẕẇẕi֔ym ẇ⁠bĕ⁠kò֖l ha⁠nȧhàlòliֽym׃"],[7,20,"בַּ⁠יּ֣וֹם הַ⁠ה֡וּא יְגַלַּ֣ח אֲדֹנָ⁠י֩ בְּ⁠תַ֨עַר הַ⁠שְּׂכִירָ֜ה בְּ⁠עֶבְרֵ֤י נָהָר֙ בְּ⁠מֶ֣לֶךְ אַשּׁ֔וּר אֶת־הָ⁠רֹ֖אשׁ וְ⁠שַׂ֣עַר הָ⁠רַגְלָ֑יִם וְ⁠גַ֥ם אֶת־הַ⁠זָּקָ֖ן תִּסְפֶּֽה׃ס","bȧ⁠ẏ֣wòm ha⁠h֡ẇʼ yĕgalȧ֣ẖ ʼàdòná⁠y֩ bĕ̇⁠ţa֨ʻar ha⁠şĕ̇̂kiyrá֜h bĕ̇⁠ʻebĕré֤y náhár֙ bĕ̇⁠me֣lekĕ ʼaş̇̌֔ẇr ʼeţ-há⁠rò֖ʼş̌ wĕ⁠şâ֣ʻar há⁠ragĕlá֑yim wĕ⁠ga֥m ʼeţ-ha⁠zá̇qá֖n ţi̇sĕpėֽh׃s"],[7,21,"וְ⁠הָיָ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא יְחַיֶּה־אִ֛ישׁ עֶגְלַ֥ת בָּקָ֖ר וּ⁠שְׁתֵּי־צֹֽאן׃","wĕ⁠háyá֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ yĕẖayėh-ʼi֛yş̌ ʻegĕla֥ţ bá̇qá֖r ẇ⁠şĕ̌ţé̇y-ẕòֽʼn׃"],[7,22,"וְ⁠הָיָ֗ה מֵ⁠רֹ֛ב עֲשׂ֥וֹת חָלָ֖ב יֹאכַ֣ל חֶמְאָ֑ה כִּֽי־חֶמְאָ֤ה וּ⁠דְבַשׁ֙ יֹאכֵ֔ל כָּל־הַ⁠נּוֹתָ֖ר בְּ⁠קֶ֥רֶב הָ⁠אָֽרֶץ׃","wĕ⁠háyá֗h mé⁠rò֛b ʻàş֥̂wòţ ẖálá֖b yòʼka֣l ẖemĕʼá֑h kiֽ̇y-ẖemĕʼá֤h ẇ⁠dĕbaş̌֙ yòʼké֔l ká̇l-ha⁠ṅwòţá֖r bĕ̇⁠qe֥reb há⁠ʼáֽreẕ׃"],[7,23,"וְ⁠הָיָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא יִֽהְיֶ֣ה כָל־מָק֗וֹם אֲשֶׁ֧ר יִֽהְיֶה־שָּׁ֛ם אֶ֥לֶף גֶּ֖פֶן בְּ⁠אֶ֣לֶף כָּ֑סֶף לַ⁠שָּׁמִ֥יר וְ⁠לַ⁠שַּׁ֖יִת יִֽהְיֶֽה׃","wĕ⁠háyáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ yiֽhĕye֣h kál-máq֗wòm ʼàşě֧r yiֽhĕyeh-şá֛̇̌m ʼe֥lep gė֖pen bĕ̇⁠ʼe֣lep ká֑̇sep la⁠şá̇̌mi֥yr wĕ⁠la⁠şȧ֖̌yiţ yiֽhĕyeֽh׃"],[7,24,"בַּ⁠חִצִּ֥ים וּ⁠בַ⁠קֶּ֖שֶׁת יָ֣בוֹא שָׁ֑מָּ⁠ה כִּי־שָׁמִ֥יר וָ⁠שַׁ֖יִת תִּֽהְיֶ֥ה כָל־הָ⁠אָֽרֶץ׃","bȧ⁠ẖiẕi֥̇ym ẇ⁠ba⁠qė֖şěţ yá֣bwòʼ şá֑̌má̇⁠h ki̇y-şá̌mi֥yr wá⁠şǎ֖yiţ ţiֽ̇hĕye֥h kál-há⁠ʼáֽreẕ׃"],[7,25,"וְ⁠כֹ֣ל הֶ⁠הָרִ֗ים אֲשֶׁ֤ר בַּ⁠מַּעְדֵּר֙ יֵעָ֣דֵר֔וּ⁠ן לֹֽא־תָב֣וֹא שָׁ֔מָּ⁠ה יִרְאַ֖ת שָׁמִ֣יר וָ⁠שָׁ֑יִת וְ⁠הָיָה֙ לְ⁠מִשְׁלַ֣ח שׁ֔וֹר וּ⁠לְ⁠מִרְמַ֖ס שֶֽׂה׃פ","wĕ⁠kò֣l he⁠hári֗ym ʼàşě֤r bȧ⁠mȧʻĕdé̇r֙ yéʻá֣dér֔ẇ⁠n lòֽʼ-ţáb֣wòʼ şá̌֔má̇⁠h yirĕʼa֖ţ şá̌mi֣yr wá⁠şá֑̌yiţ wĕ⁠háyáh֙ lĕ⁠mişĕ̌la֣ẖ ş̌֔wòr ẇ⁠lĕ⁠mirĕma֖s şêֽh׃p"],[8,1,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלַ֔⁠י קַח־לְ⁠ךָ֖ גִּלָּי֣וֹן גָּד֑וֹל וּ⁠כְתֹ֤ב עָלָי⁠ו֙ בְּ⁠חֶ֣רֶט אֱנ֔וֹשׁ לְ⁠מַהֵ֥ר שָׁלָ֖ל חָ֥שׁ בַּֽז׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼéla֔⁠y qaẖ-lĕ⁠ká֖ gi̇lá̇y֣wòn gá̇d֑wòl ẇ⁠kĕţò֤b ʻáláy⁠w֙ bĕ̇⁠ẖe֣ret ʼèn֔wòş̌ lĕ⁠mahé֥r şá̌lá֖l ẖá֥ş̌ bȧֽz׃"],[8,2,"וְ⁠אָעִ֣ידָה לִּ֔⁠י עֵדִ֖ים נֶאֱמָנִ֑ים אֵ֚ת אוּרִיָּ֣ה הַ⁠כֹּהֵ֔ן וְ⁠אֶת־זְכַרְיָ֖הוּ בֶּ֥ן יְבֶרֶכְיָֽהוּ׃","wĕ⁠ʼáʻi֣ydáh li̇֔⁠y ʻédi֖ym neʼèmáni֑ym ʼé֚ţ ʼẇriyá֣̇h ha⁠kò̇hé֔n wĕ⁠ʼeţ-zĕkarĕyá֖hẇ bė֥n yĕberekĕyáֽhẇ׃"],[8,3,"וָ⁠אֶקְרַב֙ אֶל־הַ⁠נְּבִיאָ֔ה וַ⁠תַּ֖הַר וַ⁠תֵּ֣לֶד בֵּ֑ן וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלַ֔⁠י קְרָ֣א שְׁמ֔⁠וֹ מַהֵ֥ר שָׁלָ֖ל חָ֥שׁ בַּֽז׃","wá⁠ʼeqĕrab֙ ʼel-ha⁠nĕ̇biyʼá֔h wa⁠ţȧ֖har wa⁠ţé֣̇led bé֑̇n wa⁠yò֤̇ʼmer yĕhwáh֙ ʼéla֔⁠y qĕrá֣ʼ şĕ̌m֔⁠wò mahé֥r şá̌lá֖l ẖá֥ş̌ bȧֽz׃"],[8,4,"כִּ֗י בְּ⁠טֶ֨רֶם֙ יֵדַ֣ע הַ⁠נַּ֔עַר קְרֹ֖א אָבִ֣⁠י וְ⁠אִמִּ֑⁠י יִשָּׂ֣א ׀ אֶת־חֵ֣יל דַּמֶּ֗שֶׂק וְ⁠אֵת֙ שְׁלַ֣ל שֹׁמְר֔וֹן לִ⁠פְנֵ֖י מֶ֥לֶךְ אַשּֽׁוּר׃ס","ki̇֗y bĕ̇⁠te֨rem֙ yéda֣ʻ ha⁠nȧ֔ʻar qĕrò֖ʼ ʼábi֣⁠y wĕ⁠ʼimi֑̇⁠y yişá֣̇̂ʼ ׀ ʼeţ-ẖé֣yl dȧmė֗şêq wĕ⁠ʼéţ֙ şĕ̌la֣l şò̌mĕr֔wòn li⁠pĕné֖y me֥lekĕ ʼaşֽ̇̌ẇr׃s"],[8,5,"וַ⁠יֹּ֣סֶף יְהוָ֔ה דַּבֵּ֥ר אֵלַ֛⁠י ע֖וֹד לֵ⁠אמֹֽר׃","wa⁠yò֣̇sep yĕhwá֔h dȧbé֥̇r ʼéla֛⁠y ʻ֖wòd lé⁠ʼmòֽr׃"],[8,6,"יַ֗עַן כִּ֤י מָאַס֙ הָ⁠עָ֣ם הַ⁠זֶּ֔ה אֵ֚ת מֵ֣י הַ⁠שִּׁלֹ֔חַ הַ⁠הֹלְכִ֖ים לְ⁠אַ֑ט וּ⁠מְשׂ֥וֹשׂ אֶת־רְצִ֖ין וּ⁠בֶן־רְמַלְיָֽהוּ׃","ya֗ʻan ki֤̇y máʼas֙ há⁠ʻá֣m ha⁠zė֔h ʼé֚ţ mé֣y ha⁠şi̇̌lò֔ẖa ha⁠hòlĕki֖ym lĕ⁠ʼa֑t ẇ⁠mĕş֥̂wòş̂ ʼeţ-rĕẕi֖yn ẇ⁠ben-rĕmalĕyáֽhẇ׃"],[8,7,"וְ⁠לָ⁠כֵ֡ן הִנֵּ֣ה אֲדֹנָ⁠י֩ מַעֲלֶ֨ה עֲלֵי⁠הֶ֜ם אֶת־מֵ֣י הַ⁠נָּהָ֗ר הָ⁠עֲצוּמִים֙ וְ⁠הָ֣⁠רַבִּ֔ים אֶת־מֶ֥לֶךְ אַשּׁ֖וּר וְ⁠אֶת־כָּל־כְּבוֹד֑⁠וֹ וְ⁠עָלָה֙ עַל־כָּל־אֲפִיקָ֔י⁠ו וְ⁠הָלַ֖ךְ עַל־כָּל־גְּדוֹתָֽי⁠ו׃","wĕ⁠lá⁠ké֡n hiné֣̇h ʼàdòná⁠y֩ maʻàle֨h ʻàléy⁠he֜m ʼeţ-mé֣y ha⁠ná̇há֗r há⁠ʻàẕẇmiym֙ wĕ⁠há֣⁠rabi̇֔ym ʼeţ-me֥lekĕ ʼaş֖̇̌ẇr wĕ⁠ʼeţ-ká̇l-kĕ̇bwòd֑⁠wò wĕ⁠ʻáláh֙ ʻal-ká̇l-ʼàpiyqá֔y⁠w wĕ⁠hála֖kĕ ʻal-ká̇l-gĕ̇dwòţáֽy⁠w׃"],[8,8,"וְ⁠חָלַ֤ף בִּֽ⁠יהוּדָה֙ שָׁטַ֣ף וְ⁠עָבַ֔ר עַד־צַוָּ֖אר יַגִּ֑יעַ וְ⁠הָיָה֙ מֻטּ֣וֹת כְּנָפָ֔י⁠ו מְלֹ֥א רֹֽחַב־אַרְצְ⁠ךָ֖ עִמָּ֥נוּ אֵֽל׃ס","wĕ⁠ẖála֤p biֽ̇⁠yhẇdáh֙ şá̌ta֣p wĕ⁠ʻába֔r ʻad-ẕawá֖̇ʼr yagi֑̇yʻa wĕ⁠háyáh֙ muṫ֣wòţ kĕ̇nápá֔y⁠w mĕlò֥ʼ ròֽẖab-ʼarĕẕĕ⁠ká֖ ʻimá֥̇nẇ ʼéֽl׃s"],[8,9,"רֹ֤עוּ עַמִּים֙ וָ⁠חֹ֔תּוּ וְ⁠הַֽאֲזִ֔ינוּ כֹּ֖ל מֶרְחַקֵּי־אָ֑רֶץ הִתְאַזְּר֣וּ וָ⁠חֹ֔תּוּ הִֽתְאַזְּר֖וּ וָ⁠חֹֽתּוּ׃","rò֤ʻẇ ʻami̇ym֙ wá⁠ẖò֔ţ̇ẇ wĕ⁠haֽʼàzi֔ynẇ kò֖̇l merĕẖaqé̇y-ʼá֑reẕ hiţĕʼazĕ̇r֣ẇ wá⁠ẖò֔ţ̇ẇ hiֽţĕʼazĕ̇r֖ẇ wá⁠ẖòֽţ̇ẇ׃"],[8,10,"עֻ֥צוּ עֵצָ֖ה וְ⁠תֻפָ֑ר דַּבְּר֤וּ דָבָר֙ וְ⁠לֹ֣א יָק֔וּם כִּ֥י עִמָּ֖⁠נוּ אֵֽל׃ס","ʻu֥ẕẇ ʻéẕá֖h wĕ⁠ţupá֑r dȧbĕ̇r֤ẇ dábár֙ wĕ⁠lò֣ʼ yáq֔ẇm ki֥̇y ʻimá֖̇⁠nẇ ʼéֽl׃s"],[8,11,"כִּי֩ כֹ֨ה אָמַ֧ר יְהוָ֛ה אֵלַ֖⁠י כְּ⁠חֶזְקַ֣ת הַ⁠יָּ֑ד וְ⁠יִסְּרֵ֕⁠נִי מִ⁠לֶּ֛כֶת בְּ⁠דֶ֥רֶךְ הָֽ⁠עָם־הַ⁠זֶּ֖ה לֵ⁠אמֹֽר׃","ki̇y֩ kò֨h ʼáma֧r yĕhwá֛h ʼéla֖⁠y kĕ̇⁠ẖezĕqa֣ţ ha⁠yá֑̇d wĕ⁠yisĕ̇ré֕⁠niy mi⁠lė֛keţ bĕ̇⁠de֥rekĕ háֽ⁠ʻám-ha⁠zė֖h lé⁠ʼmòֽr׃"],[8,12,"לֹא־תֹאמְר֣וּ⁠ן קֶ֔שֶׁר לְ⁠כֹ֧ל אֲשֶׁר־יֹאמַ֛ר הָ⁠עָ֥ם הַ⁠זֶּ֖ה קָ֑שֶׁר וְ⁠אֶת־מוֹרָא֥⁠וֹ לֹֽא־תִֽירְא֖וּ וְ⁠לֹ֥א תַעֲרִֽיצוּ׃","lòʼ-ţòʼmĕr֣ẇ⁠n qe֔şěr lĕ⁠kò֧l ʼàşěr-yòʼma֛r há⁠ʻá֥m ha⁠zė֖h qá֑şěr wĕ⁠ʼeţ-mwòráʼ֥⁠wò lòֽʼ-ţiֽyrĕʼ֖ẇ wĕ⁠lò֥ʼ ţaʻàriֽyẕẇ׃"],[8,13,"אֶת־יְהוָ֥ה צְבָא֖וֹת אֹת֣⁠וֹ תַקְדִּ֑ישׁוּ וְ⁠ה֥וּא מוֹרַאֲ⁠כֶ֖ם וְ⁠ה֥וּא מַֽעֲרִֽצְ⁠כֶֽם׃","ʼeţ-yĕhwá֥h ẕĕbáʼ֖wòţ ʼòţ֣⁠wò ţaqĕdi֑̇yş̌ẇ wĕ⁠h֥ẇʼ mwòraʼà⁠ke֖m wĕ⁠h֥ẇʼ mֽaʻàriֽẕĕ⁠keֽm׃"],[8,14,"וְ⁠הָיָ֖ה לְ⁠מִקְדָּ֑שׁ וּ⁠לְ⁠אֶ֣בֶן נֶ֠גֶף וּ⁠לְ⁠צ֨וּר מִכְשׁ֜וֹל לִ⁠שְׁנֵ֨י בָתֵּ֤י יִשְׂרָאֵל֙ לְ⁠פַ֣ח וּ⁠לְ⁠מוֹקֵ֔שׁ לְ⁠יוֹשֵׁ֖ב יְרוּשָׁלִָֽם׃","wĕ⁠háyá֖h lĕ⁠miqĕdá֑̇ş̌ ẇ⁠lĕ⁠ʼe֣ben ne֠gep ẇ⁠lĕ⁠ẕ֨ẇr mikĕş̌֜wòl li⁠şĕ̌né֨y báţé֤̇y yişĕ̂ráʼél֙ lĕ⁠pa֣ẖ ẇ⁠lĕ⁠mwòqé֔ş̌ lĕ⁠ywòşé֖̌b yĕrẇşá̌liáֽm׃"],[8,15,"וְ⁠כָ֥שְׁלוּ בָ֖⁠ם רַבִּ֑ים וְ⁠נָפְל֣וּ וְ⁠נִשְׁבָּ֔רוּ וְ⁠נוֹקְשׁ֖וּ וְ⁠נִלְכָּֽדוּ׃ס","wĕ⁠ká֥şĕ̌lẇ bá֖⁠m rabi֑̇ym wĕ⁠nápĕl֣ẇ wĕ⁠nişĕ̌bá̇֔rẇ wĕ⁠nwòqĕş֖̌ẇ wĕ⁠nilĕkáֽ̇dẇ׃s"],[8,16,"צ֖וֹר תְּעוּדָ֑ה חֲת֥וֹם תּוֹרָ֖ה בְּ⁠לִמֻּדָֽ⁠י׃","ẕ֖wòr ţĕ̇ʻẇdá֑h ẖàţ֥wòm ţ̇wòrá֖h bĕ̇⁠limu̇dáֽ⁠y׃"],[8,17,"וְ⁠חִכִּ֨יתִי֙ לַ⁠יהוָ֔ה הַ⁠מַּסְתִּ֥יר פָּנָ֖י⁠ו מִ⁠בֵּ֣ית יַעֲקֹ֑ב וְ⁠קִוֵּ֖יתִֽי־לֽ⁠וֹ׃","wĕ⁠ẖiki̇֨yţiy֙ la⁠yhwá֔h ha⁠mȧsĕţi֥̇yr pá̇ná֖y⁠w mi⁠bé֣̇yţ yaʻàqò֑b wĕ⁠qiwé֖̇yţiֽy-lֽ⁠wò׃"],[8,18,"הִנֵּ֣ה אָנֹכִ֗י וְ⁠הַ⁠יְלָדִים֙ אֲשֶׁ֣ר נָֽתַן־לִ֣⁠י יְהוָ֔ה לְ⁠אֹת֥וֹת וּ⁠לְ⁠מוֹפְתִ֖ים בְּ⁠יִשְׂרָאֵ֑ל מֵ⁠עִם֙ יְהוָ֣ה צְבָא֔וֹת הַ⁠שֹּׁכֵ֖ן בְּ⁠הַ֥ר צִיּֽוֹן׃ס","hiné֣̇h ʼánòki֗y wĕ⁠ha⁠yĕládiym֙ ʼàşě֣r náֽţan-li֣⁠y yĕhwá֔h lĕ⁠ʼòţ֥wòţ ẇ⁠lĕ⁠mwòpĕţi֖ym bĕ̇⁠yişĕ̂ráʼé֑l mé⁠ʻim֙ yĕhwá֣h ẕĕbáʼ֔wòţ ha⁠şò̇̌ké֖n bĕ̇⁠ha֥r ẕiẏֽwòn׃s"],[8,19,"וְ⁠כִֽי־יֹאמְר֣וּ אֲלֵי⁠כֶ֗ם דִּרְשׁ֤וּ אֶל־הָ⁠אֹבוֹת֙ וְ⁠אֶל־הַ⁠יִּדְּעֹנִ֔ים הַֽ⁠מְצַפְצְפִ֖ים וְ⁠הַ⁠מַּהְגִּ֑ים הֲ⁠לוֹא־עַם֙ אֶל־אֱלֹהָ֣י⁠ו יִדְרֹ֔שׁ בְּעַ֥ד הַ⁠חַיִּ֖ים אֶל־הַ⁠מֵּתִֽים׃","wĕ⁠kiֽy-yòʼmĕr֣ẇ ʼàléy⁠ke֗m di̇rĕş֤̌ẇ ʼel-há⁠ʼòbwòţ֙ wĕ⁠ʼel-ha⁠yi̇dĕ̇ʻòni֔ym haֽ⁠mĕẕapĕẕĕpi֖ym wĕ⁠ha⁠mȧhĕgi֑̇ym hà⁠lwòʼ-ʻam֙ ʼel-ʼèlòhá֣y⁠w yidĕrò֔ş̌ bĕ̇ʻa֥d ha⁠ẖayi֖̇ym ʼel-ha⁠mé̇ţiֽym׃"],[8,20,"לְ⁠תוֹרָ֖ה וְ⁠לִ⁠תְעוּדָ֑ה אִם־לֹ֤א יֹֽאמְרוּ֙ כַּ⁠דָּבָ֣ר הַ⁠זֶּ֔ה אֲשֶׁ֥ר אֵֽין־ל֖⁠וֹ שָֽׁחַר׃","lĕ⁠ţwòrá֖h wĕ⁠li⁠ţĕʻẇdá֑h ʼim-lò֤ʼ yòֽʼmĕrẇ֙ kȧ⁠dá̇bá֣r ha⁠zė֔h ʼàşě֥r ʼéֽyn-l֖⁠wò şáֽ̌ẖar׃"],[8,21,"וְ⁠עָ֥בַר בָּ֖⁠הּ נִקְשֶׁ֣ה וְ⁠רָעֵ֑ב וְ⁠הָיָ֨ה כִֽי־יִרְעַ֜ב וְ⁠הִתְקַצַּ֗ף וְ⁠קִלֵּ֧ל בְּ⁠מַלְכּ֛⁠וֹ וּ⁠בֵ⁠אלֹהָ֖י⁠ו וּ⁠פָנָ֥ה לְ⁠מָֽעְלָ⁠ה׃","wĕ⁠ʻá֥bar bá֖̇⁠ḣ niqĕşě֣h wĕ⁠ráʻé֑b wĕ⁠háyá֨h kiֽy-yirĕʻa֜b wĕ⁠hiţĕqaẕȧ֗p wĕ⁠qilé֧̇l bĕ̇⁠malĕk֛̇⁠wò ẇ⁠bé⁠ʼlòhá֖y⁠w ẇ⁠páná֥h lĕ⁠máֽʻĕlá⁠h׃"],[8,22,"וְ⁠אֶל־אֶ֖רֶץ יַבִּ֑יט וְ⁠הִנֵּ֨ה צָרָ֤ה וַ⁠חֲשֵׁכָה֙ מְע֣וּף צוּקָ֔ה וַ⁠אֲפֵלָ֖ה מְנֻדָּֽח׃","wĕ⁠ʼel-ʼe֖reẕ yabi֑̇yt wĕ⁠hiné̇֨h ẕárá֤h wa⁠ẖàşé̌káh֙ mĕʻ֣ẇp ẕẇqá֔h wa⁠ʼàpélá֖h mĕnudáֽ̇ẖ׃"],[9,1,"כִּ֣י לֹ֣א מוּעָף֮ לַ⁠אֲשֶׁ֣ר מוּצָ֣ק לָ⁠הּ֒ כָּ⁠עֵ֣ת הָ⁠רִאשׁ֗וֹן הֵקַ֞ל אַ֤רְצָ⁠ה זְבֻלוּן֙ וְ⁠אַ֣רְצָ⁠ה נַפְתָּלִ֔י וְ⁠הָ⁠אַחֲר֖וֹן הִכְבִּ֑יד דֶּ֤רֶךְ הַ⁠יָּם֙ עֵ֣בֶר הַ⁠יַּרְדֵּ֔ן גְּלִ֖יל הַ⁠גּוֹיִֽם׃","ki֣̇y lò֣ʼ mẇʻáp֮ la⁠ʼàşě֣r mẇẕá֣q lá⁠ḣ֒ ká̇⁠ʻé֣ţ há⁠riʼş̌֗wòn héqa֞l ʼa֤rĕẕá⁠h zĕbulẇn֙ wĕ⁠ʼa֣rĕẕá⁠h napĕţá̇li֔y wĕ⁠há⁠ʼaẖàr֖wòn hikĕbi֑̇yd dė֤rekĕ ha⁠yá̇m֙ ʻé֣ber ha⁠yȧrĕdé̇֔n gĕ̇li֖yl ha⁠ġwòyiֽm׃"],[9,2,"הָ⁠עָם֙ הַ⁠הֹלְכִ֣ים בַּ⁠חֹ֔שֶׁךְ רָא֖וּ א֣וֹר גָּד֑וֹל יֹשְׁבֵי֙ בְּ⁠אֶ֣רֶץ צַלְמָ֔וֶת א֖וֹר נָגַ֥הּ עֲלֵי⁠הֶֽם׃","há⁠ʻám֙ ha⁠hòlĕki֣ym bȧ⁠ẖò֔şěkĕ ráʼ֖ẇ ʼ֣wòr gá̇d֑wòl yòşĕ̌béy֙ bĕ̇⁠ʼe֣reẕ ẕalĕmá֔weţ ʼ֖wòr nága֥ḣ ʻàléy⁠heֽm׃"],[9,3,"הִרְבִּ֣יתָ הַ⁠גּ֔וֹי לא הִגְדַּ֣לְתָּ הַ⁠שִּׂמְחָ֑ה שָׂמְח֤וּ לְ⁠פָנֶ֨י⁠ךָ֙ כְּ⁠שִׂמְחַ֣ת בַּ⁠קָּצִ֔יר כַּ⁠אֲשֶׁ֥ר יָגִ֖ילוּ בְּ⁠חַלְּקָ֥⁠ם שָׁלָֽל׃","hirĕbi֣̇yţá ha⁠ġ֔wòy lʼ higĕdȧ֣lĕţá̇ ha⁠şi̇̂mĕẖá֑h şá̂mĕẖ֤ẇ lĕ⁠páne֨y⁠ká֙ kĕ̇⁠şîmĕẖa֣ţ bȧ⁠qá̇ẕi֔yr kȧ⁠ʼàşě֥r yági֖ylẇ bĕ̇⁠ẖalĕ̇qá֥⁠m şá̌láֽl׃"],[9,4,"כִּ֣י ׀ אֶת־עֹ֣ל סֻבֳּל֗⁠וֹ וְ⁠אֵת֙ מַטֵּ֣ה שִׁכְמ֔⁠וֹ שֵׁ֖בֶט הַ⁠נֹּגֵ֣שׂ בּ֑⁠וֹ הַחִתֹּ֖תָ כְּ⁠י֥וֹם מִדְיָֽן׃","ki֣̇y ׀ ʼeţ-ʻò֣l subȯl֗⁠wò wĕ⁠ʼéţ֙ maté֣̇h şǐkĕm֔⁠wò şé֖̌bet ha⁠nò̇gé֣ş̂ ḃ֑⁠wò haẖiţò֖̇ţá kĕ̇⁠y֥wòm midĕyáֽn׃"],[9,5,"כִּ֤י כָל־סְאוֹן֙ סֹאֵ֣ן בְּ⁠רַ֔עַשׁ וְ⁠שִׂמְלָ֖ה מְגוֹלָלָ֣ה בְ⁠דָמִ֑ים וְ⁠הָיְתָ֥ה לִ⁠שְׂרֵפָ֖ה מַאֲכֹ֥לֶת אֵֽשׁ׃","ki֤̇y kál-sĕʼwòn֙ sòʼé֣n bĕ̇⁠ra֔ʻaş̌ wĕ⁠şîmĕlá֖h mĕgwòlálá֣h bĕ⁠dámi֑ym wĕ⁠háyĕţá֥h li⁠şĕ̂répá֖h maʼàkò֥leţ ʼéֽş̌׃"],[9,6,"כִּי־יֶ֣לֶד יֻלַּד־לָ֗⁠נוּ בֵּ֚ן נִתַּן־לָ֔⁠נוּ וַ⁠תְּהִ֥י הַ⁠מִּשְׂרָ֖ה עַל־שִׁכְמ֑⁠וֹ וַ⁠יִּקְרָ֨א שְׁמ֜⁠וֹ פֶּ֠לֶא יוֹעֵץ֙ אֵ֣ל גִּבּ֔וֹר אֲבִי עַ֖ד שַׂר־שָׁלֽוֹם׃","ki̇y-ye֣led yulȧd-lá֗⁠nẇ bé֚̇n niţȧn-lá֔⁠nẇ wa⁠ţĕ̇hi֥y ha⁠mi̇şĕ̂rá֖h ʻal-şǐkĕm֑⁠wò wa⁠yi̇qĕrá֨ʼ şĕ̌m֜⁠wò pė֠leʼ ywòʻéẕ֙ ʼé֣l gi̇ḃ֔wòr ʼàbiy ʻa֖d şâr-şá̌lֽwòm׃"],[9,7,"ל⁠םרבה הַ⁠מִּשְׂרָ֜ה וּ⁠לְ⁠שָׁל֣וֹם אֵֽין־קֵ֗ץ עַל־כִּסֵּ֤א דָוִד֙ וְ⁠עַל־מַמְלַכְתּ֔⁠וֹ לְ⁠הָכִ֤ין אֹתָ⁠הּ֙ וּֽ⁠לְ⁠סַעֲדָ֔⁠הּ בְּ⁠מִשְׁפָּ֖ט וּ⁠בִ⁠צְדָקָ֑ה מֵ⁠עַתָּה֙ וְ⁠עַד־עוֹלָ֔ם קִנְאַ֛ת יְהוָ֥ה צְבָא֖וֹת תַּעֲשֶׂה־זֹּֽאת׃ס","l⁠mrbh ha⁠mi̇şĕ̂rá֜h ẇ⁠lĕ⁠şá̌l֣wòm ʼéֽyn-qé֗ẕ ʻal-ki̇sé֤̇ʼ dáwid֙ wĕ⁠ʻal-mamĕlakĕţ̇֔⁠wò lĕ⁠háki֤yn ʼòţá⁠ḣ֙ ẇֽ⁠lĕ⁠saʻàdá֔⁠ḣ bĕ̇⁠mişĕ̌pá֖̇t ẇ⁠bi⁠ẕĕdáqá֑h mé⁠ʻaţá̇h֙ wĕ⁠ʻad-ʻwòlá֔m qinĕʼa֛ţ yĕhwá֥h ẕĕbáʼ֖wòţ ţȧʻàşêh-zòֽ̇ʼţ׃s"],[9,8,"דָּבָ֛ר שָׁלַ֥ח אֲדֹנָ֖⁠י בְּ⁠יַעֲקֹ֑ב וְ⁠נָפַ֖ל בְּ⁠יִשְׂרָאֵֽל׃","dá̇bá֛r şá̌la֥ẖ ʼàdòná֖⁠y bĕ̇⁠yaʻàqò֑b wĕ⁠nápa֖l bĕ̇⁠yişĕ̂ráʼéֽl׃"],[9,9,"וְ⁠יָדְעוּ֙ הָ⁠עָ֣ם כֻּלּ֔⁠וֹ אֶפְרַ֖יִם וְ⁠יוֹשֵׁ֣ב שֹׁמְר֑וֹן בְּ⁠גַאֲוָ֛ה וּ⁠בְ⁠גֹ֥דֶל לֵבָ֖ב לֵ⁠אמֹֽר׃","wĕ⁠yádĕʻẇ֙ há⁠ʻá֣m ku̇l̇֔⁠wò ʼepĕra֖yim wĕ⁠ywòşé֣̌b şò̌mĕr֑wòn bĕ̇⁠gaʼàwá֛h ẇ⁠bĕ⁠gò֥del lébá֖b lé⁠ʼmòֽr׃"],[9,10,"לְבֵנִ֥ים נָפָ֖לוּ וְ⁠גָזִ֣ית נִבְנֶ֑ה שִׁקְמִ֣ים גֻּדָּ֔עוּ וַ⁠אֲרָזִ֖ים נַחֲלִֽיף׃","lĕbéni֥ym nápá֖lẇ wĕ⁠gázi֣yţ nibĕne֑h şǐqĕmi֣ym gu̇dá̇֔ʻẇ wa⁠ʼàrázi֖ym naẖàliֽyp׃"],[9,11,"וַ⁠יְשַׂגֵּ֧ב יְהוָ֛ה אֶת־צָרֵ֥י רְצִ֖ין עָלָ֑י⁠ו וְ⁠אֶת־אֹיְבָ֖י⁠ו יְסַכְסֵֽךְ׃","wa⁠yĕşâgé֧̇b yĕhwá֛h ʼeţ-ẕáré֥y rĕẕi֖yn ʻálá֑y⁠w wĕ⁠ʼeţ-ʼòyĕbá֖y⁠w yĕsakĕséֽkĕ׃"],[9,12,"אֲרָ֣ם מִ⁠קֶּ֗דֶם וּ⁠פְלִשְׁתִּים֙ מֵֽ⁠אָח֔וֹר וַ⁠יֹּאכְל֥וּ אֶת־יִשְׂרָאֵ֖ל בְּ⁠כָל־פֶּ֑ה בְּ⁠כָל־זֹאת֙ לֹא־שָׁ֣ב אַפּ֔⁠וֹ וְ⁠ע֖וֹד יָד֥⁠וֹ נְטוּיָֽה׃","ʼàrá֣m mi⁠qė֗dem ẇ⁠pĕlişĕ̌ţi̇ym֙ méֽ⁠ʼáẖ֔wòr wa⁠yò̇ʼkĕl֥ẇ ʼeţ-yişĕ̂ráʼé֖l bĕ̇⁠kál-pė֑h bĕ̇⁠kál-zòʼţ֙ lòʼ-şá֣̌b ʼaṗ֔⁠wò wĕ⁠ʻ֖wòd yád֥⁠wò nĕtẇyáֽh׃"],[9,13,"וְ⁠הָ⁠עָ֥ם לֹא־שָׁ֖ב עַד־הַ⁠מַּכֵּ֑⁠הוּ וְ⁠אֶת־יְהוָ֥ה צְבָא֖וֹת לֹ֥א דָרָֽשׁוּ׃ס","wĕ⁠há⁠ʻá֥m lòʼ-şá֖̌b ʻad-ha⁠mȧké֑̇⁠hẇ wĕ⁠ʼeţ-yĕhwá֥h ẕĕbáʼ֖wòţ lò֥ʼ dáráֽş̌ẇ׃s"],[9,14,"וַ⁠יַּכְרֵ֨ת יְהוָ֜ה מִ⁠יִּשְׂרָאֵ֗ל רֹ֧אשׁ וְ⁠זָנָ֛ב כִּפָּ֥ה וְ⁠אַגְמ֖וֹן י֥וֹם אֶחָֽד׃","wa⁠yȧkĕré֨ţ yĕhwá֜h mi⁠yi̇şĕ̂ráʼé֗l rò֧ʼş̌ wĕ⁠záná֛b ki̇pá֥̇h wĕ⁠ʼagĕm֖wòn y֥wòm ʼeẖáֽd׃"],[9,15,"זָקֵ֥ן וּ⁠נְשׂוּא־פָנִ֖ים ה֣וּא הָ⁠רֹ֑אשׁ וְ⁠נָבִ֥יא מֽוֹרֶה־שֶּׁ֖קֶר ה֥וּא הַ⁠זָּנָֽב׃","záqé֥n ẇ⁠nĕş̂ẇʼ-páni֖ym h֣ẇʼ há⁠rò֑ʼş̌ wĕ⁠nábi֥yʼ mֽwòreh-şė֖̌qer h֥ẇʼ ha⁠zá̇náֽb׃"],[9,16,"וַ⁠יִּֽהְי֛וּ מְאַשְּׁרֵ֥י הָֽ⁠עָם־הַ⁠זֶּ֖ה מַתְעִ֑ים וּ⁠מְאֻשָּׁרָ֖י⁠ו מְבֻלָּעִֽים׃","wa⁠yiֽ̇hĕy֛ẇ mĕʼaşĕ̇̌ré֥y háֽ⁠ʻám-ha⁠zė֖h maţĕʻi֑ym ẇ⁠mĕʼuşá̇̌rá֖y⁠w mĕbulá̇ʻiֽym׃"],[9,17,"עַל־כֵּ֨ן עַל־בַּחוּרָ֜י⁠ו לֹֽא־יִשְׂמַ֣ח ׀ אֲדֹנָ֗⁠י וְ⁠אֶת־יְתֹמָ֤י⁠ו וְ⁠אֶת־אַלְמְנֹתָי⁠ו֙ לֹ֣א יְרַחֵ֔ם כִּ֤י כֻלּ⁠וֹ֙ חָנֵ֣ף וּ⁠מֵרַ֔ע וְ⁠כָל־פֶּ֖ה דֹּבֵ֣ר נְבָלָ֑ה בְּ⁠כָל־זֹאת֙ לֹא־שָׁ֣ב אַפּ֔⁠וֹ וְ⁠ע֖וֹד יָד֥⁠וֹ נְטוּיָֽה׃","ʻal-ké̇֨n ʻal-bȧẖẇrá֜y⁠w lòֽʼ-yişĕ̂ma֣ẖ ׀ ʼàdòná֗⁠y wĕ⁠ʼeţ-yĕţòmá֤y⁠w wĕ⁠ʼeţ-ʼalĕmĕnòţáy⁠w֙ lò֣ʼ yĕraẖé֔m ki֤̇y kul̇⁠wò֙ ẖáné֣p ẇ⁠méra֔ʻ wĕ⁠kál-pė֖h dò̇bé֣r nĕbálá֑h bĕ̇⁠kál-zòʼţ֙ lòʼ-şá֣̌b ʼaṗ֔⁠wò wĕ⁠ʻ֖wòd yád֥⁠wò nĕtẇyáֽh׃"],[9,18,"כִּֽי־בָעֲרָ֤ה כָ⁠אֵשׁ֙ רִשְׁעָ֔ה שָׁמִ֥יר וָ⁠שַׁ֖יִת תֹּאכֵ֑ל וַ⁠תִּצַּת֙ בְּ⁠סִֽבְכֵ֣י הַ⁠יַּ֔עַר וַ⁠יִּֽתְאַבְּכ֖וּ גֵּא֥וּת עָשָֽׁן׃","kiֽ̇y-báʻàrá֤h ká⁠ʼéş̌֙ rişĕ̌ʻá֔h şá̌mi֥yr wá⁠şǎ֖yiţ ţò̇ʼké֑l wa⁠ţi̇ẕȧţ֙ bĕ̇⁠siֽbĕké֣y ha⁠yȧ֔ʻar wa⁠yiֽ̇ţĕʼabĕ̇k֖ẇ gé̇ʼ֥ẇţ ʻáşáֽ̌n׃"],[9,19,"בְּ⁠עֶבְרַ֛ת יְהוָ֥ה צְבָא֖וֹת נֶעְתַּ֣ם אָ֑רֶץ וַ⁠יְהִ֤י הָ⁠עָם֙ כְּ⁠מַאֲכֹ֣לֶת אֵ֔שׁ אִ֥ישׁ אֶל־אָחִ֖י⁠ו לֹ֥א יַחְמֹֽלוּ׃","bĕ̇⁠ʻebĕra֛ţ yĕhwá֥h ẕĕbáʼ֖wòţ neʻĕţȧ֣m ʼá֑reẕ wa⁠yĕhi֤y há⁠ʻám֙ kĕ̇⁠maʼàkò֣leţ ʼé֔ş̌ ʼi֥yş̌ ʼel-ʼáẖi֖y⁠w lò֥ʼ yaẖĕmòֽlẇ׃"],[9,20,"וַ⁠יִּגְזֹ֤ר עַל־יָמִין֙ וְ⁠רָעֵ֔ב וַ⁠יֹּ֥אכַל עַל־שְׂמֹ֖אול וְ⁠לֹ֣א שָׂבֵ֑עוּ אִ֥ישׁ בְּשַׂר־זְרֹע֖⁠וֹ יֹאכֵֽלוּ׃","wa⁠yi̇gĕzò֤r ʻal-yámiyn֙ wĕ⁠ráʻé֔b wa⁠yò֥̇ʼkal ʻal-şĕ̂mò֖ʼwl wĕ⁠lò֣ʼ şá̂bé֑ʻẇ ʼi֥yş̌ bĕ̇şâr-zĕròʻ֖⁠wò yòʼkéֽlẇ׃"],[9,21,"מְנַשֶּׁ֣ה אֶת־אֶפְרַ֗יִם וְ⁠אֶפְרַ֨יִם֙ אֶת־מְנַשֶּׁ֔ה יַחְדָּ֥ו הֵ֖מָּה עַל־יְהוּדָ֑ה בְּ⁠כָל־זֹאת֙ לֹא־שָׁ֣ב אַפּ֔⁠וֹ וְ⁠ע֖וֹד יָד֥⁠וֹ נְטוּיָֽה׃ס","mĕnaşė֣̌h ʼeţ-ʼepĕra֗yim wĕ⁠ʼepĕra֨yim֙ ʼeţ-mĕnaşė̌֔h yaẖĕdá֥̇w hé֖má̇h ʻal-yĕhẇdá֑h bĕ̇⁠kál-zòʼţ֙ lòʼ-şá֣̌b ʼaṗ֔⁠wò wĕ⁠ʻ֖wòd yád֥⁠wò nĕtẇyáֽh׃s"],[10,1,"ה֥וֹי הַ⁠חֹֽקְקִ֖ים חִקְקֵי־אָ֑וֶן וּֽ⁠מְכַתְּבִ֥ים עָמָ֖ל כִּתֵּֽבוּ׃","h֥wòy ha⁠ẖòֽqĕqi֖ym ẖiqĕqéy-ʼá֑wen ẇֽ⁠mĕkaţĕ̇bi֥ym ʻámá֖l ki̇ţéֽ̇bẇ׃"],[10,2,"לְ⁠הַטּ֤וֹת מִ⁠דִּין֙ דַּלִּ֔ים וְ⁠לִ⁠גְזֹ֕ל מִשְׁפַּ֖ט עֲנִיֵּ֣י עַמִּ֑⁠י לִ⁠הְי֤וֹת אַלְמָנוֹת֙ שְׁלָלָ֔⁠ם וְ⁠אֶת־יְתוֹמִ֖ים יָבֹֽזּוּ׃","lĕ⁠haṫ֤wòţ mi⁠di̇yn֙ dȧli̇֔ym wĕ⁠li⁠gĕzò֕l mişĕ̌pȧ֖t ʻàniyé֣̇y ʻami֑̇⁠y li⁠hĕy֤wòţ ʼalĕmánwòţ֙ şĕ̌lálá֔⁠m wĕ⁠ʼeţ-yĕţwòmi֖ym yábòֽżẇ׃"],[10,3,"וּ⁠מַֽה־תַּעֲשׂוּ֙ לְ⁠י֣וֹם פְּקֻדָּ֔ה וּ⁠לְ⁠שׁוֹאָ֖ה מִ⁠מֶּרְחָ֣ק תָּב֑וֹא עַל־מִי֙ תָּנ֣וּסוּ לְ⁠עֶזְרָ֔ה וְ⁠אָ֥נָה תַעַזְב֖וּ כְּבוֹדְ⁠כֶֽם׃","ẇ⁠maֽh-ţȧʻàş̂ẇ֙ lĕ⁠y֣wòm pĕ̇qudá̇֔h ẇ⁠lĕ⁠ş̌wòʼá֖h mi⁠mėrĕẖá֣q ţá̇b֑wòʼ ʻal-miy֙ ţá̇n֣ẇsẇ lĕ⁠ʻezĕrá֔h wĕ⁠ʼá֥náh ţaʻazĕb֖ẇ kĕ̇bwòdĕ⁠keֽm׃"],[10,4,"בִּלְתִּ֤י כָרַע֙ תַּ֣חַת אַסִּ֔יר וְ⁠תַ֥חַת הֲרוּגִ֖ים יִפֹּ֑לוּ בְּ⁠כָל־זֹאת֙ לֹא־שָׁ֣ב אַפּ֔⁠וֹ וְ⁠ע֖וֹד יָד֥⁠וֹ נְטוּיָֽה׃ס","bi̇lĕţi֤̇y káraʻ֙ ţȧ֣ẖaţ ʼasi̇֔yr wĕ⁠ţa֥ẖaţ hàrẇgi֖ym yipò֑̇lẇ bĕ̇⁠kál-zòʼţ֙ lòʼ-şá֣̌b ʼaṗ֔⁠wò wĕ⁠ʻ֖wòd yád֥⁠wò nĕtẇyáֽh׃s"],[10,5,"ה֥וֹי אַשּׁ֖וּר שֵׁ֣בֶט אַפִּ֑⁠י וּ⁠מַטֶּה־ה֥וּא בְ⁠יָדָ֖⁠ם זַעְמִֽ⁠י׃","h֥wòy ʼaş֖̇̌ẇr şé֣̌bet ʼapi֑̇⁠y ẇ⁠matėh-h֥ẇʼ bĕ⁠yádá֖⁠m zaʻĕmiֽ⁠y׃"],[10,6,"בְּ⁠ג֤וֹי חָנֵף֙ אֲשַׁלְּחֶ֔⁠נּוּ וְ⁠עַל־עַ֥ם עֶבְרָתִ֖⁠י אֲצַוֶּ֑⁠נּוּ לִ⁠שְׁלֹ֤ל שָׁלָל֙ וְ⁠לָ⁠בֹ֣ז בַּ֔ז ו⁠ל⁠שימ⁠ו מִרְמָ֖ס כְּ⁠חֹ֥מֶר חוּצֽוֹת׃","bĕ̇⁠g֤wòy ẖánép֙ ʼàşǎlĕ̇ẖe֔⁠ṅẇ wĕ⁠ʻal-ʻa֥m ʻebĕráţi֖⁠y ʼàẕawė֑⁠ṅẇ li⁠şĕ̌lò֤l şá̌lál֙ wĕ⁠lá⁠bò֣z bȧ֔z w⁠l⁠şym⁠w mirĕmá֖s kĕ̇⁠ẖò֥mer ẖẇẕֽwòţ׃"],[10,7,"וְ⁠הוּא֙ לֹא־כֵ֣ן יְדַמֶּ֔ה וּ⁠לְבָב֖⁠וֹ לֹא־כֵ֣ן יַחְשֹׁ֑ב כִּ֚י לְ⁠הַשְׁמִ֣יד בִּ⁠לְבָב֔⁠וֹ וּ⁠לְ⁠הַכְרִ֥ית גּוֹיִ֖ם לֹ֥א מְעָֽט׃","wĕ⁠hẇʼ֙ lòʼ-ké֣n yĕdamė֔h ẇ⁠lĕbáb֖⁠wò lòʼ-ké֣n yaẖĕşò֑̌b ki֚̇y lĕ⁠haşĕ̌mi֣yd bi̇⁠lĕbáb֔⁠wò ẇ⁠lĕ⁠hakĕri֥yţ ġwòyi֖m lò֥ʼ mĕʻáֽt׃"],[10,8,"כִּ֖י יֹאמַ֑ר הֲ⁠לֹ֥א שָׂרַ֛⁠י יַחְדָּ֖ו מְלָכִֽים׃","ki֖̇y yòʼma֑r hà⁠lò֥ʼ şá̂ra֛⁠y yaẖĕdá֖̇w mĕlákiֽym׃"],[10,9,"הֲ⁠לֹ֥א כְּ⁠כַרְכְּמִ֖ישׁ כַּלְנ֑וֹ אִם־לֹ֤א כְ⁠אַרְפַּד֙ חֲמָ֔ת אִם־לֹ֥א כְ⁠דַמֶּ֖שֶׂק שֹׁמְרֽוֹן׃","hà⁠lò֥ʼ kĕ̇⁠karĕkĕ̇mi֖yş̌ kȧlĕn֑wò ʼim-lò֤ʼ kĕ⁠ʼarĕpȧd֙ ẖàmá֔ţ ʼim-lò֥ʼ kĕ⁠damė֖şêq şò̌mĕrֽwòn׃"],[10,10,"כַּ⁠אֲשֶׁר֙ מָצְאָ֣ה יָדִ֔⁠י לְ⁠מַמְלְכֹ֖ת הָ⁠אֱלִ֑יל וּ⁠פְסִ֣ילֵי⁠הֶ֔ם מִ⁠ירֽוּשָׁלִַ֖ם וּ⁠מִ⁠שֹּׁמְרֽוֹן׃","kȧ⁠ʼàşěr֙ máẕĕʼá֣h yádi֔⁠y lĕ⁠mamĕlĕkò֖ţ há⁠ʼèli֑yl ẇ⁠pĕsi֣yléy⁠he֔m mi⁠yrֽẇşá̌lia֖m ẇ⁠mi⁠şò̇̌mĕrֽwòn׃"],[10,11,"הֲ⁠לֹ֗א כַּ⁠אֲשֶׁ֥ר עָשִׂ֛יתִי לְ⁠שֹׁמְר֖וֹן וְ⁠לֶ⁠אֱלִילֶ֑י⁠הָ כֵּ֛ן אֶעֱשֶׂ֥ה לִ⁠ירוּשָׁלִַ֖ם וְ⁠לַ⁠עֲצַבֶּֽי⁠הָ׃ס","hà⁠lò֗ʼ kȧ⁠ʼàşě֥r ʻáşî֛yţiy lĕ⁠şò̌mĕr֖wòn wĕ⁠le⁠ʼèliyle֑y⁠há ké֛̇n ʼeʻèşê֥h li⁠yrẇşá̌lia֖m wĕ⁠la⁠ʻàẕabėֽy⁠há׃s"],[10,12,"וְ⁠הָיָ֗ה כִּֽי־יְבַצַּ֤ע אֲדֹנָ⁠י֙ אֶת־כָּל־מַֽעֲשֵׂ֔⁠הוּ בְּ⁠הַ֥ר צִיּ֖וֹן וּ⁠בִ⁠ירוּשָׁלִָ֑ם אֶפְקֹ֗ד עַל־פְּרִי־גֹ֨דֶל֙ לְבַ֣ב מֶֽלֶךְ־אַשּׁ֔וּר וְ⁠עַל־תִּפְאֶ֖רֶת ר֥וּם עֵינָֽי⁠ו׃","wĕ⁠háyá֗h kiֽ̇y-yĕbaẕȧ֤ʻ ʼàdòná⁠y֙ ʼeţ-ká̇l-mֽaʻàşé̂֔⁠hẇ bĕ̇⁠ha֥r ẕiẏ֖wòn ẇ⁠bi⁠yrẇşá̌liá֑m ʼepĕqò֗d ʻal-pĕ̇riy-gò֨del֙ lĕba֣b meֽlekĕ-ʼaş̇̌֔ẇr wĕ⁠ʻal-ţi̇pĕʼe֖reţ r֥ẇm ʻéynáֽy⁠w׃"],[10,13,"כִּ֣י אָמַ֗ר בְּ⁠כֹ֤חַ יָדִ⁠י֙ עָשִׂ֔יתִי וּ⁠בְ⁠חָכְמָתִ֖⁠י כִּ֣י נְבֻנ֑וֹתִי וְ⁠אָסִ֣יר ׀ גְּבוּלֹ֣ת עַמִּ֗ים ו⁠עתידתי⁠הם שׁוֹשֵׂ֔תִי וְ⁠אוֹרִ֥יד כַּ⁠אבִּ֖יר יוֹשְׁבִֽים׃","ki֣̇y ʼáma֗r bĕ̇⁠kò֤ẖa yádi⁠y֙ ʻáşî֔yţiy ẇ⁠bĕ⁠ẖákĕmáţi֖⁠y ki֣̇y nĕbun֑wòţiy wĕ⁠ʼási֣yr ׀ gĕ̇bẇlò֣ţ ʻami̇֗ym w⁠ʻţydţy⁠hm ş̌wòşé̂֔ţiy wĕ⁠ʼwòri֥yd kȧ⁠ʼbi֖̇yr ywòşĕ̌biֽym׃"],[10,14,"וַ⁠תִּמְצָ֨א כַ⁠קֵּ֤ן ׀ יָדִ⁠י֙ לְ⁠חֵ֣יל הָֽ⁠עַמִּ֔ים וְ⁠כֶ⁠אֱסֹף֙ בֵּיצִ֣ים עֲזֻב֔וֹת כָּל־הָ⁠אָ֖רֶץ אֲנִ֣י אָסָ֑פְתִּי וְ⁠לֹ֤א הָיָה֙ נֹדֵ֣ד כָּנָ֔ף וּ⁠פֹצֶ֥ה פֶ֖ה וּ⁠מְצַפְצֵֽף׃","wa⁠ţi̇mĕẕá֨ʼ ka⁠qé֤̇n ׀ yádi⁠y֙ lĕ⁠ẖé֣yl háֽ⁠ʻami̇֔ym wĕ⁠ke⁠ʼèsòp֙ bé̇yẕi֣ym ʻàzub֔wòţ ká̇l-há⁠ʼá֖reẕ ʼàni֣y ʼásá֑pĕţi̇y wĕ⁠lò֤ʼ háyáh֙ nòdé֣d ká̇ná֔p ẇ⁠pòẕe֥h pe֖h ẇ⁠mĕẕapĕẕéֽp׃"],[10,15,"הֲ⁠יִתְפָּאֵר֙ הַ⁠גַּרְזֶ֔ן עַ֖ל הַ⁠חֹצֵ֣ב בּ֑⁠וֹ אִם־יִתְגַּדֵּ֤ל הַ⁠מַּשּׂוֹר֙ עַל־מְנִיפ֔⁠וֹ כְּ⁠הָנִ֥יף שֵׁ֨בֶט֙ וְ⁠אֶת־מְרִימָ֔י⁠ו כְּ⁠הָרִ֥ים מַטֶּ֖ה לֹא־עֵֽץ׃","hà⁠yiţĕpá̇ʼér֙ ha⁠gȧrĕze֔n ʻa֖l ha⁠ẖòẕé֣b ḃ֑⁠wò ʼim-yiţĕgȧdé֤̇l ha⁠mȧş̇̂wòr֙ ʻal-mĕniyp֔⁠wò kĕ̇⁠háni֥yp şé̌֨bet֙ wĕ⁠ʼeţ-mĕriymá֔y⁠w kĕ̇⁠hári֥ym matė֖h lòʼ-ʻéֽẕ׃"],[10,16,"לָ֠⁠כֵן יְשַׁלַּ֨ח הָ⁠אָד֜וֹן יְהוָ֧ה צְבָא֛וֹת בְּ⁠מִשְׁמַנָּ֖י⁠ו רָז֑וֹן וְ⁠תַ֧חַת כְּבֹד֛⁠וֹ יֵקַ֥ד יְקֹ֖ד כִּ⁠יק֥וֹד אֵֽשׁ׃","lá֠⁠kén yĕşǎlȧ֨ẖ há⁠ʼád֜wòn yĕhwá֧h ẕĕbáʼ֛wòţ bĕ̇⁠mişĕ̌maná֖̇y⁠w ráz֑wòn wĕ⁠ţa֧ẖaţ kĕ̇bòd֛⁠wò yéqa֥d yĕqò֖d ki̇⁠yq֥wòd ʼéֽş̌׃"],[10,17,"וְ⁠הָיָ֤ה אֽוֹר־יִשְׂרָאֵל֙ לְ⁠אֵ֔שׁ וּ⁠קְדוֹשׁ֖⁠וֹ לְ⁠לֶהָבָ֑ה וּ⁠בָעֲרָ֗ה וְ⁠אָֽכְלָ֛ה שִׁית֥⁠וֹ וּ⁠שְׁמִיר֖⁠וֹ בְּ⁠י֥וֹם אֶחָֽד׃","wĕ⁠háyá֤h ʼֽwòr-yişĕ̂ráʼél֙ lĕ⁠ʼé֔ş̌ ẇ⁠qĕdwòş֖̌⁠wò lĕ⁠lehábá֑h ẇ⁠báʻàrá֗h wĕ⁠ʼáֽkĕlá֛h şǐyţ֥⁠wò ẇ⁠şĕ̌miyr֖⁠wò bĕ̇⁠y֥wòm ʼeẖáֽd׃"],[10,18,"וּ⁠כְב֤וֹד יַעְר⁠וֹ֙ וְ⁠כַרְמִלּ֔⁠וֹ מִ⁠נֶּ֥פֶשׁ וְ⁠עַד־בָּשָׂ֖ר יְכַלֶּ֑ה וְ⁠הָיָ֖ה כִּ⁠מְסֹ֥ס נֹסֵֽס׃","ẇ⁠kĕb֤wòd yaʻĕr⁠wò֙ wĕ⁠karĕmil̇֔⁠wò mi⁠nė֥peş̌ wĕ⁠ʻad-bá̇şá֖̂r yĕkalė֑h wĕ⁠háyá֖h ki̇⁠mĕsò֥s nòséֽs׃"],[10,19,"וּ⁠שְׁאָ֥ר עֵ֛ץ יַעְר֖⁠וֹ מִסְפָּ֣ר יִֽהְי֑וּ וְ⁠נַ֖עַר יִכְתְּבֵֽ⁠ם׃פ","ẇ⁠şĕ̌ʼá֥r ʻé֛ẕ yaʻĕr֖⁠wò misĕpá֣̇r yiֽhĕy֑ẇ wĕ⁠na֖ʻar yikĕţĕ̇béֽ⁠m׃p"],[10,20,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא לֹֽא־יוֹסִ֨יף ע֜וֹד שְׁאָ֤ר יִשְׂרָאֵל֙ וּ⁠פְלֵיטַ֣ת בֵּֽית־יַעֲקֹ֔ב לְ⁠הִשָּׁעֵ֖ן עַל־מַכֵּ֑⁠הוּ וְ⁠נִשְׁעַ֗ן עַל־יְהוָ֛ה קְד֥וֹשׁ יִשְׂרָאֵ֖ל בֶּ⁠אֱמֶֽת׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ lòֽʼ-ywòsi֨yp ʻ֜wòd şĕ̌ʼá֤r yişĕ̂ráʼél֙ ẇ⁠pĕléyta֣ţ béֽ̇yţ-yaʻàqò֔b lĕ⁠hişá̇̌ʻé֖n ʻal-maké֑̇⁠hẇ wĕ⁠nişĕ̌ʻa֗n ʻal-yĕhwá֛h qĕd֥wòş̌ yişĕ̂ráʼé֖l bė⁠ʼèmeֽţ׃"],[10,21,"שְׁאָ֥ר יָשׁ֖וּב שְׁאָ֣ר יַעֲקֹ֑ב אֶל־אֵ֖ל גִּבּֽוֹר׃","şĕ̌ʼá֥r yáş֖̌ẇb şĕ̌ʼá֣r yaʻàqò֑b ʼel-ʼé֖l gi̇ḃֽwòr׃"],[10,22,"כִּ֣י אִם־יִהְיֶ֞ה עַמְּ⁠ךָ֤ יִשְׂרָאֵל֙ כְּ⁠ח֣וֹל הַ⁠יָּ֔ם שְׁאָ֖ר יָשׁ֣וּב בּ֑⁠וֹ כִּלָּי֥וֹן חָר֖וּץ שׁוֹטֵ֥ף צְדָקָֽה׃","ki֣̇y ʼim-yihĕye֞h ʻamĕ̇⁠ká֤ yişĕ̂ráʼél֙ kĕ̇⁠ẖ֣wòl ha⁠yá̇֔m şĕ̌ʼá֖r yáş֣̌ẇb ḃ֑⁠wò ki̇lá̇y֥wòn ẖár֖ẇẕ ş̌wòté֥p ẕĕdáqáֽh׃"],[10,23,"כִּ֥י כָלָ֖ה וְ⁠נֶחֱרָצָ֑ה אֲדֹנָ֤⁠י יְהוִה֙ צְבָא֔וֹת עֹשֶׂ֖ה בְּ⁠קֶ֥רֶב כָּל־הָ⁠אָֽרֶץ׃ס","ki֥̇y kálá֖h wĕ⁠neẖèráẕá֑h ʼàdòná֤⁠y yĕhwih֙ ẕĕbáʼ֔wòţ ʻòşê֖h bĕ̇⁠qe֥reb ká̇l-há⁠ʼáֽreẕ׃s"],[10,24,"לָ⁠כֵ֗ן כֹּֽה־אָמַ֞ר אֲדֹנָ֤⁠י יְהוִה֙ צְבָא֔וֹת אַל־תִּירָ֥א עַמִּ֛⁠י יֹשֵׁ֥ב צִיּ֖וֹן מֵֽ⁠אַשּׁ֑וּר בַּ⁠שֵּׁ֣בֶט יַכֶּ֔⁠כָּה וּ⁠מַטֵּ֥⁠הוּ יִשָּֽׂא־עָלֶ֖י⁠ךָ בְּ⁠דֶ֥רֶךְ מִצְרָֽיִם׃","lá⁠ké֗n kòֽ̇h-ʼáma֞r ʼàdòná֤⁠y yĕhwih֙ ẕĕbáʼ֔wòţ ʼal-ţi̇yrá֥ʼ ʻami֛̇⁠y yòşé֥̌b ẕiẏ֖wòn méֽ⁠ʼaş֑̇̌ẇr bȧ⁠şé֣̇̌bet yakė֔⁠ká̇h ẇ⁠maté֥̇⁠hẇ yişáֽ̇̂ʼ-ʻále֖y⁠ká bĕ̇⁠de֥rekĕ miẕĕráֽyim׃"],[10,25,"כִּי־ע֖וֹד מְעַ֣ט מִזְעָ֑ר וְ⁠כָ֣לָה זַ֔עַם וְ⁠אַפִּ֖⁠י עַל־תַּבְלִיתָֽ⁠ם׃","ki̇y-ʻ֖wòd mĕʻa֣t mizĕʻá֑r wĕ⁠ká֣láh za֔ʻam wĕ⁠ʼapi֖̇⁠y ʻal-ţȧbĕliyţáֽ⁠m׃"],[10,26,"וְ⁠עוֹרֵ֨ר עָלָ֜י⁠ו יְהוָ֤ה צְבָאוֹת֙ שׁ֔וֹט כְּ⁠מַכַּ֥ת מִדְיָ֖ן בְּ⁠צ֣וּר עוֹרֵ֑ב וּ⁠מַטֵּ֨⁠הוּ֙ עַל־הַ⁠יָּ֔ם וּ⁠נְשָׂא֖⁠וֹ בְּ⁠דֶ֥רֶךְ מִצְרָֽיִם׃","wĕ⁠ʻwòré֨r ʻálá֜y⁠w yĕhwá֤h ẕĕbáʼwòţ֙ ş̌֔wòt kĕ̇⁠makȧ֥ţ midĕyá֖n bĕ̇⁠ẕ֣ẇr ʻwòré֑b ẇ⁠maté̇֨⁠hẇ֙ ʻal-ha⁠yá̇֔m ẇ⁠nĕşá̂ʼ֖⁠wò bĕ̇⁠de֥rekĕ miẕĕráֽyim׃"],[10,27,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יָס֤וּר סֻבֳּל⁠וֹ֙ מֵ⁠עַ֣ל שִׁכְמֶ֔⁠ךָ וְ⁠עֻלּ֖⁠וֹ מֵ⁠עַ֣ל צַוָּארֶ֑⁠ךָ וְ⁠חֻבַּ֥ל עֹ֖ל מִ⁠פְּנֵי־שָֽׁמֶן׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yás֤ẇr subȯl⁠wò֙ mé⁠ʻa֣l şǐkĕme֔⁠ká wĕ⁠ʻul֖̇⁠wò mé⁠ʻa֣l ẕawá̇ʼre֑⁠ká wĕ⁠ẖubȧ֥l ʻò֖l mi⁠pĕ̇néy-şáֽ̌men׃"],[10,28,"בָּ֥א עַל־עַיַּ֖ת עָבַ֣ר בְּ⁠מִגְר֑וֹן לְ⁠מִכְמָ֖שׂ יַפְקִ֥יד כֵּלָֽי⁠ו׃","bá֥̇ʼ ʻal-ʻayȧ֖ţ ʻába֣r bĕ̇⁠migĕr֑wòn lĕ⁠mikĕmá֖ş̂ yapĕqi֥yd ké̇láֽy⁠w׃"],[10,29,"עָֽבְרוּ֙ מַעְבָּרָ֔ה גֶּ֖בַע מָל֣וֹן לָ֑⁠נוּ חָֽרְדָה֙ הָֽ⁠רָמָ֔ה גִּבְעַ֥ת שָׁא֖וּל נָֽסָה׃","ʻáֽbĕrẇ֙ maʻĕbá̇rá֔h gė֖baʻ mál֣wòn lá֑⁠nẇ ẖáֽrĕdáh֙ háֽ⁠rámá֔h gi̇bĕʻa֥ţ şá̌ʼ֖ẇl náֽsáh׃"],[10,30,"צַהֲלִ֥י קוֹלֵ֖⁠ךְ בַּת־גַּלִּ֑ים הַקְשִׁ֥יבִי לַ֖יְשָׁה עֲנִיָּ֥ה עֲנָתֽוֹת׃","ẕahàli֥y qwòlé֖⁠kĕ bȧţ-gȧli֑̇ym haqĕşǐ֥ybiy la֖yĕşá̌h ʻàniyá֥̇h ʻànáţֽwòţ׃"],[10,31,"נָדְדָ֖ה מַדְמֵנָ֑ה יֹשְׁבֵ֥י הַ⁠גֵּבִ֖ים הֵעִֽיזוּ׃","nádĕdá֖h madĕméná֑h yòşĕ̌bé֥y ha⁠gé̇bi֖ym héʻiֽyzẇ׃"],[10,32,"ע֥וֹד הַ⁠יּ֖וֹם בְּ⁠נֹ֣ב לַֽ⁠עֲמֹ֑ד יְנֹפֵ֤ף יָד⁠וֹ֙ הַ֣ר בית־צִיּ֔וֹן גִּבְעַ֖ת יְרוּשָׁלִָֽם׃ס","ʻ֥wòd ha⁠ẏ֖wòm bĕ̇⁠nò֣b laֽ⁠ʻàmò֑d yĕnòpé֤p yád⁠wò֙ ha֣r byţ-ẕiẏ֔wòn gi̇bĕʻa֖ţ yĕrẇşá̌liáֽm׃s"],[10,33,"הִנֵּ֤ה הָ⁠אָדוֹן֙ יְהוָ֣ה צְבָא֔וֹת מְסָעֵ֥ף פֻּארָ֖ה בְּ⁠מַעֲרָצָ֑ה וְ⁠רָמֵ֤י הַ⁠קּוֹמָה֙ גְּדוּעִ֔ים וְ⁠הַ⁠גְּבֹהִ֖ים יִשְׁפָּֽלוּ׃","hiné֤̇h há⁠ʼádwòn֙ yĕhwá֣h ẕĕbáʼ֔wòţ mĕsáʻé֥p pu̇ʼrá֖h bĕ̇⁠maʻàráẕá֑h wĕ⁠rámé֤y ha⁠q̇wòmáh֙ gĕ̇dẇʻi֔ym wĕ⁠ha⁠gĕ̇bòhi֖ym yişĕ̌páֽ̇lẇ׃"],[10,34,"וְ⁠נִקַּ֛ף סִֽבְכֵ֥י הַ⁠יַּ֖עַר בַּ⁠בַּרְזֶ֑ל וְ⁠הַ⁠לְּבָנ֖וֹן בְּ⁠אַדִּ֥יר יִפּֽוֹל׃ס","wĕ⁠niqȧ֛p siֽbĕké֥y ha⁠yȧ֖ʻar bȧ⁠bȧrĕze֑l wĕ⁠ha⁠lĕ̇bán֖wòn bĕ̇⁠ʼadi֥̇yr yiṗֽwòl׃s"],[11,1,"וְ⁠יָצָ֥א חֹ֖טֶר מִ⁠גֵּ֣זַע יִשָׁ֑י וְ⁠נֵ֖צֶר מִ⁠שָּׁרָשָׁ֥י⁠ו יִפְרֶֽה׃","wĕ⁠yáẕá֥ʼ ẖò֖ter mi⁠gé֣̇zaʻ yişá֑̌y wĕ⁠né֖ẕer mi⁠şá̇̌ráşá֥̌y⁠w yipĕreֽh׃"],[11,2,"וְ⁠נָחָ֥ה עָלָ֖י⁠ו ר֣וּחַ יְהוָ֑ה ר֧וּחַ חָכְמָ֣ה וּ⁠בִינָ֗ה ר֤וּחַ עֵצָה֙ וּ⁠גְבוּרָ֔ה ר֥וּחַ דַּ֖עַת וְ⁠יִרְאַ֥ת יְהוָֽה׃","wĕ⁠náẖá֥h ʻálá֖y⁠w r֣ẇẖa yĕhwá֑h r֧ẇẖa ẖákĕmá֣h ẇ⁠biyná֗h r֤ẇẖa ʻéẕáh֙ ẇ⁠gĕbẇrá֔h r֥ẇẖa dȧ֖ʻaţ wĕ⁠yirĕʼa֥ţ yĕhwáֽh׃"],[11,3,"וַ⁠הֲרִיח֖⁠וֹ בְּ⁠יִרְאַ֣ת יְהוָ֑ה וְ⁠לֹֽא־לְ⁠מַרְאֵ֤ה עֵינָי⁠ו֙ יִשְׁפּ֔וֹט וְ⁠לֹֽא־לְ⁠מִשְׁמַ֥ע אָזְנָ֖י⁠ו יוֹכִֽיחַ׃","wa⁠hàriyẖ֖⁠wò bĕ̇⁠yirĕʼa֣ţ yĕhwá֑h wĕ⁠lòֽʼ-lĕ⁠marĕʼé֤h ʻéynáy⁠w֙ yişĕ̌ṗ֔wòt wĕ⁠lòֽʼ-lĕ⁠mişĕ̌ma֥ʻ ʼázĕná֖y⁠w ywòkiֽyẖa׃"],[11,4,"וְ⁠שָׁפַ֤ט בְּ⁠צֶ֨דֶק֙ דַּלִּ֔ים וְ⁠הוֹכִ֥יחַ בְּ⁠מִישׁ֖וֹר לְ⁠עַנְוֵי־אָ֑רֶץ וְ⁠הִֽכָּה־אֶ֨רֶץ֙ בְּ⁠שֵׁ֣בֶט פִּ֔י⁠ו וּ⁠בְ⁠ר֥וּחַ שְׂפָתָ֖י⁠ו יָמִ֥ית רָשָֽׁע׃","wĕ⁠şá̌pa֤t bĕ̇⁠ẕe֨deq֙ dȧli̇֔ym wĕ⁠hwòki֥yẖa bĕ̇⁠miyş֖̌wòr lĕ⁠ʻanĕwéy-ʼá֑reẕ wĕ⁠hiֽká̇h-ʼe֨reẕ֙ bĕ̇⁠şé֣̌bet pi̇֔y⁠w ẇ⁠bĕ⁠r֥ẇẖa şĕ̂páţá֖y⁠w yámi֥yţ ráşáֽ̌ʻ׃"],[11,5,"וְ⁠הָ֥יָה צֶ֖דֶק אֵז֣וֹר מָתְנָ֑י⁠ו וְ⁠הָ⁠אֱמוּנָ֖ה אֵז֥וֹר חֲלָצָֽי⁠ו׃","wĕ⁠há֥yáh ẕe֖deq ʼéz֣wòr máţĕná֑y⁠w wĕ⁠há⁠ʼèmẇná֖h ʼéz֥wòr ẖàláẕáֽy⁠w׃"],[11,6,"וְ⁠גָ֤ר זְאֵב֙ עִם־כֶּ֔בֶשׂ וְ⁠נָמֵ֖ר עִם־גְּדִ֣י יִרְבָּ֑ץ וְ⁠עֵ֨גֶל וּ⁠כְפִ֤יר וּ⁠מְרִיא֙ יַחְדָּ֔ו וְ⁠נַ֥עַר קָטֹ֖ן נֹהֵ֥ג בָּֽ⁠ם׃","wĕ⁠gá֤r zĕʼéb֙ ʻim-kė֔beş̂ wĕ⁠námé֖r ʻim-gĕ̇di֣y yirĕbá֑̇ẕ wĕ⁠ʻé֨gel ẇ⁠kĕpi֤yr ẇ⁠mĕriyʼ֙ yaẖĕdá̇֔w wĕ⁠na֥ʻar qátò֖n nòhé֥g báֽ̇⁠m׃"],[11,7,"וּ⁠פָרָ֤ה וָ⁠דֹב֙ תִּרְעֶ֔ינָה יַחְדָּ֖ו יִרְבְּצ֣וּ יַלְדֵי⁠הֶ֑ן וְ⁠אַרְיֵ֖ה כַּ⁠בָּקָ֥ר יֹֽאכַל־תֶּֽבֶן׃","ẇ⁠párá֤h wá⁠dòb֙ ţi̇rĕʻe֔ynáh yaẖĕdá֖̇w yirĕbĕ̇ẕ֣ẇ yalĕdéy⁠he֑n wĕ⁠ʼarĕyé֖h kȧ⁠bá̇qá֥r yòֽʼkal-ţėֽben׃"],[11,8,"וְ⁠שִֽׁעֲשַׁ֥ע יוֹנֵ֖ק עַל־חֻ֣ר פָּ֑תֶן וְ⁠עַל֙ מְאוּרַ֣ת צִפְעוֹנִ֔י גָּמ֖וּל יָד֥⁠וֹ הָדָֽה׃","wĕ⁠şǐֽʻàşǎ֥ʻ ywòné֖q ʻal-ẖu֣r pá֑̇ţen wĕ⁠ʻal֙ mĕʼẇra֣ţ ẕipĕʻwòni֔y gá̇m֖ẇl yád֥⁠wò hádáֽh׃"],[11,9,"לֹֽא־יָרֵ֥עוּ וְ⁠לֹֽא־יַשְׁחִ֖יתוּ בְּ⁠כָל־הַ֣ר קָדְשִׁ֑⁠י כִּֽי־מָלְאָ֣ה הָ⁠אָ֗רֶץ דֵּעָה֙ אֶת־יְהוָ֔ה כַּ⁠מַּ֖יִם לַ⁠יָּ֥ם מְכַסִּֽים׃פ","lòֽʼ-yáré֥ʻẇ wĕ⁠lòֽʼ-yaşĕ̌ẖi֖yţẇ bĕ̇⁠kál-ha֣r qádĕşǐ֑⁠y kiֽ̇y-málĕʼá֣h há⁠ʼá֗reẕ dé̇ʻáh֙ ʼeţ-yĕhwá֔h kȧ⁠mȧ֖yim la⁠yá֥̇m mĕkasiֽ̇ym׃p"],[11,10,"וְ⁠הָיָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא שֹׁ֣רֶשׁ יִשַׁ֗י אֲשֶׁ֤ר עֹמֵד֙ לְ⁠נֵ֣ס עַמִּ֔ים אֵלָ֖י⁠ו גּוֹיִ֣ם יִדְרֹ֑שׁוּ וְ⁠הָיְתָ֥ה מְנֻחָת֖⁠וֹ כָּבֽוֹד׃פ","wĕ⁠háyáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ şò֣̌reş̌ yişǎ֗y ʼàşě֤r ʻòméd֙ lĕ⁠né֣s ʻami̇֔ym ʼélá֖y⁠w ġwòyi֣m yidĕrò֑ş̌ẇ wĕ⁠háyĕţá֥h mĕnuẖáţ֖⁠wò ká̇bֽwòd׃p"],[11,11,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יוֹסִ֨יף אֲדֹנָ֤⁠י ׀ שֵׁנִית֙ יָד֔⁠וֹ לִ⁠קְנ֖וֹת אֶת־שְׁאָ֣ר עַמּ֑⁠וֹ אֲשֶׁ֣ר יִשָּׁאֵר֩ מֵ⁠אַשּׁ֨וּר וּ⁠מִ⁠מִּצְרַ֜יִם וּ⁠מִ⁠פַּתְר֣וֹס וּ⁠מִ⁠כּ֗וּשׁ וּ⁠מֵ⁠עֵילָ֤ם וּ⁠מִ⁠שִּׁנְעָר֙ וּ⁠מֵ֣⁠חֲמָ֔ת וּ⁠מֵ⁠אִיֵּ֖י הַ⁠יָּֽם׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ ywòsi֨yp ʼàdòná֤⁠y ׀ şé̌niyţ֙ yád֔⁠wò li⁠qĕn֖wòţ ʼeţ-şĕ̌ʼá֣r ʻaṁ֑⁠wò ʼàşě֣r yişá̇̌ʼér֩ mé⁠ʼaş̇̌֨ẇr ẇ⁠mi⁠mi̇ẕĕra֜yim ẇ⁠mi⁠pȧţĕr֣wòs ẇ⁠mi⁠k̇֗ẇş̌ ẇ⁠mé⁠ʻéylá֤m ẇ⁠mi⁠şi̇̌nĕʻár֙ ẇ⁠mé֣⁠ẖàmá֔ţ ẇ⁠mé⁠ʼiyé֖̇y ha⁠yáֽ̇m׃"],[11,12,"וְ⁠נָשָׂ֥א נֵס֙ לַ⁠גּוֹיִ֔ם וְ⁠אָסַ֖ף נִדְחֵ֣י יִשְׂרָאֵ֑ל וּ⁠נְפֻצ֤וֹת יְהוּדָה֙ יְקַבֵּ֔ץ מֵ⁠אַרְבַּ֖ע כַּנְפ֥וֹת הָ⁠אָֽרֶץ׃","wĕ⁠náşá֥̂ʼ nés֙ la⁠ġwòyi֔m wĕ⁠ʼása֖p nidĕẖé֣y yişĕ̂ráʼé֑l ẇ⁠nĕpuẕ֤wòţ yĕhẇdáh֙ yĕqabé̇֔ẕ mé⁠ʼarĕbȧ֖ʻ kȧnĕp֥wòţ há⁠ʼáֽreẕ׃"],[11,13,"וְ⁠סָ֨רָה֙ קִנְאַ֣ת אֶפְרַ֔יִם וְ⁠צֹרְרֵ֥י יְהוּדָ֖ה יִכָּרֵ֑תוּ אֶפְרַ֨יִם֙ לֹֽא־יְקַנֵּ֣א אֶת־יְהוּדָ֔ה וִֽ⁠יהוּדָ֖ה לֹֽא־יָצֹ֥ר אֶת־אֶפְרָֽיִם׃","wĕ⁠sá֨ráh֙ qinĕʼa֣ţ ʼepĕra֔yim wĕ⁠ẕòrĕré֥y yĕhẇdá֖h yiká̇ré֑ţẇ ʼepĕra֨yim֙ lòֽʼ-yĕqané֣̇ʼ ʼeţ-yĕhẇdá֔h wiֽ⁠yhẇdá֖h lòֽʼ-yáẕò֥r ʼeţ-ʼepĕráֽyim׃"],[11,14,"וְ⁠עָפ֨וּ בְ⁠כָתֵ֤ף פְּלִשְׁתִּים֙ יָ֔מָּ⁠ה יַחְדָּ֖ו יָבֹ֣זּוּ אֶת־בְּנֵי־קֶ֑דֶם אֱד֤וֹם וּ⁠מוֹאָב֙ מִשְׁל֣וֹח יָדָ֔⁠ם וּ⁠בְנֵ֥י עַמּ֖וֹן מִשְׁמַעְתָּֽ⁠ם׃","wĕ⁠ʻáp֨ẇ bĕ⁠káţé֤p pĕ̇lişĕ̌ţi̇ym֙ yá֔má̇⁠h yaẖĕdá֖̇w yábò֣żẇ ʼeţ-bĕ̇néy-qe֑dem ʼèd֤wòm ẇ⁠mwòʼáb֙ mişĕ̌l֣wòẖ yádá֔⁠m ẇ⁠bĕné֥y ʻaṁ֖wòn mişĕ̌maʻĕţáֽ̇⁠m׃"],[11,15,"וְ⁠הֶחֱרִ֣ים יְהוָ֗ה אֵ֚ת לְשׁ֣וֹן יָם־מִצְרַ֔יִם וְ⁠הֵנִ֥יף יָד֛⁠וֹ עַל־הַ⁠נָּהָ֖ר בַּ⁠עְיָ֣ם רוּח֑⁠וֹ וְ⁠הִכָּ֨⁠הוּ֙ לְ⁠שִׁבְעָ֣ה נְחָלִ֔ים וְ⁠הִדְרִ֖יךְ בַּ⁠נְּעָלִֽים׃","wĕ⁠heẖèri֣ym yĕhwá֗h ʼé֚ţ lĕş֣̌wòn yám-miẕĕra֔yim wĕ⁠héni֥yp yád֛⁠wò ʻal-ha⁠ná̇há֖r bȧ⁠ʻĕyá֣m rẇẖ֑⁠wò wĕ⁠hiká̇֨⁠hẇ֙ lĕ⁠şǐbĕʻá֣h nĕẖáli֔ym wĕ⁠hidĕri֖ykĕ bȧ⁠nĕ̇ʻáliֽym׃"],[11,16,"וְ⁠הָיְתָ֣ה מְסִלָּ֔ה לִ⁠שְׁאָ֣ר עַמּ֔⁠וֹ אֲשֶׁ֥ר יִשָּׁאֵ֖ר מֵֽ⁠אַשּׁ֑וּר כַּ⁠אֲשֶׁ֤ר הָֽיְתָה֙ לְ⁠יִשְׂרָאֵ֔ל בְּ⁠י֥וֹם עֲלֹת֖⁠וֹ מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠háyĕţá֣h mĕsilá̇֔h li⁠şĕ̌ʼá֣r ʻaṁ֔⁠wò ʼàşě֥r yişá̇̌ʼé֖r méֽ⁠ʼaş֑̇̌ẇr kȧ⁠ʼàşě֤r háֽyĕţáh֙ lĕ⁠yişĕ̂ráʼé֔l bĕ̇⁠y֥wòm ʻàlòţ֖⁠wò mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[12,1,"וְ⁠אָֽמַרְתָּ֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא אוֹדְ⁠ךָ֣ יְהוָ֔ה כִּ֥י אָנַ֖פְתָּ בִּ֑⁠י יָשֹׁ֥ב אַפְּ⁠ךָ֖ וּֽ⁠תְנַחֲמֵֽ⁠נִי׃","wĕ⁠ʼáֽmarĕţá̇֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ʼwòdĕ⁠ká֣ yĕhwá֔h ki֥̇y ʼána֖pĕţá̇ bi֑̇⁠y yáşò֥̌b ʼapĕ̇⁠ká֖ ẇֽ⁠ţĕnaẖàméֽ⁠niy׃"],[12,2,"הִנֵּ֨ה אֵ֧ל יְשׁוּעָתִ֛⁠י אֶבְטַ֖ח וְ⁠לֹ֣א אֶפְחָ֑ד כִּֽי־עָזִּ֤⁠י וְ⁠זִמְרָת֙ יָ֣הּ יְהוָ֔ה וַֽ⁠יְהִי־לִ֖⁠י לִֽ⁠ישׁוּעָֽה׃","hiné̇֨h ʼé֧l yĕş̌ẇʻáţi֛⁠y ʼebĕta֖ẖ wĕ⁠lò֣ʼ ʼepĕẖá֑d kiֽ̇y-ʻázi֤̇⁠y wĕ⁠zimĕráţ֙ yá֣ḣ yĕhwá֔h waֽ⁠yĕhiy-li֖⁠y liֽ⁠yş̌ẇʻáֽh׃"],[12,3,"וּ⁠שְׁאַבְתֶּם־מַ֖יִם בְּ⁠שָׂשׂ֑וֹן מִ⁠מַּעַיְנֵ֖י הַ⁠יְשׁוּעָֽה׃","ẇ⁠şĕ̌ʼabĕţėm-ma֖yim bĕ̇⁠şá̂ş֑̂wòn mi⁠mȧʻayĕné֖y ha⁠yĕş̌ẇʻáֽh׃"],[12,4,"וַ⁠אֲמַרְתֶּ֞ם בַּ⁠יּ֣וֹם הַ⁠ה֗וּא הוֹד֤וּ לַֽ⁠יהוָה֙ קִרְא֣וּ בִ⁠שְׁמ֔⁠וֹ הוֹדִ֥יעוּ בָֽ⁠עַמִּ֖ים עֲלִֽילֹתָ֑י⁠ו הַזְכִּ֕ירוּ כִּ֥י נִשְׂגָּ֖ב שְׁמֽ⁠וֹ׃","wa⁠ʼàmarĕţė֞m bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ hwòd֤ẇ laֽ⁠yhwáh֙ qirĕʼ֣ẇ bi⁠şĕ̌m֔⁠wò hwòdi֥yʻẇ báֽ⁠ʻami֖̇ym ʻàliֽylòţá֑y⁠w hazĕki̇֕yrẇ ki֥̇y nişĕ̂gá֖̇b şĕ̌mֽ⁠wò׃"],[12,5,"זַמְּר֣וּ יְהוָ֔ה כִּ֥י גֵא֖וּת עָשָׂ֑ה מידעת זֹ֖את בְּ⁠כָל־הָ⁠אָֽרֶץ׃","zamĕ̇r֣ẇ yĕhwá֔h ki֥̇y géʼ֖ẇţ ʻáşá֑̂h mydʻţ zò֖ʼţ bĕ̇⁠kál-há⁠ʼáֽreẕ׃"],[12,6,"צַהֲלִ֥י וָ⁠רֹ֖נִּי יוֹשֶׁ֣בֶת צִיּ֑וֹן כִּֽי־גָד֥וֹל בְּ⁠קִרְבֵּ֖⁠ךְ קְד֥וֹשׁ יִשְׂרָאֵֽל׃פ","ẕahàli֥y wá⁠rò֖ni̇y ywòşě֣beţ ẕiẏ֑wòn kiֽ̇y-gád֥wòl bĕ̇⁠qirĕbé֖̇⁠kĕ qĕd֥wòş̌ yişĕ̂ráʼéֽl׃p"],[13,1,"מַשָּׂ֖א בָּבֶ֑ל אֲשֶׁ֣ר חָזָ֔ה יְשַׁעְיָ֖הוּ בֶּן־אָמֽוֹץ׃","maşá֖̇̂ʼ bá̇be֑l ʼàşě֣r ẖázá֔h yĕşǎʻĕyá֖hẇ bėn-ʼámֽwòẕ׃"],[13,2,"עַ֤ל הַר־נִשְׁפֶּה֙ שְֽׂאוּ־נֵ֔ס הָרִ֥ימוּ ק֖וֹל לָ⁠הֶ֑ם הָנִ֣יפוּ יָ֔ד וְ⁠יָבֹ֖אוּ פִּתְחֵ֥י נְדִיבִֽים׃","ʻa֤l har-nişĕ̌pėh֙ şĕֽ̂ʼẇ-né֔s hári֥ymẇ q֖wòl lá⁠he֑m háni֣ypẇ yá֔d wĕ⁠yábò֖ʼẇ pi̇ţĕẖé֥y nĕdiybiֽym׃"],[13,3,"אֲנִ֥י צִוֵּ֖יתִי לִ⁠מְקֻדָּשָׁ֑⁠י גַּ֣ם קָרָ֤אתִי גִבּוֹרַ⁠י֙ לְ⁠אַפִּ֔⁠י עַלִּיזֵ֖י גַּאֲוָתִֽ⁠י׃","ʼàni֥y ẕiwé֖̇yţiy li⁠mĕqudá̇şá֑̌⁠y gȧ֣m qárá֤ʼţiy giḃwòra⁠y֙ lĕ⁠ʼapi̇֔⁠y ʻali̇yzé֖y gȧʼàwáţiֽ⁠y׃"],[13,4,"ק֥וֹל הָמ֛וֹן בֶּֽ⁠הָרִ֖ים דְּמ֣וּת עַם־רָ֑ב ק֠וֹל שְׁא֞וֹן מַמְלְכ֤וֹת גּוֹיִם֙ נֶֽאֱסָפִ֔ים יְהוָ֣ה צְבָא֔וֹת מְפַקֵּ֖ד צְבָ֥א מִלְחָמָֽה׃","q֥wòl hám֛wòn bėֽ⁠hári֖ym dĕ̇m֣ẇţ ʻam-rá֑b q֠wòl şĕ̌ʼ֞wòn mamĕlĕk֤wòţ ġwòyim֙ neֽʼèsápi֔ym yĕhwá֣h ẕĕbáʼ֔wòţ mĕpaqé֖̇d ẕĕbá֥ʼ milĕẖámáֽh׃"],[13,5,"בָּאִ֛ים מֵ⁠אֶ֥רֶץ מֶרְחָ֖ק מִ⁠קְצֵ֣ה הַ⁠שָּׁמָ֑יִם יְהוָה֙ וּ⁠כְלֵ֣י זַעְמ֔⁠וֹ לְ⁠חַבֵּ֖ל כָּל־הָ⁠אָֽרֶץ׃","bá̇ʼi֛ym mé⁠ʼe֥reẕ merĕẖá֖q mi⁠qĕẕé֣h ha⁠şá̇̌má֑yim yĕhwáh֙ ẇ⁠kĕlé֣y zaʻĕm֔⁠wò lĕ⁠ẖabé֖̇l ká̇l-há⁠ʼáֽreẕ׃"],[13,6,"הֵילִ֕ילוּ כִּ֥י קָר֖וֹב י֣וֹם יְהוָ֑ה כְּ⁠שֹׁ֖ד מִ⁠שַּׁדַּ֥י יָבֽוֹא׃","héyli֕ylẇ ki֥̇y qár֖wòb y֣wòm yĕhwá֑h kĕ̇⁠şò֖̌d mi⁠şȧ̌dȧ֥y yábֽwòʼ׃"],[13,7,"עַל־כֵּ֖ן כָּל־יָדַ֣יִם תִּרְפֶּ֑ינָה וְ⁠כָל־לְבַ֥ב אֱנ֖וֹשׁ יִמָּס׃","ʻal-ké֖̇n ká̇l-yáda֣yim ţi̇rĕpė֑ynáh wĕ⁠kál-lĕba֥b ʼèn֖wòş̌ yimá̇s׃"],[13,8,"וְֽ⁠נִבְהָ֓לוּ ׀ צִירִ֤ים וַֽ⁠חֲבָלִים֙ יֹֽאחֵז֔וּ⁠ן כַּ⁠יּוֹלֵדָ֖ה יְחִיל֑וּ⁠ן אִ֤ישׁ אֶל־רֵעֵ֨⁠הוּ֙ יִתְמָ֔הוּ פְּנֵ֥י לְהָבִ֖ים פְּנֵי⁠הֶֽם׃","wĕֽ⁠nibĕhá֓lẇ ׀ ẕiyri֤ym waֽ⁠ẖàbáliym֙ yòֽʼẖéz֔ẇ⁠n kȧ⁠ẏwòlédá֖h yĕẖiyl֑ẇ⁠n ʼi֤yş̌ ʼel-réʻé֨⁠hẇ֙ yiţĕmá֔hẇ pĕ̇né֥y lĕhábi֖ym pĕ̇néy⁠heֽm׃"],[13,9,"הִנֵּ֤ה יוֹם־יְהוָה֙ בָּ֔א אַכְזָרִ֥י וְ⁠עֶבְרָ֖ה וַ⁠חֲר֣וֹן אָ֑ף לָ⁠שׂ֤וּם הָ⁠אָ֨רֶץ֙ לְ⁠שַׁמָּ֔ה וְ⁠חַטָּאֶ֖י⁠הָ יַשְׁמִ֥יד מִמֶּֽ⁠נָּה׃","hiné֤̇h ywòm-yĕhwáh֙ bá̇֔ʼ ʼakĕzári֥y wĕ⁠ʻebĕrá֖h wa⁠ẖàr֣wòn ʼá֑p lá⁠ş֤̂ẇm há⁠ʼá֨reẕ֙ lĕ⁠şǎmá̇֔h wĕ⁠ẖatá̇ʼe֖y⁠há yaşĕ̌mi֥yd mimėֽ⁠ná̇h׃"],[13,10,"כִּֽי־כוֹכְבֵ֤י הַ⁠שָּׁמַ֨יִם֙ וּ⁠כְסִ֣ילֵי⁠הֶ֔ם לֹ֥א יָהֵ֖לּוּ אוֹרָ֑⁠ם חָשַׁ֤ךְ הַ⁠שֶּׁ֨מֶשׁ֙ בְּ⁠צֵאת֔⁠וֹ וְ⁠יָרֵ֖חַ לֹֽא־יַגִּ֥יהַ אוֹרֽ⁠וֹ׃","kiֽ̇y-kwòkĕbé֤y ha⁠şá̇̌ma֨yim֙ ẇ⁠kĕsi֣yléy⁠he֔m lò֥ʼ yáhé֖l̇ẇ ʼwòrá֑⁠m ẖáşǎ֤kĕ ha⁠şė̌֨meş̌֙ bĕ̇⁠ẕéʼţ֔⁠wò wĕ⁠yáré֖ẖa lòֽʼ-yagi֥̇yha ʼwòrֽ⁠wò׃"],[13,11,"וּ⁠פָקַדְתִּ֤י עַל־תֵּבֵל֙ רָעָ֔ה וְ⁠עַל־רְשָׁעִ֖ים עֲוֺנָ֑⁠ם וְ⁠הִשְׁבַּתִּי֙ גְּא֣וֹן זֵדִ֔ים וְ⁠גַאֲוַ֥ת עָרִיצִ֖ים אַשְׁפִּֽיל׃","ẇ⁠páqadĕţi֤̇y ʻal-ţé̇bél֙ ráʻá֔h wĕ⁠ʻal-rĕşá̌ʻi֖ym ʻàwֺná֑⁠m wĕ⁠hişĕ̌bȧţi̇y֙ gĕ̇ʼ֣wòn zédi֔ym wĕ⁠gaʼàwa֥ţ ʻáriyẕi֖ym ʼaşĕ̌piֽ̇yl׃"],[13,12,"אוֹקִ֥יר אֱנ֖וֹשׁ מִ⁠פָּ֑ז וְ⁠אָדָ֖ם מִ⁠כֶּ֥תֶם אוֹפִֽיר׃","ʼwòqi֥yr ʼèn֖wòş̌ mi⁠pá֑̇z wĕ⁠ʼádá֖m mi⁠kė֥ţem ʼwòpiֽyr׃"],[13,13,"עַל־כֵּן֙ שָׁמַ֣יִם אַרְגִּ֔יז וְ⁠תִרְעַ֥שׁ הָ⁠אָ֖רֶץ מִ⁠מְּקוֹמָ֑⁠הּ בְּ⁠עֶבְרַת֙ יְהוָ֣ה צְבָא֔וֹת וּ⁠בְ⁠י֖וֹם חֲר֥וֹן אַפּֽ⁠וֹ׃","ʻal-ké̇n֙ şá̌ma֣yim ʼarĕgi̇֔yz wĕ⁠ţirĕʻa֥ş̌ há⁠ʼá֖reẕ mi⁠mĕ̇qwòmá֑⁠ḣ bĕ̇⁠ʻebĕraţ֙ yĕhwá֣h ẕĕbáʼ֔wòţ ẇ⁠bĕ⁠y֖wòm ẖàr֥wòn ʼaṗֽ⁠wò׃"],[13,14,"וְ⁠הָיָה֙ כִּ⁠צְבִ֣י מֻדָּ֔ח וּ⁠כְ⁠צֹ֖אן וְ⁠אֵ֣ין מְקַבֵּ֑ץ אִ֤ישׁ אֶל־עַמּ⁠וֹ֙ יִפְנ֔וּ וְ⁠אִ֥ישׁ אֶל־אַרְצ֖⁠וֹ יָנֽוּסוּ׃","wĕ⁠háyáh֙ ki̇⁠ẕĕbi֣y mudá̇֔ẖ ẇ⁠kĕ⁠ẕò֖ʼn wĕ⁠ʼé֣yn mĕqabé֑̇ẕ ʼi֤yş̌ ʼel-ʻaṁ⁠wò֙ yipĕn֔ẇ wĕ⁠ʼi֥yş̌ ʼel-ʼarĕẕ֖⁠wò yánֽẇsẇ׃"],[13,15,"כָּל־הַ⁠נִּמְצָ֖א יִדָּקֵ֑ר וְ⁠כָל־הַ⁠נִּסְפֶּ֖ה יִפּ֥וֹל בֶּ⁠חָֽרֶב׃","ká̇l-ha⁠ni̇mĕẕá֖ʼ yidá̇qé֑r wĕ⁠kál-ha⁠ni̇sĕpė֖h yiṗ֥wòl bė⁠ẖáֽreb׃"],[13,16,"וְ⁠עֹלְלֵי⁠הֶ֥ם יְרֻטְּשׁ֖וּ לְ⁠עֵֽינֵי⁠הֶ֑ם יִשַּׁ֨סּוּ֙ בָּֽתֵּי⁠הֶ֔ם וּ⁠נְשֵׁי⁠הֶ֖ם תשגלנה׃","wĕ⁠ʻòlĕléy⁠he֥m yĕrutĕ̇ş֖̌ẇ lĕ⁠ʻéֽynéy⁠he֑m yişȧ̌֨ṡẇ֙ báֽ̇ţé̇y⁠he֔m ẇ⁠nĕşé̌y⁠he֖m ţşglnh׃"],[13,17,"הִנְ⁠נִ֛י מֵעִ֥יר עֲלֵי⁠הֶ֖ם אֶת־מָדָ֑י אֲשֶׁר־כֶּ֨סֶף֙ לֹ֣א יַחְשֹׁ֔בוּ וְ⁠זָהָ֖ב לֹ֥א יַחְפְּצוּ־בֽ⁠וֹ׃","hinĕ⁠ni֛y méʻi֥yr ʻàléy⁠he֖m ʼeţ-mádá֑y ʼàşěr-kė֨sep֙ lò֣ʼ yaẖĕşò̌֔bẇ wĕ⁠záhá֖b lò֥ʼ yaẖĕpĕ̇ẕẇ-bֽ⁠wò׃"],[13,18,"וּ⁠קְשָׁת֖וֹת נְעָרִ֣ים תְּרַטַּ֑שְׁנָה וּ⁠פְרִי־בֶ֨טֶן֙ לֹ֣א יְרַחֵ֔מוּ עַל־בָּנִ֖ים לֹֽא־תָח֥וּס עֵינָֽ⁠ם׃","ẇ⁠qĕşá̌ţ֖wòţ nĕʻári֣ym ţĕ̇ratȧ֑şĕ̌náh ẇ⁠pĕriy-be֨ten֙ lò֣ʼ yĕraẖé֔mẇ ʻal-bá̇ni֖ym lòֽʼ-ţáẖ֥ẇs ʻéynáֽ⁠m׃"],[13,19,"וְ⁠הָיְתָ֤ה בָבֶל֙ צְבִ֣י מַמְלָכ֔וֹת תִּפְאֶ֖רֶת גְּא֣וֹן כַּשְׂדִּ֑ים כְּ⁠מַהְפֵּכַ֣ת אֱלֹהִ֔ים אֶת־סְדֹ֖ם וְ⁠אֶת־עֲמֹרָֽה׃","wĕ⁠háyĕţá֤h bábel֙ ẕĕbi֣y mamĕlák֔wòţ ţi̇pĕʼe֖reţ gĕ̇ʼ֣wòn kȧşĕ̂di֑̇ym kĕ̇⁠mahĕpé̇ka֣ţ ʼèlòhi֔ym ʼeţ-sĕdò֖m wĕ⁠ʼeţ-ʻàmòráֽh׃"],[13,20,"לֹֽא־תֵשֵׁ֣ב לָ⁠נֶ֔צַח וְ⁠לֹ֥א תִשְׁכֹּ֖ן עַד־דּ֣וֹר וָ⁠ד֑וֹר וְ⁠לֹֽא־יַהֵ֥ל שָׁם֙ עֲרָבִ֔י וְ⁠רֹעִ֖ים לֹא־יַרְבִּ֥צוּ שָֽׁם׃","lòֽʼ-ţéşé֣̌b lá⁠ne֔ẕaẖ wĕ⁠lò֥ʼ ţişĕ̌kò֖̇n ʻad-ḋ֣wòr wá⁠d֑wòr wĕ⁠lòֽʼ-yahé֥l şá̌m֙ ʻàrábi֔y wĕ⁠ròʻi֖ym lòʼ-yarĕbi֥̇ẕẇ şáֽ̌m׃"],[13,21,"וְ⁠רָבְצוּ־שָׁ֣ם צִיִּ֔ים וּ⁠מָלְא֥וּ בָתֵּי⁠הֶ֖ם אֹחִ֑ים וְ⁠שָׁ֤כְנוּ שָׁם֙ בְּנ֣וֹת יַֽעֲנָ֔ה וּ⁠שְׂעִירִ֖ים יְרַקְּדוּ־שָֽׁם׃","wĕ⁠rábĕẕẇ-şá֣̌m ẕiyi̇֔ym ẇ⁠málĕʼ֥ẇ báţé̇y⁠he֖m ʼòẖi֑ym wĕ⁠şá֤̌kĕnẇ şá̌m֙ bĕ̇n֣wòţ yaֽʻàná֔h ẇ⁠şĕ̂ʻiyri֖ym yĕraqĕ̇dẇ-şáֽ̌m׃"],[13,22,"וְ⁠עָנָ֤ה אִיִּים֙ בְּ⁠אַלְמנוֹתָ֔י⁠ו וְ⁠תַנִּ֖ים בְּ⁠הֵ֣יכְלֵי עֹ֑נֶג וְ⁠קָר֤וֹב לָ⁠בוֹא֙ עִתָּ֔⁠הּ וְ⁠יָמֶ֖י⁠הָ לֹ֥א יִמָּשֵֽׁכוּ׃","wĕ⁠ʻáná֤h ʼiyi̇ym֙ bĕ̇⁠ʼalĕmnwòţá֔y⁠w wĕ⁠ţani֖̇ym bĕ̇⁠hé֣ykĕléy ʻò֑neg wĕ⁠qár֤wòb lá⁠bwòʼ֙ ʻiţá̇֔⁠ḣ wĕ⁠yáme֖y⁠há lò֥ʼ yimá̇şéֽ̌kẇ׃"],[14,1,"כִּי֩ יְרַחֵ֨ם יְהוָ֜ה אֶֽת־יַעֲקֹ֗ב וּ⁠בָחַ֥ר עוֹד֙ בְּ⁠יִשְׂרָאֵ֔ל וְ⁠הִנִּיחָ֖⁠ם עַל־אַדְמָתָ֑⁠ם וְ⁠נִלְוָ֤ה הַ⁠גֵּר֙ עֲלֵי⁠הֶ֔ם וְ⁠נִסְפְּח֖וּ עַל־בֵּ֥ית יַעֲקֹֽב׃","ki̇y֩ yĕraẖé֨m yĕhwá֜h ʼeֽţ-yaʻàqò֗b ẇ⁠báẖa֥r ʻwòd֙ bĕ̇⁠yişĕ̂ráʼé֔l wĕ⁠hini̇yẖá֖⁠m ʻal-ʼadĕmáţá֑⁠m wĕ⁠nilĕwá֤h ha⁠gé̇r֙ ʻàléy⁠he֔m wĕ⁠nisĕpĕ̇ẖ֖ẇ ʻal-bé֥̇yţ yaʻàqòֽb׃"],[14,2,"וּ⁠לְקָח֣וּ⁠ם עַמִּים֮ וֶ⁠הֱבִיא֣וּ⁠ם אֶל־מְקוֹמָ⁠ם֒ וְ⁠הִֽתְנַחֲל֣וּ⁠ם בֵּֽית־יִשְׂרָאֵ֗ל עַ֚ל אַדְמַ֣ת יְהוָ֔ה לַ⁠עֲבָדִ֖ים וְ⁠לִ⁠שְׁפָח֑וֹת וְ⁠הָיוּ֙ שֹׁבִ֣ים לְ⁠שֹֽׁבֵי⁠הֶ֔ם וְ⁠רָד֖וּ בְּ⁠נֹגְשֵׂי⁠הֶֽם׃ס","ẇ⁠lĕqáẖ֣ẇ⁠m ʻami̇ym֮ we⁠hèbiyʼ֣ẇ⁠m ʼel-mĕqwòmá⁠m֒ wĕ⁠hiֽţĕnaẖàl֣ẇ⁠m béֽ̇yţ-yişĕ̂ráʼé֗l ʻa֚l ʼadĕma֣ţ yĕhwá֔h la⁠ʻàbádi֖ym wĕ⁠li⁠şĕ̌páẖ֑wòţ wĕ⁠háyẇ֙ şò̌bi֣ym lĕ⁠şòֽ̌béy⁠he֔m wĕ⁠rád֖ẇ bĕ̇⁠nògĕşé̂y⁠heֽm׃s"],[14,3,"וְ⁠הָיָ֗ה בְּ⁠י֨וֹם הָנִ֤יחַ יְהוָה֙ לְ⁠ךָ֔ מֵֽ⁠עָצְבְּ⁠ךָ֖ וּ⁠מֵ⁠רָגְזֶ֑⁠ךָ וּ⁠מִן־הָ⁠עֲבֹדָ֥ה הַ⁠קָּשָׁ֖ה אֲשֶׁ֥ר עֻבַּד־בָּֽ⁠ךְ׃","wĕ⁠háyá֗h bĕ̇⁠y֨wòm háni֤yẖa yĕhwáh֙ lĕ⁠ká֔ méֽ⁠ʻáẕĕbĕ̇⁠ká֖ ẇ⁠mé⁠rágĕze֑⁠ká ẇ⁠min-há⁠ʻàbòdá֥h ha⁠qá̇şá֖̌h ʼàşě֥r ʻubȧd-báֽ̇⁠kĕ׃"],[14,4,"וְ⁠נָשָׂ֜אתָ הַ⁠מָּשָׁ֥ל הַ⁠זֶּ֛ה עַל־מֶ֥לֶךְ בָּבֶ֖ל וְ⁠אָמָ֑רְתָּ אֵ֚יךְ שָׁבַ֣ת נֹגֵ֔שׂ שָׁבְתָ֖ה מַדְהֵבָֽה׃","wĕ⁠náşá̂֜ʼţá ha⁠má̇şá֥̌l ha⁠zė֛h ʻal-me֥lekĕ bá̇be֖l wĕ⁠ʼámá֑rĕţá̇ ʼé֚ykĕ şá̌ba֣ţ nògé֔ş̂ şá̌bĕţá֖h madĕhébáֽh׃"],[14,5,"שָׁבַ֥ר יְהוָ֖ה מַטֵּ֣ה רְשָׁעִ֑ים שֵׁ֖בֶט מֹשְׁלִֽים׃","şá̌ba֥r yĕhwá֖h maté֣̇h rĕşá̌ʻi֑ym şé֖̌bet mòşĕ̌liֽym׃"],[14,6,"מַכֶּ֤ה עַמִּים֙ בְּ⁠עֶבְרָ֔ה מַכַּ֖ת בִּלְתִּ֣י סָרָ֑ה רֹדֶ֤ה בָ⁠אַף֙ גּוֹיִ֔ם מֻרְדָּ֖ף בְּלִ֥י חָשָֽׂךְ׃","makė֤h ʻami̇ym֙ bĕ̇⁠ʻebĕrá֔h makȧ֖ţ bi̇lĕţi֣̇y sárá֑h ròde֤h bá⁠ʼap֙ ġwòyi֔m murĕdá֖̇p bĕ̇li֥y ẖáşáֽ̂kĕ׃"],[14,7,"נָ֥חָה שָׁקְטָ֖ה כָּל־הָ⁠אָ֑רֶץ פָּצְח֖וּ רִנָּֽה׃","ná֥ẖáh şá̌qĕtá֖h ká̇l-há⁠ʼá֑reẕ pá̇ẕĕẖ֖ẇ rináֽ̇h׃"],[14,8,"גַּם־בְּרוֹשִׁ֛ים שָׂמְח֥וּ לְ⁠ךָ֖ אַרְזֵ֣י לְבָנ֑וֹן מֵ⁠אָ֣ז שָׁכַ֔בְתָּ לֹֽא־יַעֲלֶ֥ה הַ⁠כֹּרֵ֖ת עָלֵֽי⁠נוּ׃","gȧm-bĕ̇rwòşǐ֛ym şá̂mĕẖ֥ẇ lĕ⁠ká֖ ʼarĕzé֣y lĕbán֑wòn mé⁠ʼá֣z şá̌ka֔bĕţá̇ lòֽʼ-yaʻàle֥h ha⁠kò̇ré֖ţ ʻáléֽy⁠nẇ׃"],[14,9,"שְׁא֗וֹל מִ⁠תַּ֛חַת רָגְזָ֥ה לְ⁠ךָ֖ לִ⁠קְרַ֣את בּוֹאֶ֑⁠ךָ עוֹרֵ֨ר לְ⁠ךָ֤ רְפָאִים֙ כָּל־עַתּ֣וּדֵי אָ֔רֶץ הֵקִים֙ מִ⁠כִּסְאוֹתָ֔⁠ם כֹּ֖ל מַלְכֵ֥י גוֹיִֽם׃","şĕ̌ʼ֗wòl mi⁠ţȧ֛ẖaţ rágĕzá֥h lĕ⁠ká֖ li⁠qĕra֣ʼţ ḃwòʼe֑⁠ká ʻwòré֨r lĕ⁠ká֤ rĕpáʼiym֙ ká̇l-ʻaţ֣̇ẇdéy ʼá֔reẕ héqiym֙ mi⁠ki̇sĕʼwòţá֔⁠m kò֖̇l malĕké֥y gwòyiֽm׃"],[14,10,"כֻּלָּ֣⁠ם יַֽעֲנ֔וּ וְ⁠יֹאמְר֖וּ אֵלֶ֑י⁠ךָ גַּם־אַתָּ֛ה חֻלֵּ֥יתָ כָמ֖וֹ⁠נוּ אֵלֵ֥י⁠נוּ נִמְשָֽׁלְתָּ׃","ku̇lá֣̇⁠m yaֽʻàn֔ẇ wĕ⁠yòʼmĕr֖ẇ ʼéle֑y⁠ká gȧm-ʼaţá֛̇h ẖulé֥̇yţá kám֖wò⁠nẇ ʼélé֥y⁠nẇ nimĕşáֽ̌lĕţá̇׃"],[14,11,"הוּרַ֥ד שְׁא֛וֹל גְּאוֹנֶ֖⁠ךָ הֶמְיַ֣ת נְבָלֶ֑י⁠ךָ תַּחְתֶּ֨י⁠ךָ֙ יֻצַּ֣ע רִמָּ֔ה וּ⁠מְכַסֶּ֖י⁠ךָ תּוֹלֵעָֽה׃","hẇra֥d şĕ̌ʼ֛wòl gĕ̇ʼwòne֖⁠ká hemĕya֣ţ nĕbále֑y⁠ká ţȧẖĕţė֨y⁠ká֙ yuẕȧ֣ʻ rimá̇֔h ẇ⁠mĕkasė֖y⁠ká ţ̇wòléʻáֽh׃"],[14,12,"אֵ֛יךְ נָפַ֥לְתָּ מִ⁠שָּׁמַ֖יִם הֵילֵ֣ל בֶּן־שָׁ֑חַר נִגְדַּ֣עְתָּ לָ⁠אָ֔רֶץ חוֹלֵ֖שׁ עַל־גּוֹיִֽם׃","ʼé֛ykĕ nápa֥lĕţá̇ mi⁠şá̇̌ma֖yim héylé֣l bėn-şá֑̌ẖar nigĕdȧ֣ʻĕţá̇ lá⁠ʼá֔reẕ ẖwòlé֖ş̌ ʻal-ġwòyiֽm׃"],[14,13,"וְ⁠אַתָּ֞ה אָמַ֤רְתָּ בִֽ⁠לְבָבְ⁠ךָ֙ הַ⁠שָּׁמַ֣יִם אֶֽעֱלֶ֔ה מִ⁠מַּ֥עַל לְ⁠כֽוֹכְבֵי־אֵ֖ל אָרִ֣ים כִּסְאִ֑⁠י וְ⁠אֵשֵׁ֥ב בְּ⁠הַר־מוֹעֵ֖ד בְּ⁠יַרְכְּתֵ֥י צָפֽוֹן׃","wĕ⁠ʼaţá̇֞h ʼáma֤rĕţá̇ biֽ⁠lĕbábĕ⁠ká֙ ha⁠şá̇̌ma֣yim ʼeֽʻèle֔h mi⁠mȧ֥ʻal lĕ⁠kֽwòkĕbéy-ʼé֖l ʼári֣ym ki̇sĕʼi֑⁠y wĕ⁠ʼéşé֥̌b bĕ̇⁠har-mwòʻé֖d bĕ̇⁠yarĕkĕ̇ţé֥y ẕápֽwòn׃"],[14,14,"אֶעֱלֶ֖ה עַל־בָּ֣מֳתֵי עָ֑ב אֶדַּמֶּ֖ה לְ⁠עֶלְיֽוֹן׃","ʼeʻèle֖h ʻal-bá֣̇moţéy ʻá֑b ʼedȧmė֖h lĕ⁠ʻelĕyֽwòn׃"],[14,15,"אַ֧ךְ אֶל־שְׁא֛וֹל תּוּרָ֖ד אֶל־יַרְכְּתֵי־בֽוֹר׃","ʼa֧kĕ ʼel-şĕ̌ʼ֛wòl ţ̇ẇrá֖d ʼel-yarĕkĕ̇ţéy-bֽwòr׃"],[14,16,"רֹאֶ֨י⁠ךָ֙ אֵלֶ֣י⁠ךָ יַשְׁגִּ֔יחוּ אֵלֶ֖י⁠ךָ יִתְבּוֹנָ֑נוּ הֲ⁠זֶ֤ה הָ⁠אִישׁ֙ מַרְגִּ֣יז הָ⁠אָ֔רֶץ מַרְעִ֖ישׁ מַמְלָכֽוֹת׃","ròʼe֨y⁠ká֙ ʼéle֣y⁠ká yaşĕ̌gi̇֔yẖẇ ʼéle֖y⁠ká yiţĕḃwòná֑nẇ hà⁠ze֤h há⁠ʼiyş̌֙ marĕgi֣̇yz há⁠ʼá֔reẕ marĕʻi֖yş̌ mamĕlákֽwòţ׃"],[14,17,"שָׂ֥ם תֵּבֵ֛ל כַּ⁠מִּדְבָּ֖ר וְ⁠עָרָ֣י⁠ו הָרָ֑ס אֲסִירָ֖י⁠ו לֹא־פָ֥תַח בָּֽיְתָ⁠ה׃","şá֥̂m ţé̇bé֛l kȧ⁠mi̇dĕbá֖̇r wĕ⁠ʻárá֣y⁠w hárá֑s ʼàsiyrá֖y⁠w lòʼ-pá֥ţaẖ báֽ̇yĕţá⁠h׃"],[14,18,"כָּל־מַלְכֵ֥י גוֹיִ֖ם כֻּלָּ֑⁠ם שָׁכְב֥וּ בְ⁠כָב֖וֹד אִ֥ישׁ בְּ⁠בֵיתֽ⁠וֹ׃","ká̇l-malĕké֥y gwòyi֖m ku̇lá֑̇⁠m şá̌kĕb֥ẇ bĕ⁠káb֖wòd ʼi֥yş̌ bĕ̇⁠béyţֽ⁠wò׃"],[14,19,"וְ⁠אַתָּ֞ה הָשְׁלַ֤כְתָּ מִֽ⁠קִּבְרְ⁠ךָ֙ כְּ⁠נֵ֣צֶר נִתְעָ֔ב לְב֥וּשׁ הֲרֻגִ֖ים מְטֹ֣עֲנֵי חָ֑רֶב יוֹרְדֵ֥י אֶל־אַבְנֵי־ב֖וֹר כְּ⁠פֶ֥גֶר מוּבָֽס׃","wĕ⁠ʼaţá̇֞h háşĕ̌la֤kĕţá̇ miֽ⁠qi̇bĕrĕ⁠ká֙ kĕ̇⁠né֣ẕer niţĕʻá֔b lĕb֥ẇş̌ hàrugi֖ym mĕtò֣ʻànéy ẖá֑reb ywòrĕdé֥y ʼel-ʼabĕnéy-b֖wòr kĕ̇⁠pe֥ger mẇbáֽs׃"],[14,20,"לֹֽא־תֵחַ֤ד אִתָּ⁠ם֙ בִּ⁠קְבוּרָ֔ה כִּֽי־אַרְצְ⁠ךָ֥ שִׁחַ֖תָּ עַמְּ⁠ךָ֣ הָרָ֑גְתָּ לֹֽא־יִקָּרֵ֥א לְ⁠עוֹלָ֖ם זֶ֥רַע מְרֵעִֽים׃","lòֽʼ-ţéẖa֤d ʼiţá̇⁠m֙ bi̇⁠qĕbẇrá֔h kiֽ̇y-ʼarĕẕĕ⁠ká֥ şǐẖa֖ţá̇ ʻamĕ̇⁠ká֣ hárá֑gĕţá̇ lòֽʼ-yiqá̇ré֥ʼ lĕ⁠ʻwòlá֖m ze֥raʻ mĕréʻiֽym׃"],[14,21,"הָכִ֧ינוּ לְ⁠בָנָ֛י⁠ו מַטְבֵּ֖חַ בַּ⁠עֲוֺ֣ן אֲבוֹתָ֑⁠ם בַּל־יָקֻ֨מוּ֙ וְ⁠יָ֣רְשׁוּ אָ֔רֶץ וּ⁠מָלְא֥וּ פְנֵֽי־תֵבֵ֖ל עָרִֽים׃","háki֧ynẇ lĕ⁠báná֛y⁠w matĕbé֖̇ẖa bȧ⁠ʻàwֺ֣n ʼàbwòţá֑⁠m bȧl-yáqu֨mẇ֙ wĕ⁠yá֣rĕş̌ẇ ʼá֔reẕ ẇ⁠málĕʼ֥ẇ pĕnéֽy-ţébé֖l ʻáriֽym׃"],[14,22,"וְ⁠קַמְתִּ֣י עֲלֵי⁠הֶ֔ם נְאֻ֖ם יְהוָ֣ה צְבָא֑וֹת וְ⁠הִכְרַתִּ֨י לְ⁠בָבֶ֜ל שֵׁ֥ם וּ⁠שְׁאָ֛ר וְ⁠נִ֥ין וָ⁠נֶ֖כֶד נְאֻם־יְהוָֽה׃","wĕ⁠qamĕţi֣̇y ʻàléy⁠he֔m nĕʼu֖m yĕhwá֣h ẕĕbáʼ֑wòţ wĕ⁠hikĕraţi̇֨y lĕ⁠bábe֜l şé֥̌m ẇ⁠şĕ̌ʼá֛r wĕ⁠ni֥yn wá⁠ne֖ked nĕʼum-yĕhwáֽh׃"],[14,23,"וְ⁠שַׂמְתִּ֛י⁠הָ לְ⁠מוֹרַ֥שׁ קִפֹּ֖ד וְ⁠אַגְמֵי־מָ֑יִם וְ⁠טֵֽאטֵאתִ֨י⁠הָ֙ בְּ⁠מַטְאֲטֵ֣א הַשְׁמֵ֔ד נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃פ","wĕ⁠şâmĕţi֛̇y⁠há lĕ⁠mwòra֥ş̌ qipò֖̇d wĕ⁠ʼagĕméy-má֑yim wĕ⁠téֽʼtéʼţi֨y⁠há֙ bĕ̇⁠matĕʼàté֣ʼ haşĕ̌mé֔d nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃p"],[14,24,"נִשְׁבַּ֛ע יְהוָ֥ה צְבָא֖וֹת לֵ⁠אמֹ֑ר אִם־לֹ֞א כַּ⁠אֲשֶׁ֤ר דִּמִּ֨יתִי֙ כֵּ֣ן הָיָ֔תָה וְ⁠כַ⁠אֲשֶׁ֥ר יָעַ֖צְתִּי הִ֥יא תָקֽוּם׃","nişĕ̌bȧ֛ʻ yĕhwá֥h ẕĕbáʼ֖wòţ lé⁠ʼmò֑r ʼim-lò֞ʼ kȧ⁠ʼàşě֤r di̇mi̇֨yţiy֙ ké֣̇n háyá֔ţáh wĕ⁠ka⁠ʼàşě֥r yáʻa֖ẕĕţi̇y hi֥yʼ ţáqֽẇm׃"],[14,25,"לִ⁠שְׁבֹּ֤ר אַשּׁוּר֙ בְּ⁠אַרְצִ֔⁠י וְ⁠עַל־הָרַ֖⁠י אֲבוּסֶ֑⁠נּוּ וְ⁠סָ֤ר מֵֽ⁠עֲלֵי⁠הֶם֙ עֻלּ֔⁠וֹ וְ⁠סֻ֨בֳּל֔⁠וֹ מֵ⁠עַ֥ל שִׁכְמ֖⁠וֹ יָסֽוּר׃","li⁠şĕ̌bò֤̇r ʼaş̇̌ẇr֙ bĕ̇⁠ʼarĕẕi֔⁠y wĕ⁠ʻal-hára֖⁠y ʼàbẇse֑⁠ṅẇ wĕ⁠sá֤r méֽ⁠ʻàléy⁠hem֙ ʻul̇֔⁠wò wĕ⁠su֨bȯl֔⁠wò mé⁠ʻa֥l şǐkĕm֖⁠wò yásֽẇr׃"],[14,26,"זֹ֛את הָ⁠עֵצָ֥ה הַ⁠יְּעוּצָ֖ה עַל־כָּל־הָ⁠אָ֑רֶץ וְ⁠זֹ֛את הַ⁠יָּ֥ד הַ⁠נְּטוּיָ֖ה עַל־כָּל־הַ⁠גּוֹיִֽם׃","zò֛ʼţ há⁠ʻéẕá֥h ha⁠yĕ̇ʻẇẕá֖h ʻal-ká̇l-há⁠ʼá֑reẕ wĕ⁠zò֛ʼţ ha⁠yá֥̇d ha⁠nĕ̇tẇyá֖h ʻal-ká̇l-ha⁠ġwòyiֽm׃"],[14,27,"כִּֽי־יְהוָ֧ה צְבָא֛וֹת יָעָ֖ץ וּ⁠מִ֣י יָפֵ֑ר וְ⁠יָד֥⁠וֹ הַ⁠נְּטוּיָ֖ה וּֽ⁠מִ֥י יְשִׁיבֶֽ⁠נָּה׃פ","kiֽ̇y-yĕhwá֧h ẕĕbáʼ֛wòţ yáʻá֖ẕ ẇ⁠mi֣y yápé֑r wĕ⁠yád֥⁠wò ha⁠nĕ̇tẇyá֖h ẇֽ⁠mi֥y yĕşǐybeֽ⁠ná̇h׃p"],[14,28,"בִּ⁠שְׁנַת־מ֖וֹת הַ⁠מֶּ֣לֶךְ אָחָ֑ז הָיָ֖ה הַ⁠מַּשָּׂ֥א הַ⁠זֶּֽה׃","bi̇⁠şĕ̌naţ-m֖wòţ ha⁠mė֣lekĕ ʼáẖá֑z háyá֖h ha⁠mȧşá֥̇̂ʼ ha⁠zėֽh׃"],[14,29,"אַֽל־תִּשְׂמְחִ֤י פְלֶ֨שֶׁת֙ כֻּלֵּ֔⁠ךְ כִּ֥י נִשְׁבַּ֖ר שֵׁ֣בֶט מַכֵּ֑⁠ךְ כִּֽי־מִ⁠שֹּׁ֤רֶשׁ נָחָשׁ֙ יֵ֣צֵא צֶ֔פַע וּ⁠פִרְי֖⁠וֹ שָׂרָ֥ף מְעוֹפֵֽף׃","ʼaֽl-ţi̇şĕ̂mĕẖi֤y pĕle֨şěţ֙ ku̇lé̇֔⁠kĕ ki֥̇y nişĕ̌bȧ֖r şé֣̌bet maké֑̇⁠kĕ kiֽ̇y-mi⁠şò֤̇̌reş̌ náẖáş̌֙ yé֣ẕéʼ ẕe֔paʻ ẇ⁠pirĕy֖⁠wò şá̂rá֥p mĕʻwòpéֽp׃"],[14,30,"וְ⁠רָעוּ֙ בְּכוֹרֵ֣י דַלִּ֔ים וְ⁠אֶבְיוֹנִ֖ים לָ⁠בֶ֣טַח יִרְבָּ֑צוּ וְ⁠הֵמַתִּ֤י בָֽ⁠רָעָב֙ שָׁרְשֵׁ֔⁠ךְ וּ⁠שְׁאֵרִיתֵ֖⁠ךְ יַהֲרֹֽג׃","wĕ⁠ráʻẇ֙ bĕ̇kwòré֣y dali̇֔ym wĕ⁠ʼebĕywòni֖ym lá⁠be֣taẖ yirĕbá֑̇ẕẇ wĕ⁠hémaţi֤̇y báֽ⁠ráʻáb֙ şá̌rĕşé̌֔⁠kĕ ẇ⁠şĕ̌ʼériyţé֖⁠kĕ yahàròֽg׃"],[14,31,"הֵילִ֤ילִֽי שַׁ֨עַר֙ זַֽעֲקִי־עִ֔יר נָמ֖וֹג פְּלֶ֣שֶׁת כֻּלֵּ֑⁠ךְ כִּ֤י מִ⁠צָּפוֹן֙ עָשָׁ֣ן בָּ֔א וְ⁠אֵ֥ין בּוֹדֵ֖ד בְּ⁠מוֹעָדָֽי⁠ו׃","héyli֤yliֽy şǎ֨ʻar֙ zaֽʻàqiy-ʻi֔yr nám֖wòg pĕ̇le֣şěţ ku̇lé֑̇⁠kĕ ki֤̇y mi⁠ẕá̇pwòn֙ ʻáşá֣̌n bá̇֔ʼ wĕ⁠ʼé֥yn ḃwòdé֖d bĕ̇⁠mwòʻádáֽy⁠w׃"],[14,32,"וּ⁠מַֽה־יַּעֲנֶ֖ה מַלְאֲכֵי־ג֑וֹי כִּ֤י יְהוָה֙ יִסַּ֣ד צִיּ֔וֹן וּ⁠בָ֥⁠הּ יֶחֱס֖וּ עֲנִיֵּ֥י עַמּֽ⁠וֹ׃ס","ẇ⁠maֽh-yȧʻàne֖h malĕʼàkéy-g֑wòy ki֤̇y yĕhwáh֙ yisȧ֣d ẕiẏ֔wòn ẇ⁠bá֥⁠ḣ yeẖès֖ẇ ʻàniyé֥̇y ʻaṁֽ⁠wò׃s"],[15,1,"מַשָּׂ֖א מוֹאָ֑ב כִּ֠י בְּ⁠לֵ֞יל שֻׁדַּ֨ד עָ֤ר מוֹאָב֙ נִדְמָ֔ה כִּ֗י בְּ⁠לֵ֛יל שֻׁדַּ֥ד קִיר־מוֹאָ֖ב נִדְמָֽה׃","maşá֖̇̂ʼ mwòʼá֑b ki̇֠y bĕ̇⁠lé֞yl şǔdȧ֨d ʻá֤r mwòʼáb֙ nidĕmá֔h ki̇֗y bĕ̇⁠lé֛yl şǔdȧ֥d qiyr-mwòʼá֖b nidĕmáֽh׃"],[15,2,"עָלָ֨ה הַ⁠בַּ֧יִת וְ⁠דִיבֹ֛ן הַ⁠בָּמ֖וֹת לְ⁠בֶ֑כִי עַל־נְב֞וֹ וְ⁠עַ֤ל מֵֽידְבָא֙ מוֹאָ֣ב יְיֵלִ֔יל בְּ⁠כָל־רֹאשָׁ֣י⁠ו קָרְחָ֔ה כָּל־זָקָ֖ן גְּרוּעָֽה׃","ʻálá֨h ha⁠bȧ֧yiţ wĕ⁠diybò֛n ha⁠bá̇m֖wòţ lĕ⁠be֑kiy ʻal-nĕb֞wò wĕ⁠ʻa֤l méֽydĕbáʼ֙ mwòʼá֣b yĕyéli֔yl bĕ̇⁠kál-ròʼşá֣̌y⁠w qárĕẖá֔h ká̇l-záqá֖n gĕ̇rẇʻáֽh׃"],[15,3,"בְּ⁠חוּצֹתָ֖י⁠ו חָ֣גְרוּ שָׂ֑ק עַ֣ל גַּגּוֹתֶ֧י⁠הָ וּ⁠בִ⁠רְחֹבֹתֶ֛י⁠הָ כֻּלֹּ֥⁠ה יְיֵלִ֖יל יֹרֵ֥ד בַּ⁠בֶּֽכִי׃","bĕ̇⁠ẖẇẕòţá֖y⁠w ẖá֣gĕrẇ şá֑̂q ʻa֣l gȧġwòţe֧y⁠há ẇ⁠bi⁠rĕẖòbòţe֛y⁠há ku̇lò֥̇⁠h yĕyéli֖yl yòré֥d bȧ⁠bėֽkiy׃"],[15,4,"וַ⁠תִּזְעַ֤ק חֶשְׁבּוֹן֙ וְ⁠אֶלְעָלֵ֔ה עַד־יַ֖הַץ נִשְׁמַ֣ע קוֹלָ֑⁠ם עַל־כֵּ֗ן חֲלֻצֵ֤י מוֹאָב֙ יָרִ֔יעוּ נַפְשׁ֖⁠וֹ יָ֥רְעָה לּֽ⁠וֹ׃","wa⁠ţi̇zĕʻa֤q ẖeşĕ̌ḃwòn֙ wĕ⁠ʼelĕʻálé֔h ʻad-ya֖haẕ nişĕ̌ma֣ʻ qwòlá֑⁠m ʻal-ké̇֗n ẖàluẕé֤y mwòʼáb֙ yári֔yʻẇ napĕş֖̌⁠wò yá֥rĕʻáh lֽ̇⁠wò׃"],[15,5,"לִבִּ⁠י֙ לְ⁠מוֹאָ֣ב יִזְעָ֔ק בְּרִיחֶ֕⁠הָ עַד־צֹ֖עַר עֶגְלַ֣ת שְׁלִשִׁיָּ֑ה כִּ֣י ׀ מַעֲלֵ֣ה הַ⁠לּוּחִ֗ית בִּ⁠בְכִי֙ יַֽעֲלֶה־בּ֔⁠וֹ כִּ֚י דֶּ֣רֶךְ חוֹרֹנַ֔יִם זַעֲקַת־שֶׁ֖בֶר יְעֹעֵֽרוּ׃","libi̇⁠y֙ lĕ⁠mwòʼá֣b yizĕʻá֔q bĕ̇riyẖe֕⁠há ʻad-ẕò֖ʻar ʻegĕla֣ţ şĕ̌lişǐyá֑̇h ki֣̇y ׀ maʻàlé֣h ha⁠l̇ẇẖi֗yţ bi̇⁠bĕkiy֙ yaֽʻàleh-ḃ֔⁠wò ki֚̇y dė֣rekĕ ẖwòròna֔yim zaʻàqaţ-şě֖ber yĕʻòʻéֽrẇ׃"],[15,6,"כִּֽי־מֵ֥י נִמְרִ֖ים מְשַׁמּ֣וֹת יִֽהְי֑וּ כִּֽי־יָבֵ֤שׁ חָצִיר֙ כָּ֣לָה דֶ֔שֶׁא יֶ֖רֶק לֹ֥א הָיָֽה׃","kiֽ̇y-mé֥y nimĕri֖ym mĕşǎṁ֣wòţ yiֽhĕy֑ẇ kiֽ̇y-yábé֤ş̌ ẖáẕiyr֙ ká֣̇láh de֔şěʼ ye֖req lò֥ʼ háyáֽh׃"],[15,7,"עַל־כֵּ֖ן יִתְרָ֣ה עָשָׂ֑ה וּ⁠פְקֻדָּתָ֔⁠ם עַ֛ל נַ֥חַל הָ⁠עֲרָבִ֖ים יִשָּׂאֽוּ⁠ם׃","ʻal-ké֖̇n yiţĕrá֣h ʻáşá֑̂h ẇ⁠pĕqudá̇ţá֔⁠m ʻa֛l na֥ẖal há⁠ʻàrábi֖ym yişá̇̂ʼֽẇ⁠m׃"],[15,8,"כִּֽי־הִקִּ֥יפָה הַ⁠זְּעָקָ֖ה אֶת־גְּב֣וּל מוֹאָ֑ב עַד־אֶגְלַ֨יִם֙ יִלְלָתָ֔⁠הּ וּ⁠בְאֵ֥ר אֵילִ֖ים יִלְלָתָֽ⁠הּ׃","kiֽ̇y-hiqi֥̇ypáh ha⁠zĕ̇ʻáqá֖h ʼeţ-gĕ̇b֣ẇl mwòʼá֑b ʻad-ʼegĕla֨yim֙ yilĕláţá֔⁠ḣ ẇ⁠bĕʼé֥r ʼéyli֖ym yilĕláţáֽ⁠ḣ׃"],[15,9,"כִּ֣י מֵ֤י דִימוֹן֙ מָ֣לְאוּ דָ֔ם כִּֽי־אָשִׁ֥ית עַל־דִּימ֖וֹן נוֹסָפ֑וֹת לִ⁠פְלֵיטַ֤ת מוֹאָב֙ אַרְיֵ֔ה וְ⁠לִ⁠שְׁאֵרִ֖ית אֲדָמָֽה׃","ki֣̇y mé֤y diymwòn֙ má֣lĕʼẇ dá֔m kiֽ̇y-ʼáşǐ֥yţ ʻal-di̇ym֖wòn nwòsáp֑wòţ li⁠pĕléyta֤ţ mwòʼáb֙ ʼarĕyé֔h wĕ⁠li⁠şĕ̌ʼéri֖yţ ʼàdámáֽh׃"],[16,1,"שִׁלְחוּ־כַ֥ר מֹשֵֽׁל־אֶ֖רֶץ מִ⁠סֶּ֣לַע מִדְבָּ֑רָ⁠ה אֶל־הַ֖ר בַּת־צִיּֽוֹן׃","şǐlĕẖẇ-ka֥r mòşéֽ̌l-ʼe֖reẕ mi⁠sė֣laʻ midĕbá֑̇rá⁠h ʼel-ha֖r bȧţ-ẕiẏֽwòn׃"],[16,2,"וְ⁠הָיָ֥ה כְ⁠עוֹף־נוֹדֵ֖ד קֵ֣ן מְשֻׁלָּ֑ח תִּֽהְיֶ֨ינָה֙ בְּנ֣וֹת מוֹאָ֔ב מַעְבָּרֹ֖ת לְ⁠אַרְנֽוֹן׃","wĕ⁠háyá֥h kĕ⁠ʻwòp-nwòdé֖d qé֣n mĕşǔlá֑̇ẖ ţiֽ̇hĕye֨ynáh֙ bĕ̇n֣wòţ mwòʼá֔b maʻĕbá̇rò֖ţ lĕ⁠ʼarĕnֽwòn׃"],[16,3,"הביאו עֵצָה֙ עֲשׂ֣וּ פְלִילָ֔ה שִׁ֧יתִי כַ⁠לַּ֛יִל צִלֵּ֖⁠ךְ בְּ⁠ת֣וֹךְ צָהֳרָ֑יִם סַתְּרִי֙ נִדָּחִ֔ים נֹדֵ֖ד אַל־תְּגַלִּֽי׃","hbyʼw ʻéẕáh֙ ʻàş֣̂ẇ pĕliylá֔h şǐ֧yţiy ka⁠lȧ֛yil ẕilé֖̇⁠kĕ bĕ̇⁠ţ֣wòkĕ ẕáhorá֑yim saţĕ̇riy֙ nidá̇ẖi֔ym nòdé֖d ʼal-ţĕ̇galiֽ̇y׃"],[16,4,"יָג֤וּרוּ בָ⁠ךְ֙ נִדָּחַ֔⁠י מוֹאָ֛ב הֱוִי־סֵ֥תֶר לָ֖⁠מוֹ מִ⁠פְּנֵ֣י שׁוֹדֵ֑ד כִּֽי־אָפֵ֤ס הַ⁠מֵּץ֙ כָּ֣לָה שֹׁ֔ד תַּ֥מּוּ רֹמֵ֖ס מִן־הָ⁠אָֽרֶץ׃","yág֤ẇrẇ bá⁠kĕ֙ nidá̇ẖa֔⁠y mwòʼá֛b hèwiy-sé֥ţer lá֖⁠mwò mi⁠pĕ̇né֣y ş̌wòdé֑d kiֽ̇y-ʼápé֤s ha⁠mé̇ẕ֙ ká֣̇láh şò̌֔d ţȧ֥ṁẇ ròmé֖s min-há⁠ʼáֽreẕ׃"],[16,5,"וְ⁠הוּכַ֤ן בַּ⁠חֶ֨סֶד֙ כִּסֵּ֔א וְ⁠יָשַׁ֥ב עָלָ֛י⁠ו בֶּ⁠אֱמֶ֖ת בְּ⁠אֹ֣הֶל דָּוִ֑ד שֹׁפֵ֛ט וְ⁠דֹרֵ֥שׁ מִשְׁפָּ֖ט וּ⁠מְהִ֥ר צֶֽדֶק׃","wĕ⁠hẇka֤n bȧ⁠ẖe֨sed֙ ki̇sé̇֔ʼ wĕ⁠yáşǎ֥b ʻálá֛y⁠w bė⁠ʼème֖ţ bĕ̇⁠ʼò֣hel dá̇wi֑d şò̌pé֛t wĕ⁠dòré֥ş̌ mişĕ̌pá֖̇t ẇ⁠mĕhi֥r ẕeֽdeq׃"],[16,6,"שָׁמַ֥עְנוּ גְאוֹן־מוֹאָ֖ב גֵּ֣א מְאֹ֑ד גַּאֲוָת֧⁠וֹ וּ⁠גְאוֹנ֛⁠וֹ וְ⁠עֶבְרָת֖⁠וֹ לֹא־כֵ֥ן בַּדָּֽי⁠ו׃ס","şá̌ma֥ʻĕnẇ gĕʼwòn-mwòʼá֖b gé֣̇ʼ mĕʼò֑d gȧʼàwáţ֧⁠wò ẇ⁠gĕʼwòn֛⁠wò wĕ⁠ʻebĕráţ֖⁠wò lòʼ-ké֥n bȧdáֽ̇y⁠w׃s"],[16,7,"לָ⁠כֵ֗ן יְיֵלִ֥יל מוֹאָ֛ב לְ⁠מוֹאָ֖ב כֻּלֹּ֣⁠ה יְיֵלִ֑יל לַ⁠אֲשִׁישֵׁ֧י קִיר־חֲרֶ֛שֶׂת תֶּהְגּ֖וּ אַךְ־נְכָאִֽים׃","lá⁠ké֗n yĕyéli֥yl mwòʼá֛b lĕ⁠mwòʼá֖b ku̇lò֣̇⁠h yĕyéli֑yl la⁠ʼàşǐyşé֧̌y qiyr-ẖàre֛şêţ ţėhĕġ֖ẇ ʼakĕ-nĕkáʼiֽym׃"],[16,8,"כִּ֣י שַׁדְמוֹת֩ חֶשְׁבּ֨וֹן אֻמְלָ֜ל גֶּ֣פֶן שִׂבְמָ֗ה בַּעֲלֵ֤י גוֹיִם֙ הָלְמ֣וּ שְׂרוּקֶּ֔י⁠הָ עַד־יַעְזֵ֥ר נָגָ֖עוּ תָּ֣עוּ מִדְבָּ֑ר שְׁלֻ֣חוֹתֶ֔י⁠הָ נִטְּשׁ֖וּ עָ֥בְרוּ יָֽם׃","ki֣̇y şǎdĕmwòţ֩ ẖeşĕ̌ḃ֨wòn ʼumĕlá֜l gė֣pen şîbĕmá֗h bȧʻàlé֤y gwòyim֙ hálĕm֣ẇ şĕ̂rẇqė֔y⁠há ʻad-yaʻĕzé֥r nágá֖ʻẇ ţá֣̇ʻẇ midĕbá֑̇r şĕ̌lu֣ẖwòţe֔y⁠há nitĕ̇ş֖̌ẇ ʻá֥bĕrẇ yáֽm׃"],[16,9,"עַל־כֵּ֡ן אֶבְכֶּ֞ה בִּ⁠בְכִ֤י יַעְזֵר֙ גֶּ֣פֶן שִׂבְמָ֔ה אֲרַיָּ֨וֶ⁠ךְ֙ דִּמְעָתִ֔⁠י חֶשְׁבּ֖וֹן וְ⁠אֶלְעָלֵ֑ה כִּ֧י עַל־קֵיצֵ֛⁠ךְ וְ⁠עַל־קְצִירֵ֖⁠ךְ הֵידָ֥ד נָפָֽל׃","ʻal-ké̇֡n ʼebĕkė֞h bi̇⁠bĕki֤y yaʻĕzér֙ gė֣pen şîbĕmá֔h ʼàrayá̇֨we⁠kĕ֙ di̇mĕʻáţi֔⁠y ẖeşĕ̌ḃ֖wòn wĕ⁠ʼelĕʻálé֑h ki֧̇y ʻal-qéyẕé֛⁠kĕ wĕ⁠ʻal-qĕẕiyré֖⁠kĕ héydá֥d nápáֽl׃"],[16,10,"וְ⁠נֶאֱסַ֨ף שִׂמְחָ֤ה וָ⁠גִיל֙ מִן־הַ⁠כַּרְמֶ֔ל וּ⁠בַ⁠כְּרָמִ֥ים לֹֽא־יְרֻנָּ֖ן לֹ֣א יְרֹעָ֑ע יַ֗יִן בַּ⁠יְקָבִ֛ים לֹֽא־יִדְרֹ֥ךְ הַ⁠דֹּרֵ֖ךְ הֵידָ֥ד הִשְׁבַּֽתִּי׃","wĕ⁠neʼèsa֨p şîmĕẖá֤h wá⁠giyl֙ min-ha⁠kȧrĕme֔l ẇ⁠ba⁠kĕ̇rámi֥ym lòֽʼ-yĕruná֖̇n lò֣ʼ yĕròʻá֑ʻ ya֗yin bȧ⁠yĕqábi֛ym lòֽʼ-yidĕrò֥kĕ ha⁠dò̇ré֖kĕ héydá֥d hişĕ̌bȧֽţi̇y׃"],[16,11,"עַל־כֵּן֙ מֵעַ֣⁠י לְ⁠מוֹאָ֔ב כַּ⁠כִּנּ֖וֹר יֶֽהֱמ֑וּ וְ⁠קִרְבִּ֖⁠י לְ⁠קִ֥יר חָֽרֶשׂ׃","ʻal-ké̇n֙ méʻa֣⁠y lĕ⁠mwòʼá֔b kȧ⁠ki̇ṅ֖wòr yeֽhèm֑ẇ wĕ⁠qirĕbi֖̇⁠y lĕ⁠qi֥yr ẖáֽreş̂׃"],[16,12,"וְ⁠הָיָ֧ה כִֽי־נִרְאָ֛ה כִּֽי־נִלְאָ֥ה מוֹאָ֖ב עַל־הַ⁠בָּמָ֑ה וּ⁠בָ֧א אֶל־מִקְדָּשׁ֛⁠וֹ לְ⁠הִתְפַּלֵּ֖ל וְ⁠לֹ֥א יוּכָֽל׃","wĕ⁠háyá֧h kiֽy-nirĕʼá֛h kiֽ̇y-nilĕʼá֥h mwòʼá֖b ʻal-ha⁠bá̇má֑h ẇ⁠bá֧ʼ ʼel-miqĕdá̇ş֛̌⁠wò lĕ⁠hiţĕpȧlé֖̇l wĕ⁠lò֥ʼ yẇkáֽl׃"],[16,13,"זֶ֣ה הַ⁠דָּבָ֗ר אֲשֶׁ֨ר דִּבֶּ֧ר יְהוָ֛ה אֶל־מוֹאָ֖ב מֵ⁠אָֽז׃","ze֣h ha⁠dá̇bá֗r ʼàşě֨r di̇bė֧r yĕhwá֛h ʼel-mwòʼá֖b mé⁠ʼáֽz׃"],[16,14,"וְ⁠עַתָּ֗ה דִּבֶּ֣ר יְהוָה֮ לֵ⁠אמֹר֒ בְּ⁠שָׁלֹ֤שׁ שָׁנִים֙ כִּ⁠שְׁנֵ֣י שָׂכִ֔יר וְ⁠נִקְלָה֙ כְּב֣וֹד מוֹאָ֔ב בְּ⁠כֹ֖ל הֶ⁠הָמ֣וֹן הָ⁠רָ֑ב וּ⁠שְׁאָ֥ר מְעַ֛ט מִזְעָ֖ר ל֥וֹא כַבִּֽיר׃ס","wĕ⁠ʻaţá̇֗h di̇bė֣r yĕhwáh֮ lé⁠ʼmòr֒ bĕ̇⁠şá̌lò֤ş̌ şá̌niym֙ ki̇⁠şĕ̌né֣y şá̂ki֔yr wĕ⁠niqĕláh֙ kĕ̇b֣wòd mwòʼá֔b bĕ̇⁠kò֖l he⁠hám֣wòn há⁠rá֑b ẇ⁠şĕ̌ʼá֥r mĕʻa֛t mizĕʻá֖r l֥wòʼ kabiֽ̇yr׃s"],[17,1,"מַשָּׂ֖א דַּמָּ֑שֶׂק הִנֵּ֤ה דַמֶּ֨שֶׂק֙ מוּסָ֣ר מֵ⁠עִ֔יר וְ⁠הָיְתָ֖ה מְעִ֥י מַפָּלָֽה׃","maşá֖̇̂ʼ dȧmá֑̇şêq hiné֤̇h damė֨şêq֙ mẇsá֣r mé⁠ʻi֔yr wĕ⁠háyĕţá֖h mĕʻi֥y mapá̇láֽh׃"],[17,2,"עֲזֻב֖וֹת עָרֵ֣י עֲרֹעֵ֑ר לַ⁠עֲדָרִ֣ים תִּֽהְיֶ֔ינָה וְ⁠רָבְצ֖וּ וְ⁠אֵ֥ין מַחֲרִֽיד׃","ʻàzub֖wòţ ʻáré֣y ʻàròʻé֑r la⁠ʻàdári֣ym ţiֽ̇hĕye֔ynáh wĕ⁠rábĕẕ֖ẇ wĕ⁠ʼé֥yn maẖàriֽyd׃"],[17,3,"וְ⁠נִשְׁבַּ֤ת מִבְצָר֙ מֵֽ⁠אֶפְרַ֔יִם וּ⁠מַמְלָכָ֥ה מִ⁠דַּמֶּ֖שֶׂק וּ⁠שְׁאָ֣ר אֲרָ֑ם כִּ⁠כְב֤וֹד בְּנֵֽי־יִשְׂרָאֵל֙ יִֽהְי֔וּ נְאֻ֖ם יְהוָ֥ה צְבָאֽוֹת׃ס","wĕ⁠nişĕ̌bȧ֤ţ mibĕẕár֙ méֽ⁠ʼepĕra֔yim ẇ⁠mamĕláká֥h mi⁠dȧmė֖şêq ẇ⁠şĕ̌ʼá֣r ʼàrá֑m ki̇⁠kĕb֤wòd bĕ̇néֽy-yişĕ̂ráʼél֙ yiֽhĕy֔ẇ nĕʼu֖m yĕhwá֥h ẕĕbáʼֽwòţ׃s"],[17,4,"וְ⁠הָיָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא יִדַּ֖ל כְּב֣וֹד יַעֲקֹ֑ב וּ⁠מִשְׁמַ֥ן בְּשָׂר֖⁠וֹ יֵרָזֶֽה׃","wĕ⁠háyáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ yidȧ֖l kĕ̇b֣wòd yaʻàqò֑b ẇ⁠mişĕ̌ma֥n bĕ̇şá̂r֖⁠wò yérázeֽh׃"],[17,5,"וְ⁠הָיָ֗ה כֶּֽ⁠אֱסֹף֙ קָצִ֣יר קָמָ֔ה וּ⁠זְרֹע֖⁠וֹ שִׁבֳּלִ֣ים יִקְצ֑וֹר וְ⁠הָיָ֛ה כִּ⁠מְלַקֵּ֥ט שִׁבֳּלִ֖ים בְּ⁠עֵ֥מֶק רְפָאִֽים׃","wĕ⁠háyá֗h kėֽ⁠ʼèsòp֙ qáẕi֣yr qámá֔h ẇ⁠zĕròʻ֖⁠wò şǐbȯli֣ym yiqĕẕ֑wòr wĕ⁠háyá֛h ki̇⁠mĕlaqé֥̇t şǐbȯli֖ym bĕ̇⁠ʻé֥meq rĕpáʼiֽym׃"],[17,6,"וְ⁠נִשְׁאַר־בּ֤⁠וֹ עֽוֹלֵלֹת֙ כְּ⁠נֹ֣קֶף זַ֔יִת שְׁנַ֧יִם שְׁלֹשָׁ֛ה גַּרְגְּרִ֖ים בְּ⁠רֹ֣אשׁ אָמִ֑יר אַרְבָּעָ֣ה חֲמִשָּׁ֗ה בִּ⁠סְעִפֶ֨י⁠הָ֙ פֹּֽרִיָּ֔ה נְאֻם־יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃ס","wĕ⁠nişĕ̌ʼar-ḃ֤⁠wò ʻֽwòlélòţ֙ kĕ̇⁠nò֣qep za֔yiţ şĕ̌na֧yim şĕ̌lòşá֛̌h gȧrĕgĕ̇ri֖ym bĕ̇⁠rò֣ʼş̌ ʼámi֑yr ʼarĕbá̇ʻá֣h ẖàmişá̇̌֗h bi̇⁠sĕʻipe֨y⁠há֙ pòֽ̇riyá̇֔h nĕʼum-yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃s"],[17,7,"בַּ⁠יּ֣וֹם הַ⁠ה֔וּא יִשְׁעֶ֥ה הָ⁠אָדָ֖ם עַל־עֹשֵׂ֑⁠הוּ וְ⁠עֵינָ֕י⁠ו אֶל־קְד֥וֹשׁ יִשְׂרָאֵ֖ל תִּרְאֶֽינָה׃","bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ yişĕ̌ʻe֥h há⁠ʼádá֖m ʻal-ʻòşé֑̂⁠hẇ wĕ⁠ʻéyná֕y⁠w ʼel-qĕd֥wòş̌ yişĕ̂ráʼé֖l ţi̇rĕʼeֽynáh׃"],[17,8,"וְ⁠לֹ֣א יִשְׁעֶ֔ה אֶל־הַֽ⁠מִּזְבְּח֖וֹת מַעֲשֵׂ֣ה יָדָ֑י⁠ו וַ⁠אֲשֶׁ֨ר עָשׂ֤וּ אֶצְבְּעֹתָי⁠ו֙ לֹ֣א יִרְאֶ֔ה וְ⁠הָ⁠אֲשֵׁרִ֖ים וְ⁠הָ⁠חַמָּנִֽים׃","wĕ⁠lò֣ʼ yişĕ̌ʻe֔h ʼel-haֽ⁠mi̇zĕbĕ̇ẖ֖wòţ maʻàşé֣̂h yádá֑y⁠w wa⁠ʼàşě֨r ʻáş֤̂ẇ ʼeẕĕbĕ̇ʻòţáy⁠w֙ lò֣ʼ yirĕʼe֔h wĕ⁠há⁠ʼàşé̌ri֖ym wĕ⁠há⁠ẖamá̇niֽym׃"],[17,9,"בַּ⁠יּ֨וֹם הַ⁠ה֜וּא יִהְי֣וּ ׀ עָרֵ֣י מָעֻזּ֗⁠וֹ כַּ⁠עֲזוּבַ֤ת הַ⁠חֹ֨רֶשׁ֙ וְ⁠הָ֣⁠אָמִ֔יר אֲשֶׁ֣ר עָזְב֔וּ מִ⁠פְּנֵ֖י בְּנֵ֣י יִשְׂרָאֵ֑ל וְ⁠הָיְתָ֖ה שְׁמָמָֽה׃","bȧ⁠ẏ֨wòm ha⁠h֜ẇʼ yihĕy֣ẇ ׀ ʻáré֣y máʻuż֗⁠wò kȧ⁠ʻàzẇba֤ţ ha⁠ẖò֨reş̌֙ wĕ⁠há֣⁠ʼámi֔yr ʼàşě֣r ʻázĕb֔ẇ mi⁠pĕ̇né֖y bĕ̇né֣y yişĕ̂ráʼé֑l wĕ⁠háyĕţá֖h şĕ̌mámáֽh׃"],[17,10,"כִּ֤י שָׁכַ֨חַתְּ֙ אֱלֹהֵ֣י יִשְׁעֵ֔⁠ךְ וְ⁠צ֥וּר מָעֻזֵּ֖⁠ךְ לֹ֣א זָכָ֑רְתְּ עַל־כֵּ֗ן תִּטְּעִי֙ נִטְעֵ֣י נַעֲמָנִ֔ים וּ⁠זְמֹ֥רַת זָ֖ר תִּזְרָעֶֽ⁠נּוּ׃","ki֤̇y şá̌ka֨ẖaţĕ̇֙ ʼèlòhé֣y yişĕ̌ʻé֔⁠kĕ wĕ⁠ẕ֥ẇr máʻuzé֖̇⁠kĕ lò֣ʼ záká֑rĕţĕ̇ ʻal-ké̇֗n ţi̇tĕ̇ʻiy֙ nitĕʻé֣y naʻàmáni֔ym ẇ⁠zĕmò֥raţ zá֖r ţi̇zĕráʻeֽ⁠ṅẇ׃"],[17,11,"בְּ⁠י֤וֹם נִטְעֵ⁠ךְ֙ תְּשַׂגְשֵׂ֔גִי וּ⁠בַ⁠בֹּ֖קֶר זַרְעֵ֣⁠ךְ תַּפְרִ֑יחִי נֵ֥ד קָצִ֛יר בְּ⁠י֥וֹם נַחֲלָ֖ה וּ⁠כְאֵ֥ב אָנֽוּשׁ׃ס","bĕ̇⁠y֤wòm nitĕʻé⁠kĕ֙ ţĕ̇şâgĕşé̂֔giy ẇ⁠ba⁠bò֖̇qer zarĕʻé֣⁠kĕ ţȧpĕri֑yẖiy né֥d qáẕi֛yr bĕ̇⁠y֥wòm naẖàlá֖h ẇ⁠kĕʼé֥b ʼánֽẇş̌׃s"],[17,12,"ה֗וֹי הֲמוֹן֙ עַמִּ֣ים רַבִּ֔ים כַּ⁠הֲמ֥וֹת יַמִּ֖ים יֶהֱמָי֑וּ⁠ן וּ⁠שְׁא֣וֹן לְאֻמִּ֔ים כִּ⁠שְׁא֛וֹן מַ֥יִם כַּבִּירִ֖ים יִשָּׁאֽוּ⁠ן׃","h֗wòy hàmwòn֙ ʻami֣̇ym rabi̇֔ym kȧ⁠hàm֥wòţ yami֖̇ym yehèmáy֑ẇ⁠n ẇ⁠şĕ̌ʼ֣wòn lĕʼumi̇֔ym ki̇⁠şĕ̌ʼ֛wòn ma֥yim kȧbi̇yri֖ym yişá̇̌ʼֽẇ⁠n׃"],[17,13,"לְאֻמִּ֗ים כִּ⁠שְׁא֞וֹן מַ֤יִם רַבִּים֙ יִשָּׁא֔וּ⁠ן וְ⁠גָ֥עַר בּ֖⁠וֹ וְ⁠נָ֣ס מִ⁠מֶּרְחָ֑ק וְ⁠רֻדַּ֗ף כְּ⁠מֹ֤ץ הָרִים֙ לִ⁠פְנֵי־ר֔וּחַ וּ⁠כְ⁠גַלְגַּ֖ל לִ⁠פְנֵ֥י סוּפָֽה׃","lĕʼumi̇֗ym ki̇⁠şĕ̌ʼ֞wòn ma֤yim rabi̇ym֙ yişá̇̌ʼ֔ẇ⁠n wĕ⁠gá֥ʻar ḃ֖⁠wò wĕ⁠ná֣s mi⁠mėrĕẖá֑q wĕ⁠rudȧ֗p kĕ̇⁠mò֤ẕ háriym֙ li⁠pĕnéy-r֔ẇẖa ẇ⁠kĕ⁠galĕgȧ֖l li⁠pĕné֥y sẇpáֽh׃"],[17,14,"לְ⁠עֵ֥ת עֶ֨רֶב֙ וְ⁠הִנֵּ֣ה בַלָּהָ֔ה בְּ⁠טֶ֥רֶם בֹּ֖קֶר אֵינֶ֑⁠נּוּ זֶ֚ה חֵ֣לֶק שׁוֹסֵ֔י⁠נוּ וְ⁠גוֹרָ֖ל לְ⁠בֹזְזֵֽי⁠נוּ׃ס","lĕ⁠ʻé֥ţ ʻe֨reb֙ wĕ⁠hiné֣̇h balá̇há֔h bĕ̇⁠te֥rem bò֖̇qer ʼéyne֑⁠ṅẇ ze֚h ẖé֣leq ş̌wòsé֔y⁠nẇ wĕ⁠gwòrá֖l lĕ⁠bòzĕzéֽy⁠nẇ׃s"],[18,1,"ה֥וֹי אֶ֖רֶץ צִלְצַ֣ל כְּנָפָ֑יִם אֲשֶׁ֥ר מֵ⁠עֵ֖בֶר לְ⁠נַֽהֲרֵי־כֽוּשׁ׃","h֥wòy ʼe֖reẕ ẕilĕẕa֣l kĕ̇nápá֑yim ʼàşě֥r mé⁠ʻé֖ber lĕ⁠naֽhàréy-kֽẇş̌׃"],[18,2,"הַ⁠שֹּׁלֵ֨חַ בַּ⁠יָּ֜ם צִירִ֗ים וּ⁠בִ⁠כְלֵי־גֹמֶא֮ עַל־פְּנֵי־מַיִם֒ לְכ֣וּ ׀ מַלְאָכִ֣ים קַלִּ֗ים אֶל־גּוֹי֙ מְמֻשָּׁ֣ךְ וּ⁠מוֹרָ֔ט אֶל־עַ֥ם נוֹרָ֖א מִן־ה֣וּא וָ⁠הָ֑לְאָה גּ֚וֹי קַו־קָ֣ו וּ⁠מְבוּסָ֔ה אֲשֶׁר־בָּזְא֥וּ נְהָרִ֖ים אַרְצֽ⁠וֹ׃","ha⁠şò̇̌lé֨ẖa bȧ⁠yá̇֜m ẕiyri֗ym ẇ⁠bi⁠kĕléy-gòmeʼ֮ ʻal-pĕ̇néy-mayim֒ lĕk֣ẇ ׀ malĕʼáki֣ym qali̇֗ym ʼel-ġwòy֙ mĕmuşá֣̇̌kĕ ẇ⁠mwòrá֔t ʼel-ʻa֥m nwòrá֖ʼ min-h֣ẇʼ wá⁠há֑lĕʼáh ġ֚wòy qaw-qá֣w ẇ⁠mĕbẇsá֔h ʼàşěr-bá̇zĕʼ֥ẇ nĕhári֖ym ʼarĕẕֽ⁠wò׃"],[18,3,"כָּל־יֹשְׁבֵ֥י תֵבֵ֖ל וְ⁠שֹׁ֣כְנֵי אָ֑רֶץ כִּ⁠נְשֹׂא־נֵ֤ס הָרִים֙ תִּרְא֔וּ וְ⁠כִ⁠תְקֹ֥עַ שׁוֹפָ֖ר תִּשְׁמָֽעוּ׃ס","ká̇l-yòşĕ̌bé֥y ţébé֖l wĕ⁠şò֣̌kĕnéy ʼá֑reẕ ki̇⁠nĕşò̂ʼ-né֤s háriym֙ ţi̇rĕʼ֔ẇ wĕ⁠ki⁠ţĕqò֥ʻa ş̌wòpá֖r ţi̇şĕ̌máֽʻẇ׃s"],[18,4,"כִּי֩ כֹ֨ה אָמַ֤ר יְהוָה֙ אֵלַ֔⁠י אשקוטה וְ⁠אַבִּ֣יטָה בִ⁠מְכוֹנִ֑⁠י כְּ⁠חֹ֥ם צַח֙ עֲלֵי־א֔וֹר כְּ⁠עָ֥ב טַ֖ל בְּ⁠חֹ֥ם קָצִֽיר׃","ki̇y֩ kò֨h ʼáma֤r yĕhwáh֙ ʼéla֔⁠y ʼşqwth wĕ⁠ʼabi֣̇ytáh bi⁠mĕkwòni֑⁠y kĕ̇⁠ẖò֥m ẕaẖ֙ ʻàléy-ʼ֔wòr kĕ̇⁠ʻá֥b ta֖l bĕ̇⁠ẖò֥m qáẕiֽyr׃"],[18,5,"כִּֽי־לִ⁠פְנֵ֤י קָצִיר֙ כְּ⁠תָם־פֶּ֔רַח וּ⁠בֹ֥סֶר גֹּמֵ֖ל יִֽהְיֶ֣ה נִצָּ֑ה וְ⁠כָרַ֤ת הַ⁠זַּלְזַלִּים֙ בַּ⁠מַּזְמֵר֔וֹת וְ⁠אֶת־הַ⁠נְּטִישׁ֖וֹת הֵסִ֥יר הֵתַֽז׃","kiֽ̇y-li⁠pĕné֤y qáẕiyr֙ kĕ̇⁠ţám-pė֔raẖ ẇ⁠bò֥ser gò̇mé֖l yiֽhĕye֣h niẕá֑̇h wĕ⁠kára֤ţ ha⁠zȧlĕzali̇ym֙ bȧ⁠mȧzĕmér֔wòţ wĕ⁠ʼeţ-ha⁠nĕ̇tiyş֖̌wòţ hési֥yr héţaֽz׃"],[18,6,"יֵעָזְב֤וּ יַחְדָּו֙ לְ⁠עֵ֣יט הָרִ֔ים וּֽ⁠לְ⁠בֶהֱמַ֖ת הָ⁠אָ֑רֶץ וְ⁠קָ֤ץ עָלָי⁠ו֙ הָ⁠עַ֔יִט וְ⁠כָל־בֶּהֱמַ֥ת הָ⁠אָ֖רֶץ עָלָ֥י⁠ו תֶּחֱרָֽף׃","yéʻázĕb֤ẇ yaẖĕdá̇w֙ lĕ⁠ʻé֣yt hári֔ym ẇֽ⁠lĕ⁠behèma֖ţ há⁠ʼá֑reẕ wĕ⁠qá֤ẕ ʻáláy⁠w֙ há⁠ʻa֔yit wĕ⁠kál-bėhèma֥ţ há⁠ʼá֖reẕ ʻálá֥y⁠w ţėẖèráֽp׃"],[18,7,"בָּ⁠עֵת֩ הַ⁠הִ֨יא יֽוּבַל־שַׁ֜י לַ⁠יהוָ֣ה צְבָא֗וֹת עַ֚ם מְמֻשָּׁ֣ךְ וּ⁠מוֹרָ֔ט וּ⁠מֵ⁠עַ֥ם נוֹרָ֖א מִן־ה֣וּא וָ⁠הָ֑לְאָה גּ֣וֹי ׀ קַו־קָ֣ו וּ⁠מְבוּסָ֗ה אֲשֶׁ֨ר בָּזְא֤וּ נְהָרִים֙ אַרְצ֔⁠וֹ אֶל־מְק֛וֹם שֵׁם־יְהוָ֥ה צְבָא֖וֹת הַר־צִיּֽוֹן׃ס","bá̇⁠ʻéţ֩ ha⁠hi֨yʼ yֽẇbal-şǎ֜y la⁠yhwá֣h ẕĕbáʼ֗wòţ ʻa֚m mĕmuşá֣̇̌kĕ ẇ⁠mwòrá֔t ẇ⁠mé⁠ʻa֥m nwòrá֖ʼ min-h֣ẇʼ wá⁠há֑lĕʼáh ġ֣wòy ׀ qaw-qá֣w ẇ⁠mĕbẇsá֗h ʼàşě֨r bá̇zĕʼ֤ẇ nĕháriym֙ ʼarĕẕ֔⁠wò ʼel-mĕq֛wòm şé̌m-yĕhwá֥h ẕĕbáʼ֖wòţ har-ẕiẏֽwòn׃s"],[19,1,"מַשָּׂ֖א מִצְרָ֑יִם הִנֵּ֨ה יְהוָ֜ה רֹכֵ֨ב עַל־עָ֥ב קַל֙ וּ⁠בָ֣א מִצְרַ֔יִם וְ⁠נָע֞וּ אֱלִילֵ֤י מִצְרַ֨יִם֙ מִ⁠פָּנָ֔י⁠ו וּ⁠לְבַ֥ב מִצְרַ֖יִם יִמַּ֥ס בְּ⁠קִרְבּֽ⁠וֹ׃","maşá֖̇̂ʼ miẕĕrá֑yim hiné̇֨h yĕhwá֜h ròké֨b ʻal-ʻá֥b qal֙ ẇ⁠bá֣ʼ miẕĕra֔yim wĕ⁠náʻ֞ẇ ʼèliylé֤y miẕĕra֨yim֙ mi⁠pá̇ná֔y⁠w ẇ⁠lĕba֥b miẕĕra֖yim yimȧ֥s bĕ̇⁠qirĕḃֽ⁠wò׃"],[19,2,"וְ⁠סִכְסַכְתִּ֤י מִצְרַ֨יִם֙ בְּ⁠מִצְרַ֔יִם וְ⁠נִלְחֲמ֥וּ אִישׁ־בְּ⁠אָחִ֖י⁠ו וְ⁠אִ֣ישׁ בְּ⁠רֵעֵ֑⁠הוּ עִ֣יר בְּ⁠עִ֔יר מַמְלָכָ֖ה בְּ⁠מַמְלָכָֽה׃","wĕ⁠sikĕsakĕţi֤̇y miẕĕra֨yim֙ bĕ̇⁠miẕĕra֔yim wĕ⁠nilĕẖàm֥ẇ ʼiyş̌-bĕ̇⁠ʼáẖi֖y⁠w wĕ⁠ʼi֣yş̌ bĕ̇⁠réʻé֑⁠hẇ ʻi֣yr bĕ̇⁠ʻi֔yr mamĕláká֖h bĕ̇⁠mamĕlákáֽh׃"],[19,3,"וְ⁠נָבְקָ֤ה רֽוּחַ־מִצְרַ֨יִם֙ בְּ⁠קִרְבּ֔⁠וֹ וַ⁠עֲצָת֖⁠וֹ אֲבַלֵּ֑עַ וְ⁠דָרְשׁ֤וּ אֶל־הָֽ⁠אֱלִילִים֙ וְ⁠אֶל־הָ֣⁠אִטִּ֔ים וְ⁠אֶל־הָ⁠אֹב֖וֹת וְ⁠אֶל־הַ⁠יִּדְּעֹנִֽים׃","wĕ⁠nábĕqá֤h rֽẇẖa-miẕĕra֨yim֙ bĕ̇⁠qirĕḃ֔⁠wò wa⁠ʻàẕáţ֖⁠wò ʼàbalé֑̇ʻa wĕ⁠dárĕş֤̌ẇ ʼel-háֽ⁠ʼèliyliym֙ wĕ⁠ʼel-há֣⁠ʼiti̇֔ym wĕ⁠ʼel-há⁠ʼòb֖wòţ wĕ⁠ʼel-ha⁠yi̇dĕ̇ʻòniֽym׃"],[19,4,"וְ⁠סִכַּרְתִּי֙ אֶת־מִצְרַ֔יִם בְּ⁠יַ֖ד אֲדֹנִ֣ים קָשֶׁ֑ה וּ⁠מֶ֤לֶךְ עַז֙ יִמְשָׁל־בָּ֔⁠ם נְאֻ֥ם הָ⁠אָד֖וֹן יְהוָ֥ה צְבָאֽוֹת׃","wĕ⁠sikȧrĕţi̇y֙ ʼeţ-miẕĕra֔yim bĕ̇⁠ya֖d ʼàdòni֣ym qáşě֑h ẇ⁠me֤lekĕ ʻaz֙ yimĕşá̌l-bá̇֔⁠m nĕʼu֥m há⁠ʼád֖wòn yĕhwá֥h ẕĕbáʼֽwòţ׃"],[19,5,"וְ⁠נִשְּׁתוּ־מַ֖יִם מֵֽ⁠הַ⁠יָּ֑ם וְ⁠נָהָ֖ר יֶחֱרַ֥ב וְ⁠יָבֵֽשׁ׃","wĕ⁠nişĕ̇̌ţẇ-ma֖yim méֽ⁠ha⁠yá֑̇m wĕ⁠náhá֖r yeẖèra֥b wĕ⁠yábéֽş̌׃"],[19,6,"וְ⁠הֶאֶזְנִ֣יחוּ נְהָר֔וֹת דָּלֲל֥וּ וְ⁠חָרְב֖וּ יְאֹרֵ֣י מָצ֑וֹר קָנֶ֥ה וָ⁠ס֖וּף קָמֵֽלוּ׃","wĕ⁠heʼezĕni֣yẖẇ nĕhár֔wòţ dá̇làl֥ẇ wĕ⁠ẖárĕb֖ẇ yĕʼòré֣y máẕ֑wòr qáne֥h wá⁠s֖ẇp qáméֽlẇ׃"],[19,7,"עָר֥וֹת עַל־יְא֖וֹר עַל־פִּ֣י יְא֑וֹר וְ⁠כֹל֙ מִזְרַ֣ע יְא֔וֹר יִיבַ֥שׁ נִדַּ֖ף וְ⁠אֵינֶֽ⁠נּוּ׃","ʻár֥wòţ ʻal-yĕʼ֖wòr ʻal-pi֣̇y yĕʼ֑wòr wĕ⁠kòl֙ mizĕra֣ʻ yĕʼ֔wòr yiyba֥ş̌ nidȧ֖p wĕ⁠ʼéyneֽ⁠ṅẇ׃"],[19,8,"וְ⁠אָנוּ֙ הַ⁠דַּיָּגִ֔ים וְ⁠אָ֣בְל֔וּ כָּל־מַשְׁלִיכֵ֥י בַ⁠יְא֖וֹר חַכָּ֑ה וּ⁠פֹרְשֵׂ֥י מִכְמֹ֛רֶת עַל־פְּנֵי־מַ֖יִם אֻמְלָֽלוּ׃","wĕ⁠ʼánẇ֙ ha⁠dȧyá̇gi֔ym wĕ⁠ʼá֣bĕl֔ẇ ká̇l-maşĕ̌liyké֥y ba⁠yĕʼ֖wòr ẖaká֑̇h ẇ⁠pòrĕşé֥̂y mikĕmò֛reţ ʻal-pĕ̇néy-ma֖yim ʼumĕláֽlẇ׃"],[19,9,"וּ⁠בֹ֛שׁוּ עֹבְדֵ֥י פִשְׁתִּ֖ים שְׂרִיק֑וֹת וְ⁠אֹרְגִ֖ים חוֹרָֽי׃","ẇ⁠bò֛ş̌ẇ ʻòbĕdé֥y pişĕ̌ţi֖̇ym şĕ̂riyq֑wòţ wĕ⁠ʼòrĕgi֖ym ẖwòráֽy׃"],[19,10,"וְ⁠הָי֥וּ שָׁתֹתֶ֖י⁠הָ מְדֻכָּאִ֑ים כָּל־עֹ֥שֵׂי שֶׂ֖כֶר אַגְמֵי־נָֽפֶשׁ׃","wĕ⁠háy֥ẇ şá̌ţòţe֖y⁠há mĕduká̇ʼi֑ym ká̇l-ʻò֥şé̂y şê֖ker ʼagĕméy-náֽpeş̌׃"],[19,11,"אַךְ־אֱוִלִים֙ שָׂ֣רֵי צֹ֔עַן חַכְמֵי֙ יֹעֲצֵ֣י פַרְעֹ֔ה עֵצָ֖ה נִבְעָרָ֑ה אֵ֚יךְ תֹּאמְר֣וּ אֶל־פַּרְעֹ֔ה בֶּן־חֲכָמִ֥ים אֲנִ֖י בֶּן־מַלְכֵי־קֶֽדֶם׃","ʼakĕ-ʼèwiliym֙ şá֣̂réy ẕò֔ʻan ẖakĕméy֙ yòʻàẕé֣y parĕʻò֔h ʻéẕá֖h nibĕʻárá֑h ʼé֚ykĕ ţò̇ʼmĕr֣ẇ ʼel-pȧrĕʻò֔h bėn-ẖàkámi֥ym ʼàni֖y bėn-malĕkéy-qeֽdem׃"],[19,12,"אַיָּ⁠ם֙ אֵפ֣וֹא חֲכָמֶ֔י⁠ךָ וְ⁠יַגִּ֥ידוּ נָ֖א לָ֑⁠ךְ וְ⁠יֵ֣דְע֔וּ מַה־יָּעַ֛ץ יְהוָ֥ה צְבָא֖וֹת עַל־מִצְרָֽיִם׃","ʼayá̇⁠m֙ ʼép֣wòʼ ẖàkáme֔y⁠ká wĕ⁠yagi֥̇ydẇ ná֖ʼ lá֑⁠kĕ wĕ⁠yé֣dĕʻ֔ẇ mah-yá̇ʻa֛ẕ yĕhwá֥h ẕĕbáʼ֖wòţ ʻal-miẕĕráֽyim׃"],[19,13,"נֽוֹאֲלוּ֙ שָׂ֣רֵי צֹ֔עַן נִשְּׁא֖וּ שָׂ֣רֵי נֹ֑ף הִתְע֥וּ אֶת־מִצְרַ֖יִם פִּנַּ֥ת שְׁבָטֶֽי⁠הָ׃","nֽwòʼàlẇ֙ şá֣̂réy ẕò֔ʻan nişĕ̇̌ʼ֖ẇ şá֣̂réy nò֑p hiţĕʻ֥ẇ ʼeţ-miẕĕra֖yim pi̇nȧ֥ţ şĕ̌báteֽy⁠há׃"],[19,14,"יְהוָ֛ה מָסַ֥ךְ בְּ⁠קִרְבָּ֖⁠הּ ר֣וּחַ עִוְעִ֑ים וְ⁠הִתְע֤וּ אֶת־מִצְרַ֨יִם֙ בְּ⁠כָֽל־מַעֲשֵׂ֔⁠הוּ כְּ⁠הִתָּע֥וֹת שִׁכּ֖וֹר בְּ⁠קִיאֽ⁠וֹ׃","yĕhwá֛h mása֥kĕ bĕ̇⁠qirĕbá֖̇⁠ḣ r֣ẇẖa ʻiwĕʻi֑ym wĕ⁠hiţĕʻ֤ẇ ʼeţ-miẕĕra֨yim֙ bĕ̇⁠káֽl-maʻàşé̂֔⁠hẇ kĕ̇⁠hiţá̇ʻ֥wòţ şǐk֖̇wòr bĕ̇⁠qiyʼֽ⁠wò׃"],[19,15,"וְ⁠לֹֽא־יִהְיֶ֥ה לְ⁠מִצְרַ֖יִם מַֽעֲשֶׂ֑ה אֲשֶׁ֧ר יַעֲשֶׂ֛ה רֹ֥אשׁ וְ⁠זָנָ֖ב כִּפָּ֥ה וְ⁠אַגְמֽוֹן׃ס","wĕ⁠lòֽʼ-yihĕye֥h lĕ⁠miẕĕra֖yim maֽʻàşê֑h ʼàşě֧r yaʻàşê֛h rò֥ʼş̌ wĕ⁠záná֖b ki̇pá֥̇h wĕ⁠ʼagĕmֽwòn׃s"],[19,16,"בַּ⁠יּ֣וֹם הַ⁠ה֔וּא יִֽהְיֶ֥ה מִצְרַ֖יִם כַּ⁠נָּשִׁ֑ים וְ⁠חָרַ֣ד ׀ וּ⁠פָחַ֗ד מִ⁠פְּנֵי֙ תְּנוּפַת֙ יַד־יְהוָ֣ה צְבָא֔וֹת אֲשֶׁר־ה֖וּא מֵנִ֥יף עָלָֽי⁠ו׃","bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ yiֽhĕye֥h miẕĕra֖yim kȧ⁠ná̇şǐ֑ym wĕ⁠ẖára֣d ׀ ẇ⁠páẖa֗d mi⁠pĕ̇néy֙ ţĕ̇nẇpaţ֙ yad-yĕhwá֣h ẕĕbáʼ֔wòţ ʼàşěr-h֖ẇʼ méni֥yp ʻáláֽy⁠w׃"],[19,17,"וְ֠⁠הָיְתָה אַדְמַ֨ת יְהוּדָ֤ה לְ⁠מִצְרַ֨יִם֙ לְ⁠חָגָּ֔א כֹּל֩ אֲשֶׁ֨ר יַזְכִּ֥יר אֹתָ֛⁠הּ אֵלָ֖י⁠ו יִפְחָ֑ד מִ⁠פְּנֵ֗י עֲצַת֙ יְהוָ֣ה צְבָא֔וֹת אֲשֶׁר־ה֖וּא יוֹעֵ֥ץ עָלָֽי⁠ו׃ס","wĕ֠⁠háyĕţáh ʼadĕma֨ţ yĕhẇdá֤h lĕ⁠miẕĕra֨yim֙ lĕ⁠ẖágá̇֔ʼ kò̇l֩ ʼàşě֨r yazĕki֥̇yr ʼòţá֛⁠ḣ ʼélá֖y⁠w yipĕẖá֑d mi⁠pĕ̇né֗y ʻàẕaţ֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʼàşěr-h֖ẇʼ ywòʻé֥ẕ ʻáláֽy⁠w׃s"],[19,18,"בַּ⁠יּ֣וֹם הַ⁠ה֡וּא יִהְיוּ֩ חָמֵ֨שׁ עָרִ֜ים בְּ⁠אֶ֣רֶץ מִצְרַ֗יִם מְדַבְּרוֹת֙ שְׂפַ֣ת כְּנַ֔עַן וְ⁠נִשְׁבָּע֖וֹת לַ⁠יהוָ֣ה צְבָא֑וֹת עִ֣יר הַ⁠הֶ֔רֶס יֵאָמֵ֖ר לְ⁠אֶחָֽת׃ס","bȧ⁠ẏ֣wòm ha⁠h֡ẇʼ yihĕyẇ֩ ẖámé֨ş̌ ʻári֜ym bĕ̇⁠ʼe֣reẕ miẕĕra֗yim mĕdabĕ̇rwòţ֙ şĕ̂pa֣ţ kĕ̇na֔ʻan wĕ⁠nişĕ̌bá̇ʻ֖wòţ la⁠yhwá֣h ẕĕbáʼ֑wòţ ʻi֣yr ha⁠he֔res yéʼámé֖r lĕ⁠ʼeẖáֽţ׃s"],[19,19,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִֽהְיֶ֤ה מִזְבֵּ֨חַ֙ לַֽ⁠יהוָ֔ה בְּ⁠ת֖וֹךְ אֶ֣רֶץ מִצְרָ֑יִם וּ⁠מַצֵּבָ֥ה אֵֽצֶל־גְּבוּלָ֖⁠הּ לַֽ⁠יהוָֽה׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yiֽhĕye֤h mizĕbé̇֨ẖa֙ laֽ⁠yhwá֔h bĕ̇⁠ţ֖wòkĕ ʼe֣reẕ miẕĕrá֑yim ẇ⁠maẕé̇bá֥h ʼéֽẕel-gĕ̇bẇlá֖⁠ḣ laֽ⁠yhwáֽh׃"],[19,20,"וְ⁠הָיָ֨ה לְ⁠א֥וֹת וּ⁠לְ⁠עֵ֛ד לַֽ⁠יהוָ֥ה צְבָא֖וֹת בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם כִּֽי־יִצְעֲק֤וּ אֶל־יְהוָה֙ מִ⁠פְּנֵ֣י לֹֽחֲצִ֔ים וְ⁠יִשְׁלַ֥ח לָ⁠הֶ֛ם מוֹשִׁ֥יעַ וָ⁠רָ֖ב וְ⁠הִצִּילָֽ⁠ם׃","wĕ⁠háyá֨h lĕ⁠ʼ֥wòţ ẇ⁠lĕ⁠ʻé֛d laֽ⁠yhwá֥h ẕĕbáʼ֖wòţ bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim kiֽ̇y-yiẕĕʻàq֤ẇ ʼel-yĕhwáh֙ mi⁠pĕ̇né֣y lòֽẖàẕi֔ym wĕ⁠yişĕ̌la֥ẖ lá⁠he֛m mwòşǐ֥yʻa wá⁠rá֖b wĕ⁠hiẕi̇yláֽ⁠m׃"],[19,21,"וְ⁠נוֹדַ֤ע יְהוָה֙ לְ⁠מִצְרַ֔יִם וְ⁠יָדְע֥וּ מִצְרַ֛יִם אֶת־יְהוָ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וְ⁠עָֽבְדוּ֙ זֶ֣בַח וּ⁠מִנְחָ֔ה וְ⁠נָדְרוּ־נֵ֥דֶר לַֽ⁠יהוָ֖ה וְ⁠שִׁלֵּֽמוּ׃","wĕ⁠nwòda֤ʻ yĕhwáh֙ lĕ⁠miẕĕra֔yim wĕ⁠yádĕʻ֥ẇ miẕĕra֛yim ʼeţ-yĕhwá֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ wĕ⁠ʻáֽbĕdẇ֙ ze֣baẖ ẇ⁠minĕẖá֔h wĕ⁠nádĕrẇ-né֥der laֽ⁠yhwá֖h wĕ⁠şǐléֽ̇mẇ׃"],[19,22,"וְ⁠נָגַ֧ף יְהוָ֛ה אֶת־מִצְרַ֖יִם נָגֹ֣ף וְ⁠רָפ֑וֹא וְ⁠שָׁ֨בוּ֙ עַד־יְהוָ֔ה וְ⁠נֶעְתַּ֥ר לָ⁠הֶ֖ם וּ⁠רְפָאָֽ⁠ם׃","wĕ⁠nága֧p yĕhwá֛h ʼeţ-miẕĕra֖yim nágò֣p wĕ⁠ráp֑wòʼ wĕ⁠şá̌֨bẇ֙ ʻad-yĕhwá֔h wĕ⁠neʻĕţȧ֥r lá⁠he֖m ẇ⁠rĕpáʼáֽ⁠m׃"],[19,23,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא תִּהְיֶ֨ה מְסִלָּ֤ה מִ⁠מִּצְרַ֨יִם֙ אַשּׁ֔וּרָ⁠ה וּ⁠בָֽא־אַשּׁ֥וּר בְּ⁠מִצְרַ֖יִם וּ⁠מִצְרַ֣יִם בְּ⁠אַשּׁ֑וּר וְ⁠עָבְד֥וּ מִצְרַ֖יִם אֶת־אַשּֽׁוּר׃ס","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ ţi̇hĕye֨h mĕsilá֤̇h mi⁠mi̇ẕĕra֨yim֙ ʼaş̇̌֔ẇrá⁠h ẇ⁠báֽʼ-ʼaş֥̇̌ẇr bĕ̇⁠miẕĕra֖yim ẇ⁠miẕĕra֣yim bĕ̇⁠ʼaş֑̇̌ẇr wĕ⁠ʻábĕd֥ẇ miẕĕra֖yim ʼeţ-ʼaşֽ̇̌ẇr׃s"],[19,24,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִהְיֶ֤ה יִשְׂרָאֵל֙ שְׁלִ֣ישִׁיָּ֔ה לְ⁠מִצְרַ֖יִם וּ⁠לְ⁠אַשּׁ֑וּר בְּרָכָ֖ה בְּ⁠קֶ֥רֶב הָ⁠אָֽרֶץ׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yihĕye֤h yişĕ̂ráʼél֙ şĕ̌li֣yşǐyá̇֔h lĕ⁠miẕĕra֖yim ẇ⁠lĕ⁠ʼaş֑̇̌ẇr bĕ̇ráká֖h bĕ̇⁠qe֥reb há⁠ʼáֽreẕ׃"],[19,25,"אֲשֶׁ֧ר בֵּרֲכ֛⁠וֹ יְהוָ֥ה צְבָא֖וֹת לֵ⁠אמֹ֑ר בָּר֨וּךְ עַמִּ֜⁠י מִצְרַ֗יִם וּ⁠מַעֲשֵׂ֤ה יָדַ⁠י֙ אַשּׁ֔וּר וְ⁠נַחֲלָתִ֖⁠י יִשְׂרָאֵֽל׃ס","ʼàşě֧r bé̇ràk֛⁠wò yĕhwá֥h ẕĕbáʼ֖wòţ lé⁠ʼmò֑r bá̇r֨ẇkĕ ʻami̇֜⁠y miẕĕra֗yim ẇ⁠maʻàşé֤̂h yáda⁠y֙ ʼaş̇̌֔ẇr wĕ⁠naẖàláţi֖⁠y yişĕ̂ráʼéֽl׃s"],[20,1,"בִּ⁠שְׁנַ֨ת בֹּ֤א תַרְתָּן֙ אַשְׁדּ֔וֹדָ⁠ה בִּ⁠שְׁלֹ֣ח אֹת֔⁠וֹ סַֽרְג֖וֹן מֶ֣לֶךְ אַשּׁ֑וּר וַ⁠יִּלָּ֥חֶם בְּ⁠אַשְׁדּ֖וֹד וַֽ⁠יִּלְכְּדָֽ⁠הּ׃","bi̇⁠şĕ̌na֨ţ bò֤̇ʼ ţarĕţá̇n֙ ʼaşĕ̌ḋ֔wòdá⁠h bi̇⁠şĕ̌lò֣ẖ ʼòţ֔⁠wò saֽrĕg֖wòn me֣lekĕ ʼaş֑̇̌ẇr wa⁠yi̇lá֥̇ẖem bĕ̇⁠ʼaşĕ̌ḋ֖wòd waֽ⁠yi̇lĕkĕ̇dáֽ⁠ḣ׃"],[20,2,"בָּ⁠עֵ֣ת הַ⁠הִ֗יא דִּבֶּ֣ר יְהוָה֮ בְּ⁠יַ֣ד יְשַׁעְיָ֣הוּ בֶן־אָמוֹץ֮ לֵ⁠אמֹר֒ לֵ֗ךְ וּ⁠פִתַּחְתָּ֤ הַ⁠שַּׂק֙ מֵ⁠עַ֣ל מָתְנֶ֔י⁠ךָ וְ⁠נַעַלְ⁠ךָ֥ תַחֲלֹ֖ץ מֵ⁠עַ֣ל רַגְלֶ֑י⁠ךָ וַ⁠יַּ֣עַשׂ כֵּ֔ן הָלֹ֖ךְ עָר֥וֹם וְ⁠יָחֵֽף׃ס","bá̇⁠ʻé֣ţ ha⁠hi֗yʼ di̇bė֣r yĕhwáh֮ bĕ̇⁠ya֣d yĕşǎʻĕyá֣hẇ ben-ʼámwòẕ֮ lé⁠ʼmòr֒ lé֗kĕ ẇ⁠piţȧẖĕţá֤̇ ha⁠şȧ̂q֙ mé⁠ʻa֣l máţĕne֔y⁠ká wĕ⁠naʻalĕ⁠ká֥ ţaẖàlò֖ẕ mé⁠ʻa֣l ragĕle֑y⁠ká wa⁠yȧ֣ʻaş̂ ké̇֔n hálò֖kĕ ʻár֥wòm wĕ⁠yáẖéֽp׃s"],[20,3,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה כַּ⁠אֲשֶׁ֥ר הָלַ֛ךְ עַבְדִּ֥⁠י יְשַׁעְיָ֖הוּ עָר֣וֹם וְ⁠יָחֵ֑ף שָׁלֹ֤שׁ שָׁנִים֙ א֣וֹת וּ⁠מוֹפֵ֔ת עַל־מִצְרַ֖יִם וְ⁠עַל־כּֽוּשׁ׃","wa⁠yò֣̇ʼmer yĕhwá֔h kȧ⁠ʼàşě֥r hála֛kĕ ʻabĕdi֥̇⁠y yĕşǎʻĕyá֖hẇ ʻár֣wòm wĕ⁠yáẖé֑p şá̌lò֤ş̌ şá̌niym֙ ʼ֣wòţ ẇ⁠mwòpé֔ţ ʻal-miẕĕra֖yim wĕ⁠ʻal-kֽ̇ẇş̌׃"],[20,4,"כֵּ֣ן יִנְהַ֣ג מֶֽלֶךְ־אַ֠שּׁוּר אֶת־שְׁבִ֨י מִצְרַ֜יִם וְ⁠אֶת־גָּל֥וּת כּ֛וּשׁ נְעָרִ֥ים וּ⁠זְקֵנִ֖ים עָר֣וֹם וְ⁠יָחֵ֑ף וַ⁠חֲשׂוּפַ֥י שֵׁ֖ת עֶרְוַ֥ת מִצְרָֽיִם׃","ké֣̇n yinĕha֣g meֽlekĕ-ʼa֠ş̇̌ẇr ʼeţ-şĕ̌bi֨y miẕĕra֜yim wĕ⁠ʼeţ-gá̇l֥ẇţ k֛̇ẇş̌ nĕʻári֥ym ẇ⁠zĕqéni֖ym ʻár֣wòm wĕ⁠yáẖé֑p wa⁠ẖàş̂ẇpa֥y şé֖̌ţ ʻerĕwa֥ţ miẕĕráֽyim׃"],[20,5,"וְ⁠חַתּ֖וּ וָ⁠בֹ֑שׁוּ מִ⁠כּוּשׁ֙ מַבָּטָ֔⁠ם וּ⁠מִן־מִצְרַ֖יִם תִּפְאַרְתָּֽ⁠ם׃","wĕ⁠ẖaţ֖̇ẇ wá⁠bò֑ş̌ẇ mi⁠k̇ẇş̌֙ mabá̇tá֔⁠m ẇ⁠min-miẕĕra֖yim ţi̇pĕʼarĕţáֽ̇⁠m׃"],[20,6,"וְ֠⁠אָמַר יֹשֵׁ֨ב הָ⁠אִ֣י הַ⁠זֶּה֮ בַּ⁠יּ֣וֹם הַ⁠הוּא֒ הִנֵּה־כֹ֣ה מַבָּטֵ֗⁠נוּ אֲשֶׁר־נַ֤סְנוּ שָׁם֙ לְ⁠עֶזְרָ֔ה לְ⁠הִ֨נָּצֵ֔ל מִ⁠פְּנֵ֖י מֶ֣לֶךְ אַשּׁ֑וּר וְ⁠אֵ֖יךְ נִמָּלֵ֥ט אֲנָֽחְנוּ׃ס","wĕ֠⁠ʼámar yòşé̌֨b há⁠ʼi֣y ha⁠zėh֮ bȧ⁠ẏ֣wòm ha⁠hẇʼ֒ hiné̇h-kò֣h mabá̇té֗⁠nẇ ʼàşěr-na֤sĕnẇ şá̌m֙ lĕ⁠ʻezĕrá֔h lĕ⁠hi֨ná̇ẕé֔l mi⁠pĕ̇né֖y me֣lekĕ ʼaş֑̇̌ẇr wĕ⁠ʼé֖ykĕ nimá̇lé֥t ʼànáֽẖĕnẇ׃s"],[21,1,"מַשָּׂ֖א מִדְבַּר־יָ֑ם כְּ⁠סוּפ֤וֹת בַּ⁠נֶּ֨גֶב֙ לַֽ⁠חֲלֹ֔ף מִ⁠מִּדְבָּ֣ר בָּ֔א מֵ⁠אֶ֖רֶץ נוֹרָאָֽה׃","maşá֖̇̂ʼ midĕbȧr-yá֑m kĕ̇⁠sẇp֤wòţ bȧ⁠nė֨geb֙ laֽ⁠ẖàlò֔p mi⁠mi̇dĕbá֣̇r bá̇֔ʼ mé⁠ʼe֖reẕ nwòráʼáֽh׃"],[21,2,"חָז֥וּת קָשָׁ֖ה הֻגַּד־לִ֑⁠י הַ⁠בּוֹגֵ֤ד ׀ בּוֹגֵד֙ וְ⁠הַ⁠שּׁוֹדֵ֣ד ׀ שׁוֹדֵ֔ד עֲלִ֤י עֵילָם֙ צוּרִ֣י מָדַ֔י כָּל־אַנְחָתָ֖⁠ה הִשְׁבַּֽתִּי׃","ẖáz֥ẇţ qáşá֖̌h hugȧd-li֑⁠y ha⁠ḃwògé֤d ׀ ḃwògéd֙ wĕ⁠ha⁠ş̇̌wòdé֣d ׀ ş̌wòdé֔d ʻàli֤y ʻéylám֙ ẕẇri֣y máda֔y ká̇l-ʼanĕẖáţá֖⁠h hişĕ̌bȧֽţi̇y׃"],[21,3,"עַל־כֵּ֗ן מָלְא֤וּ מָתְנַ⁠י֙ חַלְחָלָ֔ה צִירִ֣ים אֲחָז֔וּ⁠נִי כְּ⁠צִירֵ֖י יֽוֹלֵדָ֑ה נַעֲוֵ֣יתִי מִ⁠שְּׁמֹ֔עַ נִבְהַ֖לְתִּי מֵ⁠רְאֽוֹת׃","ʻal-ké̇֗n málĕʼ֤ẇ máţĕna⁠y֙ ẖalĕẖálá֔h ẕiyri֣ym ʼàẖáz֔ẇ⁠niy kĕ̇⁠ẕiyré֖y yֽwòlédá֑h naʻàwé֣yţiy mi⁠şĕ̇̌mò֔ʻa nibĕha֖lĕţi̇y mé⁠rĕʼֽwòţ׃"],[21,4,"תָּעָ֣ה לְבָבִ֔⁠י פַּלָּצ֖וּת בִּֽעֲתָ֑תְ⁠נִי אֵ֚ת נֶ֣שֶׁף חִשְׁקִ֔⁠י שָׂ֥ם לִ֖⁠י לַ⁠חֲרָדָֽה׃","ţá̇ʻá֣h lĕbábi֔⁠y pȧlá̇ẕ֖ẇţ biֽ̇ʻàţá֑ţĕ⁠niy ʼé֚ţ ne֣şěp ẖişĕ̌qi֔⁠y şá֥̂m li֖⁠y la⁠ẖàrádáֽh׃"],[21,5,"עָרֹ֧ךְ הַ⁠שֻּׁלְחָ֛ן צָפֹ֥ה הַ⁠צָּפִ֖ית אָכ֣וֹל שָׁתֹ֑ה ק֥וּמוּ הַ⁠שָּׂרִ֖ים מִשְׁח֥וּ מָגֵֽן׃פ","ʻárò֧kĕ ha⁠şu̇̌lĕẖá֛n ẕápò֥h ha⁠ẕá̇pi֖yţ ʼák֣wòl şá̌ţò֑h q֥ẇmẇ ha⁠şá̇̂ri֖ym mişĕ̌ẖ֥ẇ mágéֽn׃p"],[21,6,"כִּ֣י כֹ֥ה אָמַ֛ר אֵלַ֖⁠י אֲדֹנָ֑⁠י לֵ֚ךְ הַעֲמֵ֣ד הַֽ⁠מְצַפֶּ֔ה אֲשֶׁ֥ר יִרְאֶ֖ה יַגִּֽיד׃","ki֣̇y kò֥h ʼáma֛r ʼéla֖⁠y ʼàdòná֑⁠y lé֚kĕ haʻàmé֣d haֽ⁠mĕẕapė֔h ʼàşě֥r yirĕʼe֖h yagiֽ̇yd׃"],[21,7,"וְ⁠רָ֣אָה רֶ֗כֶב צֶ֚מֶד פָּֽרָשִׁ֔ים רֶ֥כֶב חֲמ֖וֹר רֶ֣כֶב גָּמָ֑ל וְ⁠הִקְשִׁ֥יב קֶ֖שֶׁב רַב־קָֽשֶׁב׃","wĕ⁠rá֣ʼáh re֗keb ẕe֚med páֽ̇ráşǐ֔ym re֥keb ẖàm֖wòr re֣keb gá̇má֑l wĕ⁠hiqĕşǐ֥yb qe֖şěb rab-qáֽşěb׃"],[21,8,"וַ⁠יִּקְרָ֖א אַרְיֵ֑ה עַל־מִצְפֶּ֣ה ׀ אֲדֹנָ֗⁠י אָנֹכִ֞י עֹמֵ֤ד תָּמִיד֙ יוֹמָ֔ם וְ⁠עַל־מִ֨שְׁמַרְתִּ֔⁠י אָנֹכִ֥י נִצָּ֖ב כָּל־הַ⁠לֵּילֽוֹת׃","wa⁠yi̇qĕrá֖ʼ ʼarĕyé֑h ʻal-miẕĕpė֣h ׀ ʼàdòná֗⁠y ʼánòki֞y ʻòmé֤d ţá̇miyd֙ ywòmá֔m wĕ⁠ʻal-mi֨şĕ̌marĕţi̇֔⁠y ʼánòki֥y niẕá֖̇b ká̇l-ha⁠lé̇ylֽwòţ׃"],[21,9,"וְ⁠הִנֵּה־זֶ֥ה בָא֙ רֶ֣כֶב אִ֔ישׁ צֶ֖מֶד פָּֽרָשִׁ֑ים וַ⁠יַּ֣עַן וַ⁠יֹּ֗אמֶר נָפְלָ֤ה נָֽפְלָה֙ בָּבֶ֔ל וְ⁠כָל־פְּסִילֵ֥י אֱלֹהֶ֖י⁠הָ שִׁבַּ֥ר לָ⁠אָֽרֶץ׃","wĕ⁠hiné̇h-ze֥h báʼ֙ re֣keb ʼi֔yş̌ ẕe֖med páֽ̇ráşǐ֑ym wa⁠yȧ֣ʻan wa⁠yò̇֗ʼmer nápĕlá֤h náֽpĕláh֙ bá̇be֔l wĕ⁠kál-pĕ̇siylé֥y ʼèlòhe֖y⁠há şǐbȧ֥r lá⁠ʼáֽreẕ׃"],[21,10,"מְדֻשָׁתִ֖⁠י וּ⁠בֶן־גָּרְנִ֑⁠י אֲשֶׁ֣ר שָׁמַ֗עְתִּי מֵ⁠אֵ֨ת יְהוָ֧ה צְבָא֛וֹת אֱלֹהֵ֥י יִשְׂרָאֵ֖ל הִגַּ֥דְתִּי לָ⁠כֶֽם׃ס","mĕduşá̌ţi֖⁠y ẇ⁠ben-gá̇rĕni֑⁠y ʼàşě֣r şá̌ma֗ʻĕţi̇y mé⁠ʼé֨ţ yĕhwá֧h ẕĕbáʼ֛wòţ ʼèlòhé֥y yişĕ̂ráʼé֖l higȧ֥dĕţi̇y lá⁠keֽm׃s"],[21,11,"מַשָּׂ֖א דּוּמָ֑ה אֵלַ⁠י֙ קֹרֵ֣א מִ⁠שֵּׂעִ֔יר שֹׁמֵר֙ מַה־מִ⁠לַּ֔יְלָה שֹׁמֵ֖ר מַה־מִ⁠לֵּֽיל׃","maşá֖̇̂ʼ ḋẇmá֑h ʼéla⁠y֙ qòré֣ʼ mi⁠şé̇̂ʻi֔yr şò̌mér֙ mah-mi⁠lȧ֔yĕláh şò̌mé֖r mah-mi⁠léֽ̇yl׃"],[21,12,"אָמַ֣ר שֹׁמֵ֔ר אָתָ֥ה בֹ֖קֶר וְ⁠גַם־לָ֑יְלָה אִם־תִּבְעָי֥וּ⁠ן בְּעָ֖יוּ שֻׁ֥בוּ אֵתָֽיוּ׃ס","ʼáma֣r şò̌mé֔r ʼáţá֥h bò֖qer wĕ⁠gam-lá֑yĕláh ʼim-ţi̇bĕʻáy֥ẇ⁠n bĕ̇ʻá֖yẇ şǔ֥bẇ ʼéţáֽyẇ׃s"],[21,13,"מַשָּׂ֖א בַּ⁠עְרָ֑ב בַּ⁠יַּ֤עַר בַּ⁠עְרַב֙ תָּלִ֔ינוּ אֹֽרְח֖וֹת דְּדָנִֽים׃","maşá֖̇̂ʼ bȧ⁠ʻĕrá֑b bȧ⁠yȧ֤ʻar bȧ⁠ʻĕrab֙ ţá̇li֔ynẇ ʼòֽrĕẖ֖wòţ dĕ̇dániֽym׃"],[21,14,"לִ⁠קְרַ֥את צָמֵ֖א הֵתָ֣יוּ מָ֑יִם יֹשְׁבֵי֙ אֶ֣רֶץ תֵּימָ֔א בְּ⁠לַחְמ֖⁠וֹ קִדְּמ֥וּ נֹדֵֽד׃","li⁠qĕra֥ʼţ ẕámé֖ʼ héţá֣yẇ má֑yim yòşĕ̌béy֙ ʼe֣reẕ ţé̇ymá֔ʼ bĕ̇⁠laẖĕm֖⁠wò qidĕ̇m֥ẇ nòdéֽd׃"],[21,15,"כִּֽי־מִ⁠פְּנֵ֥י חֲרָב֖וֹת נָדָ֑דוּ מִ⁠פְּנֵ֣י ׀ חֶ֣רֶב נְטוּשָׁ֗ה וּ⁠מִ⁠פְּנֵי֙ קֶ֣שֶׁת דְּרוּכָ֔ה וּ⁠מִ⁠פְּנֵ֖י כֹּ֥בֶד מִלְחָמָֽה׃ס","kiֽ̇y-mi⁠pĕ̇né֥y ẖàráb֖wòţ nádá֑dẇ mi⁠pĕ̇né֣y ׀ ẖe֣reb nĕtẇşá̌֗h ẇ⁠mi⁠pĕ̇néy֙ qe֣şěţ dĕ̇rẇká֔h ẇ⁠mi⁠pĕ̇né֖y kò֥̇bed milĕẖámáֽh׃s"],[21,16,"כִּי־כֹ֛ה אָמַ֥ר אֲדֹנָ֖⁠י אֵלָ֑⁠י בְּ⁠ע֤וֹד שָׁנָה֙ כִּ⁠שְׁנֵ֣י שָׂכִ֔יר וְ⁠כָלָ֖ה כָּל־כְּב֥וֹד קֵדָֽר׃","ki̇y-kò֛h ʼáma֥r ʼàdòná֖⁠y ʼélá֑⁠y bĕ̇⁠ʻ֤wòd şá̌náh֙ ki̇⁠şĕ̌né֣y şá̂ki֔yr wĕ⁠kálá֖h ká̇l-kĕ̇b֥wòd qédáֽr׃"],[21,17,"וּ⁠שְׁאָ֧ר מִסְפַּר־קֶ֛שֶׁת גִּבּוֹרֵ֥י בְנֵֽי־קֵדָ֖ר יִמְעָ֑טוּ כִּ֛י יְהוָ֥ה אֱלֹהֵֽי־יִשְׂרָאֵ֖ל דִּבֵּֽר׃ס","ẇ⁠şĕ̌ʼá֧r misĕpȧr-qe֛şěţ gi̇ḃwòré֥y bĕnéֽy-qédá֖r yimĕʻá֑tẇ ki֛̇y yĕhwá֥h ʼèlòhéֽy-yişĕ̂ráʼé֖l di̇béֽ̇r׃s"],[22,1,"מַשָּׂ֖א גֵּ֣יא חִזָּי֑וֹן מַה־לָּ֣⁠ךְ אֵפ֔וֹא כִּֽי־עָלִ֥ית כֻּלָּ֖⁠ךְ לַ⁠גַּגּֽוֹת׃","maşá֖̇̂ʼ gé֣̇yʼ ẖizá̇y֑wòn mah-lá֣̇⁠kĕ ʼép֔wòʼ kiֽ̇y-ʻáli֥yţ ku̇lá֖̇⁠kĕ la⁠gȧġֽwòţ׃"],[22,2,"תְּשֻׁא֣וֹת ׀ מְלֵאָ֗ה עִ֚יר הֽוֹמִיָּ֔ה קִרְיָ֖ה עַלִּיזָ֑ה חֲלָלַ֨יִ⁠ךְ֙ לֹ֣א חַלְלֵי־חֶ֔רֶב וְ⁠לֹ֖א מֵתֵ֥י מִלְחָמָֽה׃","ţĕ̇şǔʼ֣wòţ ׀ mĕléʼá֗h ʻi֚yr hֽwòmiyá̇֔h qirĕyá֖h ʻali̇yzá֑h ẖàlála֨yi⁠kĕ֙ lò֣ʼ ẖalĕléy-ẖe֔reb wĕ⁠lò֖ʼ méţé֥y milĕẖámáֽh׃"],[22,3,"כָּל־קְצִינַ֥יִ⁠ךְ נָֽדְדוּ־יַ֖חַד מִ⁠קֶּ֣שֶׁת אֻסָּ֑רוּ כָּל־נִמְצָאַ֨יִ⁠ךְ֙ אֻסְּר֣וּ יַחְדָּ֔ו מֵ⁠רָח֖וֹק בָּרָֽחוּ׃","ká̇l-qĕẕiyna֥yi⁠kĕ náֽdĕdẇ-ya֖ẖad mi⁠qė֣şěţ ʼusá֑̇rẇ ká̇l-nimĕẕáʼa֨yi⁠kĕ֙ ʼusĕ̇r֣ẇ yaẖĕdá̇֔w mé⁠ráẖ֖wòq bá̇ráֽẖẇ׃"],[22,4,"עַל־כֵּ֥ן אָמַ֛רְתִּי שְׁע֥וּ מִ⁠נִּ֖י אֲמָרֵ֣ר בַּ⁠בֶּ֑כִי אַל־תָּאִ֣יצוּ לְ⁠נַֽחֲמֵ֔⁠נִי עַל־שֹׁ֖ד בַּת־עַמִּֽ⁠י׃","ʻal-ké֥̇n ʼáma֛rĕţi̇y şĕ̌ʻ֥ẇ mi⁠ni֖̇y ʼàmáré֣r bȧ⁠bė֑kiy ʼal-ţá̇ʼi֣yẕẇ lĕ⁠naֽẖàmé֔⁠niy ʻal-şò֖̌d bȧţ-ʻamiֽ̇⁠y׃"],[22,5,"כִּ֣י יוֹם֩ מְהוּמָ֨ה וּ⁠מְבוּסָ֜ה וּ⁠מְבוּכָ֗ה לַֽ⁠אדֹנָ֧⁠י יְהוִ֛ה צְבָא֖וֹת בְּ⁠גֵ֣יא חִזָּי֑וֹן מְקַרְקַ֥ר קִ֖ר וְ⁠שׁ֥וֹעַ אֶל־הָ⁠הָֽר׃","ki֣̇y ywòm֩ mĕhẇmá֨h ẇ⁠mĕbẇsá֜h ẇ⁠mĕbẇká֗h laֽ⁠ʼdòná֧⁠y yĕhwi֛h ẕĕbáʼ֖wòţ bĕ̇⁠gé֣yʼ ẖizá̇y֑wòn mĕqarĕqa֥r qi֖r wĕ⁠ş֥̌wòʻa ʼel-há⁠háֽr׃"],[22,6,"וְ⁠עֵילָם֙ נָשָׂ֣א אַשְׁפָּ֔ה בְּ⁠רֶ֥כֶב אָדָ֖ם פָּֽרָשִׁ֑ים וְ⁠קִ֥יר עֵרָ֖ה מָגֵֽן׃","wĕ⁠ʻéylám֙ náşá֣̂ʼ ʼaşĕ̌pá̇֔h bĕ̇⁠re֥keb ʼádá֖m páֽ̇ráşǐ֑ym wĕ⁠qi֥yr ʻérá֖h mágéֽn׃"],[22,7,"וַ⁠יְהִ֥י מִבְחַר־עֲמָקַ֖יִ⁠ךְ מָ֣לְאוּ רָ֑כֶב וְ⁠הַ⁠פָּ֣רָשִׁ֔ים שֹׁ֖ת שָׁ֥תוּ הַ⁠שָּֽׁעְרָ⁠ה׃","wa⁠yĕhi֥y mibĕẖar-ʻàmáqa֖yi⁠kĕ má֣lĕʼẇ rá֑keb wĕ⁠ha⁠pá֣̇ráşǐ֔ym şò֖̌ţ şá֥̌ţẇ ha⁠şáֽ̇̌ʻĕrá⁠h׃"],[22,8,"וַ⁠יְגַ֕ל אֵ֖ת מָסַ֣ךְ יְהוּדָ֑ה וַ⁠תַּבֵּט֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא אֶל־נֶ֖שֶׁק בֵּ֥ית הַ⁠יָּֽעַר׃","wa⁠yĕga֕l ʼé֖ţ mása֣kĕ yĕhẇdá֑h wa⁠ţȧbé̇t֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ʼel-ne֖şěq bé֥̇yţ ha⁠yáֽ̇ʻar׃"],[22,9,"וְ⁠אֵ֨ת בְּקִיעֵ֧י עִיר־דָּוִ֛ד רְאִיתֶ֖ם כִּי־רָ֑בּוּ וַֽ⁠תְּקַבְּצ֔וּ אֶת־מֵ֥י הַ⁠בְּרֵכָ֖ה הַ⁠תַּחְתּוֹנָֽה׃","wĕ⁠ʼé֨ţ bĕ̇qiyʻé֧y ʻiyr-dá̇wi֛d rĕʼiyţe֖m ki̇y-rá֑ḃẇ waֽ⁠ţĕ̇qabĕ̇ẕ֔ẇ ʼeţ-mé֥y ha⁠bĕ̇réká֖h ha⁠ţȧẖĕţ̇wònáֽh׃"],[22,10,"וְ⁠אֶת־בָּתֵּ֥י יְרוּשָׁלִַ֖ם סְפַרְתֶּ֑ם וַ⁠תִּתְֿצוּ֙ הַ⁠בָּ֣תִּ֔ים לְ⁠בַצֵּ֖ר הַ⁠חוֹמָֽה׃","wĕ⁠ʼeţ-bá̇ţé֥̇y yĕrẇşá̌lia֖m sĕparĕţė֑m wa⁠ţi̇ţĕ̄ẕẇ֙ ha⁠bá֣̇ţi̇֔ym lĕ⁠baẕé֖̇r ha⁠ẖwòmáֽh׃"],[22,11,"וּ⁠מִקְוָ֣ה ׀ עֲשִׂיתֶ֗ם בֵּ֚ין הַ⁠חֹ֣מֹתַ֔יִם לְ⁠מֵ֖י הַ⁠בְּרֵכָ֣ה הַ⁠יְשָׁנָ֑ה וְ⁠לֹ֤א הִבַּטְתֶּם֙ אֶל־עֹשֶׂ֔י⁠הָ וְ⁠יֹצְרָ֥⁠הּ מֵֽ⁠רָח֖וֹק לֹ֥א רְאִיתֶֽם׃","ẇ⁠miqĕwá֣h ׀ ʻàşîyţe֗m bé֚̇yn ha⁠ẖò֣mòţa֔yim lĕ⁠mé֖y ha⁠bĕ̇réká֣h ha⁠yĕşá̌ná֑h wĕ⁠lò֤ʼ hibȧtĕţėm֙ ʼel-ʻòşê֔y⁠há wĕ⁠yòẕĕrá֥⁠ḣ méֽ⁠ráẖ֖wòq lò֥ʼ rĕʼiyţeֽm׃"],[22,12,"וַ⁠יִּקְרָ֗א אֲדֹנָ֧⁠י יְהוִ֛ה צְבָא֖וֹת בַּ⁠יּ֣וֹם הַ⁠ה֑וּא לִ⁠בְכִי֙ וּ⁠לְ⁠מִסְפֵּ֔ד וּ⁠לְ⁠קָרְחָ֖ה וְ⁠לַ⁠חֲגֹ֥ר שָֽׂק׃","wa⁠yi̇qĕrá֗ʼ ʼàdòná֧⁠y yĕhwi֛h ẕĕbáʼ֖wòţ bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ li⁠bĕkiy֙ ẇ⁠lĕ⁠misĕpé̇֔d ẇ⁠lĕ⁠qárĕẖá֖h wĕ⁠la⁠ẖàgò֥r şáֽ̂q׃"],[22,13,"וְ⁠הִנֵּ֣ה ׀ שָׂשׂ֣וֹן וְ⁠שִׂמְחָ֗ה הָרֹ֤ג ׀ בָּקָר֙ וְ⁠שָׁחֹ֣ט צֹ֔אן אָכֹ֥ל בָּשָׂ֖ר וְ⁠שָׁת֣וֹת יָ֑יִן אָכ֣וֹל וְ⁠שָׁת֔וֹ כִּ֥י מָחָ֖ר נָמֽוּת׃","wĕ⁠hiné֣̇h ׀ şá̂ş֣̂wòn wĕ⁠şîmĕẖá֗h hárò֤g ׀ bá̇qár֙ wĕ⁠şá̌ẖò֣t ẕò֔ʼn ʼákò֥l bá̇şá֖̂r wĕ⁠şá̌ţ֣wòţ yá֑yin ʼák֣wòl wĕ⁠şá̌ţ֔wò ki֥̇y máẖá֖r námֽẇţ׃"],[22,14,"וְ⁠נִגְלָ֥ה בְ⁠אָזְנָ֖⁠י יְהוָ֣ה צְבָא֑וֹת אִם־יְ֠כֻפַּר הֶ⁠עָוֺ֨ן הַ⁠זֶּ֤ה לָ⁠כֶם֙ עַד־תְּמֻת֔וּ⁠ן אָמַ֛ר אֲדֹנָ֥⁠י יְהוִ֖ה צְבָאֽוֹת׃פ","wĕ⁠nigĕlá֥h bĕ⁠ʼázĕná֖⁠y yĕhwá֣h ẕĕbáʼ֑wòţ ʼim-yĕ֠kupȧr he⁠ʻáwֺ֨n ha⁠zė֤h lá⁠kem֙ ʻad-ţĕ̇muţ֔ẇ⁠n ʼáma֛r ʼàdòná֥⁠y yĕhwi֖h ẕĕbáʼֽwòţ׃p"],[22,15,"כֹּ֥ה אָמַ֛ר אֲדֹנָ֥⁠י יְהוִ֖ה צְבָא֑וֹת לֶךְ־בֹּא֙ אֶל־הַ⁠סֹּכֵ֣ן הַ⁠זֶּ֔ה עַל־שֶׁבְנָ֖א אֲשֶׁ֥ר עַל־הַ⁠בָּֽיִת׃","kò֥̇h ʼáma֛r ʼàdòná֥⁠y yĕhwi֖h ẕĕbáʼ֑wòţ lekĕ-bò̇ʼ֙ ʼel-ha⁠sò̇ké֣n ha⁠zė֔h ʻal-şěbĕná֖ʼ ʼàşě֥r ʻal-ha⁠báֽ̇yiţ׃"],[22,16,"מַה־לְּ⁠ךָ֥ פֹה֙ וּ⁠מִ֣י לְ⁠ךָ֣ פֹ֔ה כִּֽי־חָצַ֧בְתָּ לְּ⁠ךָ֛ פֹּ֖ה קָ֑בֶר חֹצְבִ֤י מָרוֹם֙ קִבְר֔⁠וֹ חֹקְקִ֥י בַ⁠סֶּ֖לַע מִשְׁכָּ֥ן לֽ⁠וֹ׃","mah-lĕ̇⁠ká֥ pòh֙ ẇ⁠mi֣y lĕ⁠ká֣ pò֔h kiֽ̇y-ẖáẕa֧bĕţá̇ lĕ̇⁠ká֛ pò֖̇h qá֑ber ẖòẕĕbi֤y márwòm֙ qibĕr֔⁠wò ẖòqĕqi֥y ba⁠sė֖laʻ mişĕ̌ká֥̇n lֽ⁠wò׃"],[22,17,"הִנֵּ֤ה יְהוָה֙ מְטַלְטֶלְ⁠ךָ֔ טַלְטֵלָ֖ה גָּ֑בֶר וְ⁠עֹטְ⁠ךָ֖ עָטֹֽה׃","hiné֤̇h yĕhwáh֙ mĕtalĕtelĕ⁠ká֔ talĕtélá֖h gá֑̇ber wĕ⁠ʻòtĕ⁠ká֖ ʻátòֽh׃"],[22,18,"צָנ֤וֹף יִצְנָפְ⁠ךָ֙ צְנֵפָ֔ה כַּדּ֕וּר אֶל־אֶ֖רֶץ רַחֲבַ֣ת יָדָ֑יִם שָׁ֣מָּ⁠ה תָמ֗וּת וְ⁠שָׁ֨מָּ⁠ה֙ מַרְכְּב֣וֹת כְּבוֹדֶ֔⁠ךָ קְל֖וֹן בֵּ֥ית אֲדֹנֶֽי⁠ךָ׃","ẕán֤wòp yiẕĕnápĕ⁠ká֙ ẕĕnépá֔h kȧḋ֕ẇr ʼel-ʼe֖reẕ raẖàba֣ţ yádá֑yim şá֣̌má̇⁠h ţám֗ẇţ wĕ⁠şá̌֨má̇⁠h֙ marĕkĕ̇b֣wòţ kĕ̇bwòde֔⁠ká qĕl֖wòn bé֥̇yţ ʼàdòneֽy⁠ká׃"],[22,19,"וַ⁠הֲדַפְתִּ֖י⁠ךָ מִ⁠מַּצָּבֶ֑⁠ךָ וּ⁠מִ⁠מַּעֲמָֽדְ⁠ךָ֖ יֶהֶרְסֶֽ⁠ךָ׃","wa⁠hàdapĕţi֖̇y⁠ká mi⁠mȧẕá̇be֑⁠ká ẇ⁠mi⁠mȧʻàmáֽdĕ⁠ká֖ yeherĕseֽ⁠ká׃"],[22,20,"וְ⁠הָיָ֖ה בַּ⁠יּ֣וֹם הַ⁠ה֑וּא וְ⁠קָרָ֣אתִי לְ⁠עַבְדִּ֔⁠י לְ⁠אֶלְיָקִ֖ים בֶּן־חִלְקִיָּֽהוּ׃","wĕ⁠háyá֖h bȧ⁠ẏ֣wòm ha⁠h֑ẇʼ wĕ⁠qárá֣ʼţiy lĕ⁠ʻabĕdi̇֔⁠y lĕ⁠ʼelĕyáqi֖ym bėn-ẖilĕqiyáֽ̇hẇ׃"],[22,21,"וְ⁠הִלְבַּשְׁתִּ֣י⁠ו כֻּתָּנְתֶּ֗⁠ךָ וְ⁠אַבְנֵֽטְ⁠ךָ֙ אֲחַזְּקֶ֔⁠נּוּ וּ⁠מֶֽמְשֶׁלְתְּ⁠ךָ֖ אֶתֵּ֣ן בְּ⁠יָד֑⁠וֹ וְ⁠הָיָ֥ה לְ⁠אָ֛ב לְ⁠יוֹשֵׁ֥ב יְרוּשָׁלִַ֖ם וּ⁠לְ⁠בֵ֥ית יְהוּדָֽה׃","wĕ⁠hilĕbȧşĕ̌ţi֣̇y⁠w ku̇ţá̇nĕţė֗⁠ká wĕ⁠ʼabĕnéֽtĕ⁠ká֙ ʼàẖazĕ̇qe֔⁠ṅẇ ẇ⁠meֽmĕşělĕţĕ̇⁠ká֖ ʼeţé֣̇n bĕ̇⁠yád֑⁠wò wĕ⁠háyá֥h lĕ⁠ʼá֛b lĕ⁠ywòşé֥̌b yĕrẇşá̌lia֖m ẇ⁠lĕ⁠bé֥yţ yĕhẇdáֽh׃"],[22,22,"וְ⁠נָתַתִּ֛י מַפְתֵּ֥חַ בֵּית־דָּוִ֖ד עַל־שִׁכְמ֑⁠וֹ וּ⁠פָתַח֙ וְ⁠אֵ֣ין סֹגֵ֔ר וְ⁠סָגַ֖ר וְ⁠אֵ֥ין פֹּתֵֽחַ׃","wĕ⁠náţaţi֛̇y mapĕţé֥̇ẖa bé̇yţ-dá̇wi֖d ʻal-şǐkĕm֑⁠wò ẇ⁠páţaẖ֙ wĕ⁠ʼé֣yn sògé֔r wĕ⁠sága֖r wĕ⁠ʼé֥yn pò̇ţéֽẖa׃"],[22,23,"וּ⁠תְקַעְתִּ֥י⁠ו יָתֵ֖ד בְּ⁠מָק֣וֹם נֶאֱמָ֑ן וְ⁠הָיָ֛ה לְ⁠כִסֵּ֥א כָב֖וֹד לְ⁠בֵ֥ית אָבִֽי⁠ו׃","ẇ⁠ţĕqaʻĕţi֥̇y⁠w yáţé֖d bĕ̇⁠máq֣wòm neʼèmá֑n wĕ⁠háyá֛h lĕ⁠kisé֥̇ʼ káb֖wòd lĕ⁠bé֥yţ ʼábiֽy⁠w׃"],[22,24,"וְ⁠תָל֨וּ עָלָ֜י⁠ו כֹּ֣ל ׀ כְּב֣וֹד בֵּית־אָבִ֗י⁠ו הַ⁠צֶּֽאֱצָאִים֙ וְ⁠הַ⁠צְּפִע֔וֹת כֹּ֖ל כְּלֵ֣י הַ⁠קָּטָ֑ן מִ⁠כְּלֵי֙ הָֽ⁠אַגָּנ֔וֹת וְ⁠עַ֖ד כָּל־כְּלֵ֥י הַ⁠נְּבָלִֽים׃","wĕ⁠ţál֨ẇ ʻálá֜y⁠w kò֣̇l ׀ kĕ̇b֣wòd bé̇yţ-ʼábi֗y⁠w ha⁠ẕėֽʼèẕáʼiym֙ wĕ⁠ha⁠ẕĕ̇piʻ֔wòţ kò֖̇l kĕ̇lé֣y ha⁠qá̇tá֑n mi⁠kĕ̇léy֙ háֽ⁠ʼagá̇n֔wòţ wĕ⁠ʻa֖d ká̇l-kĕ̇lé֥y ha⁠nĕ̇báliֽym׃"],[22,25,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא נְאֻם֙ יְהוָ֣ה צְבָא֔וֹת תָּמוּשׁ֙ הַ⁠יָּתֵ֔ד הַ⁠תְּקוּעָ֖ה בְּ⁠מָק֣וֹם נֶאֱמָ֑ן וְ⁠נִגְדְּעָ֣ה וְ⁠נָפְלָ֗ה וְ⁠נִכְרַת֙ הַ⁠מַּשָּׂ֣א אֲשֶׁר־עָלֶ֔י⁠הָ כִּ֥י יְהוָ֖ה דִּבֵּֽר׃ס","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ nĕʼum֙ yĕhwá֣h ẕĕbáʼ֔wòţ ţá̇mẇş̌֙ ha⁠yá̇ţé֔d ha⁠ţĕ̇qẇʻá֖h bĕ̇⁠máq֣wòm neʼèmá֑n wĕ⁠nigĕdĕ̇ʻá֣h wĕ⁠nápĕlá֗h wĕ⁠nikĕraţ֙ ha⁠mȧşá֣̇̂ʼ ʼàşěr-ʻále֔y⁠há ki֥̇y yĕhwá֖h di̇béֽ̇r׃s"],[23,1,"מַשָּׂ֖א צֹ֑ר הֵילִ֣ילוּ ׀ אֳנִיּ֣וֹת תַּרְשִׁ֗ישׁ כִּֽי־שֻׁדַּ֤ד מִ⁠בַּ֨יִת֙ מִ⁠בּ֔וֹא מֵ⁠אֶ֥רֶץ כִּתִּ֖ים נִגְלָה־לָֽ⁠מוֹ׃","maşá֖̇̂ʼ ẕò֑r héyli֣ylẇ ׀ ʼoniẏ֣wòţ ţȧrĕşǐ֗yş̌ kiֽ̇y-şǔdȧ֤d mi⁠bȧ֨yiţ֙ mi⁠ḃ֔wòʼ mé⁠ʼe֥reẕ ki̇ţi֖̇ym nigĕláh-láֽ⁠mwò׃"],[23,2,"דֹּ֖מּוּ יֹ֣שְׁבֵי אִ֑י סֹחֵ֥ר צִיד֛וֹן עֹבֵ֥ר יָ֖ם מִלְאֽוּ⁠ךְ׃","dò֖̇ṁẇ yò֣şĕ̌béy ʼi֑y sòẖé֥r ẕiyd֛wòn ʻòbé֥r yá֖m milĕʼֽẇ⁠kĕ׃"],[23,3,"וּ⁠בְ⁠מַ֤יִם רַבִּים֙ זֶ֣רַע שִׁחֹ֔ר קְצִ֥יר יְא֖וֹר תְּבֽוּאָתָ֑⁠הּ וַ⁠תְּהִ֖י סְחַ֥ר גּוֹיִֽם׃","ẇ⁠bĕ⁠ma֤yim rabi̇ym֙ ze֣raʻ şǐẖò֔r qĕẕi֥yr yĕʼ֖wòr ţĕ̇bֽẇʼáţá֑⁠ḣ wa⁠ţĕ̇hi֖y sĕẖa֥r ġwòyiֽm׃"],[23,4,"בּ֣וֹשִׁי צִיד֔וֹן כִּֽי־אָמַ֣ר יָ֔ם מָע֥וֹז הַ⁠יָּ֖ם לֵ⁠אמֹ֑ר לֹֽא־חַ֣לְתִּי וְ⁠לֹֽא־יָלַ֗דְתִּי וְ⁠לֹ֥א גִדַּ֛לְתִּי בַּחוּרִ֖ים רוֹמַ֥מְתִּי בְתוּלֽוֹת׃","ḃ֣wòşǐy ẕiyd֔wòn kiֽ̇y-ʼáma֣r yá֔m máʻ֥wòz ha⁠yá֖̇m lé⁠ʼmò֑r lòֽʼ-ẖa֣lĕţi̇y wĕ⁠lòֽʼ-yála֗dĕţi̇y wĕ⁠lò֥ʼ gidȧ֛lĕţi̇y bȧẖẇri֖ym rwòma֥mĕţi̇y bĕţẇlֽwòţ׃"],[23,5,"כַּֽ⁠אֲשֶׁר־שֵׁ֖מַע לְ⁠מִצְרָ֑יִם יָחִ֖ילוּ כְּ⁠שֵׁ֥מַע צֹֽר׃","kȧֽ⁠ʼàşěr-şé֖̌maʻ lĕ⁠miẕĕrá֑yim yáẖi֖ylẇ kĕ̇⁠şé֥̌maʻ ẕòֽr׃"],[23,6,"עִבְר֖וּ תַּרְשִׁ֑ישָׁ⁠ה הֵילִ֖ילוּ יֹ֥שְׁבֵי אִֽי׃","ʻibĕr֖ẇ ţȧrĕşǐ֑yşá̌⁠h héyli֖ylẇ yò֥şĕ̌béy ʼiֽy׃"],[23,7,"הֲ⁠זֹ֥את לָ⁠כֶ֖ם עַלִּיזָ֑ה מִֽ⁠ימֵי־קֶ֤דֶם קַדְמָתָ⁠הּ֙ יֹבִל֣וּ⁠הָ רַגְלֶ֔י⁠הָ מֵֽ⁠רָח֖וֹק לָ⁠גֽוּר׃","hà⁠zò֥ʼţ lá⁠ke֖m ʻali̇yzá֑h miֽ⁠yméy-qe֤dem qadĕmáţá⁠ḣ֙ yòbil֣ẇ⁠há ragĕle֔y⁠há méֽ⁠ráẖ֖wòq lá⁠gֽẇr׃"],[23,8,"מִ֚י יָעַ֣ץ זֹ֔את עַל־צֹ֖ר הַ⁠מַּֽעֲטִירָ֑ה אֲשֶׁ֤ר סֹחֲרֶ֨י⁠ה֙ שָׂרִ֔ים כִּנְעָנֶ֖י⁠הָ נִכְבַּדֵּי־אָֽרֶץ׃","mi֚y yáʻa֣ẕ zò֔ʼţ ʻal-ẕò֖r ha⁠mȧֽʻàtiyrá֑h ʼàşě֤r sòẖàre֨y⁠h֙ şá̂ri֔ym ki̇nĕʻáne֖y⁠há nikĕbȧdé̇y-ʼáֽreẕ׃"],[23,9,"יְהוָ֥ה צְבָא֖וֹת יְעָצָ֑⁠הּ לְ⁠חַלֵּל֙ גְּא֣וֹן כָּל־צְבִ֔י לְ⁠הָקֵ֖ל כָּל־נִכְבַּדֵּי־אָֽרֶץ׃","yĕhwá֥h ẕĕbáʼ֖wòţ yĕʻáẕá֑⁠ḣ lĕ⁠ẖalé̇l֙ gĕ̇ʼ֣wòn ká̇l-ẕĕbi֔y lĕ⁠háqé֖l ká̇l-nikĕbȧdé̇y-ʼáֽreẕ׃"],[23,10,"עִבְרִ֥י אַרְצֵ֖⁠ךְ כַּ⁠יְאֹ֑ר בַּת־תַּרְשִׁ֕ישׁ אֵ֖ין מֵ֥זַח עֽוֹד׃","ʻibĕri֥y ʼarĕẕé֖⁠kĕ kȧ⁠yĕʼò֑r bȧţ-ţȧrĕşǐ֕yş̌ ʼé֖yn mé֥zaẖ ʻֽwòd׃"],[23,11,"יָד⁠וֹ֙ נָטָ֣ה עַל־הַ⁠יָּ֔ם הִרְגִּ֖יז מַמְלָכ֑וֹת יְהוָה֙ צִוָּ֣ה אֶל־כְּנַ֔עַן לַ⁠שְׁמִ֖ד מָעֻזְנֶֽי⁠הָ׃","yád⁠wò֙ nátá֣h ʻal-ha⁠yá̇֔m hirĕgi֖̇yz mamĕlák֑wòţ yĕhwáh֙ ẕiwá֣̇h ʼel-kĕ̇na֔ʻan la⁠şĕ̌mi֖d máʻuzĕneֽy⁠há׃"],[23,12,"וַ⁠יֹּ֕אמֶר לֹֽא־תוֹסִ֥יפִי ע֖וֹד לַ⁠עְל֑וֹז הַֽ⁠מְעֻשָּׁקָ֞ה בְּתוּלַ֣ת בַּת־צִיד֗וֹן כתיים ק֣וּמִי עֲבֹ֔רִי גַּם־שָׁ֖ם לֹא־יָנ֥וּחַֽ לָֽ⁠ךְ׃","wa⁠yò̇֕ʼmer lòֽʼ-ţwòsi֥ypiy ʻ֖wòd la⁠ʻĕl֑wòz haֽ⁠mĕʻuşá̇̌qá֞h bĕ̇ţẇla֣ţ bȧţ-ẕiyd֗wòn kţyym q֣ẇmiy ʻàbò֔riy gȧm-şá֖̌m lòʼ-yán֥ẇẖaֽ láֽ⁠kĕ׃"],[23,13,"הֵ֣ן ׀ אֶ֣רֶץ כַּשְׂדִּ֗ים זֶ֤ה הָ⁠עָם֙ לֹ֣א הָיָ֔ה אַשּׁ֖וּר יְסָדָ֣⁠הּ לְ⁠צִיִּ֑ים הֵקִ֣ימוּ בחיני⁠ו עֹרְרוּ֙ אַרְמְנוֹתֶ֔י⁠הָ שָׂמָ֖⁠הּ לְ⁠מַפֵּלָֽה׃","hé֣n ׀ ʼe֣reẕ kȧşĕ̂di̇֗ym ze֤h há⁠ʻám֙ lò֣ʼ háyá֔h ʼaş֖̇̌ẇr yĕsádá֣⁠ḣ lĕ⁠ẕiyi֑̇ym héqi֣ymẇ bẖyny⁠w ʻòrĕrẇ֙ ʼarĕmĕnwòţe֔y⁠há şá̂má֖⁠ḣ lĕ⁠mapé̇láֽh׃"],[23,14,"הֵילִ֖ילוּ אֳנִיּ֣וֹת תַּרְשִׁ֑ישׁ כִּ֥י שֻׁדַּ֖ד מָעֻזְּ⁠כֶֽן׃ס","héyli֖ylẇ ʼoniẏ֣wòţ ţȧrĕşǐ֑yş̌ ki֥̇y şǔdȧ֖d máʻuzĕ̇⁠keֽn׃s"],[23,15,"וְ⁠הָיָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא וְ⁠נִשְׁכַּ֤חַת צֹר֙ שִׁבְעִ֣ים שָׁנָ֔ה כִּ⁠ימֵ֖י מֶ֣לֶךְ אֶחָ֑ד מִ⁠קֵּ֞ץ שִׁבְעִ֤ים שָׁנָה֙ יִהְיֶ֣ה לְ⁠צֹ֔ר כְּ⁠שִׁירַ֖ת הַ⁠זּוֹנָֽה׃","wĕ⁠háyáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ wĕ⁠nişĕ̌kȧ֤ẖaţ ẕòr֙ şǐbĕʻi֣ym şá̌ná֔h ki̇⁠ymé֖y me֣lekĕ ʼeẖá֑d mi⁠qé̇֞ẕ şǐbĕʻi֤ym şá̌náh֙ yihĕye֣h lĕ⁠ẕò֔r kĕ̇⁠şǐyra֖ţ ha⁠żwònáֽh׃"],[23,16,"קְחִ֥י כִנּ֛וֹר סֹ֥בִּי עִ֖יר זוֹנָ֣ה נִשְׁכָּחָ֑ה הֵיטִ֤יבִי נַגֵּן֙ הַרְבִּי־שִׁ֔יר לְמַ֖עַן תִּזָּכֵֽרִי׃","qĕẖi֥y kiṅ֛wòr sò֥bi̇y ʻi֖yr zwòná֣h nişĕ̌ká̇ẖá֑h héyti֤ybiy nagé̇n֙ harĕbi̇y-şǐ֔yr lĕma֖ʻan ţi̇zá̇kéֽriy׃"],[23,17,"וְ⁠הָיָ֞ה מִ⁠קֵּ֣ץ ׀ שִׁבְעִ֣ים שָׁנָ֗ה יִפְקֹ֤ד יְהוָה֙ אֶת־צֹ֔ר וְ⁠שָׁבָ֖ה לְ⁠אֶתְנַנָּ֑⁠ה וְ⁠זָֽנְתָ֛ה אֶת־כָּל־מַמְלְכ֥וֹת הָ⁠אָ֖רֶץ עַל־פְּנֵ֥י הָ⁠אֲדָמָֽה׃","wĕ⁠háyá֞h mi⁠qé֣̇ẕ ׀ şǐbĕʻi֣ym şá̌ná֗h yipĕqò֤d yĕhwáh֙ ʼeţ-ẕò֔r wĕ⁠şá̌bá֖h lĕ⁠ʼeţĕnaná֑̇⁠h wĕ⁠záֽnĕţá֛h ʼeţ-ká̇l-mamĕlĕk֥wòţ há⁠ʼá֖reẕ ʻal-pĕ̇né֥y há⁠ʼàdámáֽh׃"],[23,18,"וְ⁠הָיָ֨ה סַחְרָ֜⁠הּ וְ⁠אֶתְנַנָּ֗⁠הּ קֹ֚דֶשׁ לַֽ⁠יהוָ֔ה לֹ֥א יֵֽאָצֵ֖ר וְ⁠לֹ֣א יֵֽחָסֵ֑ן כִּ֣י לַ⁠יֹּשְׁבִ֞ים לִ⁠פְנֵ֤י יְהוָה֙ יִֽהְיֶ֣ה סַחְרָ֔⁠הּ לֶ⁠אֱכֹ֥ל לְ⁠שָׂבְעָ֖ה וְ⁠לִ⁠מְכַסֶּ֥ה עָתִֽיק׃פ","wĕ⁠háyá֨h saẖĕrá֜⁠ḣ wĕ⁠ʼeţĕnaná̇֗⁠ḣ qò֚deş̌ laֽ⁠yhwá֔h lò֥ʼ yéֽʼáẕé֖r wĕ⁠lò֣ʼ yéֽẖásé֑n ki֣̇y la⁠yò̇şĕ̌bi֞ym li⁠pĕné֤y yĕhwáh֙ yiֽhĕye֣h saẖĕrá֔⁠ḣ le⁠ʼèkò֥l lĕ⁠şá̂bĕʻá֖h wĕ⁠li⁠mĕkasė֥h ʻáţiֽyq׃p"],[24,1,"הִנֵּ֧ה יְהוָ֛ה בּוֹקֵ֥ק הָ⁠אָ֖רֶץ וּ⁠בֽוֹלְקָ֑⁠הּ וְ⁠עִוָּ֣ה פָנֶ֔י⁠הָ וְ⁠הֵפִ֖יץ יֹשְׁבֶֽי⁠הָ׃","hiné֧̇h yĕhwá֛h ḃwòqé֥q há⁠ʼá֖reẕ ẇ⁠bֽwòlĕqá֑⁠ḣ wĕ⁠ʻiwá֣̇h páne֔y⁠há wĕ⁠hépi֖yẕ yòşĕ̌beֽy⁠há׃"],[24,2,"וְ⁠הָיָ֤ה כָ⁠עָם֙ כַּ⁠כֹּהֵ֔ן כַּ⁠עֶ֨בֶד֙ כַּֽ⁠אדֹנָ֔י⁠ו כַּ⁠שִּׁפְחָ֖ה כַּ⁠גְּבִרְתָּ֑⁠הּ כַּ⁠קּוֹנֶה֙ כַּ⁠מּוֹכֵ֔ר כַּ⁠מַּלְוֶה֙ כַּ⁠לֹּוֶ֔ה כַּ⁠נֹּשֶׁ֕ה כַּ⁠אֲשֶׁ֖ר נֹשֶׁ֥א בֽ⁠וֹ׃","wĕ⁠háyá֤h ká⁠ʻám֙ kȧ⁠kò̇hé֔n kȧ⁠ʻe֨bed֙ kȧֽ⁠ʼdòná֔y⁠w kȧ⁠şi̇̌pĕẖá֖h kȧ⁠gĕ̇birĕţá֑̇⁠ḣ kȧ⁠q̇wòneh֙ kȧ⁠ṁwòké֔r kȧ⁠mȧlĕweh֙ kȧ⁠lò̇we֔h kȧ⁠nò̇şě֕h kȧ⁠ʼàşě֖r nòşě֥ʼ bֽ⁠wò׃"],[24,3,"הִבּ֧וֹק ׀ תִּבּ֛וֹק הָ⁠אָ֖רֶץ וְ⁠הִבּ֣וֹז ׀ תִּבּ֑וֹז כִּ֣י יְהוָ֔ה דִּבֶּ֖ר אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּֽה׃","hiḃ֧wòq ׀ ţi̇ḃ֛wòq há⁠ʼá֖reẕ wĕ⁠hiḃ֣wòz ׀ ţi̇ḃ֑wòz ki֣̇y yĕhwá֔h di̇bė֖r ʼeţ-ha⁠dá̇bá֥r ha⁠zėֽh׃"],[24,4,"אָבְלָ֤ה נָֽבְלָה֙ הָ⁠אָ֔רֶץ אֻמְלְלָ֥ה נָבְלָ֖ה תֵּבֵ֑ל אֻמְלָ֖לוּ מְר֥וֹם עַם־הָ⁠אָֽרֶץ׃","ʼábĕlá֤h náֽbĕláh֙ há⁠ʼá֔reẕ ʼumĕlĕlá֥h nábĕlá֖h ţé̇bé֑l ʼumĕlá֖lẇ mĕr֥wòm ʻam-há⁠ʼáֽreẕ׃"],[24,5,"וְ⁠הָ⁠אָ֥רֶץ חָנְפָ֖ה תַּ֣חַת יֹשְׁבֶ֑י⁠הָ כִּֽי־עָבְר֤וּ תוֹרֹת֙ חָ֣לְפוּ חֹ֔ק הֵפֵ֖רוּ בְּרִ֥ית עוֹלָֽם׃","wĕ⁠há⁠ʼá֥reẕ ẖánĕpá֖h ţȧ֣ẖaţ yòşĕ̌be֑y⁠há kiֽ̇y-ʻábĕr֤ẇ ţwòròţ֙ ẖá֣lĕpẇ ẖò֔q hépé֖rẇ bĕ̇ri֥yţ ʻwòláֽm׃"],[24,6,"עַל־כֵּ֗ן אָלָה֙ אָ֣כְלָה אֶ֔רֶץ וַֽ⁠יֶּאְשְׁמ֖וּ יֹ֣שְׁבֵי בָ֑⁠הּ עַל־כֵּ֗ן חָרוּ֙ יֹ֣שְׁבֵי אֶ֔רֶץ וְ⁠נִשְׁאַ֥ר אֱנ֖וֹשׁ מִזְעָֽר׃","ʻal-ké̇֗n ʼáláh֙ ʼá֣kĕláh ʼe֔reẕ waֽ⁠yėʼĕşĕ̌m֖ẇ yò֣şĕ̌béy bá֑⁠ḣ ʻal-ké̇֗n ẖárẇ֙ yò֣şĕ̌béy ʼe֔reẕ wĕ⁠nişĕ̌ʼa֥r ʼèn֖wòş̌ mizĕʻáֽr׃"],[24,7,"אָבַ֥ל תִּיר֖וֹשׁ אֻמְלְלָה־גָ֑פֶן נֶאֶנְח֖וּ כָּל־שִׂמְחֵי־לֵֽב׃","ʼába֥l ţi̇yr֖wòş̌ ʼumĕlĕláh-gá֑pen neʼenĕẖ֖ẇ ká̇l-şîmĕẖéy-léֽb׃"],[24,8,"שָׁבַת֙ מְשׂ֣וֹשׂ תֻּפִּ֔ים חָדַ֖ל שְׁא֣וֹן עַלִּיזִ֑ים שָׁבַ֖ת מְשׂ֥וֹשׂ כִּנּֽוֹר׃","şá̌baţ֙ mĕş֣̂wòş̂ ţu̇pi̇֔ym ẖáda֖l şĕ̌ʼ֣wòn ʻali̇yzi֑ym şá̌ba֖ţ mĕş֥̂wòş̂ ki̇ṅֽwòr׃"],[24,9,"בַּ⁠שִּׁ֖יר לֹ֣א יִשְׁתּוּ־יָ֑יִן יֵמַ֥ר שֵׁכָ֖ר לְ⁠שֹׁתָֽי⁠ו׃","bȧ⁠şi֖̇̌yr lò֣ʼ yişĕ̌ţ̇ẇ-yá֑yin yéma֥r şé̌ká֖r lĕ⁠şò̌ţáֽy⁠w׃"],[24,10,"נִשְׁבְּרָ֖ה קִרְיַת־תֹּ֑הוּ סֻגַּ֥ר כָּל־בַּ֖יִת מִ⁠בּֽוֹא׃","nişĕ̌bĕ̇rá֖h qirĕyaţ-ţò֑̇hẇ sugȧ֥r ká̇l-bȧ֖yiţ mi⁠ḃֽwòʼ׃"],[24,11,"צְוָחָ֥ה עַל־הַ⁠יַּ֖יִן בַּֽ⁠חוּצ֑וֹת עָֽרְבָה֙ כָּל־שִׂמְחָ֔ה גָּלָ֖ה מְשׂ֥וֹשׂ הָ⁠אָֽרֶץ׃","ẕĕwáẖá֥h ʻal-ha⁠yȧ֖yin bȧֽ⁠ẖẇẕ֑wòţ ʻáֽrĕbáh֙ ká̇l-şîmĕẖá֔h gá̇lá֖h mĕş֥̂wòş̂ há⁠ʼáֽreẕ׃"],[24,12,"נִשְׁאַ֥ר בָּ⁠עִ֖יר שַׁמָּ֑ה וּ⁠שְׁאִיָּ֖ה יֻכַּת־שָֽׁעַר׃","nişĕ̌ʼa֥r bá̇⁠ʻi֖yr şǎmá֑̇h ẇ⁠şĕ̌ʼiyá֖̇h yukȧţ-şáֽ̌ʻar׃"],[24,13,"כִּ֣י כֹ֥ה יִהְיֶ֛ה בְּ⁠קֶ֥רֶב הָ⁠אָ֖רֶץ בְּ⁠ת֣וֹךְ הָֽ⁠עַמִּ֑ים כְּ⁠נֹ֣קֶף זַ֔יִת כְּ⁠עוֹלֵלֹ֖ת אִם־כָּלָ֥ה בָצִֽיר׃","ki֣̇y kò֥h yihĕye֛h bĕ̇⁠qe֥reb há⁠ʼá֖reẕ bĕ̇⁠ţ֣wòkĕ háֽ⁠ʻami֑̇ym kĕ̇⁠nò֣qep za֔yiţ kĕ̇⁠ʻwòlélò֖ţ ʼim-ká̇lá֥h báẕiֽyr׃"],[24,14,"הֵ֛מָּה יִשְׂא֥וּ קוֹלָ֖⁠ם יָרֹ֑נּוּ בִּ⁠גְא֣וֹן יְהוָ֔ה צָהֲל֖וּ מִ⁠יָּֽם׃","hé֛má̇h yişĕ̂ʼ֥ẇ qwòlá֖⁠m yárò֑ṅẇ bi̇⁠gĕʼ֣wòn yĕhwá֔h ẕáhàl֖ẇ mi⁠yáֽ̇m׃"],[24,15,"עַל־כֵּ֥ן בָּ⁠אֻרִ֖ים כַּבְּד֣וּ יְהוָ֑ה בְּ⁠אִיֵּ֣י הַ⁠יָּ֔ם שֵׁ֥ם יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃ס","ʻal-ké֥̇n bá̇⁠ʼuri֖ym kȧbĕ̇d֣ẇ yĕhwá֑h bĕ̇⁠ʼiyé֣̇y ha⁠yá̇֔m şé֥̌m yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃s"],[24,16,"מִ⁠כְּנַ֨ף הָ⁠אָ֜רֶץ זְמִרֹ֤ת שָׁמַ֨עְנוּ֙ צְבִ֣י לַ⁠צַּדִּ֔יק וָ⁠אֹמַ֛ר רָזִי־לִ֥⁠י רָֽזִי־לִ֖⁠י א֣וֹי לִ֑⁠י בֹּגְדִ֣ים בָּגָ֔דוּ וּ⁠בֶ֥גֶד בּוֹגְדִ֖ים בָּגָֽדוּ׃","mi⁠kĕ̇na֨p há⁠ʼá֜reẕ zĕmirò֤ţ şá̌ma֨ʻĕnẇ֙ ẕĕbi֣y la⁠ẕȧdi̇֔yq wá⁠ʼòma֛r ráziy-li֥⁠y ráֽziy-li֖⁠y ʼ֣wòy li֑⁠y bò̇gĕdi֣ym bá̇gá֔dẇ ẇ⁠be֥ged ḃwògĕdi֖ym bá̇gáֽdẇ׃"],[24,17,"פַּ֥חַד וָ⁠פַ֖חַת וָ⁠פָ֑ח עָלֶ֖י⁠ךָ יוֹשֵׁ֥ב הָ⁠אָֽרֶץ׃","pȧ֥ẖad wá⁠pa֖ẖaţ wá⁠pá֑ẖ ʻále֖y⁠ká ywòşé֥̌b há⁠ʼáֽreẕ׃"],[24,18,"וְֽ֠⁠הָיָה הַ⁠נָּ֞ס מִ⁠קּ֤וֹל הַ⁠פַּ֨חַד֙ יִפֹּ֣ל אֶל־הַ⁠פַּ֔חַת וְ⁠הָֽ⁠עוֹלֶה֙ מִ⁠תּ֣וֹךְ הַ⁠פַּ֔חַת יִלָּכֵ֖ד בַּ⁠פָּ֑ח כִּֽי־אֲרֻבּ֤וֹת מִ⁠מָּרוֹם֙ נִפְתָּ֔חוּ וַֽ⁠יִּרְעֲשׁ֖וּ מ֥וֹסְדֵי אָֽרֶץ׃","wֽĕ֠⁠háyáh ha⁠ná̇֞s mi⁠q֤̇wòl ha⁠pȧ֨ẖad֙ yipò֣̇l ʼel-ha⁠pȧ֔ẖaţ wĕ⁠háֽ⁠ʻwòleh֙ mi⁠ţ֣̇wòkĕ ha⁠pȧ֔ẖaţ yilá̇ké֖d bȧ⁠pá֑̇ẖ kiֽ̇y-ʼàruḃ֤wòţ mi⁠má̇rwòm֙ nipĕţá̇֔ẖẇ waֽ⁠yi̇rĕʻàş֖̌ẇ m֥wòsĕdéy ʼáֽreẕ׃"],[24,19,"רֹ֥עָה הִֽתְרֹעֲעָ֖ה הָ⁠אָ֑רֶץ פּ֤וֹר הִֽתְפּוֹרְרָה֙ אֶ֔רֶץ מ֥וֹט הִֽתְמוֹטְטָ֖ה אָֽרֶץ׃","rò֥ʻáh hiֽţĕròʻàʻá֖h há⁠ʼá֑reẕ ṗ֤wòr hiֽţĕṗwòrĕráh֙ ʼe֔reẕ m֥wòt hiֽţĕmwòtĕtá֖h ʼáֽreẕ׃"],[24,20,"נ֣וֹעַ תָּנ֤וּעַ אֶ֨רֶץ֙ כַּ⁠שִּׁכּ֔וֹר וְ⁠הִֽתְנוֹדְדָ֖ה כַּ⁠מְּלוּנָ֑ה וְ⁠כָבַ֤ד עָלֶ֨י⁠הָ֙ פִּשְׁעָ֔⁠הּ וְ⁠נָפְלָ֖ה וְ⁠לֹא־תֹסִ֥יף קֽוּם׃ס","n֣wòʻa ţá̇n֤ẇʻa ʼe֨reẕ֙ kȧ⁠şi̇̌k̇֔wòr wĕ⁠hiֽţĕnwòdĕdá֖h kȧ⁠mĕ̇lẇná֑h wĕ⁠kába֤d ʻále֨y⁠há֙ pi̇şĕ̌ʻá֔⁠ḣ wĕ⁠nápĕlá֖h wĕ⁠lòʼ-ţòsi֥yp qֽẇm׃s"],[24,21,"וְ⁠הָיָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא יִפְקֹ֧ד יְהוָ֛ה עַל־צְבָ֥א הַ⁠מָּר֖וֹם בַּ⁠מָּר֑וֹם וְ⁠עַל־מַלְכֵ֥י הָ⁠אֲדָמָ֖ה עַל־הָ⁠אֲדָמָֽה׃","wĕ⁠háyáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ yipĕqò֧d yĕhwá֛h ʻal-ẕĕbá֥ʼ ha⁠má̇r֖wòm bȧ⁠má̇r֑wòm wĕ⁠ʻal-malĕké֥y há⁠ʼàdámá֖h ʻal-há⁠ʼàdámáֽh׃"],[24,22,"וְ⁠אֻסְּפ֨וּ אֲסֵפָ֤ה אַסִּיר֙ עַל־בּ֔וֹר וְ⁠סֻגְּר֖וּ עַל־מַסְגֵּ֑ר וּ⁠מֵ⁠רֹ֥ב יָמִ֖ים יִפָּקֵֽדוּ׃","wĕ⁠ʼusĕ̇p֨ẇ ʼàsépá֤h ʼasi̇yr֙ ʻal-ḃ֔wòr wĕ⁠sugĕ̇r֖ẇ ʻal-masĕgé֑̇r ẇ⁠mé⁠rò֥b yámi֖ym yipá̇qéֽdẇ׃"],[24,23,"וְ⁠חָֽפְרָה֙ הַ⁠לְּבָנָ֔ה וּ⁠בוֹשָׁ֖ה הַֽ⁠חַמָּ֑ה כִּֽי־מָלַ֞ךְ יְהוָ֣ה צְבָא֗וֹת בְּ⁠הַ֤ר צִיּוֹן֙ וּ⁠בִ⁠יר֣וּשָׁלִַ֔ם וְ⁠נֶ֥גֶד זְקֵנָ֖י⁠ו כָּבֽוֹד׃פ","wĕ⁠ẖáֽpĕráh֙ ha⁠lĕ̇báná֔h ẇ⁠bwòşá֖̌h haֽ⁠ẖamá֑̇h kiֽ̇y-mála֞kĕ yĕhwá֣h ẕĕbáʼ֗wòţ bĕ̇⁠ha֤r ẕiẏwòn֙ ẇ⁠bi⁠yr֣ẇşá̌lia֔m wĕ⁠ne֥ged zĕqéná֖y⁠w ká̇bֽwòd׃p"],[25,1,"יְהוָ֤ה אֱלֹהַ⁠י֙ אַתָּ֔ה אֲרֽוֹמִמְ⁠ךָ֙ אוֹדֶ֣ה שִׁמְ⁠ךָ֔ כִּ֥י עָשִׂ֖יתָ פֶּ֑לֶא עֵצ֥וֹת מֵֽ⁠רָח֖וֹק אֱמ֥וּנָה אֹֽמֶן׃","yĕhwá֤h ʼèlòha⁠y֙ ʼaţá̇֔h ʼàrֽwòmimĕ⁠ká֙ ʼwòde֣h şǐmĕ⁠ká֔ ki֥̇y ʻáşî֖yţá pė֑leʼ ʻéẕ֥wòţ méֽ⁠ráẖ֖wòq ʼèm֥ẇnáh ʼòֽmen׃"],[25,2,"כִּ֣י שַׂ֤מְתָּ מֵ⁠עִיר֙ לַ⁠גָּ֔ל קִרְיָ֥ה בְצוּרָ֖ה לְ⁠מַפֵּלָ֑ה אַרְמ֤וֹן זָרִים֙ מֵ⁠עִ֔יר לְ⁠עוֹלָ֖ם לֹ֥א יִבָּנֶֽה׃","ki֣̇y şâ֤mĕţá̇ mé⁠ʻiyr֙ la⁠gá̇֔l qirĕyá֥h bĕẕẇrá֖h lĕ⁠mapé̇lá֑h ʼarĕm֤wòn záriym֙ mé⁠ʻi֔yr lĕ⁠ʻwòlá֖m lò֥ʼ yibá̇neֽh׃"],[25,3,"עַל־כֵּ֖ן יְכַבְּד֣וּ⁠ךָ עַם־עָ֑ז קִרְיַ֛ת גּוֹיִ֥ם עָרִיצִ֖ים יִירָאֽוּ⁠ךָ׃","ʻal-ké֖̇n yĕkabĕ̇d֣ẇ⁠ká ʻam-ʻá֑z qirĕya֛ţ ġwòyi֥m ʻáriyẕi֖ym yiyráʼֽẇ⁠ká׃"],[25,4,"כִּֽי־הָיִ֨יתָ מָע֥וֹז לַ⁠דָּ֛ל מָע֥וֹז לָ⁠אֶבְי֖וֹן בַּ⁠צַּר־ל֑⁠וֹ מַחְסֶ֤ה מִ⁠זֶּ֨רֶם֙ צֵ֣ל מֵ⁠חֹ֔רֶב כִּ֛י ר֥וּחַ עָרִיצִ֖ים כְּ⁠זֶ֥רֶם קִֽיר׃","kiֽ̇y-háyi֨yţá máʻ֥wòz la⁠dá֛̇l máʻ֥wòz lá⁠ʼebĕy֖wòn bȧ⁠ẕȧr-l֑⁠wò maẖĕse֤h mi⁠zė֨rem֙ ẕé֣l mé⁠ẖò֔reb ki֛̇y r֥ẇẖa ʻáriyẕi֖ym kĕ̇⁠ze֥rem qiֽyr׃"],[25,5,"כְּ⁠חֹ֣רֶב בְּ⁠צָי֔וֹן שְׁא֥וֹן זָרִ֖ים תַּכְנִ֑יעַ חֹ֚רֶב בְּ⁠צֵ֣ל עָ֔ב זְמִ֥יר עָֽרִיצִ֖ים יַעֲנֶֽה׃פ","kĕ̇⁠ẖò֣reb bĕ̇⁠ẕáy֔wòn şĕ̌ʼ֥wòn zári֖ym ţȧkĕni֑yʻa ẖò֚reb bĕ̇⁠ẕé֣l ʻá֔b zĕmi֥yr ʻáֽriyẕi֖ym yaʻàneֽh׃p"],[25,6,"וְ⁠עָשָׂה֩ יְהוָ֨ה צְבָא֜וֹת לְ⁠כָל־הָֽ⁠עַמִּים֙ בָּ⁠הָ֣ר הַ⁠זֶּ֔ה מִשְׁתֵּ֥ה שְׁמָנִ֖ים מִשְׁתֵּ֣ה שְׁמָרִ֑ים שְׁמָנִים֙ מְמֻ֣חָיִ֔ם שְׁמָרִ֖ים מְזֻקָּקִֽים׃","wĕ⁠ʻáşá̂h֩ yĕhwá֨h ẕĕbáʼ֜wòţ lĕ⁠kál-háֽ⁠ʻami̇ym֙ bá̇⁠há֣r ha⁠zė֔h mişĕ̌ţé֥̇h şĕ̌máni֖ym mişĕ̌ţé֣̇h şĕ̌mári֑ym şĕ̌mániym֙ mĕmu֣ẖáyi֔m şĕ̌mári֖ym mĕzuqá̇qiֽym׃"],[25,7,"וּ⁠בִלַּע֙ בָּ⁠הָ֣ר הַ⁠זֶּ֔ה פְּנֵֽי־הַ⁠לּ֥וֹט ׀ הַ⁠לּ֖וֹט עַל־כָּל־הָֽ⁠עַמִּ֑ים וְ⁠הַ⁠מַּסֵּכָ֥ה הַ⁠נְּסוּכָ֖ה עַל־כָּל־הַ⁠גּוֹיִֽם׃","ẇ⁠bilȧʻ֙ bá̇⁠há֣r ha⁠zė֔h pĕ̇néֽy-ha⁠l֥̇wòt ׀ ha⁠l֖̇wòt ʻal-ká̇l-háֽ⁠ʻami֑̇ym wĕ⁠ha⁠mȧsé̇ká֥h ha⁠nĕ̇sẇká֖h ʻal-ká̇l-ha⁠ġwòyiֽm׃"],[25,8,"בִּלַּ֤ע הַ⁠מָּ֨וֶת֙ לָ⁠נֶ֔צַח וּ⁠מָחָ֨ה אֲדֹנָ֧⁠י יְהוִ֛ה דִּמְעָ֖ה מֵ⁠עַ֣ל כָּל־פָּנִ֑ים וְ⁠חֶרְפַּ֣ת עַמּ֗⁠וֹ יָסִיר֙ מֵ⁠עַ֣ל כָּל־הָ⁠אָ֔רֶץ כִּ֥י יְהוָ֖ה דִּבֵּֽר׃פ","bi̇lȧ֤ʻ ha⁠má̇֨weţ֙ lá⁠ne֔ẕaẖ ẇ⁠máẖá֨h ʼàdòná֧⁠y yĕhwi֛h di̇mĕʻá֖h mé⁠ʻa֣l ká̇l-pá̇ni֑ym wĕ⁠ẖerĕpȧ֣ţ ʻaṁ֗⁠wò yásiyr֙ mé⁠ʻa֣l ká̇l-há⁠ʼá֔reẕ ki֥̇y yĕhwá֖h di̇béֽ̇r׃p"],[25,9,"וְ⁠אָמַר֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא הִנֵּ֨ה אֱלֹהֵ֥י⁠נוּ זֶ֛ה קִוִּ֥ינוּ ל֖⁠וֹ וְ⁠יֽוֹשִׁיעֵ֑⁠נוּ זֶ֤ה יְהוָה֙ קִוִּ֣ינוּ ל֔⁠וֹ נָגִ֥ילָה וְ⁠נִשְׂמְחָ֖ה בִּ⁠ישׁוּעָתֽ⁠וֹ׃","wĕ⁠ʼámar֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ hiné̇֨h ʼèlòhé֥y⁠nẇ ze֛h qiwi֥̇ynẇ l֖⁠wò wĕ⁠yֽwòşǐyʻé֑⁠nẇ ze֤h yĕhwáh֙ qiwi֣̇ynẇ l֔⁠wò nági֥yláh wĕ⁠nişĕ̂mĕẖá֖h bi̇⁠yş̌ẇʻáţֽ⁠wò׃"],[25,10,"כִּֽי־תָנ֥וּחַ יַד־יְהוָ֖ה בָּ⁠הָ֣ר הַ⁠זֶּ֑ה וְ⁠נָ֤דוֹשׁ מוֹאָב֙ תַּחְתָּ֔י⁠ו כְּ⁠הִדּ֥וּשׁ מַתְבֵּ֖ן ב⁠מי מַדְמֵנָֽה׃","kiֽ̇y-ţán֥ẇẖa yad-yĕhwá֖h bá̇⁠há֣r ha⁠zė֑h wĕ⁠ná֤dwòş̌ mwòʼáb֙ ţȧẖĕţá̇֔y⁠w kĕ̇⁠hiḋ֥ẇş̌ maţĕbé֖̇n b⁠my madĕménáֽh׃"],[25,11,"וּ⁠פֵרַ֤שׂ יָדָי⁠ו֙ בְּ⁠קִרְבּ֔⁠וֹ כַּ⁠אֲשֶׁ֛ר יְפָרֵ֥שׂ הַ⁠שֹּׂחֶ֖ה לִ⁠שְׂח֑וֹת וְ⁠הִשְׁפִּיל֙ גַּֽאֲוָת֔⁠וֹ עִ֖ם אָרְבּ֥וֹת יָדָֽי⁠ו׃","ẇ⁠péra֤ş̂ yádáy⁠w֙ bĕ̇⁠qirĕḃ֔⁠wò kȧ⁠ʼàşě֛r yĕpáré֥ş̂ ha⁠şò̇̂ẖe֖h li⁠şĕ̂ẖ֑wòţ wĕ⁠hişĕ̌pi̇yl֙ gȧֽʼàwáţ֔⁠wò ʻi֖m ʼárĕḃ֥wòţ yádáֽy⁠w׃"],[25,12,"וּ⁠מִבְצַ֞ר מִשְׂגַּ֣ב חוֹמֹתֶ֗י⁠ךָ הֵשַׁ֥ח הִשְׁפִּ֛יל הִגִּ֥יעַ לָ⁠אָ֖רֶץ עַד־עָפָֽר׃ס","ẇ⁠mibĕẕa֞r mişĕ̂gȧ֣b ẖwòmòţe֗y⁠ká héşǎ֥ẖ hişĕ̌pi֛̇yl higi֥̇yʻa lá⁠ʼá֖reẕ ʻad-ʻápáֽr׃s"],[26,1,"בַּ⁠יּ֣וֹם הַ⁠ה֔וּא יוּשַׁ֥ר הַ⁠שִּׁיר־הַ⁠זֶּ֖ה בְּ⁠אֶ֣רֶץ יְהוּדָ֑ה עִ֣יר עָז־לָ֔⁠נוּ יְשׁוּעָ֥ה יָשִׁ֖ית חוֹמ֥וֹת וָ⁠חֵֽל׃","bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ yẇşǎ֥r ha⁠şi̇̌yr-ha⁠zė֖h bĕ̇⁠ʼe֣reẕ yĕhẇdá֑h ʻi֣yr ʻáz-lá֔⁠nẇ yĕş̌ẇʻá֥h yáşǐ֖yţ ẖwòm֥wòţ wá⁠ẖéֽl׃"],[26,2,"פִּתְח֖וּ שְׁעָרִ֑ים וְ⁠יָבֹ֥א גוֹי־צַדִּ֖יק שֹׁמֵ֥ר אֱמֻנִֽים׃","pi̇ţĕẖ֖ẇ şĕ̌ʻári֑ym wĕ⁠yábò֥ʼ gwòy-ẕadi֖̇yq şò̌mé֥r ʼèmuniֽym׃"],[26,3,"יֵ֣צֶר סָמ֔וּךְ תִּצֹּ֖ר שָׁל֣וֹם ׀ שָׁל֑וֹם כִּ֥י בְ⁠ךָ֖ בָּטֽוּחַ׃","yé֣ẕer sám֔ẇkĕ ţi̇ẕò֖̇r şá̌l֣wòm ׀ şá̌l֑wòm ki֥̇y bĕ⁠ká֖ bá̇tֽẇẖa׃"],[26,4,"בִּטְח֥וּ בַֽ⁠יהוָ֖ה עֲדֵי־עַ֑ד כִּ֚י בְּ⁠יָ֣הּ יְהוָ֔ה צ֖וּר עוֹלָמִֽים׃","bi̇tĕẖ֥ẇ baֽ⁠yhwá֖h ʻàdéy-ʻa֑d ki֚̇y bĕ̇⁠yá֣ḣ yĕhwá֔h ẕ֖ẇr ʻwòlámiֽym׃"],[26,5,"כִּ֤י הֵשַׁח֙ יֹשְׁבֵ֣י מָר֔וֹם קִרְיָ֖ה נִשְׂגָּבָ֑ה יַשְׁפִּילֶ֤⁠נָּה יַשְׁפִּילָ⁠הּ֙ עַד־אֶ֔רֶץ יַגִּיעֶ֖⁠נָּה עַד־עָפָֽר׃","ki֤̇y héşǎẖ֙ yòşĕ̌bé֣y már֔wòm qirĕyá֖h nişĕ̂gá̇bá֑h yaşĕ̌pi̇yle֤⁠ná̇h yaşĕ̌pi̇ylá⁠ḣ֙ ʻad-ʼe֔reẕ yagi̇yʻe֖⁠ná̇h ʻad-ʻápáֽr׃"],[26,6,"תִּרְמְסֶ֖⁠נָּה רָ֑גֶל רַגְלֵ֥י עָנִ֖י פַּעֲמֵ֥י דַלִּֽים׃","ţi̇rĕmĕse֖⁠ná̇h rá֑gel ragĕlé֥y ʻáni֖y pȧʻàmé֥y daliֽ̇ym׃"],[26,7,"אֹ֥רַח לַ⁠צַּדִּ֖יק מֵֽישָׁרִ֑ים יָשָׁ֕ר מַעְגַּ֥ל צַדִּ֖יק תְּפַלֵּֽס׃","ʼò֥raẖ la⁠ẕȧdi֖̇yq méֽyşá̌ri֑ym yáşá̌֕r maʻĕgȧ֥l ẕadi֖̇yq ţĕ̇paléֽ̇s׃"],[26,8,"אַ֣ף אֹ֧רַח מִשְׁפָּטֶ֛י⁠ךָ יְהוָ֖ה קִוִּינ֑וּ⁠ךָ לְ⁠שִׁמְ⁠ךָ֥ וּֽ⁠לְ⁠זִכְרְ⁠ךָ֖ תַּאֲוַת־נָֽפֶשׁ׃","ʼa֣p ʼò֧raẖ mişĕ̌pá̇te֛y⁠ká yĕhwá֖h qiwi̇yn֑ẇ⁠ká lĕ⁠şǐmĕ⁠ká֥ ẇֽ⁠lĕ⁠zikĕrĕ⁠ká֖ ţȧʼàwaţ-náֽpeş̌׃"],[26,9,"נַפְשִׁ֤⁠י אִוִּיתִ֨י⁠ךָ֙ בַּ⁠לַּ֔יְלָה אַף־רוּחִ֥⁠י בְ⁠קִרְבִּ֖⁠י אֲשַֽׁחֲרֶ֑⁠ךָּ כִּ֞י כַּ⁠אֲשֶׁ֤ר מִשְׁפָּטֶ֨י⁠ךָ֙ לָ⁠אָ֔רֶץ צֶ֥דֶק לָמְד֖וּ יֹשְׁבֵ֥י תֵבֵֽל׃","napĕşǐ֤⁠y ʼiwi̇yţi֨y⁠ká֙ bȧ⁠lȧ֔yĕláh ʼap-rẇẖi֥⁠y bĕ⁠qirĕbi֖̇⁠y ʼàşǎֽẖàre֑⁠ká̇ ki̇֞y kȧ⁠ʼàşě֤r mişĕ̌pá̇te֨y⁠ká֙ lá⁠ʼá֔reẕ ẕe֥deq lámĕd֖ẇ yòşĕ̌bé֥y ţébéֽl׃"],[26,10,"יֻחַ֤ן רָשָׁע֙ בַּל־לָמַ֣ד צֶ֔דֶק בְּ⁠אֶ֥רֶץ נְכֹח֖וֹת יְעַוֵּ֑ל וּ⁠בַל־יִרְאֶ֖ה גֵּא֥וּת יְהוָֽה׃ס","yuẖa֤n ráşá̌ʻ֙ bȧl-láma֣d ẕe֔deq bĕ̇⁠ʼe֥reẕ nĕkòẖ֖wòţ yĕʻawé֑̇l ẇ⁠bal-yirĕʼe֖h gé̇ʼ֥ẇţ yĕhwáֽh׃s"],[26,11,"יְהוָ֛ה רָ֥מָה יָדְ⁠ךָ֖ בַּל־יֶחֱזָי֑וּ⁠ן יֶחֱז֤וּ וְ⁠יֵבֹ֨שׁוּ֙ קִנְאַת־עָ֔ם אַף־אֵ֖שׁ צָרֶ֥י⁠ךָ תֹאכְלֵֽ⁠ם׃ס","yĕhwá֛h rá֥máh yádĕ⁠ká֖ bȧl-yeẖèzáy֑ẇ⁠n yeẖèz֤ẇ wĕ⁠yébò֨ş̌ẇ֙ qinĕʼaţ-ʻá֔m ʼap-ʼé֖ş̌ ẕáre֥y⁠ká ţòʼkĕléֽ⁠m׃s"],[26,12,"יְהוָ֕ה תִּשְׁפֹּ֥ת שָׁל֖וֹם לָ֑⁠נוּ כִּ֛י גַּ֥ם כָּֽל־מַעֲשֵׂ֖י⁠נוּ פָּעַ֥לְתָּ לָּֽ⁠נוּ׃","yĕhwá֕h ţi̇şĕ̌pò֥̇ţ şá̌l֖wòm lá֑⁠nẇ ki֛̇y gȧ֥m káֽ̇l-maʻàşé֖̂y⁠nẇ pá̇ʻa֥lĕţá̇ láֽ̇⁠nẇ׃"],[26,13,"יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ בְּעָל֥וּ⁠נוּ אֲדֹנִ֖ים זֽוּלָתֶ֑⁠ךָ לְ⁠בַד־בְּ⁠ךָ֖ נַזְכִּ֥יר שְׁמֶֽ⁠ךָ׃","yĕhwá֣h ʼèlòhé֔y⁠nẇ bĕ̇ʻál֥ẇ⁠nẇ ʼàdòni֖ym zֽẇláţe֑⁠ká lĕ⁠bad-bĕ̇⁠ká֖ nazĕki֥̇yr şĕ̌meֽ⁠ká׃"],[26,14,"מֵתִים֙ בַּל־יִחְי֔וּ רְפָאִ֖ים בַּל־יָקֻ֑מוּ לָ⁠כֵ֤ן פָּקַ֨דְתָּ֙ וַ⁠תַּשְׁמִידֵ֔⁠ם וַ⁠תְּאַבֵּ֥ד כָּל־זֵ֖כֶר לָֽ⁠מוֹ׃","méţiym֙ bȧl-yiẖĕy֔ẇ rĕpáʼi֖ym bȧl-yáqu֑mẇ lá⁠ké֤n pá̇qa֨dĕţá̇֙ wa⁠ţȧşĕ̌miydé֔⁠m wa⁠ţĕ̇ʼabé֥̇d ká̇l-zé֖ker láֽ⁠mwò׃"],[26,15,"יָסַ֤פְתָּ לַ⁠גּוֹי֙ יְהוָ֔ה יָסַ֥פְתָּ לַ⁠גּ֖וֹי נִכְבָּ֑דְתָּ רִחַ֖קְתָּ כָּל־קַצְוֵי־אָֽרֶץ׃","yása֤pĕţá̇ la⁠ġwòy֙ yĕhwá֔h yása֥pĕţá̇ la⁠ġ֖wòy nikĕbá֑̇dĕţá̇ riẖa֖qĕţá̇ ká̇l-qaẕĕwéy-ʼáֽreẕ׃"],[26,16,"יְהוָ֖ה בַּ⁠צַּ֣ר פְּקָד֑וּ⁠ךָ צָק֣וּ⁠ן לַ֔חַשׁ מוּסָרְ⁠ךָ֖ לָֽ⁠מוֹ׃","yĕhwá֖h bȧ⁠ẕȧ֣r pĕ̇qád֑ẇ⁠ká ẕáq֣ẇ⁠n la֔ẖaş̌ mẇsárĕ⁠ká֖ láֽ⁠mwò׃"],[26,17,"כְּמ֤וֹ הָרָה֙ תַּקְרִ֣יב לָ⁠לֶ֔דֶת תָּחִ֥יל תִּזְעַ֖ק בַּ⁠חֲבָלֶ֑י⁠הָ כֵּ֛ן הָיִ֥ינוּ מִ⁠פָּנֶ֖י⁠ךָ יְהוָֽה׃","kĕ̇m֤wò háráh֙ ţȧqĕri֣yb lá⁠le֔deţ ţá̇ẖi֥yl ţi̇zĕʻa֖q bȧ⁠ẖàbále֑y⁠há ké֛̇n háyi֥ynẇ mi⁠pá̇ne֖y⁠ká yĕhwáֽh׃"],[26,18,"הָרִ֣ינוּ חַ֔לְנוּ כְּמ֖וֹ יָלַ֣דְנוּ ר֑וּחַ יְשׁוּעֹת֙ בַּל־נַ֣עֲשֶׂה אֶ֔רֶץ וּ⁠בַֽל־יִפְּל֖וּ יֹשְׁבֵ֥י תֵבֵֽל׃","hári֣ynẇ ẖa֔lĕnẇ kĕ̇m֖wò yála֣dĕnẇ r֑ẇẖa yĕş̌ẇʻòţ֙ bȧl-na֣ʻàşêh ʼe֔reẕ ẇ⁠baֽl-yipĕ̇l֖ẇ yòşĕ̌bé֥y ţébéֽl׃"],[26,19,"יִֽחְי֣וּ מֵתֶ֔י⁠ךָ נְבֵלָתִ֖⁠י יְקוּמ֑וּ⁠ן הָקִ֨יצוּ וְ⁠רַנְּנ֜וּ שֹׁכְנֵ֣י עָפָ֗ר כִּ֣י טַ֤ל אוֹרֹת֙ טַלֶּ֔⁠ךָ וָ⁠אָ֖רֶץ רְפָאִ֥ים תַּפִּֽיל׃ס","yiֽẖĕy֣ẇ méţe֔y⁠ká nĕbéláţi֖⁠y yĕqẇm֑ẇ⁠n háqi֨yẕẇ wĕ⁠ranĕ̇n֜ẇ şò̌kĕné֣y ʻápá֗r ki֣̇y ta֤l ʼwòròţ֙ talė֔⁠ká wá⁠ʼá֖reẕ rĕpáʼi֥ym ţȧpiֽ̇yl׃s"],[26,20,"לֵ֤ךְ עַמִּ⁠י֙ בֹּ֣א בַ⁠חֲדָרֶ֔י⁠ךָ וּֽ⁠סְגֹ֥ר דלתי⁠ך בַּעֲדֶ֑⁠ךָ חֲבִ֥י כִ⁠מְעַט־רֶ֖גַע עַד־יעבור־זָֽעַם׃","lé֤kĕ ʻami̇⁠y֙ bò֣̇ʼ ba⁠ẖàdáre֔y⁠ká ẇֽ⁠sĕgò֥r dlţy⁠k bȧʻàde֑⁠ká ẖàbi֥y ki⁠mĕʻat-re֖gaʻ ʻad-yʻbwr-záֽʻam׃"],[26,21,"כִּֽי־הִנֵּ֤ה יְהוָה֙ יֹצֵ֣א מִ⁠מְּקוֹמ֔⁠וֹ לִ⁠פְקֹ֛ד עֲוֺ֥ן יֹֽשֵׁב־הָ⁠אָ֖רֶץ עָלָ֑י⁠ו וְ⁠גִלְּתָ֤ה הָ⁠אָ֨רֶץ֙ אֶת־דָּמֶ֔י⁠הָ וְ⁠לֹֽא־תְכַסֶּ֥ה ע֖וֹד עַל־הֲרוּגֶֽי⁠הָ׃ס","kiֽ̇y-hiné֤̇h yĕhwáh֙ yòẕé֣ʼ mi⁠mĕ̇qwòm֔⁠wò li⁠pĕqò֛d ʻàwֺ֥n yòֽşé̌b-há⁠ʼá֖reẕ ʻálá֑y⁠w wĕ⁠gilĕ̇ţá֤h há⁠ʼá֨reẕ֙ ʼeţ-dá̇me֔y⁠há wĕ⁠lòֽʼ-ţĕkasė֥h ʻ֖wòd ʻal-hàrẇgeֽy⁠há׃s"],[27,1,"בַּ⁠יּ֣וֹם הַ⁠ה֡וּא יִפְקֹ֣ד יְהוָה֩ בְּ⁠חַרְב֨⁠וֹ הַ⁠קָּשָׁ֜ה וְ⁠הַ⁠גְּדוֹלָ֣ה וְ⁠הַֽ⁠חֲזָקָ֗ה עַ֤ל לִוְיָתָן֙ נָחָ֣שׁ בָּרִ֔חַ וְ⁠עַל֙ לִוְיָתָ֔ן נָחָ֖שׁ עֲקַלָּת֑וֹן וְ⁠הָרַ֥ג אֶת־הַ⁠תַּנִּ֖ין אֲשֶׁ֥ר בַּ⁠יָּֽם׃ס","bȧ⁠ẏ֣wòm ha⁠h֡ẇʼ yipĕqò֣d yĕhwáh֩ bĕ̇⁠ẖarĕb֨⁠wò ha⁠qá̇şá̌֜h wĕ⁠ha⁠gĕ̇dwòlá֣h wĕ⁠hֽa⁠ẖàzáqá֗h ʻa֤l liwĕyáţán֙ náẖá֣ş̌ bá̇ri֔ẖa wĕ⁠ʻal֙ liwĕyáţá֔n náẖá֖ş̌ ʻàqalá̇ţ֑wòn wĕ⁠hára֥g ʼeţ-ha⁠ţȧni֖̇yn ʼàşě֥r bȧ⁠yáֽ̇m׃s"],[27,2,"בַּ⁠יּ֖וֹם הַ⁠ה֑וּא כֶּ֥רֶם חֶ֖מֶד עַנּוּ־לָֽ⁠הּ׃","bȧ⁠ẏ֖wòm ha⁠h֑ẇʼ kė֥rem ẖe֖med ʻaṅẇ-láֽ⁠ḣ׃"],[27,3,"אֲנִ֤י יְהוָה֙ נֹֽצְרָ֔⁠הּ לִ⁠רְגָעִ֖ים אַשְׁקֶ֑⁠נָּה פֶּ֚ן יִפְקֹ֣ד עָלֶ֔י⁠הָ לַ֥יְלָה וָ⁠י֖וֹם אֶצֳּרֶֽ⁠נָּה׃","ʼàni֤y yĕhwáh֙ nòֽẕĕrá֔⁠ḣ li⁠rĕgáʻi֖ym ʼaşĕ̌qe֑⁠ná̇h pė֚n yipĕqò֣d ʻále֔y⁠há la֥yĕláh wá⁠y֖wòm ʼeẕȯreֽ⁠ná̇h׃"],[27,4,"חֵמָ֖ה אֵ֣ין לִ֑⁠י מִֽי־יִתְּנֵ֜⁠נִי שָׁמִ֥יר שַׁ֨יִת֙ בַּ⁠מִּלְחָמָ֔ה אֶפְשְׂעָ֥ה בָ֖⁠הּ אֲצִיתֶ֥⁠נָּה יָּֽחַד׃","ẖémá֖h ʼé֣yn li֑⁠y miֽy-yiţĕ̇né֜⁠niy şá̌mi֥yr şǎ֨yiţ֙ bȧ⁠mi̇lĕẖámá֔h ʼepĕşĕ̂ʻá֥h bá֖⁠ḣ ʼàẕiyţe֥⁠ná̇h yáֽ̇ẖad׃"],[27,5,"א֚וֹ יַחֲזֵ֣ק בְּ⁠מָעוּזִּ֔⁠י יַעֲשֶׂ֥ה שָׁל֖וֹם לִ֑⁠י שָׁל֖וֹם יַֽעֲשֶׂה־לִּֽ⁠י׃","ʼ֚wò yaẖàzé֣q bĕ̇⁠máʻẇzi̇֔⁠y yaʻàşê֥h şá̌l֖wòm li֑⁠y şá̌l֖wòm yֽaʻàşêh-liֽ̇⁠y׃"],[27,6,"הַ⁠בָּאִים֙ יַשְׁרֵ֣שׁ יַֽעֲקֹ֔ב יָצִ֥יץ וּ⁠פָרַ֖ח יִשְׂרָאֵ֑ל וּ⁠מָלְא֥וּ פְנֵי־תֵבֵ֖ל תְּנוּבָֽה׃ס","ha⁠bá̇ʼiym֙ yaşĕ̌ré֣ş̌ yaֽʻàqò֔b yáẕi֥yẕ ẇ⁠pára֖ẖ yişĕ̂ráʼé֑l ẇ⁠málĕʼ֥ẇ pĕnéy-ţébé֖l ţĕ̇nẇbáֽh׃s"],[27,7,"הַ⁠כְּ⁠מַכַּ֥ת מַכֵּ֖⁠הוּ הִכָּ֑⁠הוּ אִם־כְּ⁠הֶ֥רֶג הֲרֻגָ֖י⁠ו הֹרָֽג׃","ha⁠kĕ̇⁠makȧ֥ţ maké֖̇⁠hẇ hiká֑̇⁠hẇ ʼim-kĕ̇⁠he֥reg hàrugá֖y⁠w hòráֽg׃"],[27,8,"בְּ⁠סַּאסְּאָ֖ה בְּ⁠שַׁלְחָ֣⁠הּ תְּרִיבֶ֑⁠נָּה הָגָ֛ה בְּ⁠רוּח֥⁠וֹ הַ⁠קָּשָׁ֖ה בְּ⁠י֥וֹם קָדִֽים׃","bĕ̇⁠sȧʼsĕ̇ʼá֖h bĕ̇⁠şǎlĕẖá֣⁠ḣ ţĕ̇riybe֑⁠ná̇h hágá֛h bĕ̇⁠rẇẖ֥⁠wò ha⁠qá̇şá֖̌h bĕ̇⁠y֥wòm qádiֽym׃"],[27,9,"לָ⁠כֵ֗ן בְּ⁠זֹאת֙ יְכֻפַּ֣ר עֲוֺֽן־יַעֲקֹ֔ב וְ⁠זֶ֕ה כָּל־פְּרִ֖י הָסִ֣ר חַטָּאת֑⁠וֹ בְּ⁠שׂוּמ֣⁠וֹ ׀ כָּל־אַבְנֵ֣י מִזְבֵּ֗חַ כְּ⁠אַבְנֵי־גִר֙ מְנֻפָּצ֔וֹת לֹֽא־יָקֻ֥מוּ אֲשֵׁרִ֖ים וְ⁠חַמָּנִֽים׃","lá⁠ké֗n bĕ̇⁠zòʼţ֙ yĕkupȧ֣r ʻàwֺֽn-yaʻàqò֔b wĕ⁠ze֕h ká̇l-pĕ̇ri֖y hási֣r ẖatá̇ʼţ֑⁠wò bĕ̇⁠ş̂ẇm֣⁠wò ׀ ká̇l-ʼabĕné֣y mizĕbé̇֗ẖa kĕ̇⁠ʼabĕnéy-gir֙ mĕnupá̇ẕ֔wòţ lòֽʼ-yáqu֥mẇ ʼàşé̌ri֖ym wĕ⁠ẖamá̇niֽym׃"],[27,10,"כִּ֣י עִ֤יר בְּצוּרָה֙ בָּדָ֔ד נָוֶ֕ה מְשֻׁלָּ֥ח וְ⁠נֶעֱזָ֖ב כַּ⁠מִּדְבָּ֑ר שָׁ֣ם יִרְעֶ֥ה עֵ֛גֶל וְ⁠שָׁ֥ם יִרְבָּ֖ץ וְ⁠כִלָּ֥ה סְעִפֶֽי⁠הָ׃","ki֣̇y ʻi֤yr bĕ̇ẕẇráh֙ bá̇dá֔d náwe֕h mĕşǔlá֥̇ẖ wĕ⁠neʻèzá֖b kȧ⁠mi̇dĕbá֑̇r şá֣̌m yirĕʻe֥h ʻé֛gel wĕ⁠şá֥̌m yirĕbá֖̇ẕ wĕ⁠kilá֥̇h sĕʻipeֽy⁠há׃"],[27,11,"בִּ⁠יבֹ֤שׁ קְצִירָ⁠הּ֙ תִּשָּׁבַ֔רְנָה נָשִׁ֕ים בָּא֖וֹת מְאִיר֣וֹת אוֹתָ֑⁠הּ כִּ֣י לֹ֤א עַם־בִּינוֹת֙ ה֔וּא עַל־כֵּן֙ לֹֽא־יְרַחֲמֶ֣⁠נּוּ עֹשֵׂ֔⁠הוּ וְ⁠יֹצְר֖⁠וֹ לֹ֥א יְחֻנֶּֽ⁠נּוּ׃ס","bi̇⁠ybò֤ş̌ qĕẕiyrá⁠ḣ֙ ţi̇şá̇̌ba֔rĕnáh náşǐ֕ym bá̇ʼ֖wòţ mĕʼiyr֣wòţ ʼwòţá֑⁠ḣ ki֣̇y lò֤ʼ ʻam-bi̇ynwòţ֙ h֔ẇʼ ʻal-ké̇n֙ lòֽʼ-yĕraẖàme֣⁠ṅẇ ʻòşé̂֔⁠hẇ wĕ⁠yòẕĕr֖⁠wò lò֥ʼ yĕẖunėֽ⁠ṅẇ׃s"],[27,12,"וְ⁠הָיָה֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא יַחְבֹּ֧ט יְהוָ֛ה מִ⁠שִּׁבֹּ֥לֶת הַ⁠נָּהָ֖ר עַד־נַ֣חַל מִצְרָ֑יִם וְ⁠אַתֶּ֧ם תְּלֻקְּט֛וּ לְ⁠אַחַ֥ד אֶחָ֖ד בְּנֵ֥י יִשְׂרָאֵֽל׃ס","wĕ⁠háyáh֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ yaẖĕbò֧̇t yĕhwá֛h mi⁠şi̇̌bò֥̇leţ ha⁠ná̇há֖r ʻad-na֣ẖal miẕĕrá֑yim wĕ⁠ʼaţė֧m ţĕ̇luqĕ̇t֛ẇ lĕ⁠ʼaẖa֥d ʼeẖá֖d bĕ̇né֥y yişĕ̂ráʼéֽl׃s"],[27,13,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִתָּקַע֮ בְּ⁠שׁוֹפָ֣ר גָּדוֹל֒ וּ⁠בָ֗אוּ הָ⁠אֹֽבְדִים֙ בְּ⁠אֶ֣רֶץ אַשּׁ֔וּר וְ⁠הַ⁠נִּדָּחִ֖ים בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם וְ⁠הִשְׁתַּחֲו֧וּ לַ⁠יהוָ֛ה בְּ⁠הַ֥ר הַ⁠קֹּ֖דֶשׁ בִּ⁠ירוּשָׁלִָֽם׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yiţá̇qaʻ֮ bĕ̇⁠ş̌wòpá֣r gá̇dwòl֒ ẇ⁠bá֗ʼẇ há⁠ʼòֽbĕdiym֙ bĕ̇⁠ʼe֣reẕ ʼaş̇̌֔ẇr wĕ⁠ha⁠ni̇dá̇ẖi֖ym bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim wĕ⁠hişĕ̌ţȧẖàw֧ẇ la⁠yhwá֛h bĕ̇⁠ha֥r ha⁠qò֖̇deş̌ bi̇⁠yrẇşá̌liáֽm׃"],[28,1,"ה֗וֹי עֲטֶ֤רֶת גֵּאוּת֙ שִׁכֹּרֵ֣י אֶפְרַ֔יִם וְ⁠צִ֥יץ נֹבֵ֖ל צְבִ֣י תִפְאַרְתּ֑⁠וֹ אֲשֶׁ֛ר עַל־רֹ֥אשׁ גֵּֽיא־שְׁמָנִ֖ים הֲל֥וּמֵי יָֽיִן׃","h֗wòy ʻàte֤reţ gé̇ʼẇţ֙ şǐkò̇ré֣y ʼepĕra֔yim wĕ⁠ẕi֥yẕ nòbé֖l ẕĕbi֣y ţipĕʼarĕţ֑̇⁠wò ʼàşě֛r ʻal-rò֥ʼş̌ géֽ̇yʼ-şĕ̌máni֖ym hàl֥ẇméy yáֽyin׃"],[28,2,"הִנֵּ֨ה חָזָ֤ק וְ⁠אַמִּץ֙ לַֽ⁠אדֹנָ֔⁠י כְּ⁠זֶ֥רֶם בָּרָ֖ד שַׂ֣עַר קָ֑טֶב כְּ֠⁠זֶרֶם מַ֣יִם כַּבִּירִ֥ים שֹׁטְפִ֛ים הִנִּ֥יחַ לָ⁠אָ֖רֶץ בְּ⁠יָֽד׃","hiné̇֨h ẖázá֤q wĕ⁠ʼami̇ẕ֙ laֽ⁠ʼdòná֔⁠y kĕ̇⁠ze֥rem bá̇rá֖d şâ֣ʻar qá֑teb kĕ̇֠⁠zerem ma֣yim kȧbi̇yri֥ym şò̌tĕpi֛ym hini֥̇yẖa lá⁠ʼá֖reẕ bĕ̇⁠yáֽd׃"],[28,3,"בְּ⁠רַגְלַ֖יִם תֵּֽרָמַ֑סְנָה עֲטֶ֥רֶת גֵּא֖וּת שִׁכּוֹרֵ֥י אֶפְרָֽיִם׃","bĕ̇⁠ragĕla֖yim ţéֽ̇ráma֑sĕnáh ʻàte֥reţ gé̇ʼ֖ẇţ şǐk̇wòré֥y ʼepĕráֽyim׃"],[28,4,"וְֽ⁠הָ֨יְתָ֜ה צִיצַ֤ת נֹבֵל֙ צְבִ֣י תִפְאַרְתּ֔⁠וֹ אֲשֶׁ֥ר עַל־רֹ֖אשׁ גֵּ֣יא שְׁמָנִ֑ים כְּ⁠בִכּוּרָהּ֙ בְּ⁠טֶ֣רֶם קַ֔יִץ אֲשֶׁ֨ר יִרְאֶ֤ה הָֽ⁠רֹאֶה֙ אוֹתָ֔⁠הּ בְּ⁠עוֹדָ֥⁠הּ בְּ⁠כַפּ֖⁠וֹ יִבְלָעֶֽ⁠נָּה׃ס","wĕֽ⁠há֨yĕţá֜h ẕiyẕa֤ţ nòbél֙ ẕĕbi֣y ţipĕʼarĕţ̇֔⁠wò ʼàşě֥r ʻal-rò֖ʼş̌ gé֣̇yʼ şĕ̌máni֑ym kĕ̇⁠bik̇ẇráḣ֙ bĕ̇⁠te֣rem qa֔yiẕ ʼàşě֨r yirĕʼe֤h háֽ⁠ròʼeh֙ ʼwòţá֔⁠ḣ bĕ̇⁠ʻwòdá֥⁠ḣ bĕ̇⁠kaṗ֖⁠wò yibĕláʻeֽ⁠ná̇h׃s"],[28,5,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִֽהְיֶה֙ יְהוָ֣ה צְבָא֔וֹת לַ⁠עֲטֶ֣רֶת צְבִ֔י וְ⁠לִ⁠צְפִירַ֖ת תִּפְאָרָ֑ה לִ⁠שְׁאָ֖ר עַמּֽ⁠וֹ׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yiֽhĕyeh֙ yĕhwá֣h ẕĕbáʼ֔wòţ la⁠ʻàte֣reţ ẕĕbi֔y wĕ⁠li⁠ẕĕpiyra֖ţ ţi̇pĕʼárá֑h li⁠şĕ̌ʼá֖r ʻaṁֽ⁠wò׃"],[28,6,"וּ⁠לְ⁠ר֖וּחַ מִשְׁפָּ֑ט לַ⁠יּוֹשֵׁב֙ עַל־הַ⁠מִּשְׁפָּ֔ט וְ⁠לִ֨⁠גְבוּרָ֔ה מְשִׁיבֵ֥י מִלְחָמָ֖ה שָֽׁעְרָ⁠ה׃ס","ẇ⁠lĕ⁠r֖ẇẖa mişĕ̌pá֑̇t la⁠ẏwòşé̌b֙ ʻal-ha⁠mi̇şĕ̌pá̇֔t wĕ⁠li֨⁠gĕbẇrá֔h mĕşǐybé֥y milĕẖámá֖h şáֽ̌ʻĕrá⁠h׃s"],[28,7,"וְ⁠גַם־אֵ֨לֶּה֙ בַּ⁠יַּ֣יִן שָׁג֔וּ וּ⁠בַ⁠שֵּׁכָ֖ר תָּע֑וּ כֹּהֵ֣ן וְ⁠נָבִיא֩ שָׁג֨וּ בַ⁠שֵּׁכָ֜ר נִבְלְע֣וּ מִן־הַ⁠יַּ֗יִן תָּעוּ֙ מִן־הַ⁠שֵּׁכָ֔ר שָׁגוּ֙ בָּֽ⁠רֹאֶ֔ה פָּק֖וּ פְּלִילִיָּֽה׃","wĕ⁠gam-ʼé֨lėh֙ bȧ⁠yȧ֣yin şá̌g֔ẇ ẇ⁠ba⁠şé̇̌ká֖r ţá̇ʻ֑ẇ kò̇hé֣n wĕ⁠nábiyʼ֩ şá̌g֨ẇ ba⁠şé̇̌ká֜r nibĕlĕʻ֣ẇ min-ha⁠yȧ֗yin ţá̇ʻẇ֙ min-ha⁠şé̇̌ká֔r şá̌gẇ֙ báֽ̇⁠ròʼe֔h pá̇q֖ẇ pĕ̇liyliyáֽ̇h׃"],[28,8,"כִּ֚י כָּל־שֻׁלְחָנ֔וֹת מָלְא֖וּ קִ֣יא צֹאָ֑ה בְּלִ֖י מָקֽוֹם׃ס","ki֚̇y ká̇l-şǔlĕẖán֔wòţ málĕʼ֖ẇ qi֣yʼ ẕòʼá֑h bĕ̇li֖y máqֽwòm׃s"],[28,9,"אֶת־מִי֙ יוֹרֶ֣ה דֵעָ֔ה וְ⁠אֶת־מִ֖י יָבִ֣ין שְׁמוּעָ֑ה גְּמוּלֵי֙ מֵֽ⁠חָלָ֔ב עַתִּיקֵ֖י מִ⁠שָּׁדָֽיִם׃","ʼeţ-miy֙ ywòre֣h déʻá֔h wĕ⁠ʼeţ-mi֖y yábi֣yn şĕ̌mẇʻá֑h gĕ̇mẇléy֙ méֽ⁠ẖálá֔b ʻaţi̇yqé֖y mi⁠şá̇̌dáֽyim׃"],[28,10,"כִּ֣י צַ֤ו לָ⁠צָו֙ צַ֣ו לָ⁠צָ֔ו קַ֥ו לָ⁠קָ֖ו קַ֣ו לָ⁠קָ֑ו זְעֵ֥יר שָׁ֖ם זְעֵ֥יר שָֽׁם׃","ki֣̇y ẕa֤w lá⁠ẕáw֙ ẕa֣w lá⁠ẕá֔w qa֥w lá⁠qá֖w qa֣w lá⁠qá֑w zĕʻé֥yr şá֖̌m zĕʻé֥yr şáֽ̌m׃"],[28,11,"כִּ֚י בְּ⁠לַעֲגֵ֣י שָׂפָ֔ה וּ⁠בְ⁠לָשׁ֖וֹן אַחֶ֑רֶת יְדַבֵּ֖ר אֶל־הָ⁠עָ֥ם הַ⁠זֶּֽה׃","ki֚̇y bĕ̇⁠laʻàgé֣y şá̂pá֔h ẇ⁠bĕ⁠láş֖̌wòn ʼaẖe֑reţ yĕdabé֖̇r ʼel-há⁠ʻá֥m ha⁠zėֽh׃"],[28,12,"אֲשֶׁ֣ר ׀ אָמַ֣ר אֲלֵי⁠הֶ֗ם זֹ֤את הַ⁠מְּנוּחָה֙ הָנִ֣יחוּ לֶֽ⁠עָיֵ֔ף וְ⁠זֹ֖את הַ⁠מַּרְגֵּעָ֑ה וְ⁠לֹ֥א אָב֖וּא שְׁמֽוֹעַ׃","ʼàşě֣r ׀ ʼáma֣r ʼàléy⁠he֗m zò֤ʼţ ha⁠mĕ̇nẇẖáh֙ háni֣yẖẇ leֽ⁠ʻáyé֔p wĕ⁠zò֖ʼţ ha⁠mȧrĕgé̇ʻá֑h wĕ⁠lò֥ʼ ʼáb֖ẇʼ şĕ̌mֽwòʻa׃"],[28,13,"וְ⁠הָיָ֨ה לָ⁠הֶ֜ם דְּבַר־יְהוָ֗ה צַ֣ו לָ⁠צָ֞ו צַ֤ו לָ⁠צָו֙ קַ֤ו לָ⁠קָו֙ קַ֣ו לָ⁠קָ֔ו זְעֵ֥יר שָׁ֖ם זְעֵ֣יר שָׁ֑ם לְמַ֨עַן יֵלְכ֜וּ וְ⁠כָשְׁל֤וּ אָחוֹר֙ וְ⁠נִשְׁבָּ֔רוּ וְ⁠נוֹקְשׁ֖וּ וְ⁠נִלְכָּֽדוּ׃פ","wĕ⁠háyá֨h lá⁠he֜m dĕ̇bar-yĕhwá֗h ẕa֣w lá⁠ẕá֞w ẕa֤w lá⁠ẕáw֙ qa֤w lá⁠qáw֙ qa֣w lá⁠qá֔w zĕʻé֥yr şá֖̌m zĕʻé֣yr şá֑̌m lĕma֨ʻan yélĕk֜ẇ wĕ⁠káşĕ̌l֤ẇ ʼáẖwòr֙ wĕ⁠nişĕ̌bá̇֔rẇ wĕ⁠nwòqĕş֖̌ẇ wĕ⁠nilĕkáֽ̇dẇ׃p"],[28,14,"לָ⁠כֵ֛ן שִׁמְע֥וּ דְבַר־יְהוָ֖ה אַנְשֵׁ֣י לָצ֑וֹן מֹֽשְׁלֵי֙ הָ⁠עָ֣ם הַ⁠זֶּ֔ה אֲשֶׁ֖ר בִּ⁠ירוּשָׁלִָֽם׃","lá⁠ké֛n şǐmĕʻ֥ẇ dĕbar-yĕhwá֖h ʼanĕşé֣̌y láẕ֑wòn mòֽşĕ̌léy֙ há⁠ʻá֣m ha⁠zė֔h ʼàşě֖r bi̇⁠yrẇşá̌liáֽm׃"],[28,15,"כִּ֣י אֲמַרְתֶּ֗ם כָּרַ֤תְנֽוּ בְרִית֙ אֶת־מָ֔וֶת וְ⁠עִם־שְׁא֖וֹל עָשִׂ֣ינוּ חֹזֶ֑ה שיט שׁוֹטֵ֤ף כִּֽי־עבר לֹ֣א יְבוֹאֵ֔⁠נוּ כִּ֣י שַׂ֧מְנוּ כָזָ֛ב מַחְסֵ֖⁠נוּ וּ⁠בַ⁠שֶּׁ֥קֶר נִסְתָּֽרְנוּ׃ס","ki֣̇y ʼàmarĕţė֗m ká̇ra֤ţĕnֽẇ bĕriyţ֙ ʼeţ-má֔weţ wĕ⁠ʻim-şĕ̌ʼ֖wòl ʻáşî֣ynẇ ẖòze֑h şyt ş̌wòté֤p kiֽ̇y-ʻbr lò֣ʼ yĕbwòʼé֔⁠nẇ ki֣̇y şâ֧mĕnẇ kázá֛b maẖĕsé֖⁠nẇ ẇ⁠ba⁠şė֥̌qer nisĕţáֽ̇rĕnẇ׃s"],[28,16,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנְ⁠נִ֛י יִסַּ֥ד בְּ⁠צִיּ֖וֹן אָ֑בֶן אֶ֣בֶן בֹּ֜חַן פִּנַּ֤ת יִקְרַת֙ מוּסָ֣ד מוּסָּ֔ד הַֽ⁠מַּאֲמִ֖ין לֹ֥א יָחִֽישׁ׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hinĕ⁠ni֛y yisȧ֥d bĕ̇⁠ẕiẏ֖wòn ʼá֑ben ʼe֣ben bò̇֜ẖan pi̇nȧ֤ţ yiqĕraţ֙ mẇsá֣d mẇsá̇֔d haֽ⁠mȧʼàmi֖yn lò֥ʼ yáẖiֽyş̌׃"],[28,17,"וְ⁠שַׂמְתִּ֤י מִשְׁפָּט֙ לְ⁠קָ֔ו וּ⁠צְדָקָ֖ה לְ⁠מִשְׁקָ֑לֶת וְ⁠יָעָ֤ה בָרָד֙ מַחְסֵ֣ה כָזָ֔ב וְ⁠סֵ֥תֶר מַ֖יִם יִשְׁטֹֽפוּ׃","wĕ⁠şâmĕţi֤̇y mişĕ̌pá̇t֙ lĕ⁠qá֔w ẇ⁠ẕĕdáqá֖h lĕ⁠mişĕ̌qá֑leţ wĕ⁠yáʻá֤h bárád֙ maẖĕsé֣h kázá֔b wĕ⁠sé֥ţer ma֖yim yişĕ̌tòֽpẇ׃"],[28,18,"וְ⁠כֻפַּ֤ר בְּרִֽיתְ⁠כֶם֙ אֶת־מָ֔וֶת וְ⁠חָזוּתְ⁠כֶ֥ם אֶת־שְׁא֖וֹל לֹ֣א תָק֑וּם שׁ֤וֹט שׁוֹטֵף֙ כִּ֣י יַֽעֲבֹ֔ר וִ⁠הְיִ֥יתֶם ל֖⁠וֹ לְ⁠מִרְמָֽס׃","wĕ⁠kupȧ֤r bĕ̇riֽyţĕ⁠kem֙ ʼeţ-má֔weţ wĕ⁠ẖázẇţĕ⁠ke֥m ʼeţ-şĕ̌ʼ֖wòl lò֣ʼ ţáq֑ẇm ş֤̌wòt ş̌wòtép֙ ki֣̇y yaֽʻàbò֔r wi⁠hĕyi֥yţem l֖⁠wò lĕ⁠mirĕmáֽs׃"],[28,19,"מִ⁠דֵּ֤י עָבְר⁠וֹ֙ יִקַּ֣ח אֶתְ⁠כֶ֔ם כִּֽי־בַ⁠בֹּ֧קֶר בַּ⁠בֹּ֛קֶר יַעֲבֹ֖ר בַּ⁠יּ֣וֹם וּ⁠בַ⁠לָּ֑יְלָה וְ⁠הָיָ֥ה רַק־זְוָעָ֖ה הָבִ֥ין שְׁמוּעָֽה׃","mi⁠dé֤̇y ʻábĕr⁠wò֙ yiqȧ֣ẖ ʼeţĕ⁠ke֔m kiֽ̇y-ba⁠bò֧̇qer bȧ⁠bò֛̇qer yaʻàbò֖r bȧ⁠ẏ֣wòm ẇ⁠ba⁠lá֑̇yĕláh wĕ⁠háyá֥h raq-zĕwáʻá֖h hábi֥yn şĕ̌mẇʻáֽh׃"],[28,20,"כִּֽי־קָצַ֥ר הַ⁠מַּצָּ֖ע מֵֽ⁠הִשְׂתָּרֵ֑עַ וְ⁠הַ⁠מַּסֵּכָ֥ה צָ֖רָה כְּ⁠הִתְכַּנֵּֽס׃","kiֽ̇y-qáẕa֥r ha⁠mȧẕá֖̇ʻ méֽ⁠hişĕ̂ţá̇ré֑ʻa wĕ⁠ha⁠mȧsé̇ká֥h ẕá֖ráh kĕ̇⁠hiţĕkȧnéֽ̇s׃"],[28,21,"כִּ֤י כְ⁠הַר־פְּרָצִים֙ יָק֣וּם יְהוָ֔ה כְּ⁠עֵ֖מֶק בְּ⁠גִבְע֣וֹן יִרְגָּ֑ז לַ⁠עֲשׂ֤וֹת מַעֲשֵׂ֨⁠הוּ֙ זָ֣ר מַעֲשֵׂ֔⁠הוּ וְ⁠לַֽ⁠עֲבֹד֙ עֲבֹ֣דָת֔⁠וֹ נָכְרִיָּ֖ה עֲבֹדָתֽ⁠וֹ׃","ki֤̇y kĕ⁠har-pĕ̇ráẕiym֙ yáq֣ẇm yĕhwá֔h kĕ̇⁠ʻé֖meq bĕ̇⁠gibĕʻ֣wòn yirĕgá֑̇z la⁠ʻàş֤̂wòţ maʻàşé̂֨⁠hẇ֙ zá֣r maʻàşé̂֔⁠hẇ wĕ⁠laֽ⁠ʻàbòd֙ ʻàbò֣dáţ֔⁠wò nákĕriyá֖̇h ʻàbòdáţֽ⁠wò׃"],[28,22,"וְ⁠עַתָּה֙ אַל־תִּתְלוֹצָ֔צוּ פֶּֽן־יֶחְזְק֖וּ מֽוֹסְרֵי⁠כֶ֑ם כִּֽי־כָלָ֨ה וְ⁠נֶחֱרָצָ֜ה שָׁמַ֗עְתִּי מֵ⁠אֵ֨ת אֲדֹנָ֧⁠י יְהוִ֛ה צְבָא֖וֹת עַל־כָּל־הָ⁠אָֽרֶץ׃","wĕ⁠ʻaţá̇h֙ ʼal-ţi̇ţĕlwòẕá֔ẕẇ pėֽn-yeẖĕzĕq֖ẇ mֽwòsĕréy⁠ke֑m kiֽ̇y-kálá֨h wĕ⁠neẖèráẕá֜h şá̌ma֗ʻĕţi̇y mé⁠ʼé֨ţ ʼàdòná֧⁠y yĕhwi֛h ẕĕbáʼ֖wòţ ʻal-ká̇l-há⁠ʼáֽreẕ׃"],[28,23,"הַאֲזִ֥ינוּ וְ⁠שִׁמְע֖וּ קוֹלִ֑⁠י הַקְשִׁ֥יבוּ וְ⁠שִׁמְע֖וּ אִמְרָתִֽ⁠י׃","haʼàzi֥ynẇ wĕ⁠şǐmĕʻ֖ẇ qwòli֑⁠y haqĕşǐ֥ybẇ wĕ⁠şǐmĕʻ֖ẇ ʼimĕráţiֽ⁠y׃"],[28,24,"הֲ⁠כֹ֣ל הַ⁠יּ֔וֹם יַחֲרֹ֥שׁ הַ⁠חֹרֵ֖שׁ לִ⁠זְרֹ֑עַ יְפַתַּ֥ח וִֽ⁠ישַׂדֵּ֖ד אַדְמָתֽ⁠וֹ׃","hà⁠kò֣l ha⁠ẏ֔wòm yaẖàrò֥ş̌ ha⁠ẖòré֖ş̌ li⁠zĕrò֑ʻa yĕpaţȧ֥ẖ wiֽ⁠yşâdé֖̇d ʼadĕmáţֽ⁠wò׃"],[28,25,"הֲ⁠לוֹא֙ אִם־שִׁוָּ֣ה פָנֶ֔י⁠הָ וְ⁠הֵפִ֥יץ קֶ֖צַח וְ⁠כַמֹּ֣ן יִזְרֹ֑ק וְ⁠שָׂ֨ם חִטָּ֤ה שׂוֹרָה֙ וּ⁠שְׂעֹרָ֣ה נִסְמָ֔ן וְ⁠כֻסֶּ֖מֶת גְּבֻלָתֽ⁠וֹ׃","hà⁠lwòʼ֙ ʼim-şǐwá֣̇h páne֔y⁠há wĕ⁠hépi֥yẕ qe֖ẕaẖ wĕ⁠kamò֣̇n yizĕrò֑q wĕ⁠şá̂֨m ẖitá֤̇h ş̂wòráh֙ ẇ⁠şĕ̂ʻòrá֣h nisĕmá֔n wĕ⁠kusė֖meţ gĕ̇buláţֽ⁠wò׃"],[28,26,"וְ⁠יִסְּר֥⁠וֹ לַ⁠מִּשְׁפָּ֖ט אֱלֹהָ֥י⁠ו יוֹרֶֽ⁠נּוּ׃","wĕ⁠yisĕ̇r֥⁠wò la⁠mi̇şĕ̌pá֖̇t ʼèlòhá֥y⁠w ywòreֽ⁠ṅẇ׃"],[28,27,"כִּ֣י לֹ֤א בֶֽ⁠חָרוּץ֙ י֣וּדַשׁ קֶ֔צַח וְ⁠אוֹפַ֣ן עֲגָלָ֔ה עַל־כַּמֹּ֖ן יוּסָּ֑ב כִּ֧י בַ⁠מַּטֶּ֛ה יֵחָ֥בֶט קֶ֖צַח וְ⁠כַמֹּ֥ן בַּ⁠שָּֽׁבֶט׃","ki֣̇y lò֤ʼ beֽ⁠ẖárẇẕ֙ y֣ẇdaş̌ qe֔ẕaẖ wĕ⁠ʼwòpa֣n ʻàgálá֔h ʻal-kȧmò֖̇n yẇsá֑̇b ki֧̇y ba⁠mȧtė֛h yéẖá֥bet qe֖ẕaẖ wĕ⁠kamò֥̇n bȧ⁠şáֽ̇̌bet׃"],[28,28,"לֶ֣חֶם יוּדָ֔ק כִּ֛י לֹ֥א לָ⁠נֶ֖צַח אָד֣וֹשׁ יְדוּשֶׁ֑⁠נּוּ וְ֠⁠הָמַם גִּלְגַּ֧ל עֶגְלָת֛⁠וֹ וּ⁠פָרָשָׁ֖י⁠ו לֹֽא־יְדֻקֶּֽ⁠נּוּ׃","le֣ẖem yẇdá֔q ki֛̇y lò֥ʼ lá⁠ne֖ẕaẖ ʼád֣wòş̌ yĕdẇşě֑⁠ṅẇ wĕ֠⁠hámam gi̇lĕgȧ֧l ʻegĕláţ֛⁠wò ẇ⁠páráşá֖̌y⁠w lòֽʼ-yĕduqėֽ⁠ṅẇ׃"],[28,29,"גַּם־זֹ֕את מֵ⁠עִ֛ם יְהוָ֥ה צְבָא֖וֹת יָצָ֑אָה הִפְלִ֣יא עֵצָ֔ה הִגְדִּ֖יל תּוּשִׁיָּֽה׃ס","gȧm-zò֕ʼţ mé⁠ʻi֛m yĕhwá֥h ẕĕbáʼ֖wòţ yáẕá֑ʼáh hipĕli֣yʼ ʻéẕá֔h higĕdi֖̇yl ţ̇ẇşǐyáֽ̇h׃s"],[29,1,"ה֚וֹי אֲרִיאֵ֣ל אֲרִיאֵ֔ל קִרְיַ֖ת חָנָ֣ה דָוִ֑ד סְפ֥וּ שָׁנָ֛ה עַל־שָׁנָ֖ה חַגִּ֥ים יִנְקֹֽפוּ׃","h֚wòy ʼàriyʼé֣l ʼàriyʼé֔l qirĕya֖ţ ẖáná֣h dáwi֑d sĕp֥ẇ şá̌ná֛h ʻal-şá̌ná֖h ẖagi֥̇ym yinĕqòֽpẇ׃"],[29,2,"וַ⁠הֲצִיק֖וֹתִי לַֽ⁠אֲרִיאֵ֑ל וְ⁠הָיְתָ֤ה תַֽאֲנִיָּה֙ וַֽ⁠אֲנִיָּ֔ה וְ⁠הָ֥יְתָה לִּ֖⁠י כַּ⁠אֲרִיאֵֽל׃","wa⁠hàẕiyq֖wòţiy laֽ⁠ʼàriyʼé֑l wĕ⁠háyĕţá֤h ţaֽʼàniyá̇h֙ waֽ⁠ʼàniyá̇֔h wĕ⁠há֥yĕţáh li֖̇⁠y kȧ⁠ʼàriyʼéֽl׃"],[29,3,"וְ⁠חָנִ֥יתִי כַ⁠דּ֖וּר עָלָ֑יִ⁠ךְ וְ⁠צַרְתִּ֤י עָלַ֨יִ⁠ךְ֙ מֻצָּ֔ב וַ⁠הֲקִֽימֹתִ֥י עָלַ֖יִ⁠ךְ מְצֻרֹֽת׃","wĕ⁠ẖáni֥yţiy ka⁠ḋ֖ẇr ʻálá֑yi⁠kĕ wĕ⁠ẕarĕţi֤̇y ʻála֨yi⁠kĕ֙ muẕá̇֔b wa⁠hàqֽiymòţi֥y ʻála֖yi⁠kĕ mĕẕuròֽţ׃"],[29,4,"וְ⁠שָׁפַלְתְּ֙ מֵ⁠אֶ֣רֶץ תְּדַבֵּ֔רִי וּ⁠מֵֽ⁠עָפָ֖ר תִּשַּׁ֣ח אִמְרָתֵ֑⁠ךְ וְֽ֠⁠הָיָה כְּ⁠א֤וֹב מֵ⁠אֶ֨רֶץ֙ קוֹלֵ֔⁠ךְ וּ⁠מֵ⁠עָפָ֖ר אִמְרָתֵ֥⁠ךְ תְּצַפְצֵֽף׃","wĕ⁠şá̌palĕţĕ̇֙ mé⁠ʼe֣reẕ ţĕ̇dabé̇֔riy ẇ⁠méֽ⁠ʻápá֖r ţi̇şȧ֣̌ẖ ʼimĕráţé֑⁠kĕ wĕֽ֠⁠háyáh kĕ̇⁠ʼ֤wòb mé⁠ʼe֨reẕ֙ qwòlé֔⁠kĕ ẇ⁠mé⁠ʻápá֖r ʼimĕráţé֥⁠kĕ ţĕ̇ẕapĕẕéֽp׃"],[29,5,"וְ⁠הָיָ֛ה כְּ⁠אָבָ֥ק דַּ֖ק הֲמ֣וֹן זָרָ֑יִ⁠ךְ וּ⁠כְ⁠מֹ֤ץ עֹבֵר֙ הֲמ֣וֹן עָֽרִיצִ֔ים וְ⁠הָיָ֖ה לְ⁠פֶ֥תַע פִּתְאֹֽם׃","wĕ⁠háyá֛h kĕ̇⁠ʼábá֥q dȧ֖q hàm֣wòn zárá֑yi⁠kĕ ẇ⁠kĕ⁠mò֤ẕ ʻòbér֙ hàm֣wòn ʻáֽriyẕi֔ym wĕ⁠háyá֖h lĕ⁠pe֥ţaʻ pi̇ţĕʼòֽm׃"],[29,6,"מֵ⁠עִ֨ם יְהוָ֤ה צְבָאוֹת֙ תִּפָּקֵ֔ד בְּ⁠רַ֥עַם וּ⁠בְ⁠רַ֖עַשׁ וְ⁠ק֣וֹל גָּד֑וֹל סוּפָה֙ וּ⁠סְעָרָ֔ה וְ⁠לַ֖הַב אֵ֥שׁ אוֹכֵלָֽה׃","mé⁠ʻi֨m yĕhwá֤h ẕĕbáʼwòţ֙ ţi̇pá̇qé֔d bĕ̇⁠ra֥ʻam ẇ⁠bĕ⁠ra֖ʻaş̌ wĕ⁠q֣wòl gá̇d֑wòl sẇpáh֙ ẇ⁠sĕʻárá֔h wĕ⁠la֖hab ʼé֥ş̌ ʼwòkéláֽh׃"],[29,7,"וְ⁠הָיָ֗ה כַּֽ⁠חֲלוֹם֙ חֲז֣וֹן לַ֔יְלָה הֲמוֹן֙ כָּל־הַ⁠גּוֹיִ֔ם הַ⁠צֹּבְאִ֖ים עַל־אֲרִיאֵ֑ל וְ⁠כָל־צֹבֶ֨י⁠הָ֙ וּ⁠מְצֹ֣דָתָ֔⁠הּ וְ⁠הַ⁠מְּצִיקִ֖ים לָֽ⁠הּ׃","wĕ⁠háyá֗h kȧֽ⁠ẖàlwòm֙ ẖàz֣wòn la֔yĕláh hàmwòn֙ ká̇l-ha⁠ġwòyi֔m ha⁠ẕò̇bĕʼi֖ym ʻal-ʼàriyʼé֑l wĕ⁠kál-ẕòbe֨y⁠há֙ ẇ⁠mĕẕò֣dáţá֔⁠ḣ wĕ⁠ha⁠mĕ̇ẕiyqi֖ym láֽ⁠ḣ׃"],[29,8,"וְ⁠הָיָ֡ה כַּ⁠אֲשֶׁר֩ יַחֲלֹ֨ם הָ⁠רָעֵ֜ב וְ⁠הִנֵּ֣ה אוֹכֵ֗ל וְ⁠הֵקִיץ֮ וְ⁠רֵיקָ֣ה נַפְשׁ⁠וֹ֒ וְ⁠כַ⁠אֲשֶׁ֨ר יַחֲלֹ֤ם הַ⁠צָּמֵא֙ וְ⁠הִנֵּ֣ה שֹׁתֶ֔ה וְ⁠הֵקִיץ֙ וְ⁠הִנֵּ֣ה עָיֵ֔ף וְ⁠נַפְשׁ֖⁠וֹ שׁוֹקֵקָ֑ה כֵּ֣ן יִֽהְיֶ֗ה הֲמוֹן֙ כָּל־הַ⁠גּוֹיִ֔ם הַ⁠צֹּבְאִ֖ים עַל־הַ֥ר צִיּֽוֹן׃ס","wĕ⁠háyá֡h kȧ⁠ʼàşěr֩ yaẖàlò֨m há⁠ráʻé֜b wĕ⁠hiné֣̇h ʼwòké֗l wĕ⁠héqiyẕ֮ wĕ⁠réyqá֣h napĕş̌⁠wò֒ wĕ⁠ka⁠ʼàşě֨r yaẖàlò֤m ha⁠ẕá̇méʼ֙ wĕ⁠hiné֣̇h şò̌ţe֔h wĕ⁠héqiyẕ֙ wĕ⁠hiné֣̇h ʻáyé֔p wĕ⁠napĕş֖̌⁠wò ş̌wòqéqá֑h ké֣̇n yiֽhĕye֗h hàmwòn֙ ká̇l-ha⁠ġwòyi֔m ha⁠ẕò̇bĕʼi֖ym ʻal-ha֥r ẕiẏֽwòn׃s"],[29,9,"הִתְמַהְמְה֣וּ וּ⁠תְמָ֔הוּ הִשְׁתַּֽעַשְׁע֖וּ וָ⁠שֹׁ֑עוּ שָֽׁכְר֣וּ וְ⁠לֹא־יַ֔יִן נָע֖וּ וְ⁠לֹ֥א שֵׁכָֽר׃","hiţĕmahĕmĕh֣ẇ ẇ⁠ţĕmá֔hẇ hişĕ̌ţֽ̇aʻaşĕ̌ʻ֖ẇ wá⁠şò֑̌ʻẇ şáֽ̌kĕr֣ẇ wĕ⁠lòʼ-ya֔yin náʻ֖ẇ wĕ⁠lò֥ʼ şé̌káֽr׃"],[29,10,"כִּֽי־נָסַ֨ךְ עֲלֵי⁠כֶ֤ם יְהוָה֙ ר֣וּחַ תַּרְדֵּמָ֔ה וַ⁠יְעַצֵּ֖ם אֶת־עֵֽינֵי⁠כֶ֑ם אֶת־הַ⁠נְּבִיאִ֛ים וְ⁠אֶת־רָאשֵׁי⁠כֶ֥ם הַ⁠חֹזִ֖ים כִּסָּֽה׃","kiֽ̇y-nása֨kĕ ʻàléy⁠ke֤m yĕhwáh֙ r֣ẇẖa ţȧrĕdé̇má֔h wa⁠yĕʻaẕé֖̇m ʼeţ-ʻéֽynéy⁠ke֑m ʼeţ-ha⁠nĕ̇biyʼi֛ym wĕ⁠ʼeţ-ráʼşé̌y⁠ke֥m ha⁠ẖòzi֖ym ki̇sáֽ̇h׃"],[29,11,"וַ⁠תְּהִ֨י לָ⁠כֶ֜ם חָז֣וּת הַ⁠כֹּ֗ל כְּ⁠דִבְרֵי֮ הַ⁠סֵּ֣פֶר הֶֽ⁠חָתוּם֒ אֲשֶֽׁר־יִתְּנ֣וּ אֹת֗⁠וֹ אֶל־יוֹדֵ֥עַ ה⁠ספר לֵ⁠אמֹ֖ר קְרָ֣א נָא־זֶ֑ה וְ⁠אָמַר֙ לֹ֣א אוּכַ֔ל כִּ֥י חָת֖וּם הֽוּא׃","wa⁠ţĕ̇hi֨y lá⁠ke֜m ẖáz֣ẇţ ha⁠kò̇֗l kĕ̇⁠dibĕréy֮ ha⁠sé֣̇per heֽ⁠ẖáţẇm֒ ʼàşěֽr-yiţĕ̇n֣ẇ ʼòţ֗⁠wò ʼel-ywòdé֥ʻa h⁠spr lé⁠ʼmò֖r qĕrá֣ʼ náʼ-ze֑h wĕ⁠ʼámar֙ lò֣ʼ ʼẇka֔l ki֥̇y ẖáţ֖ẇm hֽẇʼ׃"],[29,12,"וְ⁠נִתַּ֣ן הַ⁠סֵּ֗פֶר עַל֩ אֲשֶׁ֨ר לֹֽא־יָדַ֥ע סֵ֛פֶר לֵ⁠אמֹ֖ר קְרָ֣א נָא־זֶ֑ה וְ⁠אָמַ֕ר לֹ֥א יָדַ֖עְתִּי סֵֽפֶר׃ס","wĕ⁠niţȧ֣n ha⁠sé̇֗per ʻal֩ ʼàşě֨r lòֽʼ-yáda֥ʻ sé֛per lé⁠ʼmò֖r qĕrá֣ʼ náʼ-ze֑h wĕ⁠ʼáma֕r lò֥ʼ yáda֖ʻĕţi̇y séֽper׃s"],[29,13,"וַ⁠יֹּ֣אמֶר אֲדֹנָ֗⁠י יַ֚עַן כִּ֤י נִגַּשׁ֙ הָ⁠עָ֣ם הַ⁠זֶּ֔ה בְּ⁠פִ֤י⁠ו וּ⁠בִ⁠שְׂפָתָי⁠ו֙ כִּבְּד֔וּ⁠נִי וְ⁠לִבּ֖⁠וֹ רִחַ֣ק מִמֶּ֑⁠נִּי וַ⁠תְּהִ֤י יִרְאָתָ⁠ם֙ אֹתִ֔⁠י מִצְוַ֥ת אֲנָשִׁ֖ים מְלֻמָּדָֽה׃","wa⁠yò֣̇ʼmer ʼàdòná֗⁠y ya֚ʻan ki֤̇y nigȧş̌֙ há⁠ʻá֣m ha⁠zė֔h bĕ̇⁠pi֤y⁠w ẇ⁠bi⁠şĕ̂páţáy⁠w֙ ki̇bĕ̇d֔ẇ⁠niy wĕ⁠liḃ֖⁠wò riẖa֣q mimė֑⁠ni̇y wa⁠ţĕ̇hi֤y yirĕʼáţá⁠m֙ ʼòţi֔⁠y miẕĕwa֥ţ ʼànáşǐ֖ym mĕlumá̇dáֽh׃"],[29,14,"לָ⁠כֵ֗ן הִנְ⁠נִ֥י יוֹסִ֛ף לְ⁠הַפְלִ֥יא אֶת־הָֽ⁠עָם־הַ⁠זֶּ֖ה הַפְלֵ֣א וָ⁠פֶ֑לֶא וְ⁠אָֽבְדָה֙ חָכְמַ֣ת חֲכָמָ֔י⁠ו וּ⁠בִינַ֥ת נְבֹנָ֖י⁠ו תִּסְתַּתָּֽר׃ס","lá⁠ké֗n hinĕ⁠ni֥y ywòsi֛p lĕ⁠hapĕli֥yʼ ʼeţ-háֽ⁠ʻám-ha⁠zė֖h hapĕlé֣ʼ wá⁠pe֑leʼ wĕ⁠ʼáֽbĕdáh֙ ẖákĕma֣ţ ẖàkámá֔y⁠w ẇ⁠biyna֥ţ nĕbòná֖y⁠w ţi̇sĕţȧţáֽ̇r׃s"],[29,15,"ה֛וֹי הַ⁠מַּעֲמִיקִ֥ים מֵֽ⁠יהוָ֖ה לַ⁠סְתִּ֣ר עֵצָ֑ה וְ⁠הָיָ֤ה בְ⁠מַחְשָׁךְ֙ מַֽעֲשֵׂי⁠הֶ֔ם וַ⁠יֹּ֣אמְר֔וּ מִ֥י רֹאֵ֖⁠נוּ וּ⁠מִ֥י יוֹדְעֵֽ⁠נוּ׃","h֛wòy ha⁠mȧʻàmiyqi֥ym méֽ⁠yhwá֖h la⁠sĕţi֣̇r ʻéẕá֑h wĕ⁠háyá֤h bĕ⁠maẖĕşá̌kĕ֙ maֽʻàşé̂y⁠he֔m wa⁠yò֣̇ʼmĕr֔ẇ mi֥y ròʼé֖⁠nẇ ẇ⁠mi֥y ywòdĕʻéֽ⁠nẇ׃"],[29,16,"הַ֨פְכְּ⁠כֶ֔ם אִם־כְּ⁠חֹ֥מֶר הַ⁠יֹּצֵ֖ר יֵֽחָשֵׁ֑ב כִּֽי־יֹאמַ֨ר מַעֲשֶׂ֤ה לְ⁠עֹשֵׂ֨⁠הוּ֙ לֹ֣א עָשָׂ֔⁠נִי וְ⁠יֵ֛צֶר אָמַ֥ר לְ⁠יוֹצְר֖⁠וֹ לֹ֥א הֵבִֽין׃","ha֨pĕkĕ̇⁠ke֔m ʼim-kĕ̇⁠ẖò֥mer ha⁠yò̇ẕé֖r yéֽẖáşé֑̌b kiֽ̇y-yòʼma֨r maʻàşê֤h lĕ⁠ʻòşé̂֨⁠hẇ֙ lò֣ʼ ʻáşá̂֔⁠niy wĕ⁠yé֛ẕer ʼáma֥r lĕ⁠ywòẕĕr֖⁠wò lò֥ʼ hébiֽyn׃"],[29,17,"הֲ⁠לוֹא־עוֹד֙ מְעַ֣ט מִזְעָ֔ר וְ⁠שָׁ֥ב לְבָנ֖וֹן לַ⁠כַּרְמֶ֑ל וְ⁠הַ⁠כַּרְמֶ֖ל לַ⁠יַּ֥עַר יֵחָשֵֽׁב׃","hà⁠lwòʼ-ʻwòd֙ mĕʻa֣t mizĕʻá֔r wĕ⁠şá֥̌b lĕbán֖wòn la⁠kȧrĕme֑l wĕ⁠ha⁠kȧrĕme֖l la⁠yȧ֥ʻar yéẖáşéֽ̌b׃"],[29,18,"וְ⁠שָׁמְע֧וּ בַ⁠יּוֹם־הַ⁠ה֛וּא הַ⁠חֵרְשִׁ֖ים דִּבְרֵי־סֵ֑פֶר וּ⁠מֵ⁠אֹ֣פֶל וּ⁠מֵ⁠חֹ֔שֶׁךְ עֵינֵ֥י עִוְרִ֖ים תִּרְאֶֽינָה׃","wĕ⁠şá̌mĕʻ֧ẇ ba⁠ẏwòm-ha⁠h֛ẇʼ ha⁠ẖérĕşǐ֖ym di̇bĕréy-sé֑per ẇ⁠mé⁠ʼò֣pel ẇ⁠mé⁠ẖò֔şěkĕ ʻéyné֥y ʻiwĕri֖ym ţi̇rĕʼeֽynáh׃"],[29,19,"וְ⁠יָסְפ֧וּ עֲנָוִ֛ים בַּֽ⁠יהוָ֖ה שִׂמְחָ֑ה וְ⁠אֶבְיוֹנֵ֣י אָדָ֔ם בִּ⁠קְד֥וֹשׁ יִשְׂרָאֵ֖ל יָגִֽילוּ׃","wĕ⁠yásĕp֧ẇ ʻànáwi֛ym bȧֽ⁠yhwá֖h şîmĕẖá֑h wĕ⁠ʼebĕywòné֣y ʼádá֔m bi̇⁠qĕd֥wòş̌ yişĕ̂ráʼé֖l yágiֽylẇ׃"],[29,20,"כִּֽי־אָפֵ֥ס עָרִ֖יץ וְ⁠כָ֣לָה לֵ֑ץ וְ⁠נִכְרְת֖וּ כָּל־שֹׁ֥קְדֵי אָֽוֶן׃","kiֽ̇y-ʼápé֥s ʻári֖yẕ wĕ⁠ká֣láh lé֑ẕ wĕ⁠nikĕrĕţ֖ẇ ká̇l-şò֥̌qĕdéy ʼáֽwen׃"],[29,21,"מַחֲטִיאֵ֤י אָדָם֙ בְּ⁠דָבָ֔ר וְ⁠לַ⁠מּוֹכִ֥יחַ בַּ⁠שַּׁ֖עַר יְקֹשׁ֑וּ⁠ן וַ⁠יַּטּ֥וּ בַ⁠תֹּ֖הוּ צַדִּֽיק׃ס","maẖàtiyʼé֤y ʼádám֙ bĕ̇⁠dábá֔r wĕ⁠la⁠ṁwòki֥yẖa bȧ⁠şȧ֖̌ʻar yĕqòş֑̌ẇ⁠n wa⁠yȧṫ֥ẇ ba⁠ţò֖̇hẇ ẕadiֽ̇yq׃s"],[29,22,"לָ⁠כֵ֗ן כֹּֽה־אָמַ֤ר יְהוָה֙ אֶל־בֵּ֣ית יַֽעֲקֹ֔ב אֲשֶׁ֥ר פָּדָ֖ה אֶת־אַבְרָהָ֑ם לֹֽא־עַתָּ֤ה יֵבוֹשׁ֙ יַֽעֲקֹ֔ב וְ⁠לֹ֥א עַתָּ֖ה פָּנָ֥י⁠ו יֶחֱוָֽרוּ׃","lá⁠ké֗n kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼel-bé֣̇yţ yaֽʻàqò֔b ʼàşě֥r pá̇dá֖h ʼeţ-ʼabĕráhá֑m lòֽʼ-ʻaţá֤̇h yébwòş̌֙ yaֽʻàqò֔b wĕ⁠lò֥ʼ ʻaţá֖̇h pá̇ná֥y⁠w yeẖèwáֽrẇ׃"],[29,23,"כִּ֣י בִ֠⁠רְאֹת⁠וֹ יְלָדָ֞י⁠ו מַעֲשֵׂ֥ה יָדַ֛⁠י בְּ⁠קִרְבּ֖⁠וֹ יַקְדִּ֣ישֽׁוּ שְׁמִ֑⁠י וְ⁠הִקְדִּ֨ישׁוּ֙ אֶת־קְד֣וֹשׁ יַֽעֲקֹ֔ב וְ⁠אֶת־אֱלֹהֵ֥י יִשְׂרָאֵ֖ל יַעֲרִֽיצוּ׃","ki֣̇y bi֠⁠rĕʼòţ⁠wò yĕládá֞y⁠w maʻàşé֥̂h yáda֛⁠y bĕ̇⁠qirĕḃ֖⁠wò yaqĕdi֣̇yşֽ̌ẇ şĕ̌mi֑⁠y wĕ⁠hiqĕdi̇֨yş̌ẇ֙ ʼeţ-qĕd֣wòş̌ yaֽʻàqò֔b wĕ⁠ʼeţ-ʼèlòhé֥y yişĕ̂ráʼé֖l yaʻàriֽyẕẇ׃"],[29,24,"וְ⁠יָדְע֥וּ תֹֽעֵי־ר֖וּחַ בִּינָ֑ה וְ⁠רוֹגְנִ֖ים יִלְמְדוּ־לֶֽקַח׃","wĕ⁠yádĕʻ֥ẇ ţòֽʻéy-r֖ẇẖa bi̇yná֑h wĕ⁠rwògĕni֖ym yilĕmĕdẇ-leֽqaẖ׃"],[30,1,"ה֣וֹי בָּנִ֤ים סֽוֹרְרִים֙ נְאֻם־יְהוָ֔ה לַ⁠עֲשׂ֤וֹת עֵצָה֙ וְ⁠לֹ֣א מִ⁠נִּ֔י וְ⁠לִ⁠נְסֹ֥ךְ מַסֵּכָ֖ה וְ⁠לֹ֣א רוּחִ֑⁠י לְמַ֛עַן סְפ֥וֹת חַטָּ֖את עַל־חַטָּֽאת׃","h֣wòy bá̇ni֤ym sֽwòrĕriym֙ nĕʼum-yĕhwá֔h la⁠ʻàş֤̂wòţ ʻéẕáh֙ wĕ⁠lò֣ʼ mi⁠ni̇֔y wĕ⁠li⁠nĕsò֥kĕ masé̇ká֖h wĕ⁠lò֣ʼ rẇẖi֑⁠y lĕma֛ʻan sĕp֥wòţ ẖatá֖̇ʼţ ʻal-ẖatáֽ̇ʼţ׃"],[30,2,"הַ⁠הֹלְכִים֙ לָ⁠רֶ֣דֶת מִצְרַ֔יִם וּ⁠פִ֖⁠י לֹ֣א שָׁאָ֑לוּ לָ⁠עוֹז֙ בְּ⁠מָע֣וֹז פַּרְעֹ֔ה וְ⁠לַ⁠חְס֖וֹת בְּ⁠צֵ֥ל מִצְרָֽיִם׃","ha⁠hòlĕkiym֙ lá⁠re֣deţ miẕĕra֔yim ẇ⁠pi֖⁠y lò֣ʼ şá̌ʼá֑lẇ lá⁠ʻwòz֙ bĕ̇⁠máʻ֣wòz pȧrĕʻò֔h wĕ⁠la⁠ẖĕs֖wòţ bĕ̇⁠ẕé֥l miẕĕráֽyim׃"],[30,3,"וְ⁠הָיָ֥ה לָ⁠כֶ֛ם מָע֥וֹז פַּרְעֹ֖ה לְ⁠בֹ֑שֶׁת וְ⁠הֶ⁠חָס֥וּת בְּ⁠צֵל־מִצְרַ֖יִם לִ⁠כְלִמָּֽה׃","wĕ⁠háyá֥h lá⁠ke֛m máʻ֥wòz pȧrĕʻò֖h lĕ⁠bò֑şěţ wĕ⁠he⁠ẖás֥ẇţ bĕ̇⁠ẕél-miẕĕra֖yim li⁠kĕlimáֽ̇h׃"],[30,4,"כִּֽי־הָי֥וּ בְ⁠צֹ֖עַן שָׂרָ֑י⁠ו וּ⁠מַלְאָכָ֖י⁠ו חָנֵ֥ס יַגִּֽיעוּ׃","kiֽ̇y-háy֥ẇ bĕ⁠ẕò֖ʻan şá̂rá֑y⁠w ẇ⁠malĕʼáká֖y⁠w ẖáné֥s yagiֽ̇yʻẇ׃"],[30,5,"כֹּ֣ל הבאיש עַל־עַ֖ם לֹא־יוֹעִ֣ילוּ לָ֑⁠מוֹ לֹ֤א לְ⁠עֵ֨זֶר֙ וְ⁠לֹ֣א לְ⁠הוֹעִ֔יל כִּ֥י לְ⁠בֹ֖שֶׁת וְ⁠גַם־לְ⁠חֶרְפָּֽה׃ס","kò֣̇l hbʼyş ʻal-ʻa֖m lòʼ-ywòʻi֣ylẇ lá֑⁠mwò lò֤ʼ lĕ⁠ʻé֨zer֙ wĕ⁠lò֣ʼ lĕ⁠hwòʻi֔yl ki֥̇y lĕ⁠bò֖şěţ wĕ⁠gam-lĕ⁠ẖerĕpáֽ̇h׃s"],[30,6,"מַשָּׂ֖א בַּהֲמ֣וֹת נֶ֑גֶב בְּ⁠אֶרֶץ֩ צָרָ֨ה וְ⁠צוּקָ֜ה לָבִ֧יא וָ⁠לַ֣יִשׁ מֵ⁠הֶ֗ם אֶפְעֶה֙ וְ⁠שָׂרָ֣ף מְעוֹפֵ֔ף יִשְׂאוּ֩ עַל־כֶּ֨תֶף עֲיָרִ֜ים חֵֽילֵ⁠הֶ֗ם וְ⁠עַל־דַּבֶּ֤שֶׁת גְּמַלִּים֙ אֽוֹצְרֹתָ֔⁠ם עַל־עַ֖ם לֹ֥א יוֹעִֽילוּ׃","maşá֖̇̂ʼ bȧhàm֣wòţ ne֑geb bĕ̇⁠ʼereẕ֩ ẕárá֨h wĕ⁠ẕẇqá֜h lábi֧yʼ wá⁠la֣yiş̌ mé⁠he֗m ʼepĕʻeh֙ wĕ⁠şá̂rá֣p mĕʻwòpé֔p yişĕ̂ʼẇ֩ ʻal-kė֨ţep ʻàyári֜ym ẖéֽylé⁠he֗m wĕ⁠ʻal-dȧbė֤şěţ gĕ̇mali̇ym֙ ʼֽwòẕĕròţá֔⁠m ʻal-ʻa֖m lò֥ʼ ywòʻiֽylẇ׃"],[30,7,"וּ⁠מִצְרַ֕יִם הֶ֥בֶל וָ⁠רִ֖יק יַעְזֹ֑רוּ לָ⁠כֵן֙ קָרָ֣אתִי לָ⁠זֹ֔את רַ֥הַב הֵ֖ם שָֽׁבֶת׃","ẇ⁠miẕĕra֕yim he֥bel wá⁠ri֖yq yaʻĕzò֑rẇ lá⁠kén֙ qárá֣ʼţiy lá⁠zò֔ʼţ ra֥hab hé֖m şáֽ̌beţ׃"],[30,8,"עַתָּ֗ה בּ֣וֹא כָתְבָ֥⁠הּ עַל־ל֛וּחַ אִתָּ֖⁠ם וְ⁠עַל־סֵ֣פֶר חֻקָּ֑⁠הּ וּ⁠תְהִי֙ לְ⁠י֣וֹם אַחֲר֔וֹן לָ⁠עַ֖ד עַד־עוֹלָֽם׃","ʻaţá̇֗h ḃ֣wòʼ káţĕbá֥⁠ḣ ʻal-l֛ẇẖa ʼiţá֖̇⁠m wĕ⁠ʻal-sé֣per ẖuqá֑̇⁠ḣ ẇ⁠ţĕhiy֙ lĕ⁠y֣wòm ʼaẖàr֔wòn lá⁠ʻa֖d ʻad-ʻwòláֽm׃"],[30,9,"כִּ֣י עַ֤ם מְרִי֙ ה֔וּא בָּנִ֖ים כֶּחָשִׁ֑ים בָּנִ֕ים לֹֽא־אָב֥וּ שְׁמ֖וֹעַ תּוֹרַ֥ת יְהוָֽה׃","ki֣̇y ʻa֤m mĕriy֙ h֔ẇʼ bá̇ni֖ym kėẖáşǐ֑ym bá̇ni֕ym lòֽʼ-ʼáb֥ẇ şĕ̌m֖wòʻa ţ̇wòra֥ţ yĕhwáֽh׃"],[30,10,"אֲשֶׁ֨ר אָמְר֤וּ לָֽ⁠רֹאִים֙ לֹ֣א תִרְא֔וּ וְ⁠לַ֣⁠חֹזִ֔ים לֹ֥א תֶחֱזוּ־לָ֖⁠נוּ נְכֹח֑וֹת דַּבְּרוּ־לָ֣⁠נוּ חֲלָק֔וֹת חֲז֖וּ מַהֲתַלּֽוֹת׃","ʼàşě֨r ʼámĕr֤ẇ láֽ⁠ròʼiym֙ lò֣ʼ ţirĕʼ֔ẇ wĕ⁠la֣⁠ẖòzi֔ym lò֥ʼ ţeẖèzẇ-lá֖⁠nẇ nĕkòẖ֑wòţ dȧbĕ̇rẇ-lá֣⁠nẇ ẖàláq֔wòţ ẖàz֖ẇ mahàţalֽ̇wòţ׃"],[30,11,"ס֚וּרוּ מִנֵּי־דֶ֔רֶךְ הַטּ֖וּ מִנֵּי־אֹ֑רַח הַשְׁבִּ֥יתוּ מִ⁠פָּנֵ֖י⁠נוּ אֶת־קְד֥וֹשׁ יִשְׂרָאֵֽל׃ס","s֚ẇrẇ miné̇y-de֔rekĕ haṫ֖ẇ miné̇y-ʼò֑raẖ haşĕ̌bi֥̇yţẇ mi⁠pá̇né֖y⁠nẇ ʼeţ-qĕd֥wòş̌ yişĕ̂ráʼéֽl׃s"],[30,12,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ קְד֣וֹשׁ יִשְׂרָאֵ֔ל יַ֥עַן מָֽאָסְ⁠כֶ֖ם בַּ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וַֽ⁠תִּבְטְחוּ֙ בְּ⁠עֹ֣שֶׁק וְ⁠נָל֔וֹז וַ⁠תִּֽשָּׁעֲנ֖וּ עָלָֽי⁠ו׃","lá⁠ké֗n kò֤̇h ʼámar֙ qĕd֣wòş̌ yişĕ̂ráʼé֔l ya֥ʻan máֽʼásĕ⁠ke֖m bȧ⁠dá̇bá֣r ha⁠zė֑h waֽ⁠ţi̇bĕtĕẖẇ֙ bĕ̇⁠ʻò֣şěq wĕ⁠nál֔wòz wa⁠ţiֽ̇şá̇̌ʻàn֖ẇ ʻáláֽy⁠w׃"],[30,13,"לָ⁠כֵ֗ן יִֽהְיֶ֤ה לָ⁠כֶם֙ הֶ⁠עָוֺ֣ן הַ⁠זֶּ֔ה כְּ⁠פֶ֣רֶץ נֹפֵ֔ל נִבְעֶ֖ה בְּ⁠חוֹמָ֣ה נִשְׂגָּבָ֑ה אֲשֶׁר־פִּתְאֹ֥ם לְ⁠פֶ֖תַע יָב֥וֹא שִׁבְרָֽ⁠הּ׃","lá⁠ké֗n yiֽhĕye֤h lá⁠kem֙ he⁠ʻáwֺ֣n ha⁠zė֔h kĕ̇⁠pe֣reẕ nòpé֔l nibĕʻe֖h bĕ̇⁠ẖwòmá֣h nişĕ̂gá̇bá֑h ʼàşěr-pi̇ţĕʼò֥m lĕ⁠pe֖ţaʻ yáb֥wòʼ şǐbĕráֽ⁠ḣ׃"],[30,14,"וּ֠⁠שְׁבָרָ⁠הּ כְּ⁠שֵׁ֨בֶר נֵ֧בֶל יוֹצְרִ֛ים כָּת֖וּת לֹ֣א יַחְמֹ֑ל וְ⁠לֹֽא־יִמָּצֵ֤א בִ⁠מְכִתָּת⁠וֹ֙ חֶ֔רֶשׂ לַ⁠חְתּ֥וֹת אֵשׁ֙ מִ⁠יָּק֔וּד וְ⁠לַ⁠חְשֹׂ֥ף מַ֖יִם מִ⁠גֶּֽבֶא׃פ","ẇ֠⁠şĕ̌bárá⁠ḣ kĕ̇⁠şé̌֨ber né֧bel ywòẕĕri֛ym ká̇ţ֖ẇţ lò֣ʼ yaẖĕmò֑l wĕ⁠lòֽʼ-yimá̇ẕé֤ʼ bi⁠mĕkiţá̇ţ⁠wò֙ ẖe֔reş̂ la⁠ẖĕţ֥̇wòţ ʼéş̌֙ mi⁠yá̇q֔ẇd wĕ⁠la⁠ẖĕşò֥̂p ma֖yim mi⁠gėֽbeʼ׃p"],[30,15,"כִּ֣י כֹֽה־אָמַר֩ אֲדֹנָ֨⁠י יְהוִ֜ה קְד֣וֹשׁ יִשְׂרָאֵ֗ל בְּ⁠שׁוּבָ֤ה וָ⁠נַ֨חַת֙ תִּוָּ֣שֵׁע֔וּ⁠ן בְּ⁠הַשְׁקֵט֙ וּ⁠בְ⁠בִטְחָ֔ה תִּהְיֶ֖ה גְּבֽוּרַתְ⁠כֶ֑ם וְ⁠לֹ֖א אֲבִיתֶֽם׃","ki֣̇y kòֽh-ʼámar֩ ʼàdòná֨⁠y yĕhwi֜h qĕd֣wòş̌ yişĕ̂ráʼé֗l bĕ̇⁠ş̌ẇbá֤h wá⁠na֨ẖaţ֙ ţi̇wá֣̇şé̌ʻ֔ẇ⁠n bĕ̇⁠haşĕ̌qét֙ ẇ⁠bĕ⁠bitĕẖá֔h ţi̇hĕye֖h gĕ̇bֽẇraţĕ⁠ke֑m wĕ⁠lò֖ʼ ʼàbiyţeֽm׃"],[30,16,"וַ⁠תֹּ֨אמְר֥וּ לֹא־כִ֛י עַל־ס֥וּס נָנ֖וּס עַל־כֵּ֣ן תְּנוּס֑וּ⁠ן וְ⁠עַל־קַ֣ל נִרְכָּ֔ב עַל־כֵּ֖ן יִקַּ֥לּוּ רֹדְפֵי⁠כֶֽם׃","wa⁠ţò̇֨ʼmĕr֥ẇ lòʼ-ki֛y ʻal-s֥ẇs nán֖ẇs ʻal-ké֣̇n ţĕ̇nẇs֑ẇ⁠n wĕ⁠ʻal-qa֣l nirĕká̇֔b ʻal-ké֖̇n yiqȧ֥l̇ẇ ròdĕpéy⁠keֽm׃"],[30,17,"אֶ֣לֶף אֶחָ֗ד מִ⁠פְּנֵי֙ גַּעֲרַ֣ת אֶחָ֔ד מִ⁠פְּנֵ֛י גַּעֲרַ֥ת חֲמִשָּׁ֖ה תָּנֻ֑סוּ עַ֣ד אִם־נוֹתַרְתֶּ֗ם כַּ⁠תֹּ֨רֶן֙ עַל־רֹ֣אשׁ הָ⁠הָ֔ר וְ⁠כַ⁠נֵּ֖ס עַל־הַ⁠גִּבְעָֽה׃","ʼe֣lep ʼeẖá֗d mi⁠pĕ̇néy֙ gȧʻàra֣ţ ʼeẖá֔d mi⁠pĕ̇né֛y gȧʻàra֥ţ ẖàmişá֖̇̌h ţá̇nu֑sẇ ʻa֣d ʼim-nwòţarĕţė֗m kȧ⁠ţò̇֨ren֙ ʻal-rò֣ʼş̌ há⁠há֔r wĕ⁠ka⁠né֖̇s ʻal-ha⁠gi̇bĕʻáֽh׃"],[30,18,"וְ⁠לָ⁠כֵ֞ן יְחַכֶּ֤ה יְהוָה֙ לַֽ⁠חֲנַנְ⁠כֶ֔ם וְ⁠לָ⁠כֵ֥ן יָר֖וּם לְ⁠רַֽחֶמְ⁠כֶ֑ם כִּֽי־אֱלֹהֵ֤י מִשְׁפָּט֙ יְהוָ֔ה אַשְׁרֵ֖י כָּל־ח֥וֹכֵי לֽ⁠וֹ׃ס","wĕ⁠lá⁠ké֞n yĕẖakė֤h yĕhwáh֙ laֽ⁠ẖànanĕ⁠ke֔m wĕ⁠lá⁠ké֥n yár֖ẇm lĕ⁠raֽẖemĕ⁠ke֑m kiֽ̇y-ʼèlòhé֤y mişĕ̌pá̇t֙ yĕhwá֔h ʼaşĕ̌ré֖y ká̇l-ẖ֥wòkéy lֽ⁠wò׃s"],[30,19,"כִּי־עַ֛ם בְּ⁠צִיּ֥וֹן יֵשֵׁ֖ב בִּ⁠ירֽוּשָׁלִָ֑ם בָּכ֣וֹ לֹֽא־תִבְכֶּ֗ה חָנ֤וֹן יָחְנְ⁠ךָ֙ לְ⁠ק֣וֹל זַעֲקֶ֔⁠ךָ כְּ⁠שָׁמְעָת֖⁠וֹ עָנָֽ⁠ךְ׃","ki̇y-ʻa֛m bĕ̇⁠ẕiẏ֥wòn yéşé֖̌b bi̇⁠yrֽẇşá̌liá֑m bá̇k֣wò lòֽʼ-ţibĕkė֗h ẖán֤wòn yáẖĕnĕ⁠ká֙ lĕ⁠q֣wòl zaʻàqe֔⁠ká kĕ̇⁠şá̌mĕʻáţ֖⁠wò ʻánáֽ⁠kĕ׃"],[30,20,"וְ⁠נָתַ֨ן לָ⁠כֶ֧ם אֲדֹנָ֛⁠י לֶ֥חֶם צָ֖ר וּ⁠מַ֣יִם לָ֑חַץ וְ⁠לֹֽא־יִכָּנֵ֥ף עוֹד֙ מוֹרֶ֔י⁠ךָ וְ⁠הָי֥וּ עֵינֶ֖י⁠ךָ רֹא֥וֹת אֶת־מוֹרֶֽי⁠ךָ׃","wĕ⁠náţa֨n lá⁠ke֧m ʼàdòná֛⁠y le֥ẖem ẕá֖r ẇ⁠ma֣yim lá֑ẖaẕ wĕ⁠lòֽʼ-yiká̇né֥p ʻwòd֙ mwòre֔y⁠ká wĕ⁠háy֥ẇ ʻéyne֖y⁠ká ròʼ֥wòţ ʼeţ-mwòreֽy⁠ká׃"],[30,21,"וְ⁠אָזְנֶ֨י⁠ךָ֙ תִּשְׁמַ֣עְנָה דָבָ֔ר מֵֽ⁠אַחֲרֶ֖י⁠ךָ לֵ⁠אמֹ֑ר זֶ֤ה הַ⁠דֶּ֨רֶךְ֙ לְכ֣וּ ב֔⁠וֹ כִּ֥י תַאֲמִ֖ינוּ וְ⁠כִ֥י תַשְׂמְאִֽילוּ׃","wĕ⁠ʼázĕne֨y⁠ká֙ ţi̇şĕ̌ma֣ʻĕnáh dábá֔r méֽ⁠ʼaẖàre֖y⁠ká lé⁠ʼmò֑r ze֤h ha⁠dė֨rekĕ֙ lĕk֣ẇ b֔⁠wò ki֥̇y ţaʼàmi֖ynẇ wĕ⁠ki֥y ţaşĕ̂mĕʼiֽylẇ׃"],[30,22,"וְ⁠טִמֵּאתֶ֗ם אֶת־צִפּוּי֙ פְּסִילֵ֣י כַסְפֶּ֔⁠ךָ וְ⁠אֶת־אֲפֻדַּ֖ת מַסֵּכַ֣ת זְהָבֶ֑⁠ךָ תִּזְרֵ⁠ם֙ כְּמ֣וֹ דָוָ֔ה צֵ֖א תֹּ֥אמַר לֽ⁠וֹ׃","wĕ⁠timé̇ʼţe֗m ʼeţ-ẕiṗẇy֙ pĕ̇siylé֣y kasĕpė֔⁠ká wĕ⁠ʼeţ-ʼàpudȧ֖ţ masé̇ka֣ţ zĕhábe֑⁠ká ţi̇zĕré⁠m֙ kĕ̇m֣wò dáwá֔h ẕé֖ʼ ţò֥̇ʼmar lֽ⁠wò׃"],[30,23,"וְ⁠נָתַן֩ מְטַ֨ר זַרְעֲ⁠ךָ֜ אֲשֶׁר־תִּזְרַ֣ע אֶת־הָ⁠אֲדָמָ֗ה וְ⁠לֶ֨חֶם֙ תְּבוּאַ֣ת הָֽ⁠אֲדָמָ֔ה וְ⁠הָיָ֥ה דָשֵׁ֖ן וְ⁠שָׁמֵ֑ן יִרְעֶ֥ה מִקְנֶ֛י⁠ךָ בַּ⁠יּ֥וֹם הַ⁠ה֖וּא כַּ֥ר נִרְחָֽב׃","wĕ⁠náţan֩ mĕta֨r zarĕʻà⁠ká֜ ʼàşěr-ţi̇zĕra֣ʻ ʼeţ-há⁠ʼàdámá֗h wĕ⁠le֨ẖem֙ ţĕ̇bẇʼa֣ţ háֽ⁠ʼàdámá֔h wĕ⁠háyá֥h dáşé֖̌n wĕ⁠şá̌mé֑n yirĕʻe֥h miqĕne֛y⁠ká bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ kȧ֥r nirĕẖáֽb׃"],[30,24,"וְ⁠הָ⁠אֲלָפִ֣ים וְ⁠הָ⁠עֲיָרִ֗ים עֹֽבְדֵי֙ הָֽ⁠אֲדָמָ֔ה בְּלִ֥יל חָמִ֖יץ יֹאכֵ֑לוּ אֲשֶׁר־זֹרֶ֥ה בָ⁠רַ֖חַת וּ⁠בַ⁠מִּזְרֶֽה׃","wĕ⁠há⁠ʼàlápi֣ym wĕ⁠há⁠ʻàyári֗ym ʻòֽbĕdéy֙ háֽ⁠ʼàdámá֔h bĕ̇li֥yl ẖámi֖yẕ yòʼké֑lẇ ʼàşěr-zòre֥h bá⁠ra֖ẖaţ ẇ⁠ba⁠mi̇zĕreֽh׃"],[30,25,"וְ⁠הָיָ֣ה ׀ עַל־כָּל־הַ֣ר גָּבֹ֗הַ וְ⁠עַל֙ כָּל־גִּבְעָ֣ה נִשָּׂאָ֔ה פְּלָגִ֖ים יִבְלֵי־מָ֑יִם בְּ⁠יוֹם֙ הֶ֣רֶג רָ֔ב בִּ⁠נְפֹ֖ל מִגְדָּלִֽים׃","wĕ⁠háyá֣h ׀ ʻal-ká̇l-ha֣r gá̇bò֗ha wĕ⁠ʻal֙ ká̇l-gi̇bĕʻá֣h nişá̇̂ʼá֔h pĕ̇lági֖ym yibĕléy-má֑yim bĕ̇⁠ywòm֙ he֣reg rá֔b bi̇⁠nĕpò֖l migĕdá̇liֽym׃"],[30,26,"וְ⁠הָיָ֤ה אֽוֹר־הַ⁠לְּבָנָה֙ כְּ⁠א֣וֹר הַֽ⁠חַמָּ֔ה וְ⁠א֤וֹר הַֽ⁠חַמָּה֙ יִהְיֶ֣ה שִׁבְעָתַ֔יִם כְּ⁠א֖וֹר שִׁבְעַ֣ת הַ⁠יָּמִ֑ים בְּ⁠י֗וֹם חֲבֹ֤שׁ יְהוָה֙ אֶת־שֶׁ֣בֶר עַמּ֔⁠וֹ וּ⁠מַ֥חַץ מַכָּת֖⁠וֹ יִרְפָּֽא׃ס","wĕ⁠háyá֤h ʼֽwòr-ha⁠lĕ̇bánáh֙ kĕ̇⁠ʼ֣wòr haֽ⁠ẖamá̇֔h wĕ⁠ʼ֤wòr haֽ⁠ẖamá̇h֙ yihĕye֣h şǐbĕʻáţa֔yim kĕ̇⁠ʼ֖wòr şǐbĕʻa֣ţ ha⁠yá̇mi֑ym bĕ̇⁠y֗wòm ẖàbò֤ş̌ yĕhwáh֙ ʼeţ-şě֣ber ʻaṁ֔⁠wò ẇ⁠ma֥ẖaẕ maká̇ţ֖⁠wò yirĕpáֽ̇ʼ׃s"],[30,27,"הִנֵּ֤ה שֵׁם־יְהוָה֙ בָּ֣א מִ⁠מֶּרְחָ֔ק בֹּעֵ֣ר אַפּ֔⁠וֹ וְ⁠כֹ֖בֶד מַשָּׂאָ֑ה שְׂפָתָי⁠ו֙ מָ֣לְאוּ זַ֔עַם וּ⁠לְשׁוֹנ֖⁠וֹ כְּ⁠אֵ֥שׁ אֹכָֽלֶת׃","hiné֤̇h şé̌m-yĕhwáh֙ bá֣̇ʼ mi⁠mėrĕẖá֔q bò̇ʻé֣r ʼaṗ֔⁠wò wĕ⁠kò֖bed maşá̇̂ʼá֑h şĕ̂páţáy⁠w֙ má֣lĕʼẇ za֔ʻam ẇ⁠lĕş̌wòn֖⁠wò kĕ̇⁠ʼé֥ş̌ ʼòkáֽleţ׃"],[30,28,"וְ⁠רוּח֞⁠וֹ כְּ⁠נַ֤חַל שׁוֹטֵף֙ עַד־צַוָּ֣אר יֶֽחֱצֶ֔ה לַ⁠הֲנָפָ֥ה גוֹיִ֖ם בְּ⁠נָ֣פַת שָׁ֑וְא וְ⁠רֶ֣סֶן מַתְעֶ֔ה עַ֖ל לְחָיֵ֥י עַמִּֽים׃","wĕ⁠rẇẖ֞⁠wò kĕ̇⁠na֤ẖal ş̌wòtép֙ ʻad-ẕawá֣̇ʼr yeֽẖèẕe֔h la⁠hànápá֥h gwòyi֖m bĕ̇⁠ná֣paţ şá֑̌wĕʼ wĕ⁠re֣sen maţĕʻe֔h ʻa֖l lĕẖáyé֥y ʻamiֽ̇ym׃"],[30,29,"הַ⁠שִּׁיר֙ יִֽהְיֶ֣ה לָ⁠כֶ֔ם כְּ⁠לֵ֖יל הִתְקַדֶּשׁ־חָ֑ג וְ⁠שִׂמְחַ֣ת לֵבָ֗ב כַּֽ⁠הוֹלֵךְ֙ בֶּֽ⁠חָלִ֔יל לָ⁠ב֥וֹא בְ⁠הַר־יְהוָ֖ה אֶל־צ֥וּר יִשְׂרָאֵֽל׃","ha⁠şi̇̌yr֙ yiֽhĕye֣h lá⁠ke֔m kĕ̇⁠lé֖yl hiţĕqadėş̌-ẖá֑g wĕ⁠şîmĕẖa֣ţ lébá֗b kȧֽ⁠hwòlékĕ֙ bėֽ⁠ẖáli֔yl lá⁠b֥wòʼ bĕ⁠har-yĕhwá֖h ʼel-ẕ֥ẇr yişĕ̂ráʼéֽl׃"],[30,30,"וְ⁠הִשְׁמִ֨יעַ יְהוָ֜ה אֶת־ה֣וֹד קוֹל֗⁠וֹ וְ⁠נַ֤חַת זְרוֹע⁠וֹ֙ יַרְאֶ֔ה בְּ⁠זַ֣עַף אַ֔ף וְ⁠לַ֖הַב אֵ֣שׁ אוֹכֵלָ֑ה נֶ֥פֶץ וָ⁠זֶ֖רֶם וְ⁠אֶ֥בֶן בָּרָֽד׃","wĕ⁠hişĕ̌mi֨yʻa yĕhwá֜h ʼeţ-h֣wòd qwòl֗⁠wò wĕ⁠na֤ẖaţ zĕrwòʻ⁠wò֙ yarĕʼe֔h bĕ̇⁠za֣ʻap ʼa֔p wĕ⁠la֖hab ʼé֣ş̌ ʼwòkélá֑h ne֥peẕ wá⁠ze֖rem wĕ⁠ʼe֥ben bá̇ráֽd׃"],[30,31,"כִּֽי־מִ⁠קּ֥וֹל יְהוָ֖ה יֵחַ֣ת אַשּׁ֑וּר בַּ⁠שֵּׁ֖בֶט יַכֶּֽה׃","kiֽ̇y-mi⁠q֥̇wòl yĕhwá֖h yéẖa֣ţ ʼaş֑̇̌ẇr bȧ⁠şé֖̇̌bet yakėֽh׃"],[30,32,"וְ⁠הָיָ֗ה כֹּ֤ל מַֽעֲבַר֙ מַטֵּ֣ה מֽוּסָדָ֔ה אֲשֶׁ֨ר יָנִ֤יחַ יְהוָה֙ עָלָ֔י⁠ו בְּ⁠תֻפִּ֖ים וּ⁠בְ⁠כִנֹּר֑וֹת וּ⁠בְ⁠מִלְחֲמ֥וֹת תְּנוּפָ֖ה נִלְחַם־ב⁠ה׃","wĕ⁠háyá֗h kò֤̇l maֽʻàbar֙ maté֣̇h mֽẇsádá֔h ʼàşě֨r yáni֤yẖa yĕhwáh֙ ʻálá֔y⁠w bĕ̇⁠ţupi֖̇ym ẇ⁠bĕ⁠kinò̇r֑wòţ ẇ⁠bĕ⁠milĕẖàm֥wòţ ţĕ̇nẇpá֖h nilĕẖam-b⁠h׃"],[30,33,"כִּֽי־עָר֤וּךְ מֵֽ⁠אֶתְמוּל֙ תָּפְתֶּ֔ה גַּם־הוא לַ⁠מֶּ֥לֶךְ הוּכָ֖ן הֶעְמִ֣יק הִרְחִ֑ב מְדֻרָתָ֗⁠הּ אֵ֤שׁ וְ⁠עֵצִים֙ הַרְבֵּ֔ה נִשְׁמַ֤ת יְהוָה֙ כְּ⁠נַ֣חַל גָּפְרִ֔ית בֹּעֲרָ֖ה בָּֽ⁠הּ׃ס","kiֽ̇y-ʻár֤ẇkĕ méֽ⁠ʼeţĕmẇl֙ ţá̇pĕţė֔h gȧm-hwʼ la⁠mė֥lekĕ hẇká֖n heʻĕmi֣yq hirĕẖi֑b mĕduráţá֗⁠ḣ ʼé֤ş̌ wĕ⁠ʻéẕiym֙ harĕbé̇֔h nişĕ̌ma֤ţ yĕhwáh֙ kĕ̇⁠na֣ẖal gá̇pĕri֔yţ bò̇ʻàrá֖h báֽ̇⁠ḣ׃s"],[31,1,"ה֣וֹי הַ⁠יֹּרְדִ֤ים מִצְרַ֨יִם֙ לְ⁠עֶזְרָ֔ה עַל־סוּסִ֖ים יִשָּׁעֵ֑נוּ וַ⁠יִּבְטְח֨וּ עַל־רֶ֜כֶב כִּ֣י רָ֗ב וְ⁠עַ֤ל פָּֽרָשִׁים֙ כִּֽי־עָצְמ֣וּ מְאֹ֔ד וְ⁠לֹ֤א שָׁעוּ֙ עַל־קְד֣וֹשׁ יִשְׂרָאֵ֔ל וְ⁠אֶת־יְהוָ֖ה לֹ֥א דָרָֽשׁוּ׃","h֣wòy ha⁠yò̇rĕdi֤ym miẕĕra֨yim֙ lĕ⁠ʻezĕrá֔h ʻal-sẇsi֖ym yişá̇̌ʻé֑nẇ wa⁠yi̇bĕtĕẖ֨ẇ ʻal-re֜keb ki֣̇y rá֗b wĕ⁠ʻa֤l páֽ̇ráşǐym֙ kiֽ̇y-ʻáẕĕm֣ẇ mĕʼò֔d wĕ⁠lò֤ʼ şá̌ʻẇ֙ ʻal-qĕd֣wòş̌ yişĕ̂ráʼé֔l wĕ⁠ʼeţ-yĕhwá֖h lò֥ʼ dáráֽş̌ẇ׃"],[31,2,"וְ⁠גַם־ה֤וּא חָכָם֙ וַ⁠יָּ֣בֵא רָ֔ע וְ⁠אֶת־דְּבָרָ֖י⁠ו לֹ֣א הֵסִ֑יר וְ⁠קָם֙ עַל־בֵּ֣ית מְרֵעִ֔ים וְ⁠עַל־עֶזְרַ֖ת פֹּ֥עֲלֵי אָֽוֶן׃","wĕ⁠gam-h֤ẇʼ ẖákám֙ wa⁠yá֣̇béʼ rá֔ʻ wĕ⁠ʼeţ-dĕ̇bárá֖y⁠w lò֣ʼ hési֑yr wĕ⁠qám֙ ʻal-bé֣̇yţ mĕréʻi֔ym wĕ⁠ʻal-ʻezĕra֖ţ pò֥̇ʻàléy ʼáֽwen׃"],[31,3,"וּ⁠מִצְרַ֤יִם אָדָם֙ וְֽ⁠לֹא־אֵ֔ל וְ⁠סוּסֵי⁠הֶ֥ם בָּשָׂ֖ר וְ⁠לֹא־ר֑וּחַ וַֽ⁠יהוָ֞ה יַטֶּ֣ה יָד֗⁠וֹ וְ⁠כָשַׁ֤ל עוֹזֵר֙ וְ⁠נָפַ֣ל עָזֻ֔ר וְ⁠יַחְדָּ֖ו כֻּלָּ֥⁠ם יִכְלָיֽוּ⁠ן׃ס","ẇ⁠miẕĕra֤yim ʼádám֙ wĕֽ⁠lòʼ-ʼé֔l wĕ⁠sẇséy⁠he֥m bá̇şá֖̂r wĕ⁠lòʼ-r֑ẇẖa waֽ⁠yhwá֞h yatė֣h yád֗⁠wò wĕ⁠káşǎ֤l ʻwòzér֙ wĕ⁠nápa֣l ʻázu֔r wĕ⁠yaẖĕdá֖̇w ku̇lá֥̇⁠m yikĕláyֽẇ⁠n׃s"],[31,4,"כִּ֣י כֹ֣ה אָֽמַר־יְהוָ֣ה ׀ אֵלַ֡⁠י כַּ⁠אֲשֶׁ֣ר יֶהְגֶּה֩ הָ⁠אַרְיֵ֨ה וְ⁠הַ⁠כְּפִ֜יר עַל־טַרְפּ֗⁠וֹ אֲשֶׁ֨ר יִקָּרֵ֤א עָלָי⁠ו֙ מְלֹ֣א רֹעִ֔ים מִ⁠קּוֹלָ⁠ם֙ לֹ֣א יֵחָ֔ת וּ⁠מֵֽ⁠הֲמוֹנָ֖⁠ם לֹ֣א יַֽעֲנֶ֑ה כֵּ֗ן יֵרֵד֙ יְהוָ֣ה צְבָא֔וֹת לִ⁠צְבֹּ֥א עַל־הַר־צִיּ֖וֹן וְ⁠עַל־גִּבְעָתָֽ⁠הּ׃","ki֣̇y kò֣h ʼáֽmar-yĕhwá֣h ׀ ʼéla֡⁠y kȧ⁠ʼàşě֣r yehĕgėh֩ há⁠ʼarĕyé֨h wĕ⁠ha⁠kĕ̇pi֜yr ʻal-tarĕṗ֗⁠wò ʼàşě֨r yiqá̇ré֤ʼ ʻáláy⁠w֙ mĕlò֣ʼ ròʻi֔ym mi⁠q̇wòlá⁠m֙ lò֣ʼ yéẖá֔ţ ẇ⁠méֽ⁠hàmwòná֖⁠m lò֣ʼ yaֽʻàne֑h ké̇֗n yéréd֙ yĕhwá֣h ẕĕbáʼ֔wòţ li⁠ẕĕbò֥̇ʼ ʻal-har-ẕiẏ֖wòn wĕ⁠ʻal-gi̇bĕʻáţáֽ⁠ḣ׃"],[31,5,"כְּ⁠צִפֳּרִ֣ים עָפ֔וֹת כֵּ֗ן יָגֵ֛ן יְהוָ֥ה צְבָא֖וֹת עַל־יְרֽוּשָׁלִָ֑ם גָּנ֥וֹן וְ⁠הִצִּ֖יל פָּסֹ֥חַ וְ⁠הִמְלִֽיט׃","kĕ̇⁠ẕipȯri֣ym ʻáp֔wòţ ké̇֗n yágé֛n yĕhwá֥h ẕĕbáʼ֖wòţ ʻal-yĕrֽẇşá̌liá֑m gá̇n֥wòn wĕ⁠hiẕi֖̇yl pá̇sò֥ẖa wĕ⁠himĕliֽyt׃"],[31,6,"שׁ֗וּבוּ לַ⁠אֲשֶׁ֛ר הֶעְמִ֥יקוּ סָרָ֖ה בְּנֵ֥י יִשְׂרָאֵֽל׃","ş̌֗ẇbẇ la⁠ʼàşě֛r heʻĕmi֥yqẇ sárá֖h bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[31,7,"כִּ֚י בַּ⁠יּ֣וֹם הַ⁠ה֔וּא יִמְאָס֗וּ⁠ן אִ֚ישׁ אֱלִילֵ֣י כַסְפּ֔⁠וֹ וֶ⁠אֱלִילֵ֖י זְהָב֑⁠וֹ אֲשֶׁ֨ר עָשׂ֥וּ לָ⁠כֶ֛ם יְדֵי⁠כֶ֖ם חֵֽטְא׃","ki֚̇y bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ yimĕʼás֗ẇ⁠n ʼi֚yş̌ ʼèliylé֣y kasĕṗ֔⁠wò we⁠ʼèliylé֖y zĕháb֑⁠wò ʼàşě֨r ʻáş֥̂ẇ lá⁠ke֛m yĕdéy⁠ke֖m ẖéֽtĕʼ׃"],[31,8,"וְ⁠נָפַ֤ל אַשּׁוּר֙ בְּ⁠חֶ֣רֶב לֹא־אִ֔ישׁ וְ⁠חֶ֥רֶב לֹֽא־אָדָ֖ם תֹּֽאכֲלֶ֑⁠נּוּ וְ⁠נָ֥ס ל⁠וֹ֙ מִ⁠פְּנֵי־חֶ֔רֶב וּ⁠בַחוּרָ֖י⁠ו לָ⁠מַ֥ס יִהְיֽוּ׃","wĕ⁠nápa֤l ʼaş̇̌ẇr֙ bĕ̇⁠ẖe֣reb lòʼ-ʼi֔yş̌ wĕ⁠ẖe֥reb lòֽʼ-ʼádá֖m ţòֽ̇ʼkàle֑⁠ṅẇ wĕ⁠ná֥s l⁠wò֙ mi⁠pĕ̇néy-ẖe֔reb ẇ⁠baẖẇrá֖y⁠w lá⁠ma֥s yihĕyֽẇ׃"],[31,9,"וְ⁠סַלְע⁠וֹ֙ מִ⁠מָּג֣וֹר יַֽעֲב֔וֹר וְ⁠חַתּ֥וּ מִ⁠נֵּ֖ס שָׂרָ֑י⁠ו נְאֻם־יְהוָ֗ה אֲשֶׁר־א֥וּר ל⁠וֹ֙ בְּ⁠צִיּ֔וֹן וְ⁠תַנּ֥וּר ל֖⁠וֹ בִּ⁠ירוּשָׁלִָֽם׃ס","wĕ⁠salĕʻ⁠wò֙ mi⁠má̇g֣wòr yaֽʻàb֔wòr wĕ⁠ẖaţ֥̇ẇ mi⁠né֖̇s şá̂rá֑y⁠w nĕʼum-yĕhwá֗h ʼàşěr-ʼ֥ẇr l⁠wò֙ bĕ̇⁠ẕiẏ֔wòn wĕ⁠ţaṅ֥ẇr l֖⁠wò bi̇⁠yrẇşá̌liáֽm׃s"],[32,1,"הֵ֥ן לְ⁠צֶ֖דֶק יִמְלָךְ־מֶ֑לֶךְ וּ⁠לְ⁠שָׂרִ֖ים לְ⁠מִשְׁפָּ֥ט יָשֹֽׂרוּ׃","hé֥n lĕ⁠ẕe֖deq yimĕlákĕ-me֑lekĕ ẇ⁠lĕ⁠şá̂ri֖ym lĕ⁠mişĕ̌pá֥̇t yáşòֽ̂rẇ׃"],[32,2,"וְ⁠הָיָה־אִ֥ישׁ כְּ⁠מַֽחֲבֵא־ר֖וּחַ וְ⁠סֵ֣תֶר זָ֑רֶם כְּ⁠פַלְגֵי־מַ֣יִם בְּ⁠צָי֔וֹן כְּ⁠צֵ֥ל סֶֽלַע־כָּבֵ֖ד בְּ⁠אֶ֥רֶץ עֲיֵפָֽה׃","wĕ⁠háyáh-ʼi֥yş̌ kĕ̇⁠maֽẖàbéʼ-r֖ẇẖa wĕ⁠sé֣ţer zá֑rem kĕ̇⁠palĕgéy-ma֣yim bĕ̇⁠ẕáy֔wòn kĕ̇⁠ẕé֥l seֽlaʻ-ká̇bé֖d bĕ̇⁠ʼe֥reẕ ʻàyépáֽh׃"],[32,3,"וְ⁠לֹ֥א תִשְׁעֶ֖ינָה עֵינֵ֣י רֹאִ֑ים וְ⁠אָזְנֵ֥י שֹׁמְעִ֖ים תִּקְשַֽׁבְנָה׃","wĕ⁠lò֥ʼ ţişĕ̌ʻe֖ynáh ʻéyné֣y ròʼi֑ym wĕ⁠ʼázĕné֥y şò̌mĕʻi֖ym ţi̇qĕşǎֽbĕnáh׃"],[32,4,"וּ⁠לְבַ֥ב נִמְהָרִ֖ים יָבִ֣ין לָ⁠דָ֑עַת וּ⁠לְשׁ֣וֹן עִלְּגִ֔ים תְּמַהֵ֖ר לְ⁠דַבֵּ֥ר צָחֽוֹת׃","ẇ⁠lĕba֥b nimĕhári֖ym yábi֣yn lá⁠dá֑ʻaţ ẇ⁠lĕş֣̌wòn ʻilĕ̇gi֔ym ţĕ̇mahé֖r lĕ⁠dabé֥̇r ẕáẖֽwòţ׃"],[32,5,"לֹֽא־יִקָּרֵ֥א ע֛וֹד לְ⁠נָבָ֖ל נָדִ֑יב וּ⁠לְ⁠כִילַ֕י לֹ֥א יֵֽאָמֵ֖ר שֽׁוֹעַ׃","lòֽʼ-yiqá̇ré֥ʼ ʻ֛wòd lĕ⁠nábá֖l nádi֑yb ẇ⁠lĕ⁠kiyla֕y lò֥ʼ yéֽʼámé֖r şֽ̌wòʻa׃"],[32,6,"כִּ֤י נָבָל֙ נְבָלָ֣ה יְדַבֵּ֔ר וְ⁠לִבּ֖⁠וֹ יַעֲשֶׂה־אָ֑וֶן לַ⁠עֲשׂ֣וֹת חֹ֗נֶף וּ⁠לְ⁠דַבֵּ֤ר אֶל־יְהוָה֙ תּוֹעָ֔ה לְ⁠הָרִיק֙ נֶ֣פֶשׁ רָעֵ֔ב וּ⁠מַשְׁקֶ֥ה צָמֵ֖א יַחְסִֽיר׃","ki֤̇y nábál֙ nĕbálá֣h yĕdabé̇֔r wĕ⁠liḃ֖⁠wò yaʻàşêh-ʼá֑wen la⁠ʻàş֣̂wòţ ẖò֗nep ẇ⁠lĕ⁠dabé֤̇r ʼel-yĕhwáh֙ ţ̇wòʻá֔h lĕ⁠háriyq֙ ne֣peş̌ ráʻé֔b ẇ⁠maşĕ̌qe֥h ẕámé֖ʼ yaẖĕsiֽyr׃"],[32,7,"וְ⁠כֵלַ֖י כֵּלָ֣י⁠ו רָעִ֑ים ה֚וּא זִמּ֣וֹת יָעָ֔ץ לְ⁠חַבֵּ֤ל ענוים בְּ⁠אִמְרֵי־שֶׁ֔קֶר וּ⁠בְ⁠דַבֵּ֥ר אֶבְי֖וֹן מִשְׁפָּֽט׃","wĕ⁠kéla֖y ké̇lá֣y⁠w ráʻi֑ym h֚ẇʼ ziṁ֣wòţ yáʻá֔ẕ lĕ⁠ẖabé֤̇l ʻnwym bĕ̇⁠ʼimĕréy-şě֔qer ẇ⁠bĕ⁠dabé֥̇r ʼebĕy֖wòn mişĕ̌páֽ̇t׃"],[32,8,"וְ⁠נָדִ֖יב נְדִיב֣וֹת יָעָ֑ץ וְ⁠ה֖וּא עַל־נְדִיב֥וֹת יָקֽוּם׃פ","wĕ⁠nádi֖yb nĕdiyb֣wòţ yáʻá֑ẕ wĕ⁠h֖ẇʼ ʻal-nĕdiyb֥wòţ yáqֽẇm׃p"],[32,9,"נָשִׁים֙ שַֽׁאֲנַנּ֔וֹת קֹ֖מְנָה שְׁמַ֣עְנָה קוֹלִ֑⁠י בָּנוֹת֙ בֹּֽטח֔וֹת הַאְזֵ֖נָּה אִמְרָתִֽ⁠י׃","náşǐym֙ şǎֽʼànaṅ֔wòţ qò֖mĕnáh şĕ̌ma֣ʻĕnáh qwòli֑⁠y bá̇nwòţ֙ bòֽ̇tẖ֔wòţ haʼĕzé֖ná̇h ʼimĕráţiֽ⁠y׃"],[32,10,"יָמִים֙ עַל־שָׁנָ֔ה תִּרְגַּ֖זְנָה בֹּֽטְח֑וֹת כִּ֚י כָּלָ֣ה בָצִ֔יר אֹ֖סֶף בְּלִ֥י יָבֽוֹא׃","yámiym֙ ʻal-şá̌ná֔h ţi̇rĕgȧ֖zĕnáh bòֽ̇tĕẖ֑wòţ ki֚̇y ká̇lá֣h báẕi֔yr ʼò֖sep bĕ̇li֥y yábֽwòʼ׃"],[32,11,"חִרְדוּ֙ שַֽׁאֲנַנּ֔וֹת רְגָ֖זָה בֹּֽטְח֑וֹת פְּשֹׁ֣טָֽה וְ⁠עֹ֔רָה וַ⁠חֲג֖וֹרָה עַל־חֲלָצָֽיִם׃","ẖirĕdẇ֙ şǎֽʼànaṅ֔wòţ rĕgá֖záh bòֽ̇tĕẖ֑wòţ pĕ̇şò֣̌táֽh wĕ⁠ʻò֔ráh wa⁠ẖàg֖wòráh ʻal-ẖàláẕáֽyim׃"],[32,12,"עַל־שָׁדַ֖יִם סֹֽפְדִ֑ים עַל־שְׂדֵי־חֶ֕מֶד עַל־גֶּ֖פֶן פֹּרִיָּֽה׃","ʻal-şá̌da֖yim sòֽpĕdi֑ym ʻal-şĕ̂déy-ẖe֕med ʻal-gė֖pen pò̇riyáֽ̇h׃"],[32,13,"עַ֚ל אַדְמַ֣ת עַמִּ֔⁠י ק֥וֹץ שָׁמִ֖יר תַּֽעֲלֶ֑ה כִּ֚י עַל־כָּל־בָּתֵּ֣י מָשׂ֔וֹשׂ קִרְיָ֖ה עַלִּיזָֽה׃","ʻa֚l ʼadĕma֣ţ ʻami̇֔⁠y q֥wòẕ şá̌mi֖yr ţȧֽʻàle֑h ki֚̇y ʻal-ká̇l-bá̇ţé֣̇y máş̂֔wòş̂ qirĕyá֖h ʻali̇yzáֽh׃"],[32,14,"כִּֽי־אַרְמ֣וֹן נֻטָּ֔שׁ הֲמ֥וֹן עִ֖יר עֻזָּ֑ב עֹ֣פֶל וָ⁠בַ֜חַן הָיָ֨ה בְעַ֤ד מְעָרוֹת֙ עַד־עוֹלָ֔ם מְשׂ֥וֹשׂ פְּרָאִ֖ים מִרְעֵ֥ה עֲדָרִֽים׃","kiֽ̇y-ʼarĕm֣wòn nutá̇֔ş̌ hàm֥wòn ʻi֖yr ʻuzá֑̇b ʻò֣pel wá⁠ba֜ẖan háyá֨h bĕʻa֤d mĕʻárwòţ֙ ʻad-ʻwòlá֔m mĕş֥̂wòş̂ pĕ̇ráʼi֖ym mirĕʻé֥h ʻàdáriֽym׃"],[32,15,"עַד־יֵ֨עָרֶ֥ה עָלֵ֛י⁠נוּ ר֖וּחַ מִ⁠מָּר֑וֹם וְ⁠הָיָ֤ה מִדְבָּר֙ לַ⁠כַּרְמֶ֔ל ו⁠כרמל לַ⁠יַּ֥עַר יֵחָשֵֽׁב׃","ʻad-yé֨ʻáre֥h ʻálé֛y⁠nẇ r֖ẇẖa mi⁠má̇r֑wòm wĕ⁠háyá֤h midĕbá̇r֙ la⁠kȧrĕme֔l w⁠krml la⁠yȧ֥ʻar yéẖáşéֽ̌b׃"],[32,16,"וְ⁠שָׁכַ֥ן בַּ⁠מִּדְבָּ֖ר מִשְׁפָּ֑ט וּ⁠צְדָקָ֖ה בַּ⁠כַּרְמֶ֥ל תֵּשֵֽׁב׃","wĕ⁠şá̌ka֥n bȧ⁠mi̇dĕbá֖̇r mişĕ̌pá֑̇t ẇ⁠ẕĕdáqá֖h bȧ⁠kȧrĕme֥l ţé̇şéֽ̌b׃"],[32,17,"וְ⁠הָיָ֛ה מַעֲשֵׂ֥ה הַ⁠צְּדָקָ֖ה שָׁל֑וֹם וַֽ⁠עֲבֹדַת֙ הַ⁠צְּדָקָ֔ה הַשְׁקֵ֥ט וָ⁠בֶ֖טַח עַד־עוֹלָֽם׃","wĕ⁠háyá֛h maʻàşé֥̂h ha⁠ẕĕ̇dáqá֖h şá̌l֑wòm waֽ⁠ʻàbòdaţ֙ ha⁠ẕĕ̇dáqá֔h haşĕ̌qé֥t wá⁠be֖taẖ ʻad-ʻwòláֽm׃"],[32,18,"וְ⁠יָשַׁ֥ב עַמִּ֖⁠י בִּ⁠נְוֵ֣ה שָׁל֑וֹם וּֽ⁠בְ⁠מִשְׁכְּנוֹת֙ מִבְטַחִ֔ים וּ⁠בִ⁠מְנוּחֹ֖ת שַׁאֲנַנּֽוֹת׃","wĕ⁠yáşǎ֥b ʻami֖̇⁠y bi̇⁠nĕwé֣h şá̌l֑wòm ẇֽ⁠bĕ⁠mişĕ̌kĕ̇nwòţ֙ mibĕtaẖi֔ym ẇ⁠bi⁠mĕnẇẖò֖ţ şǎʼànaṅֽwòţ׃"],[32,19,"וּ⁠בָרַ֖ד בְּ⁠רֶ֣דֶת הַ⁠יָּ֑עַר וּ⁠בַ⁠שִּׁפְלָ֖ה תִּשְׁפַּ֥ל הָ⁠עִֽיר׃","ẇ⁠bára֖d bĕ̇⁠re֣deţ ha⁠yá֑̇ʻar ẇ⁠ba⁠şi̇̌pĕlá֖h ţi̇şĕ̌pȧ֥l há⁠ʻiֽyr׃"],[32,20,"אַשְׁרֵי⁠כֶ֕ם זֹרְעֵ֖י עַל־כָּל־מָ֑יִם מְשַׁלְּחֵ֥י רֶֽגֶל־הַ⁠שּׁ֖וֹר וְ⁠הַ⁠חֲמֽוֹר׃ס","ʼaşĕ̌réy⁠ke֕m zòrĕʻé֖y ʻal-ká̇l-má֑yim mĕşǎlĕ̇ẖé֥y reֽgel-ha⁠ş֖̇̌wòr wĕ⁠ha⁠ẖàmֽwòr׃s"],[33,1,"ה֣וֹי שׁוֹדֵ֗ד וְ⁠אַתָּה֙ לֹ֣א שָׁד֔וּד וּ⁠בוֹגֵ֖ד וְ⁠לֹא־בָ֣גְדוּ ב֑⁠וֹ כַּ⁠הֲתִֽמְ⁠ךָ֤ שׁוֹדֵד֙ תּוּשַּׁ֔ד כַּ⁠נְּלֹתְ⁠ךָ֥ לִ⁠בְגֹּ֖ד יִבְגְּדוּ־בָֽ⁠ךְ׃ס","h֣wòy ş̌wòdé֗d wĕ⁠ʼaţá̇h֙ lò֣ʼ şá̌d֔ẇd ẇ⁠bwògé֖d wĕ⁠lòʼ-bá֣gĕdẇ b֑⁠wò kȧ⁠hàţiֽmĕ⁠ká֤ ş̌wòdéd֙ ţ̇ẇşȧ̌֔d kȧ⁠nĕ̇lòţĕ⁠ká֥ li⁠bĕgò֖̇d yibĕgĕ̇dẇ-báֽ⁠kĕ׃s"],[33,2,"יְהוָ֥ה חָנֵּ֖⁠נוּ לְ⁠ךָ֣ קִוִּ֑ינוּ הֱיֵ֤ה זְרֹעָ⁠ם֙ לַ⁠בְּקָרִ֔ים אַף־יְשׁוּעָתֵ֖⁠נוּ בְּ⁠עֵ֥ת צָרָֽה׃","yĕhwá֥h ẖáné֖̇⁠nẇ lĕ⁠ká֣ qiwi֑̇ynẇ hèyé֤h zĕròʻá⁠m֙ la⁠bĕ̇qári֔ym ʼap-yĕş̌ẇʻáţé֖⁠nẇ bĕ̇⁠ʻé֥ţ ẕáráֽh׃"],[33,3,"מִ⁠קּ֣וֹל הָמ֔וֹן נָדְד֖וּ עַמִּ֑ים מֵ⁠ר֣וֹמְמֻתֶ֔⁠ךָ נָפְצ֖וּ גּוֹיִֽם׃","mi⁠q֣̇wòl hám֔wòn nádĕd֖ẇ ʻami֑̇ym mé⁠r֣wòmĕmuţe֔⁠ká nápĕẕ֖ẇ ġwòyiֽm׃"],[33,4,"וְ⁠אֻסַּ֣ף שְׁלַלְ⁠כֶ֔ם אֹ֖סֶף הֶֽ⁠חָסִ֑יל כְּ⁠מַשַּׁ֥ק גֵּבִ֖ים שׁוֹקֵ֥ק בּֽ⁠וֹ׃","wĕ⁠ʼusȧ֣p şĕ̌lalĕ⁠ke֔m ʼò֖sep heֽ⁠ẖási֑yl kĕ̇⁠maşȧ֥̌q gé̇bi֖ym ş̌wòqé֥q ḃֽ⁠wò׃"],[33,5,"נִשְׂגָּ֣ב יְהוָ֔ה כִּ֥י שֹׁכֵ֖ן מָר֑וֹם מִלֵּ֣א צִיּ֔וֹן מִשְׁפָּ֖ט וּ⁠צְדָקָֽה׃","nişĕ̂gá֣̇b yĕhwá֔h ki֥̇y şò̌ké֖n már֑wòm milé֣̇ʼ ẕiẏ֔wòn mişĕ̌pá֖̇t ẇ⁠ẕĕdáqáֽh׃"],[33,6,"וְ⁠הָיָה֙ אֱמוּנַ֣ת עִתֶּ֔י⁠ךָ חֹ֥סֶן יְשׁוּעֹ֖ת חָכְמַ֣ת וָ⁠דָ֑עַת יִרְאַ֥ת יְהוָ֖ה הִ֥יא אוֹצָרֽ⁠וֹ׃ס","wĕ⁠háyáh֙ ʼèmẇna֣ţ ʻiţė֔y⁠ká ẖò֥sen yĕş̌ẇʻò֖ţ ẖákĕma֣ţ wá⁠dá֑ʻaţ yirĕʼa֥ţ yĕhwá֖h hi֥yʼ ʼwòẕárֽ⁠wò׃s"],[33,7,"הֵ֚ן אֶרְאֶלָּ֔ם צָעֲק֖וּ חֻ֑צָ⁠ה מַלְאֲכֵ֣י שָׁל֔וֹם מַ֖ר יִבְכָּיֽוּ⁠ן׃","hé֚n ʼerĕʼelá̇֔m ẕáʻàq֖ẇ ẖu֑ẕá⁠h malĕʼàké֣y şá̌l֔wòm ma֖r yibĕká̇yֽẇ⁠n׃"],[33,8,"נָשַׁ֣מּוּ מְסִלּ֔וֹת שָׁבַ֖ת עֹבֵ֣ר אֹ֑רַח הֵפֵ֤ר בְּרִית֙ מָאַ֣ס עָרִ֔ים לֹ֥א חָשַׁ֖ב אֱנֽוֹשׁ׃","náşǎ֣ṁẇ mĕsil̇֔wòţ şá̌ba֖ţ ʻòbé֣r ʼò֑raẖ hépé֤r bĕ̇riyţ֙ máʼa֣s ʻári֔ym lò֥ʼ ẖáşǎ֖b ʼènֽwòş̌׃"],[33,9,"אָבַ֤ל אֻמְלְלָה֙ אָ֔רֶץ הֶחְפִּ֥יר לְבָנ֖וֹן קָמַ֑ל הָיָ֤ה הַ⁠שָּׁרוֹן֙ כָּֽ⁠עֲרָבָ֔ה וְ⁠נֹעֵ֥ר בָּשָׁ֖ן וְ⁠כַרְמֶֽל׃","ʼába֤l ʼumĕlĕláh֙ ʼá֔reẕ heẖĕpi֥̇yr lĕbán֖wòn qáma֑l háyá֤h ha⁠şá̇̌rwòn֙ káֽ̇⁠ʻàrábá֔h wĕ⁠nòʻé֥r bá̇şá֖̌n wĕ⁠karĕmeֽl׃"],[33,10,"עַתָּ֥ה אָק֖וּם יֹאמַ֣ר יְהוָ֑ה עַתָּה֙ אֵֽרוֹמָ֔ם עַתָּ֖ה אֶנָּשֵֽׂא׃","ʻaţá֥̇h ʼáq֖ẇm yòʼma֣r yĕhwá֑h ʻaţá̇h֙ ʼéֽrwòmá֔m ʻaţá֖̇h ʼená̇şéֽ̂ʼ׃"],[33,11,"תַּהֲר֥וּ חֲשַׁ֖שׁ תֵּ֣לְדוּ קַ֑שׁ רוּחֲ⁠כֶ֕ם אֵ֖שׁ תֹּאכַלְ⁠כֶֽם׃","ţȧhàr֥ẇ ẖàşǎ֖ş̌ ţé֣̇lĕdẇ qa֑ş̌ rẇẖà⁠ke֕m ʼé֖ş̌ ţò̇ʼkalĕ⁠keֽm׃"],[33,12,"וְ⁠הָי֥וּ עַמִּ֖ים מִשְׂרְפ֣וֹת שִׂ֑יד קוֹצִ֥ים כְּסוּחִ֖ים בָּ⁠אֵ֥שׁ יִצַּֽתּוּ׃ס","wĕ⁠háy֥ẇ ʻami֖̇ym mişĕ̂rĕp֣wòţ şî֑yd qwòẕi֥ym kĕ̇sẇẖi֖ym bá̇⁠ʼé֥ş̌ yiẕȧֽţ̇ẇ׃s"],[33,13,"שִׁמְע֥וּ רְחוֹקִ֖ים אֲשֶׁ֣ר עָשִׂ֑יתִי וּ⁠דְע֥וּ קְרוֹבִ֖ים גְּבֻרָתִֽ⁠י׃","şǐmĕʻ֥ẇ rĕẖwòqi֖ym ʼàşě֣r ʻáşî֑yţiy ẇ⁠dĕʻ֥ẇ qĕrwòbi֖ym gĕ̇buráţiֽ⁠y׃"],[33,14,"פָּחֲד֤וּ בְ⁠צִיּוֹן֙ חַטָּאִ֔ים אָחֲזָ֥ה רְעָדָ֖ה חֲנֵפִ֑ים מִ֣י ׀ יָג֣וּר לָ֗⁠נוּ אֵ֚שׁ אוֹכֵלָ֔ה מִי־יָג֥וּר לָ֖⁠נוּ מוֹקְדֵ֥י עוֹלָֽם׃","pá̇ẖàd֤ẇ bĕ⁠ẕiẏwòn֙ ẖatá̇ʼi֔ym ʼáẖàzá֥h rĕʻádá֖h ẖànépi֑ym mi֣y ׀ yág֣ẇr lá֗⁠nẇ ʼé֚ş̌ ʼwòkélá֔h miy-yág֥ẇr lá֖⁠nẇ mwòqĕdé֥y ʻwòláֽm׃"],[33,15,"הֹלֵ֣ךְ צְדָק֔וֹת וְ⁠דֹבֵ֖ר מֵֽישָׁרִ֑ים מֹאֵ֞ס בְּ⁠בֶ֣צַע מַעֲשַׁקּ֗וֹת נֹעֵ֤ר כַּפָּי⁠ו֙ מִ⁠תְּמֹ֣ךְ בַּ⁠שֹּׁ֔חַד אֹטֵ֤ם אָזְנ⁠וֹ֙ מִ⁠שְּׁמֹ֣עַ דָּמִ֔ים וְ⁠עֹצֵ֥ם עֵינָ֖י⁠ו מֵ⁠רְא֥וֹת בְּ⁠רָֽע׃","hòlé֣kĕ ẕĕdáq֔wòţ wĕ⁠dòbé֖r méֽyşá̌ri֑ym mòʼé֞s bĕ̇⁠be֣ẕaʻ maʻàşǎq̇֗wòţ nòʻé֤r kȧpá̇y⁠w֙ mi⁠ţĕ̇mò֣kĕ bȧ⁠şò̇̌֔ẖad ʼòté֤m ʼázĕn⁠wò֙ mi⁠şĕ̇̌mò֣ʻa dá̇mi֔ym wĕ⁠ʻòẕé֥m ʻéyná֖y⁠w mé⁠rĕʼ֥wòţ bĕ̇⁠rֽáʻ׃"],[33,16,"ה֚וּא מְרוֹמִ֣ים יִשְׁכֹּ֔ן מְצָד֥וֹת סְלָעִ֖ים מִשְׂגַּבּ֑⁠וֹ לַחְמ֣⁠וֹ נִתָּ֔ן מֵימָ֖י⁠ו נֶאֱמָנִֽים׃","h֚ẇʼ mĕrwòmi֣ym yişĕ̌kò̇֔n mĕẕád֥wòţ sĕláʻi֖ym mişĕ̂gȧḃ֑⁠wò laẖĕm֣⁠wò niţá̇֔n méymá֖y⁠w neʼèmániֽym׃"],[33,17,"מֶ֥לֶךְ בְּ⁠יָפְי֖⁠וֹ תֶּחֱזֶ֣ינָה עֵינֶ֑י⁠ךָ תִּרְאֶ֖ינָה אֶ֥רֶץ מַרְחַקִּֽים׃","me֥lekĕ bĕ̇⁠yápĕy֖⁠wò ţėẖèze֣ynáh ʻéyne֑y⁠ká ţi̇rĕʼe֖ynáh ʼe֥reẕ marĕẖaqiֽ̇ym׃"],[33,18,"לִבְּ⁠ךָ֖ יֶהְגֶּ֣ה אֵימָ֑ה אַיֵּ֤ה סֹפֵר֙ אַיֵּ֣ה שֹׁקֵ֔ל אַיֵּ֖ה סֹפֵ֥ר אֶת־הַ⁠מִּגְדָּלִֽים׃","libĕ̇⁠ká֖ yehĕgė֣h ʼéymá֑h ʼayé֤̇h sòpér֙ ʼayé֣̇h şò̌qé֔l ʼayé֖̇h sòpé֥r ʼeţ-ha⁠mi̇gĕdá̇liֽym׃"],[33,19,"אֶת־עַ֥ם נוֹעָ֖ז לֹ֣א תִרְאֶ֑ה עַ֣ם עִמְקֵ֤י שָׂפָה֙ מִ⁠שְּׁמ֔וֹעַ נִלְעַ֥ג לָשׁ֖וֹן אֵ֥ין בִּינָֽה׃","ʼeţ-ʻa֥m nwòʻá֖z lò֣ʼ ţirĕʼe֑h ʻa֣m ʻimĕqé֤y şá̂páh֙ mi⁠şĕ̇̌m֔wòʻa nilĕʻa֥g láş֖̌wòn ʼé֥yn bi̇ynáֽh׃"],[33,20,"חֲזֵ֣ה צִיּ֔וֹן קִרְיַ֖ת מֽוֹעֲדֵ֑⁠נוּ עֵינֶי⁠ךָ֩ תִרְאֶ֨ינָה יְרוּשָׁלִַ֜ם נָוֶ֣ה שַׁאֲנָ֗ן אֹ֤הֶל בַּל־יִצְעָן֙ בַּל־יִסַּ֤ע יְתֵֽדֹתָי⁠ו֙ לָ⁠נֶ֔צַח וְ⁠כָל־חֲבָלָ֖י⁠ו בַּל־יִנָּתֵֽקוּ׃","ẖàzé֣h ẕiẏ֔wòn qirĕya֖ţ mֽwòʻàdé֑⁠nẇ ʻéyney⁠ká֩ ţirĕʼe֨ynáh yĕrẇşá̌lia֜m náwe֣h şǎʼàná֗n ʼò֤hel bȧl-yiẕĕʻán֙ bȧl-yisȧ֤ʻ yĕţéֽdòţáy⁠w֙ lá⁠ne֔ẕaẖ wĕ⁠kál-ẖàbálá֖y⁠w bȧl-yiná̇ţéֽqẇ׃"],[33,21,"כִּ֣י אִם־שָׁ֞ם אַדִּ֤יר יְהוָה֙ לָ֔⁠נוּ מְקוֹם־נְהָרִ֥ים יְאֹרִ֖ים רַחֲבֵ֣י יָדָ֑יִם בַּל־תֵּ֤לֶךְ בּ⁠וֹ֙ אֳנִי־שַׁ֔יִט וְ⁠צִ֥י אַדִּ֖יר לֹ֥א יַעַבְרֶֽ⁠נּוּ׃","ki֣̇y ʼim-şá̌֞m ʼadi֤̇yr yĕhwáh֙ lá֔⁠nẇ mĕqwòm-nĕhári֥ym yĕʼòri֖ym raẖàbé֣y yádá֑yim bȧl-ţé֤̇lekĕ ḃ⁠wò֙ ʼoniy-şǎ֔yit wĕ⁠ẕi֥y ʼadi֖̇yr lò֥ʼ yaʻabĕreֽ⁠ṅẇ׃"],[33,22,"כִּ֤י יְהוָה֙ שֹׁפְטֵ֔⁠נוּ יְהוָ֖ה מְחֹקְקֵ֑⁠נוּ יְהוָ֥ה מַלְכֵּ֖⁠נוּ ה֥וּא יוֹשִׁיעֵֽ⁠נוּ׃","ki֤̇y yĕhwáh֙ şò̌pĕté֔⁠nẇ yĕhwá֖h mĕẖòqĕqé֑⁠nẇ yĕhwá֥h malĕké֖̇⁠nẇ h֥ẇʼ ywòşǐyʻéֽ⁠nẇ׃"],[33,23,"נִטְּשׁ֖וּ חֲבָלָ֑יִ⁠ךְ בַּל־יְחַזְּק֤וּ כֵן־תָּרְנָ⁠ם֙ בַּל־פָּ֣רְשׂוּ נֵ֔ס אָ֣ז חֻלַּ֤ק עַֽד־שָׁלָל֙ מַרְבֶּ֔ה פִּסְחִ֖ים בָּ֥זְזוּ בַֽז׃","nitĕ̇ş֖̌ẇ ẖàbálá֑yi⁠kĕ bȧl-yĕẖazĕ̇q֤ẇ kén-ţá̇rĕná⁠m֙ bȧl-pá֣̇rĕş̂ẇ né֔s ʼá֣z ẖulȧ֤q ʻaֽd-şá̌lál֙ marĕbė֔h pi̇sĕẖi֖ym bá֥̇zĕzẇ baֽz׃"],[33,24,"וּ⁠בַל־יֹאמַ֥ר שָׁכֵ֖ן חָלִ֑יתִי הָ⁠עָ֛ם הַ⁠יֹּשֵׁ֥ב בָּ֖⁠הּ נְשֻׂ֥א עָוֺֽן׃","ẇ⁠bal-yòʼma֥r şá̌ké֖n ẖáli֑yţiy há⁠ʻá֛m ha⁠yò̇şé֥̌b bá֖̇⁠ḣ nĕşû֥ʼ ʻáwֺֽn׃"],[34,1,"קִרְב֤וּ גוֹיִם֙ לִ⁠שְׁמֹ֔עַ וּ⁠לְאֻמִּ֖ים הַקְשִׁ֑יבוּ תִּשְׁמַ֤ע הָ⁠אָ֨רֶץ֙ וּ⁠מְלֹאָ֔⁠הּ תֵּבֵ֖ל וְ⁠כָל־צֶאֱצָאֶֽי⁠הָ׃","qirĕb֤ẇ gwòyim֙ li⁠şĕ̌mò֔ʻa ẇ⁠lĕʼumi֖̇ym haqĕşǐ֑ybẇ ţi̇şĕ̌ma֤ʻ há⁠ʼá֨reẕ֙ ẇ⁠mĕlòʼá֔⁠ḣ ţé̇bé֖l wĕ⁠kál-ẕeʼèẕáʼeֽy⁠há׃"],[34,2,"כִּ֣י קֶ֤צֶף לַֽ⁠יהוָה֙ עַל־כָּל־הַ⁠גּוֹיִ֔ם וְ⁠חֵמָ֖ה עַל־כָּל־צְבָאָ֑⁠ם הֶחֱרִימָ֖⁠ם נְתָנָ֥⁠ם לַ⁠טָּֽבַח׃","ki֣̇y qe֤ẕep laֽ⁠yhwáh֙ ʻal-ká̇l-ha⁠ġwòyi֔m wĕ⁠ẖémá֖h ʻal-ká̇l-ẕĕbáʼá֑⁠m heẖèriymá֖⁠m nĕţáná֥⁠m la⁠táֽ̇baẖ׃"],[34,3,"וְ⁠חַלְלֵי⁠הֶ֣ם יֻשְׁלָ֔כוּ וּ⁠פִגְרֵי⁠הֶ֖ם יַעֲלֶ֣ה בָאְשָׁ֑⁠ם וְ⁠נָמַ֥סּוּ הָרִ֖ים מִ⁠דָּמָֽ⁠ם׃","wĕ⁠ẖalĕléy⁠he֣m yuşĕ̌lá֔kẇ ẇ⁠pigĕréy⁠he֖m yaʻàle֣h báʼĕşá֑̌⁠m wĕ⁠náma֥ṡẇ hári֖ym mi⁠dá̇máֽ⁠m׃"],[34,4,"וְ⁠נָמַ֨קּוּ֙ כָּל־צְבָ֣א הַ⁠שָּׁמַ֔יִם וְ⁠נָגֹ֥לּוּ כַ⁠סֵּ֖פֶר הַ⁠שָּׁמָ֑יִם וְ⁠כָל־צְבָאָ֣⁠ם יִבּ֔וֹל כִּ⁠נְבֹ֤ל עָלֶה֙ מִ⁠גֶּ֔פֶן וּ⁠כְ⁠נֹבֶ֖לֶת מִ⁠תְּאֵנָֽה׃","wĕ⁠náma֨q̇ẇ֙ ká̇l-ẕĕbá֣ʼ ha⁠şá̇̌ma֔yim wĕ⁠nágò֥l̇ẇ ka⁠sé֖̇per ha⁠şá̇̌má֑yim wĕ⁠kál-ẕĕbáʼá֣⁠m yiḃ֔wòl ki̇⁠nĕbò֤l ʻáleh֙ mi⁠gė֔pen ẇ⁠kĕ⁠nòbe֖leţ mi⁠ţĕ̇ʼénáֽh׃"],[34,5,"כִּֽי־רִוְּתָ֥ה בַ⁠שָּׁמַ֖יִם חַרְבִּ֑⁠י הִנֵּה֙ עַל־אֱד֣וֹם תֵּרֵ֔ד וְ⁠עַל־עַ֥ם חֶרְמִ֖⁠י לְ⁠מִשְׁפָּֽט׃","kiֽ̇y-riwĕ̇ţá֥h ba⁠şá̇̌ma֖yim ẖarĕbi֑̇⁠y hiné̇h֙ ʻal-ʼèd֣wòm ţé̇ré֔d wĕ⁠ʻal-ʻa֥m ẖerĕmi֖⁠y lĕ⁠mişĕ̌páֽ̇t׃"],[34,6,"חֶ֣רֶב לַ⁠יהוָ֞ה מָלְאָ֥ה דָם֙ הֻדַּ֣שְׁנָה מֵ⁠חֵ֔לֶב מִ⁠דַּ֤ם כָּרִים֙ וְ⁠עַתּוּדִ֔ים מֵ⁠חֵ֖לֶב כִּלְי֣וֹת אֵילִ֑ים כִּ֣י זֶ֤בַח לַֽ⁠יהוָה֙ בְּ⁠בָצְרָ֔ה וְ⁠טֶ֥בַח גָּד֖וֹל בְּ⁠אֶ֥רֶץ אֱדֽוֹם׃","ẖe֣reb la⁠yhwá֞h málĕʼá֥h dám֙ hudȧ֣şĕ̌náh mé⁠ẖé֔leb mi⁠dȧ֤m ká̇riym֙ wĕ⁠ʻaţ̇ẇdi֔ym mé⁠ẖé֖leb ki̇lĕy֣wòţ ʼéyli֑ym ki֣̇y ze֤baẖ laֽ⁠yhwáh֙ bĕ̇⁠báẕĕrá֔h wĕ⁠te֥baẖ gá̇d֖wòl bĕ̇⁠ʼe֥reẕ ʼèdֽwòm׃"],[34,7,"וְ⁠יָרְד֤וּ רְאֵמִים֙ עִמָּ֔⁠ם וּ⁠פָרִ֖ים עִם־אַבִּירִ֑ים וְ⁠רִוְּתָ֤ה אַרְצָ⁠ם֙ מִ⁠דָּ֔ם וַ⁠עֲפָרָ֖⁠ם מֵ⁠חֵ֥לֶב יְדֻשָּֽׁן׃","wĕ⁠yárĕd֤ẇ rĕʼémiym֙ ʻimá̇֔⁠m ẇ⁠pári֖ym ʻim-ʼabi̇yri֑ym wĕ⁠riwĕ̇ţá֤h ʼarĕẕá⁠m֙ mi⁠dá̇֔m wa⁠ʻàpárá֖⁠m mé⁠ẖé֥leb yĕduşáֽ̇̌n׃"],[34,8,"כִּ֛י י֥וֹם נָקָ֖ם לַֽ⁠יהוָ֑ה שְׁנַ֥ת שִׁלּוּמִ֖ים לְ⁠רִ֥יב צִיּֽוֹן׃","ki֛̇y y֥wòm náqá֖m laֽ⁠yhwá֑h şĕ̌na֥ţ şǐl̇ẇmi֖ym lĕ⁠ri֥yb ẕiẏֽwòn׃"],[34,9,"וְ⁠נֶהֶפְכ֤וּ נְחָלֶ֨י⁠הָ֙ לְ⁠זֶ֔פֶת וַ⁠עֲפָרָ֖⁠הּ לְ⁠גָפְרִ֑ית וְ⁠הָיְתָ֣ה אַרְצָ֔⁠הּ לְ⁠זֶ֖פֶת בֹּעֵרָֽה׃","wĕ⁠nehepĕk֤ẇ nĕẖále֨y⁠há֙ lĕ⁠ze֔peţ wa⁠ʻàpárá֖⁠ḣ lĕ⁠gápĕri֑yţ wĕ⁠háyĕţá֣h ʼarĕẕá֔⁠ḣ lĕ⁠ze֖peţ bò̇ʻéráֽh׃"],[34,10,"לַ֤יְלָה וְ⁠יוֹמָם֙ לֹ֣א תִכְבֶּ֔ה לְ⁠עוֹלָ֖ם יַעֲלֶ֣ה עֲשָׁנָ֑⁠הּ מִ⁠דּ֤וֹר לָ⁠דוֹר֙ תֶּחֱרָ֔ב לְ⁠נֵ֣צַח נְצָחִ֔ים אֵ֥ין עֹבֵ֖ר בָּֽ⁠הּ׃","la֤yĕláh wĕ⁠ywòmám֙ lò֣ʼ ţikĕbė֔h lĕ⁠ʻwòlá֖m yaʻàle֣h ʻàşá̌ná֑⁠ḣ mi⁠ḋ֤wòr lá⁠dwòr֙ ţėẖèrá֔b lĕ⁠né֣ẕaẖ nĕẕáẖi֔ym ʼé֥yn ʻòbé֖r báֽ̇⁠ḣ׃"],[34,11,"וִ⁠ירֵשׁ֨וּ⁠הָ֙ קָאַ֣ת וְ⁠קִפּ֔וֹד וְ⁠יַנְשׁ֥וֹף וְ⁠עֹרֵ֖ב יִשְׁכְּנוּ־בָ֑⁠הּ וְ⁠נָטָ֥ה עָלֶ֛י⁠הָ קַֽו־תֹ֖הוּ וְ⁠אַבְנֵי־בֹֽהוּ׃","wi⁠yréş̌֨ẇ⁠há֙ qáʼa֣ţ wĕ⁠qiṗ֔wòd wĕ⁠yanĕş֥̌wòp wĕ⁠ʻòré֖b yişĕ̌kĕ̇nẇ-bá֑⁠ḣ wĕ⁠nátá֥h ʻále֛y⁠há qaֽw-ţò֖hẇ wĕ⁠ʼabĕnéy-bòֽhẇ׃"],[34,12,"חֹרֶ֥י⁠הָ וְ⁠אֵֽין־שָׁ֖ם מְלוּכָ֣ה יִקְרָ֑אוּ וְ⁠כָל־שָׂרֶ֖י⁠הָ יִ֥הְיוּ אָֽפֶס׃","ẖòre֥y⁠há wĕ⁠ʼéֽyn-şá֖̌m mĕlẇká֣h yiqĕrá֑ʼẇ wĕ⁠kál-şá̂re֖y⁠há yi֥hĕyẇ ʼáֽpes׃"],[34,13,"וְ⁠עָלְתָ֤ה אַרְמְנֹתֶ֨י⁠הָ֙ סִירִ֔ים קִמּ֥וֹשׂ וָ⁠ח֖וֹחַ בְּ⁠מִבְצָרֶ֑י⁠הָ וְ⁠הָיְתָה֙ נְוֵ֣ה תַנִּ֔ים חָצִ֖יר לִ⁠בְנ֥וֹת יַעֲנָֽה׃","wĕ⁠ʻálĕţá֤h ʼarĕmĕnòţe֨y⁠há֙ siyri֔ym qiṁ֥wòş̂ wá⁠ẖ֖wòẖa bĕ̇⁠mibĕẕáre֑y⁠há wĕ⁠háyĕţáh֙ nĕwé֣h ţani̇֔ym ẖáẕi֖yr li⁠bĕn֥wòţ yaʻànáֽh׃"],[34,14,"וּ⁠פָגְשׁ֤וּ צִיִּים֙ אֶת־אִיִּ֔ים וְ⁠שָׂעִ֖יר עַל־רֵעֵ֣⁠הוּ יִקְרָ֑א אַךְ־שָׁם֙ הִרְגִּ֣יעָה לִּילִ֔ית וּ⁠מָצְאָ֥ה לָ֖⁠הּ מָנֽוֹחַ׃","ẇ⁠págĕş֤̌ẇ ẕiyi̇ym֙ ʼeţ-ʼiyi̇֔ym wĕ⁠şá̂ʻi֖yr ʻal-réʻé֣⁠hẇ yiqĕrá֑ʼ ʼakĕ-şá̌m֙ hirĕgi֣̇yʻáh li̇yli֔yţ ẇ⁠máẕĕʼá֥h lá֖⁠ḣ mánֽwòẖa׃"],[34,15,"שָׁ֣מָּ⁠ה קִנְּנָ֤ה קִפּוֹז֙ וַ⁠תְּמַלֵּ֔ט וּ⁠בָקְעָ֖ה וְ⁠דָגְרָ֣ה בְ⁠צִלָּ֑⁠הּ אַךְ־שָׁ֛ם נִקְבְּצ֥וּ דַיּ֖וֹת אִשָּׁ֥ה רְעוּתָֽ⁠הּ׃","şá֣̌má̇⁠h qinĕ̇ná֤h qiṗwòz֙ wa⁠ţĕ̇malé̇֔t ẇ⁠báqĕʻá֖h wĕ⁠dágĕrá֣h bĕ⁠ẕilá֑̇⁠ḣ ʼakĕ-şá֛̌m niqĕbĕ̇ẕ֥ẇ daẏ֖wòţ ʼişá֥̇̌h rĕʻẇţáֽ⁠ḣ׃"],[34,16,"דִּרְשׁ֨וּ מֵֽ⁠עַל־סֵ֤פֶר יְהוָה֙ וּֽ⁠קְרָ֔אוּ אַחַ֤ת מֵ⁠הֵ֨נָּה֙ לֹ֣א נֶעְדָּ֔רָה אִשָּׁ֥ה רְעוּתָ֖⁠הּ לֹ֣א פָקָ֑דוּ כִּֽי־פִ⁠י֙ ה֣וּא צִוָּ֔ה וְ⁠רוּח֖⁠וֹ ה֥וּא קִבְּצָֽ⁠ן׃","di̇rĕş̌֨ẇ méֽ⁠ʻal-sé֤per yĕhwáh֙ ẇֽ⁠qĕrá֔ʼẇ ʼaẖa֤ţ mé⁠hé֨ná̇h֙ lò֣ʼ neʻĕdá̇֔ráh ʼişá֥̇̌h rĕʻẇţá֖⁠ḣ lò֣ʼ páqá֑dẇ kiֽ̇y-pi⁠y֙ h֣ẇʼ ẕiwá̇֔h wĕ⁠rẇẖ֖⁠wò h֥ẇʼ qibĕ̇ẕáֽ⁠n׃"],[34,17,"וְ⁠הֽוּא־הִפִּ֤יל לָ⁠הֶן֙ גּוֹרָ֔ל וְ⁠יָד֛⁠וֹ חִלְּקַ֥תָּ⁠ה לָ⁠הֶ֖ם בַּ⁠קָּ֑ו עַד־עוֹלָם֙ יִֽירָשׁ֔וּ⁠הָ לְ⁠ד֥וֹר וָ⁠ד֖וֹר יִשְׁכְּנוּ־בָֽ⁠הּ׃ס","wĕ⁠hֽẇʼ-hipi֤̇yl lá⁠hen֙ ġwòrá֔l wĕ⁠yád֛⁠wò ẖilĕ̇qa֥ţá̇⁠h lá⁠he֖m bȧ⁠qá֑̇w ʻad-ʻwòlám֙ yiֽyráş̌֔ẇ⁠há lĕ⁠d֥wòr wá⁠d֖wòr yişĕ̌kĕ̇nẇ-báֽ⁠ḣ׃s"],[35,1,"יְשֻׂשׂ֥וּ⁠ם מִדְבָּ֖ר וְ⁠צִיָּ֑ה וְ⁠תָגֵ֧ל עֲרָבָ֛ה וְ⁠תִפְרַ֖ח כַּ⁠חֲבַצָּֽלֶת׃","yĕşûş֥̂ẇ⁠m midĕbá֖̇r wĕ⁠ẕiyá֑̇h wĕ⁠ţágé֧l ʻàrábá֛h wĕ⁠ţipĕra֖ẖ kȧ⁠ẖàbaẕáֽ̇leţ׃"],[35,2,"פָּרֹ֨חַ תִּפְרַ֜ח וְ⁠תָגֵ֗ל אַ֚ף גִּילַ֣ת וְ⁠רַנֵּ֔ן כְּב֤וֹד הַ⁠לְּבָנוֹן֙ נִתַּן־לָ֔⁠הּ הֲדַ֥ר הַ⁠כַּרְמֶ֖ל וְ⁠הַ⁠שָּׁר֑וֹן הֵ֛מָּה יִרְא֥וּ כְבוֹד־יְהוָ֖ה הֲדַ֥ר אֱלֹהֵֽי⁠נוּ׃ס","pá̇rò֨ẖa ţi̇pĕra֜ẖ wĕ⁠ţágé֗l ʼa֚p gi̇yla֣ţ wĕ⁠rané̇֔n kĕ̇b֤wòd ha⁠lĕ̇bánwòn֙ niţȧn-lá֔⁠ḣ hàda֥r ha⁠kȧrĕme֖l wĕ⁠ha⁠şá̇̌r֑wòn hé֛má̇h yirĕʼ֥ẇ kĕbwòd-yĕhwá֖h hàda֥r ʼèlòhéֽy⁠nẇ׃s"],[35,3,"חַזְּק֖וּ יָדַ֣יִם רָפ֑וֹת וּ⁠בִרְכַּ֥יִם כֹּשְׁל֖וֹת אַמֵּֽצוּ׃","ẖazĕ̇q֖ẇ yáda֣yim ráp֑wòţ ẇ⁠birĕkȧ֥yim kò̇şĕ̌l֖wòţ ʼaméֽ̇ẕẇ׃"],[35,4,"אִמְרוּ֙ לְ⁠נִמְהֲרֵי־לֵ֔ב חִזְק֖וּ אַל־תִּירָ֑אוּ הִנֵּ֤ה אֱלֹֽהֵי⁠כֶם֙ נָקָ֣ם יָב֔וֹא גְּמ֣וּל אֱלֹהִ֔ים ה֥וּא יָב֖וֹא וְ⁠יֹשַׁעֲ⁠כֶֽם׃","ʼimĕrẇ֙ lĕ⁠nimĕhàréy-lé֔b ẖizĕq֖ẇ ʼal-ţi̇yrá֑ʼẇ hiné֤̇h ʼèlòֽhéy⁠kem֙ náqá֣m yáb֔wòʼ gĕ̇m֣ẇl ʼèlòhi֔ym h֥ẇʼ yáb֖wòʼ wĕ⁠yòşǎʻà⁠keֽm׃"],[35,5,"אָ֥ז תִּפָּקַ֖חְנָה עֵינֵ֣י עִוְרִ֑ים וְ⁠אָזְנֵ֥י חֵרְשִׁ֖ים תִּפָּתַֽחְנָה׃","ʼá֥z ţi̇pá̇qa֖ẖĕnáh ʻéyné֣y ʻiwĕri֑ym wĕ⁠ʼázĕné֥y ẖérĕşǐ֖ym ţi̇pá̇ţaֽẖĕnáh׃"],[35,6,"אָ֣ז יְדַלֵּ֤ג כָּֽ⁠אַיָּל֙ פִּסֵּ֔חַ וְ⁠תָרֹ֖ן לְשׁ֣וֹן אִלֵּ֑ם כִּֽי־נִבְקְע֤וּ בַ⁠מִּדְבָּר֙ מַ֔יִם וּ⁠נְחָלִ֖ים בָּ⁠עֲרָבָֽה׃","ʼá֣z yĕdalé֤̇g káֽ̇⁠ʼayá̇l֙ pi̇sé̇֔ẖa wĕ⁠ţárò֖n lĕş֣̌wòn ʼilé֑̇m kiֽ̇y-nibĕqĕʻ֤ẇ ba⁠mi̇dĕbá̇r֙ ma֔yim ẇ⁠nĕẖáli֖ym bá̇⁠ʻàrábáֽh׃"],[35,7,"וְ⁠הָיָ֤ה הַ⁠שָּׁרָב֙ לַ⁠אֲגַ֔ם וְ⁠צִמָּא֖וֹן לְ⁠מַבּ֣וּעֵי מָ֑יִם בִּ⁠נְוֵ֤ה תַנִּים֙ רִבְצָ֔⁠הּ חָצִ֖יר לְ⁠קָנֶ֥ה וָ⁠גֹֽמֶא׃","wĕ⁠háyá֤h ha⁠şá̇̌ráb֙ la⁠ʼàga֔m wĕ⁠ẕimá̇ʼ֖wòn lĕ⁠maḃ֣ẇʻéy má֑yim bi̇⁠nĕwé֤h ţani̇ym֙ ribĕẕá֔⁠ḣ ẖáẕi֖yr lĕ⁠qáne֥h wá⁠gòֽmeʼ׃"],[35,8,"וְ⁠הָיָה־שָׁ֞ם מַסְל֣וּל וָ⁠דֶ֗רֶךְ וְ⁠דֶ֤רֶךְ הַ⁠קֹּ֨דֶשׁ֙ יִקָּ֣רֵא לָ֔⁠הּ לֹֽא־יַעַבְרֶ֥⁠נּוּ טָמֵ֖א וְ⁠הוּא־לָ֑⁠מוֹ הֹלֵ֥ךְ דֶּ֛רֶךְ וֶ⁠אֱוִילִ֖ים לֹ֥א יִתְעֽוּ׃","wĕ⁠háyáh-şá̌֞m masĕl֣ẇl wá⁠de֗rekĕ wĕ⁠de֤rekĕ ha⁠qò̇֨deş̌֙ yiqá֣̇réʼ lá֔⁠ḣ lòֽʼ-yaʻabĕre֥⁠ṅẇ támé֖ʼ wĕ⁠hẇʼ-lá֑⁠mwò hòlé֥kĕ dė֛rekĕ we⁠ʼèwiyli֖ym lò֥ʼ yiţĕʻֽẇ׃"],[35,9,"לֹא־יִהְיֶ֨ה שָׁ֜ם אַרְיֵ֗ה וּ⁠פְרִ֤יץ חַיּוֹת֙ בַּֽל־יַעֲלֶ֔⁠נָּה לֹ֥א תִמָּצֵ֖א שָׁ֑ם וְ⁠הָלְכ֖וּ גְּאוּלִֽים׃","lòʼ-yihĕye֨h şá̌֜m ʼarĕyé֗h ẇ⁠pĕri֤yẕ ẖaẏwòţ֙ bȧֽl-yaʻàle֔⁠ná̇h lò֥ʼ ţimá̇ẕé֖ʼ şá֑̌m wĕ⁠hálĕk֖ẇ gĕ̇ʼẇliֽym׃"],[35,10,"וּ⁠פְדוּיֵ֨י יְהוָ֜ה יְשֻׁב֗וּ⁠ן וּ⁠בָ֤אוּ צִיּוֹן֙ בְּ⁠רִנָּ֔ה וְ⁠שִׂמְחַ֥ת עוֹלָ֖ם עַל־רֹאשָׁ֑⁠ם שָׂשׂ֤וֹן וְ⁠שִׂמְחָה֙ יַשִּׂ֔יגוּ וְ⁠נָ֖סוּ יָג֥וֹן וַ⁠אֲנָחָֽה׃פ","ẇ⁠pĕdẇyé֨y yĕhwá֜h yĕşǔb֗ẇ⁠n ẇ⁠bá֤ʼẇ ẕiẏwòn֙ bĕ̇⁠riná̇֔h wĕ⁠şîmĕẖa֥ţ ʻwòlá֖m ʻal-ròʼşá֑̌⁠m şá̂ş֤̂wòn wĕ⁠şîmĕẖáh֙ yaşi̇̂֔ygẇ wĕ⁠ná֖sẇ yág֥wòn wa⁠ʼànáẖáֽh׃p"],[36,1,"וַ⁠יְהִ֡י בְּ⁠אַרְבַּע֩ עֶשְׂרֵ֨ה שָׁנָ֜ה לַ⁠מֶּ֣לֶךְ חִזְקִיָּ֗הוּ עָלָ֞ה סַנְחֵרִ֤יב מֶֽלֶךְ־אַשּׁוּר֙ עַ֣ל כָּל־עָרֵ֧י יְהוּדָ֛ה הַ⁠בְּצֻר֖וֹת וַֽ⁠יִּתְפְּשֵֽׂ⁠ם׃","wa⁠yĕhi֡y bĕ̇⁠ʼarĕbȧʻ֩ ʻeşĕ̂ré֨h şá̌ná֜h la⁠mė֣lekĕ ẖizĕqiyá̇֗hẇ ʻálá֞h sanĕẖéri֤yb meֽlekĕ-ʼaş̇̌ẇr֙ ʻa֣l ká̇l-ʻáré֧y yĕhẇdá֛h ha⁠bĕ̇ẕur֖wòţ waֽ⁠yi̇ţĕpĕ̇şéֽ̂⁠m׃"],[36,2,"וַ⁠יִּשְׁלַ֣ח מֶֽלֶךְ־אַשּׁ֣וּר ׀ אֶת־רַב־שָׁקֵ֨ה מִ⁠לָּכִ֧ישׁ יְרוּשָׁלְַ֛מָ⁠ה אֶל־הַ⁠מֶּ֥לֶךְ חִזְקִיָּ֖הוּ בְּ⁠חֵ֣יל כָּבֵ֑ד וַֽ⁠יַּעֲמֹ֗ד בִּ⁠תְעָלַת֙ הַ⁠בְּרֵכָ֣ה הָ⁠עֶלְיוֹנָ֔ה בִּ⁠מְסִלַּ֖ת שְׂדֵ֥ה כוֹבֵֽס׃","wa⁠yi̇şĕ̌la֣ẖ meֽlekĕ-ʼaş֣̇̌ẇr ׀ ʼeţ-rab-şá̌qé֨h mi⁠lá̇ki֧yş̌ yĕrẇşá̌lĕa֛má⁠h ʼel-ha⁠mė֥lekĕ ẖizĕqiyá֖̇hẇ bĕ̇⁠ẖé֣yl ká̇bé֑d waֽ⁠yȧʻàmò֗d bi̇⁠ţĕʻálaţ֙ ha⁠bĕ̇réká֣h há⁠ʻelĕywòná֔h bi̇⁠mĕsilȧ֖ţ şĕ̂dé֥h kwòbéֽs׃"],[36,3,"וַ⁠יֵּצֵ֥א אֵלָ֛י⁠ו אֶלְיָקִ֥ים בֶּן־חִלְקִיָּ֖הוּ אֲשֶׁ֣ר עַל־הַ⁠בָּ֑יִת וְ⁠שֶׁבְנָא֙ הַ⁠סֹּפֵ֔ר וְ⁠יוֹאָ֥ח בֶּן־אָסָ֖ף הַ⁠מַּזְכִּֽיר׃","wa⁠yé̇ẕé֥ʼ ʼélá֛y⁠w ʼelĕyáqi֥ym bėn-ẖilĕqiyá֖̇hẇ ʼàşě֣r ʻal-ha⁠bá֑̇yiţ wĕ⁠şěbĕnáʼ֙ ha⁠sò̇pé֔r wĕ⁠ywòʼá֥ẖ bėn-ʼásá֖p ha⁠mȧzĕkiֽ̇yr׃"],[36,4,"וַ⁠יֹּ֤אמֶר אֲלֵי⁠הֶם֙ רַב־שָׁקֵ֔ה אִמְרוּ־נָ֖א אֶל־חִזְקִיָּ֑הוּ כֹּֽה־אָמַ֞ר הַ⁠מֶּ֤לֶךְ הַ⁠גָּדוֹל֙ מֶ֣לֶךְ אַשּׁ֔וּר מָ֧ה הַ⁠בִּטָּח֛וֹן הַ⁠זֶּ֖ה אֲשֶׁ֥ר בָּטָֽחְתָּ׃","wa⁠yò֤̇ʼmer ʼàléy⁠hem֙ rab-şá̌qé֔h ʼimĕrẇ-ná֖ʼ ʼel-ẖizĕqiyá֑̇hẇ kòֽ̇h-ʼáma֞r ha⁠mė֤lekĕ ha⁠gá̇dwòl֙ me֣lekĕ ʼaş̇̌֔ẇr má֧h ha⁠bi̇tá̇ẖ֛wòn ha⁠zė֖h ʼàşě֥r bá̇táֽẖĕţá̇׃"],[36,5,"אָמַ֨רְתִּי֙ אַךְ־דְּבַר־שְׂפָתַ֔יִם עֵצָ֥ה וּ⁠גְבוּרָ֖ה לַ⁠מִּלְחָמָ֑ה עַתָּה֙ עַל־מִ֣י בָטַ֔חְתָּ כִּ֥י מָרַ֖דְתָּ בִּֽ⁠י׃","ʼáma֨rĕţi̇y֙ ʼakĕ-dĕ̇bar-şĕ̂páţa֔yim ʻéẕá֥h ẇ⁠gĕbẇrá֖h la⁠mi̇lĕẖámá֑h ʻaţá̇h֙ ʻal-mi֣y báta֔ẖĕţá̇ ki֥̇y mára֖dĕţá̇ biֽ̇⁠y׃"],[36,6,"הִנֵּ֣ה בָטַ֡חְתָּ עַל־מִשְׁעֶנֶת֩ הַ⁠קָּנֶ֨ה הָ⁠רָצ֤וּץ הַ⁠זֶּה֙ עַל־מִצְרַ֔יִם אֲשֶׁ֨ר יִסָּמֵ֥ךְ אִישׁ֙ עָלָ֔י⁠ו וּ⁠בָ֥א בְ⁠כַפּ֖⁠וֹ וּ⁠נְקָבָ֑⁠הּ כֵּ֚ן פַּרְעֹ֣ה מֶֽלֶךְ־מִצְרַ֔יִם לְ⁠כָֽל־הַ⁠בֹּטְחִ֖ים עָלָֽי⁠ו׃","hiné֣̇h báta֡ẖĕţá̇ ʻal-mişĕ̌ʻeneţ֩ ha⁠qá̇ne֨h há⁠ráẕ֤ẇẕ ha⁠zėh֙ ʻal-miẕĕra֔yim ʼàşě֨r yisá̇mé֥kĕ ʼiyş̌֙ ʻálá֔y⁠w ẇ⁠bá֥ʼ bĕ⁠kaṗ֖⁠wò ẇ⁠nĕqábá֑⁠ḣ ké֚̇n pȧrĕʻò֣h meֽlekĕ-miẕĕra֔yim lĕ⁠káֽl-ha⁠bò̇tĕẖi֖ym ʻáláֽy⁠w׃"],[36,7,"וְ⁠כִי־תֹאמַ֣ר אֵלַ֔⁠י אֶל־יְהוָ֥ה אֱלֹהֵ֖י⁠נוּ בָּטָ֑חְנוּ הֲ⁠לוֹא־ה֗וּא אֲשֶׁ֨ר הֵסִ֤יר חִזְקִיָּ֨הוּ֙ אֶת־בָּמֹתָ֣י⁠ו וְ⁠אֶת־מִזְבְּחֹתָ֔י⁠ו וַ⁠יֹּ֤אמֶר לִֽ⁠יהוּדָה֙ וְ⁠לִ⁠יר֣וּשָׁלִַ֔ם לִ⁠פְנֵ֛י הַ⁠מִּזְבֵּ֥חַ הַ⁠זֶּ֖ה תִּֽשְׁתַּחֲוֽוּ׃","wĕ⁠kiy-ţòʼma֣r ʼéla֔⁠y ʼel-yĕhwá֥h ʼèlòhé֖y⁠nẇ bá̇tá֑ẖĕnẇ hà⁠lwòʼ-h֗ẇʼ ʼàşě֨r hési֤yr ẖizĕqiyá̇֨hẇ֙ ʼeţ-bá̇mòţá֣y⁠w wĕ⁠ʼeţ-mizĕbĕ̇ẖòţá֔y⁠w wa⁠yò֤̇ʼmer liֽ⁠yhẇdáh֙ wĕ⁠li⁠yr֣ẇşá̌lia֔m li⁠pĕné֛y ha⁠mi̇zĕbé֥̇ẖa ha⁠zė֖h ţiֽ̇şĕ̌ţȧẖàwֽẇ׃"],[36,8,"וְ⁠עַתָּה֙ הִתְעָ֣רֶב נָ֔א אֶת־אֲדֹנִ֖⁠י הַ⁠מֶּ֣לֶךְ אַשּׁ֑וּר וְ⁠אֶתְּנָ֤ה לְ⁠ךָ֙ אַלְפַּ֣יִם סוּסִ֔ים אִם־תּוּכַ֕ל לָ֥⁠תֶת לְ⁠ךָ֖ רֹכְבִ֥ים עֲלֵי⁠הֶֽם׃","wĕ⁠ʻaţá̇h֙ hiţĕʻá֣reb ná֔ʼ ʼeţ-ʼàdòni֖⁠y ha⁠mė֣lekĕ ʼaş֑̇̌ẇr wĕ⁠ʼeţĕ̇ná֤h lĕ⁠ká֙ ʼalĕpȧ֣yim sẇsi֔ym ʼim-ţ̇ẇka֕l lá֥⁠ţeţ lĕ⁠ká֖ ròkĕbi֥ym ʻàléy⁠heֽm׃"],[36,9,"וְ⁠אֵ֣יךְ תָּשִׁ֗יב אֵ֠ת פְּנֵ֨י פַחַ֥ת אַחַ֛ד עַבְדֵ֥י אֲדֹנִ֖⁠י הַ⁠קְטַנִּ֑ים וַ⁠תִּבְטַ֤ח לְ⁠ךָ֙ עַל־מִצְרַ֔יִם לְ⁠רֶ֖כֶב וּ⁠לְ⁠פָרָשִֽׁים׃","wĕ⁠ʼé֣ykĕ ţá̇şǐ֗yb ʼé֠ţ pĕ̇né֨y paẖa֥ţ ʼaẖa֛d ʻabĕdé֥y ʼàdòni֖⁠y ha⁠qĕtani֑̇ym wa⁠ţi̇bĕta֤ẖ lĕ⁠ká֙ ʻal-miẕĕra֔yim lĕ⁠re֖keb ẇ⁠lĕ⁠páráşǐֽym׃"],[36,10,"וְ⁠עַתָּה֙ הֲ⁠מִ⁠בַּלְעֲדֵ֣י יְהוָ֔ה עָלִ֛יתִי עַל־הָ⁠אָ֥רֶץ הַ⁠זֹּ֖את לְ⁠הַשְׁחִיתָ֑⁠הּ יְהוָה֙ אָמַ֣ר אֵלַ֔⁠י עֲלֵ֛ה אֶל־הָ⁠אָ֥רֶץ הַ⁠זֹּ֖את וְ⁠הַשְׁחִיתָֽ⁠הּ׃","wĕ⁠ʻaţá̇h֙ hà⁠mi⁠bȧlĕʻàdé֣y yĕhwá֔h ʻáli֛yţiy ʻal-há⁠ʼá֥reẕ ha⁠zò֖̇ʼţ lĕ⁠haşĕ̌ẖiyţá֑⁠ḣ yĕhwáh֙ ʼáma֣r ʼéla֔⁠y ʻàlé֛h ʼel-há⁠ʼá֥reẕ ha⁠zò֖̇ʼţ wĕ⁠haşĕ̌ẖiyţáֽ⁠ḣ׃"],[36,11,"וַ⁠יֹּ֣אמֶר אֶלְיָקִים֩ וְ⁠שֶׁבְנָ֨א וְ⁠יוֹאָ֜ח אֶל־רַב־שָׁקֵ֗ה דַּבֶּר־נָ֤א אֶל־עֲבָדֶ֨י⁠ךָ֙ אֲרָמִ֔ית כִּ֥י שֹׁמְעִ֖ים אֲנָ֑חְנוּ וְ⁠אַל־תְּדַבֵּ֤ר אֵלֵ֨י⁠נוּ֙ יְהוּדִ֔ית בְּ⁠אָזְנֵ֣י הָ⁠עָ֔ם אֲשֶׁ֖ר עַל־הַ⁠חוֹמָֽה׃","wa⁠yò֣̇ʼmer ʼelĕyáqiym֩ wĕ⁠şěbĕná֨ʼ wĕ⁠ywòʼá֜ẖ ʼel-rab-şá̌qé֗h dȧbėr-ná֤ʼ ʼel-ʻàbáde֨y⁠ká֙ ʼàrámi֔yţ ki֥̇y şò̌mĕʻi֖ym ʼàná֑ẖĕnẇ wĕ⁠ʼal-ţĕ̇dabé֤̇r ʼélé֨y⁠nẇ֙ yĕhẇdi֔yţ bĕ̇⁠ʼázĕné֣y há⁠ʻá֔m ʼàşě֖r ʻal-ha⁠ẖwòmáֽh׃"],[36,12,"וַ⁠יֹּ֣אמֶר רַב־שָׁקֵ֗ה הַ⁠אֶ֨ל אֲדֹנֶ֤י⁠ךָ וְ⁠אֵלֶ֨י⁠ךָ֙ שְׁלָחַ֣⁠נִי אֲדֹנִ֔⁠י לְ⁠דַבֵּ֖ר אֶת־הַ⁠דְּבָרִ֣ים הָ⁠אֵ֑לֶּה הֲ⁠לֹ֣א עַל־הָ⁠אֲנָשִׁ֗ים הַ⁠יֹּֽשְׁבִים֙ עַל־הַ֣⁠חוֹמָ֔ה לֶ⁠אֱכֹ֣ל אֶת־חראי⁠הם וְ⁠לִ⁠שְׁתּ֛וֹת אֶת־שיני⁠הם עִמָּ⁠כֶֽם׃","wa⁠yò֣̇ʼmer rab-şá̌qé֗h ha⁠ʼe֨l ʼàdòne֤y⁠ká wĕ⁠ʼéle֨y⁠ká֙ şĕ̌láẖa֣⁠niy ʼàdòni֔⁠y lĕ⁠dabé֖̇r ʼeţ-ha⁠dĕ̇bári֣ym há⁠ʼé֑lėh hà⁠lò֣ʼ ʻal-há⁠ʼànáşǐ֗ym ha⁠yòֽ̇şĕ̌biym֙ ʻal-ha֣⁠ẖwòmá֔h le⁠ʼèkò֣l ʼeţ-ẖrʼy⁠hm wĕ⁠li⁠şĕ̌ţ֛̇wòţ ʼeţ-şyny⁠hm ʻimá̇⁠keֽm׃"],[36,13,"וַֽ⁠יַּעֲמֹד֙ רַב־שָׁקֵ֔ה וַ⁠יִּקְרָ֥א בְ⁠קוֹל־גָּד֖וֹל יְהוּדִ֑ית וַ⁠יֹּ֕אמֶר שִׁמְע֗וּ אֶת־דִּבְרֵ֛י הַ⁠מֶּ֥לֶךְ הַ⁠גָּד֖וֹל מֶ֥לֶךְ אַשּֽׁוּר׃","waֽ⁠yȧʻàmòd֙ rab-şá̌qé֔h wa⁠yi̇qĕrá֥ʼ bĕ⁠qwòl-gá̇d֖wòl yĕhẇdi֑yţ wa⁠yò̇֕ʼmer şǐmĕʻ֗ẇ ʼeţ-di̇bĕré֛y ha⁠mė֥lekĕ ha⁠gá̇d֖wòl me֥lekĕ ʼaşֽ̇̌ẇr׃"],[36,14,"כֹּ֚ה אָמַ֣ר הַ⁠מֶּ֔לֶךְ אַל־יַשִּׁ֥א לָ⁠כֶ֖ם חִזְקִיָּ֑הוּ כִּ֥י לֹֽא־יוּכַ֖ל לְ⁠הַצִּ֥יל אֶתְ⁠כֶֽם׃","kò֚̇h ʼáma֣r ha⁠mė֔lekĕ ʼal-yaşi֥̇̌ʼ lá⁠ke֖m ẖizĕqiyá֑̇hẇ ki֥̇y lòֽʼ-yẇka֖l lĕ⁠haẕi֥̇yl ʼeţĕ⁠keֽm׃"],[36,15,"וְ⁠אַל־יַבְטַ֨ח אֶתְ⁠כֶ֤ם חִזְקִיָּ֨הוּ֙ אֶל־יְהוָ֣ה לֵ⁠אמֹ֔ר הַצֵּ֥ל יַצִּילֵ֖⁠נוּ יְהוָ֑ה לֹ֤א תִנָּתֵן֙ הָ⁠עִ֣יר הַ⁠זֹּ֔את בְּ⁠יַ֖ד מֶ֥לֶךְ אַשּֽׁוּר׃","wĕ⁠ʼal-yabĕta֨ẖ ʼeţĕ⁠ke֤m ẖizĕqiyá̇֨hẇ֙ ʼel-yĕhwá֣h lé⁠ʼmò֔r haẕé֥̇l yaẕi̇ylé֖⁠nẇ yĕhwá֑h lò֤ʼ ţiná̇ţén֙ há⁠ʻi֣yr ha⁠zò̇֔ʼţ bĕ̇⁠ya֖d me֥lekĕ ʼaşֽ̇̌ẇr׃"],[36,16,"אַֽל־תִּשְׁמְע֖וּ אֶל־חִזְקִיָּ֑הוּ ס כִּי֩ כֹ֨ה אָמַ֜ר הַ⁠מֶּ֣לֶךְ אַשּׁ֗וּר עֲשֽׂוּ־אִתִּ֤⁠י בְרָכָה֙ וּ⁠צְא֣וּ אֵלַ֔⁠י וְ⁠אִכְל֤וּ אִישׁ־גַּפְנ⁠וֹ֙ וְ⁠אִ֣ישׁ תְּאֵנָת֔⁠וֹ וּ⁠שְׁת֖וּ אִ֥ישׁ מֵי־בוֹרֽ⁠וֹ׃","ʼaֽl-ţi̇şĕ̌mĕʻ֖ẇ ʼel-ẖizĕqiyá֑̇hẇ s ki̇y֩ kò֨h ʼáma֜r ha⁠mė֣lekĕ ʼaş̇̌֗ẇr ʻàşֽ̂ẇ-ʼiţi֤̇⁠y bĕrákáh֙ ẇ⁠ẕĕʼ֣ẇ ʼéla֔⁠y wĕ⁠ʼikĕl֤ẇ ʼiyş̌-gȧpĕn⁠wò֙ wĕ⁠ʼi֣yş̌ ţĕ̇ʼénáţ֔⁠wò ẇ⁠şĕ̌ţ֖ẇ ʼi֥yş̌ méy-bwòrֽ⁠wò׃"],[36,17,"עַד־בֹּאִ֕⁠י וְ⁠לָקַחְתִּ֥י אֶתְ⁠כֶ֖ם אֶל־אֶ֣רֶץ כְּ⁠אַרְצְ⁠כֶ֑ם אֶ֤רֶץ דָּגָן֙ וְ⁠תִיר֔וֹשׁ אֶ֥רֶץ לֶ֖חֶם וּ⁠כְרָמִֽים׃","ʻad-bò̇ʼi֕⁠y wĕ⁠láqaẖĕţi֥̇y ʼeţĕ⁠ke֖m ʼel-ʼe֣reẕ kĕ̇⁠ʼarĕẕĕ⁠ke֑m ʼe֤reẕ dá̇gán֙ wĕ⁠ţiyr֔wòş̌ ʼe֥reẕ le֖ẖem ẇ⁠kĕrámiֽym׃"],[36,18,"פֶּן־יַסִּ֨ית אֶתְ⁠כֶ֤ם חִזְקִיָּ֨הוּ֙ לֵ⁠אמֹ֔ר יְהוָ֖ה יַצִּילֵ֑⁠נוּ הַ⁠הִצִּ֜ילוּ אֱלֹהֵ֤י הַ⁠גּוֹיִם֙ אִ֣ישׁ אֶת־אַרְצ֔⁠וֹ מִ⁠יַּ֖ד מֶ֥לֶךְ אַשּֽׁוּר׃","pėn-yasi̇֨yţ ʼeţĕ⁠ke֤m ẖizĕqiyá̇֨hẇ֙ lé⁠ʼmò֔r yĕhwá֖h yaẕi̇ylé֑⁠nẇ ha⁠hiẕi̇֜ylẇ ʼèlòhé֤y ha⁠ġwòyim֙ ʼi֣yş̌ ʼeţ-ʼarĕẕ֔⁠wò mi⁠yȧ֖d me֥lekĕ ʼaşֽ̇̌ẇr׃"],[36,19,"אַיֵּ֞ה אֱלֹהֵ֤י חֲמָת֙ וְ⁠אַרְפָּ֔ד אַיֵּ֖ה אֱלֹהֵ֣י סְפַרְוָ֑יִם וְ⁠כִֽי־הִצִּ֥ילוּ אֶת־שֹׁמְר֖וֹן מִ⁠יָּדִֽ⁠י׃","ʼayé̇֞h ʼèlòhé֤y ẖàmáţ֙ wĕ⁠ʼarĕpá̇֔d ʼayé֖̇h ʼèlòhé֣y sĕparĕwá֑yim wĕ⁠kiֽy-hiẕi֥̇ylẇ ʼeţ-şò̌mĕr֖wòn mi⁠yá̇diֽ⁠y׃"],[36,20,"מִ֗י בְּ⁠כָל־אֱלֹהֵ֤י הָֽ⁠אֲרָצוֹת֙ הָ⁠אֵ֔לֶּה אֲשֶׁר־הִצִּ֥ילוּ אֶת־אַרְצָ֖⁠ם מִ⁠יָּדִ֑⁠י כִּֽי־יַצִּ֧יל יְהוָ֛ה אֶת־יְרוּשָׁלִַ֖ם מִ⁠יָּדִֽ⁠י׃","mi֗y bĕ̇⁠kál-ʼèlòhé֤y háֽ⁠ʼàráẕwòţ֙ há⁠ʼé֔lėh ʼàşěr-hiẕi֥̇ylẇ ʼeţ-ʼarĕẕá֖⁠m mi⁠yá̇di֑⁠y kiֽ̇y-yaẕi֧̇yl yĕhwá֛h ʼeţ-yĕrẇşá̌lia֖m mi⁠yá̇diֽ⁠y׃"],[36,21,"וַֽ⁠יַּחֲרִ֔ישׁוּ וְ⁠לֹֽא־עָנ֥וּ אֹת֖⁠וֹ דָּבָ֑ר כִּֽי־מִצְוַ֨ת הַ⁠מֶּ֥לֶךְ הִ֛יא לֵ⁠אמֹ֖ר לֹ֥א תַעֲנֻֽ⁠הוּ׃","waֽ⁠yȧẖàri֔yş̌ẇ wĕ⁠lòֽʼ-ʻán֥ẇ ʼòţ֖⁠wò dá̇bá֑r kiֽ̇y-miẕĕwa֨ţ ha⁠mė֥lekĕ hi֛yʼ lé⁠ʼmò֖r lò֥ʼ ţaʻànuֽ⁠hẇ׃"],[36,22,"וַ⁠יָּבֹ֣א אֶלְיָקִ֣ים בֶּן־חִלְקִיָּ֣הוּ אֲשֶׁר־עַל־הַ֠⁠בַּיִת וְ⁠שֶׁבְנָ֨א הַ⁠סּוֹפֵ֜ר וְ⁠יוֹאָ֨ח בֶּן־אָסָ֧ף הַ⁠מַּזְכִּ֛יר אֶל־חִזְקִיָּ֖הוּ קְרוּעֵ֣י בְגָדִ֑ים וַ⁠יַּגִּ֣ידוּ ל֔⁠וֹ אֵ֖ת דִּבְרֵ֥י רַב־שָׁקֵֽה׃ס","wa⁠yá̇bò֣ʼ ʼelĕyáqi֣ym bėn-ẖilĕqiyá֣̇hẇ ʼàşěr-ʻal-ha֠⁠bȧyiţ wĕ⁠şěbĕná֨ʼ ha⁠ṡwòpé֜r wĕ⁠ywòʼá֨ẖ bėn-ʼásá֧p ha⁠mȧzĕki֛̇yr ʼel-ẖizĕqiyá֖̇hẇ qĕrẇʻé֣y bĕgádi֑ym wa⁠yȧgi֣̇ydẇ l֔⁠wò ʼé֖ţ di̇bĕré֥y rab-şá̌qéֽh׃s"],[37,1,"וַ⁠יְהִ֗י כִּ⁠שְׁמֹ֨עַ֙ הַ⁠מֶּ֣לֶךְ חִזְקִיָּ֔הוּ וַ⁠יִּקְרַ֖ע אֶת־בְּגָדָ֑י⁠ו וַ⁠יִּתְכַּ֣ס בַּ⁠שָּׂ֔ק וַ⁠יָּבֹ֖א בֵּ֥ית יְהוָֽה׃","wa⁠yĕhi֗y ki̇⁠şĕ̌mò֨ʻa֙ ha⁠mė֣lekĕ ẖizĕqiyá̇֔hẇ wa⁠yi̇qĕra֖ʻ ʼeţ-bĕ̇gádá֑y⁠w wa⁠yi̇ţĕkȧ֣s bȧ⁠şá̇̂֔q wa⁠yá̇bò֖ʼ bé֥̇yţ yĕhwáֽh׃"],[37,2,"וַ֠⁠יִּשְׁלַח אֶת־אֶלְיָקִ֨ים אֲשֶׁר־עַל־הַ⁠בַּ֜יִת וְ⁠אֵ֣ת ׀ שֶׁבְנָ֣א הַ⁠סּוֹפֵ֗ר וְ⁠אֵת֙ זִקְנֵ֣י הַ⁠כֹּהֲנִ֔ים מִתְכַּסִּ֖ים בַּ⁠שַּׂקִּ֑ים אֶל־יְשַֽׁעְיָ֥הוּ בֶן־אָמ֖וֹץ הַ⁠נָּבִֽיא׃","wa֠⁠yi̇şĕ̌laẖ ʼeţ-ʼelĕyáqi֨ym ʼàşěr-ʻal-ha⁠bȧ֜yiţ wĕ⁠ʼé֣ţ ׀ şěbĕná֣ʼ ha⁠ṡwòpé֗r wĕ⁠ʼéţ֙ ziqĕné֣y ha⁠kò̇hàni֔ym miţĕkȧsi֖̇ym bȧ⁠şȧ̂qi֑̇ym ʼel-yĕşǎֽʻĕyá֥hẇ ben-ʼám֖wòẕ ha⁠ná̇biֽyʼ׃"],[37,3,"וַ⁠יֹּאמְר֣וּ אֵלָ֗י⁠ו כֹּ֚ה אָמַ֣ר חִזְקִיָּ֔הוּ יוֹם־צָרָ֧ה וְ⁠תוֹכֵחָ֛ה וּ⁠נְאָצָ֖ה הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה כִּ֣י בָ֤אוּ בָנִים֙ עַד־מַשְׁבֵּ֔ר וְ⁠כֹ֥חַ אַ֖יִן לְ⁠לֵדָֽה׃","wa⁠yò̇ʼmĕr֣ẇ ʼélá֗y⁠w kò֚̇h ʼáma֣r ẖizĕqiyá̇֔hẇ ywòm-ẕárá֧h wĕ⁠ţwòkéẖá֛h ẇ⁠nĕʼáẕá֖h ha⁠ẏ֣wòm ha⁠zė֑h ki֣̇y bá֤ʼẇ bániym֙ ʻad-maşĕ̌bé̇֔r wĕ⁠kò֥ẖa ʼa֖yin lĕ⁠lédáֽh׃"],[37,4,"אוּלַ֡י יִשְׁמַע֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ אֵ֣ת ׀ דִּבְרֵ֣י רַב־שָׁקֵ֗ה אֲשֶׁר֩ שְׁלָח֨⁠וֹ מֶֽלֶךְ־אַשּׁ֤וּר ׀ אֲדֹנָי⁠ו֙ לְ⁠חָרֵף֙ אֱלֹהִ֣ים חַ֔י וְ⁠הוֹכִ֨יחַ֙ בַּ⁠דְּבָרִ֔ים אֲשֶׁ֥ר שָׁמַ֖ע יְהוָ֣ה אֱלֹהֶ֑י⁠ךָ וְ⁠נָשָׂ֣אתָ תְפִלָּ֔ה בְּעַ֥ד הַ⁠שְּׁאֵרִ֖ית הַ⁠נִּמְצָאָֽה׃","ʼẇla֡y yişĕ̌maʻ֩ yĕhwá֨h ʼèlòhe֜y⁠ká ʼé֣ţ ׀ di̇bĕré֣y rab-şá̌qé֗h ʼàşěr֩ şĕ̌láẖ֨⁠wò meֽlekĕ-ʼaş֤̇̌ẇr ׀ ʼàdònáy⁠w֙ lĕ⁠ẖárép֙ ʼèlòhi֣ym ẖa֔y wĕ⁠hwòki֨yẖa֙ bȧ⁠dĕ̇bári֔ym ʼàşě֥r şá̌ma֖ʻ yĕhwá֣h ʼèlòhe֑y⁠ká wĕ⁠náşá֣̂ʼţá ţĕpilá̇֔h bĕ̇ʻa֥d ha⁠şĕ̇̌ʼéri֖yţ ha⁠ni̇mĕẕáʼáֽh׃"],[37,5,"וַ⁠יָּבֹ֗אוּ עַבְדֵ֛י הַ⁠מֶּ֥לֶךְ חִזְקִיָּ֖הוּ אֶל־יְשַׁעְיָֽהוּ׃","wa⁠yá̇bò֗ʼẇ ʻabĕdé֛y ha⁠mė֥lekĕ ẖizĕqiyá֖̇hẇ ʼel-yĕşǎʻĕyáֽhẇ׃"],[37,6,"וַ⁠יֹּ֤אמֶר אֲלֵי⁠הֶם֙ יְשַֽׁעְיָ֔הוּ כֹּ֥ה תֹאמְר֖וּ⁠ן אֶל־אֲדֹנֵי⁠כֶ֑ם כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה אַל־תִּירָא֙ מִ⁠פְּנֵ֤י הַ⁠דְּבָרִים֙ אֲשֶׁ֣ר שָׁמַ֔עְתָּ אֲשֶׁ֧ר גִּדְּפ֛וּ נַעֲרֵ֥י מֶלֶךְ־אַשּׁ֖וּר אוֹתִֽ⁠י׃","wa⁠yò֤̇ʼmer ʼàléy⁠hem֙ yĕşǎֽʻĕyá֔hẇ kò֥̇h ţòʼmĕr֖ẇ⁠n ʼel-ʼàdònéy⁠ke֑m kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʼal-ţi̇yráʼ֙ mi⁠pĕ̇né֤y ha⁠dĕ̇báriym֙ ʼàşě֣r şá̌ma֔ʻĕţá̇ ʼàşě֧r gi̇dĕ̇p֛ẇ naʻàré֥y melekĕ-ʼaş֖̇̌ẇr ʼwòţiֽ⁠y׃"],[37,7,"הִנְ⁠נִ֨י נוֹתֵ֥ן בּ⁠וֹ֙ ר֔וּחַ וְ⁠שָׁמַ֥ע שְׁמוּעָ֖ה וְ⁠שָׁ֣ב אֶל־אַרְצ֑⁠וֹ וְ⁠הִפַּלְתִּ֥י⁠ו בַּ⁠חֶ֖רֶב בְּ⁠אַרְצֽ⁠וֹ׃","hinĕ⁠ni֨y nwòţé֥n ḃ⁠wò֙ r֔ẇẖa wĕ⁠şá̌ma֥ʻ şĕ̌mẇʻá֖h wĕ⁠şá֣̌b ʼel-ʼarĕẕ֑⁠wò wĕ⁠hipȧlĕţi֥̇y⁠w bȧ⁠ẖe֖reb bĕ̇⁠ʼarĕẕֽ⁠wò׃"],[37,8,"וַ⁠יָּ֨שָׁב֙ רַב־שָׁקֵ֔ה וַ⁠יִּמְצָא֙ אֶת־מֶ֣לֶךְ אַשּׁ֔וּר נִלְחָ֖ם עַל־לִבְנָ֑ה כִּ֣י שָׁמַ֔ע כִּ֥י נָסַ֖ע מִ⁠לָּכִֽישׁ׃","wa⁠yá̇֨şá̌b֙ rab-şá̌qé֔h wa⁠yi̇mĕẕáʼ֙ ʼeţ-me֣lekĕ ʼaş̇̌֔ẇr nilĕẖá֖m ʻal-libĕná֑h ki֣̇y şá̌ma֔ʻ ki֥̇y nása֖ʻ mi⁠lá̇kiֽyş̌׃"],[37,9,"וַ⁠יִּשְׁמַ֗ע עַל־תִּרְהָ֤קָה מֶֽלֶךְ־כּוּשׁ֙ לֵ⁠אמֹ֔ר יָצָ֖א לְ⁠הִלָּחֵ֣ם אִתָּ֑⁠ךְ וַ⁠יִּשְׁמַע֙ וַ⁠יִּשְׁלַ֣ח מַלְאָכִ֔ים אֶל־חִזְקִיָּ֖הוּ לֵ⁠אמֹֽר׃","wa⁠yi̇şĕ̌ma֗ʻ ʻal-ţi̇rĕhá֤qáh meֽlekĕ-k̇ẇş̌֙ lé⁠ʼmò֔r yáẕá֖ʼ lĕ⁠hilá̇ẖé֣m ʼiţá֑̇⁠kĕ wa⁠yi̇şĕ̌maʻ֙ wa⁠yi̇şĕ̌la֣ẖ malĕʼáki֔ym ʼel-ẖizĕqiyá֖̇hẇ lé⁠ʼmòֽr׃"],[37,10,"כֹּ֣ה תֹאמְר֗וּ⁠ן אֶל־חִזְקִיָּ֤הוּ מֶֽלֶךְ־יְהוּדָה֙ לֵ⁠אמֹ֔ר אַל־יַשִּֽׁאֲ⁠ךָ֣ אֱלֹהֶ֔י⁠ךָ אֲשֶׁ֥ר אַתָּ֛ה בּוֹטֵ֥חַ בּ֖⁠וֹ לֵ⁠אמֹ֑ר לֹ֤א תִנָּתֵן֙ יְר֣וּשָׁלִַ֔ם בְּ⁠יַ֖ד מֶ֥לֶךְ אַשּֽׁוּר׃","kò֣̇h ţòʼmĕr֗ẇ⁠n ʼel-ẖizĕqiyá֤̇hẇ meֽlekĕ-yĕhẇdáh֙ lé⁠ʼmò֔r ʼal-yaşiֽ̇̌ʼà⁠ká֣ ʼèlòhe֔y⁠ká ʼàşě֥r ʼaţá֛̇h ḃwòté֥ẖa ḃ֖⁠wò lé⁠ʼmò֑r lò֤ʼ ţiná̇ţén֙ yĕr֣ẇşá̌lia֔m bĕ̇⁠ya֖d me֥lekĕ ʼaşֽ̇̌ẇr׃"],[37,11,"הִנֵּ֣ה ׀ אַתָּ֣ה שָׁמַ֗עְתָּ אֲשֶׁ֨ר עָשׂ֜וּ מַלְכֵ֥י אַשּׁ֛וּר לְ⁠כָל־הָ⁠אֲרָצ֖וֹת לְ⁠הַחֲרִימָ֑⁠ם וְ⁠אַתָּ֖ה תִּנָּצֵֽל׃","hiné֣̇h ׀ ʼaţá֣̇h şá̌ma֗ʻĕţá̇ ʼàşě֨r ʻáş̂֜ẇ malĕké֥y ʼaş֛̇̌ẇr lĕ⁠kál-há⁠ʼàráẕ֖wòţ lĕ⁠haẖàriymá֑⁠m wĕ⁠ʼaţá֖̇h ţi̇ná̇ẕéֽl׃"],[37,12,"הַ⁠הִצִּ֨ילוּ אוֹתָ֜⁠ם אֱלֹהֵ֤י הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר הִשְׁחִ֣יתוּ אֲבוֹתַ֔⁠י אֶת־גּוֹזָ֖ן וְ⁠אֶת־חָרָ֑ן וְ⁠רֶ֥צֶף וּ⁠בְנֵי־עֶ֖דֶן אֲשֶׁ֥ר בִּ⁠תְלַשָּֽׂר׃","ha⁠hiẕi̇֨ylẇ ʼwòţá֜⁠m ʼèlòhé֤y ha⁠ġwòyim֙ ʼàşě֣r hişĕ̌ẖi֣yţẇ ʼàbwòţa֔⁠y ʼeţ-ġwòzá֖n wĕ⁠ʼeţ-ẖárá֑n wĕ⁠re֥ẕep ẇ⁠bĕnéy-ʻe֖den ʼàşě֥r bi̇⁠ţĕlaşáֽ̇̂r׃"],[37,13,"אַיֵּ֤ה מֶֽלֶךְ־חֲמָת֙ וּ⁠מֶ֣לֶךְ אַרְפָּ֔ד וּ⁠מֶ֖לֶךְ לָעִ֣יר סְפַרְוָ֑יִם הֵנַ֖ע וְ⁠עִוָּֽה׃","ʼayé֤̇h meֽlekĕ-ẖàmáţ֙ ẇ⁠me֣lekĕ ʼarĕpá̇֔d ẇ⁠me֖lekĕ láʻi֣yr sĕparĕwá֑yim héna֖ʻ wĕ⁠ʻiwáֽ̇h׃"],[37,14,"וַ⁠יִּקַּ֨ח חִזְקִיָּ֧הוּ אֶת־הַ⁠סְּפָרִ֛ים מִ⁠יַּ֥ד הַ⁠מַּלְאָכִ֖ים וַ⁠יִּקְרָאֵ֑⁠הוּ וַ⁠יַּ֨עַל֙ בֵּ֣ית יְהוָ֔ה וַ⁠יִּפְרְשֵׂ֥⁠הוּ חִזְקִיָּ֖הוּ לִ⁠פְנֵ֥י יְהוָֽה׃","wa⁠yi̇qȧ֨ẖ ẖizĕqiyá֧̇hẇ ʼeţ-ha⁠sĕ̇pári֛ym mi⁠yȧ֥d ha⁠mȧlĕʼáki֖ym wa⁠yi̇qĕráʼé֑⁠hẇ wa⁠yȧ֨ʻal֙ bé֣̇yţ yĕhwá֔h wa⁠yi̇pĕrĕşé֥̂⁠hẇ ẖizĕqiyá֖̇hẇ li⁠pĕné֥y yĕhwáֽh׃"],[37,15,"וַ⁠יִּתְפַּלֵּל֙ חִזְקִיָּ֔הוּ אֶל־יְהוָ֖ה לֵ⁠אמֹֽר׃","wa⁠yi̇ţĕpȧlé̇l֙ ẖizĕqiyá̇֔hẇ ʼel-yĕhwá֖h lé⁠ʼmòֽr׃"],[37,16,"יְהוָ֨ה צְבָא֜וֹת אֱלֹהֵ֤י יִשְׂרָאֵל֙ יֹשֵׁ֣ב הַ⁠כְּרֻבִ֔ים אַתָּה־ה֤וּא הָֽ⁠אֱלֹהִים֙ לְ⁠בַדְּ⁠ךָ֔ לְ⁠כֹ֖ל מַמְלְכ֣וֹת הָ⁠אָ֑רֶץ אַתָּ֣ה עָשִׂ֔יתָ אֶת־הַ⁠שָּׁמַ֖יִם וְ⁠אֶת־הָ⁠אָֽרֶץ׃","yĕhwá֨h ẕĕbáʼ֜wòţ ʼèlòhé֤y yişĕ̂ráʼél֙ yòşé֣̌b ha⁠kĕ̇rubi֔ym ʼaţá̇h-h֤ẇʼ háֽ⁠ʼèlòhiym֙ lĕ⁠badĕ̇⁠ká֔ lĕ⁠kò֖l mamĕlĕk֣wòţ há⁠ʼá֑reẕ ʼaţá֣̇h ʻáşî֔yţá ʼeţ-ha⁠şá̇̌ma֖yim wĕ⁠ʼeţ-há⁠ʼáֽreẕ׃"],[37,17,"הַטֵּ֨ה יְהוָ֤ה ׀ אָזְנְ⁠ךָ֙ וּֽ⁠שְׁמָ֔ע פְּקַ֧ח יְהוָ֛ה עֵינֶ֖⁠ךָ וּ⁠רְאֵ֑ה וּ⁠שְׁמַ֗ע אֵ֚ת כָּל־דִּבְרֵ֣י סַנְחֵרִ֔יב אֲשֶׁ֣ר שָׁלַ֔ח לְ⁠חָרֵ֖ף אֱלֹהִ֥ים חָֽי׃","haté̇֨h yĕhwá֤h ׀ ʼázĕnĕ⁠ká֙ ẇֽ⁠şĕ̌má֔ʻ pĕ̇qa֧ẖ yĕhwá֛h ʻéyne֖⁠ká ẇ⁠rĕʼé֑h ẇ⁠şĕ̌ma֗ʻ ʼé֚ţ ká̇l-di̇bĕré֣y sanĕẖéri֔yb ʼàşě֣r şá̌la֔ẖ lĕ⁠ẖáré֖p ʼèlòhi֥ym ẖáֽy׃"],[37,18,"אָמְנָ֖ם יְהוָ֑ה הֶחֱרִ֜יבוּ מַלְכֵ֥י אַשּׁ֛וּר אֶת־כָּל־הָ⁠אֲרָצ֖וֹת וְ⁠אֶת־אַרְצָֽ⁠ם׃","ʼámĕná֖m yĕhwá֑h heẖèri֜ybẇ malĕké֥y ʼaş֛̇̌ẇr ʼeţ-ká̇l-há⁠ʼàráẕ֖wòţ wĕ⁠ʼeţ-ʼarĕẕáֽ⁠m׃"],[37,19,"וְ⁠נָתֹ֥ן אֶת־אֱלֹהֵי⁠הֶ֖ם בָּ⁠אֵ֑שׁ כִּי֩ לֹ֨א אֱלֹהִ֜ים הֵ֗מָּה כִּ֣י אִם־מַעֲשֵׂ֧ה יְדֵֽי־אָדָ֛ם עֵ֥ץ וָ⁠אֶ֖בֶן וַֽ⁠יְאַבְּדֽוּ⁠ם׃","wĕ⁠náţò֥n ʼeţ-ʼèlòhéy⁠he֖m bá̇⁠ʼé֑ş̌ ki̇y֩ lò֨ʼ ʼèlòhi֜ym hé֗má̇h ki֣̇y ʼim-maʻàşé֧̂h yĕdéֽy-ʼádá֛m ʻé֥ẕ wá⁠ʼe֖ben waֽ⁠yĕʼabĕ̇dֽẇ⁠m׃"],[37,20,"וְ⁠עַתָּה֙ יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ הוֹשִׁיעֵ֖⁠נוּ מִ⁠יָד֑⁠וֹ וְ⁠יֵֽדְעוּ֙ כָּל־מַמְלְכ֣וֹת הָ⁠אָ֔רֶץ כִּֽי־אַתָּ֥ה יְהוָ֖ה לְ⁠בַדֶּֽ⁠ךָ׃","wĕ⁠ʻaţá̇h֙ yĕhwá֣h ʼèlòhé֔y⁠nẇ hwòşǐyʻé֖⁠nẇ mi⁠yád֑⁠wò wĕ⁠yéֽdĕʻẇ֙ ká̇l-mamĕlĕk֣wòţ há⁠ʼá֔reẕ kiֽ̇y-ʼaţá֥̇h yĕhwá֖h lĕ⁠badėֽ⁠ká׃"],[37,21,"וַ⁠יִּשְׁלַח֙ יְשַֽׁעְיָ֣הוּ בֶן־אָמ֔וֹץ אֶל־חִזְקִיָּ֖הוּ לֵ⁠אמֹ֑ר כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁר֙ הִתְפַּלַּ֣לְתָּ אֵלַ֔⁠י אֶל־סַנְחֵרִ֖יב מֶ֥לֶךְ אַשּֽׁוּר׃","wa⁠yi̇şĕ̌laẖ֙ yĕşǎֽʻĕyá֣hẇ ben-ʼám֔wòẕ ʼel-ẖizĕqiyá֖̇hẇ lé⁠ʼmò֑r kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼàşěr֙ hiţĕpȧlȧ֣lĕţá̇ ʼéla֔⁠y ʼel-sanĕẖéri֖yb me֥lekĕ ʼaşֽ̇̌ẇr׃"],[37,22,"זֶ֣ה הַ⁠דָּבָ֔ר אֲשֶׁר־דִּבֶּ֥ר יְהוָ֖ה עָלָ֑י⁠ו בָּזָ֨ה לְ⁠ךָ֜ לָעֲגָ֣ה לְ⁠ךָ֗ בְּתוּלַת֙ בַּת־צִיּ֔וֹן אַחֲרֶ֨י⁠ךָ֙ רֹ֣אשׁ הֵנִ֔יעָה בַּ֖ת יְרוּשָׁלִָֽם׃","ze֣h ha⁠dá̇bá֔r ʼàşěr-di̇bė֥r yĕhwá֖h ʻálá֑y⁠w bá̇zá֨h lĕ⁠ká֜ láʻàgá֣h lĕ⁠ká֗ bĕ̇ţẇlaţ֙ bȧţ-ẕiẏ֔wòn ʼaẖàre֨y⁠ká֙ rò֣ʼş̌ héni֔yʻáh bȧ֖ţ yĕrẇşá̌liáֽm׃"],[37,23,"אֶת־מִ֤י חֵרַ֨פְתָּ֙ וְ⁠גִדַּ֔פְתָּ וְ⁠עַל־מִ֖י הֲרִימ֣וֹתָה קּ֑וֹל וַ⁠תִּשָּׂ֥א מָר֛וֹם עֵינֶ֖י⁠ךָ אֶל־קְד֥וֹשׁ יִשְׂרָאֵֽל׃","ʼeţ-mi֤y ẖéra֨pĕţá̇֙ wĕ⁠gidȧ֔pĕţá̇ wĕ⁠ʻal-mi֖y hàriym֣wòţáh q֑̇wòl wa⁠ţi̇şá֥̇̂ʼ már֛wòm ʻéyne֖y⁠ká ʼel-qĕd֥wòş̌ yişĕ̂ráʼéֽl׃"],[37,24,"בְּ⁠יַ֣ד עֲבָדֶי⁠ךָ֮ חֵרַ֣פְתָּ ׀ אֲדֹנָ⁠י֒ וַ⁠תֹּ֗אמֶר בְּ⁠רֹ֥ב רִכְבִּ֛⁠י אֲנִ֥י עָלִ֛יתִי מְר֥וֹם הָרִ֖ים יַרְכְּתֵ֣י לְבָנ֑וֹן וְ⁠אֶכְרֹ֞ת קוֹמַ֤ת אֲרָזָי⁠ו֙ מִבְחַ֣ר בְּרֹשָׁ֔י⁠ו וְ⁠אָבוֹא֙ מְר֣וֹם קִצּ֔⁠וֹ יַ֖עַר כַּרְמִלּֽ⁠וֹ׃","bĕ̇⁠ya֣d ʻàbádey⁠ká֮ ẖéra֣pĕţá̇ ׀ ʼàdòná⁠y֒ wa⁠ţò̇֗ʼmer bĕ̇⁠rò֥b rikĕbi֛̇⁠y ʼàni֥y ʻáli֛yţiy mĕr֥wòm hári֖ym yarĕkĕ̇ţé֣y lĕbán֑wòn wĕ⁠ʼekĕrò֞ţ qwòma֤ţ ʼàrázáy⁠w֙ mibĕẖa֣r bĕ̇ròşá̌֔y⁠w wĕ⁠ʼábwòʼ֙ mĕr֣wòm qiẕ̇֔⁠wò ya֖ʻar kȧrĕmilֽ̇⁠wò׃"],[37,25,"אֲנִ֥י קַ֖רְתִּי וְ⁠שָׁתִ֣יתִי מָ֑יִם וְ⁠אַחְרִב֙ בְּ⁠כַף־פְּעָמַ֔⁠י כֹּ֖ל יְאֹרֵ֥י מָצֽוֹר׃","ʼàni֥y qa֖rĕţi̇y wĕ⁠şá̌ţi֣yţiy má֑yim wĕ⁠ʼaẖĕrib֙ bĕ̇⁠kap-pĕ̇ʻáma֔⁠y kò֖̇l yĕʼòré֥y máẕֽwòr׃"],[37,26,"הֲ⁠לֽוֹא־שָׁמַ֤עְתָּ לְ⁠מֵֽ⁠רָחוֹק֙ אוֹתָ֣⁠הּ עָשִׂ֔יתִי מִ֥⁠ימֵי קֶ֖דֶם וִ⁠יצַרְתִּ֑י⁠הָ עַתָּ֣ה הֲבֵאתִ֔י⁠הָ וּ⁠תְהִ֗י לְ⁠הַשְׁא֛וֹת גַּלִּ֥ים נִצִּ֖ים עָרִ֥ים בְּצֻרֽוֹת׃","hà⁠lֽwòʼ-şá̌ma֤ʻĕţá̇ lĕ⁠méֽ⁠ráẖwòq֙ ʼwòţá֣⁠ḣ ʻáşî֔yţiy mi֥⁠yméy qe֖dem wi⁠yẕarĕţi֑̇y⁠há ʻaţá֣̇h hàbéʼţi֔y⁠há ẇ⁠ţĕhi֗y lĕ⁠haşĕ̌ʼ֛wòţ gȧli֥̇ym niẕi֖̇ym ʻári֥ym bĕ̇ẕurֽwòţ׃"],[37,27,"וְ⁠יֹֽשְׁבֵי⁠הֶן֙ קִצְרֵי־יָ֔ד חַ֖תּוּ וָ⁠בֹ֑שׁוּ הָי֞וּ עֵ֤שֶׂב שָׂדֶה֙ וִ֣⁠ירַק דֶּ֔שֶׁא חֲצִ֣יר גַּגּ֔וֹת וּ⁠שְׁדֵמָ֖ה לִ⁠פְנֵ֥י קָמָֽה׃","wĕ⁠yòֽşĕ̌béy⁠hen֙ qiẕĕréy-yá֔d ẖa֖ţ̇ẇ wá⁠bò֑ş̌ẇ háy֞ẇ ʻé֤şêb şá̂deh֙ wi֣⁠yraq dė֔şěʼ ẖàẕi֣yr gȧġ֔wòţ ẇ⁠şĕ̌démá֖h li⁠pĕné֥y qámáֽh׃"],[37,28,"וְ⁠שִׁבְתְּ⁠ךָ֛ וְ⁠צֵאתְ⁠ךָ֥ וּ⁠בוֹאֲ⁠ךָ֖ יָדָ֑עְתִּי וְ⁠אֵ֖ת הִֽתְרַגֶּזְ⁠ךָ֥ אֵלָֽ⁠י׃","wĕ⁠şǐbĕţĕ̇⁠ká֛ wĕ⁠ẕéʼţĕ⁠ká֥ ẇ⁠bwòʼà⁠ká֖ yádá֑ʻĕţi̇y wĕ⁠ʼé֖ţ hiֽţĕragėzĕ⁠ká֥ ʼéláֽ⁠y׃"],[37,29,"יַ֚עַן הִתְרַגֶּזְ⁠ךָ֣ אֵלַ֔⁠י וְ⁠שַׁאֲנַנְ⁠ךָ֖ עָלָ֣ה בְ⁠אָזְנָ֑⁠י וְ⁠שַׂמְתִּ֨י חַחִ֜⁠י בְּ⁠אַפֶּ֗⁠ךָ וּ⁠מִתְגִּ⁠י֙ בִּ⁠שְׂפָתֶ֔י⁠ךָ וַ⁠הֲשִׁ֣יבֹתִ֔י⁠ךָ בַּ⁠דֶּ֖רֶךְ אֲשֶׁר־בָּ֥אתָ בָּֽ⁠הּ׃","ya֚ʻan hiţĕragėzĕ⁠ká֣ ʼéla֔⁠y wĕ⁠şǎʼànanĕ⁠ká֖ ʻálá֣h bĕ⁠ʼázĕná֑⁠y wĕ⁠şâmĕţi̇֨y ẖaẖi֜⁠y bĕ̇⁠ʼapė֗⁠ká ẇ⁠miţĕgi̇⁠y֙ bi̇⁠şĕ̂páţe֔y⁠ká wa⁠hàşǐ֣ybòţi֔y⁠ká bȧ⁠dė֖rekĕ ʼàşěr-bá֥̇ʼţá báֽ̇⁠ḣ׃"],[37,30,"וְ⁠זֶה־לְּ⁠ךָ֣ הָ⁠א֔וֹת אָכ֤וֹל הַ⁠שָּׁנָה֙ סָפִ֔יחַ וּ⁠בַ⁠שָּׁנָ֥ה הַ⁠שֵּׁנִ֖ית שָׁחִ֑יס וּ⁠בַ⁠שָּׁנָ֣ה הַ⁠שְּׁלִישִׁ֗ית זִרְע֧וּ וְ⁠קִצְר֛וּ וְ⁠נִטְע֥וּ כְרָמִ֖ים ו⁠אכול פִרְיָֽ⁠ם׃","wĕ⁠zeh-lĕ̇⁠ká֣ há⁠ʼ֔wòţ ʼák֤wòl ha⁠şá̇̌náh֙ sápi֔yẖa ẇ⁠ba⁠şá̇̌ná֥h ha⁠şé̇̌ni֖yţ şá̌ẖi֑ys ẇ⁠ba⁠şá̇̌ná֣h ha⁠şĕ̇̌liyşǐ֗yţ zirĕʻ֧ẇ wĕ⁠qiẕĕr֛ẇ wĕ⁠nitĕʻ֥ẇ kĕrámi֖ym w⁠ʼkwl pirĕyáֽ⁠m׃"],[37,31,"וְ⁠יָ֨סְפָ֜ה פְּלֵיטַ֧ת בֵּית־יְהוּדָ֛ה הַ⁠נִּשְׁאָרָ֖ה שֹׁ֣רֶשׁ לְ⁠מָ֑טָּה וְ⁠עָשָׂ֥ה פְרִ֖י לְ⁠מָֽעְלָ⁠ה׃","wĕ⁠yá֨sĕpá֜h pĕ̇léyta֧ţ bé̇yţ-yĕhẇdá֛h ha⁠ni̇şĕ̌ʼárá֖h şò֣̌reş̌ lĕ⁠má֑tá̇h wĕ⁠ʻáşá֥̂h pĕri֖y lĕ⁠máֽʻĕlá⁠h׃"],[37,32,"כִּ֤י מִ⁠ירֽוּשָׁלִַ֨ם֙ תֵּצֵ֣א שְׁאֵרִ֔ית וּ⁠פְלֵיטָ֖ה מֵ⁠הַ֣ר צִיּ֑וֹן קִנְאַ֛ת יְהוָ֥ה צְבָא֖וֹת תַּֽעֲשֶׂה־זֹּֽאת׃ס","ki֤̇y mi⁠yrֽẇşá̌lia֨m֙ ţé̇ẕé֣ʼ şĕ̌ʼéri֔yţ ẇ⁠pĕléytá֖h mé⁠ha֣r ẕiẏ֑wòn qinĕʼa֛ţ yĕhwá֥h ẕĕbáʼ֖wòţ ţȧֽʻàşêh-zòֽ̇ʼţ׃s"],[37,33,"לָ⁠כֵ֗ן כֹּֽה־אָמַ֤ר יְהוָה֙ אֶל־מֶ֣לֶךְ אַשּׁ֔וּר לֹ֤א יָבוֹא֙ אֶל־הָ⁠עִ֣יר הַ⁠זֹּ֔את וְ⁠לֹֽא־יוֹרֶ֥ה שָׁ֖ם חֵ֑ץ וְ⁠לֹֽא־יְקַדְּמֶ֣⁠נָּה מָגֵ֔ן וְ⁠לֹֽא־יִשְׁפֹּ֥ךְ עֳלֶ֖י⁠הָ סֹלְלָֽה׃","lá⁠ké֗n kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼel-me֣lekĕ ʼaş̇̌֔ẇr lò֤ʼ yábwòʼ֙ ʼel-há⁠ʻi֣yr ha⁠zò̇֔ʼţ wĕ⁠lòֽʼ-ywòre֥h şá֖̌m ẖé֑ẕ wĕ⁠lòֽʼ-yĕqadĕ̇me֣⁠ná̇h mágé֔n wĕ⁠lòֽʼ-yişĕ̌pò֥̇kĕ ʻole֖y⁠há sòlĕláֽh׃"],[37,34,"בַּ⁠דֶּ֥רֶךְ אֲשֶׁר־בָּ֖א בָּ֣⁠הּ יָשׁ֑וּב וְ⁠אֶל־הָ⁠עִ֥יר הַ⁠זֹּ֛את לֹ֥א יָב֖וֹא נְאֻם־יְהוָֽה׃","bȧ⁠dė֥rekĕ ʼàşěr-bá֖̇ʼ bá֣̇⁠ḣ yáş֑̌ẇb wĕ⁠ʼel-há⁠ʻi֥yr ha⁠zò֛̇ʼţ lò֥ʼ yáb֖wòʼ nĕʼum-yĕhwáֽh׃"],[37,35,"וְ⁠גַנּוֹתִ֛י עַל־הָ⁠עִ֥יר הַ⁠זֹּ֖את לְ⁠הֽוֹשִׁיעָ֑⁠הּ לְמַֽעֲנִ֔⁠י וּ⁠לְמַ֖עַן דָּוִ֥ד עַבְדִּֽ⁠י׃ס","wĕ⁠gaṅwòţi֛y ʻal-há⁠ʻi֥yr ha⁠zò֖̇ʼţ lĕ⁠hֽwòşǐyʻá֑⁠ḣ lĕmaֽʻàni֔⁠y ẇ⁠lĕma֖ʻan dá̇wi֥d ʻabĕdiֽ̇⁠y׃s"],[37,36,"וַ⁠יֵּצֵ֣א ׀ מַלְאַ֣ךְ יְהוָ֗ה וַ⁠יַּכֶּה֙ בְּ⁠מַחֲנֵ֣ה אַשּׁ֔וּר מֵאָ֛ה וּ⁠שְׁמֹנִ֥ים וַ⁠חֲמִשָּׁ֖ה אָ֑לֶף וַ⁠יַּשְׁכִּ֣ימוּ בַ⁠בֹּ֔קֶר וְ⁠הִנֵּ֥ה כֻלָּ֖⁠ם פְּגָרִ֥ים מֵתִֽים׃","wa⁠yé̇ẕé֣ʼ ׀ malĕʼa֣kĕ yĕhwá֗h wa⁠yȧkėh֙ bĕ̇⁠maẖàné֣h ʼaş̇̌֔ẇr méʼá֛h ẇ⁠şĕ̌mòni֥ym wa⁠ẖàmişá֖̇̌h ʼá֑lep wa⁠yȧşĕ̌ki֣̇ymẇ ba⁠bò̇֔qer wĕ⁠hiné֥̇h kulá֖̇⁠m pĕ̇gári֥ym méţiֽym׃"],[37,37,"וַ⁠יִּסַּ֣ע וַ⁠יֵּ֔לֶךְ וַ⁠יָּ֖שָׁב סַנְחֵרִ֣יב מֶֽלֶךְ־אַשּׁ֑וּר וַ⁠יֵּ֖שֶׁב בְּ⁠נִֽינְוֵֽה׃","wa⁠yi̇sȧ֣ʻ wa⁠yé̇֔lekĕ wa⁠yá֖̇şá̌b sanĕẖéri֣yb meֽlekĕ-ʼaş֑̇̌ẇr wa⁠yé֖̇şěb bĕ̇⁠niֽynĕwéֽh׃"],[37,38,"וַ⁠יְהִי֩ ה֨וּא מִֽשְׁתַּחֲוֶ֜ה בֵּ֣ית ׀ נִסְרֹ֣ךְ אֱלֹהָ֗י⁠ו וְֽ⁠אַדְרַמֶּ֨לֶךְ וְ⁠שַׂרְאֶ֤צֶר בָּנָי⁠ו֙ הִכֻּ֣⁠הוּ בַ⁠חֶ֔רֶב וְ⁠הֵ֥מָּה נִמְלְט֖וּ אֶ֣רֶץ אֲרָרָ֑ט וַ⁠יִּמְלֹ֛ךְ אֵֽסַר־חַדֹּ֥ן בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃ס","wa⁠yĕhiy֩ h֨ẇʼ miֽşĕ̌ţȧẖàwe֜h bé֣̇yţ ׀ nisĕrò֣kĕ ʼèlòhá֗y⁠w wĕֽ⁠ʼadĕramė֨lekĕ wĕ⁠şârĕʼe֤ẕer bá̇náy⁠w֙ hiku֣̇⁠hẇ ba⁠ẖe֔reb wĕ⁠hé֥má̇h nimĕlĕt֖ẇ ʼe֣reẕ ʼàrárá֑t wa⁠yi̇mĕlò֛kĕ ʼéֽsar-ẖadò֥̇n bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃s"],[38,1,"בַּ⁠יָּמִ֣ים הָ⁠הֵ֔ם חָלָ֥ה חִזְקִיָּ֖הוּ לָ⁠מ֑וּת וַ⁠יָּב֣וֹא אֵ֠לָי⁠ו יְשַׁעְיָ֨הוּ בֶן־אָמ֜וֹץ הַ⁠נָּבִ֗יא וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו כֹּֽה־אָמַ֤ר יְהוָה֙ צַ֣ו לְ⁠בֵיתֶ֔⁠ךָ כִּ֛י מֵ֥ת אַתָּ֖ה וְ⁠לֹ֥א תִֽחְיֶֽה׃","bȧ⁠yá̇mi֣ym há⁠hé֔m ẖálá֥h ẖizĕqiyá֖̇hẇ lá⁠m֑ẇţ wa⁠yá̇b֣wòʼ ʼé֠láy⁠w yĕşǎʻĕyá֨hẇ ben-ʼám֜wòẕ ha⁠ná̇bi֗yʼ wa⁠yò̇֨ʼmer ʼélá֜y⁠w kòֽ̇h-ʼáma֤r yĕhwáh֙ ẕa֣w lĕ⁠béyţe֔⁠ká ki֛̇y mé֥ţ ʼaţá֖̇h wĕ⁠lò֥ʼ ţiֽẖĕyeֽh׃"],[38,2,"וַ⁠יַּסֵּ֧ב חִזְקִיָּ֛הוּ פָּנָ֖י⁠ו אֶל־הַ⁠קִּ֑יר וַ⁠יִּתְפַּלֵּ֖ל אֶל־יְהוָֽה׃","wa⁠yȧsé֧̇b ẖizĕqiyá֛̇hẇ pá̇ná֖y⁠w ʼel-ha⁠qi֑̇yr wa⁠yi̇ţĕpȧlé֖̇l ʼel-yĕhwáֽh׃"],[38,3,"וַ⁠יֹּאמַ֗ר אָנָּ֤ה יְהוָה֙ זְכָר־נָ֞א אֵ֣ת אֲשֶׁ֧ר הִתְהַלַּ֣כְתִּי לְ⁠פָנֶ֗י⁠ךָ בֶּֽ⁠אֱמֶת֙ וּ⁠בְ⁠לֵ֣ב שָׁלֵ֔ם וְ⁠הַ⁠טּ֥וֹב בְּ⁠עֵינֶ֖י⁠ךָ עָשִׂ֑יתִי וַ⁠יֵּ֥בְךְּ חִזְקִיָּ֖הוּ בְּכִ֥י גָדֽוֹל׃ס","wa⁠yò̇ʼma֗r ʼáná֤̇h yĕhwáh֙ zĕkár-ná֞ʼ ʼé֣ţ ʼàşě֧r hiţĕhalȧ֣kĕţi̇y lĕ⁠páne֗y⁠ká bėֽ⁠ʼèmeţ֙ ẇ⁠bĕ⁠lé֣b şá̌lé֔m wĕ⁠ha⁠ṫ֥wòb bĕ̇⁠ʻéyne֖y⁠ká ʻáşî֑yţiy wa⁠yé֥̇bĕkĕ̇ ẖizĕqiyá֖̇hẇ bĕ̇ki֥y gádֽwòl׃s"],[38,4,"וַֽ⁠יְהִי֙ דְּבַר־יְהוָ֔ה אֶֽל־יְשַׁעְיָ֖הוּ לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ dĕ̇bar-yĕhwá֔h ʼeֽl-yĕşǎʻĕyá֖hẇ lé⁠ʼmòֽr׃"],[38,5,"הָל֞וֹךְ וְ⁠אָמַרְתָּ֣ אֶל־חִזְקִיָּ֗הוּ כֹּֽה־אָמַ֤ר יְהוָה֙ אֱלֹהֵי֙ דָּוִ֣ד אָבִ֔י⁠ךָ שָׁמַ֨עְתִּי֙ אֶת־תְּפִלָּתֶ֔⁠ךָ רָאִ֖יתִי אֶת־דִּמְעָתֶ֑⁠ךָ הִנְ⁠נִי֙ יוֹסִ֣ף עַל־יָמֶ֔י⁠ךָ חֲמֵ֥שׁ עֶשְׂרֵ֖ה שָׁנָֽה׃","hál֞wòkĕ wĕ⁠ʼámarĕţá֣̇ ʼel-ẖizĕqiyá̇֗hẇ kòֽ̇h-ʼáma֤r yĕhwáh֙ ʼèlòhéy֙ dá̇wi֣d ʼábi֔y⁠ká şá̌ma֨ʻĕţi̇y֙ ʼeţ-ţĕ̇pilá̇ţe֔⁠ká ráʼi֖yţiy ʼeţ-di̇mĕʻáţe֑⁠ká hinĕ⁠niy֙ ywòsi֣p ʻal-yáme֔y⁠ká ẖàmé֥ş̌ ʻeşĕ̂ré֖h şá̌náֽh׃"],[38,6,"וּ⁠מִ⁠כַּ֤ף מֶֽלֶךְ־אַשּׁוּר֙ אַצִּ֣ילְ⁠ךָ֔ וְ⁠אֵ֖ת הָ⁠עִ֣יר הַ⁠זֹּ֑את וְ⁠גַנּוֹתִ֖י עַל־הָ⁠עִ֥יר הַ⁠זֹּֽאת׃","ẇ⁠mi⁠kȧ֤p meֽlekĕ-ʼaş̇̌ẇr֙ ʼaẕi֣̇ylĕ⁠ká֔ wĕ⁠ʼé֖ţ há⁠ʻi֣yr ha⁠zò֑̇ʼţ wĕ⁠gaṅwòţi֖y ʻal-há⁠ʻi֥yr ha⁠zòֽ̇ʼţ׃"],[38,7,"וְ⁠זֶה־לְּ⁠ךָ֥ הָ⁠א֖וֹת מֵ⁠אֵ֣ת יְהוָ֑ה אֲשֶׁר֙ יַעֲשֶׂ֣ה יְהוָ֔ה אֶת־הַ⁠דָּבָ֥ר הַ⁠זֶּ֖ה אֲשֶׁ֥ר דִּבֵּֽר׃","wĕ⁠zeh-lĕ̇⁠ká֥ há⁠ʼ֖wòţ mé⁠ʼé֣ţ yĕhwá֑h ʼàşěr֙ yaʻàşê֣h yĕhwá֔h ʼeţ-ha⁠dá̇bá֥r ha⁠zė֖h ʼàşě֥r di̇béֽ̇r׃"],[38,8,"הִנְ⁠נִ֣י מֵשִׁ֣יב אֶת־צֵ֣ל הַֽ⁠מַּעֲל֡וֹת אֲשֶׁ֣ר יָרְדָה֩ בְ⁠מַעֲל֨וֹת אָחָ֥ז בַּ⁠שֶּׁ֛מֶשׁ אֲחֹרַנִּ֖ית עֶ֣שֶׂר מַעֲל֑וֹת וַ⁠תָּ֤שָׁב הַ⁠שֶּׁ֨מֶשׁ֙ עֶ֣שֶׂר מַעֲל֔וֹת בַּֽ⁠מַּעֲל֖וֹת אֲשֶׁ֥ר יָרָֽדָה׃ס","hinĕ⁠ni֣y méşǐ֣yb ʼeţ-ẕé֣l haֽ⁠mȧʻàl֡wòţ ʼàşě֣r yárĕdáh֩ bĕ⁠maʻàl֨wòţ ʼáẖá֥z bȧ⁠şė֛̌meş̌ ʼàẖòrani֖̇yţ ʻe֣şêr maʻàl֑wòţ wa⁠ţá֤̇şá̌b ha⁠şė̌֨meş̌֙ ʻe֣şêr maʻàl֔wòţ bȧֽ⁠mȧʻàl֖wòţ ʼàşě֥r yáráֽdáh׃s"],[38,9,"מִכְתָּ֖ב לְ⁠חִזְקִיָּ֣הוּ מֶֽלֶךְ־יְהוּדָ֑ה בַּ⁠חֲלֹת֕⁠וֹ וַ⁠יְחִ֖י מֵ⁠חָלְיֽ⁠וֹ׃","mikĕţá֖̇b lĕ⁠ẖizĕqiyá֣̇hẇ meֽlekĕ-yĕhẇdá֑h bȧ⁠ẖàlòţ֕⁠wò wa⁠yĕẖi֖y mé⁠ẖálĕyֽ⁠wò׃"],[38,10,"אֲנִ֣י אָמַ֗רְתִּי בִּ⁠דְמִ֥י יָמַ֛⁠י אֵלֵ֖כָה בְּ⁠שַׁעֲרֵ֣י שְׁא֑וֹל פֻּקַּ֖דְתִּי יֶ֥תֶר שְׁנוֹתָֽ⁠י׃","ʼàni֣y ʼáma֗rĕţi̇y bi̇⁠dĕmi֥y yáma֛⁠y ʼélé֖káh bĕ̇⁠şǎʻàré֣y şĕ̌ʼ֑wòl pu̇qȧ֖dĕţi̇y ye֥ţer şĕ̌nwòţáֽ⁠y׃"],[38,11,"אָמַ֨רְתִּי֙ לֹא־אֶרְאֶ֣ה יָ֔הּ יָ֖הּ בְּ⁠אֶ֣רֶץ הַ⁠חַיִּ֑ים לֹא־אַבִּ֥יט אָדָ֛ם ע֖וֹד עִם־י֥וֹשְׁבֵי חָֽדֶל׃","ʼáma֨rĕţi̇y֙ lòʼ-ʼerĕʼe֣h yá֔ḣ yá֖ḣ bĕ̇⁠ʼe֣reẕ ha⁠ẖayi֑̇ym lòʼ-ʼabi֥̇yt ʼádá֛m ʻ֖wòd ʻim-y֥wòşĕ̌béy ẖáֽdel׃"],[38,12,"דּוֹרִ֗⁠י נִסַּ֧ע וְ⁠נִגְלָ֛ה מִ⁠נִּ֖י כְּ⁠אֹ֣הֶל רֹעִ֑⁠י קִפַּ֨דְתִּי כָ⁠אֹרֵ֤ג חַיַּ⁠י֙ מִ⁠דַּלָּ֣ה יְבַצְּעֵ֔⁠נִי מִ⁠יּ֥וֹם עַד־לַ֖יְלָה תַּשְׁלִימֵֽ⁠נִי׃","ḋwòri֗⁠y nisȧ֧ʻ wĕ⁠nigĕlá֛h mi⁠ni֖̇y kĕ̇⁠ʼò֣hel ròʻi֑⁠y qipȧ֨dĕţi̇y ká⁠ʼòré֤g ẖayȧ⁠y֙ mi⁠dȧlá֣̇h yĕbaẕĕ̇ʻé֔⁠niy mi⁠ẏ֥wòm ʻad-la֖yĕláh ţȧşĕ̌liyméֽ⁠niy׃"],[38,13,"שִׁוִּ֤יתִי עַד־בֹּ֨קֶר֙ כָּֽ⁠אֲרִ֔י כֵּ֥ן יְשַׁבֵּ֖ר כָּל־עַצְמוֹתָ֑⁠י מִ⁠יּ֥וֹם עַד־לַ֖יְלָה תַּשְׁלִימֵֽ⁠נִי׃","şǐwi֤̇yţiy ʻad-bò̇֨qer֙ kֽ̇á⁠ʼàri֔y ké֥̇n yĕşǎbé֖̇r ká̇l-ʻaẕĕmwòţá֑⁠y mi⁠ẏ֥wòm ʻad-la֖yĕláh ţȧşĕ̌liyméֽ⁠niy׃"],[38,14,"כְּ⁠ס֤וּס עָגוּר֙ כֵּ֣ן אֲצַפְצֵ֔ף אֶהְגֶּ֖ה כַּ⁠יּוֹנָ֑ה דַּלּ֤וּ עֵינַ⁠י֙ לַ⁠מָּר֔וֹם אֲדֹנָ֖⁠י עָֽשְׁקָה־לִּ֥⁠י עָרְבֵֽ⁠נִי׃","kĕ̇⁠s֤ẇs ʻágẇr֙ ké֣̇n ʼàẕapĕẕé֔p ʼehĕgė֖h kȧ⁠ẏwòná֑h dȧl֤̇ẇ ʻéyna⁠y֙ la⁠má̇r֔wòm ʼàdòná֖⁠y ʻáֽşĕ̌qáh-li֥̇⁠y ʻárĕbéֽ⁠niy׃"],[38,15,"מָֽה־אֲדַבֵּ֥ר וְ⁠אָֽמַר־לִ֖⁠י וְ⁠ה֣וּא עָשָׂ֑ה אֶדַּדֶּ֥ה כָל־שְׁנוֹתַ֖⁠י עַל־מַ֥ר נַפְשִֽׁ⁠י׃","máֽh-ʼàdabé֥̇r wĕ⁠ʼáֽmar-li֖⁠y wĕ⁠h֣ẇʼ ʻáşá֑̂h ʼedȧdė֥h kál-şĕ̌nwòţa֖⁠y ʻal-ma֥r napĕşǐֽ⁠y׃"],[38,16,"אֲדֹנָ֖⁠י עֲלֵי⁠הֶ֣ם יִֽחְי֑וּ וּ⁠לְ⁠כָל־בָּ⁠הֶן֙ חַיֵּ֣י רוּחִ֔⁠י וְ⁠תַחֲלִימֵ֖⁠נִי וְ⁠הַחֲיֵֽ⁠נִי׃","ʼàdòná֖⁠y ʻàléy⁠he֣m yiֽẖĕy֑ẇ ẇ⁠lĕ⁠kál-bá̇⁠hen֙ ẖayé֣̇y rẇẖi֔⁠y wĕ⁠ţaẖàliymé֖⁠niy wĕ⁠haẖàyéֽ⁠niy׃"],[38,17,"הִנֵּ֥ה לְ⁠שָׁל֖וֹם מַר־לִ֣⁠י מָ֑ר וְ⁠אַתָּ֞ה חָשַׁ֤קְתָּ נַפְשִׁ⁠י֙ מִ⁠שַּׁ֣חַת בְּלִ֔י כִּ֥י הִשְׁלַ֛כְתָּ אַחֲרֵ֥י גֵוְ⁠ךָ֖ כָּל־חֲטָאָֽ⁠י׃","hiné֥̇h lĕ⁠şá̌l֖wòm mar-li֣⁠y má֑r wĕ⁠ʼaţá̇֞h ẖáşǎ֤qĕţá̇ napĕşǐ⁠y֙ mi⁠şȧ֣̌ẖaţ bĕ̇li֔y ki֥̇y hişĕ̌la֛kĕţá̇ ʼaẖàré֥y géwĕ⁠ká֖ ká̇l-ẖàtáʼáֽ⁠y׃"],[38,18,"כִּ֣י לֹ֥א שְׁא֛וֹל תּוֹדֶ֖⁠ךָּ מָ֣וֶת יְהַלְלֶ֑⁠ךָּ לֹֽא־יְשַׂבְּר֥וּ יֽוֹרְדֵי־ב֖וֹר אֶל־אֲמִתֶּֽ⁠ךָ׃","ki֣̇y lò֥ʼ şĕ̌ʼ֛wòl ţ̇wòde֖⁠ká̇ má֣weţ yĕhalĕle֑⁠ká̇ lòֽʼ-yĕşâbĕ̇r֥ẇ yֽwòrĕdéy-b֖wòr ʼel-ʼàmiţėֽ⁠ká׃"],[38,19,"חַ֥י חַ֛י ה֥וּא יוֹדֶ֖⁠ךָ כָּמ֣וֹ⁠נִי הַ⁠יּ֑וֹם אָ֣ב לְ⁠בָנִ֔ים יוֹדִ֖יעַ אֶל־אֲמִתֶּֽ⁠ךָ׃","ẖa֥y ẖa֛y h֥ẇʼ ywòde֖⁠ká ká̇m֣wò⁠niy ha⁠ẏ֑wòm ʼá֣b lĕ⁠báni֔ym ywòdi֖yʻa ʼel-ʼàmiţėֽ⁠ká׃"],[38,20,"יְהוָ֖ה לְ⁠הוֹשִׁיעֵ֑⁠נִי וּ⁠נְגִנוֹתַ֧י נְנַגֵּ֛ן כָּל־יְמֵ֥י חַיֵּ֖י⁠נוּ עַל־בֵּ֥ית יְהוָֽה׃","yĕhwá֖h lĕ⁠hwòşǐyʻé֑⁠niy ẇ⁠nĕginwòţa֧y nĕnagé֛̇n ká̇l-yĕmé֥y ẖayé֖̇y⁠nẇ ʻal-bé֥̇yţ yĕhwáֽh׃"],[38,21,"וַ⁠יֹּ֣אמֶר יְשַׁעְיָ֔הוּ יִשְׂא֖וּ דְּבֶ֣לֶת תְּאֵנִ֑ים וְ⁠יִמְרְח֥וּ עַֽל־הַ⁠שְּׁחִ֖ין וְ⁠יֶֽחִי׃","wa⁠yò֣̇ʼmer yĕşǎʻĕyá֔hẇ yişĕ̂ʼ֖ẇ dĕ̇be֣leţ ţĕ̇ʼéni֑ym wĕ⁠yimĕrĕẖ֥ẇ ʻaֽl-ha⁠şĕ̇̌ẖi֖yn wĕ⁠yeֽẖiy׃"],[38,22,"וַ⁠יֹּ֥אמֶר חִזְקִיָּ֖הוּ מָ֣ה א֑וֹת כִּ֥י אֶעֱלֶ֖ה בֵּ֥ית יְהוָֽה׃ס","wa⁠yò֥̇ʼmer ẖizĕqiyá֖̇hẇ má֣h ʼ֑wòţ ki֥̇y ʼeʻèle֖h bé֥̇yţ yĕhwáֽh׃s"],[39,1,"בָּ⁠עֵ֣ת הַ⁠הִ֡וא שָׁלַ֡ח מְרֹדַ֣ךְ בַּ֠לְאֲדָן בֶּֽן־בַּלְאֲדָ֧ן מֶֽלֶךְ־בָּבֶ֛ל סְפָרִ֥ים וּ⁠מִנְחָ֖ה אֶל־חִזְקִיָּ֑הוּ וַ⁠יִּשְׁמַ֕ע כִּ֥י חָלָ֖ה וַֽ⁠יֶּחֱזָֽק׃","bá̇⁠ʻé֣ţ ha⁠hi֡wʼ şá̌la֡ẖ mĕròda֣kĕ bȧ֠lĕʼàdán bėֽn-bȧlĕʼàdá֧n meֽlekĕ-bá̇be֛l sĕpári֥ym ẇ⁠minĕẖá֖h ʼel-ẖizĕqiyá֑̇hẇ wa⁠yi̇şĕ̌ma֕ʻ ki֥̇y ẖálá֖h wֽa⁠yėẖèzáֽq׃"],[39,2,"וַ⁠יִּשְׂמַ֣ח עֲלֵי⁠הֶם֮ חִזְקִיָּהוּ֒ וַ⁠יַּרְאֵ֣⁠ם אֶת־בֵּ֣ית נכת⁠ה אֶת־הַ⁠כֶּסֶף֩ וְ⁠אֶת־הַ⁠זָּהָ֨ב וְ⁠אֶת־הַ⁠בְּשָׂמִ֜ים וְ⁠אֵ֣ת ׀ הַ⁠שֶּׁ֣מֶן הַ⁠טּ֗וֹב וְ⁠אֵת֙ כָּל־בֵּ֣ית כֵּלָ֔י⁠ו וְ⁠אֵ֛ת כָּל־אֲשֶׁ֥ר נִמְצָ֖א בְּ⁠אֹֽצְרֹתָ֑י⁠ו לֹֽא־הָיָ֣ה דָבָ֗ר אֲ֠שֶׁר לֹֽא־הֶרְאָ֧⁠ם חִזְקִיָּ֛הוּ בְּ⁠בֵית֖⁠וֹ וּ⁠בְ⁠כָל־מֶמְשַׁלְתּֽ⁠וֹ׃","wa⁠yi̇şĕ̂ma֣ẖ ʻàléy⁠hem֮ ẖizĕqiyá̇hẇ֒ wa⁠yȧrĕʼé֣⁠m ʼeţ-bé֣̇yţ nkţ⁠h ʼeţ-ha⁠kėsep֩ wĕ⁠ʼeţ-ha⁠zá̇há֨b wĕ⁠ʼeţ-ha⁠bĕ̇şá̂mi֜ym wĕ⁠ʼé֣ţ ׀ ha⁠şė֣̌men ha⁠ṫ֗wòb wĕ⁠ʼéţ֙ ká̇l-bé֣̇yţ ké̇lá֔y⁠w wĕ⁠ʼé֛ţ ká̇l-ʼàşě֥r nimĕẕá֖ʼ bĕ̇⁠ʼòֽẕĕròţá֑y⁠w lòֽʼ-háyá֣h dábá֗r ʼà֠şěr lòֽʼ-herĕʼá֧⁠m ẖizĕqiyá֛̇hẇ bĕ̇⁠béyţ֖⁠wò ẇ⁠bĕ⁠kál-memĕşǎlĕţֽ̇⁠wò׃"],[39,3,"וַ⁠יָּבֹא֙ יְשַׁעְיָ֣הוּ הַ⁠נָּבִ֔יא אֶל־הַ⁠מֶּ֖לֶךְ חִזְקִיָּ֑הוּ וַ⁠יֹּ֨אמֶר אֵלָ֜י⁠ו מָ֥ה אָמְר֣וּ ׀ הָ⁠אֲנָשִׁ֣ים הָ⁠אֵ֗לֶּה וּ⁠מֵ⁠אַ֨יִן֙ יָבֹ֣אוּ אֵלֶ֔י⁠ךָ וַ⁠יֹּ֨אמֶר֙ חִזְקִיָּ֔הוּ מֵ⁠אֶ֧רֶץ רְחוֹקָ֛ה בָּ֥אוּ אֵלַ֖⁠י מִ⁠בָּבֶֽל׃","wa⁠yá̇bòʼ֙ yĕşǎʻĕyá֣hẇ ha⁠ná̇bi֔yʼ ʼel-ha⁠mė֖lekĕ ẖizĕqiyá֑̇hẇ wa⁠yò̇֨ʼmer ʼélá֜y⁠w má֥h ʼámĕr֣ẇ ׀ há⁠ʼànáşǐ֣ym há⁠ʼé֗lėh ẇ⁠mé⁠ʼa֨yin֙ yábò֣ʼẇ ʼéle֔y⁠ká wa⁠yò̇֨ʼmer֙ ẖizĕqiyá̇֔hẇ mé⁠ʼe֧reẕ rĕẖwòqá֛h bá֥̇ʼẇ ʼéla֖⁠y mi⁠bá̇beֽl׃"],[39,4,"וַ⁠יֹּ֕אמֶר מָ֥ה רָא֖וּ בְּ⁠בֵיתֶ֑⁠ךָ וַ⁠יֹּ֣אמֶר חִזְקִיָּ֗הוּ אֵ֣ת כָּל־אֲשֶׁ֤ר בְּ⁠בֵיתִ⁠י֙ רָא֔וּ לֹֽא־הָיָ֥ה דָבָ֛ר אֲשֶׁ֥ר לֹֽא־הִרְאִיתִ֖י⁠ם בְּ⁠אוֹצְרֹתָֽ⁠י׃","wa⁠yò̇֕ʼmer má֥h ráʼ֖ẇ bĕ̇⁠béyţe֑⁠ká wa⁠yò֣̇ʼmer ẖizĕqiyá̇֗hẇ ʼé֣ţ ká̇l-ʼàşě֤r bĕ̇⁠béyţi⁠y֙ ráʼ֔ẇ lòֽʼ-háyá֥h dábá֛r ʼàşě֥r lòֽʼ-hirĕʼiyţi֖y⁠m bĕ̇⁠ʼwòẕĕròţáֽ⁠y׃"],[39,5,"וַ⁠יֹּ֥אמֶר יְשַׁעְיָ֖הוּ אֶל־חִזְקִיָּ֑הוּ שְׁמַ֖ע דְּבַר־יְהוָ֥ה צְבָאֽוֹת׃","wa⁠yò֥̇ʼmer yĕşǎʻĕyá֖hẇ ʼel-ẖizĕqiyá֑̇hẇ şĕ̌ma֖ʻ dĕ̇bar-yĕhwá֥h ẕĕbáʼֽwòţ׃"],[39,6,"הִנֵּה֮ יָמִ֣ים בָּאִים֒ וְ⁠נִשָּׂ֣א ׀ כָּל־אֲשֶׁ֣ר בְּ⁠בֵיתֶ֗⁠ךָ וַ⁠אֲשֶׁ֨ר אָצְר֧וּ אֲבֹתֶ֛י⁠ךָ עַד־הַ⁠יּ֥וֹם הַ⁠זֶּ֖ה בָּבֶ֑ל לֹֽא־יִוָּתֵ֥ר דָּבָ֖ר אָמַ֥ר יְהוָֽה׃","hiné̇h֮ yámi֣ym bá̇ʼiym֒ wĕ⁠nişá֣̇̂ʼ ׀ ká̇l-ʼàşě֣r bĕ̇⁠béyţe֗⁠ká wa⁠ʼàşě֨r ʼáẕĕr֧ẇ ʼàbòţe֛y⁠ká ʻad-ha⁠ẏ֥wòm ha⁠zė֖h bá̇be֑l lòֽʼ-yiwá̇ţé֥r dá̇bá֖r ʼáma֥r yĕhwáֽh׃"],[39,7,"וּ⁠מִ⁠בָּנֶ֜י⁠ךָ אֲשֶׁ֨ר יֵצְא֧וּ מִמְּ⁠ךָ֛ אֲשֶׁ֥ר תּוֹלִ֖יד יִקָּ֑חוּ וְ⁠הָיוּ֙ סָרִיסִ֔ים בְּ⁠הֵיכַ֖ל מֶ֥לֶךְ בָּבֶֽל׃","ẇ⁠mi⁠bá̇ne֜y⁠ká ʼàşě֨r yéẕĕʼ֧ẇ mimĕ̇⁠ká֛ ʼàşě֥r ţ̇wòli֖yd yiqá֑̇ẖẇ wĕ⁠háyẇ֙ sáriysi֔ym bĕ̇⁠héyka֖l me֥lekĕ bá̇beֽl׃"],[39,8,"וַ⁠יֹּ֤אמֶר חִזְקִיָּ֨הוּ֙ אֶֽל־יְשַׁעְיָ֔הוּ ט֥וֹב דְּבַר־יְהוָ֖ה אֲשֶׁ֣ר דִּבַּ֑רְתָּ וַ⁠יֹּ֕אמֶר כִּ֥י יִהְיֶ֛ה שָׁל֥וֹם וֶ⁠אֱמֶ֖ת בְּ⁠יָמָֽ⁠י׃פ","wa⁠yò֤̇ʼmer ẖizĕqiyá̇֨hẇ֙ ʼeֽl-yĕşǎʻĕyá֔hẇ t֥wòb dĕ̇bar-yĕhwá֖h ʼàşě֣r di̇bȧ֑rĕţá̇ wa⁠yò̇֕ʼmer ki֥̇y yihĕye֛h şá̌l֥wòm we⁠ʼème֖ţ bĕ̇⁠yámáֽ⁠y׃p"],[40,1,"נַחֲמ֥וּ נַחֲמ֖וּ עַמִּ֑⁠י יֹאמַ֖ר אֱלֹהֵי⁠כֶֽם׃","naẖàm֥ẇ naẖàm֖ẇ ʻami֑̇⁠y yòʼma֖r ʼèlòhéy⁠keֽm׃"],[40,2,"דַּבְּר֞וּ עַל־לֵ֤ב יְרֽוּשָׁלִַ֨ם֙ וְ⁠קִרְא֣וּ אֵלֶ֔י⁠הָ כִּ֤י מָֽלְאָה֙ צְבָאָ֔⁠הּ כִּ֥י נִרְצָ֖ה עֲוֺנָ֑⁠הּ כִּ֤י לָקְחָה֙ מִ⁠יַּ֣ד יְהוָ֔ה כִּפְלַ֖יִם בְּ⁠כָל־חַטֹּאתֶֽי⁠הָ׃ס","dȧbĕ̇r֞ẇ ʻal-lé֤b yĕrֽẇşá̌lia֨m֙ wĕ⁠qirĕʼ֣ẇ ʼéle֔y⁠há ki֤̇y máֽlĕʼáh֙ ẕĕbáʼá֔⁠ḣ ki֥̇y nirĕẕá֖h ʻàwֺná֑⁠ḣ ki֤̇y láqĕẖáh֙ mi⁠yȧ֣d yĕhwá֔h ki̇pĕla֖yim bĕ̇⁠kál-ẖatò̇ʼţeֽy⁠há׃s"],[40,3,"ק֣וֹל קוֹרֵ֔א בַּ⁠מִּדְבָּ֕ר פַּנּ֖וּ דֶּ֣רֶךְ יְהוָ֑ה יַשְּׁרוּ֙ בָּ⁠עֲרָבָ֔ה מְסִלָּ֖ה לֵ⁠אלֹהֵֽי⁠נוּ׃","q֣wòl qwòré֔ʼ bȧ⁠mi̇dĕbá̇֕r pȧṅ֖ẇ dė֣rekĕ yĕhwá֑h yaşĕ̇̌rẇ֙ bá̇⁠ʻàrábá֔h mĕsilá֖̇h lé⁠ʼlòhéֽy⁠nẇ׃"],[40,4,"כָּל־גֶּיא֙ יִנָּשֵׂ֔א וְ⁠כָל־הַ֥ר וְ⁠גִבְעָ֖ה יִשְׁפָּ֑לוּ וְ⁠הָיָ֤ה הֶֽ⁠עָקֹב֙ לְ⁠מִישׁ֔וֹר וְ⁠הָ⁠רְכָסִ֖ים לְ⁠בִקְעָֽה׃","ká̇l-gėyʼ֙ yiná̇şé̂֔ʼ wĕ⁠kál-ha֥r wĕ⁠gibĕʻá֖h yişĕ̌pá֑̇lẇ wĕ⁠háyá֤h heֽ⁠ʻáqòb֙ lĕ⁠miyş̌֔wòr wĕ⁠há⁠rĕkási֖ym lĕ⁠biqĕʻáֽh׃"],[40,5,"וְ⁠נִגְלָ֖ה כְּב֣וֹד יְהוָ֑ה וְ⁠רָא֤וּ כָל־בָּשָׂר֙ יַחְדָּ֔ו כִּ֛י פִּ֥י יְהוָ֖ה דִּבֵּֽר׃ס","wĕ⁠nigĕlá֖h kĕ̇b֣wòd yĕhwá֑h wĕ⁠ráʼ֤ẇ kál-bá̇şá̂r֙ yaẖĕdá̇֔w ki֛̇y pi֥̇y yĕhwá֖h di̇béֽ̇r׃s"],[40,6,"ק֚וֹל אֹמֵ֣ר קְרָ֔א וְ⁠אָמַ֖ר מָ֣ה אֶקְרָ֑א כָּל־הַ⁠בָּשָׂ֣ר חָצִ֔יר וְ⁠כָל־חַסְדּ֖⁠וֹ כְּ⁠צִ֥יץ הַ⁠שָּׂדֶֽה׃","q֚wòl ʼòmé֣r qĕrá֔ʼ wĕ⁠ʼáma֖r má֣h ʼeqĕrá֑ʼ ká̇l-ha⁠bá̇şá֣̂r ẖáẕi֔yr wĕ⁠kál-ẖasĕḋ֖⁠wò kĕ̇⁠ẕi֥yẕ ha⁠şá̇̂deֽh׃"],[40,7,"יָבֵ֤שׁ חָצִיר֙ נָ֣בֵֽל צִ֔יץ כִּ֛י ר֥וּחַ יְהוָ֖ה נָ֣שְׁבָה בּ֑⁠וֹ אָכֵ֥ן חָצִ֖יר הָ⁠עָֽם׃","yábé֤ş̌ ẖáẕiyr֙ ná֣béֽl ẕi֔yẕ ki֛̇y r֥ẇẖa yĕhwá֖h ná֣şĕ̌báh ḃ֑⁠wò ʼáké֥n ẖáẕi֖yr há⁠ʻáֽm׃"],[40,8,"יָבֵ֥שׁ חָצִ֖יר נָ֣בֵֽל צִ֑יץ וּ⁠דְבַר־אֱלֹהֵ֖י⁠נוּ יָק֥וּם לְ⁠עוֹלָֽם׃ס","yábé֥ş̌ ẖáẕi֖yr ná֣béֽl ẕi֑yẕ ẇ⁠dĕbar-ʼèlòhé֖y⁠nẇ yáq֥ẇm lĕ⁠ʻwòláֽm׃s"],[40,9,"עַ֣ל הַר־גָּבֹ֤הַ עֲלִי־לָ⁠ךְ֙ מְבַשֶּׂ֣רֶת צִיּ֔וֹן הָרִ֤ימִי בַ⁠כֹּ֨חַ֙ קוֹלֵ֔⁠ךְ מְבַשֶּׂ֖רֶת יְרוּשָׁלִָ֑ם הָרִ֨ימִי֙ אַל־תִּירָ֔אִי אִמְרִי֙ לְ⁠עָרֵ֣י יְהוּדָ֔ה הִנֵּ֖ה אֱלֹהֵי⁠כֶֽם׃","ʻa֣l har-gá̇bò֤ha ʻàliy-lá⁠kĕ֙ mĕbaşė֣̂reţ ẕiẏ֔wòn hári֤ymiy ba⁠kò̇֨ẖa֙ qwòlé֔⁠kĕ mĕbaşė֖̂reţ yĕrẇşá̌liá֑m hári֨ymiy֙ ʼal-ţi̇yrá֔ʼiy ʼimĕriy֙ lĕ⁠ʻáré֣y yĕhẇdá֔h hiné֖̇h ʼèlòhéy⁠keֽm׃"],[40,10,"הִנֵּ֨ה אֲדֹנָ֤⁠י יְהוִה֙ בְּ⁠חָזָ֣ק יָב֔וֹא וּ⁠זְרֹע֖⁠וֹ מֹ֣שְׁלָה ל֑⁠וֹ הִנֵּ֤ה שְׂכָר⁠וֹ֙ אִתּ֔⁠וֹ וּ⁠פְעֻלָּת֖⁠וֹ לְ⁠פָנָֽי⁠ו׃","hiné̇֨h ʼàdòná֤⁠y yĕhwih֙ bĕ̇⁠ẖázá֣q yáb֔wòʼ ẇ⁠zĕròʻ֖⁠wò mò֣şĕ̌láh l֑⁠wò hiné֤̇h şĕ̂kár⁠wò֙ ʼiţ̇֔⁠wò ẇ⁠pĕʻulá̇ţ֖⁠wò lĕ⁠pánáֽy⁠w׃"],[40,11,"כְּ⁠רֹעֶה֙ עֶדְר֣⁠וֹ יִרְעֶ֔ה בִּ⁠זְרֹע⁠וֹ֙ יְקַבֵּ֣ץ טְלָאִ֔ים וּ⁠בְ⁠חֵיק֖⁠וֹ יִשָּׂ֑א עָל֖וֹת יְנַהֵֽל׃ס","kĕ̇⁠ròʻeh֙ ʻedĕr֣⁠wò yirĕʻe֔h bi̇⁠zĕròʻ⁠wò֙ yĕqabé֣̇ẕ tĕláʼi֔ym ẇ⁠bĕ⁠ẖéyq֖⁠wò yişá֑̇̂ʼ ʻál֖wòţ yĕnahéֽl׃s"],[40,12,"מִֽי־מָדַ֨ד בְּ⁠שָׁעֳל֜⁠וֹ מַ֗יִם וְ⁠שָׁמַ֨יִם֙ בַּ⁠זֶּ֣רֶת תִּכֵּ֔ן וְ⁠כָ֥ל בַּ⁠שָּׁלִ֖שׁ עֲפַ֣ר הָ⁠אָ֑רֶץ וְ⁠שָׁקַ֤ל בַּ⁠פֶּ֨לֶס֙ הָרִ֔ים וּ⁠גְבָע֖וֹת בְּ⁠מֹאזְנָֽיִם׃","miֽy-máda֨d bĕ̇⁠şá̌ʻol֜⁠wò ma֗yim wĕ⁠şá̌ma֨yim֙ bȧ⁠zė֣reţ ţi̇ké̇֔n wĕ⁠ká֥l bȧ⁠şá̇̌li֖ş̌ ʻàpa֣r há⁠ʼá֑reẕ wĕ⁠şá̌qa֤l bȧ⁠pė֨les֙ hári֔ym ẇ⁠gĕbáʻ֖wòţ bĕ̇⁠mòʼzĕnáֽyim׃"],[40,13,"מִֽי־תִכֵּ֥ן אֶת־ר֖וּחַ יְהוָ֑ה וְ⁠אִ֥ישׁ עֲצָת֖⁠וֹ יוֹדִיעֶֽ⁠נּוּ׃","miֽy-ţiké֥̇n ʼeţ-r֖ẇẖa yĕhwá֑h wĕ⁠ʼi֥yş̌ ʻàẕáţ֖⁠wò ywòdiyʻeֽ⁠ṅẇ׃"],[40,14,"אֶת־מִ֤י נוֹעָץ֙ וַ⁠יְבִינֵ֔⁠הוּ וַֽ⁠יְלַמְּדֵ֖⁠הוּ בְּ⁠אֹ֣רַח מִשְׁפָּ֑ט וַ⁠יְלַמְּדֵ֣⁠הוּ דַ֔עַת וְ⁠דֶ֥רֶךְ תְּבוּנ֖וֹת יוֹדִיעֶֽ⁠נּוּ׃","ʼeţ-mi֤y nwòʻáẕ֙ wa⁠yĕbiyné֔⁠hẇ waֽ⁠yĕlamĕ̇dé֖⁠hẇ bĕ̇⁠ʼò֣raẖ mişĕ̌pá֑̇t wa⁠yĕlamĕ̇dé֣⁠hẇ da֔ʻaţ wĕ⁠de֥rekĕ ţĕ̇bẇn֖wòţ ywòdiyʻeֽ⁠ṅẇ׃"],[40,15,"הֵ֤ן גּוֹיִם֙ כְּ⁠מַ֣ר מִ⁠דְּלִ֔י וּ⁠כְ⁠שַׁ֥חַק מֹאזְנַ֖יִם נֶחְשָׁ֑בוּ הֵ֥ן אִיִּ֖ים כַּ⁠דַּ֥ק יִטּֽוֹל׃","hé֤n ġwòyim֙ kĕ̇⁠ma֣r mi⁠dĕ̇li֔y ẇ⁠kĕ⁠şǎ֥ẖaq mòʼzĕna֖yim neẖĕşá֑̌bẇ hé֥n ʼiyi֖̇ym kȧ⁠dȧ֥q yiṫֽwòl׃"],[40,16,"וּ⁠לְבָנ֕וֹן אֵ֥ין דֵּ֖י בָּעֵ֑ר וְ⁠חַיָּת֔⁠וֹ אֵ֥ין דֵּ֖י עוֹלָֽה׃ס","ẇ⁠lĕbán֕wòn ʼé֥yn dé֖̇y bá̇ʻé֑r wĕ⁠ẖayá̇ţ֔⁠wò ʼé֥yn dé֖̇y ʻwòláֽh׃s"],[40,17,"כָּל־הַ⁠גּוֹיִ֖ם כְּ⁠אַ֣יִן נֶגְדּ֑⁠וֹ מֵ⁠אֶ֥פֶס וָ⁠תֹ֖הוּ נֶחְשְׁבוּ־לֽ⁠וֹ׃","ká̇l-ha⁠ġwòyi֖m kĕ̇⁠ʼa֣yin negĕḋ֑⁠wò mé⁠ʼe֥pes wá⁠ţò֖hẇ neẖĕşĕ̌bẇ-lֽ⁠wò׃"],[40,18,"וְ⁠אֶל־מִ֖י תְּדַמְּי֣וּ⁠ן אֵ֑ל וּ⁠מַה־דְּמ֖וּת תַּ֥עַרְכוּ לֽ⁠וֹ׃","wĕ⁠ʼel-mi֖y ţĕ̇damĕ̇y֣ẇ⁠n ʼé֑l ẇ⁠mah-dĕ̇m֖ẇţ ţȧ֥ʻarĕkẇ lֽ⁠wò׃"],[40,19,"הַ⁠פֶּ֨סֶל֙ נָסַ֣ךְ חָרָ֔שׁ וְ⁠צֹרֵ֖ף בַּ⁠זָּהָ֣ב יְרַקְּעֶ֑⁠נּוּ וּ⁠רְתֻק֥וֹת כֶּ֖סֶף צוֹרֵֽף׃","ha⁠pė֨sel֙ nása֣kĕ ẖárá֔ş̌ wĕ⁠ẕòré֖p bȧ⁠zá̇há֣b yĕraqĕ̇ʻe֑⁠ṅẇ ẇ⁠rĕţuq֥wòţ kė֖sep ẕwòréֽp׃"],[40,20,"הַֽ⁠מְסֻכָּ֣ן תְּרוּמָ֔ה עֵ֥ץ לֹֽא־יִרְקַ֖ב יִבְחָ֑ר חָרָ֤שׁ חָכָם֙ יְבַקֶּשׁ־ל֔⁠וֹ לְ⁠הָכִ֥ין פֶּ֖סֶל לֹ֥א יִמּֽוֹט׃","haֽ⁠mĕsuká֣̇n ţĕ̇rẇmá֔h ʻé֥ẕ lòֽʼ-yirĕqa֖b yibĕẖá֑r ẖárá֤ş̌ ẖákám֙ yĕbaqėş̌-l֔⁠wò lĕ⁠háki֥yn pė֖sel lò֥ʼ yiṁֽwòt׃"],[40,21,"הֲ⁠ל֤וֹא תֵֽדְעוּ֙ הֲ⁠ל֣וֹא תִשְׁמָ֔עוּ הֲ⁠ל֛וֹא הֻגַּ֥ד מֵ⁠רֹ֖אשׁ לָ⁠כֶ֑ם הֲ⁠לוֹא֙ הֲבִ֣ינֹתֶ֔ם מוֹסְד֖וֹת הָ⁠אָֽרֶץ׃","hà⁠l֤wòʼ ţéֽdĕʻẇ֙ hà⁠l֣wòʼ ţişĕ̌má֔ʻẇ hà⁠l֛wòʼ hugȧ֥d mé⁠rò֖ʼş̌ lá⁠ke֑m hà⁠lwòʼ֙ hàbi֣ynòţe֔m mwòsĕd֖wòţ há⁠ʼáֽreẕ׃"],[40,22,"הַ⁠יֹּשֵׁב֙ עַל־ח֣וּג הָ⁠אָ֔רֶץ וְ⁠יֹשְׁבֶ֖י⁠הָ כַּ⁠חֲגָבִ֑ים הַ⁠נּוֹטֶ֤ה כַ⁠דֹּק֙ שָׁמַ֔יִם וַ⁠יִּמְתָּחֵ֥⁠ם כָּ⁠אֹ֖הֶל לָ⁠שָֽׁבֶת׃","ha⁠yò̇şé̌b֙ ʻal-ẖ֣ẇg há⁠ʼá֔reẕ wĕ⁠yòşĕ̌be֖y⁠há kȧ⁠ẖàgábi֑ym ha⁠ṅwòte֤h ka⁠dò̇q֙ şá̌ma֔yim wa⁠yi̇mĕţá̇ẖé֥⁠m ká̇⁠ʼò֖hel lá⁠şáֽ̌beţ׃"],[40,23,"הַ⁠נּוֹתֵ֥ן רוֹזְנִ֖ים לְ⁠אָ֑יִן שֹׁ֥פְטֵי אֶ֖רֶץ כַּ⁠תֹּ֥הוּ עָשָֽׂה׃","ha⁠ṅwòţé֥n rwòzĕni֖ym lĕ⁠ʼá֑yin şò֥̌pĕtéy ʼe֖reẕ kȧ⁠ţò֥̇hẇ ʻáşáֽ̂h׃"],[40,24,"אַ֣ף בַּל־נִטָּ֗עוּ אַ֚ף בַּל־זֹרָ֔עוּ אַ֛ף בַּל־שֹׁרֵ֥שׁ בָּ⁠אָ֖רֶץ גִּזְעָ֑⁠ם וְ⁠גַם־נָשַׁ֤ף בָּ⁠הֶם֙ וַ⁠יִּבָ֔שׁוּ וּ⁠סְעָרָ֖ה כַּ⁠קַּ֥שׁ תִּשָּׂאֵֽ⁠ם׃ס","ʼa֣p bȧl-nitá̇֗ʻẇ ʼa֚p bȧl-zòrá֔ʻẇ ʼa֛p bȧl-şò̌ré֥ş̌ bá̇⁠ʼá֖reẕ gi̇zĕʻá֑⁠m wĕ⁠gam-náşǎ֤p bá̇⁠hem֙ wa⁠yi̇bá֔ş̌ẇ ẇ⁠sĕʻárá֖h kȧ⁠qȧ֥ş̌ ţi̇şá̇̂ʼéֽ⁠m׃s"],[40,25,"וְ⁠אֶל־מִ֥י תְדַמְּי֖וּ⁠נִי וְ⁠אֶשְׁוֶ֑ה יֹאמַ֖ר קָדֽוֹשׁ׃","wĕ⁠ʼel-mi֥y ţĕdamĕ̇y֖ẇ⁠niy wĕ⁠ʼeşĕ̌we֑h yòʼma֖r qádֽwòş̌׃"],[40,26,"שְׂאוּ־מָר֨וֹם עֵינֵי⁠כֶ֤ם וּ⁠רְאוּ֙ מִי־בָרָ֣א אֵ֔לֶּה הַ⁠מּוֹצִ֥יא בְ⁠מִסְפָּ֖ר צְבָאָ֑⁠ם לְ⁠כֻלָּ⁠ם֙ בְּ⁠שֵׁ֣ם יִקְרָ֔א מֵ⁠רֹ֤ב אוֹנִים֙ וְ⁠אַמִּ֣יץ כֹּ֔חַ אִ֖ישׁ לֹ֥א נֶעְדָּֽר׃ס","şĕ̂ʼẇ-már֨wòm ʻéynéy⁠ke֤m ẇ⁠rĕʼẇ֙ miy-bárá֣ʼ ʼé֔lėh ha⁠ṁwòẕi֥yʼ bĕ⁠misĕpá֖̇r ẕĕbáʼá֑⁠m lĕ⁠kulá̇⁠m֙ bĕ̇⁠şé֣̌m yiqĕrá֔ʼ mé⁠rò֤b ʼwòniym֙ wĕ⁠ʼami֣̇yẕ kò̇֔ẖa ʼi֖yş̌ lò֥ʼ neʻĕdáֽ̇r׃s"],[40,27,"לָ֤⁠מָּה תֹאמַר֙ יַֽעֲקֹ֔ב וּ⁠תְדַבֵּ֖ר יִשְׂרָאֵ֑ל נִסְתְּרָ֤ה דַרְכִּ⁠י֙ מֵֽ⁠יְהוָ֔ה וּ⁠מֵ⁠אֱלֹהַ֖⁠י מִשְׁפָּטִ֥⁠י יַעֲבֽוֹר׃","lá֤⁠má̇h ţòʼmar֙ yaֽʻàqò֔b ẇ⁠ţĕdabé֖̇r yişĕ̂ráʼé֑l nisĕţĕ̇rá֤h darĕki̇⁠y֙ méֽ⁠yĕhwá֔h ẇ⁠mé⁠ʼèlòha֖⁠y mişĕ̌pá̇ti֥⁠y yaʻàbֽwòr׃"],[40,28,"הֲ⁠ל֨וֹא יָדַ֜עְתָּ אִם־לֹ֣א שָׁמַ֗עְתָּ אֱלֹהֵ֨י עוֹלָ֤ם ׀ יְהוָה֙ בּוֹרֵא֙ קְצ֣וֹת הָ⁠אָ֔רֶץ לֹ֥א יִיעַ֖ף וְ⁠לֹ֣א יִיגָ֑ע אֵ֥ין חֵ֖קֶר לִ⁠תְבוּנָתֽ⁠וֹ׃","hà⁠l֨wòʼ yáda֜ʻĕţá̇ ʼim-lò֣ʼ şá̌ma֗ʻĕţá̇ ʼèlòhé֨y ʻwòlá֤m ׀ yĕhwáh֙ ḃwòréʼ֙ qĕẕ֣wòţ há⁠ʼá֔reẕ lò֥ʼ yiyʻa֖p wĕ⁠lò֣ʼ yiygá֑ʻ ʼé֥yn ẖé֖qer li⁠ţĕbẇnáţֽ⁠wò׃"],[40,29,"נֹתֵ֥ן לַ⁠יָּעֵ֖ף כֹּ֑חַ וּ⁠לְ⁠אֵ֥ין אוֹנִ֖ים עָצְמָ֥ה יַרְבֶּֽה׃","nòţé֥n la⁠yá̇ʻé֖p kò֑̇ẖa ẇ⁠lĕ⁠ʼé֥yn ʼwòni֖ym ʻáẕĕmá֥h yarĕbėֽh׃"],[40,30,"וְ⁠יִֽעֲפ֥וּ נְעָרִ֖ים וְ⁠יִגָ֑עוּ וּ⁠בַחוּרִ֖ים כָּשׁ֥וֹל יִכָּשֵֽׁלוּ׃","wĕ⁠yiֽʻàp֥ẇ nĕʻári֖ym wĕ⁠yigá֑ʻẇ ẇ⁠baẖẇri֖ym ká̇ş֥̌wòl yiká̇şéֽ̌lẇ׃"],[40,31,"וְ⁠קוֹיֵ֤ יְהוָה֙ יַחֲלִ֣יפוּ כֹ֔חַ יַעֲל֥וּ אֵ֖בֶר כַּ⁠נְּשָׁרִ֑ים יָר֨וּצוּ֙ וְ⁠לֹ֣א יִיגָ֔עוּ יֵלְכ֖וּ וְ⁠לֹ֥א יִיעָֽפוּ׃פ","wĕ⁠qwòyé֤ yĕhwáh֙ yaẖàli֣ypẇ kò֔ẖa yaʻàl֥ẇ ʼé֖ber kȧ⁠nĕ̇şá̌ri֑ym yár֨ẇẕẇ֙ wĕ⁠lò֣ʼ yiygá֔ʻẇ yélĕk֖ẇ wĕ⁠lò֥ʼ yiyʻáֽpẇ׃p"],[41,1,"הַחֲרִ֤ישׁוּ אֵלַ⁠י֙ אִיִּ֔ים וּ⁠לְאֻמִּ֖ים יַחֲלִ֣יפוּ כֹ֑חַ יִגְּשׁוּ֙ אָ֣ז יְדַבֵּ֔רוּ יַחְדָּ֖ו לַ⁠מִּשְׁפָּ֥ט נִקְרָֽבָה׃","haẖàri֤yş̌ẇ ʼéla⁠y֙ ʼiyi̇֔ym ẇ⁠lĕʼumi֖̇ym yaẖàli֣ypẇ kò֑ẖa yigĕ̇ş̌ẇ֙ ʼá֣z yĕdabé̇֔rẇ yaẖĕdá֖̇w la⁠mi̇şĕ̌pá֥̇t niqĕráֽbáh׃"],[41,2,"מִ֤י הֵעִיר֙ מִ⁠מִּזְרָ֔ח צֶ֖דֶק יִקְרָאֵ֣⁠הוּ לְ⁠רַגְל֑⁠וֹ יִתֵּ֨ן לְ⁠פָנָ֤י⁠ו גּוֹיִם֙ וּ⁠מְלָכִ֣ים יַ֔רְדְּ יִתֵּ֤ן כֶּֽ⁠עָפָר֙ חַרְבּ֔⁠וֹ כְּ⁠קַ֥שׁ נִדָּ֖ף קַשְׁתּֽ⁠וֹ׃","mi֤y héʻiyr֙ mi⁠mi̇zĕrá֔ẖ ẕe֖deq yiqĕráʼé֣⁠hẇ lĕ⁠ragĕl֑⁠wò yiţé̇֨n lĕ⁠páná֤y⁠w ġwòyim֙ ẇ⁠mĕláki֣ym ya֔rĕdĕ̇ yiţé֤̇n kėֽ⁠ʻápár֙ ẖarĕḃ֔⁠wò kĕ̇⁠qa֥ş̌ nidá֖̇p qaşĕ̌ţֽ̇⁠wò׃"],[41,3,"יִרְדְּפֵ֖⁠ם יַעֲב֣וֹר שָׁל֑וֹם אֹ֥רַח בְּ⁠רַגְלָ֖י⁠ו לֹ֥א יָבֽוֹא׃","yirĕdĕ̇pé֖⁠m yaʻàb֣wòr şá̌l֑wòm ʼò֥raẖ bĕ̇⁠ragĕlá֖y⁠w lò֥ʼ yábֽwòʼ׃"],[41,4,"מִֽי־פָעַ֣ל וְ⁠עָשָׂ֔ה קֹרֵ֥א הַ⁠דֹּר֖וֹת מֵ⁠רֹ֑אשׁ אֲנִ֤י יְהוָה֙ רִאשׁ֔וֹן וְ⁠אֶת־אַחֲרֹנִ֖ים אֲנִי־הֽוּא׃","miֽy-páʻa֣l wĕ⁠ʻáşá̂֔h qòré֥ʼ ha⁠dò̇r֖wòţ mé⁠rò֑ʼş̌ ʼàni֤y yĕhwáh֙ riʼş̌֔wòn wĕ⁠ʼeţ-ʼaẖàròni֖ym ʼàniy-hֽẇʼ׃"],[41,5,"רָא֤וּ אִיִּים֙ וְ⁠יִירָ֔אוּ קְצ֥וֹת הָ⁠אָ֖רֶץ יֶחֱרָ֑דוּ קָרְב֖וּ וַ⁠יֶּאֱתָיֽוּ⁠ן׃","ráʼ֤ẇ ʼiyi̇ym֙ wĕ⁠yiyrá֔ʼẇ qĕẕ֥wòţ há⁠ʼá֖reẕ yeẖèrá֑dẇ qárĕb֖ẇ wa⁠yėʼèţáyֽẇ⁠n׃"],[41,6,"אִ֥ישׁ אֶת־רֵעֵ֖⁠הוּ יַעְזֹ֑רוּ וּ⁠לְ⁠אָחִ֖י⁠ו יֹאמַ֥ר חֲזָֽק׃","ʼi֥yş̌ ʼeţ-réʻé֖⁠hẇ yaʻĕzò֑rẇ ẇ⁠lĕ⁠ʼáẖi֖y⁠w yòʼma֥r ẖàzáֽq׃"],[41,7,"וַ⁠יְחַזֵּ֤ק חָרָשׁ֙ אֶת־צֹרֵ֔ף מַחֲלִ֥יק פַּטִּ֖ישׁ אֶת־ה֣וֹלֶם פָּ֑עַם אֹמֵ֤ר לַ⁠דֶּ֨בֶק֙ ט֣וֹב ה֔וּא וַ⁠יְחַזְּקֵ֥⁠הוּ בְ⁠מַסְמְרִ֖ים לֹ֥א יִמּֽוֹט׃ס","wa⁠yĕẖazé֤̇q ẖáráş̌֙ ʼeţ-ẕòré֔p maẖàli֥yq pȧti֖̇yş̌ ʼeţ-h֣wòlem pá֑̇ʻam ʼòmé֤r la⁠dė֨beq֙ t֣wòb h֔ẇʼ wa⁠yĕẖazĕ̇qé֥⁠hẇ bĕ⁠masĕmĕri֖ym lò֥ʼ yiṁֽwòt׃s"],[41,8,"וְ⁠אַתָּה֙ יִשְׂרָאֵ֣ל עַבְדִּ֔⁠י יַעֲקֹ֖ב אֲשֶׁ֣ר בְּחַרְתִּ֑י⁠ךָ זֶ֖רַע אַבְרָהָ֥ם אֹהֲבִֽ⁠י׃","wĕ⁠ʼaţá̇h֙ yişĕ̂ráʼé֣l ʻabĕdi̇֔⁠y yaʻàqò֖b ʼàşě֣r bĕ̇ẖarĕţi֑̇y⁠ká ze֖raʻ ʼabĕráhá֥m ʼòhàbiֽ⁠y׃"],[41,9,"אֲשֶׁ֤ר הֶחֱזַקְתִּ֨י⁠ךָ֙ מִ⁠קְצ֣וֹת הָ⁠אָ֔רֶץ וּ⁠מֵ⁠אֲצִילֶ֖י⁠הָ קְרָאתִ֑י⁠ךָ וָ⁠אֹ֤מַר לְ⁠ךָ֙ עַבְדִּ⁠י־אַ֔תָּה בְּחַרְתִּ֖י⁠ךָ וְ⁠לֹ֥א מְאַסְתִּֽי⁠ךָ׃","ʼàşě֤r heẖèzaqĕţi̇֨y⁠ká֙ mi⁠qĕẕ֣wòţ há⁠ʼá֔reẕ ẇ⁠mé⁠ʼàẕiyle֖y⁠há qĕráʼţi֑y⁠ká wá⁠ʼò֤mar lĕ⁠ká֙ ʻabĕdi̇⁠y-ʼa֔ţá̇h bĕ̇ẖarĕţi֖̇y⁠ká wĕ⁠lò֥ʼ mĕʼasĕţiֽ̇y⁠ká׃"],[41,10,"אַל־תִּירָא֙ כִּ֣י עִמְּ⁠ךָ־אָ֔נִי אַל־תִּשְׁתָּ֖ע כִּֽי־אֲנִ֣י אֱלֹהֶ֑י⁠ךָ אִמַּצְתִּ֨י⁠ךָ֙ אַף־עֲזַרְתִּ֔י⁠ךָ אַף־תְּמַכְתִּ֖י⁠ךָ בִּ⁠ימִ֥ין צִדְקִֽ⁠י׃","ʼal-ţi̇yráʼ֙ ki֣̇y ʻimĕ̇⁠ká-ʼá֔niy ʼal-ţi̇şĕ̌ţá֖̇ʻ kiֽ̇y-ʼàni֣y ʼèlòhe֑y⁠ká ʼimȧẕĕţi̇֨y⁠ká֙ ʼap-ʻàzarĕţi̇֔y⁠ká ʼap-ţĕ̇makĕţi֖̇y⁠ká bi̇⁠ymi֥yn ẕidĕqiֽ⁠y׃"],[41,11,"הֵ֤ן יֵבֹ֨שׁוּ֙ וְ⁠יִכָּ֣לְמ֔וּ כֹּ֖ל הַ⁠נֶּחֱרִ֣ים בָּ֑⁠ךְ יִֽהְי֥וּ כְ⁠אַ֛יִן וְ⁠יֹאבְד֖וּ אַנְשֵׁ֥י רִיבֶֽ⁠ךָ׃","hé֤n yébò֨ş̌ẇ֙ wĕ⁠yiká֣̇lĕm֔ẇ kò֖̇l ha⁠nėẖèri֣ym bá֑̇⁠kĕ yiֽhĕy֥ẇ kĕ⁠ʼa֛yin wĕ⁠yòʼbĕd֖ẇ ʼanĕşé֥̌y riybeֽ⁠ká׃"],[41,12,"תְּבַקְשֵׁ⁠ם֙ וְ⁠לֹ֣א תִמְצָאֵ֔⁠ם אַנְשֵׁ֖י מַצֻּתֶ֑⁠ךָ יִהְי֥וּ כְ⁠אַ֛יִן וּ⁠כְ⁠אֶ֖פֶס אַנְשֵׁ֥י מִלְחַמְתֶּֽ⁠ךָ׃","ţĕ̇baqĕşé̌⁠m֙ wĕ⁠lò֣ʼ ţimĕẕáʼé֔⁠m ʼanĕşé֖̌y maẕu̇ţe֑⁠ká yihĕy֥ẇ kĕ⁠ʼa֛yin ẇ⁠kĕ⁠ʼe֖pes ʼanĕşé֥̌y milĕẖamĕţėֽ⁠ká׃"],[41,13,"כִּ֗י אֲנִ֛י יְהוָ֥ה אֱלֹהֶ֖י⁠ךָ מַחֲזִ֣יק יְמִינֶ֑⁠ךָ הָ⁠אֹמֵ֥ר לְ⁠ךָ֛ אַל־תִּירָ֖א אֲנִ֥י עֲזַרְתִּֽי⁠ךָ׃ס","ki̇֗y ʼàni֛y yĕhwá֥h ʼèlòhe֖y⁠ká maẖàzi֣yq yĕmiyne֑⁠ká há⁠ʼòmé֥r lĕ⁠ká֛ ʼal-ţi̇yrá֖ʼ ʼàni֥y ʻàzarĕţiֽ̇y⁠ká׃s"],[41,14,"אַל־תִּֽירְאִי֙ תּוֹלַ֣עַת יַֽעֲקֹ֔ב מְתֵ֖י יִשְׂרָאֵ֑ל אֲנִ֤י עֲזַרְתִּי⁠ךְ֙ נְאֻם־יְהוָ֔ה וְ⁠גֹאֲלֵ֖⁠ךְ קְד֥וֹשׁ יִשְׂרָאֵֽל׃","ʼal-ţiֽ̇yrĕʼiy֙ ţ̇wòla֣ʻaţ yaֽʻàqò֔b mĕţé֖y yişĕ̂ráʼé֑l ʼàni֤y ʻàzarĕţi̇y⁠kĕ֙ nĕʼum-yĕhwá֔h wĕ⁠gòʼàlé֖⁠kĕ qĕd֥wòş̌ yişĕ̂ráʼéֽl׃"],[41,15,"הִנֵּ֣ה שַׂמְתִּ֗י⁠ךְ לְ⁠מוֹרַג֙ חָר֣וּץ חָדָ֔שׁ בַּ֖עַל פִּֽיפִיּ֑וֹת תָּד֤וּשׁ הָרִים֙ וְ⁠תָדֹ֔ק וּ⁠גְבָע֖וֹת כַּ⁠מֹּ֥ץ תָּשִֽׂים׃","hiné֣̇h şâmĕţi̇֗y⁠kĕ lĕ⁠mwòrag֙ ẖár֣ẇẕ ẖádá֔ş̌ bȧ֖ʻal piֽ̇ypiẏ֑wòţ ţá̇d֤ẇş̌ háriym֙ wĕ⁠ţádò֔q ẇ⁠gĕbáʻ֖wòţ kȧ⁠mò֥̇ẕ ţá̇şîֽym׃"],[41,16,"תִּזְרֵ⁠ם֙ וְ⁠ר֣וּחַ תִּשָּׂאֵ֔⁠ם וּ⁠סְעָרָ֖ה תָּפִ֣יץ אוֹתָ֑⁠ם וְ⁠אַתָּה֙ תָּגִ֣יל בַּֽ⁠יהוָ֔ה בִּ⁠קְד֥וֹשׁ יִשְׂרָאֵ֖ל תִּתְהַלָּֽל׃פ","ţi̇zĕré⁠m֙ wĕ⁠r֣ẇẖa ţi̇şá̇̂ʼé֔⁠m ẇ⁠sĕʻárá֖h ţá̇pi֣yẕ ʼwòţá֑⁠m wĕ⁠ʼaţá̇h֙ ţá̇gi֣yl bȧֽ⁠yhwá֔h bi̇⁠qĕd֥wòş̌ yişĕ̂ráʼé֖l ţi̇ţĕhaláֽ̇l׃p"],[41,17,"הָ⁠עֲנִיִּ֨ים וְ⁠הָ⁠אֶבְיוֹנִ֜ים מְבַקְשִׁ֥ים מַ֨יִם֙ וָ⁠אַ֔יִן לְשׁוֹנָ֖⁠ם בַּ⁠צָּמָ֣א נָשָׁ֑תָּה אֲנִ֤י יְהוָה֙ אֶעֱנֵ֔⁠ם אֱלֹהֵ֥י יִשְׂרָאֵ֖ל לֹ֥א אֶעֶזְבֵֽ⁠ם׃","há⁠ʻàniyi̇֨ym wĕ⁠há⁠ʼebĕywòni֜ym mĕbaqĕşǐ֥ym ma֨yim֙ wá⁠ʼa֔yin lĕş̌wòná֖⁠m bȧ⁠ẕá̇má֣ʼ náşá֑̌ţá̇h ʼàni֤y yĕhwáh֙ ʼeʻèné֔⁠m ʼèlòhé֥y yişĕ̂ráʼé֖l lò֥ʼ ʼeʻezĕbéֽ⁠m׃"],[41,18,"אֶפְתַּ֤ח עַל־שְׁפָיִים֙ נְהָר֔וֹת וּ⁠בְ⁠ת֥וֹךְ בְּקָע֖וֹת מַעְיָנ֑וֹת אָשִׂ֤ים מִדְבָּר֙ לַ⁠אֲגַם־מַ֔יִם וְ⁠אֶ֥רֶץ צִיָּ֖ה לְ⁠מוֹצָ֥אֵי מָֽיִם׃","ʼepĕţȧ֤ẖ ʻal-şĕ̌páyiym֙ nĕhár֔wòţ ẇ⁠bĕ⁠ţ֥wòkĕ bĕ̇qáʻ֖wòţ maʻĕyán֑wòţ ʼáşî֤ym midĕbá̇r֙ la⁠ʼàgam-ma֔yim wĕ⁠ʼe֥reẕ ẕiyá֖̇h lĕ⁠mwòẕá֥ʼéy máֽyim׃"],[41,19,"אֶתֵּ֤ן בַּ⁠מִּדְבָּר֙ אֶ֣רֶז שִׁטָּ֔ה וַ⁠הֲדַ֖ס וְ⁠עֵ֣ץ שָׁ֑מֶן אָשִׂ֣ים בָּ⁠עֲרָבָ֗ה בְּר֛וֹשׁ תִּדְהָ֥ר וּ⁠תְאַשּׁ֖וּר יַחְדָּֽו׃","ʼeţé֤̇n bȧ⁠mi̇dĕbá̇r֙ ʼe֣rez şǐtá̇֔h wa⁠hàda֖s wĕ⁠ʻé֣ẕ şá֑̌men ʼáşî֣ym bá̇⁠ʻàrábá֗h bĕ̇r֛wòş̌ ţi̇dĕhá֥r ẇ⁠ţĕʼaş֖̇̌ẇr yaẖĕdáֽ̇w׃"],[41,20,"לְמַ֧עַן יִרְא֣וּ וְ⁠יֵדְע֗וּ וְ⁠יָשִׂ֤ימוּ וְ⁠יַשְׂכִּ֨ילוּ֙ יַחְדָּ֔ו כִּ֥י יַד־יְהוָ֖ה עָ֣שְׂתָה זֹּ֑את וּ⁠קְד֥וֹשׁ יִשְׂרָאֵ֖ל בְּרָאָֽ⁠הּ׃פ","lĕma֧ʻan yirĕʼ֣ẇ wĕ⁠yédĕʻ֗ẇ wĕ⁠yáşî֤ymẇ wĕ⁠yaşĕ̂ki̇֨ylẇ֙ yaẖĕdá̇֔w ki֥̇y yad-yĕhwá֖h ʻá֣şĕ̂ţáh zò֑̇ʼţ ẇ⁠qĕd֥wòş̌ yişĕ̂ráʼé֖l bĕ̇ráʼáֽ⁠ḣ׃p"],[41,21,"קָרְב֥וּ רִֽיבְ⁠כֶ֖ם יֹאמַ֣ר יְהוָ֑ה הַגִּ֨ישׁוּ֙ עֲצֻמ֣וֹתֵי⁠כֶ֔ם יֹאמַ֖ר מֶ֥לֶךְ יַעֲקֹֽב׃","qárĕb֥ẇ riֽybĕ⁠ke֖m yòʼma֣r yĕhwá֑h hagi̇֨yş̌ẇ֙ ʻàẕum֣wòţéy⁠ke֔m yòʼma֖r me֥lekĕ yaʻàqòֽb׃"],[41,22,"יַגִּ֨ישׁוּ֙ וְ⁠יַגִּ֣ידוּ לָ֔⁠נוּ אֵ֖ת אֲשֶׁ֣ר תִּקְרֶ֑ינָה הָ⁠רִאשֹׁנ֣וֹת ׀ מָ֣ה הֵ֗נָּה הַגִּ֜ידוּ וְ⁠נָשִׂ֤ימָה לִבֵּ֨⁠נוּ֙ וְ⁠נֵדְעָ֣ה אַחֲרִיתָ֔⁠ן א֥וֹ הַ⁠בָּא֖וֹת הַשְׁמִיעֻֽ⁠נוּ׃","yagi̇֨yş̌ẇ֙ wĕ⁠yagi֣̇ydẇ lá֔⁠nẇ ʼé֖ţ ʼàşě֣r ţi̇qĕre֑ynáh há⁠riʼşò̌n֣wòţ ׀ má֣h hé֗ná̇h hagi̇֜ydẇ wĕ⁠náşî֤ymáh libé̇֨⁠nẇ֙ wĕ⁠nédĕʻá֣h ʼaẖàriyţá֔⁠n ʼ֥wò ha⁠bá̇ʼ֖wòţ haşĕ̌miyʻuֽ⁠nẇ׃"],[41,23,"הַגִּ֨ידוּ֙ הָ⁠אֹתִיּ֣וֹת לְ⁠אָח֔וֹר וְ⁠נֵ֣דְעָ֔ה כִּ֥י אֱלֹהִ֖ים אַתֶּ֑ם אַף־תֵּיטִ֣יבוּ וְ⁠תָרֵ֔עוּ וְ⁠נִשְׁתָּ֖עָה ו⁠נרא יַחְדָּֽו׃","hagi̇֨ydẇ֙ há⁠ʼòţiẏ֣wòţ lĕ⁠ʼáẖ֔wòr wĕ⁠né֣dĕʻá֔h ki֥̇y ʼèlòhi֖ym ʼaţė֑m ʼap-ţé̇yti֣ybẇ wĕ⁠ţáré֔ʻẇ wĕ⁠nişĕ̌ţá֖̇ʻáh w⁠nrʼ yaẖĕdáֽ̇w׃"],[41,24,"הֵן־אַתֶּ֣ם מֵ⁠אַ֔יִן וּ⁠פָעָלְ⁠כֶ֖ם מֵ⁠אָ֑פַע תּוֹעֵבָ֖ה יִבְחַ֥ר בָּ⁠כֶֽם׃","hén-ʼaţė֣m mé⁠ʼa֔yin ẇ⁠páʻálĕ⁠ke֖m mé⁠ʼá֑paʻ ţ̇wòʻébá֖h yibĕẖa֥r bá̇⁠keֽm׃"],[41,25,"הַעִיר֤וֹתִי מִ⁠צָּפוֹן֙ וַ⁠יַּ֔את מִ⁠מִּזְרַח־שֶׁ֖מֶשׁ יִקְרָ֣א בִ⁠שְׁמִ֑⁠י וְ⁠יָבֹ֤א סְגָנִים֙ כְּמוֹ־חֹ֔מֶר וּ⁠כְמ֥וֹ יוֹצֵ֖ר יִרְמָס־טִֽיט׃","haʻiyr֤wòţiy mi⁠ẕá̇pwòn֙ wa⁠yȧ֔ʼţ mi⁠mi̇zĕraẖ-şě֖meş̌ yiqĕrá֣ʼ bi⁠şĕ̌mi֑⁠y wĕ⁠yábò֤ʼ sĕgániym֙ kĕ̇mwò-ẖò֔mer ẇ⁠kĕm֥wò ywòẕé֖r yirĕmás-tiֽyt׃"],[41,26,"מִֽי־הִגִּ֤יד מֵ⁠רֹאשׁ֙ וְ⁠נֵדָ֔עָה וּ⁠מִ⁠לְּ⁠פָנִ֖ים וְ⁠נֹאמַ֣ר צַדִּ֑יק אַ֣ף אֵין־מַגִּ֗יד אַ֚ף אֵ֣ין מַשְׁמִ֔יעַ אַ֥ף אֵין־שֹׁמֵ֖עַ אִמְרֵי⁠כֶֽם׃","miֽy-higi֤̇yd mé⁠ròʼş̌֙ wĕ⁠nédá֔ʻáh ẇ⁠mi⁠lĕ̇⁠páni֖ym wĕ⁠nòʼma֣r ẕadi֑̇yq ʼa֣p ʼéyn-magi̇֗yd ʼa֚p ʼé֣yn maşĕ̌mi֔yʻa ʼa֥p ʼéyn-şò̌mé֖ʻa ʼimĕréy⁠keֽm׃"],[41,27,"רִאשׁ֥וֹן לְ⁠צִיּ֖וֹן הִנֵּ֣ה הִנָּ֑⁠ם וְ⁠לִ⁠ירוּשָׁלִַ֖ם מְבַשֵּׂ֥ר אֶתֵּֽן׃","riʼş֥̌wòn lĕ⁠ẕiẏ֖wòn hiné֣̇h hiná֑̇⁠m wĕ⁠li⁠yrẇşá̌lia֖m mĕbaşé֥̇̂r ʼeţéֽ̇n׃"],[41,28,"וְ⁠אֵ֨רֶא֙ וְ⁠אֵ֣ין אִ֔ישׁ וּ⁠מֵ⁠אֵ֖לֶּה וְ⁠אֵ֣ין יוֹעֵ֑ץ וְ⁠אֶשְׁאָלֵ֖⁠ם וְ⁠יָשִׁ֥יבוּ דָבָֽר׃","wĕ⁠ʼé֨reʼ֙ wĕ⁠ʼé֣yn ʼi֔yş̌ ẇ⁠mé⁠ʼé֖lėh wĕ⁠ʼé֣yn ywòʻé֑ẕ wĕ⁠ʼeşĕ̌ʼálé֖⁠m wĕ⁠yáşǐ֥ybẇ dábáֽr׃"],[41,29,"הֵ֣ן כֻּלָּ֔⁠ם אָ֥וֶן אֶ֖פֶס מַעֲשֵׂי⁠הֶ֑ם ר֥וּחַ וָ⁠תֹ֖הוּ נִסְכֵּי⁠הֶֽם׃פ","hé֣n ku̇lá̇֔⁠m ʼá֥wen ʼe֖pes maʻàşé̂y⁠he֑m r֥ẇẖa wá⁠ţò֖hẇ nisĕké̇y⁠heֽm׃p"],[42,1,"הֵ֤ן עַבְדִּ⁠י֙ אֶתְמָךְ־בּ֔⁠וֹ בְּחִירִ֖⁠י רָצְתָ֣ה נַפְשִׁ֑⁠י נָתַ֤תִּי רוּחִ⁠י֙ עָלָ֔י⁠ו מִשְׁפָּ֖ט לַ⁠גּוֹיִ֥ם יוֹצִֽיא׃","hé֤n ʻabĕdi̇⁠y֙ ʼeţĕmákĕ-ḃ֔⁠wò bĕ̇ẖiyri֖⁠y ráẕĕţá֣h napĕşǐ֑⁠y náţa֤ţi̇y rẇẖi⁠y֙ ʻálá֔y⁠w mişĕ̌pá֖̇t la⁠ġwòyi֥m ywòẕiֽyʼ׃"],[42,2,"לֹ֥א יִצְעַ֖ק וְ⁠לֹ֣א יִשָּׂ֑א וְ⁠לֹֽא־יַשְׁמִ֥יעַ בַּ⁠ח֖וּץ קוֹלֽ⁠וֹ׃","lò֥ʼ yiẕĕʻa֖q wĕ⁠lò֣ʼ yişá֑̇̂ʼ wĕ⁠lòֽʼ-yaşĕ̌mi֥yʻa bȧ⁠ẖ֖ẇẕ qwòlֽ⁠wò׃"],[42,3,"קָנֶ֤ה רָצוּץ֙ לֹ֣א יִשְׁבּ֔וֹר וּ⁠פִשְׁתָּ֥ה כֵהָ֖ה לֹ֣א יְכַבֶּ֑⁠נָּה לֶ⁠אֱמֶ֖ת יוֹצִ֥יא מִשְׁפָּֽט׃","qáne֤h ráẕẇẕ֙ lò֣ʼ yişĕ̌ḃ֔wòr ẇ⁠pişĕ̌ţá֥̇h kéhá֖h lò֣ʼ yĕkabė֑⁠ná̇h le⁠ʼème֖ţ ywòẕi֥yʼ mişĕ̌páֽ̇t׃"],[42,4,"לֹ֤א יִכְהֶה֙ וְ⁠לֹ֣א יָר֔וּץ עַד־יָשִׂ֥ים בָּ⁠אָ֖רֶץ מִשְׁפָּ֑ט וּ⁠לְ⁠תוֹרָת֖⁠וֹ אִיִּ֥ים יְיַחֵֽילוּ׃פ","lò֤ʼ yikĕheh֙ wĕ⁠lò֣ʼ yár֔ẇẕ ʻad-yáşî֥ym bá̇⁠ʼá֖reẕ mişĕ̌pá֑̇t ẇ⁠lĕ⁠ţwòráţ֖⁠wò ʼiyi֥̇ym yĕyaẖéֽylẇ׃p"],[42,5,"כֹּֽה־אָמַ֞ר הָ⁠אֵ֣ל ׀ יְהוָ֗ה בּוֹרֵ֤א הַ⁠שָּׁמַ֨יִם֙ וְ⁠נ֣וֹטֵי⁠הֶ֔ם רֹקַ֥ע הָ⁠אָ֖רֶץ וְ⁠צֶאֱצָאֶ֑י⁠הָ נֹתֵ֤ן נְשָׁמָה֙ לָ⁠עָ֣ם עָלֶ֔י⁠הָ וְ⁠ר֖וּחַ לַ⁠הֹלְכִ֥ים בָּֽ⁠הּ׃","kòֽ̇h-ʼáma֞r há⁠ʼé֣l ׀ yĕhwá֗h ḃwòré֤ʼ ha⁠şá̇̌ma֨yim֙ wĕ⁠n֣wòtéy⁠he֔m ròqa֥ʻ há⁠ʼá֖reẕ wĕ⁠ẕeʼèẕáʼe֑y⁠há nòţé֤n nĕşá̌máh֙ lá⁠ʻá֣m ʻále֔y⁠há wĕ⁠r֖ẇẖa la⁠hòlĕki֥ym báֽ̇⁠ḣ׃"],[42,6,"אֲנִ֧י יְהוָ֛ה קְרָאתִ֥י⁠ךָֽ בְ⁠צֶ֖דֶק וְ⁠אַחְזֵ֣ק בְּ⁠יָדֶ֑⁠ךָ וְ⁠אֶצָּרְ⁠ךָ֗ וְ⁠אֶתֶּנְ⁠ךָ֛ לִ⁠בְרִ֥ית עָ֖ם לְ⁠א֥וֹר גּוֹיִֽם׃","ʼàni֧y yĕhwá֛h qĕráʼţi֥y⁠káֽ bĕ⁠ẕe֖deq wĕ⁠ʼaẖĕzé֣q bĕ̇⁠yáde֑⁠ká wĕ⁠ʼeẕá̇rĕ⁠ká֗ wĕ⁠ʼeţėnĕ⁠ká֛ li⁠bĕri֥yţ ʻá֖m lĕ⁠ʼ֥wòr ġwòyiֽm׃"],[42,7,"לִ⁠פְקֹ֖חַ עֵינַ֣יִם עִוְר֑וֹת לְ⁠הוֹצִ֤יא מִ⁠מַּסְגֵּר֙ אַסִּ֔יר מִ⁠בֵּ֥ית כֶּ֖לֶא יֹ֥שְׁבֵי חֹֽשֶׁךְ׃","li⁠pĕqò֖ẖa ʻéyna֣yim ʻiwĕr֑wòţ lĕ⁠hwòẕi֤yʼ mi⁠mȧsĕgé̇r֙ ʼasi̇֔yr mi⁠bé֥̇yţ kė֖leʼ yò֥şĕ̌béy ẖòֽşěkĕ׃"],[42,8,"אֲנִ֥י יְהוָ֖ה ה֣וּא שְׁמִ֑⁠י וּ⁠כְבוֹדִ⁠י֙ לְ⁠אַחֵ֣ר לֹֽא־אֶתֵּ֔ן וּ⁠תְהִלָּתִ֖⁠י לַ⁠פְּסִילִֽים׃","ʼàni֥y yĕhwá֖h h֣ẇʼ şĕ̌mi֑⁠y ẇ⁠kĕbwòdi⁠y֙ lĕ⁠ʼaẖé֣r lòֽʼ-ʼeţé̇֔n ẇ⁠ţĕhilá̇ţi֖⁠y la⁠pĕ̇siyliֽym׃"],[42,9,"הָ⁠רִֽאשֹׁנ֖וֹת הִנֵּה־בָ֑אוּ וַֽ⁠חֲדָשׁוֹת֙ אֲנִ֣י מַגִּ֔יד בְּ⁠טֶ֥רֶם תִּצְמַ֖חְנָה אַשְׁמִ֥יע אֶתְ⁠כֶֽם׃פ","há⁠riֽʼşò̌n֖wòţ hiné̇h-bá֑ʼẇ waֽ⁠ẖàdáş̌wòţ֙ ʼàni֣y magi̇֔yd bĕ̇⁠te֥rem ţi̇ẕĕma֖ẖĕnáh ʼaşĕ̌mi֥yʻ ʼeţĕ⁠keֽm׃p"],[42,10,"שִׁ֤ירוּ לַֽ⁠יהוָה֙ שִׁ֣יר חָדָ֔שׁ תְּהִלָּת֖⁠וֹ מִ⁠קְצֵ֣ה הָ⁠אָ֑רֶץ יוֹרְדֵ֤י הַ⁠יָּם֙ וּ⁠מְלֹא֔⁠וֹ אִיִּ֖ים וְ⁠יֹשְׁבֵי⁠הֶֽם׃","şǐ֤yrẇ laֽ⁠yhwáh֙ şǐ֣yr ẖádá֔ş̌ ţĕ̇hilá̇ţ֖⁠wò mi⁠qĕẕé֣h há⁠ʼá֑reẕ ywòrĕdé֤y ha⁠yá̇m֙ ẇ⁠mĕlòʼ֔⁠wò ʼiyi֖̇ym wĕ⁠yòşĕ̌béy⁠heֽm׃"],[42,11,"יִשְׂא֤וּ מִדְבָּר֙ וְ⁠עָרָ֔י⁠ו חֲצֵרִ֖ים תֵּשֵׁ֣ב קֵדָ֑ר יָרֹ֨נּוּ֙ יֹ֣שְׁבֵי סֶ֔לַע מֵ⁠רֹ֥אשׁ הָרִ֖ים יִצְוָֽחוּ׃","yişĕ̂ʼ֤ẇ midĕbá̇r֙ wĕ⁠ʻárá֔y⁠w ẖàẕéri֖ym ţé̇şé֣̌b qédá֑r yárò֨ṅẇ֙ yò֣şĕ̌béy se֔laʻ mé⁠rò֥ʼş̌ hári֖ym yiẕĕwáֽẖẇ׃"],[42,12,"יָשִׂ֥ימוּ לַֽ⁠יהוָ֖ה כָּב֑וֹד וּ⁠תְהִלָּת֖⁠וֹ בָּ⁠אִיִּ֥ים יַגִּֽידוּ׃","yáşî֥ymẇ laֽ⁠yhwá֖h ká̇b֑wòd ẇ⁠ţĕhilá̇ţ֖⁠wò bá̇⁠ʼiyi֥̇ym yagiֽ̇ydẇ׃"],[42,13,"יְהוָה֙ כַּ⁠גִּבּ֣וֹר יֵצֵ֔א כְּ⁠אִ֥ישׁ מִלְחָמ֖וֹת יָעִ֣יר קִנְאָ֑ה יָרִ֨יעַ֙ אַף־יַצְרִ֔יחַ עַל־אֹיְבָ֖י⁠ו יִתְגַּבָּֽר׃ס","yĕhwáh֙ kȧ⁠gi̇ḃ֣wòr yéẕé֔ʼ kĕ̇⁠ʼi֥yş̌ milĕẖám֖wòţ yáʻi֣yr qinĕʼá֑h yári֨yʻa֙ ʼap-yaẕĕri֔yẖa ʻal-ʼòyĕbá֖y⁠w yiţĕgȧbáֽ̇r׃s"],[42,14,"הֶחֱשֵׁ֨יתִי֙ מֵֽ⁠עוֹלָ֔ם אַחֲרִ֖ישׁ אֶתְאַפָּ֑ק כַּ⁠יּוֹלֵדָ֣ה אֶפְעֶ֔ה אֶשֹּׁ֥ם וְ⁠אֶשְׁאַ֖ף יָֽחַד׃","heẖèşé̌֨yţiy֙ méֽ⁠ʻwòlá֔m ʼaẖàri֖yş̌ ʼeţĕʼapá֑̇q kȧ⁠ẏwòlédá֣h ʼepĕʻe֔h ʼeşò֥̇̌m wĕ⁠ʼeşĕ̌ʼa֖p yáֽẖad׃"],[42,15,"אַחֲרִ֤יב הָרִים֙ וּ⁠גְבָע֔וֹת וְ⁠כָל־עֶשְׂבָּ֖⁠ם אוֹבִ֑ישׁ וְ⁠שַׂמְתִּ֤י נְהָרוֹת֙ לָֽ⁠אִיִּ֔ים וַ⁠אֲגַמִּ֖ים אוֹבִֽישׁ׃","ʼaẖàri֤yb háriym֙ ẇ⁠gĕbáʻ֔wòţ wĕ⁠kál-ʻeşĕ̂bá֖̇⁠m ʼwòbi֑yş̌ wĕ⁠şâmĕţi֤̇y nĕhárwòţ֙ lֽá⁠ʼiyi̇֔ym wa⁠ʼàgami֖̇ym ʼwòbiֽyş̌׃"],[42,16,"וְ⁠הוֹלַכְתִּ֣י עִוְרִ֗ים בְּ⁠דֶ֨רֶךְ֙ לֹ֣א יָדָ֔עוּ בִּ⁠נְתִיב֥וֹת לֹֽא־יָדְע֖וּ אַדְרִיכֵ֑⁠ם אָשִׂים֩ מַחְשָׁ֨ךְ לִ⁠פְנֵי⁠הֶ֜ם לָ⁠א֗וֹר וּ⁠מַֽעֲקַשִּׁים֙ לְ⁠מִישׁ֔וֹר אֵ֚לֶּה הַ⁠דְּבָרִ֔ים עֲשִׂיתִ֖⁠ם וְ⁠לֹ֥א עֲזַבְתִּֽי⁠ם׃","wĕ⁠hwòlakĕţi֣̇y ʻiwĕri֗ym bĕ̇⁠de֨rekĕ֙ lò֣ʼ yádá֔ʻẇ bi̇⁠nĕţiyb֥wòţ lòֽʼ-yádĕʻ֖ẇ ʼadĕriyké֑⁠m ʼáşîym֩ maẖĕşá̌֨kĕ li⁠pĕnéy⁠he֜m lá⁠ʼ֗wòr ẇ⁠maֽʻàqaşi̇̌ym֙ lĕ⁠miyş̌֔wòr ʼé֚lėh ha⁠dĕ̇bári֔ym ʻàşîyţi֖⁠m wĕ⁠lò֥ʼ ʻàzabĕţiֽ̇y⁠m׃"],[42,17,"נָסֹ֤גוּ אָחוֹר֙ יֵבֹ֣שׁוּ בֹ֔שֶׁת הַ⁠בֹּטְחִ֖ים בַּ⁠פָּ֑סֶל הָ⁠אֹמְרִ֥ים לְ⁠מַסֵּכָ֖ה אַתֶּ֥ם אֱלֹהֵֽי⁠נוּ׃ס","násò֤gẇ ʼáẖwòr֙ yébò֣ş̌ẇ bò֔şěţ ha⁠bò̇tĕẖi֖ym bȧ⁠pá֑̇sel há⁠ʼòmĕri֥ym lĕ⁠masé̇ká֖h ʼaţė֥m ʼèlòhéֽy⁠nẇ׃s"],[42,18,"הַ⁠חֵרְשִׁ֖ים שְׁמָ֑עוּ וְ⁠הַ⁠עִוְרִ֖ים הַבִּ֥יטוּ לִ⁠רְאֽוֹת׃","ha⁠ẖérĕşǐ֖ym şĕ̌má֑ʻẇ wĕ⁠ha⁠ʻiwĕri֖ym habi֥̇ytẇ li⁠rĕʼֽwòţ׃"],[42,19,"מִ֤י עִוֵּר֙ כִּ֣י אִם־עַבְדִּ֔⁠י וְ⁠חֵרֵ֖שׁ כְּ⁠מַלְאָכִ֣⁠י אֶשְׁלָ֑ח מִ֤י עִוֵּר֙ כִּ⁠מְשֻׁלָּ֔ם וְ⁠עִוֵּ֖ר כְּ⁠עֶ֥בֶד יְהוָֽה׃","mi֤y ʻiwé̇r֙ ki֣̇y ʼim-ʻabĕdi̇֔⁠y wĕ⁠ẖéré֖ş̌ kĕ̇⁠malĕʼáki֣⁠y ʼeşĕ̌lá֑ẖ mi֤y ʻiwé̇r֙ ki̇⁠mĕşǔlá̇֔m wĕ⁠ʻiwé֖̇r kĕ̇⁠ʻe֥bed yĕhwáֽh׃"],[42,20,"ראית רַבּ֖וֹת וְ⁠לֹ֣א תִשְׁמֹ֑ר פָּק֥וֹחַ אָזְנַ֖יִם וְ⁠לֹ֥א יִשְׁמָֽע׃","rʼyţ raḃ֖wòţ wĕ⁠lò֣ʼ ţişĕ̌mò֑r pá̇q֥wòẖa ʼázĕna֖yim wĕ⁠lò֥ʼ yişĕ̌máֽʻ׃"],[42,21,"יְהוָ֥ה חָפֵ֖ץ לְמַ֣עַן צִדְק֑⁠וֹ יַגְדִּ֥יל תּוֹרָ֖ה וְ⁠יַאְדִּֽיר׃","yĕhwá֥h ẖápé֖ẕ lĕma֣ʻan ẕidĕq֑⁠wò yagĕdi֥̇yl ţ̇wòrá֖h wĕ⁠yaʼĕdiֽ̇yr׃"],[42,22,"וְ⁠הוּא֮ עַם־בָּז֣וּז וְ⁠שָׁסוּי֒ הָפֵ֤חַ בַּֽ⁠חוּרִים֙ כֻּלָּ֔⁠ם וּ⁠בְ⁠בָתֵּ֥י כְלָאִ֖ים הָחְבָּ֑אוּ הָי֤וּ לָ⁠בַז֙ וְ⁠אֵ֣ין מַצִּ֔יל מְשִׁסָּ֖ה וְ⁠אֵין־אֹמֵ֥ר הָשַֽׁב׃","wĕ⁠hẇʼ֮ ʻam-bá̇z֣ẇz wĕ⁠şá̌sẇy֒ hápé֤ẖa bȧֽ⁠ẖẇriym֙ ku̇lá̇֔⁠m ẇ⁠bĕ⁠báţé֥̇y kĕláʼi֖ym háẖĕbá֑̇ʼẇ háy֤ẇ lá⁠baz֙ wĕ⁠ʼé֣yn maẕi̇֔yl mĕşǐsá֖̇h wĕ⁠ʼéyn-ʼòmé֥r háşǎֽb׃"],[42,23,"מִ֥י בָ⁠כֶ֖ם יַאֲזִ֣ין זֹ֑את יַקְשִׁ֥ב וְ⁠יִשְׁמַ֖ע לְ⁠אָחֽוֹר׃","mi֥y bá⁠ke֖m yaʼàzi֣yn zò֑ʼţ yaqĕşǐ֥b wĕ⁠yişĕ̌ma֖ʻ lĕ⁠ʼáẖֽwòr׃"],[42,24,"מִֽי־נָתַ֨ן ל⁠משוסה יַעֲקֹ֛ב וְ⁠יִשְׂרָאֵ֥ל לְ⁠בֹזְזִ֖ים הֲ⁠ל֣וֹא יְהוָ֑ה ז֚וּ חָטָ֣אנוּ ל֔⁠וֹ וְ⁠לֹֽא־אָב֤וּ בִ⁠דְרָכָי⁠ו֙ הָל֔וֹךְ וְ⁠לֹ֥א שָׁמְע֖וּ בְּ⁠תוֹרָתֽ⁠וֹ׃","miֽy-náţa֨n l⁠mşwsh yaʻàqò֛b wĕ⁠yişĕ̂ráʼé֥l lĕ⁠bòzĕzi֖ym hà⁠l֣wòʼ yĕhwá֑h z֚ẇ ẖátá֣ʼnẇ l֔⁠wò wĕ⁠lòֽʼ-ʼáb֤ẇ bi⁠dĕrákáy⁠w֙ hál֔wòkĕ wĕ⁠lò֥ʼ şá̌mĕʻ֖ẇ bĕ̇⁠ţwòráţֽ⁠wò׃"],[42,25,"וַ⁠יִּשְׁפֹּ֤ךְ עָלָי⁠ו֙ חֵמָ֣ה אַפּ֔⁠וֹ וֶ⁠עֱז֖וּז מִלְחָמָ֑ה וַ⁠תְּלַהֲטֵ֤⁠הוּ מִ⁠סָּבִיב֙ וְ⁠לֹ֣א יָדָ֔ע וַ⁠תִּבְעַר־בּ֖⁠וֹ וְ⁠לֹא־יָשִׂ֥ים עַל־לֵֽב׃פ","wa⁠yi̇şĕ̌pò֤̇kĕ ʻáláy⁠w֙ ẖémá֣h ʼaṗ֔⁠wò we⁠ʻèz֖ẇz milĕẖámá֑h wa⁠ţĕ̇lahàté֤⁠hẇ mi⁠sá̇biyb֙ wĕ⁠lò֣ʼ yádá֔ʻ wa⁠ţi̇bĕʻar-ḃ֖⁠wò wĕ⁠lòʼ-yáşî֥ym ʻal-léֽb׃p"],[43,1,"וְ⁠עַתָּ֞ה כֹּֽה־אָמַ֤ר יְהוָה֙ בֹּרַאֲ⁠ךָ֣ יַעֲקֹ֔ב וְ⁠יֹצֶרְ⁠ךָ֖ יִשְׂרָאֵ֑ל אַל־תִּירָא֙ כִּ֣י גְאַלְתִּ֔י⁠ךָ קָרָ֥אתִי בְ⁠שִׁמְ⁠ךָ֖ לִ⁠י־אָֽתָּה׃","wĕ⁠ʻaţá̇֞h kòֽ̇h-ʼáma֤r yĕhwáh֙ bò̇raʼà⁠ká֣ yaʻàqò֔b wĕ⁠yòẕerĕ⁠ká֖ yişĕ̂ráʼé֑l ʼal-ţi̇yráʼ֙ ki֣̇y gĕʼalĕţi̇֔y⁠ká qárá֥ʼţiy bĕ⁠şǐmĕ⁠ká֖ li⁠y-ʼáֽţá̇h׃"],[43,2,"כִּֽי־תַעֲבֹ֤ר בַּ⁠מַּ֨יִם֙ אִתְּ⁠ךָ־אָ֔נִי וּ⁠בַ⁠נְּהָר֖וֹת לֹ֣א יִשְׁטְפ֑וּ⁠ךָ כִּֽי־תֵלֵ֤ךְ בְּמוֹ־אֵשׁ֙ לֹ֣א תִכָּוֶ֔ה וְ⁠לֶהָבָ֖ה לֹ֥א תִבְעַר־בָּֽ⁠ךְ׃","kiֽ̇y-ţaʻàbò֤r bȧ⁠mȧ֨yim֙ ʼiţĕ̇⁠ká-ʼá֔niy ẇ⁠ba⁠nĕ̇hár֖wòţ lò֣ʼ yişĕ̌tĕp֑ẇ⁠ká kiֽ̇y-ţélé֤kĕ bĕ̇mwò-ʼéş̌֙ lò֣ʼ ţiká̇we֔h wĕ⁠lehábá֖h lò֥ʼ ţibĕʻar-báֽ̇⁠kĕ׃"],[43,3,"כִּ֗י אֲנִי֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ קְד֥וֹשׁ יִשְׂרָאֵ֖ל מוֹשִׁיעֶ֑⁠ךָ נָתַ֤תִּי כָפְרְ⁠ךָ֙ מִצְרַ֔יִם כּ֥וּשׁ וּ⁠סְבָ֖א תַּחְתֶּֽי⁠ךָ׃","ki̇֗y ʼàniy֙ yĕhwá֣h ʼèlòhe֔y⁠ká qĕd֥wòş̌ yişĕ̂ráʼé֖l mwòşǐyʻe֑⁠ká náţa֤ţi̇y kápĕrĕ⁠ká֙ miẕĕra֔yim k֥̇ẇş̌ ẇ⁠sĕbá֖ʼ ţȧẖĕţėֽy⁠ká׃"],[43,4,"מֵ⁠אֲשֶׁ֨ר יָקַ֧רְתָּ בְ⁠עֵינַ֛⁠י נִכְבַּ֖דְתָּ וַ⁠אֲנִ֣י אֲהַבְתִּ֑י⁠ךָ וְ⁠אֶתֵּ֤ן אָדָם֙ תַּחְתֶּ֔י⁠ךָ וּ⁠לְאֻמִּ֖ים תַּ֥חַת נַפְשֶֽׁ⁠ךָ׃","mé⁠ʼàşě֨r yáqa֧rĕţá̇ bĕ⁠ʻéyna֛⁠y nikĕbȧ֖dĕţá̇ wa⁠ʼàni֣y ʼàhabĕţi֑̇y⁠ká wĕ⁠ʼeţé֤̇n ʼádám֙ ţȧẖĕţė֔y⁠ká ẇ⁠lĕʼumi֖̇ym ţȧ֥ẖaţ napĕşěֽ⁠ká׃"],[43,5,"אַל־תִּירָ֖א כִּ֣י אִתְּ⁠ךָ־אָ֑נִי מִ⁠מִּזְרָח֙ אָבִ֣יא זַרְעֶ֔⁠ךָ וּ⁠מִֽ⁠מַּעֲרָ֖ב אֲקַבְּצֶֽ⁠ךָּ׃","ʼal-ţi̇yrá֖ʼ ki֣̇y ʼiţĕ̇⁠ká-ʼá֑niy mi⁠mi̇zĕráẖ֙ ʼábi֣yʼ zarĕʻe֔⁠ká ẇ⁠miֽ⁠mȧʻàrá֖b ʼàqabĕ̇ẕeֽ⁠ká̇׃"],[43,6,"אֹמַ֤ר לַ⁠צָּפוֹן֙ תֵּ֔נִי וּ⁠לְ⁠תֵימָ֖ן אַל־תִּכְלָ֑אִי הָבִ֤יאִי בָנַ⁠י֙ מֵ⁠רָח֔וֹק וּ⁠בְנוֹתַ֖⁠י מִ⁠קְצֵ֥ה הָ⁠אָֽרֶץ׃","ʼòma֤r la⁠ẕá̇pwòn֙ ţé̇֔niy ẇ⁠lĕ⁠ţéymá֖n ʼal-ţi̇kĕlá֑ʼiy hábi֤yʼiy bána⁠y֙ mé⁠ráẖ֔wòq ẇ⁠bĕnwòţa֖⁠y mi⁠qĕẕé֥h há⁠ʼáֽreẕ׃"],[43,7,"כֹּ֚ל הַ⁠נִּקְרָ֣א בִ⁠שְׁמִ֔⁠י וְ⁠לִ⁠כְבוֹדִ֖⁠י בְּרָאתִ֑י⁠ו יְצַרְתִּ֖י⁠ו אַף־עֲשִׂיתִֽי⁠ו׃","kò֚̇l ha⁠ni̇qĕrá֣ʼ bi⁠şĕ̌mi֔⁠y wĕ⁠li⁠kĕbwòdi֖⁠y bĕ̇ráʼţi֑y⁠w yĕẕarĕţi֖̇y⁠w ʼap-ʻàşîyţiֽy⁠w׃"],[43,8,"הוֹצִ֥יא עַם־עִוֵּ֖ר וְ⁠עֵינַ֣יִם יֵ֑שׁ וְ⁠חֵרְשִׁ֖ים וְ⁠אָזְנַ֥יִם לָֽ⁠מוֹ׃","hwòẕi֥yʼ ʻam-ʻiwé֖̇r wĕ⁠ʻéyna֣yim yé֑ş̌ wĕ⁠ẖérĕşǐ֖ym wĕ⁠ʼázĕna֥yim láֽ⁠mwò׃"],[43,9,"כָּֽל־הַ⁠גּוֹיִ֞ם נִקְבְּצ֣וּ יַחְדָּ֗ו וְ⁠יֵאָֽסְפוּ֙ לְאֻמִּ֔ים מִ֤י בָ⁠הֶם֙ יַגִּ֣יד זֹ֔את וְ⁠רִֽאשֹׁנ֖וֹת יַשְׁמִיעֻ֑⁠נוּ יִתְּנ֤וּ עֵֽדֵי⁠הֶם֙ וְ⁠יִצְדָּ֔קוּ וְ⁠יִשְׁמְע֖וּ וְ⁠יֹאמְר֥וּ אֱמֶֽת׃","káֽ̇l-ha⁠ġwòyi֞m niqĕbĕ̇ẕ֣ẇ yaẖĕdá̇֗w wĕ⁠yéʼáֽsĕpẇ֙ lĕʼumi̇֔ym mi֤y bá⁠hem֙ yagi֣̇yd zò֔ʼţ wĕ⁠riֽʼşò̌n֖wòţ yaşĕ̌miyʻu֑⁠nẇ yiţĕ̇n֤ẇ ʻéֽdéy⁠hem֙ wĕ⁠yiẕĕdá̇֔qẇ wĕ⁠yişĕ̌mĕʻ֖ẇ wĕ⁠yòʼmĕr֥ẇ ʼèmeֽţ׃"],[43,10,"אַתֶּ֤ם עֵדַ⁠י֙ נְאֻם־יְהוָ֔ה וְ⁠עַבְדִּ֖⁠י אֲשֶׁ֣ר בָּחָ֑רְתִּי לְמַ֣עַן תֵּ֠דְעוּ וְ⁠תַאֲמִ֨ינוּ לִ֤⁠י וְ⁠תָבִ֨ינוּ֙ כִּֽי־אֲנִ֣י ה֔וּא לְ⁠פָנַ⁠י֙ לֹא־נ֣וֹצַר אֵ֔ל וְ⁠אַחֲרַ֖⁠י לֹ֥א יִהְיֶֽה׃ס","ʼaţė֤m ʻéda⁠y֙ nĕʼum-yĕhwá֔h wĕ⁠ʻabĕdi֖̇⁠y ʼàşě֣r bá̇ẖá֑rĕţi̇y lĕma֣ʻan ţé̇֠dĕʻẇ wĕ⁠ţaʼàmi֨ynẇ li֤⁠y wĕ⁠ţábi֨ynẇ֙ kiֽ̇y-ʼàni֣y h֔ẇʼ lĕ⁠pána⁠y֙ lòʼ-n֣wòẕar ʼé֔l wĕ⁠ʼaẖàra֖⁠y lò֥ʼ yihĕyeֽh׃s"],[43,11,"אָנֹכִ֥י אָנֹכִ֖י יְהוָ֑ה וְ⁠אֵ֥ין מִ⁠בַּלְעָדַ֖⁠י מוֹשִֽׁיעַ׃","ʼánòki֥y ʼánòki֖y yĕhwá֑h wĕ⁠ʼé֥yn mi⁠bȧlĕʻáda֖⁠y mwòşǐֽyʻa׃"],[43,12,"אָנֹכִ֞י הִגַּ֤דְתִּי וְ⁠הוֹשַׁ֨עְתִּי֙ וְ⁠הִשְׁמַ֔עְתִּי וְ⁠אֵ֥ין בָּ⁠כֶ֖ם זָ֑ר וְ⁠אַתֶּ֥ם עֵדַ֛⁠י נְאֻם־יְהוָ֖ה וַֽ⁠אֲנִי־אֵֽל׃","ʼánòki֞y higȧ֤dĕţi̇y wĕ⁠hwòşǎ֨ʻĕţi̇y֙ wĕ⁠hişĕ̌ma֔ʻĕţi̇y wĕ⁠ʼé֥yn bá̇⁠ke֖m zá֑r wĕ⁠ʼaţė֥m ʻéda֛⁠y nĕʼum-yĕhwá֖h waֽ⁠ʼàniy-ʼéֽl׃"],[43,13,"גַּם־מִ⁠יּוֹם֙ אֲנִ֣י ה֔וּא וְ⁠אֵ֥ין מִ⁠יָּדִ֖⁠י מַצִּ֑יל אֶפְעַ֖ל וּ⁠מִ֥י יְשִׁיבֶֽ⁠נָּה׃ס","gȧm-mi⁠ẏwòm֙ ʼàni֣y h֔ẇʼ wĕ⁠ʼé֥yn mi⁠yá̇di֖⁠y maẕi֑̇yl ʼepĕʻa֖l ẇ⁠mi֥y yĕşǐybeֽ⁠ná̇h׃s"],[43,14,"כֹּֽה־אָמַ֧ר יְהוָ֛ה גֹּאַלְ⁠כֶ֖ם קְד֣וֹשׁ יִשְׂרָאֵ֑ל לְמַעַנְ⁠כֶ֞ם שִׁלַּ֣חְתִּי בָבֶ֗לָ⁠ה וְ⁠הוֹרַדְתִּ֤י בָֽ⁠רִיחִים֙ כֻּלָּ֔⁠ם וְ⁠כַשְׂדִּ֖ים בָּ⁠אֳנִיּ֥וֹת רִנָּתָֽ⁠ם׃","kòֽ̇h-ʼáma֧r yĕhwá֛h gò̇ʼalĕ⁠ke֖m qĕd֣wòş̌ yişĕ̂ráʼé֑l lĕmaʻanĕ⁠ke֞m şǐlȧ֣ẖĕţi̇y bábe֗lá⁠h wĕ⁠hwòradĕţi֤̇y báֽ⁠riyẖiym֙ ku̇lá̇֔⁠m wĕ⁠kaşĕ̂di֖̇ym bá̇⁠ʼoniẏ֥wòţ riná̇ţáֽ⁠m׃"],[43,15,"אֲנִ֥י יְהוָ֖ה קְדֽוֹשְׁ⁠כֶ֑ם בּוֹרֵ֥א יִשְׂרָאֵ֖ל מַלְכְּ⁠כֶֽם׃ס","ʼàni֥y yĕhwá֖h qĕdֽwòşĕ̌⁠ke֑m ḃwòré֥ʼ yişĕ̂ráʼé֖l malĕkĕ̇⁠keֽm׃s"],[43,16,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה הַ⁠נּוֹתֵ֥ן בַּ⁠יָּ֖ם דָּ֑רֶךְ וּ⁠בְ⁠מַ֥יִם עַזִּ֖ים נְתִיבָֽה׃","kò֚̇h ʼáma֣r yĕhwá֔h ha⁠ṅwòţé֥n bȧ⁠yá֖̇m dá֑̇rekĕ ẇ⁠bĕ⁠ma֥yim ʻazi֖̇ym nĕţiybáֽh׃"],[43,17,"הַ⁠מּוֹצִ֥יא רֶֽכֶב־וָ⁠ס֖וּס חַ֣יִל וְ⁠עִזּ֑וּז יַחְדָּ֤ו יִשְׁכְּבוּ֙ בַּל־יָק֔וּמוּ דָּעֲכ֖וּ כַּ⁠פִּשְׁתָּ֥ה כָבֽוּ׃","ha⁠ṁwòẕi֥yʼ reֽkeb-wá⁠s֖ẇs ẖa֣yil wĕ⁠ʻiż֑ẇz yaẖĕdá֤̇w yişĕ̌kĕ̇bẇ֙ bȧl-yáq֔ẇmẇ dá̇ʻàk֖ẇ kȧ⁠pi̇şĕ̌ţá֥̇h kábֽẇ׃"],[43,18,"אַֽל־תִּזְכְּר֖וּ רִֽאשֹׁנ֑וֹת וְ⁠קַדְמֹנִיּ֖וֹת אַל־תִּתְבֹּנָֽנוּ׃","ʼaֽl-ţi̇zĕkĕ̇r֖ẇ riֽʼşò̌n֑wòţ wĕ⁠qadĕmòniẏ֖wòţ ʼal-ţi̇ţĕbò̇náֽnẇ׃"],[43,19,"הִנְ⁠נִ֨י עֹשֶׂ֤ה חֲדָשָׁה֙ עַתָּ֣ה תִצְמָ֔ח הֲ⁠ל֖וֹא תֵֽדָע֑וּ⁠הָ אַ֣ף אָשִׂ֤ים בַּ⁠מִּדְבָּר֙ דֶּ֔רֶךְ בִּֽ⁠ישִׁמ֖וֹן נְהָרֽוֹת׃","hinĕ⁠ni֨y ʻòşê֤h ẖàdáşá̌h֙ ʻaţá֣̇h ţiẕĕmá֔ẖ hà⁠l֖wòʼ ţéֽdáʻ֑ẇ⁠há ʼa֣p ʼáşî֤ym bȧ⁠mi̇dĕbá̇r֙ dė֔rekĕ biֽ̇⁠yşǐm֖wòn nĕhárֽwòţ׃"],[43,20,"תְּכַבְּדֵ֨⁠נִי֙ חַיַּ֣ת הַ⁠שָּׂדֶ֔ה תַּנִּ֖ים וּ⁠בְנ֣וֹת יַֽעֲנָ֑ה כִּֽי־נָתַ֨תִּי בַ⁠מִּדְבָּ֜ר מַ֗יִם נְהָרוֹת֙ בִּֽ⁠ישִׁימֹ֔ן לְ⁠הַשְׁק֖וֹת עַמִּ֥⁠י בְחִירִֽ⁠י׃","ţĕ̇kabĕ̇dé֨⁠niy֙ ẖayȧ֣ţ ha⁠şá̇̂de֔h ţȧni֖̇ym ẇ⁠bĕn֣wòţ yaֽʻàná֑h kiֽ̇y-náţa֨ţi̇y ba⁠mi̇dĕbá̇֜r ma֗yim nĕhárwòţ֙ biֽ̇⁠yşǐymò֔n lĕ⁠haşĕ̌q֖wòţ ʻami֥̇⁠y bĕẖiyriֽ⁠y׃"],[43,21,"עַם־זוּ֙ יָצַ֣רְתִּי לִ֔⁠י תְּהִלָּתִ֖⁠י יְסַפֵּֽרוּ׃ס","ʻam-zẇ֙ yáẕa֣rĕţi̇y li֔⁠y ţĕ̇hilá̇ţi֖⁠y yĕsapéֽ̇rẇ׃s"],[43,22,"וְ⁠לֹא־אֹתִ֥⁠י קָרָ֖אתָ יַֽעֲקֹ֑ב כִּֽי־יָגַ֥עְתָּ בִּ֖⁠י יִשְׂרָאֵֽל׃","wĕ⁠lòʼ-ʼòţi֥⁠y qárá֖ʼţá yaֽʻàqò֑b kiֽ̇y-yága֥ʻĕţá̇ bi֖̇⁠y yişĕ̂ráʼéֽl׃"],[43,23,"לֹֽא־הֵבֵ֤יאתָ לִּ⁠י֙ שֵׂ֣ה עֹלֹתֶ֔י⁠ךָ וּ⁠זְבָחֶ֖י⁠ךָ לֹ֣א כִבַּדְתָּ֑⁠נִי לֹ֤א הֶעֱבַדְתִּ֨י⁠ךָ֙ בְּ⁠מִנְחָ֔ה וְ⁠לֹ֥א הוֹגַעְתִּ֖י⁠ךָ בִּ⁠לְבוֹנָֽה׃","lòֽʼ-hébé֤yʼţá li̇⁠y֙ şé֣̂h ʻòlòţe֔y⁠ká ẇ⁠zĕbáẖe֖y⁠ká lò֣ʼ kibȧdĕţá֑̇⁠niy lò֤ʼ heʻèbadĕţi̇֨y⁠ká֙ bĕ̇⁠minĕẖá֔h wĕ⁠lò֥ʼ hwògaʻĕţi֖̇y⁠ká bi̇⁠lĕbwònáֽh׃"],[43,24,"לֹא־קָנִ֨יתָ לִּ֤⁠י בַ⁠כֶּ֨סֶף֙ קָנֶ֔ה וְ⁠חֵ֥לֶב זְבָחֶ֖י⁠ךָ לֹ֣א הִרְוִיתָ֑⁠נִי אַ֗ךְ הֶעֱבַדְתַּ֨⁠נִי֙ בְּ⁠חַטֹּאותֶ֔י⁠ךָ הוֹגַעְתַּ֖⁠נִי בַּ⁠עֲוֺנֹתֶֽי⁠ךָ׃ס","lòʼ-qáni֨yţá li֤̇⁠y ba⁠kė֨sep֙ qáne֔h wĕ⁠ẖé֥leb zĕbáẖe֖y⁠ká lò֣ʼ hirĕwiyţá֑⁠niy ʼa֗kĕ heʻèbadĕţȧ֨⁠niy֙ bĕ̇⁠ẖatò̇ʼwţe֔y⁠ká hwògaʻĕţȧ֖⁠niy bȧ⁠ʻàwֺnòţeֽy⁠ká׃s"],[43,25,"אָנֹכִ֨י אָנֹכִ֥י ה֛וּא מֹחֶ֥ה פְשָׁעֶ֖י⁠ךָ לְמַעֲנִ֑⁠י וְ⁠חַטֹּאתֶ֖י⁠ךָ לֹ֥א אֶזְכֹּֽר׃","ʼánòki֨y ʼánòki֥y h֛ẇʼ mòẖe֥h pĕşá̌ʻe֖y⁠ká lĕmaʻàni֑⁠y wĕ⁠ẖatò̇ʼţe֖y⁠ká lò֥ʼ ʼezĕkòֽ̇r׃"],[43,26,"הַזְכִּירֵ֕⁠נִי נִשָּׁפְטָ֖ה יָ֑חַד סַפֵּ֥ר אַתָּ֖ה לְמַ֥עַן תִּצְדָּֽק׃","hazĕki̇yré֕⁠niy nişá̇̌pĕtá֖h yá֑ẖad sapé֥̇r ʼaţá֖̇h lĕma֥ʻan ţi̇ẕĕdáֽ̇q׃"],[43,27,"אָבִ֥י⁠ךָ הָ⁠רִאשׁ֖וֹן חָטָ֑א וּ⁠מְלִיצֶ֖י⁠ךָ פָּ֥שְׁעוּ בִֽ⁠י׃","ʼábi֥y⁠ká há⁠riʼş֖̌wòn ẖátá֑ʼ ẇ⁠mĕliyẕe֖y⁠ká pá֥̇şĕ̌ʻẇ biֽ⁠y׃"],[43,28,"וַ⁠אֲחַלֵּ֖ל שָׂ֣רֵי קֹ֑דֶשׁ וְ⁠אֶתְּנָ֤ה לַ⁠חֵ֨רֶם֙ יַעֲקֹ֔ב וְ⁠יִשְׂרָאֵ֖ל לְ⁠גִדּוּפִֽים׃ס","wa⁠ʼàẖalé֖̇l şá֣̂réy qò֑deş̌ wĕ⁠ʼeţĕ̇ná֤h la⁠ẖé֨rem֙ yaʻàqò֔b wĕ⁠yişĕ̂ráʼé֖l lĕ⁠giḋẇpiֽym׃s"],[44,1,"וְ⁠עַתָּ֥ה שְׁמַ֖ע יַעֲקֹ֣ב עַבְדִּ֑⁠י וְ⁠יִשְׂרָאֵ֖ל בָּחַ֥רְתִּי בֽ⁠וֹ׃","wĕ⁠ʻaţá֥̇h şĕ̌ma֖ʻ yaʻàqò֣b ʻabĕdi֑̇⁠y wĕ⁠yişĕ̂ráʼé֖l bá̇ẖa֥rĕţi̇y bֽ⁠wò׃"],[44,2,"כֹּה־אָמַ֨ר יְהוָ֥ה עֹשֶׂ֛⁠ךָ וְ⁠יֹצֶרְ⁠ךָ֥ מִ⁠בֶּ֖טֶן יַעְזְרֶ֑⁠ךָּ אַל־תִּירָא֙ עַבְדִּ֣⁠י יַֽעֲקֹ֔ב וִ⁠ישֻׁר֖וּן בָּחַ֥רְתִּי בֽ⁠וֹ׃","kò̇h-ʼáma֨r yĕhwá֥h ʻòşê֛⁠ká wĕ⁠yòẕerĕ⁠ká֥ mi⁠bė֖ten yaʻĕzĕre֑⁠ká̇ ʼal-ţi̇yráʼ֙ ʻabĕdi֣̇⁠y yaֽʻàqò֔b wi⁠yşǔr֖ẇn bá̇ẖa֥rĕţi̇y bֽ⁠wò׃"],[44,3,"כִּ֤י אֶצָּק־מַ֨יִם֙ עַל־צָמֵ֔א וְ⁠נֹזְלִ֖ים עַל־יַבָּשָׁ֑ה אֶצֹּ֤ק רוּחִ⁠י֙ עַל־זַרְעֶ֔⁠ךָ וּ⁠בִרְכָתִ֖⁠י עַל־צֶאֱצָאֶֽי⁠ךָ׃","ki֤̇y ʼeẕá̇q-ma֨yim֙ ʻal-ẕámé֔ʼ wĕ⁠nòzĕli֖ym ʻal-yabá̇şá֑̌h ʼeẕò֤̇q rẇẖi⁠y֙ ʻal-zarĕʻe֔⁠ká ẇ⁠birĕkáţi֖⁠y ʻal-ẕeʼèẕáʼeֽy⁠ká׃"],[44,4,"וְ⁠צָמְח֖וּ בְּ⁠בֵ֣ין חָצִ֑יר כַּ⁠עֲרָבִ֖ים עַל־יִבְלֵי־מָֽיִם׃","wĕ⁠ẕámĕẖ֖ẇ bĕ̇⁠bé֣yn ẖáẕi֑yr kȧ⁠ʻàrábi֖ym ʻal-yibĕléy-máֽyim׃"],[44,5,"זֶ֤ה יֹאמַר֙ לַֽ⁠יהוָ֣ה אָ֔נִי וְ⁠זֶ֖ה יִקְרָ֣א בְ⁠שֵֽׁם־יַעֲקֹ֑ב וְ⁠זֶ֗ה יִכְתֹּ֤ב יָד⁠וֹ֙ לַֽ⁠יהוָ֔ה וּ⁠בְ⁠שֵׁ֥ם יִשְׂרָאֵ֖ל יְכַנֶּֽה׃פ","ze֤h yòʼmar֙ laֽ⁠yhwá֣h ʼá֔niy wĕ⁠ze֖h yiqĕrá֣ʼ bĕ⁠şéֽ̌m-yaʻàqò֑b wĕ⁠ze֗h yikĕţò֤̇b yád⁠wò֙ laֽ⁠yhwá֔h ẇ⁠bĕ⁠şé֥̌m yişĕ̂ráʼé֖l yĕkanėֽh׃p"],[44,6,"כֹּֽה־אָמַ֨ר יְהוָ֧ה מֶֽלֶךְ־יִשְׂרָאֵ֛ל וְ⁠גֹאֲל֖⁠וֹ יְהוָ֣ה צְבָא֑וֹת אֲנִ֤י רִאשׁוֹן֙ וַ⁠אֲנִ֣י אַחֲר֔וֹן וּ⁠מִ⁠בַּלְעָדַ֖⁠י אֵ֥ין אֱלֹהִֽים׃","kòֽ̇h-ʼáma֨r yĕhwá֧h meֽlekĕ-yişĕ̂ráʼé֛l wĕ⁠gòʼàl֖⁠wò yĕhwá֣h ẕĕbáʼ֑wòţ ʼàni֤y riʼş̌wòn֙ wa⁠ʼàni֣y ʼaẖàr֔wòn ẇ⁠mi⁠bȧlĕʻáda֖⁠y ʼé֥yn ʼèlòhiֽym׃"],[44,7,"וּ⁠מִֽי־כָמ֣וֹ⁠נִי יִקְרָ֗א וְ⁠יַגִּידֶ֤⁠הָ וְ⁠יַעְרְכֶ֨⁠הָ֙ לִ֔⁠י מִ⁠שּׂוּמִ֖⁠י עַם־עוֹלָ֑ם וְ⁠אֹתִיּ֛וֹת וַ⁠אֲשֶׁ֥ר תָּבֹ֖אנָה יַגִּ֥ידוּ לָֽ⁠מוֹ׃","ẇ⁠miֽy-kám֣wò⁠niy yiqĕrá֗ʼ wĕ⁠yagi̇yde֤⁠há wĕ⁠yaʻĕrĕke֨⁠há֙ li֔⁠y mi⁠ş̇̂ẇmi֖⁠y ʻam-ʻwòlá֑m wĕ⁠ʼòţiẏ֛wòţ wa⁠ʼàşě֥r ţá̇bò֖ʼnáh yagi֥̇ydẇ láֽ⁠mwò׃"],[44,8,"אַֽל־תִּפְחֲדוּ֙ וְ⁠אַל־תִּרְה֔וּ הֲ⁠לֹ֥א מֵ⁠אָ֛ז הִשְׁמַעְתִּ֥י⁠ךָ וְ⁠הִגַּ֖דְתִּי וְ⁠אַתֶּ֣ם עֵדָ֑⁠י הֲ⁠יֵ֤שׁ אֱל֨וֹהַּ֙ מִ⁠בַּלְעָדַ֔⁠י וְ⁠אֵ֥ין צ֖וּר בַּל־יָדָֽעְתִּי׃","ʼaֽl-ţi̇pĕẖàdẇ֙ wĕ⁠ʼal-ţi̇rĕh֔ẇ hà⁠lò֥ʼ mé⁠ʼá֛z hişĕ̌maʻĕţi֥̇y⁠ká wĕ⁠higȧ֖dĕţi̇y wĕ⁠ʼaţė֣m ʻédá֑⁠y hà⁠yé֤ş̌ ʼèl֨wòhȧ֙ mi⁠bȧlĕʻáda֔⁠y wĕ⁠ʼé֥yn ẕ֖ẇr bȧl-yádáֽʻĕţi̇y׃"],[44,9,"יֹֽצְרֵי־פֶ֤סֶל כֻּלָּ⁠ם֙ תֹּ֔הוּ וַ⁠חֲמוּדֵי⁠הֶ֖ם בַּל־יוֹעִ֑ילוּ וְ⁠עֵדֵי⁠הֶ֣ם הֵׄ֗מָּׄהׄ בַּל־יִרְא֛וּ וּ⁠בַל־יֵדְע֖וּ לְמַ֥עַן יֵבֹֽשׁוּ׃","yòֽẕĕréy-pe֤sel ku̇lá̇⁠m֙ ţò̇֔hẇ wa⁠ẖàmẇdéy⁠he֖m bȧl-ywòʻi֑ylẇ wĕ⁠ʻédéy⁠he֣m héׄ֗má̇ׄhׄ bȧl-yirĕʼ֛ẇ ẇ⁠bal-yédĕʻ֖ẇ lĕma֥ʻan yébòֽş̌ẇ׃"],[44,10,"מִֽי־יָצַ֥ר אֵ֖ל וּ⁠פֶ֣סֶל נָסָ֑ךְ לְ⁠בִלְתִּ֖י הוֹעִֽיל׃","miֽy-yáẕa֥r ʼé֖l ẇ⁠pe֣sel násá֑kĕ lĕ⁠bilĕţi֖̇y hwòʻiֽyl׃"],[44,11,"הֵ֤ן כָּל־חֲבֵרָי⁠ו֙ יֵבֹ֔שׁוּ וְ⁠חָרָשִׁ֥ים הֵ֖מָּה מֵֽ⁠אָדָ֑ם יִֽתְקַבְּצ֤וּ כֻלָּ⁠ם֙ יַֽעֲמֹ֔דוּ יִפְחֲד֖וּ יֵבֹ֥שׁוּ יָֽחַד׃","hé֤n ká̇l-ẖàbéráy⁠w֙ yébò֔ş̌ẇ wĕ⁠ẖáráşǐ֥ym hé֖má̇h méֽ⁠ʼádá֑m yiֽţĕqabĕ̇ẕ֤ẇ kulá̇⁠m֙ yaֽʻàmò֔dẇ yipĕẖàd֖ẇ yébò֥ş̌ẇ yáֽẖad׃"],[44,12,"חָרַ֤שׁ בַּרְזֶל֙ מַֽעֲצָ֔ד וּ⁠פָעַל֙ בַּ⁠פֶּחָ֔ם וּ⁠בַ⁠מַּקָּב֖וֹת יִצְּרֵ֑⁠הוּ וַ⁠יִּפְעָלֵ֨⁠הוּ֙ בִּ⁠זְר֣וֹעַ כֹּח֔⁠וֹ גַּם־רָעֵב֙ וְ⁠אֵ֣ין כֹּ֔חַ לֹא־שָׁ֥תָה מַ֖יִם וַ⁠יִּיעָֽף׃","ẖára֤ş̌ bȧrĕzel֙ maֽʻàẕá֔d ẇ⁠páʻal֙ bȧ⁠pėẖá֔m ẇ⁠ba⁠mȧqá̇b֖wòţ yiẕĕ̇ré֑⁠hẇ wa⁠yi̇pĕʻálé֨⁠hẇ֙ bi̇⁠zĕr֣wòʻa kò̇ẖ֔⁠wò gȧm-ráʻéb֙ wĕ⁠ʼé֣yn kò̇֔ẖa lòʼ-şá֥̌ţáh ma֖yim wa⁠yi̇yʻáֽp׃"],[44,13,"חָרַ֣שׁ עֵצִים֮ נָ֣טָה קָו֒ יְתָאֲרֵ֣⁠הוּ בַ⁠שֶּׂ֔רֶד יַעֲשֵׂ֨⁠הוּ֙ בַּ⁠מַּקְצֻע֔וֹת וּ⁠בַ⁠מְּחוּגָ֖ה יְתָאֳרֵ֑⁠הוּ וַֽ⁠יַּעֲשֵׂ֨⁠הוּ֙ כְּ⁠תַבְנִ֣ית אִ֔ישׁ כְּ⁠תִפְאֶ֥רֶת אָדָ֖ם לָ⁠שֶׁ֥בֶת בָּֽיִת׃","ẖára֣ş̌ ʻéẕiym֮ ná֣táh qáw֒ yĕţáʼàré֣⁠hẇ ba⁠şė̂֔red yaʻàşé̂֨⁠hẇ֙ bȧ⁠mȧqĕẕuʻ֔wòţ ẇ⁠ba⁠mĕ̇ẖẇgá֖h yĕţáʼoré֑⁠hẇ waֽ⁠yȧʻàşé̂֨⁠hẇ֙ kĕ̇⁠ţabĕni֣yţ ʼi֔yş̌ kĕ̇⁠ţipĕʼe֥reţ ʼádá֖m lá⁠şě֥beţ báֽ̇yiţ׃"],[44,14,"לִ⁠כְרָת־ל֣⁠וֹ אֲרָזִ֔ים וַ⁠יִּקַּ֤ח תִּרְזָה֙ וְ⁠אַלּ֔וֹן וַ⁠יְאַמֶּץ־ל֖⁠וֹ בַּ⁠עֲצֵי־יָ֑עַר נָטַ֥ע אֹ֖רֶן וְ⁠גֶ֥שֶׁם יְגַדֵּֽל׃","li⁠kĕráţ-l֣⁠wò ʼàrázi֔ym wa⁠yi̇qȧ֤ẖ ţi̇rĕzáh֙ wĕ⁠ʼal̇֔wòn wa⁠yĕʼamėẕ-l֖⁠wò bȧ⁠ʻàẕéy-yá֑ʻar náta֥ʻ ʼò֖ren wĕ⁠ge֥şěm yĕgadéֽ̇l׃"],[44,15,"וְ⁠הָיָ֤ה לְ⁠אָדָם֙ לְ⁠בָעֵ֔ר וַ⁠יִּקַּ֤ח מֵ⁠הֶם֙ וַ⁠יָּ֔חָם אַף־יַשִּׂ֖יק וְ⁠אָ֣פָה לָ֑חֶם אַף־יִפְעַל־אֵל֙ וַ⁠יִּשְׁתָּ֔חוּ עָשָׂ֥⁠הוּ פֶ֖סֶל וַ⁠יִּסְגָּד־לָֽ⁠מוֹ׃","wĕ⁠háyá֤h lĕ⁠ʼádám֙ lĕ⁠báʻé֔r wa⁠yi̇qȧ֤ẖ mé⁠hem֙ wa⁠yá̇֔ẖám ʼap-yaşi֖̇̂yq wĕ⁠ʼá֣páh lá֑ẖem ʼap-yipĕʻal-ʼél֙ wa⁠yi̇şĕ̌ţá̇֔ẖẇ ʻáşá֥̂⁠hẇ pe֖sel wa⁠yi̇sĕgá̇d-láֽ⁠mwò׃"],[44,16,"חֶצְי⁠וֹ֙ שָׂרַ֣ף בְּמוֹ־אֵ֔שׁ עַל־חֶצְי⁠וֹ֙ בָּשָׂ֣ר יֹאכֵ֔ל יִצְלֶ֥ה צָלִ֖י וְ⁠יִשְׂבָּ֑ע אַף־יָחֹם֙ וְ⁠יֹאמַ֣ר הֶאָ֔ח חַמּוֹתִ֖י רָאִ֥יתִי אֽוּר׃","ẖeẕĕy⁠wò֙ şá̂ra֣p bĕ̇mwò-ʼé֔ş̌ ʻal-ẖeẕĕy⁠wò֙ bá̇şá֣̂r yòʼké֔l yiẕĕle֥h ẕáli֖y wĕ⁠yişĕ̂bá֑̇ʻ ʼap-yáẖòm֙ wĕ⁠yòʼma֣r heʼá֔ẖ ẖaṁwòţi֖y ráʼi֥yţiy ʼֽẇr׃"],[44,17,"וּ⁠שְׁאֵ֣רִית֔⁠וֹ לְ⁠אֵ֥ל עָשָׂ֖ה לְ⁠פִסְל֑⁠וֹ יסגוד־ל֤⁠וֹ וְ⁠יִשְׁתַּ֨חוּ֙ וְ⁠יִתְפַּלֵּ֣ל אֵלָ֔י⁠ו וְ⁠יֹאמַר֙ הַצִּילֵ֔⁠נִי כִּ֥י אֵלִ֖⁠י אָֽתָּה׃","ẇ⁠şĕ̌ʼé֣riyţ֔⁠wò lĕ⁠ʼé֥l ʻáşá֖̂h lĕ⁠pisĕl֑⁠wò ysgwd-l֤⁠wò wĕ⁠yişĕ̌ţȧ֨ẖẇ֙ wĕ⁠yiţĕpȧlé֣̇l ʼélá֔y⁠w wĕ⁠yòʼmar֙ haẕi̇ylé֔⁠niy ki֥̇y ʼéli֖⁠y ʼáֽţá̇h׃"],[44,18,"לֹ֥א יָדְע֖וּ וְ⁠לֹ֣א יָבִ֑ינוּ כִּ֣י טַ֤ח מֵֽ⁠רְאוֹת֙ עֵֽינֵי⁠הֶ֔ם מֵ⁠הַשְׂכִּ֖יל לִבֹּתָֽ⁠ם׃","lò֥ʼ yádĕʻ֖ẇ wĕ⁠lò֣ʼ yábi֑ynẇ ki֣̇y ta֤ẖ méֽ⁠rĕʼwòţ֙ ʻéֽynéy⁠he֔m mé⁠haşĕ̂ki֖̇yl libò̇ţáֽ⁠m׃"],[44,19,"וְ⁠לֹא־יָשִׁ֣יב אֶל־לִבּ֗⁠וֹ וְ⁠לֹ֨א דַ֥עַת וְ⁠לֹֽא־תְבוּנָה֮ לֵ⁠אמֹר֒ חֶצְי֞⁠וֹ שָׂרַ֣פְתִּי בְמוֹ־אֵ֗שׁ וְ֠⁠אַף אָפִ֤יתִי עַל־גֶּחָלָי⁠ו֙ לֶ֔חֶם אֶצְלֶ֥ה בָשָׂ֖ר וְ⁠אֹכֵ֑ל וְ⁠יִתְר⁠וֹ֙ לְ⁠תוֹעֵבָ֣ה אֶעֱשֶׂ֔ה לְ⁠ב֥וּל עֵ֖ץ אֶסְגּֽוֹד׃","wĕ⁠lòʼ-yáşǐ֣yb ʼel-liḃ֗⁠wò wĕ⁠lò֨ʼ da֥ʻaţ wĕ⁠lòֽʼ-ţĕbẇnáh֮ lé⁠ʼmòr֒ ẖeẕĕy֞⁠wò şá̂ra֣pĕţi̇y bĕmwò-ʼé֗ş̌ wĕ֠⁠ʼap ʼápi֤yţiy ʻal-gėẖáláy⁠w֙ le֔ẖem ʼeẕĕle֥h báşá֖̂r wĕ⁠ʼòké֑l wĕ⁠yiţĕr⁠wò֙ lĕ⁠ţwòʻébá֣h ʼeʻèşê֔h lĕ⁠b֥ẇl ʻé֖ẕ ʼesĕġֽwòd׃"],[44,20,"רֹעֶ֣ה אֵ֔פֶר לֵ֥ב הוּתַ֖ל הִטָּ֑⁠הוּ וְ⁠לֹֽא־יַצִּ֤יל אֶת־נַפְשׁ⁠וֹ֙ וְ⁠לֹ֣א יֹאמַ֔ר הֲ⁠ל֥וֹא שֶׁ֖קֶר בִּ⁠ימִינִֽ⁠י׃ס","ròʻe֣h ʼé֔per lé֥b hẇţa֖l hitá֑̇⁠hẇ wĕ⁠lòֽʼ-yaẕi֤̇yl ʼeţ-napĕş̌⁠wò֙ wĕ⁠lò֣ʼ yòʼma֔r hà⁠l֥wòʼ şě֖qer bi̇⁠ymiyniֽ⁠y׃s"],[44,21,"זְכָר־אֵ֣לֶּה יַעֲקֹ֔ב וְ⁠יִשְׂרָאֵ֖ל כִּ֣י עַבְדִּ⁠י־אָ֑תָּה יְצַרְתִּ֤י⁠ךָ עֶֽבֶד־לִ⁠י֙ אַ֔תָּה יִשְׂרָאֵ֖ל לֹ֥א תִנָּשֵֽׁ⁠נִי׃","zĕkár-ʼé֣lėh yaʻàqò֔b wĕ⁠yişĕ̂ráʼé֖l ki֣̇y ʻabĕdi̇⁠y-ʼá֑ţá̇h yĕẕarĕţi֤̇y⁠ká ʻeֽbed-li⁠y֙ ʼa֔ţá̇h yişĕ̂ráʼé֖l lò֥ʼ ţiná̇şéֽ̌⁠niy׃"],[44,22,"מָחִ֤יתִי כָ⁠עָב֙ פְּשָׁעֶ֔י⁠ךָ וְ⁠כֶ⁠עָנָ֖ן חַטֹּאותֶ֑י⁠ךָ שׁוּבָ֥⁠ה אֵלַ֖⁠י כִּ֥י גְאַלְתִּֽי⁠ךָ׃","máẖi֤yţiy ká⁠ʻáb֙ pĕ̇şá̌ʻe֔y⁠ká wĕ⁠ke⁠ʻáná֖n ẖatò̇ʼwţe֑y⁠ká ş̌ẇbá֥⁠h ʼéla֖⁠y ki֥̇y gĕʼalĕţiֽ̇y⁠ká׃"],[44,23,"רָנּ֨וּ שָׁמַ֜יִם כִּֽי־עָשָׂ֣ה יְהוָ֗ה הָרִ֨יעוּ֙ תַּחְתִּיּ֣וֹת אָ֔רֶץ פִּצְח֤וּ הָרִים֙ רִנָּ֔ה יַ֖עַר וְ⁠כָל־עֵ֣ץ בּ֑⁠וֹ כִּֽי־גָאַ֤ל יְהוָה֙ יַֽעֲקֹ֔ב וּ⁠בְ⁠יִשְׂרָאֵ֖ל יִתְפָּאָֽר׃פ","ráṅ֨ẇ şá̌ma֜yim kiֽ̇y-ʻáşá֣̂h yĕhwá֗h hári֨yʻẇ֙ ţȧẖĕţi̇ẏ֣wòţ ʼá֔reẕ pi̇ẕĕẖ֤ẇ háriym֙ riná̇֔h ya֖ʻar wĕ⁠kál-ʻé֣ẕ ḃ֑⁠wò kiֽ̇y-gáʼa֤l yĕhwáh֙ yaֽʻàqò֔b ẇ⁠bĕ⁠yişĕ̂ráʼé֖l yiţĕpá̇ʼáֽr׃p"],[44,24,"כֹּֽה־אָמַ֤ר יְהוָה֙ גֹּאֲלֶ֔⁠ךָ וְ⁠יֹצֶרְ⁠ךָ֖ מִ⁠בָּ֑טֶן אָנֹכִ֤י יְהוָה֙ עֹ֣שֶׂה כֹּ֔ל נֹטֶ֤ה שָׁמַ֨יִם֙ לְ⁠בַדִּ֔⁠י רֹקַ֥ע הָ⁠אָ֖רֶץ מי את⁠י׃","kòֽ̇h-ʼáma֤r yĕhwáh֙ gò̇ʼàle֔⁠ká wĕ⁠yòẕerĕ⁠ká֖ mi⁠bá֑̇ten ʼánòki֤y yĕhwáh֙ ʻò֣şêh kò̇֔l nòte֤h şá̌ma֨yim֙ lĕ⁠badi̇֔⁠y ròqa֥ʻ há⁠ʼá֖reẕ my ʼţ⁠y׃"],[44,25,"מֵפֵר֙ אֹת֣וֹת בַּדִּ֔ים וְ⁠קֹסְמִ֖ים יְהוֹלֵ֑ל מֵשִׁ֧יב חֲכָמִ֛ים אָח֖וֹר וְ⁠דַעְתָּ֥⁠ם יְשַׂכֵּֽל׃","mépér֙ ʼòţ֣wòţ bȧdi̇֔ym wĕ⁠qòsĕmi֖ym yĕhwòlé֑l méşǐ֧yb ẖàkámi֛ym ʼáẖ֖wòr wĕ⁠daʻĕţá֥̇⁠m yĕşâkéֽ̇l׃"],[44,26,"מֵקִים֙ דְּבַ֣ר עַבְדּ֔⁠וֹ וַ⁠עֲצַ֥ת מַלְאָכָ֖י⁠ו יַשְׁלִ֑ים הָ⁠אֹמֵ֨ר לִ⁠ירוּשָׁלִַ֜ם תּוּשָׁ֗ב וּ⁠לְ⁠עָרֵ֤י יְהוּדָה֙ תִּבָּנֶ֔ינָה וְ⁠חָרְבוֹתֶ֖י⁠הָ אֲקוֹמֵֽם׃","méqiym֙ dĕ̇ba֣r ʻabĕḋ֔⁠wò wa⁠ʻàẕa֥ţ malĕʼáká֖y⁠w yaşĕ̌li֑ym há⁠ʼòmé֨r li⁠yrẇşá̌lia֜m ţ̇ẇşá̌֗b ẇ⁠lĕ⁠ʻáré֤y yĕhẇdáh֙ ţi̇bá̇ne֔ynáh wĕ⁠ẖárĕbwòţe֖y⁠há ʼàqwòméֽm׃"],[44,27,"הָ⁠אֹמֵ֥ר לַ⁠צּוּלָ֖ה חֳרָ֑בִי וְ⁠נַהֲרֹתַ֖יִ⁠ךְ אוֹבִֽישׁ׃","há⁠ʼòmé֥r la⁠ẕ̇ẇlá֖h ẖorá֑biy wĕ⁠nahàròţa֖yi⁠kĕ ʼwòbiֽyş̌׃"],[44,28,"הָ⁠אֹמֵ֤ר לְ⁠כ֨וֹרֶשׁ֙ רֹעִ֔⁠י וְ⁠כָל־חֶפְצִ֖⁠י יַשְׁלִ֑ם וְ⁠לֵ⁠אמֹ֤ר לִ⁠ירוּשָׁלִַ֨ם֙ תִּבָּנֶ֔ה וְ⁠הֵיכָ֖ל תִּוָּסֵֽד׃ס","há⁠ʼòmé֤r lĕ⁠k֨wòreş̌֙ ròʻi֔⁠y wĕ⁠kál-ẖepĕẕi֖⁠y yaşĕ̌li֑m wĕ⁠lé⁠ʼmò֤r li⁠yrẇşá̌lia֨m֙ ţi̇bá̇ne֔h wĕ⁠héyká֖l ţi̇wá̇séֽd׃s"],[45,1,"כֹּה־אָמַ֣ר יְהוָה֮ לִ⁠מְשִׁיח⁠וֹ֮ לְ⁠כ֣וֹרֶשׁ אֲשֶׁר־הֶחֱזַ֣קְתִּי בִֽ⁠ימִינ֗⁠וֹ לְ⁠רַד־לְ⁠פָנָי⁠ו֙ גּוֹיִ֔ם וּ⁠מָתְנֵ֥י מְלָכִ֖ים אֲפַתֵּ֑חַ לִ⁠פְתֹּ֤חַ לְ⁠פָנָי⁠ו֙ דְּלָתַ֔יִם וּ⁠שְׁעָרִ֖ים לֹ֥א יִסָּגֵֽרוּ׃","kò̇h-ʼáma֣r yĕhwáh֮ li⁠mĕşǐyẖ⁠wò֮ lĕ⁠k֣wòreş̌ ʼàşěr-heẖèza֣qĕţi̇y biֽ⁠ymiyn֗⁠wò lĕ⁠rad-lĕ⁠pánáy⁠w֙ ġwòyi֔m ẇ⁠máţĕné֥y mĕláki֖ym ʼàpaţé֑̇ẖa li⁠pĕţò֤̇ẖa lĕ⁠pánáy⁠w֙ dĕ̇láţa֔yim ẇ⁠şĕ̌ʻári֖ym lò֥ʼ yisá̇géֽrẇ׃"],[45,2,"אֲנִי֙ לְ⁠פָנֶ֣י⁠ךָ אֵלֵ֔ךְ וַ⁠הֲדוּרִ֖ים אושר דַּלְת֤וֹת נְחוּשָׁה֙ אֲשַׁבֵּ֔ר וּ⁠בְרִיחֵ֥י בַרְזֶ֖ל אֲגַדֵּֽעַ׃","ʼàniy֙ lĕ⁠páne֣y⁠ká ʼélé֔kĕ wa⁠hàdẇri֖ym ʼwşr dȧlĕţ֤wòţ nĕẖẇşá̌h֙ ʼàşǎbé̇֔r ẇ⁠bĕriyẖé֥y barĕze֖l ʼàgadéֽ̇ʻa׃"],[45,3,"וְ⁠נָתַתִּ֤י לְ⁠ךָ֙ אוֹצְר֣וֹת חֹ֔שֶׁךְ וּ⁠מַטְמֻנֵ֖י מִסְתָּרִ֑ים לְמַ֣עַן תֵּדַ֗ע כִּֽי־אֲנִ֧י יְהוָ֛ה הַ⁠קּוֹרֵ֥א בְ⁠שִׁמְ⁠ךָ֖ אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠náţaţi֤̇y lĕ⁠ká֙ ʼwòẕĕr֣wòţ ẖò֔şěkĕ ẇ⁠matĕmuné֖y misĕţá̇ri֑ym lĕma֣ʻan ţé̇da֗ʻ kiֽ̇y-ʼàni֧y yĕhwá֛h ha⁠q̇wòré֥ʼ bĕ⁠şǐmĕ⁠ká֖ ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[45,4,"לְמַ֨עַן֙ עַבְדִּ֣⁠י יַעֲקֹ֔ב וְ⁠יִשְׂרָאֵ֖ל בְּחִירִ֑⁠י וָ⁠אֶקְרָ֤א לְ⁠ךָ֙ בִּ⁠שְׁמֶ֔⁠ךָ אֲכַנְּ⁠ךָ֖ וְ⁠לֹ֥א יְדַעְתָּֽ⁠נִי׃","lĕma֨ʻan֙ ʻabĕdi֣̇⁠y yaʻàqò֔b wĕ⁠yişĕ̂ráʼé֖l bĕ̇ẖiyri֑⁠y wá⁠ʼeqĕrá֤ʼ lĕ⁠ká֙ bi̇⁠şĕ̌me֔⁠ká ʼàkanĕ̇⁠ká֖ wĕ⁠lò֥ʼ yĕdaʻĕţáֽ̇⁠niy׃"],[45,5,"אֲנִ֤י יְהוָה֙ וְ⁠אֵ֣ין ע֔וֹד זוּלָתִ֖⁠י אֵ֣ין אֱלֹהִ֑ים אֲאַזֶּרְ⁠ךָ֖ וְ⁠לֹ֥א יְדַעְתָּֽ⁠נִי׃","ʼàni֤y yĕhwáh֙ wĕ⁠ʼé֣yn ʻ֔wòd zẇláţi֖⁠y ʼé֣yn ʼèlòhi֑ym ʼàʼazėrĕ⁠ká֖ wĕ⁠lò֥ʼ yĕdaʻĕţáֽ̇⁠niy׃"],[45,6,"לְמַ֣עַן יֵדְע֗וּ מִ⁠מִּזְרַח־שֶׁ֨מֶשׁ֙ וּ⁠מִ⁠מַּ֣עֲרָבָ֔⁠הּ כִּי־אֶ֖פֶס בִּלְעָדָ֑⁠י אֲנִ֥י יְהוָ֖ה וְ⁠אֵ֥ין עֽוֹד׃","lĕma֣ʻan yédĕʻ֗ẇ mi⁠mi̇zĕraẖ-şě֨meş̌֙ ẇ⁠mi⁠mȧ֣ʻàrábá֔⁠ḣ ki̇y-ʼe֖pes bi̇lĕʻádá֑⁠y ʼàni֥y yĕhwá֖h wĕ⁠ʼé֥yn ʻֽwòd׃"],[45,7,"יוֹצֵ֥ר אוֹר֙ וּ⁠בוֹרֵ֣א חֹ֔שֶׁךְ עֹשֶׂ֥ה שָׁל֖וֹם וּ⁠ב֣וֹרֵא רָ֑ע אֲנִ֥י יְהוָ֖ה עֹשֶׂ֥ה כָל־אֵֽלֶּה׃ס","ywòẕé֥r ʼwòr֙ ẇ⁠bwòré֣ʼ ẖò֔şěkĕ ʻòşê֥h şá̌l֖wòm ẇ⁠b֣wòréʼ rá֑ʻ ʼàni֥y yĕhwá֖h ʻòşê֥h kál-ʼéֽlėh׃s"],[45,8,"הַרְעִ֤יפוּ שָׁמַ֨יִם֙ מִ⁠מַּ֔עַל וּ⁠שְׁחָקִ֖ים יִזְּלוּ־צֶ֑דֶק תִּפְתַּח־אֶ֣רֶץ וְ⁠יִפְרוּ־יֶ֗שַׁע וּ⁠צְדָקָ֤ה תַצְמִ֨יחַ֙ יַ֔חַד אֲנִ֥י יְהוָ֖ה בְּרָאתִֽי⁠ו׃ס","harĕʻi֤ypẇ şá̌ma֨yim֙ mi⁠mȧ֔ʻal ẇ⁠şĕ̌ẖáqi֖ym yizĕ̇lẇ-ẕe֑deq ţi̇pĕţȧẖ-ʼe֣reẕ wĕ⁠yipĕrẇ-ye֗şǎʻ ẇ⁠ẕĕdáqá֤h ţaẕĕmi֨yẖa֙ ya֔ẖad ʼàni֥y yĕhwá֖h bĕ̇ráʼţiֽy⁠w׃s"],[45,9,"ה֗וֹי רָ֚ב אֶת־יֹ֣צְר֔⁠וֹ חֶ֖רֶשׂ אֶת־חַרְשֵׂ֣י אֲדָמָ֑ה הֲ⁠יֹאמַ֨ר חֹ֤מֶר לְ⁠יֹֽצְר⁠וֹ֙ מַֽה־תַּעֲשֶׂ֔ה וּ⁠פָעָלְ⁠ךָ֖ אֵין־יָדַ֥יִם לֽ⁠וֹ׃ס","h֗wòy rá֚b ʼeţ-yò֣ẕĕr֔⁠wò ẖe֖reş̂ ʼeţ-ẖarĕşé֣̂y ʼàdámá֑h hà⁠yòʼma֨r ẖò֤mer lĕ⁠yòֽẕĕr⁠wò֙ maֽh-ţȧʻàşê֔h ẇ⁠páʻálĕ⁠ká֖ ʼéyn-yáda֥yim lֽ⁠wò׃s"],[45,10,"ה֛וֹי אֹמֵ֥ר לְ⁠אָ֖ב מַה־תּוֹלִ֑יד וּ⁠לְ⁠אִשָּׁ֖ה מַה־תְּחִילִֽי⁠ן׃ס","h֛wòy ʼòmé֥r lĕ⁠ʼá֖b mah-ţ̇wòli֑yd ẇ⁠lĕ⁠ʼişá֖̇̌h mah-ţĕ̇ẖiyliֽy⁠n׃s"],[45,11,"כֹּֽה־אָמַ֧ר יְהוָ֛ה קְד֥וֹשׁ יִשְׂרָאֵ֖ל וְ⁠יֹצְר֑⁠וֹ הָ⁠אֹתִיּ֣וֹת שְׁאָל֔וּ⁠נִי עַל־בָּנַ֛⁠י וְ⁠עַל־פֹּ֥עַל יָדַ֖⁠י תְּצַוֻּֽ⁠נִי׃","kòֽ̇h-ʼáma֧r yĕhwá֛h qĕd֥wòş̌ yişĕ̂ráʼé֖l wĕ⁠yòẕĕr֑⁠wò há⁠ʼòţiẏ֣wòţ şĕ̌ʼál֔ẇ⁠niy ʻal-bá̇na֛⁠y wĕ⁠ʻal-pò֥̇ʻal yáda֖⁠y ţĕ̇ẕawuֽ̇⁠niy׃"],[45,12,"אָֽנֹכִי֙ עָשִׂ֣יתִי אֶ֔רֶץ וְ⁠אָדָ֖ם עָלֶ֣י⁠הָ בָרָ֑אתִי אֲנִ֗י יָדַ⁠י֙ נָט֣וּ שָׁמַ֔יִם וְ⁠כָל־צְבָאָ֖⁠ם צִוֵּֽיתִי׃","ʼáֽnòkiy֙ ʻáşî֣yţiy ʼe֔reẕ wĕ⁠ʼádá֖m ʻále֣y⁠há bárá֑ʼţiy ʼàni֗y yáda⁠y֙ nát֣ẇ şá̌ma֔yim wĕ⁠kál-ẕĕbáʼá֖⁠m ẕiwéֽ̇yţiy׃"],[45,13,"אָנֹכִי֙ הַעִירֹתִ֣⁠הֽוּ בְ⁠צֶ֔דֶק וְ⁠כָל־דְּרָכָ֖י⁠ו אֲיַשֵּׁ֑ר הֽוּא־יִבְנֶ֤ה עִירִ⁠י֙ וְ⁠גָלוּתִ֣⁠י יְשַׁלֵּ֔חַ לֹ֤א בִ⁠מְחִיר֙ וְ⁠לֹ֣א בְ⁠שֹׁ֔חַד אָמַ֖ר יְהוָ֥ה צְבָאֽוֹת׃פ","ʼánòkiy֙ haʻiyròţi֣⁠hֽẇ bĕ⁠ẕe֔deq wĕ⁠kál-dĕ̇ráká֖y⁠w ʼàyaşé֑̇̌r hֽẇʼ-yibĕne֤h ʻiyri⁠y֙ wĕ⁠gálẇţi֣⁠y yĕşǎlé̇֔ẖa lò֤ʼ bi⁠mĕẖiyr֙ wĕ⁠lò֣ʼ bĕ⁠şò̌֔ẖad ʼáma֖r yĕhwá֥h ẕĕbáʼֽwòţ׃p"],[45,14,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה יְגִ֨יעַ מִצְרַ֥יִם וּֽ⁠סְחַר־כּוּשׁ֮ וּ⁠סְבָאִים֮ אַנְשֵׁ֣י מִדָּה֒ עָלַ֤יִ⁠ךְ יַעֲבֹ֨רוּ֙ וְ⁠לָ֣⁠ךְ יִֽהְי֔וּ אַחֲרַ֣יִ⁠ךְ יֵלֵ֔כוּ בַּ⁠זִּקִּ֖ים יַעֲבֹ֑רוּ וְ⁠אֵלַ֤יִ⁠ךְ יִֽשְׁתַּחֲוּוּ֙ אֵלַ֣יִ⁠ךְ יִתְפַּלָּ֔לוּ אַ֣ךְ בָּ֥⁠ךְ אֵ֛ל וְ⁠אֵ֥ין ע֖וֹד אֶ֥פֶס אֱלֹהִֽים׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h yĕgi֨yʻa miẕĕra֥yim ẇֽ⁠sĕẖar-k̇ẇş֮̌ ẇ⁠sĕbáʼiym֮ ʼanĕşé֣̌y midá̇h֒ ʻála֤yi⁠kĕ yaʻàbò֨rẇ֙ wĕ⁠lá֣⁠kĕ yiֽhĕy֔ẇ ʼaẖàra֣yi⁠kĕ yélé֔kẇ bȧ⁠zi̇qi֖̇ym yaʻàbò֑rẇ wĕ⁠ʼéla֤yi⁠kĕ yiֽşĕ̌ţȧẖàẇẇ֙ ʼéla֣yi⁠kĕ yiţĕpȧlá̇֔lẇ ʼa֣kĕ bá֥̇⁠kĕ ʼé֛l wĕ⁠ʼé֥yn ʻ֖wòd ʼe֥pes ʼèlòhiֽym׃"],[45,15,"אָכֵ֕ן אַתָּ֖ה אֵ֣ל מִסְתַּתֵּ֑ר אֱלֹהֵ֥י יִשְׂרָאֵ֖ל מוֹשִֽׁיעַ׃","ʼáké֕n ʼaţá֖̇h ʼé֣l misĕţȧţé֑̇r ʼèlòhé֥y yişĕ̂ráʼé֖l mwòşǐֽyʻa׃"],[45,16,"בּ֥וֹשׁוּ וְ⁠גַֽם־נִכְלְמ֖וּ כֻּלָּ֑⁠ם יַחְדָּו֙ הָלְכ֣וּ בַ⁠כְּלִמָּ֔ה חָרָשֵׁ֖י צִירִֽים׃","ḃ֥wòş̌ẇ wĕ⁠gaֽm-nikĕlĕm֖ẇ ku̇lá֑̇⁠m yaẖĕdá̇w֙ hálĕk֣ẇ ba⁠kĕ̇limá̇֔h ẖáráşé֖̌y ẕiyriֽym׃"],[45,17,"יִשְׂרָאֵל֙ נוֹשַׁ֣ע בַּ⁠יהוָ֔ה תְּשׁוּעַ֖ת עוֹלָמִ֑ים לֹא־תֵבֹ֥שׁוּ וְ⁠לֹא־תִכָּלְמ֖וּ עַד־ע֥וֹלְמֵי עַֽד׃פ","yişĕ̂ráʼél֙ nwòşǎ֣ʻ bȧ⁠yhwá֔h ţĕ̇ş̌ẇʻa֖ţ ʻwòlámi֑ym lòʼ-ţébò֥ş̌ẇ wĕ⁠lòʼ-ţiká̇lĕm֖ẇ ʻad-ʻ֥wòlĕméy ʻaֽd׃p"],[45,18,"כִּ֣י כֹ֣ה אָֽמַר־יְ֠הוָה בּוֹרֵ֨א הַ⁠שָּׁמַ֜יִם ה֣וּא הָ⁠אֱלֹהִ֗ים יֹצֵ֨ר הָ⁠אָ֤רֶץ וְ⁠עֹשָׂ⁠הּ֙ ה֣וּא כֽוֹנְנָ֔⁠הּ לֹא־תֹ֥הוּ בְרָאָ֖⁠הּ לָ⁠שֶׁ֣בֶת יְצָרָ֑⁠הּ אֲנִ֥י יְהוָ֖ה וְ⁠אֵ֥ין עֽוֹד׃","ki֣̇y kò֣h ʼáֽmar-yĕ֠hwáh ḃwòré֨ʼ ha⁠şá̇̌ma֜yim h֣ẇʼ há⁠ʼèlòhi֗ym yòẕé֨r há⁠ʼá֤reẕ wĕ⁠ʻòşá̂⁠ḣ֙ h֣ẇʼ kֽwònĕná֔⁠ḣ lòʼ-ţò֥hẇ bĕráʼá֖⁠ḣ lá⁠şě֣beţ yĕẕárá֑⁠ḣ ʼàni֥y yĕhwá֖h wĕ⁠ʼé֥yn ʻֽwòd׃"],[45,19,"לֹ֧א בַ⁠סֵּ֣תֶר דִּבַּ֗רְתִּי בִּ⁠מְקוֹם֙ אֶ֣רֶץ חֹ֔שֶׁךְ לֹ֥א אָמַ֛רְתִּי לְ⁠זֶ֥רַע יַעֲקֹ֖ב תֹּ֣הוּ בַקְּשׁ֑וּ⁠נִי אֲנִ֤י יְהוָה֙ דֹּבֵ֣ר צֶ֔דֶק מַגִּ֖יד מֵישָׁרִֽים׃","lò֧ʼ ba⁠sé֣̇ţer di̇bȧ֗rĕţi̇y bi̇⁠mĕqwòm֙ ʼe֣reẕ ẖò֔şěkĕ lò֥ʼ ʼáma֛rĕţi̇y lĕ⁠ze֥raʻ yaʻàqò֖b ţò֣̇hẇ baqĕ̇ş֑̌ẇ⁠niy ʼàni֤y yĕhwáh֙ dò̇bé֣r ẕe֔deq magi֖̇yd méyşá̌riֽym׃"],[45,20,"הִקָּבְצ֥וּ וָ⁠בֹ֛אוּ הִֽתְנַגְּשׁ֥וּ יַחְדָּ֖ו פְּלִיטֵ֣י הַ⁠גּוֹיִ֑ם לֹ֣א יָדְע֗וּ הַ⁠נֹּֽשְׂאִים֙ אֶת־עֵ֣ץ פִּסְלָ֔⁠ם וּ⁠מִתְפַּלְלִ֔ים אֶל־אֵ֖ל לֹ֥א יוֹשִֽׁיעַ׃","hiqá̇bĕẕ֥ẇ wá⁠bò֛ʼẇ hiֽţĕnagĕ̇ş֥̌ẇ yaẖĕdá֖̇w pĕ̇liyté֣y ha⁠ġwòyi֑m lò֣ʼ yádĕʻ֗ẇ ha⁠nòֽ̇şĕ̂ʼiym֙ ʼeţ-ʻé֣ẕ pi̇sĕlá֔⁠m ẇ⁠miţĕpȧlĕli֔ym ʼel-ʼé֖l lò֥ʼ ywòşǐֽyʻa׃"],[45,21,"הַגִּ֣ידוּ וְ⁠הַגִּ֔ישׁוּ אַ֥ף יִֽוָּעֲצ֖וּ יַחְדָּ֑ו מִ֣י הִשְׁמִיעַ֩ זֹ֨את מִ⁠קֶּ֜דֶם מֵ⁠אָ֣ז הִגִּידָ֗⁠הּ הֲ⁠ל֨וֹא אֲנִ֤י יְהוָה֙ וְ⁠אֵֽין־ע֤וֹד אֱלֹהִים֙ מִ⁠בַּלְעָדַ֔⁠י אֵֽל־צַדִּ֣יק וּ⁠מוֹשִׁ֔יעַ אַ֖יִן זוּלָתִֽ⁠י׃","hagi֣̇ydẇ wĕ⁠hagi̇֔yş̌ẇ ʼa֥p yiֽwá̇ʻàẕ֖ẇ yaẖĕdá֑̇w mi֣y hişĕ̌miyʻa֩ zò֨ʼţ mi⁠qė֜dem mé⁠ʼá֣z higi̇ydá֗⁠ḣ hà⁠l֨wòʼ ʼàni֤y yĕhwáh֙ wĕ⁠ʼéֽyn-ʻ֤wòd ʼèlòhiym֙ mi⁠bȧlĕʻáda֔⁠y ʼéֽl-ẕadi֣̇yq ẇ⁠mwòşǐ֔yʻa ʼa֖yin zẇláţiֽ⁠y׃"],[45,22,"פְּנוּ־אֵלַ֥⁠י וְ⁠הִוָּשְׁע֖וּ כָּל־אַפְסֵי־אָ֑רֶץ כִּ֥י אֲנִי־אֵ֖ל וְ⁠אֵ֥ין עֽוֹד׃","pĕ̇nẇ-ʼéla֥⁠y wĕ⁠hiwá̇şĕ̌ʻ֖ẇ ká̇l-ʼapĕséy-ʼá֑reẕ ki֥̇y ʼàniy-ʼé֖l wĕ⁠ʼé֥yn ʻֽwòd׃"],[45,23,"בִּ֣⁠י נִשְׁבַּ֔עְתִּי יָצָ֨א מִ⁠פִּ֧⁠י צְדָקָ֛ה דָּבָ֖ר וְ⁠לֹ֣א יָשׁ֑וּב כִּי־לִ⁠י֙ תִּכְרַ֣ע כָּל־בֶּ֔רֶךְ תִּשָּׁבַ֖ע כָּל־לָשֽׁוֹן׃","bi֣̇⁠y nişĕ̌bȧ֔ʻĕţi̇y yáẕá֨ʼ mi⁠pi֧̇⁠y ẕĕdáqá֛h dá̇bá֖r wĕ⁠lò֣ʼ yáş֑̌ẇb ki̇y-li⁠y֙ ţi̇kĕra֣ʻ ká̇l-bė֔rekĕ ţi̇şá̇̌ba֖ʻ ká̇l-láşֽ̌wòn׃"],[45,24,"אַ֧ךְ בַּ⁠יהוָ֛ה לִ֥⁠י אָמַ֖ר צְדָק֣וֹת וָ⁠עֹ֑ז עָדָי⁠ו֙ יָב֣וֹא וְ⁠יֵבֹ֔שׁוּ כֹּ֖ל הַ⁠נֶּחֱרִ֥ים בּֽ⁠וֹ׃","ʼa֧kĕ bȧ⁠yhwá֛h li֥⁠y ʼáma֖r ẕĕdáq֣wòţ wá⁠ʻò֑z ʻádáy⁠w֙ yáb֣wòʼ wĕ⁠yébò֔ş̌ẇ kò֖̇l ha⁠nėẖèri֥ym ḃֽ⁠wò׃"],[45,25,"בַּ⁠יהוָ֛ה יִצְדְּק֥וּ וְ⁠יִֽתְהַלְל֖וּ כָּל־זֶ֥רַע יִשְׂרָאֵֽל׃","bȧ⁠yhwá֛h yiẕĕdĕ̇q֥ẇ wĕ⁠yiֽţĕhalĕl֖ẇ ká̇l-ze֥raʻ yişĕ̂ráʼéֽl׃"],[46,1,"כָּרַ֥ע בֵּל֙ קֹרֵ֣ס נְב֔וֹ הָיוּ֙ עֲצַבֵּי⁠הֶ֔ם לַ⁠חַיָּ֖ה וְ⁠לַ⁠בְּהֵמָ֑ה נְשֻׂאֹתֵי⁠כֶ֣ם עֲמוּס֔וֹת מַשָּׂ֖א לַ⁠עֲיֵפָֽה׃","ká̇ra֥ʻ bé̇l֙ qòré֣s nĕb֔wò háyẇ֙ ʻàẕabé̇y⁠he֔m la⁠ẖayá֖̇h wĕ⁠la⁠bĕ̇hémá֑h nĕşûʼòţéy⁠ke֣m ʻàmẇs֔wòţ maşá֖̇̂ʼ la⁠ʻàyépáֽh׃"],[46,2,"קָרְס֤וּ כָֽרְעוּ֙ יַחְדָּ֔ו לֹ֥א יָכְל֖וּ מַלֵּ֣ט מַשָּׂ֑א וְ⁠נַפְשָׁ֖⁠ם בַּ⁠שְּׁבִ֥י הָלָֽכָה׃ס","qárĕs֤ẇ káֽrĕʻẇ֙ yaẖĕdá̇֔w lò֥ʼ yákĕl֖ẇ malé֣̇t maşá֑̇̂ʼ wĕ⁠napĕşá֖̌⁠m bȧ⁠şĕ̇̌bi֥y háláֽkáh׃s"],[46,3,"שִׁמְע֤וּ אֵלַ⁠י֙ בֵּ֣ית יַעֲקֹ֔ב וְ⁠כָל־שְׁאֵרִ֖ית בֵּ֣ית יִשְׂרָאֵ֑ל הַֽ⁠עֲמֻסִים֙ מִנִּי־בֶ֔טֶן הַ⁠נְּשֻׂאִ֖ים מִנִּי־רָֽחַם׃","şǐmĕʻ֤ẇ ʼéla⁠y֙ bé֣̇yţ yaʻàqò֔b wĕ⁠kál-şĕ̌ʼéri֖yţ bé֣̇yţ yişĕ̂ráʼé֑l haֽ⁠ʻàmusiym֙ mini̇y-be֔ten ha⁠nĕ̇şûʼi֖ym mini̇y-ráֽẖam׃"],[46,4,"וְ⁠עַד־זִקְנָה֙ אֲנִ֣י ה֔וּא וְ⁠עַד־שֵיבָ֖ה אֲנִ֣י אֶסְבֹּ֑ל אֲנִ֤י עָשִׂ֨יתִי֙ וַ⁠אֲנִ֣י אֶשָּׂ֔א וַ⁠אֲנִ֥י אֶסְבֹּ֖ל וַ⁠אֲמַלֵּֽט׃ס","wĕ⁠ʻad-ziqĕnáh֙ ʼàni֣y h֔ẇʼ wĕ⁠ʻad-şéybá֖h ʼàni֣y ʼesĕbò֑̇l ʼàni֤y ʻáşî֨yţiy֙ wa⁠ʼàni֣y ʼeşá̇̂֔ʼ wa⁠ʼàni֥y ʼesĕbò֖̇l wa⁠ʼàmaléֽ̇t׃s"],[46,5,"לְ⁠מִ֥י תְדַמְי֖וּ⁠נִי וְ⁠תַשְׁו֑וּ וְ⁠תַמְשִׁל֖וּ⁠נִי וְ⁠נִדְמֶֽה׃","lĕ⁠mi֥y ţĕdamĕy֖ẇ⁠niy wĕ⁠ţaşĕ̌w֑ẇ wĕ⁠ţamĕşǐl֖ẇ⁠niy wĕ⁠nidĕmeֽh׃"],[46,6,"הַ⁠זָּלִ֤ים זָהָב֙ מִ⁠כִּ֔יס וְ⁠כֶ֖סֶף בַּ⁠קָּנֶ֣ה יִשְׁקֹ֑לוּ יִשְׂכְּר֤וּ צוֹרֵף֙ וְ⁠יַעֲשֵׂ֣⁠הוּ אֵ֔ל יִסְגְּד֖וּ אַף־יִֽשְׁתַּחֲוּֽוּ׃","ha⁠zá̇li֤ym záháb֙ mi⁠ki̇֔ys wĕ⁠ke֖sep bȧ⁠qá̇ne֣h yişĕ̌qò֑lẇ yişĕ̂kĕ̇r֤ẇ ẕwòrép֙ wĕ⁠yaʻàşé֣̂⁠hẇ ʼé֔l yisĕgĕ̇d֖ẇ ʼap-yiֽşĕ̌ţȧẖàẇֽẇ׃"],[46,7,"יִ֠שָּׂאֻ⁠הוּ עַל־כָּתֵ֨ף יִסְבְּלֻ֜⁠הוּ וְ⁠יַנִּיחֻ֤⁠הוּ תַחְתָּי⁠ו֙ וְ⁠יַֽעֲמֹ֔ד מִ⁠מְּקוֹמ֖⁠וֹ לֹ֣א יָמִ֑ישׁ אַף־יִצְעַ֤ק אֵלָי⁠ו֙ וְ⁠לֹ֣א יַעֲנֶ֔ה מִ⁠צָּרָת֖⁠וֹ לֹ֥א יוֹשִׁיעֶֽ⁠נּוּ׃ס","yi֠şá̇̂ʼu⁠hẇ ʻal-ká̇ţé֨p yisĕbĕ̇lu֜⁠hẇ wĕ⁠yani̇yẖu֤⁠hẇ ţaẖĕţá̇y⁠w֙ wĕ⁠yaֽʻàmò֔d mi⁠mĕ̇qwòm֖⁠wò lò֣ʼ yámi֑yş̌ ʼap-yiẕĕʻa֤q ʼéláy⁠w֙ wĕ⁠lò֣ʼ yaʻàne֔h mi⁠ẕá̇ráţ֖⁠wò lò֥ʼ ywòşǐyʻeֽ⁠ṅẇ׃s"],[46,8,"זִכְרוּ־זֹ֖את וְ⁠הִתְאֹשָׁ֑שׁוּ הָשִׁ֥יבוּ פוֹשְׁעִ֖ים עַל־לֵֽב׃","zikĕrẇ-zò֖ʼţ wĕ⁠hiţĕʼòşá֑̌ş̌ẇ háşǐ֥ybẇ pwòşĕ̌ʻi֖ym ʻal-léֽb׃"],[46,9,"זִכְר֥וּ רִאשֹׁנ֖וֹת מֵ⁠עוֹלָ֑ם כִּ֣י אָנֹכִ֥י אֵל֙ וְ⁠אֵ֣ין ע֔וֹד אֱלֹהִ֖ים וְ⁠אֶ֥פֶס כָּמֽוֹ⁠נִי׃","zikĕr֥ẇ riʼşò̌n֖wòţ mé⁠ʻwòlá֑m ki֣̇y ʼánòki֥y ʼél֙ wĕ⁠ʼé֣yn ʻ֔wòd ʼèlòhi֖ym wĕ⁠ʼe֥pes ká̇mֽwò⁠niy׃"],[46,10,"מַגִּ֤יד מֵֽ⁠רֵאשִׁית֙ אַחֲרִ֔ית וּ⁠מִ⁠קֶּ֖דֶם אֲשֶׁ֣ר לֹא־נַעֲשׂ֑וּ אֹמֵר֙ עֲצָתִ֣⁠י תָק֔וּם וְ⁠כָל־חֶפְצִ֖⁠י אֶעֱשֶֽׂה׃","magi֤̇yd méֽ⁠réʼşǐyţ֙ ʼaẖàri֔yţ ẇ⁠mi⁠qė֖dem ʼàşě֣r lòʼ-naʻàş֑̂ẇ ʼòmér֙ ʻàẕáţi֣⁠y ţáq֔ẇm wĕ⁠kál-ẖepĕẕi֖⁠y ʼeʻèşêֽh׃"],[46,11,"קֹרֵ֤א מִ⁠מִּזְרָח֙ עַ֔יִט מֵ⁠אֶ֥רֶץ מֶרְחָ֖ק אִ֣ישׁ עצת⁠ו אַף־דִּבַּ֨רְתִּי֙ אַף־אֲבִיאֶ֔⁠נָּה יָצַ֖רְתִּי אַף־אֶעֱשֶֽׂ⁠נָּה׃ס","qòré֤ʼ mi⁠mi̇zĕráẖ֙ ʻa֔yit mé⁠ʼe֥reẕ merĕẖá֖q ʼi֣yş̌ ʻẕţ⁠w ʼap-di̇bȧ֨rĕţi̇y֙ ʼap-ʼàbiyʼe֔⁠ná̇h yáẕa֖rĕţi̇y ʼap-ʼeʻèşêֽ⁠ná̇h׃s"],[46,12,"שִׁמְע֥וּ אֵלַ֖⁠י אַבִּ֣ירֵי לֵ֑ב הָ⁠רְחוֹקִ֖ים מִ⁠צְּדָקָֽה׃","şǐmĕʻ֥ẇ ʼéla֖⁠y ʼabi֣̇yréy lé֑b há⁠rĕẖwòqi֖ym mi⁠ẕĕ̇dáqáֽh׃"],[46,13,"קֵרַ֤בְתִּי צִדְקָתִ⁠י֙ לֹ֣א תִרְחָ֔ק וּ⁠תְשׁוּעָתִ֖⁠י לֹ֣א תְאַחֵ֑ר וְ⁠נָתַתִּ֤י בְ⁠צִיּוֹן֙ תְּשׁוּעָ֔ה לְ⁠יִשְׂרָאֵ֖ל תִּפְאַרְתִּֽ⁠י׃ס","qéra֤bĕţi̇y ẕidĕqáţi⁠y֙ lò֣ʼ ţirĕẖá֔q ẇ⁠ţĕş̌ẇʻáţi֖⁠y lò֣ʼ ţĕʼaẖé֑r wĕ⁠náţaţi֤̇y bĕ⁠ẕiẏwòn֙ ţĕ̇ş̌ẇʻá֔h lĕ⁠yişĕ̂ráʼé֖l ţi̇pĕʼarĕţiֽ̇⁠y׃s"],[47,1,"רְדִ֣י ׀ וּ⁠שְׁבִ֣י עַל־עָפָ֗ר בְּתוּלַת֙ בַּת־בָּבֶ֔ל שְׁבִי־לָ⁠אָ֥רֶץ אֵין־כִּסֵּ֖א בַּת־כַּשְׂדִּ֑ים כִּ֣י לֹ֤א תוֹסִ֨יפִי֙ יִקְרְאוּ־לָ֔⁠ךְ רַכָּ֖ה וַ⁠עֲנֻגָּֽה׃","rĕdi֣y ׀ ẇ⁠şĕ̌bi֣y ʻal-ʻápá֗r bĕ̇ţẇlaţ֙ bȧţ-bá̇be֔l şĕ̌biy-lá⁠ʼá֥reẕ ʼéyn-ki̇sé֖̇ʼ bȧţ-kȧşĕ̂di֑̇ym ki֣̇y lò֤ʼ ţwòsi֨ypiy֙ yiqĕrĕʼẇ-lá֔⁠kĕ raká֖̇h wa⁠ʻànugáֽ̇h׃"],[47,2,"קְחִ֥י רֵחַ֖יִם וְ⁠טַ֣חֲנִי קָ֑מַח גַּלִּ֨י צַמָּתֵ֧⁠ךְ חֶשְׂפִּי־שֹׁ֛בֶל גַּלִּי־שׁ֖וֹק עִבְרִ֥י נְהָרֽוֹת׃","qĕẖi֥y réẖa֖yim wĕ⁠ta֣ẖàniy qá֑maẖ gȧli̇֨y ẕamá̇ţé֧⁠kĕ ẖeşĕ̂pi̇y-şò֛̌bel gȧli̇y-ş֖̌wòq ʻibĕri֥y nĕhárֽwòţ׃"],[47,3,"תִּגָּל֙ עֶרְוָתֵ֔⁠ךְ גַּ֥ם תֵּרָאֶ֖ה חֶרְפָּתֵ֑⁠ךְ נָקָ֣ם אֶקָּ֔ח וְ⁠לֹ֥א אֶפְגַּ֖ע אָדָֽם׃ס","ţi̇gá̇l֙ ʻerĕwáţé֔⁠kĕ gȧ֥m ţé̇ráʼe֖h ẖerĕpá̇ţé֑⁠kĕ náqá֣m ʼeqá̇֔ẖ wĕ⁠lò֥ʼ ʼepĕgȧ֖ʻ ʼádáֽm׃s"],[47,4,"גֹּאֲלֵ֕⁠נוּ יְהוָ֥ה צְבָא֖וֹת שְׁמ֑⁠וֹ קְד֖וֹשׁ יִשְׂרָאֵֽל׃","gò̇ʼàlé֕⁠nẇ yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌m֑⁠wò qĕd֖wòş̌ yişĕ̂ráʼéֽl׃"],[47,5,"שְׁבִ֥י דוּמָ֛ם וּ⁠בֹ֥אִי בַ⁠חֹ֖שֶׁךְ בַּת־כַּשְׂדִּ֑ים כִּ֣י לֹ֤א תוֹסִ֨יפִי֙ יִקְרְאוּ־לָ֔⁠ךְ גְּבֶ֖רֶת מַמְלָכֽוֹת׃","şĕ̌bi֥y dẇmá֛m ẇ⁠bò֥ʼiy ba⁠ẖò֖şěkĕ bȧţ-kȧşĕ̂di֑̇ym ki֣̇y lò֤ʼ ţwòsi֨ypiy֙ yiqĕrĕʼẇ-lá֔⁠kĕ gĕ̇be֖reţ mamĕlákֽwòţ׃"],[47,6,"קָצַ֣פְתִּי עַל־עַמִּ֗⁠י חִלַּ֨לְתִּי֙ נַחֲלָתִ֔⁠י וָ⁠אֶתְּנֵ֖⁠ם בְּ⁠יָדֵ֑⁠ךְ לֹא־שַׂ֤מְתְּ לָ⁠הֶם֙ רַחֲמִ֔ים עַל־זָקֵ֕ן הִכְבַּ֥דְתְּ עֻלֵּ֖⁠ךְ מְאֹֽד׃","qáẕa֣pĕţi̇y ʻal-ʻami̇֗⁠y ẖilȧ֨lĕţi̇y֙ naẖàláţi֔⁠y wá⁠ʼeţĕ̇né֖⁠m bĕ̇⁠yádé֑⁠kĕ lòʼ-şâ֤mĕţĕ̇ lá⁠hem֙ raẖàmi֔ym ʻal-záqé֕n hikĕbȧ֥dĕţĕ̇ ʻulé֖̇⁠kĕ mĕʼòֽd׃"],[47,7,"וַ⁠תֹּ֣אמְרִ֔י לְ⁠עוֹלָ֖ם אֶהְיֶ֣ה גְבָ֑רֶת עַ֣ד לֹא־שַׂ֥מְתְּ אֵ֨לֶּה֙ עַל־לִבֵּ֔⁠ךְ לֹ֥א זָכַ֖רְתְּ אַחֲרִיתָֽ⁠הּ׃ס","wa⁠ţò֣̇ʼmĕri֔y lĕ⁠ʻwòlá֖m ʼehĕye֣h gĕbá֑reţ ʻa֣d lòʼ-şâ֥mĕţĕ̇ ʼé֨lėh֙ ʻal-libé̇֔⁠kĕ lò֥ʼ záka֖rĕţĕ̇ ʼaẖàriyţáֽ⁠ḣ׃s"],[47,8,"וְ⁠עַתָּ֞ה שִׁמְעִי־זֹ֤את עֲדִינָה֙ הַ⁠יּוֹשֶׁ֣בֶת לָ⁠בֶ֔טַח הָ⁠אֹֽמְרָה֙ בִּ⁠לְבָ֔בָ⁠הּ אֲנִ֖י וְ⁠אַפְסִ֣⁠י ע֑וֹד לֹ֤א אֵשֵׁב֙ אַלְמָנָ֔ה וְ⁠לֹ֥א אֵדַ֖ע שְׁכֽוֹל׃","wĕ⁠ʻaţá̇֞h şǐmĕʻiy-zò֤ʼţ ʻàdiynáh֙ ha⁠ẏwòşě֣beţ lá⁠be֔taẖ há⁠ʼòֽmĕráh֙ bi̇⁠lĕbá֔bá⁠ḣ ʼàni֖y wĕ⁠ʼapĕsi֣⁠y ʻ֑wòd lò֤ʼ ʼéşé̌b֙ ʼalĕmáná֔h wĕ⁠lò֥ʼ ʼéda֖ʻ şĕ̌kֽwòl׃"],[47,9,"וְ⁠תָבֹאנָה֩ לָּ֨⁠ךְ שְׁתֵּי־אֵ֥לֶּה רֶ֛גַע בְּ⁠י֥וֹם אֶחָ֖ד שְׁכ֣וֹל וְ⁠אַלְמֹ֑ן כְּ⁠תֻמָּ⁠ם֙ בָּ֣אוּ עָלַ֔יִ⁠ךְ בְּ⁠רֹ֣ב כְּשָׁפַ֔יִ⁠ךְ בְּ⁠עָצְמַ֥ת חֲבָרַ֖יִ⁠ךְ מְאֹֽד׃","wĕ⁠ţábòʼnáh֩ lá̇֨⁠kĕ şĕ̌ţé̇y-ʼé֥lėh re֛gaʻ bĕ̇⁠y֥wòm ʼeẖá֖d şĕ̌k֣wòl wĕ⁠ʼalĕmò֑n kĕ̇⁠ţumá̇⁠m֙ bá֣̇ʼẇ ʻála֔yi⁠kĕ bĕ̇⁠rò֣b kĕ̇şá̌pa֔yi⁠kĕ bĕ̇⁠ʻáẕĕma֥ţ ẖàbára֖yi⁠kĕ mĕʼòֽd׃"],[47,10,"וַ⁠תִּבְטְחִ֣י בְ⁠רָעָתֵ֗⁠ךְ אָמַרְתְּ֙ אֵ֣ין רֹאָ֔⁠נִי חָכְמָתֵ֥⁠ךְ וְ⁠דַעְתֵּ֖⁠ךְ הִ֣יא שׁוֹבְבָ֑תֶ⁠ךְ וַ⁠תֹּאמְרִ֣י בְ⁠לִבֵּ֔⁠ךְ אֲנִ֖י וְ⁠אַפְסִ֥⁠י עֽוֹד׃","wa⁠ţi̇bĕtĕẖi֣y bĕ⁠ráʻáţé֗⁠kĕ ʼámarĕţĕ̇֙ ʼé֣yn ròʼá֔⁠niy ẖákĕmáţé֥⁠kĕ wĕ⁠daʻĕţé֖̇⁠kĕ hi֣yʼ ş̌wòbĕbá֑ţe⁠kĕ wa⁠ţò̇ʼmĕri֣y bĕ⁠libé̇֔⁠kĕ ʼàni֖y wĕ⁠ʼapĕsi֥⁠y ʻֽwòd׃"],[47,11,"וּ⁠בָ֧א עָלַ֣יִ⁠ךְ רָעָ֗ה לֹ֤א תֵדְעִי֙ שַׁחְרָ֔⁠הּ וְ⁠תִפֹּ֤ל עָלַ֨יִ⁠ךְ֙ הֹוָ֔ה לֹ֥א תוּכְלִ֖י כַּפְּרָ֑⁠הּ וְ⁠תָבֹ֨א עָלַ֧יִ⁠ךְ פִּתְאֹ֛ם שׁוֹאָ֖ה לֹ֥א תֵדָֽעִי׃","ẇ⁠bá֧ʼ ʻála֣yi⁠kĕ ráʻá֗h lò֤ʼ ţédĕʻiy֙ şǎẖĕrá֔⁠ḣ wĕ⁠ţipò֤̇l ʻála֨yi⁠kĕ֙ hòwá֔h lò֥ʼ ţẇkĕli֖y kȧpĕ̇rá֑⁠ḣ wĕ⁠ţábò֨ʼ ʻála֧yi⁠kĕ pi̇ţĕʼò֛m ş̌wòʼá֖h lò֥ʼ ţédáֽʻiy׃"],[47,12,"עִמְדִי־נָ֤א בַ⁠חֲבָרַ֨יִ⁠ךְ֙ וּ⁠בְ⁠רֹ֣ב כְּשָׁפַ֔יִ⁠ךְ בַּ⁠אֲשֶׁ֥ר יָגַ֖עַתְּ מִ⁠נְּעוּרָ֑יִ⁠ךְ אוּלַ֛י תּוּכְלִ֥י הוֹעִ֖יל אוּלַ֥י תַּעֲרֽוֹצִי׃","ʻimĕdiy-ná֤ʼ ba⁠ẖàbára֨yi⁠kĕ֙ ẇ⁠bĕ⁠rò֣b kĕ̇şá̌pa֔yi⁠kĕ bȧ⁠ʼàşě֥r yága֖ʻaţĕ̇ mi⁠nĕ̇ʻẇrá֑yi⁠kĕ ʼẇla֛y ţ̇ẇkĕli֥y hwòʻi֖yl ʼẇla֥y ţȧʻàrֽwòẕiy׃"],[47,13,"נִלְאֵ֖ית בְּ⁠רֹ֣ב עֲצָתָ֑יִ⁠ךְ יַעַמְדוּ־נָ֨א וְ⁠יוֹשִׁיעֻ֜⁠ךְ הברו שָׁמַ֗יִם הַֽ⁠חֹזִים֙ בַּ⁠כּ֣וֹכָבִ֔ים מֽוֹדִיעִם֙ לֶ⁠חֳדָשִׁ֔ים מֵ⁠אֲשֶׁ֥ר יָבֹ֖אוּ עָלָֽיִ⁠ךְ׃","nilĕʼé֖yţ bĕ̇⁠rò֣b ʻàẕáţá֑yi⁠kĕ yaʻamĕdẇ-ná֨ʼ wĕ⁠ywòşǐyʻu֜⁠kĕ hbrw şá̌ma֗yim haֽ⁠ẖòziym֙ bȧ⁠k֣̇wòkábi֔ym mֽwòdiyʻim֙ le⁠ẖodáşǐ֔ym mé⁠ʼàşě֥r yábò֖ʼẇ ʻáláֽyi⁠kĕ׃"],[47,14,"הִנֵּ֨ה הָי֤וּ כְ⁠קַשׁ֙ אֵ֣שׁ שְׂרָפָ֔תַ⁠ם לֹֽא־יַצִּ֥ילוּ אֶת־נַפְשָׁ֖⁠ם מִ⁠יַּ֣ד לֶֽהָבָ֑ה אֵין־גַּחֶ֣לֶת לַ⁠חְמָ֔ם א֖וּר לָ⁠שֶׁ֥בֶת נֶגְדּֽ⁠וֹ׃","hiné̇֨h háy֤ẇ kĕ⁠qaş̌֙ ʼé֣ş̌ şĕ̂rápá֔ţa⁠m lòֽʼ-yaẕi֥̇ylẇ ʼeţ-napĕşá֖̌⁠m mi⁠yȧ֣d leֽhábá֑h ʼéyn-gȧẖe֣leţ la⁠ẖĕmá֔m ʼ֖ẇr lá⁠şě֥beţ negĕḋֽ⁠wò׃"],[47,15,"כֵּ֥ן הָיוּ־לָ֖⁠ךְ אֲשֶׁ֣ר יָגָ֑עַתְּ סֹחֲרַ֣יִ⁠ךְ מִ⁠נְּעוּרַ֗יִ⁠ךְ אִ֤ישׁ לְ⁠עֶבְר⁠וֹ֙ תָּע֔וּ אֵ֖ין מוֹשִׁיעֵֽ⁠ךְ׃ס","ké֥̇n háyẇ-lá֖⁠kĕ ʼàşě֣r yágá֑ʻaţĕ̇ sòẖàra֣yi⁠kĕ mi⁠nĕ̇ʻẇra֗yi⁠kĕ ʼi֤yş̌ lĕ⁠ʻebĕr⁠wò֙ ţá̇ʻ֔ẇ ʼé֖yn mwòşǐyʻéֽ⁠kĕ׃s"],[48,1,"שִׁמְעוּ־זֹ֣את בֵּֽית־יַעֲקֹ֗ב הַ⁠נִּקְרָאִים֙ בְּ⁠שֵׁ֣ם יִשְׂרָאֵ֔ל וּ⁠מִ⁠מֵּ֥י יְהוּדָ֖ה יָצָ֑אוּ הַֽ⁠נִּשְׁבָּעִ֣ים ׀ בְּ⁠שֵׁ֣ם יְהוָ֗ה וּ⁠בֵ⁠אלֹהֵ֤י יִשְׂרָאֵל֙ יַזְכִּ֔ירוּ לֹ֥א בֶ⁠אֱמֶ֖ת וְ⁠לֹ֥א בִ⁠צְדָקָֽה׃","şǐmĕʻẇ-zò֣ʼţ béֽ̇yţ-yaʻàqò֗b ha⁠ni̇qĕráʼiym֙ bĕ̇⁠şé֣̌m yişĕ̂ráʼé֔l ẇ⁠mi⁠mé֥̇y yĕhẇdá֖h yáẕá֑ʼẇ haֽ⁠ni̇şĕ̌bá̇ʻi֣ym ׀ bĕ̇⁠şé֣̌m yĕhwá֗h ẇ⁠bé⁠ʼlòhé֤y yişĕ̂ráʼél֙ yazĕki̇֔yrẇ lò֥ʼ be⁠ʼème֖ţ wĕ⁠lò֥ʼ bi⁠ẕĕdáqáֽh׃"],[48,2,"כִּֽי־מֵ⁠עִ֤יר הַ⁠קֹּ֨דֶשׁ֙ נִקְרָ֔אוּ וְ⁠עַל־אֱלֹהֵ֥י יִשְׂרָאֵ֖ל נִסְמָ֑כוּ יְהוָ֥ה צְבָא֖וֹת שְׁמֽ⁠וֹ׃ס","kiֽ̇y-mé⁠ʻi֤yr ha⁠qò̇֨deş̌֙ niqĕrá֔ʼẇ wĕ⁠ʻal-ʼèlòhé֥y yişĕ̂ráʼé֖l nisĕmá֑kẇ yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌mֽ⁠wò׃s"],[48,3,"הָ⁠רִֽאשֹׁנוֹת֙ מֵ⁠אָ֣ז הִגַּ֔דְתִּי וּ⁠מִ⁠פִּ֥⁠י יָצְא֖וּ וְ⁠אַשְׁמִיעֵ֑⁠ם פִּתְאֹ֥ם עָשִׂ֖יתִי וַ⁠תָּבֹֽאנָה׃","há⁠riֽʼşò̌nwòţ֙ mé⁠ʼá֣z higȧ֔dĕţi̇y ẇ⁠mi⁠pi֥̇⁠y yáẕĕʼ֖ẇ wĕ⁠ʼaşĕ̌miyʻé֑⁠m pi̇ţĕʼò֥m ʻáşî֖yţiy wa⁠ţá̇bòֽʼnáh׃"],[48,4,"מִ⁠דַּעְתִּ֕⁠י כִּ֥י קָשֶׁ֖ה אָ֑תָּה וְ⁠גִ֤יד בַּרְזֶל֙ עָרְפֶּ֔⁠ךָ וּ⁠מִצְחֲ⁠ךָ֖ נְחוּשָֽׁה׃","mi⁠dȧʻĕţi̇֕⁠y ki֥̇y qáşě֖h ʼá֑ţá̇h wĕ⁠gi֤yd bȧrĕzel֙ ʻárĕpė֔⁠ká ẇ⁠miẕĕẖà⁠ká֖ nĕẖẇşáֽ̌h׃"],[48,5,"וָ⁠אַגִּ֤יד לְ⁠ךָ֙ מֵ⁠אָ֔ז בְּ⁠טֶ֥רֶם תָּב֖וֹא הִשְׁמַעְתִּ֑י⁠ךָ פֶּן־תֹּאמַר֙ עָצְבִּ֣⁠י עָשָׂ֔⁠ם וּ⁠פִסְלִ֥⁠י וְ⁠נִסְכִּ֖⁠י צִוָּֽ⁠ם׃","wá⁠ʼagi֤̇yd lĕ⁠ká֙ mé⁠ʼá֔z bĕ̇⁠te֥rem ţá̇b֖wòʼ hişĕ̌maʻĕţi֑̇y⁠ká pėn-ţò̇ʼmar֙ ʻáẕĕbi֣̇⁠y ʻáşá̂֔⁠m ẇ⁠pisĕli֥⁠y wĕ⁠nisĕki֖̇⁠y ẕiwáֽ̇⁠m׃"],[48,6,"שָׁמַ֤עְתָּֽ חֲזֵה֙ כֻּלָּ֔⁠הּ וְ⁠אַתֶּ֖ם הֲ⁠ל֣וֹא תַגִּ֑ידוּ הִשְׁמַעְתִּ֤י⁠ךָ חֲדָשׁוֹת֙ מֵ⁠עַ֔תָּה וּ⁠נְצֻר֖וֹת וְ⁠לֹ֥א יְדַעְתָּֽ⁠ם׃","şá̌ma֤ʻĕţáֽ̇ ẖàzéh֙ ku̇lá̇֔⁠ḣ wĕ⁠ʼaţė֖m hà⁠l֣wòʼ ţagi֑̇ydẇ hişĕ̌maʻĕţi֤̇y⁠ká ẖàdáş̌wòţ֙ mé⁠ʻa֔ţá̇h ẇ⁠nĕẕur֖wòţ wĕ⁠lò֥ʼ yĕdaʻĕţáֽ̇⁠m׃"],[48,7,"עַתָּ֤ה נִבְרְאוּ֙ וְ⁠לֹ֣א מֵ⁠אָ֔ז וְ⁠לִ⁠פְנֵי־י֖וֹם וְ⁠לֹ֣א שְׁמַעְתָּ֑⁠ם פֶּן־תֹּאמַ֖ר הִנֵּ֥ה יְדַעְתִּֽי⁠ן׃","ʻaţá֤̇h nibĕrĕʼẇ֙ wĕ⁠lò֣ʼ mé⁠ʼá֔z wĕ⁠li⁠pĕnéy-y֖wòm wĕ⁠lò֣ʼ şĕ̌maʻĕţá֑̇⁠m pėn-ţò̇ʼma֖r hiné֥̇h yĕdaʻĕţiֽ̇y⁠n׃"],[48,8,"גַּ֣ם לֹֽא־שָׁמַ֗עְתָּ גַּ֚ם לֹ֣א יָדַ֔עְתָּ גַּ֕ם מֵ⁠אָ֖ז לֹא־פִתְּחָ֣ה אָזְנֶ֑⁠ךָ כִּ֤י יָדַ֨עְתִּי֙ בָּג֣וֹד תִּבְגּ֔וֹד וּ⁠פֹשֵׁ֥עַ מִ⁠בֶּ֖טֶן קֹ֥רָא לָֽ⁠ךְ׃","gȧ֣m lòֽʼ-şá̌ma֗ʻĕţá̇ gȧ֚m lò֣ʼ yáda֔ʻĕţá̇ gȧ֕m mé⁠ʼá֖z lòʼ-piţĕ̇ẖá֣h ʼázĕne֑⁠ká ki֤̇y yáda֨ʻĕţi̇y֙ bá̇g֣wòd ţi̇bĕġ֔wòd ẇ⁠pòşé֥̌ʻa mi⁠bė֖ten qò֥ráʼ láֽ⁠kĕ׃"],[48,9,"לְמַ֤עַן שְׁמִ⁠י֙ אַאֲרִ֣יךְ אַפִּ֔⁠י וּ⁠תְהִלָּתִ֖⁠י אֶחֱטָם־לָ֑⁠ךְ לְ⁠בִלְתִּ֖י הַכְרִיתֶֽ⁠ךָ׃","lĕma֤ʻan şĕ̌mi⁠y֙ ʼaʼàri֣ykĕ ʼapi̇֔⁠y ẇ⁠ţĕhilá̇ţi֖⁠y ʼeẖètám-lá֑⁠kĕ lĕ⁠bilĕţi֖̇y hakĕriyţeֽ⁠ká׃"],[48,10,"הִנֵּ֥ה צְרַפְתִּ֖י⁠ךָ וְ⁠לֹ֣א בְ⁠כָ֑סֶף בְּחַרְתִּ֖י⁠ךָ בְּ⁠כ֥וּר עֹֽנִי׃","hiné֥̇h ẕĕrapĕţi֖̇y⁠ká wĕ⁠lò֣ʼ bĕ⁠ká֑sep bĕ̇ẖarĕţi֖̇y⁠ká bĕ̇⁠k֥ẇr ʻòֽniy׃"],[48,11,"לְמַעֲנִ֧⁠י לְמַעֲנִ֛⁠י אֶעֱשֶׂ֖ה כִּ֣י אֵ֣יךְ יֵחָ֑ל וּ⁠כְבוֹדִ֖⁠י לְ⁠אַחֵ֥ר לֹֽא־אֶתֵּֽן׃ס","lĕmaʻàni֧⁠y lĕmaʻàni֛⁠y ʼeʻèşê֖h ki֣̇y ʼé֣ykĕ yéẖá֑l ẇ⁠kĕbwòdi֖⁠y lĕ⁠ʼaẖé֥r lòֽʼ-ʼeţéֽ̇n׃s"],[48,12,"שְׁמַ֤ע אֵלַ⁠י֙ יַֽעֲקֹ֔ב וְ⁠יִשְׂרָאֵ֖ל מְקֹרָאִ֑⁠י אֲנִי־הוּא֙ אֲנִ֣י רִאשׁ֔וֹן אַ֖ף אֲנִ֥י אַחֲרֽוֹן׃","şĕ̌ma֤ʻ ʼéla⁠y֙ yaֽʻàqò֔b wĕ⁠yişĕ̂ráʼé֖l mĕqòráʼi֑⁠y ʼàniy-hẇʼ֙ ʼàni֣y riʼş̌֔wòn ʼa֖p ʼàni֥y ʼaẖàrֽwòn׃"],[48,13,"אַף־יָדִ⁠י֙ יָ֣סְדָה אֶ֔רֶץ וִֽ⁠ימִינִ֖⁠י טִפְּחָ֣ה שָׁמָ֑יִם קֹרֵ֥א אֲנִ֛י אֲלֵי⁠הֶ֖ם יַעַמְד֥וּ יַחְדָּֽו׃","ʼap-yádi⁠y֙ yá֣sĕdáh ʼe֔reẕ wiֽ⁠ymiyni֖⁠y tipĕ̇ẖá֣h şá̌má֑yim qòré֥ʼ ʼàni֛y ʼàléy⁠he֖m yaʻamĕd֥ẇ yaẖĕdáֽ̇w׃"],[48,14,"הִקָּבְצ֤וּ כֻלְּ⁠כֶם֙ וּֽ⁠שֲׁמָ֔עוּ מִ֥י בָ⁠הֶ֖ם הִגִּ֣יד אֶת־אֵ֑לֶּה יְהוָ֣ה אֲהֵב֔⁠וֹ יַעֲשֶׂ֤ה חֶפְצ⁠וֹ֙ בְּ⁠בָבֶ֔ל וּ⁠זְרֹע֖⁠וֹ כַּשְׂדִּֽים׃","hiqá̇bĕẕ֤ẇ kulĕ̇⁠kem֙ ẇֽ⁠şà̌má֔ʻẇ mi֥y bá⁠he֖m higi֣̇yd ʼeţ-ʼé֑lėh yĕhwá֣h ʼàhéb֔⁠wò yaʻàşê֤h ẖepĕẕ⁠wò֙ bĕ̇⁠bábe֔l ẇ⁠zĕròʻ֖⁠wò kȧşĕ̂diֽ̇ym׃"],[48,15,"אֲנִ֥י אֲנִ֛י דִּבַּ֖רְתִּי אַף־קְרָאתִ֑י⁠ו הֲבִיאֹתִ֖י⁠ו וְ⁠הִצְלִ֥יחַ דַּרְכּֽ⁠וֹ׃","ʼàni֥y ʼàni֛y di̇bȧ֖rĕţi̇y ʼap-qĕráʼţi֑y⁠w hàbiyʼòţi֖y⁠w wĕ⁠hiẕĕli֥yẖa dȧrĕkֽ̇⁠wò׃"],[48,16,"קִרְב֧וּ אֵלַ֣⁠י שִׁמְעוּ־זֹ֗את לֹ֤א מֵ⁠רֹאשׁ֙ בַּ⁠סֵּ֣תֶר דִּבַּ֔רְתִּי מֵ⁠עֵ֥ת הֱיוֹתָ֖⁠הּ שָׁ֣ם אָ֑נִי וְ⁠עַתָּ֗ה אֲדֹנָ֧⁠י יְהוִ֛ה שְׁלָחַ֖⁠נִי וְ⁠רוּחֽ⁠וֹ׃פ","qirĕb֧ẇ ʼéla֣⁠y şǐmĕʻẇ-zò֗ʼţ lò֤ʼ mé⁠ròʼş̌֙ bȧ⁠sé֣̇ţer di̇bȧ֔rĕţi̇y mé⁠ʻé֥ţ hèywòţá֖⁠ḣ şá֣̌m ʼá֑niy wĕ⁠ʻaţá̇֗h ʼàdòná֧⁠y yĕhwi֛h şĕ̌láẖa֖⁠niy wĕ⁠rẇẖֽ⁠wò׃p"],[48,17,"כֹּֽה־אָמַ֧ר יְהוָ֛ה גֹּאַלְ⁠ךָ֖ קְד֣וֹשׁ יִשְׂרָאֵ֑ל אֲנִ֨י יְהוָ֤ה אֱלֹהֶ֨י⁠ךָ֙ מְלַמֶּדְ⁠ךָ֣ לְ⁠הוֹעִ֔יל מַדְרִֽיכֲ⁠ךָ֖ בְּ⁠דֶ֥רֶךְ תֵּלֵֽךְ׃","kòֽ̇h-ʼáma֧r yĕhwá֛h gò̇ʼalĕ⁠ká֖ qĕd֣wòş̌ yişĕ̂ráʼé֑l ʼàni֨y yĕhwá֤h ʼèlòhe֨y⁠ká֙ mĕlamėdĕ⁠ká֣ lĕ⁠hwòʻi֔yl madĕriֽykà⁠ká֖ bĕ̇⁠de֥rekĕ ţé̇léֽkĕ׃"],[48,18,"ל֥וּא הִקְשַׁ֖בְתָּ לְ⁠מִצְוֺתָ֑⁠י וַ⁠יְהִ֤י כַ⁠נָּהָר֙ שְׁלוֹמֶ֔⁠ךָ וְ⁠צִדְקָתְ⁠ךָ֖ כְּ⁠גַלֵּ֥י הַ⁠יָּֽם׃","l֥ẇʼ hiqĕşǎ֖bĕţá̇ lĕ⁠miẕĕwֺţá֑⁠y wa⁠yĕhi֤y ka⁠ná̇hár֙ şĕ̌lwòme֔⁠ká wĕ⁠ẕidĕqáţĕ⁠ká֖ kĕ̇⁠galé֥̇y ha⁠yáֽ̇m׃"],[48,19,"וַ⁠יְהִ֤י כַ⁠חוֹל֙ זַרְעֶ֔⁠ךָ וְ⁠צֶאֱצָאֵ֥י מֵעֶ֖י⁠ךָ כִּ⁠מְעֹתָ֑י⁠ו לֹֽא־יִכָּרֵ֧ת וְֽ⁠לֹא־יִשָּׁמֵ֛ד שְׁמ֖⁠וֹ מִ⁠לְּ⁠פָנָֽ⁠י׃","wa⁠yĕhi֤y ka⁠ẖwòl֙ zarĕʻe֔⁠ká wĕ⁠ẕeʼèẕáʼé֥y méʻe֖y⁠ká ki̇⁠mĕʻòţá֑y⁠w lòֽʼ-yiká̇ré֧ţ wĕֽ⁠lòʼ-yişá̇̌mé֛d şĕ̌m֖⁠wò mi⁠lĕ̇⁠pánáֽ⁠y׃"],[48,20,"צְא֣וּ מִ⁠בָּבֶל֮ בִּרְח֣וּ מִ⁠כַּשְׂדִּים֒ בְּ⁠ק֣וֹל רִנָּ֗ה הַגִּ֤ידוּ הַשְׁמִ֨יעוּ֙ זֹ֔את הוֹצִיא֖וּ⁠הָ עַד־קְצֵ֣ה הָ⁠אָ֑רֶץ אִמְר֕וּ גָּאַ֥ל יְהוָ֖ה עַבְדּ֥⁠וֹ יַעֲקֹֽב׃","ẕĕʼ֣ẇ mi⁠bá̇bel֮ bi̇rĕẖ֣ẇ mi⁠kȧşĕ̂di̇ym֒ bĕ̇⁠q֣wòl riná̇֗h hagi֤̇ydẇ haşĕ̌mi֨yʻẇ֙ zò֔ʼţ hwòẕiyʼ֖ẇ⁠há ʻad-qĕẕé֣h há⁠ʼá֑reẕ ʼimĕr֕ẇ gá̇ʼa֥l yĕhwá֖h ʻabĕḋ֥⁠wò yaʻàqòֽb׃"],[48,21,"וְ⁠לֹ֣א צָמְא֗וּ בָּ⁠חֳרָבוֹת֙ הֽוֹלִיכָ֔⁠ם מַ֥יִם מִ⁠צּ֖וּר הִזִּ֣יל לָ֑⁠מוֹ וַ⁠יִּ֨בְקַע־צ֔וּר וַ⁠יָּזֻ֖בוּ מָֽיִם׃","wĕ⁠lò֣ʼ ẕámĕʼ֗ẇ bá̇⁠ẖorábwòţ֙ hֽwòliyká֔⁠m ma֥yim mi⁠ẕ֖̇ẇr hizi֣̇yl lá֑⁠mwò wa⁠yi̇֨bĕqaʻ-ẕ֔ẇr wa⁠yá̇zu֖bẇ máֽyim׃"],[48,22,"אֵ֣ין שָׁל֔וֹם אָמַ֥ר יְהוָ֖ה לָ⁠רְשָׁעִֽים׃ס","ʼé֣yn şá̌l֔wòm ʼáma֥r yĕhwá֖h lá⁠rĕşá̌ʻiֽym׃s"],[49,1,"שִׁמְע֤וּ אִיִּים֙ אֵלַ֔⁠י וְ⁠הַקְשִׁ֥יבוּ לְאֻמִּ֖ים מֵ⁠רָח֑וֹק יְהוָה֙ מִ⁠בֶּ֣טֶן קְרָאָ֔⁠נִי מִ⁠מְּעֵ֥י אִמִּ֖⁠י הִזְכִּ֥יר שְׁמִֽ⁠י׃","şǐmĕʻ֤ẇ ʼiyi̇ym֙ ʼéla֔⁠y wĕ⁠haqĕşǐ֥ybẇ lĕʼumi֖̇ym mé⁠ráẖ֑wòq yĕhwáh֙ mi⁠bė֣ten qĕráʼá֔⁠niy mi⁠mĕ̇ʻé֥y ʼimi֖̇⁠y hizĕki֥̇yr şĕ̌miֽ⁠y׃"],[49,2,"וַ⁠יָּ֤שֶׂם פִּ⁠י֙ כְּ⁠חֶ֣רֶב חַדָּ֔ה בְּ⁠צֵ֥ל יָד֖⁠וֹ הֶחְבִּיאָ֑⁠נִי וַ⁠יְשִׂימֵ֨⁠נִי֙ לְ⁠חֵ֣ץ בָּר֔וּר בְּ⁠אַשְׁפָּת֖⁠וֹ הִסְתִּירָֽ⁠נִי׃","wa⁠yá֤̇şêm pi̇⁠y֙ kĕ̇⁠ẖe֣reb ẖadá̇֔h bĕ̇⁠ẕé֥l yád֖⁠wò heẖĕbi̇yʼá֑⁠niy wa⁠yĕşîymé֨⁠niy֙ lĕ⁠ẖé֣ẕ bá̇r֔ẇr bĕ̇⁠ʼaşĕ̌pá̇ţ֖⁠wò hisĕţi̇yráֽ⁠niy׃"],[49,3,"וַ⁠יֹּ֥אמֶר לִ֖⁠י עַבְדִּ⁠י־אָ֑תָּה יִשְׂרָאֵ֕ל אֲשֶׁר־בְּ⁠ךָ֖ אֶתְפָּאָֽר׃","wa⁠yò֥̇ʼmer li֖⁠y ʻabĕdi̇⁠y-ʼá֑ţá̇h yişĕ̂ráʼé֕l ʼàşěr-bĕ̇⁠ká֖ ʼeţĕpá̇ʼáֽr׃"],[49,4,"וַ⁠אֲנִ֤י אָמַ֨רְתִּי֙ לְ⁠רִ֣יק יָגַ֔עְתִּי לְ⁠תֹ֥הוּ וְ⁠הֶ֖בֶל כֹּחִ֣⁠י כִלֵּ֑יתִי אָכֵן֙ מִשְׁפָּטִ֣⁠י אֶת־יְהוָ֔ה וּ⁠פְעֻלָּתִ֖⁠י אֶת־אֱלֹהָֽ⁠י׃","wa⁠ʼàni֤y ʼáma֨rĕţi̇y֙ lĕ⁠ri֣yq yága֔ʻĕţi̇y lĕ⁠ţò֥hẇ wĕ⁠he֖bel kò̇ẖi֣⁠y kilé֑̇yţiy ʼákén֙ mişĕ̌pá̇ti֣⁠y ʼeţ-yĕhwá֔h ẇ⁠pĕʻulá̇ţi֖⁠y ʼeţ-ʼèlòháֽ⁠y׃"],[49,5,"וְ⁠עַתָּ֣ה ׀ אָמַ֣ר יְהוָ֗ה יֹצְרִ֤⁠י מִ⁠בֶּ֨טֶן֙ לְ⁠עֶ֣בֶד ל֔⁠וֹ לְ⁠שׁוֹבֵ֤ב יַֽעֲקֹב֙ אֵלָ֔י⁠ו וְ⁠יִשְׂרָאֵ֖ל לא יֵאָסֵ֑ף וְ⁠אֶכָּבֵד֙ בְּ⁠עֵינֵ֣י יְהוָ֔ה וֵ⁠אלֹהַ֖⁠י הָיָ֥ה עֻזִּֽ⁠י׃","wĕ⁠ʻaţá֣̇h ׀ ʼáma֣r yĕhwá֗h yòẕĕri֤⁠y mi⁠bė֨ten֙ lĕ⁠ʻe֣bed l֔⁠wò lĕ⁠ş̌wòbé֤b yaֽʻàqòb֙ ʼélá֔y⁠w wĕ⁠yişĕ̂ráʼé֖l lʼ yéʼásé֑p wĕ⁠ʼeká̇béd֙ bĕ̇⁠ʻéyné֣y yĕhwá֔h wé⁠ʼlòha֖⁠y háyá֥h ʻuziֽ̇⁠y׃"],[49,6,"וַ⁠יֹּ֗אמֶר נָקֵ֨ל מִֽ⁠הְיוֹתְ⁠ךָ֥ לִ⁠י֙ עֶ֔בֶד לְ⁠הָקִים֙ אֶת־שִׁבְטֵ֣י יַעֲקֹ֔ב ו⁠נצירי יִשְׂרָאֵ֖ל לְ⁠הָשִׁ֑יב וּ⁠נְתַתִּ֨י⁠ךָ֙ לְ⁠א֣וֹר גּוֹיִ֔ם לִֽ⁠הְי֥וֹת יְשׁוּעָתִ֖⁠י עַד־קְצֵ֥ה הָ⁠אָֽרֶץ׃ס","wa⁠yò̇֗ʼmer náqé֨l miֽ⁠hĕywòţĕ⁠ká֥ li⁠y֙ ʻe֔bed lĕ⁠háqiym֙ ʼeţ-şǐbĕté֣y yaʻàqò֔b w⁠nẕyry yişĕ̂ráʼé֖l lĕ⁠háşǐ֑yb ẇ⁠nĕţaţi̇֨y⁠ká֙ lĕ⁠ʼ֣wòr ġwòyi֔m liֽ⁠hĕy֥wòţ yĕş̌ẇʻáţi֖⁠y ʻad-qĕẕé֥h há⁠ʼáֽreẕ׃s"],[49,7,"כֹּ֣ה אָֽמַר־יְהוָה֩ גֹּאֵ֨ל יִשְׂרָאֵ֜ל קְדוֹשׁ֗⁠וֹ לִ⁠בְזֹה־נֶ֜פֶשׁ לִ⁠מְתָ֤עֵֽב גּוֹי֙ לְ⁠עֶ֣בֶד מֹשְׁלִ֔ים מְלָכִים֙ יִרְא֣וּ וָ⁠קָ֔מוּ שָׂרִ֖ים וְ⁠יִֽשְׁתַּחֲוּ֑וּ לְמַ֤עַן יְהוָה֙ אֲשֶׁ֣ר נֶאֱמָ֔ן קְדֹ֥שׁ יִשְׂרָאֵ֖ל וַ⁠יִּבְחָרֶֽ⁠ךָּ׃","kò֣̇h ʼáֽmar-yĕhwáh֩ gò̇ʼé֨l yişĕ̂ráʼé֜l qĕdwòş̌֗⁠wò li⁠bĕzòh-ne֜peş̌ li⁠mĕţá֤ʻéֽb ġwòy֙ lĕ⁠ʻe֣bed mòşĕ̌li֔ym mĕlákiym֙ yirĕʼ֣ẇ wá⁠qá֔mẇ şá̂ri֖ym wĕ⁠yiֽşĕ̌ţȧẖàẇ֑ẇ lĕma֤ʻan yĕhwáh֙ ʼàşě֣r neʼèmá֔n qĕdò֥ş̌ yişĕ̂ráʼé֖l wa⁠yi̇bĕẖáreֽ⁠ká̇׃"],[49,8,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה בְּ⁠עֵ֤ת רָצוֹן֙ עֲנִיתִ֔י⁠ךָ וּ⁠בְ⁠י֥וֹם יְשׁוּעָ֖ה עֲזַרְתִּ֑י⁠ךָ וְ⁠אֶצָּרְ⁠ךָ֗ וְ⁠אֶתֶּנְ⁠ךָ֙ לִ⁠בְרִ֣ית עָ֔ם לְ⁠הָקִ֣ים אֶ֔רֶץ לְ⁠הַנְחִ֖יל נְחָל֥וֹת שֹׁמֵמֽוֹת׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h bĕ̇⁠ʻé֤ţ ráẕwòn֙ ʻàniyţi֔y⁠ká ẇ⁠bĕ⁠y֥wòm yĕş̌ẇʻá֖h ʻàzarĕţi֑̇y⁠ká wĕ⁠ʼeẕá̇rĕ⁠ká֗ wĕ⁠ʼeţėnĕ⁠ká֙ li⁠bĕri֣yţ ʻá֔m lĕ⁠háqi֣ym ʼe֔reẕ lĕ⁠hanĕẖi֖yl nĕẖál֥wòţ şò̌mémֽwòţ׃"],[49,9,"לֵ⁠אמֹ֤ר לַֽ⁠אֲסוּרִים֙ צֵ֔אוּ לַ⁠אֲשֶׁ֥ר בַּ⁠חֹ֖שֶׁךְ הִגָּל֑וּ עַל־דְּרָכִ֣ים יִרְע֔וּ וּ⁠בְ⁠כָל־שְׁפָיִ֖ים מַרְעִיתָֽ⁠ם׃","lé⁠ʼmò֤r laֽ⁠ʼàsẇriym֙ ẕé֔ʼẇ la⁠ʼàşě֥r bȧ⁠ẖò֖şěkĕ higá̇l֑ẇ ʻal-dĕ̇ráki֣ym yirĕʻ֔ẇ ẇ⁠bĕ⁠kál-şĕ̌páyi֖ym marĕʻiyţáֽ⁠m׃"],[49,10,"לֹ֤א יִרְעָ֨בוּ֙ וְ⁠לֹ֣א יִצְמָ֔אוּ וְ⁠לֹא־יַכֵּ֥⁠ם שָׁרָ֖ב וָ⁠שָׁ֑מֶשׁ כִּי־מְרַחֲמָ֣⁠ם יְנַהֲגֵ֔⁠ם וְ⁠עַל־מַבּ֥וּעֵי מַ֖יִם יְנַהֲלֵֽ⁠ם׃","lò֤ʼ yirĕʻá֨bẇ֙ wĕ⁠lò֣ʼ yiẕĕmá֔ʼẇ wĕ⁠lòʼ-yaké֥̇⁠m şá̌rá֖b wá⁠şá֑̌meş̌ ki̇y-mĕraẖàmá֣⁠m yĕnahàgé֔⁠m wĕ⁠ʻal-maḃ֥ẇʻéy ma֖yim yĕnahàléֽ⁠m׃"],[49,11,"וְ⁠שַׂמְתִּ֥י כָל־הָרַ֖⁠י לַ⁠דָּ֑רֶךְ וּ⁠מְסִלֹּתַ֖⁠י יְרֻמֽוּ⁠ן׃","wĕ⁠şâmĕţi֥̇y kál-hára֖⁠y la⁠dá֑̇rekĕ ẇ⁠mĕsilò̇ţa֖⁠y yĕrumֽẇ⁠n׃"],[49,12,"הִנֵּה־אֵ֕לֶּה מֵ⁠רָח֖וֹק יָבֹ֑אוּ וְ⁠הִֽנֵּה־אֵ֨לֶּה֙ מִ⁠צָּפ֣וֹן וּ⁠מִ⁠יָּ֔ם וְ⁠אֵ֖לֶּה מֵ⁠אֶ֥רֶץ סִינִֽים׃","hiné̇h-ʼé֕lėh mé⁠ráẖ֖wòq yábò֑ʼẇ wĕ⁠hiֽné̇h-ʼé֨lėh֙ mi⁠ẕá̇p֣wòn ẇ⁠mi⁠yá̇֔m wĕ⁠ʼé֖lėh mé⁠ʼe֥reẕ siyniֽym׃"],[49,13,"רָנּ֤וּ שָׁמַ֨יִם֙ וְ⁠גִ֣ילִי אָ֔רֶץ יפצחו הָרִ֖ים רִנָּ֑ה כִּֽי־נִחַ֤ם יְהוָה֙ עַמּ֔⁠וֹ וַ⁠עֲנִיָּ֖⁠ו יְרַחֵֽם׃ס","ráṅ֤ẇ şá̌ma֨yim֙ wĕ⁠gi֣yliy ʼá֔reẕ ypẕẖw hári֖ym riná֑̇h kiֽ̇y-niẖa֤m yĕhwáh֙ ʻaṁ֔⁠wò wa⁠ʻàniyá֖̇⁠w yĕraẖéֽm׃s"],[49,14,"וַ⁠תֹּ֥אמֶר צִיּ֖וֹן עֲזָבַ֣⁠נִי יְהוָ֑ה וַ⁠אדֹנָ֖⁠י שְׁכֵחָֽ⁠נִי׃","wa⁠ţò֥̇ʼmer ẕiẏ֖wòn ʻàzába֣⁠niy yĕhwá֑h wa⁠ʼdòná֖⁠y şĕ̌kéẖáֽ⁠niy׃"],[49,15,"הֲ⁠תִשְׁכַּ֤ח אִשָּׁה֙ עוּלָ֔⁠הּ מֵ⁠רַחֵ֖ם בֶּן־בִּטְנָ֑⁠הּ גַּם־אֵ֣לֶּה תִשְׁכַּ֔חְנָה וְ⁠אָנֹכִ֖י לֹ֥א אֶשְׁכָּחֵֽ⁠ךְ׃","hà⁠ţişĕ̌kȧ֤ẖ ʼişá̇̌h֙ ʻẇlá֔⁠ḣ mé⁠raẖé֖m bėn-bi̇tĕná֑⁠ḣ gȧm-ʼé֣lėh ţişĕ̌kȧ֔ẖĕnáh wĕ⁠ʼánòki֖y lò֥ʼ ʼeşĕ̌ká̇ẖéֽ⁠kĕ׃"],[49,16,"הֵ֥ן עַל־כַּפַּ֖יִם חַקֹּתִ֑י⁠ךְ חוֹמֹתַ֥יִ⁠ךְ נֶגְדִּ֖⁠י תָּמִֽיד׃","hé֥n ʻal-kȧpȧ֖yim ẖaqò̇ţi֑y⁠kĕ ẖwòmòţa֥yi⁠kĕ negĕdi֖̇⁠y ţá̇miֽyd׃"],[49,17,"מִֽהֲר֖וּ בָּנָ֑יִ⁠ךְ מְהָֽרְסַ֥יִ⁠ךְ וּ⁠מַחֲרִבַ֖יִ⁠ךְ מִמֵּ֥⁠ךְ יֵצֵֽאוּ׃","miֽhàr֖ẇ bá̇ná֑yi⁠kĕ mĕháֽrĕsa֥yi⁠kĕ ẇ⁠maẖàriba֖yi⁠kĕ mimé֥̇⁠kĕ yéẕéֽʼẇ׃"],[49,18,"שְׂאִֽי־סָבִ֤יב עֵינַ֨יִ⁠ךְ֙ וּ⁠רְאִ֔י כֻּלָּ֖⁠ם נִקְבְּצ֣וּ בָֽאוּ־לָ֑⁠ךְ חַי־אָ֣נִי נְאֻם־יְהוָ֗ה כִּ֤י כֻלָּ⁠ם֙ כָּ⁠עֲדִ֣י תִלְבָּ֔שִׁי וּֽ⁠תְקַשְּׁרִ֖י⁠ם כַּ⁠כַּלָּֽה׃","şĕ̂ʼiֽy-sábi֤yb ʻéyna֨yi⁠kĕ֙ ẇ⁠rĕʼi֔y ku̇lá֖̇⁠m niqĕbĕ̇ẕ֣ẇ báֽʼẇ-lá֑⁠kĕ ẖay-ʼá֣niy nĕʼum-yĕhwá֗h ki֤̇y kulá̇⁠m֙ ká̇⁠ʻàdi֣y ţilĕbá̇֔şǐy ẇֽ⁠ţĕqaşĕ̇̌ri֖y⁠m kȧ⁠kȧláֽ̇h׃"],[49,19,"כִּ֤י חָרְבֹתַ֨יִ⁠ךְ֙ וְ⁠שֹׁ֣מְמֹתַ֔יִ⁠ךְ וְ⁠אֶ֖רֶץ הֲרִֽסֻתֵ֑י⁠ךְ כִּ֤י עַתָּה֙ תֵּצְרִ֣י מִ⁠יּוֹשֵׁ֔ב וְ⁠רָחֲק֖וּ מְבַלְּעָֽיִ⁠ךְ׃","ki֤̇y ẖárĕbòţa֨yi⁠kĕ֙ wĕ⁠şò֣̌mĕmòţa֔yi⁠kĕ wĕ⁠ʼe֖reẕ hàriֽsuţé֑y⁠kĕ ki֤̇y ʻaţá̇h֙ ţé̇ẕĕri֣y mi⁠ẏwòşé̌֔b wĕ⁠ráẖàq֖ẇ mĕbalĕ̇ʻáֽyi⁠kĕ׃"],[49,20,"ע֚וֹד יֹאמְר֣וּ בְ⁠אָזְנַ֔יִ⁠ךְ בְּנֵ֖י שִׁכֻּלָ֑יִ⁠ךְ צַר־לִ֥⁠י הַ⁠מָּק֖וֹם גְּשָׁ⁠ה־לִּ֥⁠י וְ⁠אֵשֵֽׁבָה׃","ʻ֚wòd yòʼmĕr֣ẇ bĕ⁠ʼázĕna֔yi⁠kĕ bĕ̇né֖y şǐku̇lá֑yi⁠kĕ ẕar-li֥⁠y ha⁠má̇q֖wòm gĕ̇şá̌⁠h-li֥̇⁠y wĕ⁠ʼéşéֽ̌báh׃"],[49,21,"וְ⁠אָמַ֣רְתְּ בִּ⁠לְבָבֵ֗⁠ךְ מִ֤י יָֽלַד־לִ⁠י֙ אֶת־אֵ֔לֶּה וַ⁠אֲנִ֥י שְׁכוּלָ֖ה וְ⁠גַלְמוּדָ֑ה גֹּלָ֣ה ׀ וְ⁠סוּרָ֗ה וְ⁠אֵ֨לֶּה֙ מִ֣י גִדֵּ֔ל הֵ֤ן אֲנִי֙ נִשְׁאַ֣רְתִּי לְ⁠בַדִּ֔⁠י אֵ֖לֶּה אֵיפֹ֥ה הֵֽם׃פ","wĕ⁠ʼáma֣rĕţĕ̇ bi̇⁠lĕbábé֗⁠kĕ mi֤y yáֽlad-li⁠y֙ ʼeţ-ʼé֔lėh wa⁠ʼàni֥y şĕ̌kẇlá֖h wĕ⁠galĕmẇdá֑h gò̇lá֣h ׀ wĕ⁠sẇrá֗h wĕ⁠ʼé֨lėh֙ mi֣y gidé̇֔l hé֤n ʼàniy֙ nişĕ̌ʼa֣rĕţi̇y lĕ⁠badi̇֔⁠y ʼé֖lėh ʼéypò֥h héֽm׃p"],[49,22,"כֹּֽה־אָמַ֞ר אֲדֹנָ֣⁠י יְהוִ֗ה הִנֵּ֨ה אֶשָּׂ֤א אֶל־גּוֹיִם֙ יָדִ֔⁠י וְ⁠אֶל־עַמִּ֖ים אָרִ֣ים נִסִּ֑⁠י וְ⁠הֵבִ֤יאוּ בָנַ֨יִ⁠ךְ֙ בְּ⁠חֹ֔צֶן וּ⁠בְנֹתַ֖יִ⁠ךְ עַל־כָּתֵ֥ף תִּנָּשֶֽׂאנָה׃","kòֽ̇h-ʼáma֞r ʼàdòná֣⁠y yĕhwi֗h hiné̇֨h ʼeşá֤̇̂ʼ ʼel-ġwòyim֙ yádi֔⁠y wĕ⁠ʼel-ʻami֖̇ym ʼári֣ym nisi֑̇⁠y wĕ⁠hébi֤yʼẇ bána֨yi⁠kĕ֙ bĕ̇⁠ẖò֔ẕen ẇ⁠bĕnòţa֖yi⁠kĕ ʻal-ká̇ţé֥p ţi̇ná̇şêֽʼnáh׃"],[49,23,"וְ⁠הָי֨וּ מְלָכִ֜ים אֹֽמְנַ֗יִ⁠ךְ וְ⁠שָׂרֽוֹתֵי⁠הֶם֙ מֵינִ֣יקֹתַ֔יִ⁠ךְ אַפַּ֗יִם אֶ֚רֶץ יִשְׁתַּ֣חֲווּ לָ֔⁠ךְ וַ⁠עֲפַ֥ר רַגְלַ֖יִ⁠ךְ יְלַחֵ֑כוּ וְ⁠יָדַ֨עַתְּ֙ כִּֽי־אֲנִ֣י יְהוָ֔ה אֲשֶׁ֥ר לֹֽא־יֵבֹ֖שׁוּ קוָֹֽ⁠י׃ס","wĕ⁠háy֨ẇ mĕláki֜ym ʼòֽmĕna֗yi⁠kĕ wĕ⁠şá̂rֽwòţéy⁠hem֙ méyni֣yqòţa֔yi⁠kĕ ʼapȧ֗yim ʼe֚reẕ yişĕ̌ţȧ֣ẖàwẇ lá֔⁠kĕ wa⁠ʻàpa֥r ragĕla֖yi⁠kĕ yĕlaẖé֑kẇ wĕ⁠yáda֨ʻaţĕ̇֙ kiֽ̇y-ʼàni֣y yĕhwá֔h ʼàşě֥r lòֽʼ-yébò֖ş̌ẇ qwáòֽ⁠y׃s"],[49,24,"הֲ⁠יֻקַּ֥ח מִ⁠גִּבּ֖וֹר מַלְק֑וֹחַ וְ⁠אִם־שְׁבִ֥י צַדִּ֖יק יִמָּלֵֽט׃","hà⁠yuqȧ֥ẖ mi⁠gi̇ḃ֖wòr malĕq֑wòẖa wĕ⁠ʼim-şĕ̌bi֥y ẕadi֖̇yq yimá̇léֽt׃"],[49,25,"כִּי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה גַּם־שְׁבִ֤י גִבּוֹר֙ יֻקָּ֔ח וּ⁠מַלְק֥וֹחַ עָרִ֖יץ יִמָּלֵ֑ט וְ⁠אֶת־יְרִיבֵ⁠ךְ֙ אָנֹכִ֣י אָרִ֔יב וְ⁠אֶת־בָּנַ֖יִ⁠ךְ אָנֹכִ֥י אוֹשִֽׁיעַ׃","ki̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h gȧm-şĕ̌bi֤y giḃwòr֙ yuqá̇֔ẖ ẇ⁠malĕq֥wòẖa ʻári֖yẕ yimá̇lé֑t wĕ⁠ʼeţ-yĕriybé⁠kĕ֙ ʼánòki֣y ʼári֔yb wĕ⁠ʼeţ-bá̇na֖yi⁠kĕ ʼánòki֥y ʼwòşǐֽyʻa׃"],[49,26,"וְ⁠הַאֲכַלְתִּ֤י אֶת־מוֹנַ֨יִ⁠ךְ֙ אֶת־בְּשָׂרָ֔⁠ם וְ⁠כֶ⁠עָסִ֖יס דָּמָ֣⁠ם יִשְׁכָּר֑וּ⁠ן וְ⁠יָדְע֣וּ כָל־בָּשָׂ֗ר כִּ֣י אֲנִ֤י יְהוָה֙ מֽוֹשִׁיעֵ֔⁠ךְ וְ⁠גֹאֲלֵ֖⁠ךְ אֲבִ֥יר יַעֲקֹֽב׃ס","wĕ⁠haʼàkalĕţi֤̇y ʼeţ-mwòna֨yi⁠kĕ֙ ʼeţ-bĕ̇şá̂rá֔⁠m wĕ⁠ke⁠ʻási֖ys dá̇má֣⁠m yişĕ̌ká̇r֑ẇ⁠n wĕ⁠yádĕʻ֣ẇ kál-bá̇şá̂֗r ki֣̇y ʼàni֤y yĕhwáh֙ mֽwòşǐyʻé֔⁠kĕ wĕ⁠gòʼàlé֖⁠kĕ ʼàbi֥yr yaʻàqòֽb׃s"],[50,1,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה אֵ֣י זֶ֠ה סֵ֣פֶר כְּרִית֤וּת אִמְּ⁠כֶם֙ אֲשֶׁ֣ר שִׁלַּחְתִּ֔י⁠הָ א֚וֹ מִ֣י מִ⁠נּוֹשַׁ֔⁠י אֲשֶׁר־מָכַ֥רְתִּי אֶתְ⁠כֶ֖ם ל֑⁠וֹ הֵ֤ן בַּ⁠עֲוֺנֹֽתֵי⁠כֶם֙ נִמְכַּרְתֶּ֔ם וּ⁠בְ⁠פִשְׁעֵי⁠כֶ֖ם שֻׁלְּחָ֥ה אִמְּ⁠כֶֽם׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h ʼé֣y ze֠h sé֣per kĕ̇riyţ֤ẇţ ʼimĕ̇⁠kem֙ ʼàşě֣r şǐlȧẖĕţi̇֔y⁠há ʼ֚wò mi֣y mi⁠ṅwòşǎ֔⁠y ʼàşěr-máka֥rĕţi̇y ʼeţĕ⁠ke֖m l֑⁠wò hé֤n bȧ⁠ʻàwֺnòֽţéy⁠kem֙ nimĕkȧrĕţė֔m ẇ⁠bĕ⁠pişĕ̌ʻéy⁠ke֖m şǔlĕ̇ẖá֥h ʼimĕ̇⁠keֽm׃"],[50,2,"מַדּ֨וּעַ בָּ֜אתִי וְ⁠אֵ֣ין אִ֗ישׁ קָרָֽאתִי֮ וְ⁠אֵ֣ין עוֹנֶה֒ הֲ⁠קָצ֨וֹר קָצְרָ֤ה יָדִ⁠י֙ מִ⁠פְּד֔וּת וְ⁠אִם־אֵֽין־בִּ֥⁠י כֹ֖חַ לְ⁠הַצִּ֑יל הֵ֣ן בְּ⁠גַעֲרָתִ֞⁠י אַחֲרִ֣יב יָ֗ם אָשִׂ֤ים נְהָרוֹת֙ מִדְבָּ֔ר תִּבְאַ֤שׁ דְּגָתָ⁠ם֙ מֵ⁠אֵ֣ין מַ֔יִם וְ⁠תָמֹ֖ת בַּ⁠צָּמָֽא׃","maḋ֨ẇʻa bá̇֜ʼţiy wĕ⁠ʼé֣yn ʼi֗yş̌ qáráֽʼţiy֮ wĕ⁠ʼé֣yn ʻwòneh֒ hà⁠qáẕ֨wòr qáẕĕrá֤h yádi⁠y֙ mi⁠pĕ̇d֔ẇţ wĕ⁠ʼim-ʼéֽyn-bi֥̇⁠y kò֖ẖa lĕ⁠haẕi֑̇yl hé֣n bĕ̇⁠gaʻàráţi֞⁠y ʼaẖàri֣yb yá֗m ʼáşî֤ym nĕhárwòţ֙ midĕbá̇֔r ţi̇bĕʼa֤ş̌ dĕ̇gáţá⁠m֙ mé⁠ʼé֣yn ma֔yim wĕ⁠ţámò֖ţ bȧ⁠ẕá̇máֽʼ׃"],[50,3,"אַלְבִּ֥ישׁ שָׁמַ֖יִם קַדְר֑וּת וְ⁠שַׂ֖ק אָשִׂ֥ים כְּסוּתָֽ⁠ם׃ס","ʼalĕbi֥̇yş̌ şá̌ma֖yim qadĕr֑ẇţ wĕ⁠şâ֖q ʼáşî֥ym kĕ̇sẇţáֽ⁠m׃s"],[50,4,"אֲדֹנָ֣⁠י יְהֹוִ֗ה נָ֤תַן לִ⁠י֙ לְשׁ֣וֹן לִמּוּדִ֔ים לָ⁠דַ֛עַת לָ⁠ע֥וּת אֶת־יָעֵ֖ף דָּבָ֑ר יָעִ֣יר ׀ בַּ⁠בֹּ֣קֶר בַּ⁠בֹּ֗קֶר יָעִ֥יר לִ⁠י֙ אֹ֔זֶן לִ⁠שְׁמֹ֖עַ כַּ⁠לִּמּוּדִֽים׃","ʼàdòná֣⁠y yĕhòwi֗h ná֤ţan li⁠y֙ lĕş֣̌wòn liṁẇdi֔ym lá⁠da֛ʻaţ lá⁠ʻ֥ẇţ ʼeţ-yáʻé֖p dá̇bá֑r yáʻi֣yr ׀ bȧ⁠bò֣̇qer bȧ⁠bò̇֗qer yáʻi֥yr li⁠y֙ ʼò֔zen li⁠şĕ̌mò֖ʻa kȧ⁠li̇ṁẇdiֽym׃"],[50,5,"אֲדֹנָ֤⁠י יְהוִה֙ פָּתַֽח־לִ֣⁠י אֹ֔זֶן וְ⁠אָנֹכִ֖י לֹ֣א מָרִ֑יתִי אָח֖וֹר לֹ֥א נְסוּגֹֽתִי׃","ʼàdòná֤⁠y yĕhwih֙ pá̇ţaֽẖ-li֣⁠y ʼò֔zen wĕ⁠ʼánòki֖y lò֣ʼ mári֑yţiy ʼáẖ֖wòr lò֥ʼ nĕsẇgòֽţiy׃"],[50,6,"גֵּוִ⁠י֙ נָתַ֣תִּי לְ⁠מַכִּ֔ים וּ⁠לְחָיַ֖⁠י לְ⁠מֹֽרְטִ֑ים פָּנַ⁠י֙ לֹ֣א הִסְתַּ֔רְתִּי מִ⁠כְּלִמּ֖וֹת וָ⁠רֹֽק׃","gé̇wi⁠y֙ náţa֣ţi̇y lĕ⁠maki̇֔ym ẇ⁠lĕẖáya֖⁠y lĕ⁠mòֽrĕti֑ym pá̇na⁠y֙ lò֣ʼ hisĕţȧ֔rĕţi̇y mi⁠kĕ̇liṁ֖wòţ wá⁠ròֽq׃"],[50,7,"וַ⁠אדֹנָ֤⁠י יְהוִה֙ יַֽעֲזָר־לִ֔⁠י עַל־כֵּ֖ן לֹ֣א נִכְלָ֑מְתִּי עַל־כֵּ֞ן שַׂ֤מְתִּי פָנַ⁠י֙ כַּֽ⁠חַלָּמִ֔ישׁ וָ⁠אֵדַ֖ע כִּי־לֹ֥א אֵבֽוֹשׁ׃","wa⁠ʼdòná֤⁠y yĕhwih֙ yaֽʻàzár-li֔⁠y ʻal-ké֖̇n lò֣ʼ nikĕlá֑mĕţi̇y ʻal-ké̇֞n şâ֤mĕţi̇y pána⁠y֙ kȧֽ⁠ẖalá̇mi֔yş̌ wá⁠ʼéda֖ʻ ki̇y-lò֥ʼ ʼébֽwòş̌׃"],[50,8,"קָרוֹב֙ מַצְדִּיקִ֔⁠י מִֽי־יָרִ֥יב אִתִּ֖⁠י נַ֣עַמְדָה יָּ֑חַד מִֽי־בַ֥עַל מִשְׁפָּטִ֖⁠י יִגַּ֥שׁ אֵלָֽ⁠י׃","qárwòb֙ maẕĕdi̇yqi֔⁠y miֽy-yári֥yb ʼiţi֖̇⁠y na֣ʻamĕdáh yá֑̇ẖad miֽy-ba֥ʻal mişĕ̌pá̇ti֖⁠y yigȧ֥ş̌ ʼéláֽ⁠y׃"],[50,9,"הֵ֣ן אֲדֹנָ֤⁠י יְהוִה֙ יַֽעֲזָר־לִ֔⁠י מִי־ה֖וּא יַרְשִׁיעֵ֑⁠נִי הֵ֤ן כֻּלָּ⁠ם֙ כַּ⁠בֶּ֣גֶד יִבְל֔וּ עָ֖שׁ יֹאכְלֵֽ⁠ם׃","hé֣n ʼàdòná֤⁠y yĕhwih֙ yaֽʻàzár-li֔⁠y miy-h֖ẇʼ yarĕşǐyʻé֑⁠niy hé֤n ku̇lá̇⁠m֙ kȧ⁠bė֣ged yibĕl֔ẇ ʻá֖ş̌ yòʼkĕléֽ⁠m׃"],[50,10,"מִ֤י בָ⁠כֶם֙ יְרֵ֣א יְהוָ֔ה שֹׁמֵ֖עַ בְּ⁠ק֣וֹל עַבְדּ֑⁠וֹ אֲשֶׁ֣ר ׀ הָלַ֣ךְ חֲשֵׁכִ֗ים וְ⁠אֵ֥ין נֹ֨גַהּ֙ ל֔⁠וֹ יִבְטַח֙ בְּ⁠שֵׁ֣ם יְהוָ֔ה וְ⁠יִשָּׁעֵ֖ן בֵּ⁠אלֹהָֽי⁠ו׃","mi֤y bá⁠kem֙ yĕré֣ʼ yĕhwá֔h şò̌mé֖ʻa bĕ̇⁠q֣wòl ʻabĕḋ֑⁠wò ʼàşě֣r ׀ hála֣kĕ ẖàşé̌ki֗ym wĕ⁠ʼé֥yn nò֨gaḣ֙ l֔⁠wò yibĕtaẖ֙ bĕ̇⁠şé֣̌m yĕhwá֔h wĕ⁠yişá̇̌ʻé֖n bé̇⁠ʼlòháֽy⁠w׃"],[50,11,"הֵ֧ן כֻּלְּ⁠כֶ֛ם קֹ֥דְחֵי אֵ֖שׁ מְאַזְּרֵ֣י זִיק֑וֹת לְכ֣וּ ׀ בְּ⁠א֣וּר אֶשְׁ⁠כֶ֗ם וּ⁠בְ⁠זִיקוֹת֙ בִּֽעַרְתֶּ֔ם מִ⁠יָּדִ⁠י֙ הָיְתָה־זֹּ֣את לָ⁠כֶ֔ם לְ⁠מַעֲצֵבָ֖ה תִּשְׁכָּבֽוּ⁠ן׃פ","hé֧n ku̇lĕ̇⁠ke֛m qò֥dĕẖéy ʼé֖ş̌ mĕʼazĕ̇ré֣y ziyq֑wòţ lĕk֣ẇ ׀ bĕ̇⁠ʼ֣ẇr ʼeşĕ̌⁠ke֗m ẇ⁠bĕ⁠ziyqwòţ֙ biֽ̇ʻarĕţė֔m mi⁠yá̇di⁠y֙ háyĕţáh-zò֣̇ʼţ lá⁠ke֔m lĕ⁠maʻàẕébá֖h ţi̇şĕ̌ká̇bֽẇ⁠n׃p"],[51,1,"שִׁמְע֥וּ אֵלַ֛⁠י רֹ֥דְפֵי צֶ֖דֶק מְבַקְשֵׁ֣י יְהוָ֑ה הַבִּ֨יטוּ֙ אֶל־צ֣וּר חֻצַּבְתֶּ֔ם וְ⁠אֶל־מַקֶּ֥בֶת בּ֖וֹר נֻקַּרְתֶּֽם׃","şǐmĕʻ֥ẇ ʼéla֛⁠y rò֥dĕpéy ẕe֖deq mĕbaqĕşé֣̌y yĕhwá֑h habi̇֨ytẇ֙ ʼel-ẕ֣ẇr ẖuẕȧbĕţė֔m wĕ⁠ʼel-maqė֥beţ ḃ֖wòr nuqȧrĕţėֽm׃"],[51,2,"הַבִּ֨יטוּ֙ אֶל־אַבְרָהָ֣ם אֲבִי⁠כֶ֔ם וְ⁠אֶל־שָׂרָ֖ה תְּחוֹלֶלְ⁠כֶ֑ם כִּי־אֶחָ֣ד קְרָאתִ֔י⁠ו וַ⁠אֲבָרְכֵ֖⁠הוּ וְ⁠אַרְבֵּֽ⁠הוּ׃ס","habi̇֨ytẇ֙ ʼel-ʼabĕráhá֣m ʼàbiy⁠ke֔m wĕ⁠ʼel-şá̂rá֖h ţĕ̇ẖwòlelĕ⁠ke֑m ki̇y-ʼeẖá֣d qĕráʼţi֔y⁠w wa⁠ʼàbárĕké֖⁠hẇ wĕ⁠ʼarĕbéֽ̇⁠hẇ׃s"],[51,3,"כִּֽי־נִחַ֨ם יְהוָ֜ה צִיּ֗וֹן נִחַם֙ כָּל־חָרְבֹתֶ֔י⁠הָ וַ⁠יָּ֤שֶׂם מִדְבָּרָ⁠הּ֙ כְּ⁠עֵ֔דֶן וְ⁠עַרְבָתָ֖⁠הּ כְּ⁠גַן־יְהוָ֑ה שָׂשׂ֤וֹן וְ⁠שִׂמְחָה֙ יִמָּ֣צֵא בָ֔⁠הּ תּוֹדָ֖ה וְ⁠ק֥וֹל זִמְרָֽה׃ס","kiֽ̇y-niẖa֨m yĕhwá֜h ẕiẏ֗wòn niẖam֙ ká̇l-ẖárĕbòţe֔y⁠há wa⁠yá֤̇şêm midĕbá̇rá⁠ḣ֙ kĕ̇⁠ʻé֔den wĕ⁠ʻarĕbáţá֖⁠ḣ kĕ̇⁠gan-yĕhwá֑h şá̂ş֤̂wòn wĕ⁠şîmĕẖáh֙ yimá֣̇ẕéʼ bá֔⁠ḣ ţ̇wòdá֖h wĕ⁠q֥wòl zimĕráֽh׃s"],[51,4,"הַקְשִׁ֤יבוּ אֵלַ⁠י֙ עַמִּ֔⁠י וּ⁠לְאוּמִּ֖⁠י אֵלַ֣⁠י הַאֲזִ֑ינוּ כִּ֤י תוֹרָה֙ מֵ⁠אִתִּ֣⁠י תֵצֵ֔א וּ⁠מִשְׁפָּטִ֔⁠י לְ⁠א֥וֹר עַמִּ֖ים אַרְגִּֽיעַ׃","haqĕşǐ֤ybẇ ʼéla⁠y֙ ʻami̇֔⁠y ẇ⁠lĕʼẇmi֖̇⁠y ʼéla֣⁠y haʼàzi֑ynẇ ki֤̇y ţwòráh֙ mé⁠ʼiţi֣̇⁠y ţéẕé֔ʼ ẇ⁠mişĕ̌pá̇ti֔⁠y lĕ⁠ʼ֥wòr ʻami֖̇ym ʼarĕgiֽ̇yʻa׃"],[51,5,"קָר֤וֹב צִדְקִ⁠י֙ יָצָ֣א יִשְׁעִ֔⁠י וּ⁠זְרֹעַ֖⁠י עַמִּ֣ים יִשְׁפֹּ֑טוּ אֵלַ⁠י֙ אִיִּ֣ים יְקַוּ֔וּ וְ⁠אֶל־זְרֹעִ֖⁠י יְיַחֵלֽוּ⁠ן׃","qár֤wòb ẕidĕqi⁠y֙ yáẕá֣ʼ yişĕ̌ʻi֔⁠y ẇ⁠zĕròʻa֖⁠y ʻami֣̇ym yişĕ̌pò֑̇tẇ ʼéla⁠y֙ ʼiyi֣̇ym yĕqaẇ֔ẇ wĕ⁠ʼel-zĕròʻi֖⁠y yĕyaẖélֽẇ⁠n׃"],[51,6,"שְׂאוּ֩ לַ⁠שָּׁמַ֨יִם עֵֽינֵי⁠כֶ֜ם וְֽ⁠הַבִּ֧יטוּ אֶל־הָ⁠אָ֣רֶץ מִ⁠תַּ֗חַת כִּֽי־שָׁמַ֜יִם כֶּ⁠עָשָׁ֤ן נִמְלָ֨חוּ֙ וְ⁠הָ⁠אָ֨רֶץ֙ כַּ⁠בֶּ֣גֶד תִּבְלֶ֔ה וְ⁠יֹשְׁבֶ֖י⁠הָ כְּמוֹ־כֵ֣ן יְמוּת֑וּ⁠ן וִ⁠ישֽׁוּעָתִ⁠י֙ לְ⁠עוֹלָ֣ם תִּֽהְיֶ֔ה וְ⁠צִדְקָתִ֖⁠י לֹ֥א תֵחָֽת׃ס","şĕ̂ʼẇ֩ la⁠şá̇̌ma֨yim ʻéֽynéy⁠ke֜m wĕֽ⁠habi֧̇ytẇ ʼel-há⁠ʼá֣reẕ mi⁠ţȧ֗ẖaţ kiֽ̇y-şá̌ma֜yim kė⁠ʻáşá֤̌n nimĕlá֨ẖẇ֙ wĕ⁠há⁠ʼá֨reẕ֙ kȧ⁠bė֣ged ţi̇bĕle֔h wĕ⁠yòşĕ̌be֖y⁠há kĕ̇mwò-ké֣n yĕmẇţ֑ẇ⁠n wi⁠yşֽ̌ẇʻáţi⁠y֙ lĕ⁠ʻwòlá֣m ţiֽ̇hĕye֔h wĕ⁠ẕidĕqáţi֖⁠y lò֥ʼ ţéẖáֽţ׃s"],[51,7,"שִׁמְע֤וּ אֵלַ⁠י֙ יֹ֣דְעֵי צֶ֔דֶק עַ֖ם תּוֹרָתִ֣⁠י בְ⁠לִבָּ֑⁠ם אַל־תִּֽירְאוּ֙ חֶרְפַּ֣ת אֱנ֔וֹשׁ וּ⁠מִ⁠גִּדֻּפֹתָ֖⁠ם אַל־תֵּחָֽתּוּ׃","şǐmĕʻ֤ẇ ʼéla⁠y֙ yò֣dĕʻéy ẕe֔deq ʻa֖m ţ̇wòráţi֣⁠y bĕ⁠libá֑̇⁠m ʼal-ţiֽ̇yrĕʼẇ֙ ẖerĕpȧ֣ţ ʼèn֔wòş̌ ẇ⁠mi⁠gi̇du̇pòţá֖⁠m ʼal-ţé̇ẖáֽţ̇ẇ׃"],[51,8,"כִּ֤י כַ⁠בֶּ֨גֶד֙ יֹאכְלֵ֣⁠ם עָ֔שׁ וְ⁠כַ⁠צֶּ֖מֶר יֹאכְלֵ֣⁠ם סָ֑ס וְ⁠צִדְקָתִ⁠י֙ לְ⁠עוֹלָ֣ם תִּֽהְיֶ֔ה וִ⁠ישׁוּעָתִ֖⁠י לְ⁠ד֥וֹר דּוֹרִֽים׃ס","ki֤̇y ka⁠bė֨ged֙ yòʼkĕlé֣⁠m ʻá֔ş̌ wĕ⁠ka⁠ẕė֖mer yòʼkĕlé֣⁠m sá֑s wĕ⁠ẕidĕqáţi⁠y֙ lĕ⁠ʻwòlá֣m ţiֽ̇hĕye֔h wi⁠yş̌ẇʻáţi֖⁠y lĕ⁠d֥wòr ḋwòriֽym׃s"],[51,9,"עוּרִ֨י עוּרִ֤י לִבְשִׁי־עֹז֙ זְר֣וֹעַ יְהוָ֔ה ע֚וּרִי כִּ֣⁠ימֵי קֶ֔דֶם דֹּר֖וֹת עוֹלָמִ֑ים הֲ⁠ל֥וֹא אַתְּ־הִ֛יא הַ⁠מַּחְצֶ֥בֶת רַ֖הַב מְחוֹלֶ֥לֶת תַּנִּֽין׃","ʻẇri֨y ʻẇri֤y libĕşǐy-ʻòz֙ zĕr֣wòʻa yĕhwá֔h ʻ֚ẇriy ki֣̇⁠yméy qe֔dem dò̇r֖wòţ ʻwòlámi֑ym hà⁠l֥wòʼ ʼaţĕ̇-hi֛yʼ ha⁠mȧẖĕẕe֥beţ ra֖hab mĕẖwòle֥leţ ţȧniֽ̇yn׃"],[51,10,"הֲ⁠ל֤וֹא אַתְּ־הִיא֙ הַ⁠מַּחֲרֶ֣בֶת יָ֔ם מֵ֖י תְּה֣וֹם רַבָּ֑ה הַ⁠שָּׂ֨מָה֙ מַֽעֲמַקֵּי־יָ֔ם דֶּ֖רֶךְ לַ⁠עֲבֹ֥ר גְּאוּלִֽים׃","hà⁠l֤wòʼ ʼaţĕ̇-hiyʼ֙ ha⁠mȧẖàre֣beţ yá֔m mé֖y ţĕ̇h֣wòm rabá֑̇h ha⁠şá̇̂֨máh֙ maֽʻàmaqé̇y-yá֔m dė֖rekĕ la⁠ʻàbò֥r gĕ̇ʼẇliֽym׃"],[51,11,"וּ⁠פְדוּיֵ֨י יְהוָ֜ה יְשׁוּב֗וּ⁠ן וּ⁠בָ֤אוּ צִיּוֹן֙ בְּ⁠רִנָּ֔ה וְ⁠שִׂמְחַ֥ת עוֹלָ֖ם עַל־רֹאשָׁ֑⁠ם שָׂשׂ֤וֹן וְ⁠שִׂמְחָה֙ יַשִּׂיג֔וּ⁠ן נָ֖סוּ יָג֥וֹן וַ⁠אֲנָחָֽה׃ס","ẇ⁠pĕdẇyé֨y yĕhwá֜h yĕş̌ẇb֗ẇ⁠n ẇ⁠bá֤ʼẇ ẕiẏwòn֙ bĕ̇⁠riná̇֔h wĕ⁠şîmĕẖa֥ţ ʻwòlá֖m ʻal-ròʼşá֑̌⁠m şá̂ş֤̂wòn wĕ⁠şîmĕẖáh֙ yaşi̇̂yg֔ẇ⁠n ná֖sẇ yág֥wòn wa⁠ʼànáẖáֽh׃s"],[51,12,"אָנֹכִ֧י אָנֹכִ֛י ה֖וּא מְנַחֶמְ⁠כֶ֑ם מִֽי־אַ֤תְּ וַ⁠תִּֽירְאִי֙ מֵ⁠אֱנ֣וֹשׁ יָמ֔וּת וּ⁠מִ⁠בֶּן־אָדָ֖ם חָצִ֥יר יִנָּתֵֽן׃","ʼánòki֧y ʼánòki֛y h֖ẇʼ mĕnaẖemĕ⁠ke֑m miֽy-ʼa֤ţĕ̇ wa⁠ţiֽ̇yrĕʼiy֙ mé⁠ʼèn֣wòş̌ yám֔ẇţ ẇ⁠mi⁠bėn-ʼádá֖m ẖáẕi֥yr yiná̇ţéֽn׃"],[51,13,"וַ⁠תִּשְׁכַּ֞ח יְהוָ֣ה עֹשֶׂ֗⁠ךָ נוֹטֶ֣ה שָׁמַיִם֮ וְ⁠יֹסֵ֣ד אָרֶץ֒ וַ⁠תְּפַחֵ֨ד תָּמִ֜יד כָּל־הַ⁠יּ֗וֹם מִ⁠פְּנֵי֙ חֲמַ֣ת הַ⁠מֵּצִ֔יק כַּ⁠אֲשֶׁ֥ר כּוֹנֵ֖ן לְ⁠הַשְׁחִ֑ית וְ⁠אַיֵּ֖ה חֲמַ֥ת הַ⁠מֵּצִֽיק׃","wa⁠ţi̇şĕ̌kȧ֞ẖ yĕhwá֣h ʻòşê֗⁠ká nwòte֣h şá̌mayim֮ wĕ⁠yòsé֣d ʼáreẕ֒ wa⁠ţĕ̇paẖé֨d ţá̇mi֜yd ká̇l-ha⁠ẏ֗wòm mi⁠pĕ̇néy֙ ẖàma֣ţ ha⁠mé̇ẕi֔yq kȧ⁠ʼàşě֥r k̇wòné֖n lĕ⁠haşĕ̌ẖi֑yţ wĕ⁠ʼayé֖̇h ẖàma֥ţ ha⁠mé̇ẕiֽyq׃"],[51,14,"מִהַ֥ר צֹעֶ֖ה לְ⁠הִפָּתֵ֑חַ וְ⁠לֹא־יָמ֣וּת לַ⁠שַּׁ֔חַת וְ⁠לֹ֥א יֶחְסַ֖ר לַחְמֽ⁠וֹ׃","miha֥r ẕòʻe֖h lĕ⁠hipá̇ţé֑ẖa wĕ⁠lòʼ-yám֣ẇţ la⁠şȧ̌֔ẖaţ wĕ⁠lò֥ʼ yeẖĕsa֖r laẖĕmֽ⁠wò׃"],[51,15,"וְ⁠אָֽנֹכִי֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ רֹגַ֣ע הַ⁠יָּ֔ם וַ⁠יֶּהֱמ֖וּ גַּלָּ֑י⁠ו יְהוָ֥ה צְבָא֖וֹת שְׁמֽ⁠וֹ׃","wĕ⁠ʼáֽnòkiy֙ yĕhwá֣h ʼèlòhe֔y⁠ká ròga֣ʻ ha⁠yá̇֔m wa⁠yėhèm֖ẇ gȧlá֑̇y⁠w yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌mֽ⁠wò׃"],[51,16,"וָ⁠אָשִׂ֤ים דְּבָרַ⁠י֙ בְּ⁠פִ֔י⁠ךָ וּ⁠בְ⁠צֵ֥ל יָדִ֖⁠י כִּסִּיתִ֑י⁠ךָ לִ⁠נְטֹ֤עַ שָׁמַ֨יִם֙ וְ⁠לִ⁠יסֹ֣ד אָ֔רֶץ וְ⁠לֵ⁠אמֹ֥ר לְ⁠צִיּ֖וֹן עַמִּ⁠י־אָֽתָּה׃ס","wá⁠ʼáşî֤ym dĕ̇bára⁠y֙ bĕ̇⁠pi֔y⁠ká ẇ⁠bĕ⁠ẕé֥l yádi֖⁠y ki̇si̇yţi֑y⁠ká li⁠nĕtò֤ʻa şá̌ma֨yim֙ wĕ⁠li⁠ysò֣d ʼá֔reẕ wĕ⁠lé⁠ʼmò֥r lĕ⁠ẕiẏ֖wòn ʻami̇⁠y-ʼáֽţá̇h׃s"],[51,17,"הִתְעוֹרְרִ֣י הִֽתְעוֹרְרִ֗י ק֚וּמִי יְר֣וּשָׁלִַ֔ם אֲשֶׁ֥ר שָׁתִ֛ית מִ⁠יַּ֥ד יְהוָ֖ה אֶת־כּ֣וֹס חֲמָת֑⁠וֹ אֶת־קֻבַּ֜עַת כּ֧וֹס הַ⁠תַּרְעֵלָ֛ה שָׁתִ֖ית מָצִֽית׃","hiţĕʻwòrĕri֣y hiֽţĕʻwòrĕri֗y q֚ẇmiy yĕr֣ẇşá̌lia֔m ʼàşě֥r şá̌ţi֛yţ mi⁠yȧ֥d yĕhwá֖h ʼeţ-k֣̇wòs ẖàmáţ֑⁠wò ʼeţ-qubȧ֜ʻaţ k֧̇wòs ha⁠ţȧrĕʻélá֛h şá̌ţi֖yţ máẕiֽyţ׃"],[51,18,"אֵין־מְנַהֵ֣ל לָ֔⁠הּ מִ⁠כָּל־בָּנִ֖ים יָלָ֑דָה וְ⁠אֵ֤ין מַחֲזִיק֙ בְּ⁠יָדָ֔⁠הּ מִ⁠כָּל־בָּנִ֖ים גִּדֵּֽלָה׃","ʼéyn-mĕnahé֣l lá֔⁠ḣ mi⁠ká̇l-bá̇ni֖ym yálá֑dáh wĕ⁠ʼé֤yn maẖàziyq֙ bĕ̇⁠yádá֔⁠ḣ mi⁠ká̇l-bá̇ni֖ym gi̇déֽ̇láh׃"],[51,19,"שְׁתַּ֤יִם הֵ֨נָּה֙ קֹֽרְאֹתַ֔יִ⁠ךְ מִ֖י יָנ֣וּד לָ֑⁠ךְ הַ⁠שֹּׁ֧ד וְ⁠הַ⁠שֶּׁ֛בֶר וְ⁠הָ⁠רָעָ֥ב וְ⁠הַ⁠חֶ֖רֶב מִ֥י אֲנַחֲמֵֽ⁠ךְ׃","şĕ̌ţȧ֤yim hé֨ná̇h֙ qòֽrĕʼòţa֔yi⁠kĕ mi֖y yán֣ẇd lá֑⁠kĕ ha⁠şò֧̇̌d wĕ⁠ha⁠şė֛̌ber wĕ⁠há⁠ráʻá֥b wĕ⁠ha⁠ẖe֖reb mi֥y ʼànaẖàméֽ⁠kĕ׃"],[51,20,"בָּנַ֜יִ⁠ךְ עֻלְּפ֥וּ שָׁכְב֛וּ בְּ⁠רֹ֥אשׁ כָּל־חוּצ֖וֹת כְּ⁠ת֣וֹא מִכְמָ֑ר הַֽ⁠מְלֵאִ֥ים חֲמַת־יְהוָ֖ה גַּעֲרַ֥ת אֱלֹהָֽיִ⁠ךְ׃","bá̇na֜yi⁠kĕ ʻulĕ̇p֥ẇ şá̌kĕb֛ẇ bĕ̇⁠rò֥ʼş̌ ká̇l-ẖẇẕ֖wòţ kĕ̇⁠ţ֣wòʼ mikĕmá֑r haֽ⁠mĕléʼi֥ym ẖàmaţ-yĕhwá֖h gȧʻàra֥ţ ʼèlòháֽyi⁠kĕ׃"],[51,21,"לָ⁠כֵ֛ן שִׁמְעִי־נָ֥א זֹ֖את עֲנִיָּ֑ה וּ⁠שְׁכֻרַ֖ת וְ⁠לֹ֥א מִ⁠יָּֽיִן׃ס","lá⁠ké֛n şǐmĕʻiy-ná֥ʼ zò֖ʼţ ʻàniyá֑̇h ẇ⁠şĕ̌kura֖ţ wĕ⁠lò֥ʼ mi⁠yáֽ̇yin׃s"],[51,22,"כֹּֽה־אָמַ֞ר אֲדֹנַ֣יִ⁠ךְ יְהוָ֗ה וֵ⁠אלֹהַ֨יִ⁠ךְ֙ יָרִ֣יב עַמּ֔⁠וֹ הִנֵּ֥ה לָקַ֛חְתִּי מִ⁠יָּדֵ֖⁠ךְ אֶת־כּ֣וֹס הַ⁠תַּרְעֵלָ֑ה אֶת־קֻבַּ֨עַת֙ כּ֣וֹס חֲמָתִ֔⁠י לֹא־תוֹסִ֥יפִי לִ⁠שְׁתּוֹתָ֖⁠הּ עֽוֹד׃","kòֽ̇h-ʼáma֞r ʼàdòna֣yi⁠kĕ yĕhwá֗h wé⁠ʼlòha֨yi⁠kĕ֙ yári֣yb ʻaṁ֔⁠wò hiné֥̇h láqa֛ẖĕţi̇y mi⁠yá̇dé֖⁠kĕ ʼeţ-k֣̇wòs ha⁠ţȧrĕʻélá֑h ʼeţ-qubȧ֨ʻaţ֙ k֣̇wòs ẖàmáţi֔⁠y lòʼ-ţwòsi֥ypiy li⁠şĕ̌ţ̇wòţá֖⁠ḣ ʻֽwòd׃"],[51,23,"וְ⁠שַׂמְתִּ֨י⁠הָ֙ בְּ⁠יַד־מוֹגַ֔יִ⁠ךְ אֲשֶׁר־אָמְר֥וּ לְ⁠נַפְשֵׁ֖⁠ךְ שְׁחִ֣י וְ⁠נַעֲבֹ֑רָה וַ⁠תָּשִׂ֤ימִי כָ⁠אָ֨רֶץ֙ גֵּוֵ֔⁠ךְ וְ⁠כַ⁠ח֖וּץ לַ⁠עֹבְרִֽים׃ס","wĕ⁠şâmĕţi̇֨y⁠há֙ bĕ̇⁠yad-mwòga֔yi⁠kĕ ʼàşěr-ʼámĕr֥ẇ lĕ⁠napĕşé֖̌⁠kĕ şĕ̌ẖi֣y wĕ⁠naʻàbò֑ráh wa⁠ţá̇şî֤ymiy ká⁠ʼá֨reẕ֙ gé̇wé֔⁠kĕ wĕ⁠ka⁠ẖ֖ẇẕ la⁠ʻòbĕriֽym׃s"],[52,1,"עוּרִ֥י עוּרִ֛י לִבְשִׁ֥י עֻזֵּ֖⁠ךְ צִיּ֑וֹן לִבְשִׁ֣י ׀ בִּגְדֵ֣י תִפְאַרְתֵּ֗⁠ךְ יְרוּשָׁלִַ֨ם֙ עִ֣יר הַ⁠קֹּ֔דֶשׁ כִּ֣י לֹ֥א יוֹסִ֛יף יָבֹא־בָ֥⁠ךְ ע֖וֹד עָרֵ֥ל וְ⁠טָמֵֽא׃","ʻẇri֥y ʻẇri֛y libĕşǐ֥y ʻuzé֖̇⁠kĕ ẕiẏ֑wòn libĕşǐ֣y ׀ bi̇gĕdé֣y ţipĕʼarĕţé̇֗⁠kĕ yĕrẇşá̌lia֨m֙ ʻi֣yr ha⁠qò̇֔deş̌ ki֣̇y lò֥ʼ ywòsi֛yp yábòʼ-bá֥⁠kĕ ʻ֖wòd ʻáré֥l wĕ⁠táméֽʼ׃"],[52,2,"הִתְנַעֲרִ֧י מֵ⁠עָפָ֛ר ק֥וּמִי שְּׁבִ֖י יְרֽוּשָׁלִָ֑ם התפתחו מוֹסְרֵ֣י צַוָּארֵ֔⁠ךְ שְׁבִיָּ֖ה בַּת־צִיּֽוֹן׃ס","hiţĕnaʻàri֧y mé⁠ʻápá֛r q֥ẇmiy şĕ̇̌bi֖y yĕrֽẇşá̌liá֑m hţpţẖw mwòsĕré֣y ẕawá̇ʼré֔⁠kĕ şĕ̌biyá֖̇h bȧţ-ẕiẏֽwòn׃s"],[52,3,"כִּֽי־כֹה֙ אָמַ֣ר יְהוָ֔ה חִנָּ֖ם נִמְכַּרְתֶּ֑ם וְ⁠לֹ֥א בְ⁠כֶ֖סֶף תִּגָּאֵֽלוּ׃","kiֽ̇y-kòh֙ ʼáma֣r yĕhwá֔h ẖiná֖̇m nimĕkȧrĕţė֑m wĕ⁠lò֥ʼ bĕ⁠ke֖sep ţi̇gá̇ʼéֽlẇ׃"],[52,4,"כִּ֣י כֹ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה מִצְרַ֛יִם יָֽרַד־עַמִּ֥⁠י בָ⁠רִֽאשֹׁנָ֖ה לָ⁠ג֣וּר שָׁ֑ם וְ⁠אַשּׁ֖וּר בְּ⁠אֶ֥פֶס עֲשָׁקֽ⁠וֹ׃","ki֣̇y kò֤h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h miẕĕra֛yim yáֽrad-ʻami֥̇⁠y bá⁠riֽʼşò̌ná֖h lá⁠g֣ẇr şá֑̌m wĕ⁠ʼaş֖̇̌ẇr bĕ̇⁠ʼe֥pes ʻàşá̌qֽ⁠wò׃"],[52,5,"וְ⁠עַתָּ֤ה מי־ל⁠י־פֹה֙ נְאֻם־יְהוָ֔ה כִּֽי־לֻקַּ֥ח עַמִּ֖⁠י חִנָּ֑ם משל⁠ו יְהֵילִ֨ילוּ֙ נְאֻם־יְהוָ֔ה וְ⁠תָמִ֥יד כָּל־הַ⁠יּ֖וֹם שְׁמִ֥⁠י מִנֹּאָֽץ׃","wĕ⁠ʻaţá֤̇h my-l⁠y-pòh֙ nĕʼum-yĕhwá֔h kiֽ̇y-luqȧ֥ẖ ʻami֖̇⁠y ẖiná֑̇m mşl⁠w yĕhéyli֨ylẇ֙ nĕʼum-yĕhwá֔h wĕ⁠ţámi֥yd ká̇l-ha⁠ẏ֖wòm şĕ̌mi֥⁠y minò̇ʼáֽẕ׃"],[52,6,"לָ⁠כֵ֛ן יֵדַ֥ע עַמִּ֖⁠י שְׁמִ֑⁠י לָ⁠כֵן֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא כִּֽי־אֲנִי־ה֥וּא הַֽ⁠מְדַבֵּ֖ר הִנֵּֽ⁠נִי׃","lá⁠ké֛n yéda֥ʻ ʻami֖̇⁠y şĕ̌mi֑⁠y lá⁠kén֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ kiֽ̇y-ʼàniy-h֥ẇʼ haֽ⁠mĕdabé֖̇r hinéֽ̇⁠niy׃"],[52,7,"מַה־נָּאו֨וּ עַל־הֶ⁠הָרִ֜ים רַגְלֵ֣י מְבַשֵּׂ֗ר מַשְׁמִ֧יעַ שָׁל֛וֹם מְבַשֵּׂ֥ר ט֖וֹב מַשְׁמִ֣יעַ יְשׁוּעָ֑ה אֹמֵ֥ר לְ⁠צִיּ֖וֹן מָלַ֥ךְ אֱלֹהָֽיִ⁠ךְ׃","mah-ná̇ʼw֨ẇ ʻal-he⁠hári֜ym ragĕlé֣y mĕbaşé̇̂֗r maşĕ̌mi֧yʻa şá̌l֛wòm mĕbaşé֥̇̂r t֖wòb maşĕ̌mi֣yʻa yĕş̌ẇʻá֑h ʼòmé֥r lĕ⁠ẕiẏ֖wòn mála֥kĕ ʼèlòháֽyi⁠kĕ׃"],[52,8,"ק֥וֹל צֹפַ֛יִ⁠ךְ נָ֥שְׂאוּ ק֖וֹל יַחְדָּ֣ו יְרַנֵּ֑נוּ כִּ֣י עַ֤יִן בְּ⁠עַ֨יִן֙ יִרְא֔וּ בְּ⁠שׁ֥וּב יְהוָ֖ה צִיּֽוֹן׃","q֥wòl ẕòpa֛yi⁠kĕ ná֥şĕ̂ʼẇ q֖wòl yaẖĕdá֣̇w yĕrané֑̇nẇ ki֣̇y ʻa֤yin bĕ̇⁠ʻa֨yin֙ yirĕʼ֔ẇ bĕ̇⁠ş֥̌ẇb yĕhwá֖h ẕiẏֽwòn׃"],[52,9,"פִּצְח֤וּ רַנְּנוּ֙ יַחְדָּ֔ו חָרְב֖וֹת יְרוּשָׁלִָ֑ם כִּֽי־נִחַ֤ם יְהוָה֙ עַמּ֔⁠וֹ גָּאַ֖ל יְרוּשָׁלִָֽם׃","pi̇ẕĕẖ֤ẇ ranĕ̇nẇ֙ yaẖĕdá̇֔w ẖárĕb֖wòţ yĕrẇşá̌liá֑m kiֽ̇y-niẖa֤m yĕhwáh֙ ʻaṁ֔⁠wò gá̇ʼa֖l yĕrẇşá̌liáֽm׃"],[52,10,"חָשַׂ֤ף יְהוָה֙ אֶת־זְר֣וֹעַ קָדְשׁ֔⁠וֹ לְ⁠עֵינֵ֖י כָּל־הַ⁠גּוֹיִ֑ם וְ⁠רָאוּ֙ כָּל־אַפְסֵי־אָ֔רֶץ אֵ֖ת יְשׁוּעַ֥ת אֱלֹהֵֽי⁠נוּ׃ס","ẖáşâ֤p yĕhwáh֙ ʼeţ-zĕr֣wòʻa qádĕş̌֔⁠wò lĕ⁠ʻéyné֖y ká̇l-ha⁠ġwòyi֑m wĕ⁠ráʼẇ֙ ká̇l-ʼapĕséy-ʼá֔reẕ ʼé֖ţ yĕş̌ẇʻa֥ţ ʼèlòhéֽy⁠nẇ׃s"],[52,11,"ס֤וּרוּ ס֨וּרוּ֙ צְא֣וּ מִ⁠שָּׁ֔ם טָמֵ֖א אַל־תִּגָּ֑עוּ צְא֣וּ מִ⁠תּוֹכָ֔⁠הּ הִבָּ֕רוּ נֹשְׂאֵ֖י כְּלֵ֥י יְהוָֽה׃","s֤ẇrẇ s֨ẇrẇ֙ ẕĕʼ֣ẇ mi⁠şá̇̌֔m támé֖ʼ ʼal-ţi̇gá֑̇ʻẇ ẕĕʼ֣ẇ mi⁠ţ̇wòká֔⁠ḣ hibá̇֕rẇ nòşĕ̂ʼé֖y kĕ̇lé֥y yĕhwáֽh׃"],[52,12,"כִּ֣י לֹ֤א בְ⁠חִפָּזוֹן֙ תֵּצֵ֔אוּ וּ⁠בִ⁠מְנוּסָ֖ה לֹ֣א תֵלֵכ֑וּ⁠ן כִּֽי־הֹלֵ֤ךְ לִ⁠פְנֵי⁠כֶם֙ יְהוָ֔ה וּ⁠מְאַסִּפְ⁠כֶ֖ם אֱלֹהֵ֥י יִשְׂרָאֵֽל׃ס","ki֣̇y lò֤ʼ bĕ⁠ẖipá̇zwòn֙ ţé̇ẕé֔ʼẇ ẇ⁠bi⁠mĕnẇsá֖h lò֣ʼ ţélék֑ẇ⁠n kiֽ̇y-hòlé֤kĕ li⁠pĕnéy⁠kem֙ yĕhwá֔h ẇ⁠mĕʼasi̇pĕ⁠ke֖m ʼèlòhé֥y yişĕ̂ráʼéֽl׃s"],[52,13,"הִנֵּ֥ה יַשְׂכִּ֖יל עַבְדִּ֑⁠י יָר֧וּם וְ⁠נִשָּׂ֛א וְ⁠גָבַ֖הּ מְאֹֽד׃","hiné֥̇h yaşĕ̂ki֖̇yl ʻabĕdi֑̇⁠y yár֧ẇm wĕ⁠nişá֛̇̂ʼ wĕ⁠gába֖ḣ mĕʼòֽd׃"],[52,14,"כַּ⁠אֲשֶׁ֨ר שָׁמְמ֤וּ עָלֶ֨י⁠ךָ֙ רַבִּ֔ים כֵּן־מִשְׁחַ֥ת מֵ⁠אִ֖ישׁ מַרְאֵ֑⁠הוּ וְ⁠תֹאֲר֖⁠וֹ מִ⁠בְּנֵ֥י אָדָֽם׃","kȧ⁠ʼàşě֨r şá̌mĕm֤ẇ ʻále֨y⁠ká֙ rabi̇֔ym ké̇n-mişĕ̌ẖa֥ţ mé⁠ʼi֖yş̌ marĕʼé֑⁠hẇ wĕ⁠ţòʼàr֖⁠wò mi⁠bĕ̇né֥y ʼádáֽm׃"],[52,15,"כֵּ֤ן יַזֶּה֙ גּוֹיִ֣ם רַבִּ֔ים עָלָ֛י⁠ו יִקְפְּצ֥וּ מְלָכִ֖ים פִּי⁠הֶ֑ם כִּ֠י אֲשֶׁ֨ר לֹֽא־סֻפַּ֤ר לָ⁠הֶם֙ רָא֔וּ וַ⁠אֲשֶׁ֥ר לֹֽא־שָׁמְע֖וּ הִתְבּוֹנָֽנוּ׃","ké֤̇n yazėh֙ ġwòyi֣m rabi̇֔ym ʻálá֛y⁠w yiqĕpĕ̇ẕ֥ẇ mĕláki֖ym pi̇y⁠he֑m ki̇֠y ʼàşě֨r lòֽʼ-supȧ֤r lá⁠hem֙ ráʼ֔ẇ wa⁠ʼàşě֥r lòֽʼ-şá̌mĕʻ֖ẇ hiţĕḃwònáֽnẇ׃"],[53,1,"מִ֥י הֶאֱמִ֖ין לִ⁠שְׁמֻעָתֵ֑⁠נוּ וּ⁠זְר֥וֹעַ יְהוָ֖ה עַל־מִ֥י נִגְלָֽתָה׃","mi֥y heʼèmi֖yn li⁠şĕ̌muʻáţé֑⁠nẇ ẇ⁠zĕr֥wòʻa yĕhwá֖h ʻal-mi֥y nigĕláֽţáh׃"],[53,2,"וַ⁠יַּ֨עַל כַּ⁠יּוֹנֵ֜ק לְ⁠פָנָ֗י⁠ו וְ⁠כַ⁠שֹּׁ֨רֶשׁ֙ מֵ⁠אֶ֣רֶץ צִיָּ֔ה לֹא־תֹ֥אַר ל֖⁠וֹ וְ⁠לֹ֣א הָדָ֑ר וְ⁠נִרְאֵ֥⁠הוּ וְ⁠לֹֽא־מַרְאֶ֖ה וְ⁠נֶחְמְדֵֽ⁠הוּ׃","wa⁠yȧ֨ʻal kȧ⁠ẏwòné֜q lĕ⁠páná֗y⁠w wĕ⁠ka⁠şò̇̌֨reş̌֙ mé⁠ʼe֣reẕ ẕiyá̇֔h lòʼ-ţò֥ʼar l֖⁠wò wĕ⁠lò֣ʼ hádá֑r wĕ⁠nirĕʼé֥⁠hẇ wĕ⁠lòֽʼ-marĕʼe֖h wĕ⁠neẖĕmĕdéֽ⁠hẇ׃"],[53,3,"נִבְזֶה֙ וַ⁠חֲדַ֣ל אִישִׁ֔ים אִ֥ישׁ מַכְאֹב֖וֹת וִ⁠יד֣וּעַ חֹ֑לִי וּ⁠כְ⁠מַסְתֵּ֤ר פָּנִים֙ מִמֶּ֔⁠נּוּ נִבְזֶ֖ה וְ⁠לֹ֥א חֲשַׁבְנֻֽ⁠הוּ׃","nibĕzeh֙ wa⁠ẖàda֣l ʼiyşǐ֔ym ʼi֥yş̌ makĕʼòb֖wòţ wi⁠yd֣ẇʻa ẖò֑liy ẇ⁠kĕ⁠masĕţé֤̇r pá̇niym֙ mimė֔⁠ṅẇ nibĕze֖h wĕ⁠lò֥ʼ ẖàşǎbĕnuֽ⁠hẇ׃"],[53,4,"אָכֵ֤ן חֳלָיֵ֨⁠נוּ֙ ה֣וּא נָשָׂ֔א וּ⁠מַכְאֹבֵ֖י⁠נוּ סְבָלָ֑⁠ם וַ⁠אֲנַ֣חְנוּ חֲשַׁבְנֻ֔⁠הוּ נָג֛וּעַ מֻכֵּ֥ה אֱלֹהִ֖ים וּ⁠מְעֻנֶּֽה׃","ʼáké֤n ẖoláyé֨⁠nẇ֙ h֣ẇʼ náşá̂֔ʼ ẇ⁠makĕʼòbé֖y⁠nẇ sĕbálá֑⁠m wa⁠ʼàna֣ẖĕnẇ ẖàşǎbĕnu֔⁠hẇ nág֛ẇʻa muké֥̇h ʼèlòhi֖ym ẇ⁠mĕʻunėֽh׃"],[53,5,"וְ⁠הוּא֙ מְחֹלָ֣ל מִ⁠פְּשָׁעֵ֔⁠נוּ מְדֻכָּ֖א מֵ⁠עֲוֺנֹתֵ֑י⁠נוּ מוּסַ֤ר שְׁלוֹמֵ֨⁠נוּ֙ עָלָ֔י⁠ו וּ⁠בַ⁠חֲבֻרָת֖⁠וֹ נִרְפָּא־לָֽ⁠נוּ׃","wĕ⁠hẇʼ֙ mĕẖòlá֣l mi⁠pĕ̇şá̌ʻé֔⁠nẇ mĕduká֖̇ʼ mé⁠ʻàwֺnòţé֑y⁠nẇ mẇsa֤r şĕ̌lwòmé֨⁠nẇ֙ ʻálá֔y⁠w ẇ⁠ba⁠ẖàburáţ֖⁠wò nirĕpá̇ʼ-láֽ⁠nẇ׃"],[53,6,"כֻּלָּ֨⁠נוּ֙ כַּ⁠צֹּ֣אן תָּעִ֔ינוּ אִ֥ישׁ לְ⁠דַרְכּ֖⁠וֹ פָּנִ֑ינוּ וַֽ⁠יהוָה֙ הִפְגִּ֣יעַ בּ֔⁠וֹ אֵ֖ת עֲוֺ֥ן כֻּלָּֽ⁠נוּ׃","ku̇lá̇֨⁠nẇ֙ kȧ⁠ẕò֣̇ʼn ţá̇ʻi֔ynẇ ʼi֥yş̌ lĕ⁠darĕk֖̇⁠wò pá̇ni֑ynẇ waֽ⁠yhwáh֙ hipĕgi֣̇yʻa ḃ֔⁠wò ʼé֖ţ ʻàwֺ֥n ku̇láֽ̇⁠nẇ׃"],[53,7,"נִגַּ֨שׂ וְ⁠ה֣וּא נַעֲנֶה֮ וְ⁠לֹ֣א יִפְתַּח־פִּי⁠ו֒ כַּ⁠שֶּׂה֙ לַ⁠טֶּ֣בַח יוּבָ֔ל וּ⁠כְ⁠רָחֵ֕ל לִ⁠פְנֵ֥י גֹזְזֶ֖י⁠הָ נֶאֱלָ֑מָה וְ⁠לֹ֥א יִפְתַּ֖ח פִּֽי⁠ו׃","nigȧ֨ş̂ wĕ⁠h֣ẇʼ naʻàneh֮ wĕ⁠lò֣ʼ yipĕţȧẖ-pi̇y⁠w֒ kȧ⁠şė̂h֙ la⁠tė֣baẖ yẇbá֔l ẇ⁠kĕ⁠ráẖé֕l li⁠pĕné֥y gòzĕze֖y⁠há neʼèlá֑máh wĕ⁠lò֥ʼ yipĕţȧ֖ẖ piֽ̇y⁠w׃"],[53,8,"מֵ⁠עֹ֤צֶר וּ⁠מִ⁠מִּשְׁפָּט֙ לֻקָּ֔ח וְ⁠אֶת־דּוֹר֖⁠וֹ מִ֣י יְשׂוֹחֵ֑חַ כִּ֤י נִגְזַר֙ מֵ⁠אֶ֣רֶץ חַיִּ֔ים מִ⁠פֶּ֥שַׁע עַמִּ֖⁠י נֶ֥גַע לָֽ⁠מוֹ׃","mé⁠ʻò֤ẕer ẇ⁠mi⁠mi̇şĕ̌pá̇t֙ luqá̇֔ẖ wĕ⁠ʼeţ-ḋwòr֖⁠wò mi֣y yĕş̂wòẖé֑ẖa ki֤̇y nigĕzar֙ mé⁠ʼe֣reẕ ẖayi̇֔ym mi⁠pė֥şǎʻ ʻami֖̇⁠y ne֥gaʻ láֽ⁠mwò׃"],[53,9,"וַ⁠יִּתֵּ֤ן אֶת־רְשָׁעִים֙ קִבְר֔⁠וֹ וְ⁠אֶת־עָשִׁ֖יר בְּ⁠מֹתָ֑י⁠ו עַ֚ל לֹא־חָמָ֣ס עָשָׂ֔ה וְ⁠לֹ֥א מִרְמָ֖ה בְּ⁠פִֽי⁠ו׃","wa⁠yi̇ţé֤̇n ʼeţ-rĕşá̌ʻiym֙ qibĕr֔⁠wò wĕ⁠ʼeţ-ʻáşǐ֖yr bĕ̇⁠mòţá֑y⁠w ʻa֚l lòʼ-ẖámá֣s ʻáşá̂֔h wĕ⁠lò֥ʼ mirĕmá֖h bĕ̇⁠piֽy⁠w׃"],[53,10,"וַ⁠יהוָ֞ה חָפֵ֤ץ דַּכְּא⁠וֹ֙ הֶֽחֱלִ֔י אִם־תָּשִׂ֤ים אָשָׁם֙ נַפְשׁ֔⁠וֹ יִרְאֶ֥ה זֶ֖רַע יַאֲרִ֣יךְ יָמִ֑ים וְ⁠חֵ֥פֶץ יְהוָ֖ה בְּ⁠יָד֥⁠וֹ יִצְלָֽח׃","wa⁠yhwá֞h ẖápé֤ẕ dȧkĕ̇ʼ⁠wò֙ heֽẖèli֔y ʼim-ţá̇şî֤ym ʼáşá̌m֙ napĕş̌֔⁠wò yirĕʼe֥h ze֖raʻ yaʼàri֣ykĕ yámi֑ym wĕ⁠ẖé֥peẕ yĕhwá֖h bĕ̇⁠yád֥⁠wò yiẕĕláֽẖ׃"],[53,11,"מֵ⁠עֲמַ֤ל נַפְשׁ⁠וֹ֙ יִרְאֶ֣ה יִשְׂבָּ֔ע בְּ⁠דַעְתּ֗⁠וֹ יַצְדִּ֥יק צַדִּ֛יק עַבְדִּ֖⁠י לָֽ⁠רַבִּ֑ים וַ⁠עֲוֺנֹתָ֖⁠ם ה֥וּא יִסְבֹּֽל׃","mé⁠ʻàma֤l napĕş̌⁠wò֙ yirĕʼe֣h yişĕ̂bá̇֔ʻ bĕ̇⁠daʻĕţ̇֗⁠wò yaẕĕdi֥̇yq ẕadi֛̇yq ʻabĕdi֖̇⁠y láֽ⁠rabi֑̇ym wa⁠ʻàwֺnòţá֖⁠m h֥ẇʼ yisĕbòֽ̇l׃"],[53,12,"לָ⁠כֵ֞ן אֲחַלֶּק־ל֣⁠וֹ בָ⁠רַבִּ֗ים וְ⁠אֶת־עֲצוּמִים֮ יְחַלֵּ֣ק שָׁלָל֒ תַּ֗חַת אֲשֶׁ֨ר הֶעֱרָ֤ה לַ⁠מָּ֨וֶת֙ נַפְשׁ֔⁠וֹ וְ⁠אֶת־פֹּשְׁעִ֖ים נִמְנָ֑ה וְ⁠הוּא֙ חֵטְא־רַבִּ֣ים נָשָׂ֔א וְ⁠לַ⁠פֹּשְׁעִ֖ים יַפְגִּֽיעַ׃ס","lá⁠ké֞n ʼàẖalėq-l֣⁠wò bá⁠rabi̇֗ym wĕ⁠ʼeţ-ʻàẕẇmiym֮ yĕẖalé֣̇q şá̌lál֒ ţȧ֗ẖaţ ʼàşě֨r heʻèrá֤h la⁠má̇֨weţ֙ napĕş̌֔⁠wò wĕ⁠ʼeţ-pò̇şĕ̌ʻi֖ym nimĕná֑h wĕ⁠hẇʼ֙ ẖétĕʼ-rabi֣̇ym náşá̂֔ʼ wĕ⁠la⁠pò̇şĕ̌ʻi֖ym yapĕgiֽ̇yʻa׃s"],[54,1,"רָנִּ֥י עֲקָרָ֖ה לֹ֣א יָלָ֑דָה פִּצְחִ֨י רִנָּ֤ה וְ⁠צַהֲלִי֙ לֹא־חָ֔לָה כִּֽי־רַבִּ֧ים בְּֽנֵי־שׁוֹמֵמָ֛ה מִ⁠בְּנֵ֥י בְעוּלָ֖ה אָמַ֥ר יְהוָֽה׃","ráni֥̇y ʻàqárá֖h lò֣ʼ yálá֑dáh pi̇ẕĕẖi֨y riná֤̇h wĕ⁠ẕahàliy֙ lòʼ-ẖá֔láh kiֽ̇y-rabi֧̇ym bĕֽ̇néy-ş̌wòmémá֛h mi⁠bĕ̇né֥y bĕʻẇlá֖h ʼáma֥r yĕhwáֽh׃"],[54,2,"הַרְחִ֣יבִי ׀ מְק֣וֹם אָהֳלֵ֗⁠ךְ וִ⁠ירִיע֧וֹת מִשְׁכְּנוֹתַ֛יִ⁠ךְ יַטּ֖וּ אַל־תַּחְשֹׂ֑כִי הַאֲרִ֨יכִי֙ מֵֽיתָרַ֔יִ⁠ךְ וִ⁠יתֵדֹתַ֖יִ⁠ךְ חַזֵּֽקִי׃","harĕẖi֣ybiy ׀ mĕq֣wòm ʼáholé֗⁠kĕ wi⁠yriyʻ֧wòţ mişĕ̌kĕ̇nwòţa֛yi⁠kĕ yaṫ֖ẇ ʼal-ţȧẖĕşò֑̂kiy haʼàri֨ykiy֙ méֽyţára֔yi⁠kĕ wi⁠yţédòţa֖yi⁠kĕ ẖazéֽ̇qiy׃"],[54,3,"כִּי־יָמִ֥ין וּ⁠שְׂמֹ֖אול תִּפְרֹ֑צִי וְ⁠זַרְעֵ⁠ךְ֙ גּוֹיִ֣ם יִירָ֔שׁ וְ⁠עָרִ֥ים נְשַׁמּ֖וֹת יוֹשִֽׁיבוּ׃","ki̇y-yámi֥yn ẇ⁠şĕ̂mò֖ʼwl ţi̇pĕrò֑ẕiy wĕ⁠zarĕʻé⁠kĕ֙ ġwòyi֣m yiyrá֔ş̌ wĕ⁠ʻári֥ym nĕşǎṁ֖wòţ ywòşǐֽybẇ׃"],[54,4,"אַל־תִּֽירְאִי֙ כִּי־לֹ֣א תֵב֔וֹשִׁי וְ⁠אַל־תִּכָּלְמִ֖י כִּ֣י לֹ֣א תַחְפִּ֑ירִי כִּ֣י בֹ֤שֶׁת עֲלוּמַ֨יִ⁠ךְ֙ תִּשְׁכָּ֔חִי וְ⁠חֶרְפַּ֥ת אַלְמְנוּתַ֖יִ⁠ךְ לֹ֥א תִזְכְּרִי־עֽוֹד׃","ʼal-ţiֽ̇yrĕʼiy֙ ki̇y-lò֣ʼ ţéb֔wòşǐy wĕ⁠ʼal-ţi̇ká̇lĕmi֖y ki֣̇y lò֣ʼ ţaẖĕpi֑̇yriy ki֣̇y bò֤şěţ ʻàlẇma֨yi⁠kĕ֙ ţi̇şĕ̌ká̇֔ẖiy wĕ⁠ẖerĕpȧ֥ţ ʼalĕmĕnẇţa֖yi⁠kĕ lò֥ʼ ţizĕkĕ̇riy-ʻֽwòd׃"],[54,5,"כִּ֤י בֹעֲלַ֨יִ⁠ךְ֙ עֹשַׂ֔יִ⁠ךְ יְהוָ֥ה צְבָא֖וֹת שְׁמ֑⁠וֹ וְ⁠גֹֽאֲלֵ⁠ךְ֙ קְד֣וֹשׁ יִשְׂרָאֵ֔ל אֱלֹהֵ֥י כָל־הָ⁠אָ֖רֶץ יִקָּרֵֽא׃","ki֤̇y bòʻàla֨yi⁠kĕ֙ ʻòşâ֔yi⁠kĕ yĕhwá֥h ẕĕbáʼ֖wòţ şĕ̌m֑⁠wò wĕ⁠gòֽʼàlé⁠kĕ֙ qĕd֣wòş̌ yişĕ̂ráʼé֔l ʼèlòhé֥y kál-há⁠ʼá֖reẕ yiqá̇réֽʼ׃"],[54,6,"כִּֽי־כְ⁠אִשָּׁ֧ה עֲזוּבָ֛ה וַ⁠עֲצ֥וּבַת ר֖וּחַ קְרָאָ֣⁠ךְ יְהוָ֑ה וְ⁠אֵ֧שֶׁת נְעוּרִ֛ים כִּ֥י תִמָּאֵ֖ס אָמַ֥ר אֱלֹהָֽיִ⁠ךְ׃","kiֽ̇y-kĕ⁠ʼişá֧̇̌h ʻàzẇbá֛h wa⁠ʻàẕ֥ẇbaţ r֖ẇẖa qĕráʼá֣⁠kĕ yĕhwá֑h wĕ⁠ʼé֧şěţ nĕʻẇri֛ym ki֥̇y ţimá̇ʼé֖s ʼáma֥r ʼèlòháֽyi⁠kĕ׃"],[54,7,"בְּ⁠רֶ֥גַע קָטֹ֖ן עֲזַבְתִּ֑י⁠ךְ וּ⁠בְ⁠רַחֲמִ֥ים גְּדֹלִ֖ים אֲקַבְּצֵֽ⁠ךְ׃","bĕ̇⁠re֥gaʻ qátò֖n ʻàzabĕţi֑̇y⁠kĕ ẇ⁠bĕ⁠raẖàmi֥ym gĕ̇dòli֖ym ʼàqabĕ̇ẕéֽ⁠kĕ׃"],[54,8,"בְּ⁠שֶׁ֣צֶף קֶ֗צֶף הִסְתַּ֨רְתִּי פָנַ֥⁠י רֶ֨גַע֙ מִמֵּ֔⁠ךְ וּ⁠בְ⁠חֶ֥סֶד עוֹלָ֖ם רִֽחַמְתִּ֑י⁠ךְ אָמַ֥ר גֹּאֲלֵ֖⁠ךְ יְהוָֽה׃ס","bĕ̇⁠şě֣ẕep qe֗ẕep hisĕţȧ֨rĕţi̇y pána֥⁠y re֨gaʻ֙ mimé̇֔⁠kĕ ẇ⁠bĕ⁠ẖe֥sed ʻwòlá֖m riֽẖamĕţi֑̇y⁠kĕ ʼáma֥r gò̇ʼàlé֖⁠kĕ yĕhwáֽh׃s"],[54,9,"כִּי־מֵ֥י נֹ֨חַ֙ זֹ֣את לִ֔⁠י אֲשֶׁ֣ר נִשְׁבַּ֗עְתִּי מֵ⁠עֲבֹ֥ר מֵי־נֹ֛חַ ע֖וֹד עַל־הָ⁠אָ֑רֶץ כֵּ֥ן נִשְׁבַּ֛עְתִּי מִ⁠קְּצֹ֥ף עָלַ֖יִ⁠ךְ וּ⁠מִ⁠גְּעָר־בָּֽ⁠ךְ׃","ki̇y-mé֥y nò֨ẖa֙ zò֣ʼţ li֔⁠y ʼàşě֣r nişĕ̌bȧ֗ʻĕţi̇y mé⁠ʻàbò֥r méy-nò֛ẖa ʻ֖wòd ʻal-há⁠ʼá֑reẕ ké֥̇n nişĕ̌bȧ֛ʻĕţi̇y mi⁠qĕ̇ẕò֥p ʻála֖yi⁠kĕ ẇ⁠mi⁠gĕ̇ʻár-báֽ̇⁠kĕ׃"],[54,10,"כִּ֤י הֶֽ⁠הָרִים֙ יָמ֔וּשׁוּ וְ⁠הַ⁠גְּבָע֖וֹת תְּמוּטֶ֑נָה וְ⁠חַסְדִּ֞⁠י מֵ⁠אִתֵּ֣⁠ךְ לֹֽא־יָמ֗וּשׁ וּ⁠בְרִ֤ית שְׁלוֹמִ⁠י֙ לֹ֣א תָמ֔וּט אָמַ֥ר מְרַחֲמֵ֖⁠ךְ יְהוָֽה׃ס","ki֤̇y heֽ⁠háriym֙ yám֔ẇş̌ẇ wĕ⁠ha⁠gĕ̇báʻ֖wòţ ţĕ̇mẇte֑náh wĕ⁠ẖasĕdi̇֞⁠y mé⁠ʼiţé֣̇⁠kĕ lòֽʼ-yám֗ẇş̌ ẇ⁠bĕri֤yţ şĕ̌lwòmi⁠y֙ lò֣ʼ ţám֔ẇt ʼáma֥r mĕraẖàmé֖⁠kĕ yĕhwáֽh׃s"],[54,11,"עֲנִיָּ֥ה סֹעֲרָ֖ה לֹ֣א נֻחָ֑מָה הִנֵּ֨ה אָנֹכִ֜י מַרְבִּ֤יץ בַּ⁠פּוּךְ֙ אֲבָנַ֔יִ⁠ךְ וִ⁠יסַדְתִּ֖י⁠ךְ בַּ⁠סַּפִּירִֽים׃","ʻàniyá֥̇h sòʻàrá֖h lò֣ʼ nuẖá֑máh hiné̇֨h ʼánòki֜y marĕbi֤̇yẕ bȧ⁠ṗẇkĕ֙ ʼàbána֔yi⁠kĕ wi⁠ysadĕţi֖̇y⁠kĕ bȧ⁠sȧpi̇yriֽym׃"],[54,12,"וְ⁠שַׂמְתִּ֤י כַּֽדְכֹד֙ שִׁמְשֹׁתַ֔יִ⁠ךְ וּ⁠שְׁעָרַ֖יִ⁠ךְ לְ⁠אַבְנֵ֣י אֶקְדָּ֑ח וְ⁠כָל־גְּבוּלֵ֖⁠ךְ לְ⁠אַבְנֵי־חֵֽפֶץ׃","wĕ⁠şâmĕţi֤̇y kȧֽdĕkòd֙ şǐmĕşò̌ţa֔yi⁠kĕ ẇ⁠şĕ̌ʻára֖yi⁠kĕ lĕ⁠ʼabĕné֣y ʼeqĕdá֑̇ẖ wĕ⁠kál-gĕ̇bẇlé֖⁠kĕ lĕ⁠ʼabĕnéy-ẖéֽpeẕ׃"],[54,13,"וְ⁠כָל־בָּנַ֖יִ⁠ךְ לִמּוּדֵ֣י יְהוָ֑ה וְ⁠רַ֖ב שְׁל֥וֹם בָּנָֽיִ⁠ךְ׃","wĕ⁠kál-bá̇na֖yi⁠kĕ liṁẇdé֣y yĕhwá֑h wĕ⁠ra֖b şĕ̌l֥wòm bá̇náֽyi⁠kĕ׃"],[54,14,"בִּ⁠צְדָקָ֖ה תִּכּוֹנָ֑נִי רַחֲקִ֤י מֵ⁠עֹ֨שֶׁק֙ כִּֽי־לֹ֣א תִירָ֔אִי וּ⁠מִ֨⁠מְּחִתָּ֔ה כִּ֥י לֹֽא־תִקְרַ֖ב אֵלָֽיִ⁠ךְ׃","bi̇⁠ẕĕdáqá֖h ţi̇k̇wòná֑niy raẖàqi֤y mé⁠ʻò֨şěq֙ kiֽ̇y-lò֣ʼ ţiyrá֔ʼiy ẇ⁠mi֨⁠mĕ̇ẖiţá̇֔h ki֥̇y lòֽʼ-ţiqĕra֖b ʼéláֽyi⁠kĕ׃"],[54,15,"הֵ֣ן גּ֥וֹר יָג֛וּר אֶ֖פֶס מֵֽ⁠אוֹתִ֑⁠י מִי־גָ֥ר אִתָּ֖⁠ךְ עָלַ֥יִ⁠ךְ יִפּֽוֹל׃","hé֣n ġ֥wòr yág֛ẇr ʼe֖pes méֽ⁠ʼwòţi֑⁠y miy-gá֥r ʼiţá֖̇⁠kĕ ʻála֥yi⁠kĕ yiṗֽwòl׃"],[54,16,"הן אָֽנֹכִי֙ בָּרָ֣אתִי חָרָ֔שׁ נֹפֵ֨חַ֙ בְּ⁠אֵ֣שׁ פֶּחָ֔ם וּ⁠מוֹצִ֥יא כְלִ֖י לְ⁠מַעֲשֵׂ֑⁠הוּ וְ⁠אָנֹכִ֛י בָּרָ֥אתִי מַשְׁחִ֖ית לְ⁠חַבֵּֽל׃","hn ʼáֽnòkiy֙ bá̇rá֣ʼţiy ẖárá֔ş̌ nòpé֨ẖa֙ bĕ̇⁠ʼé֣ş̌ pėẖá֔m ẇ⁠mwòẕi֥yʼ kĕli֖y lĕ⁠maʻàşé֑̂⁠hẇ wĕ⁠ʼánòki֛y bá̇rá֥ʼţiy maşĕ̌ẖi֖yţ lĕ⁠ẖabéֽ̇l׃"],[54,17,"כָּל־כְּלִ֞י יוּצַ֤ר עָלַ֨יִ⁠ךְ֙ לֹ֣א יִצְלָ֔ח וְ⁠כָל־לָשׁ֛וֹן תָּֽקוּם־אִתָּ֥⁠ךְ לַ⁠מִּשְׁפָּ֖ט תַּרְשִׁ֑יעִי זֹ֡את נַחֲלַת֩ עַבְדֵ֨י יְהוָ֧ה וְ⁠צִדְקָתָ֛⁠ם מֵ⁠אִתִּ֖⁠י נְאֻם־יְהוָֽה׃ס","ká̇l-kĕ̇li֞y yẇẕa֤r ʻála֨yi⁠kĕ֙ lò֣ʼ yiẕĕlá֔ẖ wĕ⁠kál-láş֛̌wòn ţáֽ̇qẇm-ʼiţá֥̇⁠kĕ la⁠mi̇şĕ̌pá֖̇t ţȧrĕşǐ֑yʻiy zò֡ʼţ naẖàlaţ֩ ʻabĕdé֨y yĕhwá֧h wĕ⁠ẕidĕqáţá֛⁠m mé⁠ʼiţi֖̇⁠y nĕʼum-yĕhwáֽh׃s"],[55,1,"ה֤וֹי כָּל־צָמֵא֙ לְכ֣וּ לַ⁠מַּ֔יִם וַ⁠אֲשֶׁ֥ר אֵֽין־ל֖⁠וֹ כָּ֑סֶף לְכ֤וּ שִׁבְרוּ֙ וֶֽ⁠אֱכֹ֔לוּ וּ⁠לְכ֣וּ שִׁבְר֗וּ בְּ⁠לוֹא־כֶ֛סֶף וּ⁠בְ⁠ל֥וֹא מְחִ֖יר יַ֥יִן וְ⁠חָלָֽב׃","h֤wòy ká̇l-ẕáméʼ֙ lĕk֣ẇ la⁠mȧ֔yim wa⁠ʼàşě֥r ʼéֽyn-l֖⁠wò ká֑̇sep lĕk֤ẇ şǐbĕrẇ֙ weֽ⁠ʼèkò֔lẇ ẇ⁠lĕk֣ẇ şǐbĕr֗ẇ bĕ̇⁠lwòʼ-ke֛sep ẇ⁠bĕ⁠l֥wòʼ mĕẖi֖yr ya֥yin wĕ⁠ẖáláֽb׃"],[55,2,"לָ֤⁠מָּה תִשְׁקְלוּ־כֶ֨סֶף֙ בְּֽ⁠לוֹא־לֶ֔חֶם וִ⁠יגִיעֲ⁠כֶ֖ם בְּ⁠ל֣וֹא לְ⁠שָׂבְעָ֑ה שִׁמְע֨וּ שָׁמ֤וֹעַ אֵלַ⁠י֙ וְ⁠אִכְלוּ־ט֔וֹב וְ⁠תִתְעַנַּ֥ג בַּ⁠דֶּ֖שֶׁן נַפְשְׁ⁠כֶֽם׃","lá֤⁠má̇h ţişĕ̌qĕlẇ-ke֨sep֙ bĕֽ̇⁠lwòʼ-le֔ẖem wi⁠ygiyʻà⁠ke֖m bĕ̇⁠l֣wòʼ lĕ⁠şá̂bĕʻá֑h şǐmĕʻ֨ẇ şá̌m֤wòʻa ʼéla⁠y֙ wĕ⁠ʼikĕlẇ-t֔wòb wĕ⁠ţiţĕʻanȧ֥g bȧ⁠dė֖şěn napĕşĕ̌⁠keֽm׃"],[55,3,"הַטּ֤וּ אָזְנְ⁠כֶם֙ וּ⁠לְכ֣וּ אֵלַ֔⁠י שִׁמְע֖וּ וּ⁠תְחִ֣י נַפְשְׁ⁠כֶ֑ם וְ⁠אֶכְרְתָ֤ה לָ⁠כֶם֙ בְּרִ֣ית עוֹלָ֔ם חַֽסְדֵ֥י דָוִ֖ד הַ⁠נֶּאֱמָנִֽים׃","haṫ֤ẇ ʼázĕnĕ⁠kem֙ ẇ⁠lĕk֣ẇ ʼéla֔⁠y şǐmĕʻ֖ẇ ẇ⁠ţĕẖi֣y napĕşĕ̌⁠ke֑m wĕ⁠ʼekĕrĕţá֤h lá⁠kem֙ bĕ̇ri֣yţ ʻwòlá֔m ẖaֽsĕdé֥y dáwi֖d ha⁠nėʼèmániֽym׃"],[55,4,"הֵ֛ן עֵ֥ד לְאוּמִּ֖ים נְתַתִּ֑י⁠ו נָגִ֥יד וּ⁠מְצַוֵּ֖ה לְאֻמִּֽים׃","hé֛n ʻé֥d lĕʼẇmi֖̇ym nĕţaţi֑̇y⁠w nági֥yd ẇ⁠mĕẕawé֖̇h lĕʼumiֽ̇ym׃"],[55,5,"הֵ֣ן גּ֤וֹי לֹֽא־תֵדַע֙ תִּקְרָ֔א וְ⁠ג֥וֹי לֹֽא־יְדָע֖וּ⁠ךָ אֵלֶ֣י⁠ךָ יָר֑וּצוּ לְמַ֨עַן֙ יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ וְ⁠לִ⁠קְד֥וֹשׁ יִשְׂרָאֵ֖ל כִּ֥י פֵאֲרָֽ⁠ךְ׃ס","hé֣n ġ֤wòy lòֽʼ-ţédaʻ֙ ţi̇qĕrá֔ʼ wĕ⁠g֥wòy lòֽʼ-yĕdáʻ֖ẇ⁠ká ʼéle֣y⁠ká yár֑ẇẕẇ lĕma֨ʻan֙ yĕhwá֣h ʼèlòhe֔y⁠ká wĕ⁠li⁠qĕd֥wòş̌ yişĕ̂ráʼé֖l ki֥̇y péʼàráֽ⁠kĕ׃s"],[55,6,"דִּרְשׁ֥וּ יְהוָ֖ה בְּ⁠הִמָּצְא֑⁠וֹ קְרָאֻ֖⁠הוּ בִּֽ⁠הְיוֹת֥⁠וֹ קָרֽוֹב׃","di̇rĕş֥̌ẇ yĕhwá֖h bĕ̇⁠himá̇ẕĕʼ֑⁠wò qĕráʼu֖⁠hẇ biֽ̇⁠hĕywòţ֥⁠wò qárֽwòb׃"],[55,7,"יַעֲזֹ֤ב רָשָׁע֙ דַּרְכּ֔⁠וֹ וְ⁠אִ֥ישׁ אָ֖וֶן מַחְשְׁבֹתָ֑י⁠ו וְ⁠יָשֹׁ֤ב אֶל־יְהוָה֙ וִֽ⁠ירַחֲמֵ֔⁠הוּ וְ⁠אֶל־אֱלֹהֵ֖י⁠נוּ כִּֽי־יַרְבֶּ֥ה לִ⁠סְלֽוֹחַ׃","yaʻàzò֤b ráşá̌ʻ֙ dȧrĕk̇֔⁠wò wĕ⁠ʼi֥yş̌ ʼá֖wen maẖĕşĕ̌bòţá֑y⁠w wĕ⁠yáşò֤̌b ʼel-yĕhwáh֙ wiֽ⁠yraẖàmé֔⁠hẇ wĕ⁠ʼel-ʼèlòhé֖y⁠nẇ kiֽ̇y-yarĕbė֥h li⁠sĕlֽwòẖa׃"],[55,8,"כִּ֣י לֹ֤א מַחְשְׁבוֹתַ⁠י֙ מַחְשְׁב֣וֹתֵי⁠כֶ֔ם וְ⁠לֹ֥א דַרְכֵי⁠כֶ֖ם דְּרָכָ֑⁠י נְאֻ֖ם יְהוָֽה׃","ki֣̇y lò֤ʼ maẖĕşĕ̌bwòţa⁠y֙ maẖĕşĕ̌b֣wòţéy⁠ke֔m wĕ⁠lò֥ʼ darĕkéy⁠ke֖m dĕ̇ráká֑⁠y nĕʼu֖m yĕhwáֽh׃"],[55,9,"כִּֽי־גָבְה֥וּ שָׁמַ֖יִם מֵ⁠אָ֑רֶץ כֵּ֣ן גָּבְה֤וּ דְרָכַ⁠י֙ מִ⁠דַּרְכֵי⁠כֶ֔ם וּ⁠מַחְשְׁבֹתַ֖⁠י מִ⁠מַּחְשְׁבֹתֵי⁠כֶֽם׃","kiֽ̇y-gábĕh֥ẇ şá̌ma֖yim mé⁠ʼá֑reẕ ké֣̇n gá̇bĕh֤ẇ dĕráka⁠y֙ mi⁠dȧrĕkéy⁠ke֔m ẇ⁠maẖĕşĕ̌bòţa֖⁠y mi⁠mȧẖĕşĕ̌bòţéy⁠keֽm׃"],[55,10,"כִּ֡י כַּ⁠אֲשֶׁ֣ר יֵרֵד֩ הַ⁠גֶּ֨שֶׁם וְ⁠הַ⁠שֶּׁ֜לֶג מִן־הַ⁠שָּׁמַ֗יִם וְ⁠שָׁ֨מָּ⁠ה֙ לֹ֣א יָשׁ֔וּב כִּ֚י אִם־הִרְוָ֣ה אֶת־הָ⁠אָ֔רֶץ וְ⁠הוֹלִידָ֖⁠הּ וְ⁠הִצְמִיחָ֑⁠הּ וְ⁠נָ֤תַן זֶ֨רַע֙ לַ⁠זֹּרֵ֔עַ וְ⁠לֶ֖חֶם לָ⁠אֹכֵֽל׃","ki̇֡y kȧ⁠ʼàşě֣r yéréd֩ ha⁠gė֨şěm wĕ⁠ha⁠şė̌֜leg min-ha⁠şá̇̌ma֗yim wĕ⁠şá̌֨má̇⁠h֙ lò֣ʼ yáş̌֔ẇb ki֚̇y ʼim-hirĕwá֣h ʼeţ-há⁠ʼá֔reẕ wĕ⁠hwòliydá֖⁠ḣ wĕ⁠hiẕĕmiyẖá֑⁠ḣ wĕ⁠ná֤ţan ze֨raʻ֙ la⁠zò̇ré֔ʻa wĕ⁠le֖ẖem lá⁠ʼòkéֽl׃"],[55,11,"כֵּ֣ן יִֽהְיֶ֤ה דְבָרִ⁠י֙ אֲשֶׁ֣ר יֵצֵ֣א מִ⁠פִּ֔⁠י לֹֽא־יָשׁ֥וּב אֵלַ֖⁠י רֵיקָ֑ם כִּ֤י אִם־עָשָׂה֙ אֶת־אֲשֶׁ֣ר חָפַ֔צְתִּי וְ⁠הִצְלִ֖יחַ אֲשֶׁ֥ר שְׁלַחְתִּֽי⁠ו׃","ké֣̇n yiֽhĕye֤h dĕbári⁠y֙ ʼàşě֣r yéẕé֣ʼ mi⁠pi̇֔⁠y lòֽʼ-yáş֥̌ẇb ʼéla֖⁠y réyqá֑m ki֤̇y ʼim-ʻáşá̂h֙ ʼeţ-ʼàşě֣r ẖápa֔ẕĕţi̇y wĕ⁠hiẕĕli֖yẖa ʼàşě֥r şĕ̌laẖĕţiֽ̇y⁠w׃"],[55,12,"כִּֽי־בְ⁠שִׂמְחָ֣ה תֵצֵ֔אוּ וּ⁠בְ⁠שָׁל֖וֹם תּֽוּבָל֑וּ⁠ן הֶ⁠הָרִ֣ים וְ⁠הַ⁠גְּבָע֗וֹת יִפְצְח֤וּ לִ⁠פְנֵי⁠כֶם֙ רִנָּ֔ה וְ⁠כָל־עֲצֵ֥י הַ⁠שָּׂדֶ֖ה יִמְחֲאוּ־כָֽף׃","kiֽ̇y-bĕ⁠şîmĕẖá֣h ţéẕé֔ʼẇ ẇ⁠bĕ⁠şá̌l֖wòm ţֽ̇ẇbál֑ẇ⁠n he⁠hári֣ym wĕ⁠ha⁠gĕ̇báʻ֗wòţ yipĕẕĕẖ֤ẇ li⁠pĕnéy⁠kem֙ riná̇֔h wĕ⁠kál-ʻàẕé֥y ha⁠şá̇̂de֖h yimĕẖàʼẇ-káֽp׃"],[55,13,"תַּ֤חַת הַֽ⁠נַּעֲצוּץ֙ יַעֲלֶ֣ה בְר֔וֹשׁ תחת הַ⁠סִּרְפַּ֖ד יַעֲלֶ֣ה הֲדַ֑ס וְ⁠הָיָ֤ה לַֽ⁠יהוָה֙ לְ⁠שֵׁ֔ם לְ⁠א֥וֹת עוֹלָ֖ם לֹ֥א יִכָּרֵֽת׃ס","ţȧ֤ẖaţ haֽ⁠nȧʻàẕẇẕ֙ yaʻàle֣h bĕr֔wòş̌ ţẖţ ha⁠si̇rĕpȧ֖d yaʻàle֣h hàda֑s wĕ⁠háyá֤h laֽ⁠yhwáh֙ lĕ⁠şé̌֔m lĕ⁠ʼ֥wòţ ʻwòlá֖m lò֥ʼ yiká̇réֽţ׃s"],[56,1,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה שִׁמְר֥וּ מִשְׁפָּ֖ט וַ⁠עֲשׂ֣וּ צְדָקָ֑ה כִּֽי־קְרוֹבָ֤ה יְשֽׁוּעָתִ⁠י֙ לָ⁠ב֔וֹא וְ⁠צִדְקָתִ֖⁠י לְ⁠הִגָּלֽוֹת׃","kò֚̇h ʼáma֣r yĕhwá֔h şǐmĕr֥ẇ mişĕ̌pá֖̇t wa⁠ʻàş֣̂ẇ ẕĕdáqá֑h kiֽ̇y-qĕrwòbá֤h yĕşֽ̌ẇʻáţi⁠y֙ lá⁠b֔wòʼ wĕ⁠ẕidĕqáţi֖⁠y lĕ⁠higá̇lֽwòţ׃"],[56,2,"אַשְׁרֵ֤י אֱנוֹשׁ֙ יַעֲשֶׂה־זֹּ֔את וּ⁠בֶן־אָדָ֖ם יַחֲזִ֣יק בָּ֑⁠הּ שֹׁמֵ֤ר שַׁבָּת֙ מֵֽ⁠חַלְּל֔⁠וֹ וְ⁠שֹׁמֵ֥ר יָד֖⁠וֹ מֵ⁠עֲשׂ֥וֹת כָּל־רָֽע׃ס","ʼaşĕ̌ré֤y ʼènwòş̌֙ yaʻàşêh-zò̇֔ʼţ ẇ⁠ben-ʼádá֖m yaẖàzi֣yq bá֑̇⁠ḣ şò̌mé֤r şǎbá̇ţ֙ méֽ⁠ẖalĕ̇l֔⁠wò wĕ⁠şò̌mé֥r yád֖⁠wò mé⁠ʻàş֥̂wòţ ká̇l-ráֽʻ׃s"],[56,3,"וְ⁠אַל־יֹאמַ֣ר בֶּן־הַ⁠נֵּכָ֗ר הַ⁠נִּלְוָ֤ה אֶל־יְהוָה֙ לֵ⁠אמֹ֔ר הַבְדֵּ֧ל יַבְדִּילַ֛⁠נִי יְהוָ֖ה מֵ⁠עַ֣ל עַמּ֑⁠וֹ וְ⁠אַל־יֹאמַר֙ הַ⁠סָּרִ֔יס הֵ֥ן אֲנִ֖י עֵ֥ץ יָבֵֽשׁ׃ס","wĕ⁠ʼal-yòʼma֣r bėn-ha⁠né̇ká֗r ha⁠ni̇lĕwá֤h ʼel-yĕhwáh֙ lé⁠ʼmò֔r habĕdé֧̇l yabĕdi̇yla֛⁠niy yĕhwá֖h mé⁠ʻa֣l ʻaṁ֑⁠wò wĕ⁠ʼal-yòʼmar֙ ha⁠sá̇ri֔ys hé֥n ʼàni֖y ʻé֥ẕ yábéֽş̌׃s"],[56,4,"כִּי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה לַ⁠סָּֽרִיסִים֙ אֲשֶׁ֤ר יִשְׁמְרוּ֙ אֶת־שַׁבְּתוֹתַ֔⁠י וּ⁠בָֽחֲר֖וּ בַּ⁠אֲשֶׁ֣ר חָפָ֑צְתִּי וּ⁠מַחֲזִיקִ֖ים בִּ⁠בְרִיתִֽ⁠י׃","ki̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h la⁠sáֽ̇riysiym֙ ʼàşě֤r yişĕ̌mĕrẇ֙ ʼeţ-şǎbĕ̇ţwòţa֔⁠y ẇ⁠báֽẖàr֖ẇ bȧ⁠ʼàşě֣r ẖápá֑ẕĕţi̇y ẇ⁠maẖàziyqi֖ym bi̇⁠bĕriyţiֽ⁠y׃"],[56,5,"וְ⁠נָתַתִּ֨י לָ⁠הֶ֜ם בְּ⁠בֵיתִ֤⁠י וּ⁠בְ⁠חֽוֹמֹתַ⁠י֙ יָ֣ד וָ⁠שֵׁ֔ם ט֖וֹב מִ⁠בָּנִ֣ים וּ⁠מִ⁠בָּנ֑וֹת שֵׁ֤ם עוֹלָם֙ אֶתֶּן־ל֔⁠וֹ אֲשֶׁ֖ר לֹ֥א יִכָּרֵֽת׃ס","wĕ⁠náţaţi̇֨y lá⁠he֜m bĕ̇⁠béyţi֤⁠y ẇ⁠bĕ⁠ẖֽwòmòţa⁠y֙ yá֣d wá⁠şé̌֔m t֖wòb mi⁠bá̇ni֣ym ẇ⁠mi⁠bá̇n֑wòţ şé֤̌m ʻwòlám֙ ʼeţėn-l֔⁠wò ʼàşě֖r lò֥ʼ yiká̇réֽţ׃s"],[56,6,"וּ⁠בְנֵ֣י הַ⁠נֵּכָ֗ר הַ⁠נִּלְוִ֤ים עַל־יְהוָה֙ לְ⁠שָׁ֣רְת֔⁠וֹ וּֽ⁠לְ⁠אַהֲבָה֙ אֶת־שֵׁ֣ם יְהוָ֔ה לִ⁠הְי֥וֹת ל֖⁠וֹ לַ⁠עֲבָדִ֑ים כָּל־שֹׁמֵ֤ר שַׁבָּת֙ מֵֽ⁠חַלְּל֔⁠וֹ וּ⁠מַחֲזִיקִ֖ים בִּ⁠בְרִיתִֽ⁠י׃","ẇ⁠bĕné֣y ha⁠né̇ká֗r ha⁠ni̇lĕwi֤ym ʻal-yĕhwáh֙ lĕ⁠şá֣̌rĕţ֔⁠wò ẇֽ⁠lĕ⁠ʼahàbáh֙ ʼeţ-şé֣̌m yĕhwá֔h li⁠hĕy֥wòţ l֖⁠wò la⁠ʻàbádi֑ym ká̇l-şò̌mé֤r şǎbá̇ţ֙ méֽ⁠ẖalĕ̇l֔⁠wò ẇ⁠maẖàziyqi֖ym bi̇⁠bĕriyţiֽ⁠y׃"],[56,7,"וַ⁠הֲבִיאוֹתִ֞י⁠ם אֶל־הַ֣ר קָדְשִׁ֗⁠י וְ⁠שִׂמַּחְתִּי⁠ם֙ בְּ⁠בֵ֣ית תְּפִלָּתִ֔⁠י עוֹלֹתֵי⁠הֶ֧ם וְ⁠זִבְחֵי⁠הֶ֛ם לְ⁠רָצ֖וֹן עַֽל־מִזְבְּחִ֑⁠י כִּ֣י בֵיתִ֔⁠י בֵּית־תְּפִלָּ֥ה יִקָּרֵ֖א לְ⁠כָל־הָ⁠עַמִּֽים׃","wa⁠hàbiyʼwòţi֞y⁠m ʼel-ha֣r qádĕşǐ֗⁠y wĕ⁠şîmȧẖĕţi̇y⁠m֙ bĕ̇⁠bé֣yţ ţĕ̇pilá̇ţi֔⁠y ʻwòlòţéy⁠he֧m wĕ⁠zibĕẖéy⁠he֛m lĕ⁠ráẕ֖wòn ʻaֽl-mizĕbĕ̇ẖi֑⁠y ki֣̇y béyţi֔⁠y bé̇yţ-ţĕ̇pilá֥̇h yiqá̇ré֖ʼ lĕ⁠kál-há⁠ʻamiֽ̇ym׃"],[56,8,"נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה מְקַבֵּ֖ץ נִדְחֵ֣י יִשְׂרָאֵ֑ל ע֛וֹד אֲקַבֵּ֥ץ עָלָ֖י⁠ו לְ⁠נִקְבָּצָֽי⁠ו׃","nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h mĕqabé֖̇ẕ nidĕẖé֣y yişĕ̂ráʼé֑l ʻ֛wòd ʼàqabé֥̇ẕ ʻálá֖y⁠w lĕ⁠niqĕbá̇ẕáֽy⁠w׃"],[56,9,"כֹּ֖ל חַיְת֣וֹ שָׂדָ֑י אֵתָ֕יוּ לֶ⁠אֱכֹ֥ל כָּל־חַיְת֖וֹ בַּ⁠יָּֽעַר׃ס","kò֖̇l ẖayĕţ֣wò şá̂dá֑y ʼéţá֕yẇ le⁠ʼèkò֥l ká̇l-ẖayĕţ֖wò bȧ⁠yáֽ̇ʻar׃s"],[56,10,"צפו עִוְרִ֤ים כֻּלָּ⁠ם֙ לֹ֣א יָדָ֔עוּ כֻּלָּ⁠ם֙ כְּלָבִ֣ים אִלְּמִ֔ים לֹ֥א יוּכְל֖וּ לִ⁠נְבֹּ֑חַ הֹזִים֙ שֹֽׁכְבִ֔ים אֹהֲבֵ֖י לָ⁠נֽוּם׃","ẕpw ʻiwĕri֤ym ku̇lá̇⁠m֙ lò֣ʼ yádá֔ʻẇ ku̇lá̇⁠m֙ kĕ̇lábi֣ym ʼilĕ̇mi֔ym lò֥ʼ yẇkĕl֖ẇ li⁠nĕbò֑̇ẖa hòziym֙ şòֽ̌kĕbi֔ym ʼòhàbé֖y lá⁠nֽẇm׃"],[56,11,"וְ⁠הַ⁠כְּלָבִ֣ים עַזֵּי־נֶ֗פֶשׁ לֹ֤א יָֽדְעוּ֙ שָׂבְעָ֔ה וְ⁠הֵ֣מָּה רֹעִ֔ים לֹ֥א יָדְע֖וּ הָבִ֑ין כֻּלָּ⁠ם֙ לְ⁠דַרְכָּ֣⁠ם פָּנ֔וּ אִ֥ישׁ לְ⁠בִצְע֖⁠וֹ מִ⁠קָּצֵֽ⁠הוּ׃","wĕ⁠ha⁠kĕ̇lábi֣ym ʻazé̇y-ne֗peş̌ lò֤ʼ yáֽdĕʻẇ֙ şá̂bĕʻá֔h wĕ⁠hé֣má̇h ròʻi֔ym lò֥ʼ yádĕʻ֖ẇ hábi֑yn ku̇lá̇⁠m֙ lĕ⁠darĕká֣̇⁠m pá̇n֔ẇ ʼi֥yş̌ lĕ⁠biẕĕʻ֖⁠wò mi⁠qá̇ẕéֽ⁠hẇ׃"],[56,12,"אֵתָ֥יוּ אֶקְחָה־יַ֖יִן וְ⁠נִסְבְּאָ֣ה שֵׁכָ֑ר וְ⁠הָיָ֤ה כָ⁠זֶה֙ י֣וֹם מָחָ֔ר גָּד֖וֹל יֶ֥תֶר מְאֹֽד׃","ʼéţá֥yẇ ʼeqĕẖáh-ya֖yin wĕ⁠nisĕbĕ̇ʼá֣h şé̌ká֑r wĕ⁠háyá֤h ká⁠zeh֙ y֣wòm máẖá֔r gá̇d֖wòl ye֥ţer mĕʼòֽd׃"],[57,1,"הַ⁠צַּדִּ֣יק אָבָ֔ד וְ⁠אֵ֥ין אִ֖ישׁ שָׂ֣ם עַל־לֵ֑ב וְ⁠אַנְשֵׁי־חֶ֤סֶד נֶֽאֱסָפִים֙ בְּ⁠אֵ֣ין מֵבִ֔ין כִּֽי־מִ⁠פְּנֵ֥י הָ⁠רָעָ֖ה נֶאֱסַ֥ף הַ⁠צַּדִּֽיק׃","ha⁠ẕȧdi֣̇yq ʼábá֔d wĕ⁠ʼé֥yn ʼi֖yş̌ şá֣̂m ʻal-lé֑b wĕ⁠ʼanĕşé̌y-ẖe֤sed neֽʼèsápiym֙ bĕ̇⁠ʼé֣yn mébi֔yn kiֽ̇y-mi⁠pĕ̇né֥y há⁠ráʻá֖h neʼèsa֥p ha⁠ẕȧdiֽ̇yq׃"],[57,2,"יָב֣וֹא שָׁל֔וֹם יָנ֖וּחוּ עַל־מִשְׁכְּבוֹתָ֑⁠ם הֹלֵ֖ךְ נְכֹחֽ⁠וֹ׃","yáb֣wòʼ şá̌l֔wòm yán֖ẇẖẇ ʻal-mişĕ̌kĕ̇bwòţá֑⁠m hòlé֖kĕ nĕkòẖֽ⁠wò׃"],[57,3,"וְ⁠אַתֶּ֥ם קִרְבוּ־הֵ֖נָּה בְּנֵ֣י עֹנְנָ֑ה זֶ֥רַע מְנָאֵ֖ף וַ⁠תִּזְנֶֽה׃","wĕ⁠ʼaţė֥m qirĕbẇ-hé֖ná̇h bĕ̇né֣y ʻònĕná֑h ze֥raʻ mĕnáʼé֖p wa⁠ţi̇zĕneֽh׃"],[57,4,"עַל־מִי֙ תִּתְעַנָּ֔גוּ עַל־מִ֛י תַּרְחִ֥יבוּ פֶ֖ה תַּאֲרִ֣יכוּ לָשׁ֑וֹן הֲ⁠לֽוֹא־אַתֶּ֥ם יִלְדֵי־פֶ֖שַׁע זֶ֥רַע שָֽׁקֶר׃","ʻal-miy֙ ţi̇ţĕʻaná̇֔gẇ ʻal-mi֛y ţȧrĕẖi֥ybẇ pe֖h ţȧʼàri֣ykẇ láş֑̌wòn hà⁠lֽwòʼ-ʼaţė֥m yilĕdéy-pe֖şǎʻ ze֥raʻ şáֽ̌qer׃"],[57,5,"הַ⁠נֵּֽחָמִים֙ בָּֽ⁠אֵלִ֔ים תַּ֖חַת כָּל־עֵ֣ץ רַעֲנָ֑ן שֹׁחֲטֵ֤י הַ⁠יְלָדִים֙ בַּ⁠נְּחָלִ֔ים תַּ֖חַת סְעִפֵ֥י הַ⁠סְּלָעִֽים׃","ha⁠néֽ̇ẖámiym֙ báֽ̇⁠ʼéli֔ym ţȧ֖ẖaţ ká̇l-ʻé֣ẕ raʻàná֑n şò̌ẖàté֤y ha⁠yĕládiym֙ bȧ⁠nĕ̇ẖáli֔ym ţȧ֖ẖaţ sĕʻipé֥y ha⁠sĕ̇láʻiֽym׃"],[57,6,"בְּ⁠חַלְּקֵי־נַ֣חַל חֶלְקֵ֔⁠ךְ הֵ֥ם הֵ֖ם גּוֹרָלֵ֑⁠ךְ גַּם־לָ⁠הֶ֞ם שָׁפַ֥כְתְּ נֶ֨סֶךְ֙ הֶעֱלִ֣ית מִנְחָ֔ה הַ֥⁠עַל אֵ֖לֶּה אֶנָּחֵֽם׃","bĕ̇⁠ẖalĕ̇qéy-na֣ẖal ẖelĕqé֔⁠kĕ hé֥m hé֖m ġwòrálé֑⁠kĕ gȧm-lá⁠he֞m şá̌pa֥kĕţĕ̇ ne֨sekĕ֙ heʻèli֣yţ minĕẖá֔h ha֥⁠ʻal ʼé֖lėh ʼená̇ẖéֽm׃"],[57,7,"עַ֤ל הַר־גָּבֹ֨הַּ֙ וְ⁠נִשָּׂ֔א שַׂ֖מְתְּ מִשְׁכָּבֵ֑⁠ךְ גַּם־שָׁ֥ם עָלִ֖ית לִ⁠זְבֹּ֥חַ זָֽבַח׃","ʻa֤l har-gá̇bò֨hȧ֙ wĕ⁠nişá̇̂֔ʼ şâ֖mĕţĕ̇ mişĕ̌ká̇bé֑⁠kĕ gȧm-şá֥̌m ʻáli֖yţ li⁠zĕbò֥̇ẖa záֽbaẖ׃"],[57,8,"וְ⁠אַחַ֤ר הַ⁠דֶּ֨לֶת֙ וְ⁠הַ⁠מְּזוּזָ֔ה שַׂ֖מְתְּ זִכְרוֹנֵ֑⁠ךְ כִּ֣י מֵ⁠אִתִּ֞⁠י גִּלִּ֣ית וַֽ⁠תַּעֲלִ֗י הִרְחַ֤בְתְּ מִשְׁכָּבֵ⁠ךְ֙ וַ⁠תִּכְרָת־לָ֣⁠ךְ מֵ⁠הֶ֔ם אָהַ֥בְתְּ מִשְׁכָּבָ֖⁠ם יָ֥ד חָזִֽית׃","wĕ⁠ʼaẖa֤r ha⁠dė֨leţ֙ wĕ⁠ha⁠mĕ̇zẇzá֔h şâ֖mĕţĕ̇ zikĕrwòné֑⁠kĕ ki֣̇y mé⁠ʼiţi̇֞⁠y gi̇li֣̇yţ waֽ⁠ţȧʻàli֗y hirĕẖa֤bĕţĕ̇ mişĕ̌ká̇bé⁠kĕ֙ wa⁠ţi̇kĕráţ-lá֣⁠kĕ mé⁠he֔m ʼáha֥bĕţĕ̇ mişĕ̌ká̇bá֖⁠m yá֥d ẖáziֽyţ׃"],[57,9,"וַ⁠תָּשֻׁ֤רִי לַ⁠מֶּ֨לֶךְ֙ בַּ⁠שֶּׁ֔מֶן וַ⁠תַּרְבִּ֖י רִקֻּחָ֑יִ⁠ךְ וַ⁠תְּשַׁלְּחִ֤י צִרַ֨יִ⁠ךְ֙ עַד־מֵ֣⁠רָחֹ֔ק וַ⁠תַּשְׁפִּ֖ילִי עַד־שְׁאֽוֹל׃","wa⁠ţá̇şǔ֤riy la⁠mė֨lekĕ֙ bȧ⁠şė̌֔men wa⁠ţȧrĕbi֖̇y riqu̇ẖá֑yi⁠kĕ wa⁠ţĕ̇şǎlĕ̇ẖi֤y ẕira֨yi⁠kĕ֙ ʻad-mé֣⁠ráẖò֔q wa⁠ţȧşĕ̌pi֖̇yliy ʻad-şĕ̌ʼֽwòl׃"],[57,10,"בְּ⁠רֹ֤ב דַּרְכֵּ⁠ךְ֙ יָגַ֔עַתְּ לֹ֥א אָמַ֖רְתְּ נוֹאָ֑שׁ חַיַּ֤ת יָדֵ⁠ךְ֙ מָצָ֔את עַל־כֵּ֖ן לֹ֥א חָלִֽית׃","bĕ̇⁠rò֤b dȧrĕké̇⁠kĕ֙ yága֔ʻaţĕ̇ lò֥ʼ ʼáma֖rĕţĕ̇ nwòʼá֑ş̌ ẖayȧ֤ţ yádé⁠kĕ֙ máẕá֔ʼţ ʻal-ké֖̇n lò֥ʼ ẖáliֽyţ׃"],[57,11,"וְ⁠אֶת־מִ֞י דָּאַ֤גְתְּ וַ⁠תִּֽירְאִי֙ כִּ֣י תְכַזֵּ֔בִי וְ⁠אוֹתִ⁠י֙ לֹ֣א זָכַ֔רְתְּ לֹא־שַׂ֖מְתְּ עַל־לִבֵּ֑⁠ךְ הֲ⁠לֹ֨א אֲנִ֤י מַחְשֶׁה֙ וּ⁠מֵ֣⁠עֹלָ֔ם וְ⁠אוֹתִ֖⁠י לֹ֥א תִירָֽאִי׃","wĕ⁠ʼeţ-mi֞y dá̇ʼa֤gĕţĕ̇ wa⁠ţiֽ̇yrĕʼiy֙ ki֣̇y ţĕkazé̇֔biy wĕ⁠ʼwòţi⁠y֙ lò֣ʼ záka֔rĕţĕ̇ lòʼ-şâ֖mĕţĕ̇ ʻal-libé֑̇⁠kĕ hà⁠lò֨ʼ ʼàni֤y maẖĕşěh֙ ẇ⁠mé֣⁠ʻòlá֔m wĕ⁠ʼwòţi֖⁠y lò֥ʼ ţiyráֽʼiy׃"],[57,12,"אֲנִ֥י אַגִּ֖יד צִדְקָתֵ֑⁠ךְ וְ⁠אֶֽת־מַעֲשַׂ֖יִ⁠ךְ וְ⁠לֹ֥א יוֹעִילֽוּ⁠ךְ׃","ʼàni֥y ʼagi֖̇yd ẕidĕqáţé֑⁠kĕ wĕ⁠ʼeֽţ-maʻàşâ֖yi⁠kĕ wĕ⁠lò֥ʼ ywòʻiylֽẇ⁠kĕ׃"],[57,13,"בְּ⁠זַֽעֲקֵ⁠ךְ֙ יַצִּילֻ֣⁠ךְ קִבּוּצַ֔יִ⁠ךְ וְ⁠אֶת־כֻּלָּ֥⁠ם יִשָּׂא־ר֖וּחַ יִקַּח־הָ֑בֶל וְ⁠הַ⁠חוֹסֶ֥ה בִ⁠י֙ יִנְחַל־אֶ֔רֶץ וְ⁠יִירַ֖שׁ הַר־קָדְשִֽׁ⁠י׃","bĕ̇⁠zaֽʻàqé⁠kĕ֙ yaẕi̇ylu֣⁠kĕ qiḃẇẕa֔yi⁠kĕ wĕ⁠ʼeţ-ku̇lá֥̇⁠m yişá̇̂ʼ-r֖ẇẖa yiqȧẖ-há֑bel wĕ⁠ha⁠ẖwòse֥h bi⁠y֙ yinĕẖal-ʼe֔reẕ wĕ⁠yiyra֖ş̌ har-qádĕşǐֽ⁠y׃"],[57,14,"וְ⁠אָמַ֥ר סֹֽלּוּ־סֹ֖לּוּ פַּנּוּ־דָ֑רֶךְ הָרִ֥ימוּ מִכְשׁ֖וֹל מִ⁠דֶּ֥רֶךְ עַמִּֽ⁠י׃ס","wĕ⁠ʼáma֥r sòֽl̇ẇ-sò֖l̇ẇ pȧṅẇ-dá֑rekĕ hári֥ymẇ mikĕş֖̌wòl mi⁠dė֥rekĕ ʻamiֽ̇⁠y׃s"],[57,15,"כִּי֩ כֹ֨ה אָמַ֜ר רָ֣ם וְ⁠נִשָּׂ֗א שֹׁכֵ֥ן עַד֙ וְ⁠קָד֣וֹשׁ שְׁמ֔⁠וֹ מָר֥וֹם וְ⁠קָד֖וֹשׁ אֶשְׁכּ֑וֹן וְ⁠אֶת־דַּכָּא֙ וּ⁠שְׁפַל־ר֔וּחַ לְ⁠הַחֲיוֹת֙ ר֣וּחַ שְׁפָלִ֔ים וּֽ⁠לְ⁠הַחֲי֖וֹת לֵ֥ב נִדְכָּאִֽים׃","ki̇y֩ kò֨h ʼáma֜r rá֣m wĕ⁠nişá̇̂֗ʼ şò̌ké֥n ʻad֙ wĕ⁠qád֣wòş̌ şĕ̌m֔⁠wò már֥wòm wĕ⁠qád֖wòş̌ ʼeşĕ̌k֑̇wòn wĕ⁠ʼeţ-dȧká̇ʼ֙ ẇ⁠şĕ̌pal-r֔ẇẖa lĕ⁠haẖàywòţ֙ r֣ẇẖa şĕ̌páli֔ym ẇֽ⁠lĕ⁠haẖày֖wòţ lé֥b nidĕká̇ʼiֽym׃"],[57,16,"כִּ֣י לֹ֤א לְ⁠עוֹלָם֙ אָרִ֔יב וְ⁠לֹ֥א לָ⁠נֶ֖צַח אֶקְּצ֑וֹף כִּי־ר֨וּחַ֙ מִ⁠לְּ⁠פָנַ֣⁠י יַֽעֲט֔וֹף וּ⁠נְשָׁמ֖וֹת אֲנִ֥י עָשִֽׂיתִי׃","ki֣̇y lò֤ʼ lĕ⁠ʻwòlám֙ ʼári֔yb wĕ⁠lò֥ʼ lá⁠ne֖ẕaẖ ʼeqĕ̇ẕ֑wòp ki̇y-r֨ẇẖa֙ mi⁠lĕ̇⁠pána֣⁠y yaֽʻàt֔wòp ẇ⁠nĕşá̌m֖wòţ ʼàni֥y ʻáşîֽyţiy׃"],[57,17,"בַּ⁠עֲוֺ֥ן בִּצְע֛⁠וֹ קָצַ֥פְתִּי וְ⁠אַכֵּ֖⁠הוּ הַסְתֵּ֣ר וְ⁠אֶקְצֹ֑ף וַ⁠יֵּ֥לֶךְ שׁוֹבָ֖ב בְּ⁠דֶ֥רֶךְ לִבּֽ⁠וֹ׃","bȧ⁠ʻàwֺ֥n bi̇ẕĕʻ֛⁠wò qáẕa֥pĕţi̇y wĕ⁠ʼaké֖̇⁠hẇ hasĕţé֣̇r wĕ⁠ʼeqĕẕò֑p wa⁠yé֥̇lekĕ ş̌wòbá֖b bĕ̇⁠de֥rekĕ liḃֽ⁠wò׃"],[57,18,"דְּרָכָ֥י⁠ו רָאִ֖יתִי וְ⁠אֶרְפָּאֵ֑⁠הוּ וְ⁠אַנְחֵ֕⁠הוּ וַ⁠אֲשַׁלֵּ֧ם נִֽחֻמִ֛ים ל֖⁠וֹ וְ⁠לַ⁠אֲבֵלָֽי⁠ו׃","dĕ̇ráká֥y⁠w ráʼi֖yţiy wĕ⁠ʼerĕpá̇ʼé֑⁠hẇ wĕ⁠ʼanĕẖé֕⁠hẇ wa⁠ʼàşǎlé֧̇m niֽẖumi֛ym l֖⁠wò wĕ⁠la⁠ʼàbéláֽy⁠w׃"],[57,19,"בּוֹרֵ֖א נוב שְׂפָתָ֑יִם שָׁל֨וֹם ׀ שָׁל֜וֹם לָ⁠רָח֧וֹק וְ⁠לַ⁠קָּר֛וֹב אָמַ֥ר יְהוָ֖ה וּ⁠רְפָאתִֽי⁠ו׃","ḃwòré֖ʼ nwb şĕ̂páţá֑yim şá̌l֨wòm ׀ şá̌l֜wòm lá⁠ráẖ֧wòq wĕ⁠la⁠qá̇r֛wòb ʼáma֥r yĕhwá֖h ẇ⁠rĕpáʼţiֽy⁠w׃"],[57,20,"וְ⁠הָ⁠רְשָׁעִ֖ים כַּ⁠יָּ֣ם נִגְרָ֑שׁ כִּ֤י הַשְׁקֵט֙ לֹ֣א יוּכָ֔ל וַ⁠יִּגְרְשׁ֥וּ מֵימָ֖י⁠ו רֶ֥פֶשׁ וָ⁠טִֽיט׃","wĕ⁠há⁠rĕşá̌ʻi֖ym kȧ⁠yá֣̇m nigĕrá֑ş̌ ki֤̇y haşĕ̌qét֙ lò֣ʼ yẇká֔l wa⁠yi̇gĕrĕş֥̌ẇ méymá֖y⁠w re֥peş̌ wá⁠tiֽyt׃"],[57,21,"אֵ֣ין שָׁל֔וֹם אָמַ֥ר אֱלֹהַ֖⁠י לָ⁠רְשָׁעִֽים׃ס","ʼé֣yn şá̌l֔wòm ʼáma֥r ʼèlòha֖⁠y lá⁠rĕşá̌ʻiֽym׃s"],[58,1,"קְרָ֤א בְ⁠גָרוֹן֙ אַל־תַּחְשֹׂ֔ךְ כַּ⁠שּׁוֹפָ֖ר הָרֵ֣ם קוֹלֶ֑⁠ךָ וְ⁠הַגֵּ֤ד לְ⁠עַמִּ⁠י֙ פִּשְׁעָ֔⁠ם וּ⁠לְ⁠בֵ֥ית יַעֲקֹ֖ב חַטֹּאתָֽ⁠ם׃","qĕrá֤ʼ bĕ⁠gárwòn֙ ʼal-ţȧẖĕşò̂֔kĕ kȧ⁠ş̇̌wòpá֖r háré֣m qwòle֑⁠ká wĕ⁠hagé֤̇d lĕ⁠ʻami̇⁠y֙ pi̇şĕ̌ʻá֔⁠m ẇ⁠lĕ⁠bé֥yţ yaʻàqò֖b ẖatò̇ʼţáֽ⁠m׃"],[58,2,"וְ⁠אוֹתִ֗⁠י י֥וֹם יוֹם֙ יִדְרֹשׁ֔וּ⁠ן וְ⁠דַ֥עַת דְּרָכַ֖⁠י יֶחְפָּצ֑וּ⁠ן כְּ⁠ג֞וֹי אֲשֶׁר־צְדָקָ֣ה עָשָׂ֗ה וּ⁠מִשְׁפַּ֤ט אֱלֹהָי⁠ו֙ לֹ֣א עָזָ֔ב יִשְׁאָל֨וּ⁠נִי֙ מִשְׁפְּטֵי־צֶ֔דֶק קִרְבַ֥ת אֱלֹהִ֖ים יֶחְפָּצֽוּ⁠ן׃","wĕ⁠ʼwòţi֗⁠y y֥wòm ywòm֙ yidĕròş̌֔ẇ⁠n wĕ⁠da֥ʻaţ dĕ̇ráka֖⁠y yeẖĕpá̇ẕ֑ẇ⁠n kĕ̇⁠g֞wòy ʼàşěr-ẕĕdáqá֣h ʻáşá̂֗h ẇ⁠mişĕ̌pȧ֤t ʼèlòháy⁠w֙ lò֣ʼ ʻázá֔b yişĕ̌ʼál֨ẇ⁠niy֙ mişĕ̌pĕ̇téy-ẕe֔deq qirĕba֥ţ ʼèlòhi֖ym yeẖĕpá̇ẕֽẇ⁠n׃"],[58,3,"לָ֤⁠מָּה צַּ֨מְנוּ֙ וְ⁠לֹ֣א רָאִ֔יתָ עִנִּ֥ינוּ נַפְשֵׁ֖⁠נוּ וְ⁠לֹ֣א תֵדָ֑ע הֵ֣ן בְּ⁠י֤וֹם צֹֽמְ⁠כֶם֙ תִּמְצְאוּ־חֵ֔פֶץ וְ⁠כָל־עַצְּבֵי⁠כֶ֖ם תִּנְגֹּֽשׂוּ׃","lá֤⁠má̇h ẕȧ֨mĕnẇ֙ wĕ⁠lò֣ʼ ráʼi֔yţá ʻini֥̇ynẇ napĕşé֖̌⁠nẇ wĕ⁠lò֣ʼ ţédá֑ʻ hé֣n bĕ̇⁠y֤wòm ẕòֽmĕ⁠kem֙ ţi̇mĕẕĕʼẇ-ẖé֔peẕ wĕ⁠kál-ʻaẕĕ̇béy⁠ke֖m ţi̇nĕgòֽ̇ş̂ẇ׃"],[58,4,"הֵ֣ן לְ⁠רִ֤יב וּ⁠מַצָּה֙ תָּצ֔וּמוּ וּ⁠לְ⁠הַכּ֖וֹת בְּ⁠אֶגְרֹ֣ף רֶ֑שַׁע לֹא־תָצ֣וּמוּ כַ⁠יּ֔וֹם לְ⁠הַשְׁמִ֥יעַ בַּ⁠מָּר֖וֹם קוֹלְ⁠כֶֽם׃","hé֣n lĕ⁠ri֤yb ẇ⁠maẕá̇h֙ ţá̇ẕ֔ẇmẇ ẇ⁠lĕ⁠hak֖̇wòţ bĕ̇⁠ʼegĕrò֣p re֑şǎʻ lòʼ-ţáẕ֣ẇmẇ ka⁠ẏ֔wòm lĕ⁠haşĕ̌mi֥yʻa bȧ⁠má̇r֖wòm qwòlĕ⁠keֽm׃"],[58,5,"הֲ⁠כָ⁠זֶ֗ה יִֽהְיֶה֙ צ֣וֹם אֶבְחָרֵ֔⁠הוּ י֛וֹם עַנּ֥וֹת אָדָ֖ם נַפְשׁ֑⁠וֹ הֲ⁠לָ⁠כֹ֨ף כְּ⁠אַגְמֹ֜ן רֹאשׁ֗⁠וֹ וְ⁠שַׂ֤ק וָ⁠אֵ֨פֶר֙ יַצִּ֔יעַ הֲ⁠לָ⁠זֶה֙ תִּקְרָא־צ֔וֹם וְ⁠י֥וֹם רָצ֖וֹן לַ⁠יהוָֽה׃","hà⁠ká⁠ze֗h yiֽhĕyeh֙ ẕ֣wòm ʼebĕẖáré֔⁠hẇ y֛wòm ʻaṅ֥wòţ ʼádá֖m napĕş֑̌⁠wò hà⁠lá⁠kò֨p kĕ̇⁠ʼagĕmò֜n ròʼş̌֗⁠wò wĕ⁠şâ֤q wá⁠ʼé֨per֙ yaẕi̇֔yʻa hà⁠lá⁠zeh֙ ţi̇qĕráʼ-ẕ֔wòm wĕ⁠y֥wòm ráẕ֖wòn la⁠yhwáֽh׃"],[58,6,"הֲ⁠ל֣וֹא זֶה֮ צ֣וֹם אֶבְחָרֵ⁠הוּ֒ פַּתֵּ֨חַ֙ חַרְצֻבּ֣וֹת רֶ֔שַׁע הַתֵּ֖ר אֲגֻדּ֣וֹת מוֹטָ֑ה וְ⁠שַׁלַּ֤ח רְצוּצִים֙ חָפְשִׁ֔ים וְ⁠כָל־מוֹטָ֖ה תְּנַתֵּֽקוּ׃","hà⁠l֣wòʼ zeh֮ ẕ֣wòm ʼebĕẖáré⁠hẇ֒ pȧţé̇֨ẖa֙ ẖarĕẕuḃ֣wòţ re֔şǎʻ haţé֖̇r ʼàguḋ֣wòţ mwòtá֑h wĕ⁠şǎlȧ֤ẖ rĕẕẇẕiym֙ ẖápĕşǐ֔ym wĕ⁠kál-mwòtá֖h ţĕ̇naţéֽ̇qẇ׃"],[58,7,"הֲ⁠ל֨וֹא פָרֹ֤ס לָֽ⁠רָעֵב֙ לַחְמֶ֔⁠ךָ וַ⁠עֲנִיִּ֥ים מְרוּדִ֖ים תָּ֣בִיא בָ֑יִת כִּֽי־תִרְאֶ֤ה עָרֹם֙ וְ⁠כִסִּית֔⁠וֹ וּ⁠מִ⁠בְּשָׂרְ⁠ךָ֖ לֹ֥א תִתְעַלָּֽם׃","hà⁠l֨wòʼ párò֤s láֽ⁠ráʻéb֙ laẖĕme֔⁠ká wa⁠ʻàniyi֥̇ym mĕrẇdi֖ym ţá֣̇biyʼ bá֑yiţ kiֽ̇y-ţirĕʼe֤h ʻáròm֙ wĕ⁠kisi̇yţ֔⁠wò ẇ⁠mi⁠bĕ̇şá̂rĕ⁠ká֖ lò֥ʼ ţiţĕʻaláֽ̇m׃"],[58,8,"אָ֣ז יִבָּקַ֤ע כַּ⁠שַּׁ֨חַר֙ אוֹרֶ֔⁠ךָ וַ⁠אֲרֻכָתְ⁠ךָ֖ מְהֵרָ֣ה תִצְמָ֑ח וְ⁠הָלַ֤ךְ לְ⁠פָנֶ֨י⁠ךָ֙ צִדְקֶ֔⁠ךָ כְּב֥וֹד יְהוָ֖ה יַאַסְפֶֽ⁠ךָ׃","ʼá֣z yibá̇qa֤ʻ kȧ⁠şȧ̌֨ẖar֙ ʼwòre֔⁠ká wa⁠ʼàrukáţĕ⁠ká֖ mĕhérá֣h ţiẕĕmá֑ẖ wĕ⁠hála֤kĕ lĕ⁠páne֨y⁠ká֙ ẕidĕqe֔⁠ká kĕ̇b֥wòd yĕhwá֖h yaʼasĕpeֽ⁠ká׃"],[58,9,"אָ֤ז תִּקְרָא֙ וַ⁠יהוָ֣ה יַעֲנֶ֔ה תְּשַׁוַּ֖ע וְ⁠יֹאמַ֣ר הִנֵּ֑⁠נִי אִם־תָּסִ֤יר מִ⁠תּֽוֹכְ⁠ךָ֙ מוֹטָ֔ה שְׁלַ֥ח אֶצְבַּ֖ע וְ⁠דַבֶּר־אָֽוֶן׃","ʼá֤z ţi̇qĕráʼ֙ wa⁠yhwá֣h yaʻàne֔h ţĕ̇şǎwȧ֖ʻ wĕ⁠yòʼma֣r hiné֑̇⁠niy ʼim-ţá̇si֤yr mi⁠ţֽ̇wòkĕ⁠ká֙ mwòtá֔h şĕ̌la֥ẖ ʼeẕĕbȧ֖ʻ wĕ⁠dabėr-ʼáֽwen׃"],[58,10,"וְ⁠תָפֵ֤ק לָֽ⁠רָעֵב֙ נַפְשֶׁ֔⁠ךָ וְ⁠נֶ֥פֶשׁ נַעֲנָ֖ה תַּשְׂבִּ֑יעַ וְ⁠זָרַ֤ח בַּ⁠חֹ֨שֶׁךְ֙ אוֹרֶ֔⁠ךָ וַ⁠אֲפֵלָתְ⁠ךָ֖ כַּֽ⁠צָּהֳרָֽיִם׃","wĕ⁠ţápé֤q láֽ⁠ráʻéb֙ napĕşě֔⁠ká wĕ⁠ne֥peş̌ naʻàná֖h ţȧşĕ̂bi֑̇yʻa wĕ⁠zára֤ẖ bȧ⁠ẖò֨şěkĕ֙ ʼwòre֔⁠ká wa⁠ʼàpéláţĕ⁠ká֖ kȧֽ⁠ẕá̇horáֽyim׃"],[58,11,"וְ⁠נָחֲ⁠ךָ֣ יְהוָה֮ תָּמִיד֒ וְ⁠הִשְׂבִּ֤יעַ בְּ⁠צַחְצָחוֹת֙ נַפְשֶׁ֔⁠ךָ וְ⁠עַצְמֹתֶ֖י⁠ךָ יַחֲלִ֑יץ וְ⁠הָיִ֨יתָ֙ כְּ⁠גַ֣ן רָוֶ֔ה וּ⁠כְ⁠מוֹצָ֣א מַ֔יִם אֲשֶׁ֥ר לֹא־יְכַזְּב֖וּ מֵימָֽי⁠ו׃","wĕ⁠náẖà⁠ká֣ yĕhwáh֮ ţá̇miyd֒ wĕ⁠hişĕ̂bi֤̇yʻa bĕ̇⁠ẕaẖĕẕáẖwòţ֙ napĕşě֔⁠ká wĕ⁠ʻaẕĕmòţe֖y⁠ká yaẖàli֑yẕ wĕ⁠háyi֨yţá֙ kĕ̇⁠ga֣n ráwe֔h ẇ⁠kĕ⁠mwòẕá֣ʼ ma֔yim ʼàşě֥r lòʼ-yĕkazĕ̇b֖ẇ méymáֽy⁠w׃"],[58,12,"וּ⁠בָנ֤וּ מִמְּ⁠ךָ֙ חָרְב֣וֹת עוֹלָ֔ם מוֹסְדֵ֥י דוֹר־וָ⁠ד֖וֹר תְּקוֹמֵ֑ם וְ⁠קֹרָ֤א לְ⁠ךָ֙ גֹּדֵ֣ר פֶּ֔רֶץ מְשֹׁבֵ֥ב נְתִיב֖וֹת לָ⁠שָֽׁבֶת׃","ẇ⁠bán֤ẇ mimĕ̇⁠ká֙ ẖárĕb֣wòţ ʻwòlá֔m mwòsĕdé֥y dwòr-wá⁠d֖wòr ţĕ̇qwòmé֑m wĕ⁠qòrá֤ʼ lĕ⁠ká֙ gò̇dé֣r pė֔reẕ mĕşò̌bé֥b nĕţiyb֖wòţ lá⁠şáֽ̌beţ׃"],[58,13,"אִם־תָּשִׁ֤יב מִ⁠שַּׁבָּת֙ רַגְלֶ֔⁠ךָ עֲשׂ֥וֹת חֲפָצֶ֖י⁠ךָ בְּ⁠י֣וֹם קָדְשִׁ֑⁠י וְ⁠קָרָ֨אתָ לַ⁠שַּׁבָּ֜ת עֹ֗נֶג לִ⁠קְד֤וֹשׁ יְהוָה֙ מְכֻבָּ֔ד וְ⁠כִבַּדְתּ⁠וֹ֙ מֵ⁠עֲשׂ֣וֹת דְּרָכֶ֔י⁠ךָ מִ⁠מְּצ֥וֹא חֶפְצְ⁠ךָ֖ וְ⁠דַבֵּ֥ר דָּבָֽר׃","ʼim-ţá̇şǐ֤yb mi⁠şȧ̌bá̇ţ֙ ragĕle֔⁠ká ʻàş֥̂wòţ ẖàpáẕe֖y⁠ká bĕ̇⁠y֣wòm qádĕşǐ֑⁠y wĕ⁠qárá֨ʼţá la⁠şȧ̌bá̇֜ţ ʻò֗neg li⁠qĕd֤wòş̌ yĕhwáh֙ mĕkubá̇֔d wĕ⁠kibȧdĕţ̇⁠wò֙ mé⁠ʻàş֣̂wòţ dĕ̇ráke֔y⁠ká mi⁠mĕ̇ẕ֥wòʼ ẖepĕẕĕ⁠ká֖ wĕ⁠dabé֥̇r dá̇báֽr׃"],[58,14,"אָ֗ז תִּתְעַנַּג֙ עַל־יְהוָ֔ה וְ⁠הִרְכַּבְתִּ֖י⁠ךָ עַל־בָּ֣מֳותֵי אָ֑רֶץ וְ⁠הַאֲכַלְתִּ֗י⁠ךָ נַחֲלַת֙ יַעֲקֹ֣ב אָבִ֔י⁠ךָ כִּ֛י פִּ֥י יְהוָ֖ה דִּבֵּֽר׃ס","ʼá֗z ţi̇ţĕʻanȧg֙ ʻal-yĕhwá֔h wĕ⁠hirĕkȧbĕţi֖̇y⁠ká ʻal-bá֣̇mowţéy ʼá֑reẕ wĕ⁠haʼàkalĕţi̇֗y⁠ká naẖàlaţ֙ yaʻàqò֣b ʼábi֔y⁠ká ki֛̇y pi֥̇y yĕhwá֖h di̇béֽ̇r׃s"],[59,1,"הֵ֛ן לֹֽא־קָצְרָ֥ה יַד־יְהוָ֖ה מֵֽ⁠הוֹשִׁ֑יעַ וְ⁠לֹא־כָבְדָ֥ה אָזְנ֖⁠וֹ מִ⁠שְּׁמֽוֹעַ׃","hé֛n lòֽʼ-qáẕĕrá֥h yad-yĕhwá֖h méֽ⁠hwòşǐ֑yʻa wĕ⁠lòʼ-kábĕdá֥h ʼázĕn֖⁠wò mi⁠şĕ̇̌mֽwòʻa׃"],[59,2,"כִּ֤י אִם־עֲוֺנֹֽתֵי⁠כֶם֙ הָי֣וּ מַבְדִּלִ֔ים בֵּינֵ⁠כֶ֕ם לְ⁠בֵ֖ין אֱלֹֽהֵי⁠כֶ֑ם וְ⁠חַטֹּֽאותֵי⁠כֶ֗ם הִסְתִּ֧ירוּ פָנִ֛ים מִ⁠כֶּ֖ם מִ⁠שְּׁמֽוֹעַ׃","ki֤̇y ʼim-ʻàwֺnòֽţéy⁠kem֙ háy֣ẇ mabĕdi̇li֔ym bé̇yné⁠ke֕m lĕ⁠bé֖yn ʼèlòֽhéy⁠ke֑m wĕ⁠ẖatòֽ̇ʼwţéy⁠ke֗m hisĕţi֧̇yrẇ páni֛ym mi⁠kė֖m mi⁠şĕ̇̌mֽwòʻa׃"],[59,3,"כִּ֤י כַפֵּי⁠כֶם֙ נְגֹאֲל֣וּ בַ⁠דָּ֔ם וְ⁠אֶצְבְּעוֹתֵי⁠כֶ֖ם בֶּֽ⁠עָוֺ֑ן שִׂפְתֽוֹתֵי⁠כֶם֙ דִּבְּרוּ־שֶׁ֔קֶר לְשׁוֹנְ⁠כֶ֖ם עַוְלָ֥ה תֶהְגֶּֽה׃","ki֤̇y kapé̇y⁠kem֙ nĕgòʼàl֣ẇ ba⁠dá̇֔m wĕ⁠ʼeẕĕbĕ̇ʻwòţéy⁠ke֖m bėֽ⁠ʻáwֺ֑n şîpĕţֽwòţéy⁠kem֙ di̇bĕ̇rẇ-şě֔qer lĕş̌wònĕ⁠ke֖m ʻawĕlá֥h ţehĕgėֽh׃"],[59,4,"אֵין־קֹרֵ֣א בְ⁠צֶ֔דֶק וְ⁠אֵ֥ין נִשְׁפָּ֖ט בֶּ⁠אֱמוּנָ֑ה בָּט֤וֹחַ עַל־תֹּ֨הוּ֙ וְ⁠דַבֶּר־שָׁ֔וְא הָר֥וֹ עָמָ֖ל וְ⁠הוֹלֵ֥יד אָֽוֶן׃","ʼéyn-qòré֣ʼ bĕ⁠ẕe֔deq wĕ⁠ʼé֥yn nişĕ̌pá֖̇t bė⁠ʼèmẇná֑h bá̇t֤wòẖa ʻal-ţò̇֨hẇ֙ wĕ⁠dabėr-şá̌֔wĕʼ hár֥wò ʻámá֖l wĕ⁠hwòlé֥yd ʼáֽwen׃"],[59,5,"בֵּיצֵ֤י צִפְעוֹנִי֙ בִּקֵּ֔עוּ וְ⁠קוּרֵ֥י עַכָּבִ֖ישׁ יֶאֱרֹ֑גוּ הָ⁠אֹכֵ֤ל מִ⁠בֵּֽיצֵי⁠הֶם֙ יָמ֔וּת וְ⁠הַ⁠זּוּרֶ֖ה תִּבָּקַ֥ע אֶפְעֶֽה׃","bé̇yẕé֤y ẕipĕʻwòniy֙ bi̇qé̇֔ʻẇ wĕ⁠qẇré֥y ʻaká̇bi֖yş̌ yeʼèrò֑gẇ há⁠ʼòké֤l mi⁠béֽ̇yẕéy⁠hem֙ yám֔ẇţ wĕ⁠ha⁠żẇre֖h ţi̇bá̇qa֥ʻ ʼepĕʻeֽh׃"],[59,6,"קֽוּרֵי⁠הֶם֙ לֹא־יִהְי֣וּ לְ⁠בֶ֔גֶד וְ⁠לֹ֥א יִתְכַּסּ֖וּ בְּ⁠מַֽעֲשֵׂי⁠הֶ֑ם מַֽעֲשֵׂי⁠הֶם֙ מַֽעֲשֵׂי־אָ֔וֶן וּ⁠פֹ֥עַל חָמָ֖ס בְּ⁠כַפֵּי⁠הֶֽם׃","qֽẇréy⁠hem֙ lòʼ-yihĕy֣ẇ lĕ⁠be֔ged wĕ⁠lò֥ʼ yiţĕkȧṡ֖ẇ bĕ̇⁠maֽʻàşé̂y⁠he֑m maֽʻàşé̂y⁠hem֙ maֽʻàşé̂y-ʼá֔wen ẇ⁠pò֥ʻal ẖámá֖s bĕ̇⁠kapé̇y⁠heֽm׃"],[59,7,"רַגְלֵי⁠הֶם֙ לָ⁠רַ֣ע יָרֻ֔צוּ וִֽ⁠ימַהֲר֔וּ לִ⁠שְׁפֹּ֖ךְ דָּ֣ם נָקִ֑י מַחְשְׁבֽוֹתֵי⁠הֶם֙ מַחְשְׁב֣וֹת אָ֔וֶן שֹׁ֥ד וָ⁠שֶׁ֖בֶר בִּ⁠מְסִלּוֹתָֽ⁠ם׃","ragĕléy⁠hem֙ lá⁠ra֣ʻ yáru֔ẕẇ wiֽ⁠ymahàr֔ẇ li⁠şĕ̌pò֖̇kĕ dá֣̇m náqi֑y maẖĕşĕ̌bֽwòţéy⁠hem֙ maẖĕşĕ̌b֣wòţ ʼá֔wen şò֥̌d wá⁠şě֖ber bi̇⁠mĕsil̇wòţáֽ⁠m׃"],[59,8,"דֶּ֤רֶךְ שָׁלוֹם֙ לֹ֣א יָדָ֔עוּ וְ⁠אֵ֥ין מִשְׁפָּ֖ט בְּ⁠מַעְגְּלוֹתָ֑⁠ם נְתִיבֽוֹתֵי⁠הֶם֙ עִקְּשׁ֣וּ לָ⁠הֶ֔ם כֹּ֚ל דֹּרֵ֣ךְ בָּ֔⁠הּ לֹ֥א יָדַ֖ע שָׁלֽוֹם׃","dė֤rekĕ şá̌lwòm֙ lò֣ʼ yádá֔ʻẇ wĕ⁠ʼé֥yn mişĕ̌pá֖̇t bĕ̇⁠maʻĕgĕ̇lwòţá֑⁠m nĕţiybֽwòţéy⁠hem֙ ʻiqĕ̇ş֣̌ẇ lá⁠he֔m kò֚̇l dò̇ré֣kĕ bá̇֔⁠ḣ lò֥ʼ yáda֖ʻ şá̌lֽwòm׃"],[59,9,"עַל־כֵּ֗ן רָחַ֤ק מִשְׁפָּט֙ מִמֶּ֔⁠נּוּ וְ⁠לֹ֥א תַשִּׂיגֵ֖⁠נוּ צְדָקָ֑ה נְקַוֶּ֤ה לָ⁠אוֹר֙ וְ⁠הִנֵּה־חֹ֔שֶׁךְ לִ⁠נְגֹה֖וֹת בָּ⁠אֲפֵל֥וֹת נְהַלֵּֽךְ׃","ʻal-ké̇֗n ráẖa֤q mişĕ̌pá̇t֙ mimė֔⁠ṅẇ wĕ⁠lò֥ʼ ţaşi̇̂ygé֖⁠nẇ ẕĕdáqá֑h nĕqawė֤h lá⁠ʼwòr֙ wĕ⁠hiné̇h-ẖò֔şěkĕ li⁠nĕgòh֖wòţ bá̇⁠ʼàpél֥wòţ nĕhaléֽ̇kĕ׃"],[59,10,"נְגַֽשְׁשָׁ֤ה כַֽ⁠עִוְרִים֙ קִ֔יר וּ⁠כְ⁠אֵ֥ין עֵינַ֖יִם נְגַשֵּׁ֑שָׁה כָּשַׁ֤לְנוּ בַֽ⁠צָּהֳרַ֨יִם֙ כַּ⁠נֶּ֔שֶׁף בָּ⁠אַשְׁמַנִּ֖ים כַּ⁠מֵּתִֽים׃","nĕgaֽşĕ̌şá֤̌h kaֽ⁠ʻiwĕriym֙ qi֔yr ẇ⁠kĕ⁠ʼé֥yn ʻéyna֖yim nĕgaşé֑̇̌şá̌h ká̇şǎ֤lĕnẇ baֽ⁠ẕá̇hora֨yim֙ kȧ⁠nė֔şěp bá̇⁠ʼaşĕ̌mani֖̇ym kȧ⁠mé̇ţiֽym׃"],[59,11,"נֶהֱמֶ֤ה כַ⁠דֻּבִּים֙ כֻּלָּ֔⁠נוּ וְ⁠כַ⁠יּוֹנִ֖ים הָגֹ֣ה נֶהְגֶּ֑ה נְקַוֶּ֤ה לַ⁠מִּשְׁפָּט֙ וָ⁠אַ֔יִן לִֽ⁠ישׁוּעָ֖ה רָחֲקָ֥ה מִמֶּֽ⁠נּוּ׃","nehème֤h ka⁠du̇bi̇ym֙ ku̇lá̇֔⁠nẇ wĕ⁠ka⁠ẏwòni֖ym hágò֣h nehĕgė֑h nĕqawė֤h la⁠mi̇şĕ̌pá̇t֙ wá⁠ʼa֔yin liֽ⁠yş̌ẇʻá֖h ráẖàqá֥h mimėֽ⁠ṅẇ׃"],[59,12,"כִּֽי־רַבּ֤וּ פְשָׁעֵ֨י⁠נוּ֙ נֶגְדֶּ֔⁠ךָ וְ⁠חַטֹּאותֵ֖י⁠נוּ עָ֣נְתָה בָּ֑⁠נוּ כִּֽי־פְשָׁעֵ֣י⁠נוּ אִתָּ֔⁠נוּ וַ⁠עֲוֺנֹתֵ֖י⁠נוּ יְדַֽעֲנֽוּ⁠ם׃","kiֽ̇y-raḃ֤ẇ pĕşá̌ʻé֨y⁠nẇ֙ negĕdė֔⁠ká wĕ⁠ẖatò̇ʼwţé֖y⁠nẇ ʻá֣nĕţáh bá֑̇⁠nẇ kiֽ̇y-pĕşá̌ʻé֣y⁠nẇ ʼiţá̇֔⁠nẇ wa⁠ʻàwֺnòţé֖y⁠nẇ yĕdaֽʻànֽẇ⁠m׃"],[59,13,"פָּשֹׁ֤עַ וְ⁠כַחֵשׁ֙ בַּֽ⁠יהוָ֔ה וְ⁠נָס֖וֹג מֵ⁠אַחַ֣ר אֱלֹהֵ֑י⁠נוּ דַּבֶּר־עֹ֣שֶׁק וְ⁠סָרָ֔ה הֹר֧וֹ וְ⁠הֹג֛וֹ מִ⁠לֵּ֖ב דִּבְרֵי־שָֽׁקֶר׃","pá̇şò֤̌ʻa wĕ⁠kaẖéş̌֙ bȧֽ⁠yhwá֔h wĕ⁠nás֖wòg mé⁠ʼaẖa֣r ʼèlòhé֑y⁠nẇ dȧbėr-ʻò֣şěq wĕ⁠sárá֔h hòr֧wò wĕ⁠hòg֛wò mi⁠lé֖̇b di̇bĕréy-şáֽ̌qer׃"],[59,14,"וְ⁠הֻסַּ֤ג אָחוֹר֙ מִשְׁפָּ֔ט וּ⁠צְדָקָ֖ה מֵ⁠רָח֣וֹק תַּעֲמֹ֑ד כִּֽי־כָשְׁלָ֤ה בָֽ⁠רְחוֹב֙ אֱמֶ֔ת וּ⁠נְכֹחָ֖ה לֹא־תוּכַ֥ל לָ⁠בֽוֹא׃","wĕ⁠husȧ֤g ʼáẖwòr֙ mişĕ̌pá̇֔t ẇ⁠ẕĕdáqá֖h mé⁠ráẖ֣wòq ţȧʻàmò֑d kiֽ̇y-káşĕ̌lá֤h báֽ⁠rĕẖwòb֙ ʼème֔ţ ẇ⁠nĕkòẖá֖h lòʼ-ţẇka֥l lá⁠bֽwòʼ׃"],[59,15,"וַ⁠תְּהִ֤י הָֽ⁠אֱמֶת֙ נֶעְדֶּ֔רֶת וְ⁠סָ֥ר מֵ⁠רָ֖ע מִשְׁתּוֹלֵ֑ל וַ⁠יַּ֧רְא יְהוָ֛ה וַ⁠יֵּ֥רַע בְּ⁠עֵינָ֖י⁠ו כִּֽי־אֵ֥ין מִשְׁפָּֽט׃","wa⁠ţĕ̇hi֤y háֽ⁠ʼèmeţ֙ neʻĕdė֔reţ wĕ⁠sá֥r mé⁠rá֖ʻ mişĕ̌ţ̇wòlé֑l wa⁠yȧ֧rĕʼ yĕhwá֛h wa⁠yé֥̇raʻ bĕ̇⁠ʻéyná֖y⁠w kiֽ̇y-ʼé֥yn mişĕ̌páֽ̇t׃"],[59,16,"וַ⁠יַּרְא֙ כִּֽי־אֵ֣ין אִ֔ישׁ וַ⁠יִּשְׁתּוֹמֵ֖ם כִּ֣י אֵ֣ין מַפְגִּ֑יעַ וַ⁠תּ֤וֹשַֽׁע ל⁠וֹ֙ זְרֹע֔⁠וֹ וְ⁠צִדְקָת֖⁠וֹ הִ֥יא סְמָכָֽתְ⁠הוּ׃","wa⁠yȧrĕʼ֙ kiֽ̇y-ʼé֣yn ʼi֔yş̌ wa⁠yi̇şĕ̌ţ̇wòmé֖m ki֣̇y ʼé֣yn mapĕgi֑̇yʻa wa⁠ţ֤̇wòşǎֽʻ l⁠wò֙ zĕròʻ֔⁠wò wĕ⁠ẕidĕqáţ֖⁠wò hi֥yʼ sĕmákáֽţĕ⁠hẇ׃"],[59,17,"וַ⁠יִּלְבַּ֤שׁ צְדָקָה֙ כַּ⁠שִּׁרְיָ֔ן וְ⁠כ֥וֹבַע יְשׁוּעָ֖ה בְּ⁠רֹאשׁ֑⁠וֹ וַ⁠יִּלְבַּ֞שׁ בִּגְדֵ֤י נָקָם֙ תִּלְבֹּ֔שֶׁת וַ⁠יַּ֥עַט כַּ⁠מְעִ֖יל קִנְאָֽה׃","wa⁠yi̇lĕbȧ֤ş̌ ẕĕdáqáh֙ kȧ⁠şi̇̌rĕyá֔n wĕ⁠k֥wòbaʻ yĕş̌ẇʻá֖h bĕ̇⁠ròʼş֑̌⁠wò wa⁠yi̇lĕbȧ֞ş̌ bi̇gĕdé֤y náqám֙ ţi̇lĕbò̇֔şěţ wa⁠yȧ֥ʻat kȧ⁠mĕʻi֖yl qinĕʼáֽh׃"],[59,18,"כְּ⁠עַ֤ל גְּמֻלוֹת֙ כְּ⁠עַ֣ל יְשַׁלֵּ֔ם חֵמָ֣ה לְ⁠צָרָ֔י⁠ו גְּמ֖וּל לְ⁠אֹֽיְבָ֑י⁠ו לָ⁠אִיִּ֖ים גְּמ֥וּל יְשַׁלֵּֽם׃","kĕ̇⁠ʻa֤l gĕ̇mulwòţ֙ kĕ̇⁠ʻa֣l yĕşǎlé̇֔m ẖémá֣h lĕ⁠ẕárá֔y⁠w gĕ̇m֖ẇl lĕ⁠ʼòֽyĕbá֑y⁠w lá⁠ʼiyi֖̇ym gĕ̇m֥ẇl yĕşǎléֽ̇m׃"],[59,19,"וְ⁠יִֽירְא֤וּ מִֽ⁠מַּעֲרָב֙ אֶת־שֵׁ֣ם יְהוָ֔ה וּ⁠מִ⁠מִּזְרַח־שֶׁ֖מֶשׁ אֶת־כְּבוֹד֑⁠וֹ כִּֽי־יָב֤וֹא כַ⁠נָּהָר֙ צָ֔ר ר֥וּחַ יְהוָ֖ה נֹ֥סְסָה בֽ⁠וֹ׃","wĕ⁠yiֽyrĕʼ֤ẇ miֽ⁠mȧʻàráb֙ ʼeţ-şé֣̌m yĕhwá֔h ẇ⁠mi⁠mi̇zĕraẖ-şě֖meş̌ ʼeţ-kĕ̇bwòd֑⁠wò kiֽ̇y-yáb֤wòʼ ka⁠ná̇hár֙ ẕá֔r r֥ẇẖa yĕhwá֖h nò֥sĕsáh bֽ⁠wò׃"],[59,20,"וּ⁠בָ֤א לְ⁠צִיּוֹן֙ גּוֹאֵ֔ל וּ⁠לְ⁠שָׁבֵ֥י פֶ֖שַׁע בְּ⁠יַֽעֲקֹ֑ב נְאֻ֖ם יְהוָֽה׃","ẇ⁠bá֤ʼ lĕ⁠ẕiẏwòn֙ ġwòʼé֔l ẇ⁠lĕ⁠şá̌bé֥y pe֖şǎʻ bĕ̇⁠yaֽʻàqò֑b nĕʼu֖m yĕhwáֽh׃"],[59,21,"וַ⁠אֲנִ֗י זֹ֣את בְּרִיתִ֤⁠י אוֹתָ⁠ם֙ אָמַ֣ר יְהוָ֔ה רוּחִ⁠י֙ אֲשֶׁ֣ר עָלֶ֔י⁠ךָ וּ⁠דְבָרַ֖⁠י אֲשֶׁר־שַׂ֣מְתִּי בְּ⁠פִ֑י⁠ךָ לֹֽא־יָמ֡וּשׁוּ מִ⁠פִּי⁠ךָ֩ וּ⁠מִ⁠פִּ֨י זַרְעֲ⁠ךָ֜ וּ⁠מִ⁠פִּ֨י זֶ֤רַע זַרְעֲ⁠ךָ֙ אָמַ֣ר יְהוָ֔ה מֵ⁠עַתָּ֖ה וְ⁠עַד־עוֹלָֽם׃ס","wa⁠ʼàni֗y zò֣ʼţ bĕ̇riyţi֤⁠y ʼwòţá⁠m֙ ʼáma֣r yĕhwá֔h rẇẖi⁠y֙ ʼàşě֣r ʻále֔y⁠ká ẇ⁠dĕbára֖⁠y ʼàşěr-şâ֣mĕţi̇y bĕ̇⁠pi֑y⁠ká lòֽʼ-yám֡ẇş̌ẇ mi⁠pi̇y⁠ká֩ ẇ⁠mi⁠pi̇֨y zarĕʻà⁠ká֜ ẇ⁠mi⁠pi̇֨y ze֤raʻ zarĕʻà⁠ká֙ ʼáma֣r yĕhwá֔h mé⁠ʻaţá֖̇h wĕ⁠ʻad-ʻwòláֽm׃s"],[60,1,"ק֥וּמִי א֖וֹרִי כִּ֣י בָ֣א אוֹרֵ֑⁠ךְ וּ⁠כְב֥וֹד יְהוָ֖ה עָלַ֥יִ⁠ךְ זָרָֽח׃","q֥ẇmiy ʼ֖wòriy ki֣̇y bá֣ʼ ʼwòré֑⁠kĕ ẇ⁠kĕb֥wòd yĕhwá֖h ʻála֥yi⁠kĕ záráֽẖ׃"],[60,2,"כִּֽי־הִנֵּ֤ה הַ⁠חֹ֨שֶׁךְ֙ יְכַסֶּה־אֶ֔רֶץ וַ⁠עֲרָפֶ֖ל לְאֻמִּ֑ים וְ⁠עָלַ֨יִ⁠ךְ֙ יִזְרַ֣ח יְהוָ֔ה וּ⁠כְבוֹד֖⁠וֹ עָלַ֥יִ⁠ךְ יֵרָאֶֽה׃","kiֽ̇y-hiné֤̇h ha⁠ẖò֨şěkĕ֙ yĕkasėh-ʼe֔reẕ wa⁠ʻàrápe֖l lĕʼumi֑̇ym wĕ⁠ʻála֨yi⁠kĕ֙ yizĕra֣ẖ yĕhwá֔h ẇ⁠kĕbwòd֖⁠wò ʻála֥yi⁠kĕ yéráʼeֽh׃"],[60,3,"וְ⁠הָלְכ֥וּ גוֹיִ֖ם לְ⁠אוֹרֵ֑⁠ךְ וּ⁠מְלָכִ֖ים לְ⁠נֹ֥גַהּ זַרְחֵֽ⁠ךְ׃","wĕ⁠hálĕk֥ẇ gwòyi֖m lĕ⁠ʼwòré֑⁠kĕ ẇ⁠mĕláki֖ym lĕ⁠nò֥gaḣ zarĕẖéֽ⁠kĕ׃"],[60,4,"שְׂאִֽי־סָבִ֤יב עֵינַ֨יִ⁠ךְ֙ וּ⁠רְאִ֔י כֻּלָּ֖⁠ם נִקְבְּצ֣וּ בָֽאוּ־לָ֑⁠ךְ בָּנַ֨יִ⁠ךְ֙ מֵ⁠רָח֣וֹק יָבֹ֔אוּ וּ⁠בְנֹתַ֖יִ⁠ךְ עַל־צַ֥ד תֵּאָמַֽנָה׃","şĕ̂ʼiֽy-sábi֤yb ʻéyna֨yi⁠kĕ֙ ẇ⁠rĕʼi֔y ku̇lá֖̇⁠m niqĕbĕ̇ẕ֣ẇ báֽʼẇ-lá֑⁠kĕ bá̇na֨yi⁠kĕ֙ mé⁠ráẖ֣wòq yábò֔ʼẇ ẇ⁠bĕnòţa֖yi⁠kĕ ʻal-ẕa֥d ţé̇ʼámaֽnáh׃"],[60,5,"אָ֤ז תִּרְאִי֙ וְ⁠נָהַ֔רְתְּ וּ⁠פָחַ֥ד וְ⁠רָחַ֖ב לְבָבֵ֑⁠ךְ כִּֽי־יֵהָפֵ֤ךְ עָלַ֨יִ⁠ךְ֙ הֲמ֣וֹן יָ֔ם חֵ֥יל גּוֹיִ֖ם יָבֹ֥אוּ לָֽ⁠ךְ׃","ʼá֤z ţi̇rĕʼiy֙ wĕ⁠náha֔rĕţĕ̇ ẇ⁠páẖa֥d wĕ⁠ráẖa֖b lĕbábé֑⁠kĕ kiֽ̇y-yéhápé֤kĕ ʻála֨yi⁠kĕ֙ hàm֣wòn yá֔m ẖé֥yl ġwòyi֖m yábò֥ʼẇ láֽ⁠kĕ׃"],[60,6,"שִֽׁפְעַ֨ת גְּמַלִּ֜ים תְּכַסֵּ֗⁠ךְ בִּכְרֵ֤י מִדְיָן֙ וְ⁠עֵיפָ֔ה כֻּלָּ֖⁠ם מִ⁠שְּׁבָ֣א יָבֹ֑אוּ זָהָ֤ב וּ⁠לְבוֹנָה֙ יִשָּׂ֔אוּ וּ⁠תְהִלֹּ֥ת יְהוָ֖ה יְבַשֵּֽׂרוּ׃","şǐֽpĕʻa֨ţ gĕ̇mali̇֜ym ţĕ̇kasé̇֗⁠kĕ bi̇kĕré֤y midĕyán֙ wĕ⁠ʻéypá֔h ku̇lá֖̇⁠m mi⁠şĕ̇̌bá֣ʼ yábò֑ʼẇ záhá֤b ẇ⁠lĕbwònáh֙ yişá̇̂֔ʼẇ ẇ⁠ţĕhilò֥̇ţ yĕhwá֖h yĕbaşéֽ̇̂rẇ׃"],[60,7,"כָּל־צֹ֤אן קֵדָר֙ יִקָּ֣בְצוּ לָ֔⁠ךְ אֵילֵ֥י נְבָי֖וֹת יְשָׁרְת֑וּ⁠נֶךְ יַעֲל֤וּ עַל־רָצוֹן֙ מִזְבְּחִ֔⁠י וּ⁠בֵ֥ית תִּפְאַרְתִּ֖⁠י אֲפָאֵֽר׃","ká̇l-ẕò֤ʼn qédár֙ yiqá֣̇bĕẕẇ lá֔⁠kĕ ʼéylé֥y nĕbáy֖wòţ yĕşá̌rĕţ֑ẇ⁠nekĕ yaʻàl֤ẇ ʻal-ráẕwòn֙ mizĕbĕ̇ẖi֔⁠y ẇ⁠bé֥yţ ţi̇pĕʼarĕţi֖̇⁠y ʼàpáʼéֽr׃"],[60,8,"מִי־אֵ֖לֶּה כָּ⁠עָ֣ב תְּעוּפֶ֑ינָה וְ⁠כַ⁠יּוֹנִ֖ים אֶל־אֲרֻבֹּתֵי⁠הֶֽם׃","miy-ʼé֖lėh ká̇⁠ʻá֣b ţĕ̇ʻẇpe֑ynáh wĕ⁠ka⁠ẏwòni֖ym ʼel-ʼàrubò̇ţéy⁠heֽm׃"],[60,9,"כִּֽי־לִ֣⁠י ׀ אִיִּ֣ים יְקַוּ֗וּ וָ⁠אֳנִיּ֤וֹת תַּרְשִׁישׁ֙ בָּ⁠רִ֣אשֹׁנָ֔ה לְ⁠הָבִ֤יא בָנַ֨יִ⁠ךְ֙ מֵֽ⁠רָח֔וֹק כַּסְפָּ֥⁠ם וּ⁠זְהָבָ֖⁠ם אִתָּ֑⁠ם לְ⁠שֵׁם֙ יְהוָ֣ה אֱלֹהַ֔יִ⁠ךְ וְ⁠לִ⁠קְד֥וֹשׁ יִשְׂרָאֵ֖ל כִּ֥י פֵאֲרָֽ⁠ךְ׃","kiֽ̇y-li֣⁠y ׀ ʼiyi֣̇ym yĕqaẇ֗ẇ wá⁠ʼoniẏ֤wòţ ţȧrĕşǐyş̌֙ bá̇⁠ri֣ʼşò̌ná֔h lĕ⁠hábi֤yʼ bána֨yi⁠kĕ֙ méֽ⁠ráẖ֔wòq kȧsĕpá֥̇⁠m ẇ⁠zĕhábá֖⁠m ʼiţá֑̇⁠m lĕ⁠şé̌m֙ yĕhwá֣h ʼèlòha֔yi⁠kĕ wĕ⁠li⁠qĕd֥wòş̌ yişĕ̂ráʼé֖l ki֥̇y péʼàráֽ⁠kĕ׃"],[60,10,"וּ⁠בָנ֤וּ בְנֵֽי־נֵכָר֙ חֹמֹתַ֔יִ⁠ךְ וּ⁠מַלְכֵי⁠הֶ֖ם יְשָׁרְת֑וּ⁠נֶךְ כִּ֤י בְ⁠קִצְפִּ⁠י֙ הִכִּיתִ֔י⁠ךְ וּ⁠בִ⁠רְצוֹנִ֖⁠י רִֽחַמְתִּֽי⁠ךְ׃","ẇ⁠bán֤ẇ bĕnéֽy-nékár֙ ẖòmòţa֔yi⁠kĕ ẇ⁠malĕkéy⁠he֖m yĕşá̌rĕţ֑ẇ⁠nekĕ ki֤̇y bĕ⁠qiẕĕpi̇⁠y֙ hiki̇yţi֔y⁠kĕ ẇ⁠bi⁠rĕẕwòni֖⁠y riֽẖamĕţiֽ̇y⁠kĕ׃"],[60,11,"וּ⁠פִתְּח֨וּ שְׁעָרַ֧יִ⁠ךְ תָּמִ֛יד יוֹמָ֥ם וָ⁠לַ֖יְלָה לֹ֣א יִסָּגֵ֑רוּ לְ⁠הָבִ֤יא אֵלַ֨יִ⁠ךְ֙ חֵ֣יל גּוֹיִ֔ם וּ⁠מַלְכֵי⁠הֶ֖ם נְהוּגִֽים׃","ẇ⁠piţĕ̇ẖ֨ẇ şĕ̌ʻára֧yi⁠kĕ ţá̇mi֛yd ywòmá֥m wá⁠la֖yĕláh lò֣ʼ yisá̇gé֑rẇ lĕ⁠hábi֤yʼ ʼéla֨yi⁠kĕ֙ ẖé֣yl ġwòyi֔m ẇ⁠malĕkéy⁠he֖m nĕhẇgiֽym׃"],[60,12,"כִּֽי־הַ⁠גּ֧וֹי וְ⁠הַ⁠מַּמְלָכָ֛ה אֲשֶׁ֥ר לֹא־יַעַבְד֖וּ⁠ךְ יֹאבֵ֑דוּ וְ⁠הַ⁠גּוֹיִ֖ם חָרֹ֥ב יֶחֱרָֽבוּ׃","kiֽ̇y-ha⁠ġ֧wòy wĕ⁠ha⁠mȧmĕláká֛h ʼàşě֥r lòʼ-yaʻabĕd֖ẇ⁠kĕ yòʼbé֑dẇ wĕ⁠ha⁠ġwòyi֖m ẖárò֥b yeẖèráֽbẇ׃"],[60,13,"כְּב֤וֹד הַ⁠לְּבָנוֹן֙ אֵלַ֣יִ⁠ךְ יָב֔וֹא בְּר֛וֹשׁ תִּדְהָ֥ר וּ⁠תְאַשּׁ֖וּר יַחְדָּ֑ו לְ⁠פָאֵר֙ מְק֣וֹם מִקְדָּשִׁ֔⁠י וּ⁠מְק֥וֹם רַגְלַ֖⁠י אֲכַבֵּֽד׃","kĕ̇b֤wòd ha⁠lĕ̇bánwòn֙ ʼéla֣yi⁠kĕ yáb֔wòʼ bĕ̇r֛wòş̌ ţi̇dĕhá֥r ẇ⁠ţĕʼaş֖̇̌ẇr yaẖĕdá֑̇w lĕ⁠páʼér֙ mĕq֣wòm miqĕdá̇şǐ֔⁠y ẇ⁠mĕq֥wòm ragĕla֖⁠y ʼàkabéֽ̇d׃"],[60,14,"וְ⁠הָלְכ֨וּ אֵלַ֤יִ⁠ךְ שְׁח֨וֹחַ֙ בְּנֵ֣י מְעַנַּ֔יִ⁠ךְ וְ⁠הִֽשְׁתַּחֲו֛וּ עַל־כַּפּ֥וֹת רַגְלַ֖יִ⁠ךְ כָּל־מְנַֽאֲצָ֑יִ⁠ךְ וְ⁠קָ֤רְאוּ לָ⁠ךְ֙ עִ֣יר יְהוָ֔ה צִיּ֖וֹן קְד֥וֹשׁ יִשְׂרָאֵֽל׃","wĕ⁠hálĕk֨ẇ ʼéla֤yi⁠kĕ şĕ̌ẖ֨wòẖa֙ bĕ̇né֣y mĕʻanȧ֔yi⁠kĕ wĕ⁠hiֽşĕ̌ţȧẖàw֛ẇ ʻal-kȧṗ֥wòţ ragĕla֖yi⁠kĕ ká̇l-mĕnaֽʼàẕá֑yi⁠kĕ wĕ⁠qá֤rĕʼẇ lá⁠kĕ֙ ʻi֣yr yĕhwá֔h ẕiẏ֖wòn qĕd֥wòş̌ yişĕ̂ráʼéֽl׃"],[60,15,"תַּ֧חַת הֱיוֹתֵ֛⁠ךְ עֲזוּבָ֥ה וּ⁠שְׂנוּאָ֖ה וְ⁠אֵ֣ין עוֹבֵ֑ר וְ⁠שַׂמְתִּי⁠ךְ֙ לִ⁠גְא֣וֹן עוֹלָ֔ם מְשׂ֖וֹשׂ דּ֥וֹר וָ⁠דֽוֹר׃","ţȧ֧ẖaţ hèywòţé֛⁠kĕ ʻàzẇbá֥h ẇ⁠şĕ̂nẇʼá֖h wĕ⁠ʼé֣yn ʻwòbé֑r wĕ⁠şâmĕţi̇y⁠kĕ֙ li⁠gĕʼ֣wòn ʻwòlá֔m mĕş֖̂wòş̂ ḋ֥wòr wá⁠dֽwòr׃"],[60,16,"וְ⁠יָנַקְתְּ֙ חֲלֵ֣ב גּוֹיִ֔ם וְ⁠שֹׁ֥ד מְלָכִ֖ים תִּינָ֑קִי וְ⁠יָדַ֗עַתְּ כִּ֣י אֲנִ֤י יְהוָה֙ מֽוֹשִׁיעֵ֔⁠ךְ וְ⁠גֹאֲלֵ֖⁠ךְ אֲבִ֥יר יַעֲקֹֽב׃","wĕ⁠yánaqĕţĕ̇֙ ẖàlé֣b ġwòyi֔m wĕ⁠şò֥̌d mĕláki֖ym ţi̇yná֑qiy wĕ⁠yáda֗ʻaţĕ̇ ki֣̇y ʼàni֤y yĕhwáh֙ mֽwòşǐyʻé֔⁠kĕ wĕ⁠gòʼàlé֖⁠kĕ ʼàbi֥yr yaʻàqòֽb׃"],[60,17,"תַּ֣חַת הַ⁠נְּחֹ֜שֶׁת אָבִ֣יא זָהָ֗ב וְ⁠תַ֤חַת הַ⁠בַּרְזֶל֙ אָ֣בִיא כֶ֔סֶף וְ⁠תַ֤חַת הָֽ⁠עֵצִים֙ נְחֹ֔שֶׁת וְ⁠תַ֥חַת הָ⁠אֲבָנִ֖ים בַּרְזֶ֑ל וְ⁠שַׂמְתִּ֤י פְקֻדָּתֵ⁠ךְ֙ שָׁל֔וֹם וְ⁠נֹגְשַׂ֖יִ⁠ךְ צְדָקָֽה׃","ţȧ֣ẖaţ ha⁠nĕ̇ẖò֜şěţ ʼábi֣yʼ záhá֗b wĕ⁠ţa֤ẖaţ ha⁠bȧrĕzel֙ ʼá֣biyʼ ke֔sep wĕ⁠ţa֤ẖaţ háֽ⁠ʻéẕiym֙ nĕẖò֔şěţ wĕ⁠ţa֥ẖaţ há⁠ʼàbáni֖ym bȧrĕze֑l wĕ⁠şâmĕţi֤̇y pĕqudá̇ţé⁠kĕ֙ şá̌l֔wòm wĕ⁠nògĕşâ֖yi⁠kĕ ẕĕdáqáֽh׃"],[60,18,"לֹא־יִשָּׁמַ֨ע ע֤וֹד חָמָס֙ בְּ⁠אַרְצֵ֔⁠ךְ שֹׁ֥ד וָ⁠שֶׁ֖בֶר בִּ⁠גְבוּלָ֑יִ⁠ךְ וְ⁠קָרָ֤את יְשׁוּעָה֙ חוֹמֹתַ֔יִ⁠ךְ וּ⁠שְׁעָרַ֖יִ⁠ךְ תְּהִלָּֽה׃","lòʼ-yişá̇̌ma֨ʻ ʻ֤wòd ẖámás֙ bĕ̇⁠ʼarĕẕé֔⁠kĕ şò֥̌d wá⁠şě֖ber bi̇⁠gĕbẇlá֑yi⁠kĕ wĕ⁠qárá֤ʼţ yĕş̌ẇʻáh֙ ẖwòmòţa֔yi⁠kĕ ẇ⁠şĕ̌ʻára֖yi⁠kĕ ţĕ̇hiláֽ̇h׃"],[60,19,"לֹא־יִֽהְיֶה־לָּ֨⁠ךְ ע֤וֹד הַ⁠שֶּׁ֨מֶשׁ֙ לְ⁠א֣וֹר יוֹמָ֔ם וּ⁠לְ⁠נֹ֕גַהּ הַ⁠יָּרֵ֖חַ לֹא־יָאִ֣יר לָ֑⁠ךְ וְ⁠הָיָה־לָ֤⁠ךְ יְהוָה֙ לְ⁠א֣וֹר עוֹלָ֔ם וֵ⁠אלֹהַ֖יִ⁠ךְ לְ⁠תִפְאַרְתֵּֽ⁠ךְ׃","lòʼ-yiֽhĕyeh-lá̇֨⁠kĕ ʻ֤wòd ha⁠şė̌֨meş̌֙ lĕ⁠ʼ֣wòr ywòmá֔m ẇ⁠lĕ⁠nò֕gaḣ ha⁠yá̇ré֖ẖa lòʼ-yáʼi֣yr lá֑⁠kĕ wĕ⁠háyáh-lá֤⁠kĕ yĕhwáh֙ lĕ⁠ʼ֣wòr ʻwòlá֔m wé⁠ʼlòha֖yi⁠kĕ lĕ⁠ţipĕʼarĕţéֽ̇⁠kĕ׃"],[60,20,"לֹא־יָב֥וֹא עוֹד֙ שִׁמְשֵׁ֔⁠ךְ וִ⁠ירֵחֵ֖⁠ךְ לֹ֣א יֵאָסֵ֑ף כִּ֣י יְהוָ֗ה יִֽהְיֶה־לָּ⁠ךְ֙ לְ⁠א֣וֹר עוֹלָ֔ם וְ⁠שָׁלְמ֖וּ יְמֵ֥י אֶבְלֵֽ⁠ךְ׃","lòʼ-yáb֥wòʼ ʻwòd֙ şǐmĕşé̌֔⁠kĕ wi⁠yréẖé֖⁠kĕ lò֣ʼ yéʼásé֑p ki֣̇y yĕhwá֗h yiֽhĕyeh-lá̇⁠kĕ֙ lĕ⁠ʼ֣wòr ʻwòlá֔m wĕ⁠şá̌lĕm֖ẇ yĕmé֥y ʼebĕléֽ⁠kĕ׃"],[60,21,"וְ⁠עַמֵּ⁠ךְ֙ כֻּלָּ֣⁠ם צַדִּיקִ֔ים לְ⁠עוֹלָ֖ם יִ֣ירְשׁוּ אָ֑רֶץ נֵ֧צֶר מטע⁠ו מַעֲשֵׂ֥ה יָדַ֖⁠י לְ⁠הִתְפָּאֵֽר׃","wĕ⁠ʻamé̇⁠kĕ֙ ku̇lá֣̇⁠m ẕadi̇yqi֔ym lĕ⁠ʻwòlá֖m yi֣yrĕş̌ẇ ʼá֑reẕ né֧ẕer mtʻ⁠w maʻàşé֥̂h yáda֖⁠y lĕ⁠hiţĕpá̇ʼéֽr׃"],[60,22,"הַ⁠קָּטֹן֙ יִֽהְיֶ֣ה לָ⁠אֶ֔לֶף וְ⁠הַ⁠צָּעִ֖יר לְ⁠ג֣וֹי עָצ֑וּם אֲנִ֥י יְהוָ֖ה בְּ⁠עִתָּ֥⁠הּ אֲחִישֶֽׁ⁠נָּה׃ס","ha⁠qá̇tòn֙ yiֽhĕye֣h lá⁠ʼe֔lep wĕ⁠ha⁠ẕá̇ʻi֖yr lĕ⁠g֣wòy ʻáẕ֑ẇm ʼàni֥y yĕhwá֖h bĕ̇⁠ʻiţá֥̇⁠ḣ ʼàẖiyşěֽ⁠ná̇h׃s"],[61,1,"ר֛וּחַ אֲדֹנָ֥⁠י יְהוִ֖ה עָלָ֑⁠י יַ֡עַן מָשַׁח֩ יְהוָ֨ה אֹתִ֜⁠י לְ⁠בַשֵּׂ֣ר עֲנָוִ֗ים שְׁלָחַ֨⁠נִי֙ לַ⁠חֲבֹ֣שׁ לְ⁠נִשְׁבְּרֵי־לֵ֔ב לִ⁠קְרֹ֤א לִ⁠שְׁבוּיִם֙ דְּר֔וֹר וְ⁠לַ⁠אֲסוּרִ֖ים פְּקַח־קֽוֹחַ׃","r֛ẇẖa ʼàdòná֥⁠y yĕhwi֖h ʻálá֑⁠y ya֡ʻan máşǎẖ֩ yĕhwá֨h ʼòţi֜⁠y lĕ⁠başé֣̇̂r ʻànáwi֗ym şĕ̌láẖa֨⁠niy֙ la⁠ẖàbò֣ş̌ lĕ⁠nişĕ̌bĕ̇réy-lé֔b li⁠qĕrò֤ʼ li⁠şĕ̌bẇyim֙ dĕ̇r֔wòr wĕ⁠la⁠ʼàsẇri֖ym pĕ̇qaẖ-qֽwòẖa׃"],[61,2,"לִ⁠קְרֹ֤א שְׁנַת־רָצוֹן֙ לַֽ⁠יהוָ֔ה וְ⁠י֥וֹם נָקָ֖ם לֵ⁠אלֹהֵ֑י⁠נוּ לְ⁠נַחֵ֖ם כָּל־אֲבֵלִֽים׃","li⁠qĕrò֤ʼ şĕ̌naţ-ráẕwòn֙ laֽ⁠yhwá֔h wĕ⁠y֥wòm náqá֖m lé⁠ʼlòhé֑y⁠nẇ lĕ⁠naẖé֖m ká̇l-ʼàbéliֽym׃"],[61,3,"לָ⁠שׂ֣וּם ׀ לַ⁠אֲבֵלֵ֣י צִיּ֗וֹן לָ⁠תֵת֩ לָ⁠הֶ֨ם פְּאֵ֜ר תַּ֣חַת אֵ֗פֶר שֶׁ֤מֶן שָׂשׂוֹן֙ תַּ֣חַת אֵ֔בֶל מַעֲטֵ֣ה תְהִלָּ֔ה תַּ֖חַת ר֣וּחַ כֵּהָ֑ה וְ⁠קֹרָ֤א לָ⁠הֶם֙ אֵילֵ֣י הַ⁠צֶּ֔דֶק מַטַּ֥ע יְהוָ֖ה לְ⁠הִתְפָּאֵֽר׃","lá⁠ş֣̂ẇm ׀ la⁠ʼàbélé֣y ẕiẏ֗wòn lá⁠ţéţ֩ lá⁠he֨m pĕ̇ʼé֜r ţȧ֣ẖaţ ʼé֗per şě֤men şá̂ş̂wòn֙ ţȧ֣ẖaţ ʼé֔bel maʻàté֣h ţĕhilá̇֔h ţȧ֖ẖaţ r֣ẇẖa ké̇há֑h wĕ⁠qòrá֤ʼ lá⁠hem֙ ʼéylé֣y ha⁠ẕė֔deq matȧ֥ʻ yĕhwá֖h lĕ⁠hiţĕpá̇ʼéֽr׃"],[61,4,"וּ⁠בָנוּ֙ חָרְב֣וֹת עוֹלָ֔ם שֹׁמְמ֥וֹת רִֽאשֹׁנִ֖ים יְקוֹמֵ֑מוּ וְ⁠חִדְּשׁוּ֙ עָ֣רֵי חֹ֔רֶב שֹׁמְמ֖וֹת דּ֥וֹר וָ⁠דֽוֹר׃","ẇ⁠bánẇ֙ ẖárĕb֣wòţ ʻwòlá֔m şò̌mĕm֥wòţ riֽʼşò̌ni֖ym yĕqwòmé֑mẇ wĕ⁠ẖidĕ̇ş̌ẇ֙ ʻá֣réy ẖò֔reb şò̌mĕm֖wòţ ḋ֥wòr wá⁠dֽwòr׃"],[61,5,"וְ⁠עָמְד֣וּ זָרִ֔ים וְ⁠רָע֖וּ צֹאנְ⁠כֶ֑ם וּ⁠בְנֵ֣י נֵכָ֔ר אִכָּרֵי⁠כֶ֖ם וְ⁠כֹרְמֵי⁠כֶֽם׃","wĕ⁠ʻámĕd֣ẇ zári֔ym wĕ⁠ráʻ֖ẇ ẕòʼnĕ⁠ke֑m ẇ⁠bĕné֣y néká֔r ʼiká̇réy⁠ke֖m wĕ⁠kòrĕméy⁠keֽm׃"],[61,6,"וְ⁠אַתֶּ֗ם כֹּהֲנֵ֤י יְהוָה֙ תִּקָּרֵ֔אוּ מְשָׁרְתֵ֣י אֱלֹהֵ֔י⁠נוּ יֵאָמֵ֖ר לָ⁠כֶ֑ם חֵ֤יל גּוֹיִם֙ תֹּאכֵ֔לוּ וּ⁠בִ⁠כְבוֹדָ֖⁠ם תִּתְיַמָּֽרוּ׃","wĕ⁠ʼaţė֗m kò̇hàné֤y yĕhwáh֙ ţi̇qá̇ré֔ʼẇ mĕşá̌rĕţé֣y ʼèlòhé֔y⁠nẇ yéʼámé֖r lá⁠ke֑m ẖé֤yl ġwòyim֙ ţò̇ʼké֔lẇ ẇ⁠bi⁠kĕbwòdá֖⁠m ţi̇ţĕyamáֽ̇rẇ׃"],[61,7,"תַּ֤חַת בָּשְׁתְּ⁠כֶם֙ מִשְׁנֶ֔ה וּ⁠כְלִמָּ֖ה יָרֹ֣נּוּ חֶלְקָ֑⁠ם לָ⁠כֵ֤ן בְּ⁠אַרְצָ⁠ם֙ מִשְׁנֶ֣ה יִירָ֔שׁוּ שִׂמְחַ֥ת עוֹלָ֖ם תִּֽהְיֶ֥ה לָ⁠הֶֽם׃","ţȧ֤ẖaţ bá̇şĕ̌ţĕ̇⁠kem֙ mişĕ̌ne֔h ẇ⁠kĕlimá֖̇h yárò֣ṅẇ ẖelĕqá֑⁠m lá⁠ké֤n bĕ̇⁠ʼarĕẕá⁠m֙ mişĕ̌ne֣h yiyrá֔ş̌ẇ şîmĕẖa֥ţ ʻwòlá֖m ţiֽ̇hĕye֥h lá⁠heֽm׃"],[61,8,"כִּ֣י אֲנִ֤י יְהוָה֙ אֹהֵ֣ב מִשְׁפָּ֔ט שֹׂנֵ֥א גָזֵ֖ל בְּ⁠עוֹלָ֑ה וְ⁠נָתַתִּ֤י פְעֻלָּתָ⁠ם֙ בֶּ⁠אֱמֶ֔ת וּ⁠בְרִ֥ית עוֹלָ֖ם אֶכְר֥וֹת לָ⁠הֶֽם׃","ki֣̇y ʼàni֤y yĕhwáh֙ ʼòhé֣b mişĕ̌pá̇֔t şò̂né֥ʼ gázé֖l bĕ̇⁠ʻwòlá֑h wĕ⁠náţaţi֤̇y pĕʻulá̇ţá⁠m֙ bė⁠ʼème֔ţ ẇ⁠bĕri֥yţ ʻwòlá֖m ʼekĕr֥wòţ lá⁠heֽm׃"],[61,9,"וְ⁠נוֹדַ֤ע בַּ⁠גּוֹיִם֙ זַרְעָ֔⁠ם וְ⁠צֶאֱצָאֵי⁠הֶ֖ם בְּ⁠ת֣וֹךְ הָ⁠עַמִּ֑ים כָּל־רֹֽאֵי⁠הֶם֙ יַכִּיר֔וּ⁠ם כִּ֛י הֵ֥ם זֶ֖רַע בֵּרַ֥ךְ יְהוָֽה׃ס","wĕ⁠nwòda֤ʻ bȧ⁠ġwòyim֙ zarĕʻá֔⁠m wĕ⁠ẕeʼèẕáʼéy⁠he֖m bĕ̇⁠ţ֣wòkĕ há⁠ʻami֑̇ym ká̇l-ròֽʼéy⁠hem֙ yaki̇yr֔ẇ⁠m ki֛̇y hé֥m ze֖raʻ bé̇ra֥kĕ yĕhwáֽh׃s"],[61,10,"שׂ֧וֹשׂ אָשִׂ֣ישׂ בַּֽ⁠יהוָ֗ה תָּגֵ֤ל נַפְשִׁ⁠י֙ בֵּֽ⁠אלֹהַ֔⁠י כִּ֤י הִלְבִּישַׁ֨⁠נִי֙ בִּגְדֵי־יֶ֔שַׁע מְעִ֥יל צְדָקָ֖ה יְעָטָ֑⁠נִי כֶּֽ⁠חָתָן֙ יְכַהֵ֣ן פְּאֵ֔ר וְ⁠כַ⁠כַּלָּ֖ה תַּעְדֶּ֥ה כֵלֶֽי⁠הָ׃","ş֧̂wòş̂ ʼáşî֣yş̂ bȧֽ⁠yhwá֗h ţá̇gé֤l napĕşǐ⁠y֙ béֽ̇⁠ʼlòha֔⁠y ki֤̇y hilĕbi̇yşǎ֨⁠niy֙ bi̇gĕdéy-ye֔şǎʻ mĕʻi֥yl ẕĕdáqá֖h yĕʻátá֑⁠niy kėֽ⁠ẖáţán֙ yĕkahé֣n pĕ̇ʼé֔r wĕ⁠ka⁠kȧlá֖̇h ţȧʻĕdė֥h kéleֽy⁠há׃"],[61,11,"כִּ֤י כָ⁠אָ֨רֶץ֙ תּוֹצִ֣יא צִמְחָ֔⁠הּ וּ⁠כְ⁠גַנָּ֖ה זֵרוּעֶ֣י⁠הָ תַצְמִ֑יחַ כֵּ֣ן ׀ אֲדֹנָ֣⁠י יְהוִ֗ה יַצְמִ֤יחַ צְדָקָה֙ וּ⁠תְהִלָּ֔ה נֶ֖גֶד כָּל־הַ⁠גּוֹיִֽם׃","ki֤̇y ká⁠ʼá֨reẕ֙ ţ̇wòẕi֣yʼ ẕimĕẖá֔⁠ḣ ẇ⁠kĕ⁠ganá֖̇h zérẇʻe֣y⁠há ţaẕĕmi֑yẖa ké֣̇n ׀ ʼàdòná֣⁠y yĕhwi֗h yaẕĕmi֤yẖa ẕĕdáqáh֙ ẇ⁠ţĕhilá̇֔h ne֖ged ká̇l-ha⁠ġwòyiֽm׃"],[62,1,"לְמַ֤עַן צִיּוֹן֙ לֹ֣א אֶחֱשֶׁ֔ה וּ⁠לְמַ֥עַן יְרוּשָׁלִַ֖ם לֹ֣א אֶשְׁק֑וֹט עַד־יֵצֵ֤א כַ⁠נֹּ֨גַהּ֙ צִדְקָ֔⁠הּ וִ⁠ישׁוּעָתָ֖⁠הּ כְּ⁠לַפִּ֥יד יִבְעָֽר׃","lĕma֤ʻan ẕiẏwòn֙ lò֣ʼ ʼeẖèşě֔h ẇ⁠lĕma֥ʻan yĕrẇşá̌lia֖m lò֣ʼ ʼeşĕ̌q֑wòt ʻad-yéẕé֤ʼ ka⁠nò̇֨gaḣ֙ ẕidĕqá֔⁠ḣ wi⁠yş̌ẇʻáţá֖⁠ḣ kĕ̇⁠lapi֥̇yd yibĕʻáֽr׃"],[62,2,"וְ⁠רָא֤וּ גוֹיִם֙ צִדְקֵ֔⁠ךְ וְ⁠כָל־מְלָכִ֖ים כְּבוֹדֵ֑⁠ךְ וְ⁠קֹ֤רָא לָ⁠ךְ֙ שֵׁ֣ם חָדָ֔שׁ אֲשֶׁ֛ר פִּ֥י יְהוָ֖ה יִקֳּבֶֽ⁠נּוּ׃","wĕ⁠ráʼ֤ẇ gwòyim֙ ẕidĕqé֔⁠kĕ wĕ⁠kál-mĕláki֖ym kĕ̇bwòdé֑⁠kĕ wĕ⁠qò֤ráʼ lá⁠kĕ֙ şé֣̌m ẖádá֔ş̌ ʼàşě֛r pi֥̇y yĕhwá֖h yiqȯbeֽ⁠ṅẇ׃"],[62,3,"וְ⁠הָיִ֛יתְ עֲטֶ֥רֶת תִּפְאֶ֖רֶת בְּ⁠יַד־יְהוָ֑ה ו⁠צנוף מְלוּכָ֖ה בְּ⁠כַף־אֱלֹהָֽיִ⁠ךְ׃","wĕ⁠háyi֛yţĕ ʻàte֥reţ ţi̇pĕʼe֖reţ bĕ̇⁠yad-yĕhwá֑h w⁠ẕnwp mĕlẇká֖h bĕ̇⁠kap-ʼèlòháֽyi⁠kĕ׃"],[62,4,"לֹֽא־יֵאָמֵר֩ לָ֨⁠ךְ ע֜וֹד עֲזוּבָ֗ה וּ⁠לְ⁠אַרְצֵ⁠ךְ֙ לֹא־יֵאָמֵ֥ר עוֹד֙ שְׁמָמָ֔ה כִּ֣י לָ֗⁠ךְ יִקָּרֵא֙ חֶפְצִי־בָ֔הּ וּ⁠לְ⁠אַרְצֵ֖⁠ךְ בְּעוּלָ֑ה כִּֽי־חָפֵ֤ץ יְהוָה֙ בָּ֔⁠ךְ וְ⁠אַרְצֵ֖⁠ךְ תִּבָּעֵֽל׃","lòֽʼ-yéʼámér֩ lá֨⁠kĕ ʻ֜wòd ʻàzẇbá֗h ẇ⁠lĕ⁠ʼarĕẕé⁠kĕ֙ lòʼ-yéʼámé֥r ʻwòd֙ şĕ̌mámá֔h ki֣̇y lá֗⁠kĕ yiqá̇réʼ֙ ẖepĕẕiy-bá֔ḣ ẇ⁠lĕ⁠ʼarĕẕé֖⁠kĕ bĕ̇ʻẇlá֑h kiֽ̇y-ẖápé֤ẕ yĕhwáh֙ bá̇֔⁠kĕ wĕ⁠ʼarĕẕé֖⁠kĕ ţi̇bá̇ʻéֽl׃"],[62,5,"כִּֽי־יִבְעַ֤ל בָּחוּר֙ בְּתוּלָ֔ה יִבְעָל֖וּ⁠ךְ בָּנָ֑יִ⁠ךְ וּ⁠מְשׂ֤וֹשׂ חָתָן֙ עַל־כַּלָּ֔ה יָשִׂ֥ישׂ עָלַ֖יִ⁠ךְ אֱלֹהָֽיִ⁠ךְ׃","kiֽ̇y-yibĕʻa֤l bá̇ẖẇr֙ bĕ̇ţẇlá֔h yibĕʻál֖ẇ⁠kĕ bá̇ná֑yi⁠kĕ ẇ⁠mĕş֤̂wòş̂ ẖáţán֙ ʻal-kȧlá̇֔h yáşî֥yş̂ ʻála֖yi⁠kĕ ʼèlòháֽyi⁠kĕ׃"],[62,6,"עַל־חוֹמֹתַ֣יִ⁠ךְ יְרוּשָׁלִַ֗ם הִפְקַ֨דְתִּי֙ שֹֽׁמְרִ֔ים כָּל־הַ⁠יּ֧וֹם וְ⁠כָל־הַ⁠לַּ֛יְלָה תָּמִ֖יד לֹ֣א יֶחֱשׁ֑וּ הַ⁠מַּזְכִּרִים֙ אֶת־יְהוָ֔ה אַל־דֳּמִ֖י לָ⁠כֶֽם׃","ʻal-ẖwòmòţa֣yi⁠kĕ yĕrẇşá̌lia֗m hipĕqa֨dĕţi̇y֙ şòֽ̌mĕri֔ym ká̇l-ha⁠ẏ֧wòm wĕ⁠kál-ha⁠lȧ֛yĕláh ţá̇mi֖yd lò֣ʼ yeẖèş֑̌ẇ ha⁠mȧzĕki̇riym֙ ʼeţ-yĕhwá֔h ʼal-dȯmi֖y lá⁠keֽm׃"],[62,7,"וְ⁠אַֽל־תִּתְּנ֥וּ דֳמִ֖י ל֑⁠וֹ עַד־יְכוֹנֵ֞ן וְ⁠עַד־יָשִׂ֧ים אֶת־יְרֽוּשָׁלִַ֛ם תְּהִלָּ֖ה בָּ⁠אָֽרֶץ׃","wĕ⁠ʼaֽl-ţi̇ţĕ̇n֥ẇ domi֖y l֑⁠wò ʻad-yĕkwòné֞n wĕ⁠ʻad-yáşî֧ym ʼeţ-yĕrֽẇşá̌lia֛m ţĕ̇hilá֖̇h bá̇⁠ʼáֽreẕ׃"],[62,8,"נִשְׁבַּ֧ע יְהוָ֛ה בִּֽ⁠ימִינ֖⁠וֹ וּ⁠בִ⁠זְר֣וֹעַ עֻזּ֑⁠וֹ אִם־אֶתֵּן֩ אֶת־דְּגָנֵ֨⁠ךְ ע֤וֹד מַֽאֲכָל֙ לְ⁠אֹ֣יְבַ֔יִ⁠ךְ וְ⁠אִם־יִשְׁתּ֤וּ בְנֵֽי־נֵכָר֙ תִּֽירוֹשֵׁ֔⁠ךְ אֲשֶׁ֥ר יָגַ֖עַתְּ בּֽ⁠וֹ׃","nişĕ̌bȧ֧ʻ yĕhwá֛h biֽ̇⁠ymiyn֖⁠wò ẇ⁠bi⁠zĕr֣wòʻa ʻuż֑⁠wò ʼim-ʼeţé̇n֩ ʼeţ-dĕ̇gáné֨⁠kĕ ʻ֤wòd maֽʼàkál֙ lĕ⁠ʼò֣yĕba֔yi⁠kĕ wĕ⁠ʼim-yişĕ̌ţ֤̇ẇ bĕnéֽy-nékár֙ ţiֽ̇yrwòşé̌֔⁠kĕ ʼàşě֥r yága֖ʻaţĕ̇ ḃֽ⁠wò׃"],[62,9,"כִּ֤י מְאַסְפָי⁠ו֙ יֹאכְלֻ֔⁠הוּ וְ⁠הִֽלְל֖וּ אֶת־יְהוָ֑ה וּֽ⁠מְקַבְּצָ֥י⁠ו יִשְׁתֻּ֖⁠הוּ בְּ⁠חַצְר֥וֹת קָדְשִֽׁ⁠י׃ס","ki֤̇y mĕʼasĕpáy⁠w֙ yòʼkĕlu֔⁠hẇ wĕ⁠hiֽlĕl֖ẇ ʼeţ-yĕhwá֑h ẇֽ⁠mĕqabĕ̇ẕá֥y⁠w yişĕ̌ţu֖̇⁠hẇ bĕ̇⁠ẖaẕĕr֥wòţ qádĕşǐֽ⁠y׃s"],[62,10,"עִבְר֤וּ עִבְרוּ֙ בַּ⁠שְּׁעָרִ֔ים פַּנּ֖וּ דֶּ֣רֶךְ הָ⁠עָ֑ם סֹ֣לּוּ סֹ֤לּוּ הַֽ⁠מְסִלָּה֙ סַקְּל֣וּ מֵ⁠אֶ֔בֶן הָרִ֥ימוּ נֵ֖ס עַל־הָ⁠עַמִּֽים׃","ʻibĕr֤ẇ ʻibĕrẇ֙ bȧ⁠şĕ̇̌ʻári֔ym pȧṅ֖ẇ dė֣rekĕ há⁠ʻá֑m sò֣l̇ẇ sò֤l̇ẇ haֽ⁠mĕsilá̇h֙ saqĕ̇l֣ẇ mé⁠ʼe֔ben hári֥ymẇ né֖s ʻal-há⁠ʻamiֽ̇ym׃"],[62,11,"הִנֵּ֣ה יְהוָ֗ה הִשְׁמִ֨יעַ֙ אֶל־קְצֵ֣ה הָ⁠אָ֔רֶץ אִמְרוּ֙ לְ⁠בַת־צִיּ֔וֹן הִנֵּ֥ה יִשְׁעֵ֖⁠ךְ בָּ֑א הִנֵּ֤ה שְׂכָר⁠וֹ֙ אִתּ֔⁠וֹ וּ⁠פְעֻלָּת֖⁠וֹ לְ⁠פָנָֽי⁠ו׃","hiné֣̇h yĕhwá֗h hişĕ̌mi֨yʻa֙ ʼel-qĕẕé֣h há⁠ʼá֔reẕ ʼimĕrẇ֙ lĕ⁠baţ-ẕiẏ֔wòn hiné֥̇h yişĕ̌ʻé֖⁠kĕ bá֑̇ʼ hiné֤̇h şĕ̂kár⁠wò֙ ʼiţ̇֔⁠wò ẇ⁠pĕʻulá̇ţ֖⁠wò lĕ⁠pánáֽy⁠w׃"],[62,12,"וְ⁠קָרְא֥וּ לָ⁠הֶ֛ם עַם־הַ⁠קֹּ֖דֶשׁ גְּאוּלֵ֣י יְהוָ֑ה וְ⁠לָ⁠ךְ֙ יִקָּרֵ֣א דְרוּשָׁ֔ה עִ֖יר לֹ֥א נֶעֱזָֽבָה׃ס","wĕ⁠qárĕʼ֥ẇ lá⁠he֛m ʻam-ha⁠qò֖̇deş̌ gĕ̇ʼẇlé֣y yĕhwá֑h wĕ⁠lá⁠kĕ֙ yiqá̇ré֣ʼ dĕrẇşá̌֔h ʻi֖yr lò֥ʼ neʻèzáֽbáh׃s"],[63,1,"מִי־זֶ֣ה ׀ בָּ֣א מֵ⁠אֱד֗וֹם חֲמ֤וּץ בְּגָדִים֙ מִ⁠בָּצְרָ֔ה זֶ֚ה הָד֣וּר בִּ⁠לְבוּשׁ֔⁠וֹ צֹעֶ֖ה בְּ⁠רֹ֣ב כֹּח֑⁠וֹ אֲנִ֛י מְדַבֵּ֥ר בִּ⁠צְדָקָ֖ה רַ֥ב לְ⁠הוֹשִֽׁיעַ׃","miy-ze֣h ׀ bá֣̇ʼ mé⁠ʼèd֗wòm ẖàm֤ẇẕ bĕ̇gádiym֙ mi⁠bá̇ẕĕrá֔h ze֚h hád֣ẇr bi̇⁠lĕbẇş̌֔⁠wò ẕòʻe֖h bĕ̇⁠rò֣b kò̇ẖ֑⁠wò ʼàni֛y mĕdabé֥̇r bi̇⁠ẕĕdáqá֖h ra֥b lĕ⁠hwòşǐֽyʻa׃"],[63,2,"מַדּ֥וּעַ אָדֹ֖ם לִ⁠לְבוּשֶׁ֑⁠ךָ וּ⁠בְגָדֶ֖י⁠ךָ כְּ⁠דֹרֵ֥ךְ בְּ⁠גַֽת׃","maḋ֥ẇʻa ʼádò֖m li⁠lĕbẇşě֑⁠ká ẇ⁠bĕgáde֖y⁠ká kĕ̇⁠dòré֥kĕ bĕ̇⁠gaֽţ׃"],[63,3,"פּוּרָ֣ה ׀ דָּרַ֣כְתִּי לְ⁠בַדִּ֗⁠י וּ⁠מֵֽ⁠עַמִּים֙ אֵֽין־אִ֣ישׁ אִתִּ֔⁠י וְ⁠אֶדְרְכֵ֣⁠ם בְּ⁠אַפִּ֔⁠י וְ⁠אֶרְמְסֵ֖⁠ם בַּ⁠חֲמָתִ֑⁠י וְ⁠יֵ֤ז נִצְחָ⁠ם֙ עַל־בְּגָדַ֔⁠י וְ⁠כָל־מַלְבּוּשַׁ֖⁠י אֶגְאָֽלְתִּי׃","ṗẇrá֣h ׀ dá̇ra֣kĕţi̇y lĕ⁠badi̇֗⁠y ẇ⁠méֽ⁠ʻami̇ym֙ ʼéֽyn-ʼi֣yş̌ ʼiţi̇֔⁠y wĕ⁠ʼedĕrĕké֣⁠m bĕ̇⁠ʼapi̇֔⁠y wĕ⁠ʼerĕmĕsé֖⁠m bȧ⁠ẖàmáţi֑⁠y wĕ⁠yé֤z niẕĕẖá⁠m֙ ʻal-bĕ̇gáda֔⁠y wĕ⁠kál-malĕḃẇşǎ֖⁠y ʼegĕʼáֽlĕţi̇y׃"],[63,4,"כִּ֛י י֥וֹם נָקָ֖ם בְּ⁠לִבִּ֑⁠י וּ⁠שְׁנַ֥ת גְּאוּלַ֖⁠י בָּֽאָה׃","ki֛̇y y֥wòm náqá֖m bĕ̇⁠libi֑̇⁠y ẇ⁠şĕ̌na֥ţ gĕ̇ʼẇla֖⁠y báֽ̇ʼáh׃"],[63,5,"וְ⁠אַבִּיט֙ וְ⁠אֵ֣ין עֹזֵ֔ר וְ⁠אֶשְׁתּוֹמֵ֖ם וְ⁠אֵ֣ין סוֹמֵ֑ךְ וַ⁠תּ֤וֹשַֽׁע לִ⁠י֙ זְרֹעִ֔⁠י וַ⁠חֲמָתִ֖⁠י הִ֥יא סְמָכָֽתְ⁠נִי׃","wĕ⁠ʼabi̇yt֙ wĕ⁠ʼé֣yn ʻòzé֔r wĕ⁠ʼeşĕ̌ţ̇wòmé֖m wĕ⁠ʼé֣yn swòmé֑kĕ wa⁠ţ֤̇wòşǎֽʻ li⁠y֙ zĕròʻi֔⁠y wa⁠ẖàmáţi֖⁠y hi֥yʼ sĕmákáֽţĕ⁠niy׃"],[63,6,"וְ⁠אָב֤וּס עַמִּים֙ בְּ⁠אַפִּ֔⁠י וַ⁠אֲשַׁכְּרֵ֖⁠ם בַּ⁠חֲמָתִ֑⁠י וְ⁠אוֹרִ֥יד לָ⁠אָ֖רֶץ נִצְחָֽ⁠ם׃ס","wĕ⁠ʼáb֤ẇs ʻami̇ym֙ bĕ̇⁠ʼapi̇֔⁠y wa⁠ʼàşǎkĕ̇ré֖⁠m bȧ⁠ẖàmáţi֑⁠y wĕ⁠ʼwòri֥yd lá⁠ʼá֖reẕ niẕĕẖáֽ⁠m׃s"],[63,7,"חַֽסְדֵ֨י יְהוָ֤ה ׀ אַזְכִּיר֙ תְּהִלֹּ֣ת יְהוָ֔ה כְּ⁠עַ֕ל כֹּ֥ל אֲשֶׁר־גְּמָלָ֖⁠נוּ יְהוָ֑ה וְ⁠רַב־טוּב֙ לְ⁠בֵ֣ית יִשְׂרָאֵ֔ל אֲשֶׁר־גְּמָלָ֥⁠ם כְּֽ⁠רַחֲמָ֖י⁠ו וּ⁠כְ⁠רֹ֥ב חֲסָדָֽי⁠ו׃","ẖaֽsĕdé֨y yĕhwá֤h ׀ ʼazĕki̇yr֙ ţĕ̇hilò֣̇ţ yĕhwá֔h kĕ̇⁠ʻa֕l kò֥̇l ʼàşěr-gĕ̇málá֖⁠nẇ yĕhwá֑h wĕ⁠rab-tẇb֙ lĕ⁠bé֣yţ yişĕ̂ráʼé֔l ʼàşěr-gĕ̇málá֥⁠m kĕֽ̇⁠raẖàmá֖y⁠w ẇ⁠kĕ⁠rò֥b ẖàsádáֽy⁠w׃"],[63,8,"וַ⁠יֹּ֨אמֶר֙ אַךְ־עַמִּ֣⁠י הֵ֔מָּה בָּנִ֖ים לֹ֣א יְשַׁקֵּ֑רוּ וַ⁠יְהִ֥י לָ⁠הֶ֖ם לְ⁠מוֹשִֽׁיעַ׃","wa⁠yò̇֨ʼmer֙ ʼakĕ-ʻami֣̇⁠y hé֔má̇h bá̇ni֖ym lò֣ʼ yĕşǎqé֑̇rẇ wa⁠yĕhi֥y lá⁠he֖m lĕ⁠mwòşǐֽyʻa׃"],[63,9,"בְּֽ⁠כָל־צָרָתָ֣⁠ם ׀ לא צָ֗ר וּ⁠מַלְאַ֤ךְ פָּנָי⁠ו֙ הֽוֹשִׁיעָ֔⁠ם בְּ⁠אַהֲבָת֥⁠וֹ וּ⁠בְ⁠חֶמְלָת֖⁠וֹ ה֣וּא גְאָלָ֑⁠ם וַֽ⁠יְנַטְּלֵ֥⁠ם וַֽ⁠יְנַשְּׂאֵ֖⁠ם כָּל־יְמֵ֥י עוֹלָֽם׃","bĕֽ̇⁠kál-ẕáráţá֣⁠m ׀ lʼ ẕá֗r ẇ⁠malĕʼa֤kĕ pá̇náy⁠w֙ hֽwòşǐyʻá֔⁠m bĕ̇⁠ʼahàbáţ֥⁠wò ẇ⁠bĕ⁠ẖemĕláţ֖⁠wò h֣ẇʼ gĕʼálá֑⁠m waֽ⁠yĕnatĕ̇lé֥⁠m waֽ⁠yĕnaşĕ̇̂ʼé֖⁠m ká̇l-yĕmé֥y ʻwòláֽm׃"],[63,10,"וְ⁠הֵ֛מָּה מָר֥וּ וְ⁠עִצְּב֖וּ אֶת־ר֣וּחַ קָדְשׁ֑⁠וֹ וַ⁠יֵּהָפֵ֥ךְ לָ⁠הֶ֛ם לְ⁠אוֹיֵ֖ב ה֥וּא נִלְחַם־בָּֽ⁠ם׃","wĕ⁠hé֛má̇h már֥ẇ wĕ⁠ʻiẕĕ̇b֖ẇ ʼeţ-r֣ẇẖa qádĕş֑̌⁠wò wa⁠yé̇hápé֥kĕ lá⁠he֛m lĕ⁠ʼwòyé֖b h֥ẇʼ nilĕẖam-báֽ̇⁠m׃"],[63,11,"וַ⁠יִּזְכֹּ֥ר יְמֵֽי־עוֹלָ֖ם מֹשֶׁ֣ה עַמּ֑⁠וֹ אַיֵּ֣ה ׀ הַֽ⁠מַּעֲלֵ֣⁠ם מִ⁠יָּ֗ם אֵ֚ת רֹעֵ֣י צֹאנ֔⁠וֹ אַיֵּ֛ה הַ⁠שָּׂ֥ם בְּ⁠קִרְבּ֖⁠וֹ אֶת־ר֥וּחַ קָדְשֽׁ⁠וֹ׃","wa⁠yi̇zĕkò֥̇r yĕméֽy-ʻwòlá֖m mòşě֣h ʻaṁ֑⁠wò ʼayé֣̇h ׀ haֽ⁠mȧʻàlé֣⁠m mi⁠yá̇֗m ʼé֚ţ ròʻé֣y ẕòʼn֔⁠wò ʼayé֛̇h ha⁠şá֥̇̂m bĕ̇⁠qirĕḃ֖⁠wò ʼeţ-r֥ẇẖa qádĕşֽ̌⁠wò׃"],[63,12,"מוֹלִיךְ֙ לִ⁠ימִ֣ין מֹשֶׁ֔ה זְר֖וֹעַ תִּפְאַרְתּ֑⁠וֹ בּ֤וֹקֵֽעַ מַ֨יִם֙ מִ⁠פְּנֵי⁠הֶ֔ם לַ⁠עֲשׂ֥וֹת ל֖⁠וֹ שֵׁ֥ם עוֹלָֽם׃","mwòliykĕ֙ li⁠ymi֣yn mòşě֔h zĕr֖wòʻa ţi̇pĕʼarĕţ֑̇⁠wò ḃ֤wòqéֽʻa ma֨yim֙ mi⁠pĕ̇néy⁠he֔m la⁠ʻàş֥̂wòţ l֖⁠wò şé֥̌m ʻwòláֽm׃"],[63,13,"מוֹלִיכָ֖⁠ם בַּ⁠תְּהֹמ֑וֹת כַּ⁠סּ֥וּס בַּ⁠מִּדְבָּ֖ר לֹ֥א יִכָּשֵֽׁלוּ׃","mwòliyká֖⁠m bȧ⁠ţĕ̇hòm֑wòţ kȧ⁠ṡ֥ẇs bȧ⁠mi̇dĕbá֖̇r lò֥ʼ yiká̇şéֽ̌lẇ׃"],[63,14,"כַּ⁠בְּהֵמָה֙ בַּ⁠בִּקְעָ֣ה תֵרֵ֔ד ר֥וּחַ יְהוָ֖ה תְּנִיחֶ֑⁠נּוּ כֵּ֚ן נִהַ֣גְתָּ עַמְּ⁠ךָ֔ לַ⁠עֲשׂ֥וֹת לְ⁠ךָ֖ שֵׁ֥ם תִּפְאָֽרֶת׃","kȧ⁠bĕ̇hémáh֙ bȧ⁠bi̇qĕʻá֣h ţéré֔d r֥ẇẖa yĕhwá֖h ţĕ̇niyẖe֑⁠ṅẇ ké֚̇n niha֣gĕţá̇ ʻamĕ̇⁠ká֔ la⁠ʻàş֥̂wòţ lĕ⁠ká֖ şé֥̌m ţi̇pĕʼáֽreţ׃"],[63,15,"הַבֵּ֤ט מִ⁠שָּׁמַ֨יִם֙ וּ⁠רְאֵ֔ה מִ⁠זְּבֻ֥ל קָדְשְׁ⁠ךָ֖ וְ⁠תִפְאַרְתֶּ֑⁠ךָ אַיֵּ֤ה קִנְאָֽתְ⁠ךָ֙ וּ⁠גְב֣וּרֹתֶ֔⁠ךָ הֲמ֥וֹן מֵעֶ֛י⁠ךָ וְֽ⁠רַחֲמֶ֖י⁠ךָ אֵלַ֥⁠י הִתְאַפָּֽקוּ׃","habé֤̇t mi⁠şá̇̌ma֨yim֙ ẇ⁠rĕʼé֔h mi⁠zĕ̇bu֥l qádĕşĕ̌⁠ká֖ wĕ⁠ţipĕʼarĕţė֑⁠ká ʼayé֤̇h qinĕʼֽáţĕ⁠ká֙ ẇ⁠gĕb֣ẇròţe֔⁠ká hàm֥wòn méʻe֛y⁠ká wĕֽ⁠raẖàme֖y⁠ká ʼéla֥⁠y hiţĕʼapáֽ̇qẇ׃"],[63,16,"כִּֽי־אַתָּ֣ה אָבִ֔י⁠נוּ כִּ֤י אַבְרָהָם֙ לֹ֣א יְדָעָ֔⁠נוּ וְ⁠יִשְׂרָאֵ֖ל לֹ֣א יַכִּירָ֑⁠נוּ אַתָּ֤ה יְהוָה֙ אָבִ֔י⁠נוּ גֹּאֲלֵ֥⁠נוּ מֵֽ⁠עוֹלָ֖ם שְׁמֶֽ⁠ךָ׃","kiֽ̇y-ʼaţá֣̇h ʼábi֔y⁠nẇ ki֤̇y ʼabĕráhám֙ lò֣ʼ yĕdáʻá֔⁠nẇ wĕ⁠yişĕ̂ráʼé֖l lò֣ʼ yaki̇yrá֑⁠nẇ ʼaţá֤̇h yĕhwáh֙ ʼábi֔y⁠nẇ gò̇ʼàlé֥⁠nẇ méֽ⁠ʻwòlá֖m şĕ̌meֽ⁠ká׃"],[63,17,"לָ֣⁠מָּה תַתְעֵ֤⁠נוּ יְהוָה֙ מִ⁠דְּרָכֶ֔י⁠ךָ תַּקְשִׁ֥יחַ לִבֵּ֖⁠נוּ מִ⁠יִּרְאָתֶ֑⁠ךָ שׁ֚וּב לְמַ֣עַן עֲבָדֶ֔י⁠ךָ שִׁבְטֵ֖י נַחֲלָתֶֽ⁠ךָ׃","lá֣⁠má̇h ţaţĕʻé֤⁠nẇ yĕhwáh֙ mi⁠dĕ̇ráke֔y⁠ká ţȧqĕşǐ֥yẖa libé֖̇⁠nẇ mi⁠yi̇rĕʼáţe֑⁠ká ş֚̌ẇb lĕma֣ʻan ʻàbáde֔y⁠ká şǐbĕté֖y naẖàláţeֽ⁠ká׃"],[63,18,"לַ⁠מִּצְעָ֕ר יָרְשׁ֖וּ עַם־קָדְשֶׁ֑⁠ךָ צָרֵ֕י⁠נוּ בּוֹסְס֖וּ מִקְדָּשֶֽׁ⁠ךָ׃","la⁠mi̇ẕĕʻá֕r yárĕş֖̌ẇ ʻam-qádĕşě֑⁠ká ẕáré֕y⁠nẇ ḃwòsĕs֖ẇ miqĕdá̇şěֽ⁠ká׃"],[63,19,"הָיִ֗ינוּ מֵֽ⁠עוֹלָם֙ לֹֽא־מָשַׁ֣לְתָּ בָּ֔⁠ם לֹֽא־נִקְרָ֥א שִׁמְ⁠ךָ֖ עֲלֵי⁠הֶ֑ם","háyi֗ynẇ méֽ⁠ʻwòlám֙ lòֽʼ-máşǎ֣lĕţá̇ bá̇֔⁠m lòֽʼ-niqĕrá֥ʼ şǐmĕ⁠ká֖ ʻàléy⁠he֑m"],[64,1,"לוּא־קָרַ֤עְתָּ שָׁמַ֨יִם֙ יָרַ֔דְתָּ מִ⁠פָּנֶ֖י⁠ךָ הָרִ֥ים נָזֹֽלּוּ׃","lẇʼ-qára֤ʻĕţá̇ şá̌ma֨yim֙ yára֔dĕţá̇ mi⁠pá̇ne֖y⁠ká hári֥ym názòֽl̇ẇ׃"],[64,2,"כִּ⁠קְדֹ֧חַ אֵ֣שׁ הֲמָסִ֗ים מַ֚יִם תִּבְעֶה־אֵ֔שׁ לְ⁠הוֹדִ֥יעַ שִׁמְ⁠ךָ֖ לְ⁠צָרֶ֑י⁠ךָ מִ⁠פָּנֶ֖י⁠ךָ גּוֹיִ֥ם יִרְגָּֽזוּ׃","ki̇⁠qĕdò֧ẖa ʼé֣ş̌ hàmási֗ym ma֚yim ţi̇bĕʻeh-ʼé֔ş̌ lĕ⁠hwòdi֥yʻa şǐmĕ⁠ká֖ lĕ⁠ẕáre֑y⁠ká mi⁠pá̇ne֖y⁠ká ġwòyi֥m yirĕgáֽ̇zẇ׃"],[64,3,"בַּ⁠עֲשׂוֹתְ⁠ךָ֥ נוֹרָא֖וֹת לֹ֣א נְקַוֶּ֑ה יָרַ֕דְתָּ מִ⁠פָּנֶ֖י⁠ךָ הָרִ֥ים נָזֹֽלּוּ׃","bȧ⁠ʻàş̂wòţĕ⁠ká֥ nwòráʼ֖wòţ lò֣ʼ nĕqawė֑h yára֕dĕţá̇ mi⁠pá̇ne֖y⁠ká hári֥ym názòֽl̇ẇ׃"],[64,4,"וּ⁠מֵ⁠עוֹלָ֥ם לֹא־שָׁמְע֖וּ לֹ֣א הֶאֱזִ֑ינוּ עַ֣יִן לֹֽא־רָאָ֗תָה אֱלֹהִים֙ זוּלָ֣תְ⁠ךָ֔ יַעֲשֶׂ֖ה לִ⁠מְחַכֵּה־לֽ⁠וֹ׃","ẇ⁠mé⁠ʻwòlá֥m lòʼ-şá̌mĕʻ֖ẇ lò֣ʼ heʼèzi֑ynẇ ʻa֣yin lòֽʼ-ráʼá֗ţáh ʼèlòhiym֙ zẇlá֣ţĕ⁠ká֔ yaʻàşê֖h li⁠mĕẖaké̇h-lֽ⁠wò׃"],[64,5,"פָּגַ֤עְתָּ אֶת־שָׂשׂ֙ וְ⁠עֹ֣שֵׂה צֶ֔דֶק בִּ⁠דְרָכֶ֖י⁠ךָ יִזְכְּר֑וּ⁠ךָ הֵן־אַתָּ֤ה קָצַ֨פְתָּ֙ וַֽ⁠נֶּחֱטָ֔א בָּ⁠הֶ֥ם עוֹלָ֖ם וְ⁠נִוָּשֵֽׁעַ׃","pá̇ga֤ʻĕţá̇ ʼeţ-şá̂ş̂֙ wĕ⁠ʻò֣şé̂h ẕe֔deq bi̇⁠dĕráke֖y⁠ká yizĕkĕ̇r֑ẇ⁠ká hén-ʼaţá֤̇h qáẕa֨pĕţá̇֙ waֽ⁠nėẖètá֔ʼ bá̇⁠he֥m ʻwòlá֖m wĕ⁠niwá̇şéֽ̌ʻa׃"],[64,6,"וַ⁠נְּהִ֤י כַ⁠טָּמֵא֙ כֻּלָּ֔⁠נוּ וּ⁠כְ⁠בֶ֥גֶד עִדִּ֖ים כָּל־צִדְקֹתֵ֑י⁠נוּ וַ⁠נָּ֤בֶל כֶּֽ⁠עָלֶה֙ כֻּלָּ֔⁠נוּ וַ⁠עֲוֺנֵ֖⁠נוּ כָּ⁠ר֥וּחַ יִשָּׂאֻֽ⁠נוּ׃","wa⁠nĕ̇hi֤y ka⁠tá̇méʼ֙ ku̇lá̇֔⁠nẇ ẇ⁠kĕ⁠be֥ged ʻidi֖̇ym ká̇l-ẕidĕqòţé֑y⁠nẇ wa⁠ná֤̇bel kėֽ⁠ʻáleh֙ ku̇lá̇֔⁠nẇ wa⁠ʻàwֺné֖⁠nẇ ká̇⁠r֥ẇẖa yişá̇̂ʼuֽ⁠nẇ׃"],[64,7,"וְ⁠אֵין־קוֹרֵ֣א בְ⁠שִׁמְ⁠ךָ֔ מִתְעוֹרֵ֖ר לְ⁠הַחֲזִ֣יק בָּ֑⁠ךְ כִּֽי־הִסְתַּ֤רְתָּ פָנֶ֨י⁠ךָ֙ מִמֶּ֔⁠נּוּ וַ⁠תְּמוּגֵ֖⁠נוּ בְּ⁠יַד־עֲוֺנֵֽ⁠נוּ׃","wĕ⁠ʼéyn-qwòré֣ʼ bĕ⁠şǐmĕ⁠ká֔ miţĕʻwòré֖r lĕ⁠haẖàzi֣yq bá֑̇⁠kĕ kiֽ̇y-hisĕţȧ֤rĕţá̇ páne֨y⁠ká֙ mimė֔⁠ṅẇ wa⁠ţĕ̇mẇgé֖⁠nẇ bĕ̇⁠yad-ʻàwֺnéֽ⁠nẇ׃"],[64,8,"וְ⁠עַתָּ֥ה יְהוָ֖ה אָבִ֣י⁠נוּ אָ֑תָּה אֲנַ֤חְנוּ הַ⁠חֹ֨מֶר֙ וְ⁠אַתָּ֣ה יֹצְרֵ֔⁠נוּ וּ⁠מַעֲשֵׂ֥ה יָדְ⁠ךָ֖ כֻּלָּֽ⁠נוּ׃","wĕ⁠ʻaţá֥̇h yĕhwá֖h ʼábi֣y⁠nẇ ʼá֑ţá̇h ʼàna֤ẖĕnẇ ha⁠ẖò֨mer֙ wĕ⁠ʼaţá֣̇h yòẕĕré֔⁠nẇ ẇ⁠maʻàşé֥̂h yádĕ⁠ká֖ ku̇láֽ̇⁠nẇ׃"],[64,9,"אַל־תִּקְצֹ֤ף יְהוָה֙ עַד־מְאֹ֔ד וְ⁠אַל־לָ⁠עַ֖ד תִּזְכֹּ֣ר עָוֺ֑ן הֵ֥ן הַבֶּט־נָ֖א עַמְּ⁠ךָ֥ כֻלָּֽ⁠נוּ׃","ʼal-ţi̇qĕẕò֤p yĕhwáh֙ ʻad-mĕʼò֔d wĕ⁠ʼal-lá⁠ʻa֖d ţi̇zĕkò֣̇r ʻáwֺ֑n hé֥n habėt-ná֖ʼ ʻamĕ̇⁠ká֥ kuláֽ̇⁠nẇ׃"],[64,10,"עָרֵ֥י קָדְשְׁ⁠ךָ֖ הָי֣וּ מִדְבָּ֑ר צִיּוֹן֙ מִדְבָּ֣ר הָיָ֔תָה יְרוּשָׁלִַ֖ם שְׁמָמָֽה׃","ʻáré֥y qádĕşĕ̌⁠ká֖ háy֣ẇ midĕbá֑̇r ẕiẏwòn֙ midĕbá֣̇r háyá֔ţáh yĕrẇşá̌lia֖m şĕ̌mámáֽh׃"],[64,11,"בֵּ֧ית קָדְשֵׁ֣⁠נוּ וְ⁠תִפְאַרְתֵּ֗⁠נוּ אֲשֶׁ֤ר הִֽלְל֨וּ⁠ךָ֙ אֲבֹתֵ֔י⁠נוּ הָיָ֖ה לִ⁠שְׂרֵ֣פַת אֵ֑שׁ וְ⁠כָל־מַחֲמַדֵּ֖י⁠נוּ הָיָ֥ה לְ⁠חָרְבָּֽה׃","bé֧̇yţ qádĕşé֣̌⁠nẇ wĕ⁠ţipĕʼarĕţé̇֗⁠nẇ ʼàşě֤r hiֽlĕl֨ẇ⁠ká֙ ʼàbòţé֔y⁠nẇ háyá֖h li⁠şĕ̂ré֣paţ ʼé֑ş̌ wĕ⁠kál-maẖàmadé֖̇y⁠nẇ háyá֥h lĕ⁠ẖárĕbáֽ̇h׃"],[64,12,"הַ⁠עַל־אֵ֥לֶּה תִתְאַפַּ֖ק יְהוָ֑ה תֶּחֱשֶׁ֥ה וּ⁠תְעַנֵּ֖⁠נוּ עַד־מְאֹֽד׃ס","ha⁠ʻal-ʼé֥lėh ţiţĕʼapȧ֖q yĕhwá֑h ţėẖèşě֥h ẇ⁠ţĕʻané֖̇⁠nẇ ʻad-mĕʼòֽd׃s"],[65,1,"נִדְרַ֨שְׁתִּי֙ לְ⁠ל֣וֹא שָׁאָ֔לוּ נִמְצֵ֖אתִי לְ⁠לֹ֣א בִקְשֻׁ֑⁠נִי אָמַ֨רְתִּי֙ הִנֵּ֣⁠נִי הִנֵּ֔⁠נִי אֶל־גּ֖וֹי לֹֽא־קֹרָ֥א בִ⁠שְׁמִֽ⁠י׃","nidĕra֨şĕ̌ţi̇y֙ lĕ⁠l֣wòʼ şá̌ʼá֔lẇ nimĕẕé֖ʼţiy lĕ⁠lò֣ʼ biqĕşǔ֑⁠niy ʼáma֨rĕţi̇y֙ hiné֣̇⁠niy hiné̇֔⁠niy ʼel-ġ֖wòy lòֽʼ-qòrá֥ʼ bi⁠şĕ̌miֽ⁠y׃"],[65,2,"פֵּרַ֧שְׂתִּי יָדַ֛⁠י כָּל־הַ⁠יּ֖וֹם אֶל־עַ֣ם סוֹרֵ֑ר הַ⁠הֹלְכִים֙ הַ⁠דֶּ֣רֶךְ לֹא־ט֔וֹב אַחַ֖ר מַחְשְׁבֹתֵי⁠הֶֽם׃","pé̇ra֧şĕ̂ţi̇y yáda֛⁠y ká̇l-ha⁠ẏ֖wòm ʼel-ʻa֣m swòré֑r ha⁠hòlĕkiym֙ ha⁠dė֣rekĕ lòʼ-t֔wòb ʼaẖa֖r maẖĕşĕ̌bòţéy⁠heֽm׃"],[65,3,"הָ⁠עָ֗ם הַ⁠מַּכְעִיסִ֥ים אוֹתִ֛⁠י עַל־פָּנַ֖⁠י תָּמִ֑יד זֹֽבְחִים֙ בַּ⁠גַּנּ֔וֹת וּֽ⁠מְקַטְּרִ֖ים עַל־הַ⁠לְּבֵנִֽים׃","há⁠ʻá֗m ha⁠mȧkĕʻiysi֥ym ʼwòţi֛⁠y ʻal-pá̇na֖⁠y ţá̇mi֑yd zòֽbĕẖiym֙ bȧ⁠gȧṅ֔wòţ ẇֽ⁠mĕqatĕ̇ri֖ym ʻal-ha⁠lĕ̇béniֽym׃"],[65,4,"הַ⁠יֹּֽשְׁבִים֙ בַּ⁠קְּבָרִ֔ים וּ⁠בַ⁠נְּצוּרִ֖ים יָלִ֑ינוּ הָ⁠אֹֽכְלִים֙ בְּשַׂ֣ר הַ⁠חֲזִ֔יר ו⁠פרק פִּגֻּלִ֖ים כְּלֵי⁠הֶֽם׃","ha⁠yòֽ̇şĕ̌biym֙ bȧ⁠qĕ̇bári֔ym ẇ⁠ba⁠nĕ̇ẕẇri֖ym yáli֑ynẇ há⁠ʼòֽkĕliym֙ bĕ̇şâ֣r ha⁠ẖàzi֔yr w⁠prq pi̇gu̇li֖ym kĕ̇léy⁠heֽm׃"],[65,5,"הָ⁠אֹֽמְרִים֙ קְרַ֣ב אֵלֶ֔י⁠ךָ אַל־תִּגַּשׁ־בִּ֖⁠י כִּ֣י קְדַשְׁתִּ֑י⁠ךָ אֵ֚לֶּה עָשָׁ֣ן בְּ⁠אַפִּ֔⁠י אֵ֥שׁ יֹקֶ֖דֶת כָּל־הַ⁠יּֽוֹם׃","há⁠ʼòֽmĕriym֙ qĕra֣b ʼéle֔y⁠ká ʼal-ţi̇gȧş̌-bi֖̇⁠y ki֣̇y qĕdaşĕ̌ţi֑̇y⁠ká ʼé֚lėh ʻáşá֣̌n bĕ̇⁠ʼapi̇֔⁠y ʼé֥ş̌ yòqe֖deţ ká̇l-ha⁠ẏֽwòm׃"],[65,6,"הִנֵּ֥ה כְתוּבָ֖ה לְ⁠פָנָ֑⁠י לֹ֤א אֶחֱשֶׂה֙ כִּ֣י אִם־שִׁלַּ֔מְתִּי וְ⁠שִׁלַּמְתִּ֖י עַל־חֵיקָֽ⁠ם׃","hiné֥̇h kĕţẇbá֖h lĕ⁠páná֑⁠y lò֤ʼ ʼeẖèşêh֙ ki֣̇y ʼim-şǐlȧ֔mĕţi̇y wĕ⁠şǐlȧmĕţi֖̇y ʻal-ẖéyqáֽ⁠m׃"],[65,7,"עֲ֠וֺנֹתֵי⁠כֶם וַ⁠עֲוֺנֹ֨ת אֲבוֹתֵי⁠כֶ֤ם יַחְדָּו֙ אָמַ֣ר יְהוָ֔ה אֲשֶׁ֤ר קִטְּרוּ֙ עַל־הֶ֣⁠הָרִ֔ים וְ⁠עַל־הַ⁠גְּבָע֖וֹת חֵרְפ֑וּ⁠נִי וּ⁠מַדֹּתִ֧י פְעֻלָּתָ֛⁠ם רִֽאשֹׁנָ֖ה על־חֵיקָֽ⁠ם׃ס","ʻà֠wֺnòţéy⁠kem wa⁠ʻàwֺnò֨ţ ʼàbwòţéy⁠ke֤m yaẖĕdá̇w֙ ʼáma֣r yĕhwá֔h ʼàşě֤r qitĕ̇rẇ֙ ʻal-he֣⁠hári֔ym wĕ⁠ʻal-ha⁠gĕ̇báʻ֖wòţ ẖérĕp֑ẇ⁠niy ẇ⁠madò̇ţi֧y pĕʻulá̇ţá֛⁠m riֽʼşò̌ná֖h ʻl-ẖéyqáֽ⁠m׃s"],[65,8,"כֹּ֣ה ׀ אָמַ֣ר יְהוָ֗ה כַּ⁠אֲשֶׁ֨ר יִמָּצֵ֤א הַ⁠תִּירוֹשׁ֙ בָּֽ⁠אֶשְׁכּ֔וֹל וְ⁠אָמַר֙ אַל־תַּשְׁחִיתֵ֔⁠הוּ כִּ֥י בְרָכָ֖ה בּ֑⁠וֹ כֵּ֤ן אֶֽעֱשֶׂה֙ לְמַ֣עַן עֲבָדַ֔⁠י לְ⁠בִלְתִּ֖י הַֽשְׁחִ֥ית הַ⁠כֹּֽל׃","kò֣̇h ׀ ʼáma֣r yĕhwá֗h kȧ⁠ʼàşě֨r yimá̇ẕé֤ʼ ha⁠ţi̇yrwòş̌֙ báֽ̇⁠ʼeşĕ̌k̇֔wòl wĕ⁠ʼámar֙ ʼal-ţȧşĕ̌ẖiyţé֔⁠hẇ ki֥̇y bĕráká֖h ḃ֑⁠wò ké֤̇n ʼeֽʻèşêh֙ lĕma֣ʻan ʻàbáda֔⁠y lĕ⁠bilĕţi֖̇y hֽaşĕ̌ẖi֥yţ ha⁠kòֽ̇l׃"],[65,9,"וְ⁠הוֹצֵאתִ֤י מִֽ⁠יַּעֲקֹב֙ זֶ֔רַע וּ⁠מִ⁠יהוּדָ֖ה יוֹרֵ֣שׁ הָרָ֑⁠י וִ⁠ירֵשׁ֣וּ⁠הָ בְחִירַ֔⁠י וַ⁠עֲבָדַ֖⁠י יִשְׁכְּנוּ־שָֽׁמָּ⁠ה׃","wĕ⁠hwòẕéʼţi֤y miֽ⁠yȧʻàqòb֙ ze֔raʻ ẇ⁠mi⁠yhẇdá֖h ywòré֣ş̌ hárá֑⁠y wi⁠yréş֣̌ẇ⁠há bĕẖiyra֔⁠y wa⁠ʻàbáda֖⁠y yişĕ̌kĕ̇nẇ-şáֽ̌má̇⁠h׃"],[65,10,"וְ⁠הָיָ֤ה הַ⁠שָּׁרוֹן֙ לִ⁠נְוֵה־צֹ֔אן וְ⁠עֵ֥מֶק עָכ֖וֹר לְ⁠רֵ֣בֶץ בָּקָ֑ר לְ⁠עַמִּ֖⁠י אֲשֶׁ֥ר דְּרָשֽׁוּ⁠נִי׃","wĕ⁠háyá֤h ha⁠şá̇̌rwòn֙ li⁠nĕwéh-ẕò֔ʼn wĕ⁠ʻé֥meq ʻák֖wòr lĕ⁠ré֣beẕ bá̇qá֑r lĕ⁠ʻami֖̇⁠y ʼàşě֥r dĕ̇ráşֽ̌ẇ⁠niy׃"],[65,11,"וְ⁠אַתֶּם֙ עֹזְבֵ֣י יְהוָ֔ה הַ⁠שְּׁכֵחִ֖ים אֶת־הַ֣ר קָדְשִׁ֑⁠י הַֽ⁠עֹרְכִ֤ים לַ⁠גַּד֙ שֻׁלְחָ֔ן וְ⁠הַֽ⁠מְמַלְאִ֖ים לַ⁠מְנִ֥י מִמְסָֽךְ׃","wĕ⁠ʼaţėm֙ ʻòzĕbé֣y yĕhwá֔h ha⁠şĕ̇̌kéẖi֖ym ʼeţ-ha֣r qádĕşǐ֑⁠y hֽa⁠ʻòrĕki֤ym la⁠gȧd֙ şǔlĕẖá֔n wĕ⁠haֽ⁠mĕmalĕʼi֖ym la⁠mĕni֥y mimĕsáֽkĕ׃"],[65,12,"וּ⁠מָנִ֨יתִי אֶתְ⁠כֶ֜ם לַ⁠חֶ֗רֶב וְ⁠כֻלְּ⁠כֶם֙ לַ⁠טֶּ֣בַח תִּכְרָ֔עוּ יַ֤עַן קָרָ֨אתִי֙ וְ⁠לֹ֣א עֲנִיתֶ֔ם דִּבַּ֖רְתִּי וְ⁠לֹ֣א שְׁמַעְתֶּ֑ם וַ⁠תַּעֲשׂ֤וּ הָ⁠רַע֙ בְּ⁠עֵינַ֔⁠י וּ⁠בַ⁠אֲשֶׁ֥ר לֹֽא־חָפַ֖צְתִּי בְּחַרְתֶּֽם׃פ","ẇ⁠máni֨yţiy ʼeţĕ⁠ke֜m la⁠ẖe֗reb wĕ⁠kulĕ̇⁠kem֙ la⁠tė֣baẖ ţi̇kĕrá֔ʻẇ ya֤ʻan qárá֨ʼţiy֙ wĕ⁠lò֣ʼ ʻàniyţe֔m di̇bȧ֖rĕţi̇y wĕ⁠lò֣ʼ şĕ̌maʻĕţė֑m wa⁠ţȧʻàş֤̂ẇ há⁠raʻ֙ bĕ̇⁠ʻéyna֔⁠y ẇ⁠ba⁠ʼàşě֥r lòֽʼ-ẖápa֖ẕĕţi̇y bĕ̇ẖarĕţėֽm׃p"],[65,13,"לָ⁠כֵ֞ן כֹּה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהוִ֗ה הִנֵּ֨ה עֲבָדַ֤⁠י ׀ יֹאכֵ֨לוּ֙ וְ⁠אַתֶּ֣ם תִּרְעָ֔בוּ הִנֵּ֧ה עֲבָדַ֛⁠י יִשְׁתּ֖וּ וְ⁠אַתֶּ֣ם תִּצְמָ֑אוּ הִנֵּ֧ה עֲבָדַ֛⁠י יִשְׂמָ֖חוּ וְ⁠אַתֶּ֥ם תֵּבֹֽשׁוּ׃","lá⁠ké֞n kò̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhwi֗h hiné̇֨h ʻàbáda֤⁠y ׀ yòʼké֨lẇ֙ wĕ⁠ʼaţė֣m ţi̇rĕʻá֔bẇ hiné֧̇h ʻàbáda֛⁠y yişĕ̌ţ֖̇ẇ wĕ⁠ʼaţė֣m ţi̇ẕĕmá֑ʼẇ hiné֧̇h ʻàbáda֛⁠y yişĕ̂má֖ẖẇ wĕ⁠ʼaţė֥m ţé̇bòֽş̌ẇ׃"],[65,14,"הִנֵּ֧ה עֲבָדַ֛⁠י יָרֹ֖נּוּ מִ⁠טּ֣וּב לֵ֑ב וְ⁠אַתֶּ֤ם תִּצְעֲקוּ֙ מִ⁠כְּאֵ֣ב לֵ֔ב וּ⁠מִ⁠שֵּׁ֥בֶר ר֖וּחַ תְּיֵלִֽילוּ׃","hiné֧̇h ʻàbáda֛⁠y yárò֖ṅẇ mi⁠ṫ֣ẇb lé֑b wĕ⁠ʼaţė֤m ţi̇ẕĕʻàqẇ֙ mi⁠kĕ̇ʼé֣b lé֔b ẇ⁠mi⁠şé֥̇̌ber r֖ẇẖa ţĕ̇yéliֽylẇ׃"],[65,15,"וְ⁠הִנַּחְתֶּ֨ם שִׁמְ⁠כֶ֤ם לִ⁠שְׁבוּעָה֙ לִ⁠בְחִירַ֔⁠י וֶ⁠הֱמִיתְ⁠ךָ֖ אֲדֹנָ֣⁠י יְהוִ֑ה וְ⁠לַ⁠עֲבָדָ֥י⁠ו יִקְרָ֖א שֵׁ֥ם אַחֵֽר׃","wĕ⁠hinȧẖĕţė֨m şǐmĕ⁠ke֤m li⁠şĕ̌bẇʻáh֙ li⁠bĕẖiyra֔⁠y we⁠hèmiyţĕ⁠ká֖ ʼàdòná֣⁠y yĕhwi֑h wĕ⁠la⁠ʻàbádá֥y⁠w yiqĕrá֖ʼ şé֥̌m ʼaẖéֽr׃"],[65,16,"אֲשֶׁ֨ר הַ⁠מִּתְבָּרֵ֜ךְ בָּ⁠אָ֗רֶץ יִתְבָּרֵךְ֙ בֵּ⁠אלֹהֵ֣י אָמֵ֔ן וְ⁠הַ⁠נִּשְׁבָּ֣ע בָּ⁠אָ֔רֶץ יִשָּׁבַ֖ע בֵּ⁠אלֹהֵ֣י אָמֵ֑ן כִּ֣י נִשְׁכְּח֗וּ הַ⁠צָּרוֹת֙ הָ⁠רִ֣אשֹׁנ֔וֹת וְ⁠כִ֥י נִסְתְּר֖וּ מֵ⁠עֵינָֽ⁠י׃","ʼàşě֨r ha⁠mi̇ţĕbá̇ré֜kĕ bá̇⁠ʼá֗reẕ yiţĕbá̇rékĕ֙ bé̇⁠ʼlòhé֣y ʼámé֔n wĕ⁠ha⁠ni̇şĕ̌bá֣̇ʻ bá̇⁠ʼá֔reẕ yişá̇̌ba֖ʻ bé̇⁠ʼlòhé֣y ʼámé֑n ki֣̇y nişĕ̌kĕ̇ẖ֗ẇ ha⁠ẕá̇rwòţ֙ há⁠ri֣ʼşò̌n֔wòţ wĕ⁠ki֥y nisĕţĕ̇r֖ẇ mé⁠ʻéynáֽ⁠y׃"],[65,17,"כִּֽי־הִנְ⁠נִ֥י בוֹרֵ֛א שָׁמַ֥יִם חֲדָשִׁ֖ים וָ⁠אָ֣רֶץ חֲדָשָׁ֑ה וְ⁠לֹ֤א תִזָּכַ֨רְנָה֙ הָ⁠רִ֣אשֹׁנ֔וֹת וְ⁠לֹ֥א תַעֲלֶ֖ינָה עַל־לֵֽב׃","kiֽ̇y-hinĕ⁠ni֥y bwòré֛ʼ şá̌ma֥yim ẖàdáşǐ֖ym wá⁠ʼá֣reẕ ẖàdáşá֑̌h wĕ⁠lò֤ʼ ţizá̇ka֨rĕnáh֙ há⁠ri֣ʼşò̌n֔wòţ wĕ⁠lò֥ʼ ţaʻàle֖ynáh ʻal-léֽb׃"],[65,18,"כִּֽי־אִם־שִׂ֤ישׂוּ וְ⁠גִ֨ילוּ֙ עֲדֵי־עַ֔ד אֲשֶׁ֖ר אֲנִ֣י בוֹרֵ֑א כִּי֩ הִנְ⁠נִ֨י בוֹרֵ֧א אֶת־יְרוּשָׁלִַ֛ם גִּילָ֖ה וְ⁠עַמָּ֥⁠הּ מָשֽׂוֹשׂ׃","kiֽ̇y-ʼim-şî֤yş̂ẇ wĕ⁠gi֨ylẇ֙ ʻàdéy-ʻa֔d ʼàşě֖r ʼàni֣y bwòré֑ʼ ki̇y֩ hinĕ⁠ni֨y bwòré֧ʼ ʼeţ-yĕrẇşá̌lia֛m gi̇ylá֖h wĕ⁠ʻamá֥̇⁠ḣ máşֽ̂wòş̂׃"],[65,19,"וְ⁠גַלְתִּ֥י בִ⁠ירוּשָׁלִַ֖ם וְ⁠שַׂשְׂתִּ֣י בְ⁠עַמִּ֑⁠י וְ⁠לֹֽא־יִשָּׁמַ֥ע בָּ⁠הּ֙ ע֔וֹד ק֥וֹל בְּכִ֖י וְ⁠ק֥וֹל זְעָקָֽה׃","wĕ⁠galĕţi֥̇y bi⁠yrẇşá̌lia֖m wĕ⁠şâşĕ̂ţi֣̇y bĕ⁠ʻami֑̇⁠y wĕ⁠lòֽʼ-yişá̇̌ma֥ʻ bá̇⁠ḣ֙ ʻ֔wòd q֥wòl bĕ̇ki֖y wĕ⁠q֥wòl zĕʻáqáֽh׃"],[65,20,"לֹא־יִֽהְיֶ֨ה מִ⁠שָּׁ֜ם ע֗וֹד ע֤וּל יָמִים֙ וְ⁠זָקֵ֔ן אֲשֶׁ֥ר לֹֽא־יְמַלֵּ֖א אֶת־יָמָ֑י⁠ו כִּ֣י הַ⁠נַּ֗עַר בֶּן־מֵאָ֤ה שָׁנָה֙ יָמ֔וּת וְ⁠הַ֣⁠חוֹטֶ֔א בֶּן־מֵאָ֥ה שָׁנָ֖ה יְקֻלָּֽל׃","lòʼ-yiֽhĕye֨h mi⁠şá̇̌֜m ʻ֗wòd ʻ֤ẇl yámiym֙ wĕ⁠záqé֔n ʼàşě֥r lòֽʼ-yĕmalé֖̇ʼ ʼeţ-yámá֑y⁠w ki֣̇y ha⁠nȧ֗ʻar bėn-méʼá֤h şá̌náh֙ yám֔ẇţ wĕ⁠ha֣⁠ẖwòte֔ʼ bėn-méʼá֥h şá̌ná֖h yĕquláֽ̇l׃"],[65,21,"וּ⁠בָנ֥וּ בָתִּ֖ים וְ⁠יָשָׁ֑בוּ וְ⁠נָטְע֣וּ כְרָמִ֔ים וְ⁠אָכְל֖וּ פִּרְיָֽ⁠ם׃","ẇ⁠bán֥ẇ báţi֖̇ym wĕ⁠yáşá֑̌bẇ wĕ⁠nátĕʻ֣ẇ kĕrámi֔ym wĕ⁠ʼákĕl֖ẇ pi̇rĕyáֽ⁠m׃"],[65,22,"לֹ֤א יִבְנוּ֙ וְ⁠אַחֵ֣ר יֵשֵׁ֔ב לֹ֥א יִטְּע֖וּ וְ⁠אַחֵ֣ר יֹאכֵ֑ל כִּֽי־כִ⁠ימֵ֤י הָ⁠עֵץ֙ יְמֵ֣י עַמִּ֔⁠י וּ⁠מַעֲשֵׂ֥ה יְדֵי⁠הֶ֖ם יְבַלּ֥וּ בְחִירָֽ⁠י׃","lò֤ʼ yibĕnẇ֙ wĕ⁠ʼaẖé֣r yéşé̌֔b lò֥ʼ yitĕ̇ʻ֖ẇ wĕ⁠ʼaẖé֣r yòʼké֑l kiֽ̇y-ki⁠ymé֤y há⁠ʻéẕ֙ yĕmé֣y ʻami̇֔⁠y ẇ⁠maʻàşé֥̂h yĕdéy⁠he֖m yĕbal֥̇ẇ bĕẖiyráֽ⁠y׃"],[65,23,"לֹ֤א יִֽיגְעוּ֙ לָ⁠רִ֔יק וְ⁠לֹ֥א יֵלְד֖וּ לַ⁠בֶּהָלָ֑ה כִּ֣י זֶ֜רַע בְּרוּכֵ֤י יְהוָה֙ הֵ֔מָּה וְ⁠צֶאֱצָאֵי⁠הֶ֖ם אִתָּֽ⁠ם׃","lò֤ʼ yiֽygĕʻẇ֙ lá⁠ri֔yq wĕ⁠lò֥ʼ yélĕd֖ẇ la⁠bėhálá֑h ki֣̇y ze֜raʻ bĕ̇rẇké֤y yĕhwáh֙ hé֔má̇h wĕ⁠ẕeʼèẕáʼéy⁠he֖m ʼiţáֽ̇⁠m׃"],[65,24,"וְ⁠הָיָ֥ה טֶֽרֶם־יִקְרָ֖אוּ וַ⁠אֲנִ֣י אֶעֱנֶ֑ה ע֛וֹד הֵ֥ם מְדַבְּרִ֖ים וַ⁠אֲנִ֥י אֶשְׁמָֽע׃","wĕ⁠háyá֥h teֽrem-yiqĕrá֖ʼẇ wa⁠ʼàni֣y ʼeʻène֑h ʻ֛wòd hé֥m mĕdabĕ̇ri֖ym wa⁠ʼàni֥y ʼeşĕ̌máֽʻ׃"],[65,25,"זְאֵ֨ב וְ⁠טָלֶ֜ה יִרְע֣וּ כְ⁠אֶחָ֗ד וְ⁠אַרְיֵה֙ כַּ⁠בָּקָ֣ר יֹֽאכַל־תֶּ֔בֶן וְ⁠נָחָ֖שׁ עָפָ֣ר לַחְמ֑⁠וֹ לֹֽא־יָרֵ֧עוּ וְ⁠לֹֽא־יַשְׁחִ֛יתוּ בְּ⁠כָל־הַ֥ר קָדְשִׁ֖⁠י אָמַ֥ר יְהוָֽה׃ס","zĕʼé֨b wĕ⁠tále֜h yirĕʻ֣ẇ kĕ⁠ʼeẖá֗d wĕ⁠ʼarĕyéh֙ kȧ⁠bá̇qá֣r yòֽʼkal-ţė֔ben wĕ⁠náẖá֖ş̌ ʻápá֣r laẖĕm֑⁠wò lòֽʼ-yáré֧ʻẇ wĕ⁠lòֽʼ-yaşĕ̌ẖi֛yţẇ bĕ̇⁠kál-ha֥r qádĕşǐ֖⁠y ʼáma֥r yĕhwáֽh׃s"],[66,1,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה הַ⁠שָּׁמַ֣יִם כִּסְאִ֔⁠י וְ⁠הָ⁠אָ֖רֶץ הֲדֹ֣ם רַגְלָ֑⁠י אֵי־זֶ֥ה בַ֨יִת֙ אֲשֶׁ֣ר תִּבְנוּ־לִ֔⁠י וְ⁠אֵי־זֶ֥ה מָק֖וֹם מְנוּחָתִֽ⁠י׃","kò֚̇h ʼáma֣r yĕhwá֔h ha⁠şá̇̌ma֣yim ki̇sĕʼi֔⁠y wĕ⁠há⁠ʼá֖reẕ hàdò֣m ragĕlá֑⁠y ʼéy-ze֥h ba֨yiţ֙ ʼàşě֣r ţi̇bĕnẇ-li֔⁠y wĕ⁠ʼéy-ze֥h máq֖wòm mĕnẇẖáţiֽ⁠y׃"],[66,2,"וְ⁠אֶת־כָּל־אֵ֨לֶּה֙ יָדִ֣⁠י עָשָׂ֔תָה וַ⁠יִּהְי֥וּ כָל־אֵ֖לֶּה נְאֻם־יְהוָ֑ה וְ⁠אֶל־זֶ֣ה אַבִּ֔יט אֶל־עָנִי֙ וּ⁠נְכֵה־ר֔וּחַ וְ⁠חָרֵ֖ד עַל־דְּבָרִֽ⁠י׃","wĕ⁠ʼeţ-ká̇l-ʼé֨lėh֙ yádi֣⁠y ʻáşá̂֔ţáh wa⁠yi̇hĕy֥ẇ kál-ʼé֖lėh nĕʼum-yĕhwá֑h wĕ⁠ʼel-ze֣h ʼabi̇֔yt ʼel-ʻániy֙ ẇ⁠nĕkéh-r֔ẇẖa wĕ⁠ẖáré֖d ʻal-dĕ̇báriֽ⁠y׃"],[66,3,"שׁוֹחֵ֨ט הַ⁠שּׁ֜וֹר מַכֵּה־אִ֗ישׁ זוֹבֵ֤חַ הַ⁠שֶּׂה֙ עֹ֣רֵֽף כֶּ֔לֶב מַעֲלֵ֤ה מִנְחָה֙ דַּם־חֲזִ֔יר מַזְכִּ֥יר לְבֹנָ֖ה מְבָ֣רֵֽךְ אָ֑וֶן גַּם־הֵ֗מָּה בָּֽחֲרוּ֙ בְּ⁠דַרְכֵי⁠הֶ֔ם וּ⁠בְ⁠שִׁקּוּצֵי⁠הֶ֖ם נַפְשָׁ֥⁠ם חָפֵֽצָה׃","ş̌wòẖé֨t ha⁠ş̇̌֜wòr maké̇h-ʼi֗yş̌ zwòbé֤ẖa ha⁠şė̂h֙ ʻò֣réֽp kė֔leb maʻàlé֤h minĕẖáh֙ dȧm-ẖàzi֔yr mazĕki֥̇yr lĕbòná֖h mĕbá֣réֽkĕ ʼá֑wen gȧm-hé֗má̇h báֽ̇ẖàrẇ֙ bĕ̇⁠darĕkéy⁠he֔m ẇ⁠bĕ⁠şǐq̇ẇẕéy⁠he֖m napĕşá֥̌⁠m ẖápéֽẕáh׃"],[66,4,"גַּם־אֲנִ֞י אֶבְחַ֣ר בְּ⁠תַעֲלֻלֵי⁠הֶ֗ם וּ⁠מְגֽוּרֹתָ⁠ם֙ אָבִ֣יא לָ⁠הֶ֔ם יַ֤עַן קָרָ֨אתִי֙ וְ⁠אֵ֣ין עוֹנֶ֔ה דִּבַּ֖רְתִּי וְ⁠לֹ֣א שָׁמֵ֑עוּ וַ⁠יַּעֲשׂ֤וּ הָ⁠רַע֙ בְּ⁠עֵינַ֔⁠י וּ⁠בַ⁠אֲשֶׁ֥ר לֹֽא־חָפַ֖צְתִּי בָּחָֽרוּ׃ס","gȧm-ʼàni֞y ʼebĕẖa֣r bĕ̇⁠ţaʻàluléy⁠he֗m ẇ⁠mĕgֽẇròţá⁠m֙ ʼábi֣yʼ lá⁠he֔m ya֤ʻan qárá֨ʼţiy֙ wĕ⁠ʼé֣yn ʻwòne֔h di̇bȧ֖rĕţi̇y wĕ⁠lò֣ʼ şá̌mé֑ʻẇ wa⁠yȧʻàş֤̂ẇ há⁠raʻ֙ bĕ̇⁠ʻéyna֔⁠y ẇ⁠ba⁠ʼàşě֥r lòֽʼ-ẖápa֖ẕĕţi̇y bá̇ẖáֽrẇ׃s"],[66,5,"שִׁמְעוּ֙ דְּבַר־יְהוָ֔ה הַ⁠חֲרֵדִ֖ים אֶל־דְּבָר֑⁠וֹ אָמְרוּ֩ אֲחֵי⁠כֶ֨ם שֹׂנְאֵי⁠כֶ֜ם מְנַדֵּי⁠כֶ֗ם לְמַ֤עַן שְׁמִ⁠י֙ יִכְבַּ֣ד יְהוָ֔ה וְ⁠נִרְאֶ֥ה בְ⁠שִׂמְחַתְ⁠כֶ֖ם וְ⁠הֵ֥ם יֵבֹֽשׁוּ׃","şǐmĕʻẇ֙ dĕ̇bar-yĕhwá֔h ha⁠ẖàrédi֖ym ʼel-dĕ̇bár֑⁠wò ʼámĕrẇ֩ ʼàẖéy⁠ke֨m şò̂nĕʼéy⁠ke֜m mĕnadé̇y⁠ke֗m lĕma֤ʻan şĕ̌mi⁠y֙ yikĕbȧ֣d yĕhwá֔h wĕ⁠nirĕʼe֥h bĕ⁠şîmĕẖaţĕ⁠ke֖m wĕ⁠hé֥m yébòֽş̌ẇ׃"],[66,6,"ק֤וֹל שָׁאוֹן֙ מֵ⁠עִ֔יר ק֖וֹל מֵֽ⁠הֵיכָ֑ל ק֣וֹל יְהוָ֔ה מְשַׁלֵּ֥ם גְּמ֖וּל לְ⁠אֹיְבָֽי⁠ו׃","q֤wòl şá̌ʼwòn֙ mé⁠ʻi֔yr q֖wòl méֽ⁠héyká֑l q֣wòl yĕhwá֔h mĕşǎlé֥̇m gĕ̇m֖ẇl lĕ⁠ʼòyĕbáֽy⁠w׃"],[66,7,"בְּ⁠טֶ֥רֶם תָּחִ֖יל יָלָ֑דָה בְּ⁠טֶ֨רֶם יָב֥וֹא חֵ֛בֶל לָ֖⁠הּ וְ⁠הִמְלִ֥יטָה זָכָֽר׃","bĕ̇⁠te֥rem ţá̇ẖi֖yl yálá֑dáh bĕ̇⁠te֨rem yáb֥wòʼ ẖé֛bel lá֖⁠ḣ wĕ⁠himĕli֥ytáh zákáֽr׃"],[66,8,"מִֽי־שָׁמַ֣ע כָּ⁠זֹ֗את מִ֤י רָאָה֙ כָּ⁠אֵ֔לֶּה הֲ⁠י֤וּחַל אֶ֨רֶץ֙ בְּ⁠י֣וֹם אֶחָ֔ד אִם־יִוָּ֥לֵֽד גּ֖וֹי פַּ֣עַם אֶחָ֑ת כִּֽי־חָ֛לָה גַּם־יָלְדָ֥ה צִיּ֖וֹן אֶת־בָּנֶֽי⁠הָ׃","miֽy-şá̌ma֣ʻ ká̇⁠zò֗ʼţ mi֤y ráʼáh֙ ká̇⁠ʼé֔lėh hà⁠y֤ẇẖal ʼe֨reẕ֙ bĕ̇⁠y֣wòm ʼeẖá֔d ʼim-yiwá֥̇léֽd ġ֖wòy pȧ֣ʻam ʼeẖá֑ţ kiֽ̇y-ẖá֛láh gȧm-yálĕdá֥h ẕiẏ֖wòn ʼeţ-bá̇neֽy⁠há׃"],[66,9,"הַ⁠אֲנִ֥י אַשְׁבִּ֛יר וְ⁠לֹ֥א אוֹלִ֖יד יֹאמַ֣ר יְהוָ֑ה אִם־אֲנִ֧י הַ⁠מּוֹלִ֛יד וְ⁠עָצַ֖רְתִּי אָמַ֥ר אֱלֹהָֽיִ⁠ךְ׃ס","ha⁠ʼàni֥y ʼaşĕ̌bi֛̇yr wĕ⁠lò֥ʼ ʼwòli֖yd yòʼma֣r yĕhwá֑h ʼim-ʼàni֧y ha⁠ṁwòli֛yd wĕ⁠ʻáẕa֖rĕţi̇y ʼáma֥r ʼèlòháֽyi⁠kĕ׃s"],[66,10,"שִׂמְח֧וּ אֶת־יְרוּשָׁלִַ֛ם וְ⁠גִ֥ילוּ בָ֖⁠הּ כָּל־אֹהֲבֶ֑י⁠הָ שִׂ֤ישׂוּ אִתָּ⁠הּ֙ מָשׂ֔וֹשׂ כָּל־הַ⁠מִּֽתְאַבְּלִ֖ים עָלֶֽי⁠הָ׃","şîmĕẖ֧ẇ ʼeţ-yĕrẇşá̌lia֛m wĕ⁠gi֥ylẇ bá֖⁠ḣ ká̇l-ʼòhàbe֑y⁠há şî֤yş̂ẇ ʼiţá̇⁠ḣ֙ máş̂֔wòş̂ ká̇l-ha⁠miֽ̇ţĕʼabĕ̇li֖ym ʻáleֽy⁠há׃"],[66,11,"לְמַ֤עַן תִּֽינְקוּ֙ וּ⁠שְׂבַעְתֶּ֔ם מִ⁠שֹּׁ֖ד תַּנְחֻמֶ֑י⁠הָ לְמַ֧עַן תָּמֹ֛צּוּ וְ⁠הִתְעַנַּגְתֶּ֖ם מִ⁠זִּ֥יז כְּבוֹדָֽ⁠הּ׃ס","lĕma֤ʻan ţiֽ̇ynĕqẇ֙ ẇ⁠şĕ̂baʻĕţė֔m mi⁠şò֖̇̌d ţȧnĕẖume֑y⁠há lĕma֧ʻan ţá̇mò֛ẕ̇ẇ wĕ⁠hiţĕʻanȧgĕţė֖m mi⁠zi֥̇yz kĕ̇bwòdáֽ⁠ḣ׃s"],[66,12,"כִּֽי־כֹ֣ה ׀ אָמַ֣ר יְהוָ֗ה הִנְ⁠נִ֣י נֹטֶֽה־אֵ֠לֶי⁠הָ כְּ⁠נָהָ֨ר שָׁל֜וֹם וּ⁠כְ⁠נַ֧חַל שׁוֹטֵ֛ף כְּב֥וֹד גּוֹיִ֖ם וִֽ⁠ינַקְתֶּ֑ם עַל־צַד֙ תִּנָּשֵׂ֔אוּ וְ⁠עַל־בִּרְכַּ֖יִם תְּשָׁעֳשָֽׁעוּ׃","kiֽ̇y-kò֣h ׀ ʼáma֣r yĕhwá֗h hinĕ⁠ni֣y nòteֽh-ʼé֠ley⁠há kĕ̇⁠náhá֨r şá̌l֜wòm ẇ⁠kĕ⁠na֧ẖal ş̌wòté֛p kĕ̇b֥wòd ġwòyi֖m wiֽ⁠ynaqĕţė֑m ʻal-ẕad֙ ţi̇ná̇şé̂֔ʼẇ wĕ⁠ʻal-bi̇rĕkȧ֖yim ţĕ̇şá̌ʻoşáֽ̌ʻẇ׃"],[66,13,"כְּ⁠אִ֕ישׁ אֲשֶׁ֥ר אִמּ֖⁠וֹ תְּנַחֲמֶ֑⁠נּוּ כֵּ֤ן אָֽנֹכִי֙ אֲנַ֣חֶמְ⁠כֶ֔ם וּ⁠בִ⁠ירֽוּשָׁלִַ֖ם תְּנֻחָֽמוּ׃","kĕ̇⁠ʼi֕yş̌ ʼàşě֥r ʼiṁ֖⁠wò ţĕ̇naẖàme֑⁠ṅẇ ké֤̇n ʼáֽnòkiy֙ ʼàna֣ẖemĕ⁠ke֔m ẇ⁠bi⁠yrֽẇşá̌lia֖m ţĕ̇nuẖáֽmẇ׃"],[66,14,"וּ⁠רְאִיתֶם֙ וְ⁠שָׂ֣שׂ לִבְּ⁠כֶ֔ם וְ⁠עַצְמוֹתֵי⁠כֶ֖ם כַּ⁠דֶּ֣שֶׁא תִפְרַ֑חְנָה וְ⁠נוֹדְעָ֤ה יַד־יְהוָה֙ אֶת־עֲבָדָ֔י⁠ו וְ⁠זָעַ֖ם אֶת־אֹיְבָֽי⁠ו׃","ẇ⁠rĕʼiyţem֙ wĕ⁠şá֣̂ş̂ libĕ̇⁠ke֔m wĕ⁠ʻaẕĕmwòţéy⁠ke֖m kȧ⁠dė֣şěʼ ţipĕra֑ẖĕnáh wĕ⁠nwòdĕʻá֤h yad-yĕhwáh֙ ʼeţ-ʻàbádá֔y⁠w wĕ⁠záʻa֖m ʼeţ-ʼòyĕbáֽy⁠w׃"],[66,15,"כִּֽי־הִנֵּ֤ה יְהוָה֙ בָּ⁠אֵ֣שׁ יָב֔וֹא וְ⁠כַ⁠סּוּפָ֖ה מַרְכְּבֹתָ֑י⁠ו לְ⁠הָשִׁ֤יב בְּ⁠חֵמָה֙ אַפּ֔⁠וֹ וְ⁠גַעֲרָת֖⁠וֹ בְּ⁠לַהֲבֵי־אֵֽשׁ׃","kiֽ̇y-hiné֤̇h yĕhwáh֙ bá̇⁠ʼé֣ş̌ yáb֔wòʼ wĕ⁠ka⁠ṡẇpá֖h marĕkĕ̇bòţá֑y⁠w lĕ⁠háşǐ֤yb bĕ̇⁠ẖémáh֙ ʼaṗ֔⁠wò wĕ⁠gaʻàráţ֖⁠wò bĕ̇⁠lahàbéy-ʼéֽş̌׃"],[66,16,"כִּ֤י בָ⁠אֵשׁ֙ יְהוָ֣ה נִשְׁפָּ֔ט וּ⁠בְ⁠חַרְבּ֖⁠וֹ אֶת־כָּל־בָּשָׂ֑ר וְ⁠רַבּ֖וּ חַֽלְלֵ֥י יְהוָֽה׃","ki֤̇y bá⁠ʼéş̌֙ yĕhwá֣h nişĕ̌pá̇֔t ẇ⁠bĕ⁠ẖarĕḃ֖⁠wò ʼeţ-ká̇l-bá̇şá֑̂r wĕ⁠raḃ֖ẇ ẖaֽlĕlé֥y yĕhwáֽh׃"],[66,17,"הַ⁠מִּתְקַדְּשִׁ֨ים וְ⁠הַ⁠מִּֽטַּהֲרִ֜ים אֶל־הַ⁠גַּנּ֗וֹת אַחַ֤ר אחד בַּ⁠תָּ֔וֶךְ אֹֽכְלֵי֙ בְּשַׂ֣ר הַ⁠חֲזִ֔יר וְ⁠הַ⁠שֶּׁ֖קֶץ וְ⁠הָ⁠עַכְבָּ֑ר יַחְדָּ֥ו יָסֻ֖פוּ נְאֻם־יְהוָֽה׃","ha⁠mi̇ţĕqadĕ̇şǐ֨ym wĕ⁠ha⁠miֽ̇tȧhàri֜ym ʼel-ha⁠gȧṅ֗wòţ ʼaẖa֤r ʼẖd bȧ⁠ţá̇֔wekĕ ʼòֽkĕléy֙ bĕ̇şâ֣r ha⁠ẖàzi֔yr wĕ⁠ha⁠şė֖̌qeẕ wĕ⁠há⁠ʻakĕbá֑̇r yaẖĕdá֥̇w yásu֖pẇ nĕʼum-yĕhwáֽh׃"],[66,18,"וְ⁠אָנֹכִ֗י מַעֲשֵׂי⁠הֶם֙ וּ⁠מַחְשְׁבֹ֣תֵי⁠הֶ֔ם בָּאָ֕ה לְ⁠קַבֵּ֥ץ אֶת־כָּל־הַ⁠גּוֹיִ֖ם וְ⁠הַ⁠לְּשֹׁנ֑וֹת וּ⁠בָ֖אוּ וְ⁠רָא֥וּ אֶת־כְּבוֹדִֽ⁠י׃","wĕ⁠ʼánòki֗y maʻàşé̂y⁠hem֙ ẇ⁠maẖĕşĕ̌bò֣ţéy⁠he֔m bá̇ʼá֕h lĕ⁠qabé֥̇ẕ ʼeţ-ká̇l-ha⁠ġwòyi֖m wĕ⁠ha⁠lĕ̇şò̌n֑wòţ ẇ⁠bá֖ʼẇ wĕ⁠ráʼ֥ẇ ʼeţ-kĕ̇bwòdiֽ⁠y׃"],[66,19,"וְ⁠שַׂמְתִּ֨י בָ⁠הֶ֜ם א֗וֹת וְ⁠שִׁלַּחְתִּ֣י מֵ⁠הֶ֣ם ׀ פְּ֠לֵיטִים אֶֽל־הַ⁠גּוֹיִ֞ם תַּרְשִׁ֨ישׁ פּ֥וּל וְ⁠ל֛וּד מֹ֥שְׁכֵי קֶ֖שֶׁת תֻּבַ֣ל וְ⁠יָוָ֑ן הָ⁠אִיִּ֣ים הָ⁠רְחֹקִ֗ים אֲשֶׁ֨ר לֹא־שָׁמְע֤וּ אֶת־שִׁמְעִ⁠י֙ וְ⁠לֹא־רָא֣וּ אֶת־כְּבוֹדִ֔⁠י וְ⁠הִגִּ֥ידוּ אֶת־כְּבוֹדִ֖⁠י בַּ⁠גּוֹיִֽם׃","wĕ⁠şâmĕţi̇֨y bá⁠he֜m ʼ֗wòţ wĕ⁠şǐlȧẖĕţi֣̇y mé⁠he֣m ׀ pĕ̇֠léytiym ʼeֽl-ha⁠ġwòyi֞m ţȧrĕşǐ֨yş̌ ṗ֥ẇl wĕ⁠l֛ẇd mò֥şĕ̌kéy qe֖şěţ ţu̇ba֣l wĕ⁠yáwá֑n há⁠ʼiyi֣̇ym há⁠rĕẖòqi֗ym ʼàşě֨r lòʼ-şá̌mĕʻ֤ẇ ʼeţ-şǐmĕʻi⁠y֙ wĕ⁠lòʼ-ráʼ֣ẇ ʼeţ-kĕ̇bwòdi֔⁠y wĕ⁠higi֥̇ydẇ ʼeţ-kĕ̇bwòdi֖⁠y bȧ⁠ġwòyiֽm׃"],[66,20,"וְ⁠הֵבִ֣יאוּ אֶת־כָּל־אֲחֵי⁠כֶ֣ם מִ⁠כָּל־הַ⁠גּוֹיִ֣ם ׀ מִנְחָ֣ה ׀ לַֽ⁠יהוָ֡ה בַּ⁠סּוּסִ֡ים וּ֠⁠בָ⁠רֶכֶב וּ⁠בַ⁠צַּבִּ֨ים וּ⁠בַ⁠פְּרָדִ֜ים וּ⁠בַ⁠כִּרְכָּר֗וֹת עַ֣ל הַ֥ר קָדְשִׁ֛⁠י יְרוּשָׁלִַ֖ם אָמַ֣ר יְהוָ֑ה כַּ⁠אֲשֶׁ֣ר יָבִיאוּ֩ בְנֵ֨י יִשְׂרָאֵ֧ל אֶת־הַ⁠מִּנְחָ֛ה בִּ⁠כְלִ֥י טָה֖וֹר בֵּ֥ית יְהוָֽה׃","wĕ⁠hébi֣yʼẇ ʼeţ-ká̇l-ʼàẖéy⁠ke֣m mi⁠ká̇l-ha⁠ġwòyi֣m ׀ minĕẖá֣h ׀ laֽ⁠yhwá֡h bȧ⁠ṡẇsi֡ym ẇ֠⁠bá⁠rekeb ẇ⁠ba⁠ẕȧbi̇֨ym ẇ⁠ba⁠pĕ̇rádi֜ym ẇ⁠ba⁠ki̇rĕká̇r֗wòţ ʻa֣l ha֥r qádĕşǐ֛⁠y yĕrẇşá̌lia֖m ʼáma֣r yĕhwá֑h kȧ⁠ʼàşě֣r yábiyʼẇ֩ bĕné֨y yişĕ̂ráʼé֧l ʼeţ-ha⁠mi̇nĕẖá֛h bi̇⁠kĕli֥y táh֖wòr bé֥̇yţ yĕhwáֽh׃"],[66,21,"וְ⁠גַם־מֵ⁠הֶ֥ם אֶקַּ֛ח לַ⁠כֹּהֲנִ֥ים לַ⁠לְוִיִּ֖ם אָמַ֥ר יְהוָֽה׃","wĕ⁠gam-mé⁠he֥m ʼeqȧ֛ẖ la⁠kò̇hàni֥ym la⁠lĕwiyi֖̇m ʼáma֥r yĕhwáֽh׃"],[66,22,"כִּ֣י כַ⁠אֲשֶׁ֣ר הַ⁠שָּׁמַ֣יִם הַ֠⁠חֳדָשִׁים וְ⁠הָ⁠אָ֨רֶץ הַ⁠חֲדָשָׁ֜ה אֲשֶׁ֨ר אֲנִ֥י עֹשֶׂ֛ה עֹמְדִ֥ים לְ⁠פָנַ֖⁠י נְאֻם־יְהוָ֑ה כֵּ֛ן יַעֲמֹ֥ד זַרְעֲ⁠כֶ֖ם וְ⁠שִׁמְ⁠כֶֽם׃","ki֣̇y ka⁠ʼàşě֣r ha⁠şá̇̌ma֣yim ha֠⁠ẖodáşǐym wĕ⁠há⁠ʼá֨reẕ ha⁠ẖàdáşá̌֜h ʼàşě֨r ʼàni֥y ʻòşê֛h ʻòmĕdi֥ym lĕ⁠pána֖⁠y nĕʼum-yĕhwá֑h ké֛̇n yaʻàmò֥d zarĕʻà⁠ke֖m wĕ⁠şǐmĕ⁠keֽm׃"],[66,23,"וְ⁠הָיָ֗ה מִֽ⁠דֵּי־חֹ֨דֶשׁ֙ בְּ⁠חָדְשׁ֔⁠וֹ וּ⁠מִ⁠דֵּ֥י שַׁבָּ֖ת בְּ⁠שַׁבַּתּ֑⁠וֹ יָב֧וֹא כָל־בָּשָׂ֛ר לְ⁠הִשְׁתַּחֲוֺ֥ת לְ⁠פָנַ֖⁠י אָמַ֥ר יְהוָֽה׃","wĕ⁠háyá֗h miֽ⁠dé̇y-ẖò֨deş̌֙ bĕ̇⁠ẖádĕş̌֔⁠wò ẇ⁠mi⁠dé֥̇y şǎbá֖̇ţ bĕ̇⁠şǎbȧţ֑̇⁠wò yáb֧wòʼ kál-bá̇şá֛̂r lĕ⁠hişĕ̌ţȧẖàwֺ֥ţ lĕ⁠pána֖⁠y ʼáma֥r yĕhwáֽh׃"],[66,24,"וְ⁠יָצְא֣וּ וְ⁠רָא֔וּ בְּ⁠פִגְרֵי֙ הָ⁠אֲנָשִׁ֔ים הַ⁠פֹּשְׁעִ֖ים בִּ֑⁠י כִּ֣י תוֹלַעְתָּ֞⁠ם לֹ֣א תָמ֗וּת וְ⁠אִשָּׁ⁠ם֙ לֹ֣א תִכְבֶּ֔ה וְ⁠הָי֥וּ דֵרָא֖וֹן לְ⁠כָל־בָּשָֽׂר׃","wĕ⁠yáẕĕʼ֣ẇ wĕ⁠ráʼ֔ẇ bĕ̇⁠pigĕréy֙ há⁠ʼànáşǐ֔ym ha⁠pò̇şĕ̌ʻi֖ym bi֑̇⁠y ki֣̇y ţwòlaʻĕţá̇֞⁠m lò֣ʼ ţám֗ẇţ wĕ⁠ʼişá̇̌⁠m֙ lò֣ʼ ţikĕbė֔h wĕ⁠háy֥ẇ déráʼ֖wòn lĕ⁠kál-bá̇şáֽ̂r׃"]]}};